@Override
    public void render(T entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        ACBoatModel model = modelMap.get(entity.getACBoatType());
        poseStack.pushPose();
        poseStack.translate(0.0F, 1.5F, 0.0F);
        poseStack.mulPose(Axis.YP.rotationDegrees(180.0F - entityYaw));
        float f = (float) entity.getHurtTime() - partialTicks;
        float f1 = entity.getDamage() - partialTicks;
        if (f1 < 0.0F) {
            f1 = 0.0F;
        }

        if (f > 0.0F) {
            poseStack.mulPose(Axis.XP.rotationDegrees(Mth.sin(f) * f * f1 / 10.0F * (float) entity.getHurtDir()));
        }

        float f2 = entity.getBubbleAngle(partialTicks);
        if (!Mth.equal(f2, 0.0F)) {
            poseStack.mulPose((new Quaternionf()).setAngleAxis(entity.getBubbleAngle(partialTicks) * ((float) Math.PI / 180F), 1.0F, 0.0F, 1.0F));
        }

        poseStack.scale(-1.0F, -1.0F, 1.0F);
        if (isChest) {
            poseStack.pushPose();
            poseStack.translate(0.0F, -0.25F, 0.5F);
            CHEST_MODEL.renderToBuffer(poseStack, bufferIn.getBuffer(RenderType.entityCutoutNoCull(CHEST_TEXTURE)), packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
            poseStack.popPose();
        }
        model.setupAnim(entity, partialTicks, 0.0F, -0.1F, 0.0F, 0.0F);
        VertexConsumer vertexconsumer = bufferIn.getBuffer(RenderType.entityCutoutNoCull(getTextureLocation(entity)));
        model.renderToBuffer(poseStack, vertexconsumer, packedLightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        if (!entity.isUnderWater()) {
            VertexConsumer vertexconsumer1 = bufferIn.getBuffer(RenderType.waterMask());
            model.getWaterMask().render(poseStack, vertexconsumer1, packedLightIn, OverlayTexture.NO_OVERLAY);
        }
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

public static void renderChain(Vec3 to, PoseStack poseStack, VertexConsumer buffer, int packedLightIn, int overlayCoords) {
        double d = to.horizontalDistance();
        float rotY = (float) (Mth.atan2(to.x, to.z) * (double) (180F / (float) Math.PI));
        float rotX = (float) (-(Mth.atan2(to.y, d) * (double) (180F / (float) Math.PI))) - 90.0F;
        float chainWidth = 3F / 16F;
        float chainOffset = chainWidth * -0.5F;
        float chainLength = (float) to.length();
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(rotY));
        poseStack.mulPose(Axis.XP.rotationDegrees(rotX));
        poseStack.translate(0, -chainLength, 0);
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f matrix4f = posestack$pose.pose();
        Matrix3f matrix3f = posestack$pose.normal();
        //x links
        buffer.vertex(matrix4f, chainOffset, 0, 0).color(255, 255, 255, 255).uv((float) 0, (float) chainLength).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, chainWidth + chainOffset, 0, 0).color(255, 255, 255, 255).uv((float) chainWidth, (float) chainLength).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, chainWidth + chainOffset, chainLength, 0).color(255, 255, 255, 255).uv((float) chainWidth, (float) 0).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, chainOffset, chainLength, 0).color(255, 255, 255, 255).uv((float) 0, (float) 0).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        float pixelSkip = 2.5F / 16F;
        //z links
        buffer.vertex(matrix4f, 0, pixelSkip, chainOffset).color(255, 255, 255, 255).uv((float) chainWidth, (float) chainLength + pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, 0, pixelSkip, chainWidth + chainOffset).color(255, 255, 255, 255).uv((float) chainWidth * 2, (float) chainLength + pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, 0, chainLength + pixelSkip, chainWidth + chainOffset).color(255, 255, 255, 255).uv((float) chainWidth * 2, (float) pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        buffer.vertex(matrix4f, 0, chainLength + pixelSkip, chainOffset).color(255, 255, 255, 255).uv((float) chainWidth, (float) pixelSkip).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        poseStack.popPose();
    }

public void render(BurrowingArrowEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int lighting) {
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot())));
        poseStack.mulPose(Axis.XN.rotationDegrees(Mth.lerp(partialTicks, entity.xRotO, entity.getXRot())));
        poseStack.translate(0.0D, (double) 1.5F, -0.35D);
        poseStack.mulPose(Axis.XP.rotationDegrees(180));
        float f9 = (float) entity.shakeTime - partialTicks;
        if (f9 > 0.0F) {
            float f10 = -Mth.sin(f9 * 3.0F) * f9;
            poseStack.mulPose(Axis.ZP.rotationDegrees(f10));
        }
        VertexConsumer vertexconsumer = bufferSource.getBuffer(RenderType.entityCutoutNoCull(this.getTextureLocation(entity)));
        MODEL.setupAnim(entity, 0.0F, 0.0F, entity.tickCount + partialTicks, 0.0F, 0.0F);
        MODEL.renderToBuffer(poseStack, vertexconsumer, lighting, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, bufferSource, lighting);
    }

public void render(CandyCaneHookEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int lighting) {
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot())));
        poseStack.mulPose(Axis.XN.rotationDegrees(Mth.lerp(partialTicks, entity.xRotO, entity.getXRot())));
        poseStack.translate(0.0D, 1.5F, -0.15D);
        poseStack.mulPose(Axis.XP.rotationDegrees(180));
        float ageInTicks = entity.tickCount + partialTicks;
        RenderType renderType = RenderType.entityCutoutNoCull(this.getTextureLocation(entity));
        VertexConsumer vertexconsumer = bufferSource.getBuffer(renderType);
        MODEL.setupAnim(entity, 0.0F, 0.0F, ageInTicks, 0.0F, 0.0F);
        MODEL.renderToBuffer(poseStack, vertexconsumer, lighting, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        poseStack.popPose();

        //fishng rod stuff
        Player player = entity.getPlayerOwner();
        if (player != null) {
            poseStack.pushPose();
            int i = 0;
            if (entity.getHandLaunchedFrom() == InteractionHand.MAIN_HAND) {
                i = player.getMainArm() == HumanoidArm.RIGHT ? 1 : -1;
            } else if (entity.getHandLaunchedFrom() == InteractionHand.OFF_HAND) {
                i = player.getMainArm() == HumanoidArm.LEFT ? 1 : -1;
            }
            float f = player.getAttackAnim(partialTicks);
            float f1 = Mth.sin(Mth.sqrt(f) * (float) Math.PI);
            float f2 = Mth.lerp(partialTicks, player.yBodyRotO, player.yBodyRot) * ((float) Math.PI / 180F);
            boolean wormRiding = player.getItemInHand(InteractionHand.MAIN_HAND).getItem() instanceof CandyCaneHookItem && CandyCaneHookItem.isActive(player.getItemInHand(InteractionHand.MAIN_HAND)) && player.getItemInHand(InteractionHand.OFF_HAND).getItem() instanceof CandyCaneHookItem && CandyCaneHookItem.isActive(player.getItemInHand(InteractionHand.OFF_HAND)) && player.getVehicle() instanceof GumWormSegmentEntity;
            float rightWiggle = -Math.min(player.xxa, 0F) * (float) Math.sin(player.tickCount + AlexsCaves.PROXY.getPartialTicks());
            float leftWiggle = Math.max(player.xxa, 0F) * (float) Math.sin(player.tickCount + AlexsCaves.PROXY.getPartialTicks());
            float wiggle = i == 1 ? rightWiggle : i == -1 ? leftWiggle : 0;
            double d0 = Mth.sin(f2);
            double d1 = Mth.cos(f2);
            double d2 = (double) i * (wormRiding ? 0.45D : 0.35D);
            double d3 = 0.8D;
            double d4;
            double d5;
            double d6;
            float f3;
            if ((this.entityRenderDispatcher.options == null || this.entityRenderDispatcher.options.getCameraType().isFirstPerson()) && player == Minecraft.getInstance().player) {
                double d7 = 960.0D / (double) this.entityRenderDispatcher.options.fov().get().intValue();
                Vec3 vec3 = this.entityRenderDispatcher.camera.getNearPlane().getPointOnPlane((float) i * 0.7F, -0.5F);
                vec3 = vec3.scale(d7);
                vec3 = vec3.yRot(f1 * 0.5F);
                vec3 = vec3.xRot(-f1 * 0.7F);
                d4 = Mth.lerp(partialTicks, player.xo, player.getX()) + vec3.x;
                d5 = Mth.lerp(partialTicks, player.yo, player.getY()) + vec3.y;
                d6 = Mth.lerp(partialTicks, player.zo, player.getZ()) + vec3.z;
                f3 = player.getEyeHeight();
            } else {
                double yDown = wormRiding ? -0.2D + 0.15D * wiggle : 0.55D;
                d4 = Mth.lerp(partialTicks, player.xo, player.getX()) - d1 * d2 - d0 * 0.45D;
                d5 = player.yo + (double) player.getEyeHeight() + (player.getY() - player.yo) * (double) partialTicks - yDown;
                d6 = Mth.lerp(partialTicks, player.zo, player.getZ()) - d0 * d2 + d1 * 0.45D;
                f3 = player.isCrouching() ? -0.1875F : 0.0F;
            }

            double d9 = Mth.lerp(partialTicks, entity.xo, entity.getX());
            double d10 = Mth.lerp(partialTicks, entity.yo, entity.getY()) + 0.25D;
            double d8 = Mth.lerp(partialTicks, entity.zo, entity.getZ());
            float f4 = (float) (d4 - d9);
            float f5 = (float) (d5 - d10) + f3;
            float f6 = (float) (d6 - d8);
            Vec3 rotationalVec = new Vec3(0F, 0.15F, -0.45F).xRot((float) Math.toRadians(Mth.lerp(partialTicks, entity.xRotO, entity.getXRot()))).yRot((float) Math.toRadians(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot())));
            renderLicoriceString(entity, new Vec3(f4, f5, f6), poseStack, bufferSource, rotationalVec);
            poseStack.popPose();
        }

        super.render(entity, entityYaw, partialTicks, poseStack, bufferSource, lighting);
    }

private static void addLicoriceStringVertexPair(VertexConsumer vertexConsumer, Matrix4f matrix4f, float x, float y, float z, int blockLightFrom, int blockLightTo, int skyLightFrom, int skyLightTo, float height, float yWidth, float xWidth, float zWidth, int vertIndex) {
        float f = (float) vertIndex / 32.0F;
        int i = (int) Mth.lerp(f, (float) blockLightFrom, (float) blockLightTo);
        int j = (int) Mth.lerp(f, (float) skyLightFrom, (float) skyLightTo);
        int k = LightTexture.pack(i, j);
        boolean colorScheme = vertIndex % 2 == 0;
        float f2 = colorScheme ? LICORICE_COLOR_1_R : LICORICE_COLOR_2_R;
        float f3 = colorScheme ? LICORICE_COLOR_1_G : LICORICE_COLOR_2_G;
        float f4 = colorScheme ? LICORICE_COLOR_1_B : LICORICE_COLOR_2_B;
        float f5 = x * f;
        float f6 = y < 0.0F ? y * f * f : y - y * (1.0F - f) * (1.0F - f);
        float f7 = z * f;
        vertexConsumer.vertex(matrix4f, f5 - xWidth, f6 + yWidth, f7 + zWidth).color(f2, f3, f4, 1.0F).uv2(k).endVertex();
        vertexConsumer.vertex(matrix4f, f5 + xWidth, f6 + height - yWidth, f7 - zWidth).color(f2, f3, f4, 1.0F).uv2(k).endVertex();
    }

public static void renderEntireBatch(LevelRenderer levelRenderer, PoseStack poseStack, int renderTick, Camera camera, float partialTick) {
        if (!allDugBlocksOnScreen.isEmpty()) {
            poseStack.pushPose();
            Vec3 cameraPos = camera.getPosition();
            poseStack.translate(-cameraPos.x, -cameraPos.y, -cameraPos.z);
            MultiBufferSource.BufferSource multibuffersource$buffersource = Minecraft.getInstance().renderBuffers().crumblingBufferSource();
            for (Map.Entry<BlockPos, Integer> posAndInt : allDugBlocksOnScreen.entrySet()) {
                int progress = posAndInt.getValue() - 1;
                if (progress >= 0 && progress < 10) {
                    poseStack.pushPose();
                    BlockPos pos = posAndInt.getKey();
                    poseStack.translate((double) pos.getX(), (double) pos.getY(), (double) pos.getZ());
                    PoseStack.Pose posestack$pose1 = poseStack.last();
                    VertexConsumer vertexconsumer1 = new SheetedDecalTextureGenerator(multibuffersource$buffersource.getBuffer(ModelBakery.DESTROY_TYPES.get(progress)), posestack$pose1.pose(), posestack$pose1.normal(), 1.0F);
                    net.minecraftforge.client.model.data.ModelData modelData = Minecraft.getInstance().level.getModelDataManager().getAt(pos);
                    Minecraft.getInstance().getBlockRenderer().renderBreakingTexture(Minecraft.getInstance().level.getBlockState(pos), pos, Minecraft.getInstance().level, poseStack, vertexconsumer1, modelData == null ? net.minecraftforge.client.model.data.ModelData.EMPTY : modelData);
                    poseStack.popPose();
                }
            }
            poseStack.popPose();
        }
        allDugBlocksOnScreen.clear();

    }

public void render(CrushedBlockEntity entity, float f1, float f2, PoseStack stack, MultiBufferSource source, int i) {
        stack.pushPose();
        float crush = entity.getCrushProgress(f2);
        stack.translate(0F, crush * -0.5F, 0F);
        stack.scale(1F, 1F - crush, 1F);
        stack.pushPose();
        for (MovingBlockData data : entity.getData()) {
            BlockState blockstate = data.getState();
            if (blockstate.getRenderShape() != RenderShape.INVISIBLE) {
                stack.pushPose();
                stack.translate(-0.5D, -0.5D, -0.5D);
                stack.translate(data.getOffset().getX(), data.getOffset().getY(), data.getOffset().getZ());
                if (blockstate.getRenderShape() == RenderShape.ENTITYBLOCK_ANIMATED && blockstate.hasProperty(HorizontalDirectionalBlock.FACING)) {
                    float f = blockstate.getValue(HorizontalDirectionalBlock.FACING).toYRot();
                    stack.translate(0.5D, 0.5D, 0.5D);
                    stack.mulPose(Axis.YP.rotationDegrees(-f));
                    stack.translate(-0.5D, -0.5D, -0.5D);
                }
                Minecraft.getInstance().getBlockRenderer().renderSingleBlock(blockstate, stack, source, i, OverlayTexture.NO_OVERLAY);
                stack.popPose();
            }
        }
        stack.popPose();
        stack.popPose();
        super.render(entity, f1, f2, stack, source, i);
    }

public void render(DarkArrowEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int lighting) {
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot())));
        poseStack.mulPose(Axis.XN.rotationDegrees(Mth.lerp(partialTicks, entity.xRotO, entity.getXRot())));
        poseStack.translate(0.0D, (double) 1.5F, -0.15D);
        poseStack.mulPose(Axis.XP.rotationDegrees(180));
        float f9 = (float) entity.shakeTime - partialTicks;
        if (f9 > 0.0F) {
            float f10 = -Mth.sin(f9 * 3.0F) * f9;
            poseStack.mulPose(Axis.ZP.rotationDegrees(f10));
        }
        float ageInTicks = entity.tickCount + partialTicks;
        float invFade = 1.0F - entity.getFadeOut(ageInTicks - entity.tickCount);
        float alpha = Math.min(ageInTicks / 4F, 1F) * invFade;
        RenderType renderType = ForgeRenderTypes.getUnlitTranslucent(this.getTextureLocation(entity));
        VertexConsumer vertexconsumer = bufferSource.getBuffer(renderType);
        MODEL.setupAnim(entity, 0.0F, 0.0F, ageInTicks, 0.0F, 0.0F);
        MODEL.renderToBuffer(poseStack, vertexconsumer, 240, OverlayTexture.NO_OVERLAY, entity.getArrowRed(partialTicks), 0.0F, 0.0F, alpha);
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, bufferSource, lighting);
    }

public void render(DesolateDaggerEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource source, int lightIn) {
        super.render(entity, entityYaw, partialTicks, poseStack, source, lightIn);
        float ageInTicks = partialTicks + entity.tickCount;
        double stab = Math.max(entity.getStab(partialTicks), Math.sin(ageInTicks * 0.1F) * 0.2F);
        poseStack.pushPose();
        poseStack.translate(0.0D, 0.5D, 0.0D);
        poseStack.mulPose(Axis.YN.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot()) + 90.0F));
        poseStack.mulPose(Axis.ZN.rotationDegrees((float) (Mth.lerp(partialTicks, entity.xRotO, entity.getXRot()) + 5F * Math.sin(ageInTicks * 0.2F))));
        poseStack.mulPose(Axis.ZN.rotationDegrees(45));
        poseStack.translate(-0.5D, -0.5D, -0.5D);
        float f = 1.0F;
        float f1 = 0;
        float f2 = 0;
        float startAlpha = ageInTicks < 3 ? 0 : (ageInTicks - 3) / 6F;
        float alpha = (float) Math.min(0.6F + stab, Math.min(1F, startAlpha));
        int redOverlay = OverlayTexture.pack(OverlayTexture.u(0), OverlayTexture.v(true));
        poseStack.translate(stab, stab + Math.cos(ageInTicks * 0.1F) * 0.2F, 0);
        BakedModel bakedmodel = Minecraft.getInstance().getItemRenderer().getModel(entity.daggerRenderStack, entity.level(), null, 0);
        for (net.minecraft.client.renderer.RenderType rt : bakedmodel.getRenderTypes(entity.daggerRenderStack, false)) {
            renderModel(poseStack.last(), source.getBuffer(Sheets.translucentItemSheet()), alpha, null, bakedmodel, f, f1, f2, 240, redOverlay, ModelData.EMPTY, rt);
        }
        poseStack.popPose();
    }

public void render(DinosaurSpiritEntity entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        poseStack.pushPose();
        poseStack.translate(0.0D, 1.5D, 0.0D);
        if(entityIn.getDinosaurType() == DinosaurSpiritEntity.DinosaurType.GROTTOCERATOPS){
            Player player = entityIn.getUsingPlayer();
            if(player != null){
                Vec3 playerPos = player.getPosition(partialTicks);
                Vec3 dinoPos = entityIn.getPosition(partialTicks);
                double d1 = playerPos.z - dinoPos.z;
                double d2 = playerPos.x - dinoPos.x;
                float f = (-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
                poseStack.mulPose(Axis.YP.rotationDegrees(-f));
            }
        }else{
            poseStack.mulPose(Axis.YP.rotationDegrees(180 - entityIn.getViewYRot(partialTicks)));
        }
        poseStack.scale(-1.0F, -1.0F, 1.0F);
        poseStack.mulPose(Axis.XN.rotationDegrees(entityIn.getViewXRot(partialTicks)));
        VertexConsumer ivertexbuilder;
        float ghostAlpha = entityIn.getFadeIn(partialTicks);
        boolean prevBaby;
        switch (entityIn.getDinosaurType()){
            case SUBTERRANODON:
                prevBaby = SUBTERRANODON_MODEL.young;
                SUBTERRANODON_MODEL.young = false;
                ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getRedGhost(SUBTERRANODON_TEXTURE));
                SUBTERRANODON_MODEL.animateSpirit(entityIn, partialTicks);
                SUBTERRANODON_MODEL.renderToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, ghostAlpha);
                SUBTERRANODON_MODEL.young = prevBaby;
                break;
            case GROTTOCERATOPS:
                prevBaby = GROTTOCERATOPS_MODEL.young;
                GROTTOCERATOPS_MODEL.young = false;
                ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getRedGhost(GROTTOCERATOPS_TEXTURE));
                GROTTOCERATOPS_MODEL.animateSpirit(entityIn, partialTicks);
                GROTTOCERATOPS_MODEL.renderSpiritToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, ghostAlpha);
                GROTTOCERATOPS_MODEL.young = prevBaby;
                break;
            case TREMORSAURUS:
                prevBaby = TREMORSAURUS_MODEL.young;
                TREMORSAURUS_MODEL.young = false;
                ivertexbuilder = bufferIn.getBuffer(ACRenderTypes.getRedGhost(TREMORSAURUS_TEXTURE));
                TREMORSAURUS_MODEL.animateSpirit(entityIn, partialTicks);
                TREMORSAURUS_MODEL.renderSpiritToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, ghostAlpha);
                TREMORSAURUS_MODEL.young = prevBaby;
                break;
        }
        poseStack.popPose();
        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

public void render(ExtinctionSpearEntity entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        poseStack.pushPose();
        poseStack.translate(0.0D, (double) 0.25F, 0.0D);
        poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entityIn.yRotO, entityIn.getYRot()) - 180F));
        poseStack.mulPose(Axis.XP.rotationDegrees(Mth.lerp(partialTicks, entityIn.xRotO, entityIn.getXRot()) + 90.0F));
        poseStack.translate(0.0D, (double) 0.25F, 0.0D);
        MODEL.setupAnim(entityIn, 0.0F, 0.0F, entityIn.tickCount + partialTicks, 0.0F, 0.0F);
        VertexConsumer ivertexbuilder = bufferIn.getBuffer(ForgeRenderTypes.getUnlitTranslucent(getTextureLocation(entityIn)));
        MODEL.renderToBuffer(poseStack, ivertexbuilder, 240, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        poseStack.popPose();
        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

public void render(FallingTreeBlockEntity entity, float f1, float f2, PoseStack stack, MultiBufferSource source, int i) {
        stack.pushPose();
        float fallProgress = entity.getFallProgress(f2);
        rotateBasedOnDirection(stack, entity.getFallDirection(), fallProgress * fallProgress * 90F);
        stack.pushPose();
        for (MovingBlockData data : entity.getData()) {
            BlockState blockstate = data.getState();
            if (blockstate.getRenderShape() != RenderShape.INVISIBLE) {
                stack.pushPose();
                stack.translate(-0.5D, -0.5D, -0.5D);
                stack.translate(data.getOffset().getX(), data.getOffset().getY(), data.getOffset().getZ());
                if (blockstate.getRenderShape() == RenderShape.ENTITYBLOCK_ANIMATED && blockstate.hasProperty(HorizontalDirectionalBlock.FACING)) {
                    float f = blockstate.getValue(HorizontalDirectionalBlock.FACING).toYRot();
                    stack.translate(0.5D, 0.5D, 0.5D);
                    stack.mulPose(Axis.YP.rotationDegrees(-f));
                    stack.translate(-0.5D, -0.5D, -0.5D);
                }
                Minecraft.getInstance().getBlockRenderer().renderSingleBlock(blockstate, stack, source, i, OverlayTexture.NO_OVERLAY);
                stack.popPose();
            }
        }
        stack.popPose();
        stack.popPose();
        super.render(entity, f1, f2, stack, source, i);
    }

public void render(FerrouslimeEntity entity, float f1, float partialTicks, PoseStack poseStack, MultiBufferSource source, int light) {
        float bodyYaw = Mth.rotLerp(partialTicks, entity.yBodyRotO, entity.yBodyRot);
        poseStack.pushPose();
        poseStack.translate(0, 0.2F + entity.getBbHeight() * 0.5F, 0);
        float ageInTicks = entity.tickCount + partialTicks;
        float orbitDist = entity.getSlimeSize(partialTicks) * 0.1F;
        for (int i = 1; i <= entity.getHeadCount(); i++) {
            Vec3 vec3 = entity.getHeadOffsetPos(i);
            if (i > entity.prevHeadCount) {
                vec3 = vec3.scale(entity.getMergeProgress(partialTicks));
            }
            poseStack.pushPose();
            poseStack.translate(vec3.x + orbitDist * Math.sin(i + ageInTicks * 0.05F), vec3.y + orbitDist * Math.sin(2 + i + ageInTicks * 0.1F), vec3.z + orbitDist * Math.cos(i + ageInTicks * 0.035F));
            poseStack.mulPose(Axis.YP.rotationDegrees(180 - bodyYaw));
            renderHead(entity, partialTicks, poseStack, source, light);
            poseStack.popPose();
        }
        float gelSize = entity.getSlimeSize(partialTicks) - 0.2F;
        poseStack.pushPose();
        if(sepia || entity.isFakeEntity()){
            renderGel(entity, partialTicks, poseStack, source.getBuffer(ACRenderTypes.getBookWidget(TEXTURE_GEL, sepia)), gelSize, light);
        }else{
            renderGel(entity, partialTicks, poseStack, source.getBuffer(ACRenderTypes.getGel(TEXTURE_GEL)), gelSize, light);
            renderGelSpikes(entity, partialTicks, poseStack, source.getBuffer(ACRenderTypes.getGelTriangles(TEXTURE_GEL)), gelSize, light);
        }
        poseStack.popPose();
        poseStack.popPose();
        super.render(entity, f1, partialTicks, poseStack, source, light);
    }

private void renderHead(FerrouslimeEntity entity, float partialTicks, PoseStack poseStack, MultiBufferSource source, int packedLight) {
        float bodyYaw = Mth.rotLerp(partialTicks, entity.yBodyRotO, entity.yBodyRot);
        float headYaw = Mth.rotLerp(partialTicks, entity.yHeadRotO, entity.yHeadRot) - bodyYaw;
        float headPitch = Mth.rotLerp(partialTicks, entity.xRotO, entity.getXRot());
        poseStack.pushPose();
        poseStack.mulPose(Axis.ZP.rotationDegrees(180));
        FERROUSLIME_MODEL.setupAnim(entity, 0, 0, entity.tickCount + partialTicks, headYaw, headPitch);
        VertexConsumer textureConsumer = source.getBuffer(sepia ? ACRenderTypes.getBookWidget(TEXTURE, true) : RenderType.entityCutoutNoCull(TEXTURE));
        FERROUSLIME_MODEL.renderToBuffer(poseStack, textureConsumer, packedLight, LivingEntityRenderer.getOverlayCoords(entity, 0.0F), 1.0F, 1.0F, 1.0F, 1.0F);
        VertexConsumer eyesConsumer = source.getBuffer(sepia ? ACRenderTypes.getBookWidget(TEXTURE_EYES, true) : RenderType.eyes(TEXTURE_EYES));
        FERROUSLIME_MODEL.renderToBuffer(poseStack, eyesConsumer, packedLight, LivingEntityRenderer.getOverlayCoords(entity, 0.0F), 1.0F, 1.0F, 1.0F, 1.0F);
        poseStack.popPose();
    }

private void renderGelSpikes(FerrouslimeEntity entity, float partialTicks, PoseStack poseStack, VertexConsumer consumer, float size, int packedLight) {
        float length = (size + 1) * entity.getAttackProgress(partialTicks);
        if (length > 0) {
            for (int i = 0; i < 8; i++) {
                poseStack.pushPose();
                poseStack.mulPose(Axis.YP.rotationDegrees(i * 45));
                poseStack.mulPose(Axis.XP.rotationDegrees(20 * (float) Math.sin(i * 2.3F + (entity.tickCount + partialTicks) * 0.4F)));
                poseStack.mulPose(Axis.ZP.rotationDegrees(20 * (float) Math.sin(i * 2.3F + (entity.tickCount + partialTicks) * 0.4F)));
                Matrix4f cubeAt = poseStack.last().pose();
                Matrix3f matrix3f = poseStack.last().normal();
                this.spikeCubeFace(entity, cubeAt, matrix3f, consumer, size * 0.25F, length, size * 0.25F, packedLight);
                poseStack.popPose();
            }
        }
    }

