                if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT) {
                    float animationIntensity = ACMath.cullAnimationTick(licowitch.getAnimationTick(), 4, LicowitchEntity.ANIMATION_EAT, partialTicks, 0);
