private void delegateRender(EntityMultipartDummy entity, double x, double y, double z, float entityYaw, float partialTicks, boolean isMultipass) {
		MultiPartEntityPart parent = entity.getParent();

		if(parent != null) {
			IEntityMultiPart mainEntityMP = ((MultiPartEntityPart) parent).parent;

			if(mainEntityMP instanceof Entity) {
				Entity mainEntity = (Entity) mainEntityMP;

				Render<Entity> mainEntityRenderer = this.renderManager.getEntityRenderObject(mainEntity);

				if(mainEntityRenderer instanceof IMultipartDummyRendererDelegate && (!isMultipass || mainEntityRenderer.isMultipass())) {
					Entity renderViewEntity = Minecraft.getMinecraft().getRenderViewEntity();

					double rx = renderViewEntity.prevPosX + (renderViewEntity.posX - renderViewEntity.prevPosX) * (double)partialTicks;
					double ry = renderViewEntity.prevPosY + (renderViewEntity.posY - renderViewEntity.prevPosY) * (double)partialTicks;
					double rz = renderViewEntity.prevPosZ + (renderViewEntity.posZ - renderViewEntity.prevPosZ) * (double)partialTicks;

					ICamera camera = new Frustum();
					camera.setPosition(rx, ry, rz);

					if(this.renderManager.shouldRender(mainEntity, camera, rx, ry, rz)) {
						((IMultipartDummyRendererDelegate<?>) mainEntityRenderer).setRenderFromMultipart(entity);

						if(isMultipass) {
							this.renderManager.renderMultipass(mainEntity, partialTicks);
						} else {
							this.renderManager.renderEntityStatic(mainEntity, partialTicks, false);
						}
					}
				}
			}
		}
	}

@Override
	public void doRender(EntityPredatorArrowGuide entity, double x, double y, double z, float entityYaw, float partialTicks) {
		super.doRender(entity, x, y, z, entityYaw, partialTicks);

		Entity target = entity.getTarget();
		Entity ridingEntity = entity.getRidingEntity();

		if(target != null) {
			double ix = entity.lastTickPosX + (entity.posX - entity.lastTickPosX) * partialTicks;
			double iy = entity.lastTickPosY + (entity.posY - entity.lastTickPosY) * partialTicks;
			double iz = entity.lastTickPosZ + (entity.posZ - entity.lastTickPosZ) * partialTicks;

			double targetIx = target.lastTickPosX + (target.posX - target.lastTickPosX) * partialTicks;
			double targetIy = target.lastTickPosY + (target.posY - target.lastTickPosY) * partialTicks + target.getEyeHeight();
			double targetIz = target.lastTickPosZ + (target.posZ - target.lastTickPosZ) * partialTicks;

			double diffX = targetIx - ix;
			double diffY = targetIy - iy;
			double diffZ = targetIz - iz;

			LightingUtil.INSTANCE.setLighting(255);

			GlStateManager.disableLighting();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0);
			GlStateManager.disableCull();
			GlStateManager.depthMask(false);

			this.bindTexture(BEAM_TEXTURE);

			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y - (ridingEntity != null ? (entity.posY - ridingEntity.posY) : 0), z);

			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

			ParticleBeam.buildBeam(diffX, diffY, diffZ, new Vec3d(-diffX, -diffY, -diffZ), 0.05F, 0, 2F,
					ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
					(vx, vy, vz, u, v) -> {
						buffer.pos(vx, vy, vz).tex(u, v).color(35, 80, 110, 255).endVertex();
					});

			tessellator.draw();

			GlStateManager.popMatrix();

			GlStateManager.depthMask(true);
			GlStateManager.enableCull();
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1f);
			GlStateManager.disableBlend();
			GlStateManager.enableLighting();

			LightingUtil.INSTANCE.revert();
		}
	}

@Override
	public void doRender(EntityPyrad entity, double x, double y, double z, float entityYaw, float partialTicks) {
		this.glow.setAlpha(entity.getActiveTicks(partialTicks) / 60.0F + (!entity.isActive() ? entity.getHitTicks(partialTicks) / 20.0F * 0.45F : 0.0F));

		GlStateManager.pushMatrix();
		GlStateManager.translate(0, (Math.sin((entity.ticksExisted + partialTicks) / 10.0F) / 4.0F - 0.25D) * entity.getActiveTicks(partialTicks) / 60.0D - 0.9D * (1.0D - entity.getActiveTicks(partialTicks) / 60.0D), 0);
		super.doRender(entity, x, y, z, entityYaw, partialTicks);
		GlStateManager.popMatrix();

		double rx = entity.lastTickPosX + (entity.posX - entity.lastTickPosX) * partialTicks;
		double ry = entity.lastTickPosY + (entity.posY - entity.lastTickPosY) * partialTicks;
		double rz = entity.lastTickPosZ + (entity.posZ - entity.lastTickPosZ) * partialTicks;

		if(!entity.isActive() && entity.getHitTicks(partialTicks) > 8 && ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			float hitTicks = entity.getHitTicks(partialTicks);
			float brightness = 1.0F - (float)(Math.cos((hitTicks - 8) / 12.0F * 2.0F * Math.PI) + 1.0F) / 2.0F;
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(rx, ry + 0.5D, rz,
					1.8f,
					134.0f / 255.0f * 3.0F * brightness,
					214.0f / 255.0f * 3.0F * brightness,
					55.0f / 255.0f * 3.0F * brightness));
		}

		if(entity.getGlowTicks(partialTicks) > 0 && ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			float glow = entity.getGlowTicks(partialTicks) / 10.0F;
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(rx, ry + entity.getEyeHeight(), rz,
					4.75F * glow + 1.0F,
					134.0f / 255.0f * 10.0F * glow,
					214.0f / 255.0f * 10.0F * glow,
					55.0f / 255.0f * 10.0F * glow));
		}
	}

@Override
	public void doRender(EntityRockSnotTendril entity, double x, double y, double z, float yaw, float partialTicks) {
		super.doRender(entity, x, y, z, yaw, partialTicks);
		if(entity.getParentEntity() != null) {
			float smoothedYaw = entity.prevRotationYaw + (entity.rotationYaw - entity.prevRotationYaw) * partialTicks;
			float smoothedPitch = entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks;
			GlStateManager.pushMatrix();
			GlStateManager.translate((float) x, (float) y + 0.125F, (float) z);
			if (entity.getExtending())
				GlStateManager.rotate(smoothedYaw + 180F, 0F, 1F, 0F);
			else
				GlStateManager.rotate(smoothedYaw, 0F, 1F, 0F);
			GlStateManager.rotate(smoothedPitch + 90F, 1F, 0F, 0F);
			bindTexture(TEXTURE);
			GRABBER_MODEL.render(entity, 0, 0, entity.ticksExisted, 0F, 0F, 0.0625F);
			GlStateManager.popMatrix();

			GlStateManager.pushMatrix();
			GlStateManager.enableBlend();
			GlStateManager.disableLighting();
			GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1F, 1F, 1F, 1F);

			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();

			bindTexture(VERTICAL_RING_TEXTURE);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			for (int part = 0; part < 8; part++) {
				buildRingQuads(buffer, x, y, z, x + entity.getParentEntity().posX - entity.posX, y + entity.getParentEntity().posY - entity.posY, z + entity.getParentEntity().posZ - entity.posZ, 45F * part, 0.125D, 0.125D, 0.25D, 0.25D);
			}
			tessellator.draw();

			GlStateManager.depthMask(true);
			GlStateManager.disableBlend();
			GlStateManager.enableLighting();
			GlStateManager.popMatrix();
		}
	}

public static void buildRingQuads(BufferBuilder buffer, double x, double y, double z, double xp, double yp, double zp, double angle, double offsetXInner, double offsetZInner, double offsetXInnerP, double offsetZInnerP) {
		double startAngle = Math.toRadians(angle);
		double endAngle = Math.toRadians(angle + 45D);

		double startAngleP = Math.toRadians(angle + 180);
		double endAngleP = Math.toRadians(angle + 235D);

		double offSetXIn1 = -Math.sin(startAngle) * offsetXInner;
		double offSetZIn1 = Math.cos(startAngle) * offsetZInner;
		double offSetXIn2 = -Math.sin(endAngle) * offsetXInner;
		double offSetZIn2 = Math.cos(endAngle) * offsetZInner;

		double offSetXIn1P = -Math.sin(startAngleP) * offsetXInnerP;
		double offSetZIn1P = Math.cos(startAngleP) * offsetZInnerP;
		double offSetXIn2P = -Math.sin(endAngleP) * offsetXInnerP;
		double offSetZIn2P = Math.cos(endAngleP) * offsetZInnerP;

		buffer.pos(xp - offSetXIn1P, yp + 0.0625F, zp + offSetZIn1P).tex(1, 1).endVertex();
		buffer.pos(x - offSetXIn1, y + 0.125F, z + offSetZIn1).tex(1, 0).endVertex();
		buffer.pos(x - offSetXIn2, y + 0.125F, z + offSetZIn2).tex(0, 0).endVertex();
		buffer.pos(xp - offSetXIn2P, yp + 0.0625F, zp + offSetZIn2P).tex(0, 1).endVertex();

		buffer.pos(xp + offSetXIn1P, yp + 0.0625F, zp + offSetZIn1P).tex(1, 1).endVertex();
		buffer.pos(x + offSetXIn1, y + 0.125F, z + offSetZIn1).tex(1, 0).endVertex();
		buffer.pos(x + offSetXIn2, y + 0.125F, z + offSetZIn2).tex(0, 0).endVertex();
		buffer.pos(xp + offSetXIn2P, yp + 0.0625F, zp + offSetZIn2P).tex(0, 1).endVertex();
	}

public void renderRoots(EntityRootGrabber entity, double x, double y, double z, float yaw, float partialTicks) {
		entity.initRootModels();

		if(entity.modelParts != null) {
			GlStateManager.pushMatrix();

			GlStateManager.disableCull();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

			GlStateManager.translate(x, y + 1, z);

			for(RootPart part : entity.modelParts) {
				GlStateManager.pushMatrix();

				this.bindTexture(part.texture);

				GlStateManager.translate(part.x, part.y, part.z);

				GlStateManager.rotate(part.yaw - 90, 0, 1, 0);
				GlStateManager.rotate(part.pitch, 1, 0, 0);

				GlStateManager.translate(0, entity.getRootYOffset(partialTicks), 0);

				if(!entity.isChains()) {
					float animationTicks = entity.ticksExisted + partialTicks;
					GlStateManager.rotate((float)Math.cos(animationTicks / 4) * 0.5F, 0, 0, 1);
					GlStateManager.rotate((float)Math.sin(animationTicks / 5) * 0.8F, 1, 0, 0);
				}

				part.render();

				int damage = MathHelper.ceil(entity.getDamage() * 10.0F);
				if(damage > 0 && damage <= 10) {
					this.bindTexture(DESTROY_STAGES[damage - 1]);

					this.preRenderDamagedBlocks();

					GlStateManager.matrixMode(GL11.GL_TEXTURE);
					GlStateManager.pushMatrix();
					GlStateManager.loadIdentity();
					GlStateManager.scale(1.0F / part.texWidth, 1.0F / part.texHeight, 0);
					GlStateManager.translate(-part.texU, -part.texV, 0);
					GlStateManager.matrixMode(GL11.GL_MODELVIEW);

					part.render();

					GlStateManager.matrixMode(GL11.GL_TEXTURE);
					GlStateManager.popMatrix();
					GlStateManager.matrixMode(GL11.GL_MODELVIEW);

					this.postRenderDamagedBlocks();
				}

				GlStateManager.popMatrix();
			}

			GlStateManager.enableCull();
			GlStateManager.popMatrix();
		}
	}

@Override
	public void doRender(EntityRopeNode ropeNode, double x, double y, double z, float yaw, float partialTicks) {
		this.bindEntityTexture(ropeNode);

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.pushMatrix();

		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.enableTexture2D();
		GlStateManager.enableLighting();
		GlStateManager.color(1.0F, 1.0F, 1.0F, 0.35F);
		LightingUtil.INSTANCE.setLighting(255);

		AxisAlignedBB boundingBox = ropeNode.getEntityBoundingBox().offset(-ropeNode.posX, -ropeNode.posY, -ropeNode.posZ);

		if(ropeNode.getNextNode() == null) {
			boundingBox = boundingBox.grow(0.025D, 0.025D, 0.025D);
			GlStateManager.color(0.25F, 1.0F, 0.25F, 0.35F);
		}

		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			double dstSq = x*x + y*y + z*z;

			if(dstSq <= 256.0D) {
				ShaderHelper.INSTANCE.require();
	        	double rx = ropeNode.lastTickPosX + (ropeNode.posX - ropeNode.lastTickPosX) * partialTicks;
				double ry = ropeNode.lastTickPosY + (ropeNode.posY - ropeNode.lastTickPosY) * partialTicks;
				double rz = ropeNode.lastTickPosZ + (ropeNode.posZ - ropeNode.lastTickPosZ) * partialTicks;
				float brightness = 1.0F - (float)Math.sqrt(dstSq) / 16.0F;
				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(rx, ry, rz, 1.25F, 1.5F * brightness, 2.0F * brightness, 4.0F * brightness));
			}
		}

		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y, z);
		nodeModel.render(ropeNode, 0, 0, 0, 0, 0, 0.0625F);
		GlStateManager.popMatrix();

		GlStateManager.color(1, 1, 1, 1);

		LightingUtil.INSTANCE.revert();
		GlStateManager.enableTexture2D();
		GlStateManager.enableLighting();

		double camPosX = this.interpolate(ropeNode.lastTickPosX, ropeNode.posX, partialTicks) - x;
		double camPosY = this.interpolate(ropeNode.lastTickPosY, ropeNode.posY, partialTicks) - y;
		double camPosZ = this.interpolate(ropeNode.lastTickPosZ, ropeNode.posZ, partialTicks) - z;

		this.frustum.setPosition(camPosX, camPosY, camPosZ);

		Entity prevNode = ropeNode.getPreviousNode();

		if(prevNode != null) {
			if(!this.renderManager.getEntityRenderObject(prevNode).shouldRender(prevNode, this.frustum, camPosX, camPosY, camPosZ)) {
				//Previous node not rendered, render rope
				GlStateManager.pushMatrix();
				double renderOffsetX = this.interpolate(prevNode.lastTickPosX - ropeNode.lastTickPosX, prevNode.posX - ropeNode.posX, partialTicks);
				double renderOffsetY = this.interpolate(prevNode.lastTickPosY - ropeNode.lastTickPosY, prevNode.posY - ropeNode.posY, partialTicks);
				double renderOffsetZ = this.interpolate(prevNode.lastTickPosZ - ropeNode.lastTickPosZ, prevNode.posZ - ropeNode.posZ, partialTicks);
				GlStateManager.translate(renderOffsetX, renderOffsetY, renderOffsetZ);
				this.renderConnection(prevNode, ropeNode, tessellator, buffer, x, y, z, partialTicks);
				GlStateManager.popMatrix();
			}
		}

		Entity nextNode = ropeNode.getNextNode();

		if(nextNode != null) {
			this.renderConnection(ropeNode, nextNode, tessellator, buffer, x, y, z, partialTicks);
		}

		GlStateManager.popMatrix();
	}

protected void renderConnection(Entity node1, Entity node2, Tessellator tessellator, BufferBuilder buffer, double x, double y, double z, float partialTicks) {
		if(node2 != null) {
			double camPosX = this.interpolate(node1.prevPosX - x, node1.posX - x, partialTicks);
			double camPosY = this.interpolate(node1.prevPosY - y, node1.posY - y, partialTicks);
			double camPosZ = this.interpolate(node1.prevPosZ - z, node1.posZ - z, partialTicks);

			double startX = x;
			double startY = y;
			double startZ = z;
			double endX = this.interpolate(node2.prevPosX - camPosX, node2.posX - camPosX, partialTicks);
			double endY = this.interpolate(node2.prevPosY - camPosY, node2.posY - camPosY, partialTicks);
			if(node2 instanceof EntityRopeNode == false) {
				endY += node2.getEyeHeight() / 2.0D;
			}
			double endZ = this.interpolate(node2.prevPosZ - camPosZ, node2.posZ - camPosZ, partialTicks);

			double diffX = (double)((float)(endX - startX));
			double diffY = (double)((float)(endY - startY));
			double diffZ = (double)((float)(endZ - startZ));

			GlStateManager.disableTexture2D();
			GlStateManager.disableLighting();
			GlStateManager.disableCull();

			buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
			for (int i = 0; i <= 24; ++i) {
				float r;
				float g;
				float b;

				if (i % 2 == 0) {
					r = 29.0f / 255.0f;
					g = 72.0f / 255.0f;
					b = 29.0f / 255.0f;
				} else {
					r = 21.0f / 255.0f;
					g = 52.0f / 255.0f;
					b = 21.0f / 255.0f;
				}

				float percentage = (float)i / 24.0F;
				double yMult = endY < startY ? percentage*Math.sqrt(percentage) : percentage * percentage;

				buffer.pos(x + diffX * (double)percentage + 0.0D, y + diffY * (double)(yMult + percentage) * 0.5D, z + diffZ * (double)percentage).color(r, g, b, 1).endVertex();
				buffer.pos(x + diffX * (double)percentage + 0.025D, y + diffY * (double)(yMult + percentage) * 0.5D + 0.025D, z + diffZ * (double)percentage).color(r, g, b, 1).endVertex();
			}
			tessellator.draw();

			buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
			for (int i = 0; i <= 24; ++i) {
				float r;
				float g;
				float b;

				if (i % 2 == 0) {
					r = 29.0f / 255.0f;
					g = 72.0f / 255.0f;
					b = 29.0f / 255.0f;
				} else {
					r = 21.0f / 255.0f;
					g = 52.0f / 255.0f;
					b = 21.0f / 255.0f;
				}

				float percentage = (float)i / 24.0F;
				double yMult = endY < startY ? percentage*Math.sqrt(percentage) : percentage * percentage;

				buffer.pos(x + diffX * (double)percentage + 0.0D, y + diffY * (double)(yMult + percentage) * 0.5D + 0.025D, z + diffZ * (double)percentage).color(r, g, b, 1).endVertex();
				buffer.pos(x + diffX * (double)percentage + 0.025D, y + diffY * (double)(yMult + percentage) * 0.5D, z + diffZ * (double)percentage + 0.025D).color(r, g, b, 1).endVertex();
			}
			tessellator.draw();

			GlStateManager.enableLighting();
			GlStateManager.enableTexture2D();
			GlStateManager.enableCull();
		}
	}

private void renderTonguePart(EntityShambler entity, MultiPartEntityPart part, double rx, double ry, double rz, float partialTicks) {
		double x = part.lastTickPosX + (part.posX - part.lastTickPosX) * (double)partialTicks - rx;
        double y = part.lastTickPosY + (part.posY - part.lastTickPosY) * (double)partialTicks - ry;
        double z = part.lastTickPosZ + (part.posZ - part.lastTickPosZ) * (double)partialTicks - rz;
        float yaw = entity.prevRotationYaw + (entity.rotationYaw - entity.prevRotationYaw) * partialTicks;
        float pitch = entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks;
		bindTexture(TEXTURE);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y - 0.85D, z);
		GlStateManager.scale(-1F, -1F, 1F);
		GlStateManager.rotate(180F + yaw, 0F, 1F, 0F);
		GlStateManager.rotate(180F + pitch, 1F, 0F, 0F);
		if(part == entity.tongue_end)
			model.renderTongueEnd(0.0625F);
		else
			model.renderTonguePart(0.0625F);
		GlStateManager.popMatrix();
	}

public void renderShockwaveBlock(EntityShockwaveBlock entity, double x, double y, double z, float yaw, float tick) {
		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY + 0.5D, entity.posZ, 
					(entity.ticksExisted + tick) / 12.0F + 1F,
					10.0f / 255.0f * 4.0F, 
					40.0f / 255.0f * 4.0F, 
					160.0f / 255.0f * 4.0F));
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY + 0.5D, entity.posZ, 
					(entity.ticksExisted + tick) / 35.0F + 0.6F,
					-3.4F, 
					-3.4F, 
					-3.4F));
		}

		GL11.glPushMatrix();
		GL11.glTranslatef((float) x - 0.5F, (float) y, (float) z - 0.5F);
		//Lighting is already handled in the block renderer
		GlStateManager.disableLighting();
		bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		@SuppressWarnings("deprecation")
		IBlockState state = entity.block.getStateFromMeta(entity.blockMeta);
		IBakedModel model = Minecraft.getMinecraft().getBlockRendererDispatcher().getModelForState(state);
		if(model != null) {
			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.BLOCK);

			blockRenderer.setLighting((IBlockState blockState, @Nullable EnumFacing facing) -> {
				return state.getPackedLightmapCoords(entity.world, facing != null ? entity.origin.up().offset(facing) : entity.origin.up());
			}).setTint((IBlockState blockState, int tintIndex) -> {
				if(blockState.getBlock() == entity.block)
					return Minecraft.getMinecraft().getBlockColors().colorMultiplier(state, entity.world, entity.origin, tintIndex);
				else
					return Minecraft.getMinecraft().getBlockColors().colorMultiplier(state, null, null, tintIndex);
			});

			blockRenderer.renderModel(entity.world, entity.origin, model, state, MathHelper.getPositionRandom(entity.origin), buffer);

			tessellator.draw();
		}
		GlStateManager.enableLighting();
		GL11.glPopMatrix();
	}

@Override
	public void doRender(EntityItem entity, double x, double y, double z, float entityYaw, float partialTicks) {
		super.doRender(entity, x, y + 0.35F, z, entityYaw, partialTicks);

		EntityShockwaveSwordItem shockWaveSwordItem = (EntityShockwaveSwordItem) entity;

		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			float waveProgress = shockWaveSwordItem.getWaveProgress(partialTicks);
			float waveSize = (float) (Math.pow(waveProgress, 3) / 64000.0F);

			if(waveProgress < 50) {
				if(waveProgress > 40) {
					waveSize = (float) (Math.pow((10 - (waveProgress - 40)) / 10.0F * 40.0F, 3) / 64000.0F);
				}

				ShaderHelper.INSTANCE.require();

				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 
						waveSize * 30.0F,
						5.0f / 255.0f * 13.0F, 
						20.0f / 255.0f * 13.0F, 
						80.0f / 255.0f * 13.0F));
				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 
						waveSize * 15.0F,
						5.0f / 255.0f * 13.0F, 
						20.0f / 255.0f * 13.0F, 
						80.0f / 255.0f * 13.0F));
				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 
						waveSize * 8.0F,
						5.0f / 255.0f * 13.0F, 
						20.0f / 255.0f * 13.0F, 
						80.0f / 255.0f * 13.0F));
			}

			if(waveProgress > 40) {
				ShaderHelper.INSTANCE.require();
				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 
						((1.0F + (float)Math.sin((entity.ticksExisted + partialTicks) / 20.0F)) / 2.0F + 0.25F) * (waveProgress - 40) / 10.0F + 1.0F,
						10.0f / 255.0f * 13.0F, 
						40.0f / 255.0f * 13.0F, 
						160.0f / 255.0f * 13.0F));
				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 
						((1.0F + (float)Math.sin((entity.ticksExisted + partialTicks) / 20.0F)) / 4.0F + 0.25F) * (waveProgress - 40) / 10.0F,
						-10.0F, 
						-10.0F, 
						-10.0F));
			}
		}
	}

