			for (int part = 0; part < 24; part++) {
				RenderDecayPitControl.buildRingQuads(buffer, 0, -0.8f + 1.5f + 0.003F, 0, 15F * part, 2D, 2D, 0D, 0D, false);
			}
			tessellator.draw();

			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.loadIdentity();
