@SubscribeEvent(priority = EventPriority.HIGHEST)
	public static void onPlayerRenderPre(RenderPlayerEvent.Pre event) {
		if(event.getEntityPlayer() instanceof AbstractClientPlayer && event.getRenderer() instanceof RenderPlayerVolarkite == false) {
			AbstractClientPlayer player = (AbstractClientPlayer) event.getEntityPlayer();

			Entity mount = player.getRidingEntity();

			EntityVolarkite kite = null;
			if(mount instanceof EntityVolarkite) {
				kite = (EntityVolarkite) mount;
			} else {
				kite = (EntityVolarkite) player.getPassengers().stream().filter(e -> e instanceof EntityVolarkite).findAny().orElse(null);
			}

			if(kite != null) {
				event.setCanceled(true);

				GlStateManager.pushMatrix();

				//Make sure origin is at feet when rotating
				GlStateManager.translate(event.getX(), event.getY(), event.getZ());

				float kiteYaw = (float)interpolate(kite.prevRotationYaw, kite.rotationYaw, event.getPartialRenderTick());

				GlStateManager.rotate(-kiteYaw, 0, 1, 0);
				GlStateManager.translate(0, 1.0D, 0);
				GlStateManager.rotate((float)interpolate(kite.prevRotationRoll, kite.rotationRoll, event.getPartialRenderTick()), 0, 0, 1);
				GlStateManager.rotate((float)interpolate(kite.prevRotationPitch, kite.rotationPitch, event.getPartialRenderTick()), 1, 0, 0);
				GlStateManager.translate(0, -1.0D, 0);
				GlStateManager.rotate(kiteYaw, 0, 1, 0);

				GlStateManager.rotate((float)interpolate(player.prevRenderYawOffset, player.renderYawOffset, event.getPartialRenderTick()) - kiteYaw, 0, 1, 0);

				//Undo previous offset
				GlStateManager.translate(-event.getX(), -event.getY(), -event.getZ());

				boolean isSmallArms = "slim".equals(player.getSkinType());

				RenderPlayer playerRenderer;

				if(isSmallArms) {
					if(renderPlayerSmallArmsVolarkite == null) {
						renderPlayerSmallArmsVolarkite = new RenderPlayerVolarkite(event.getRenderer().getRenderManager(), true);
					}
					playerRenderer = renderPlayerSmallArmsVolarkite;
				} else {
					if(renderPlayerNormalArmsVolarkite == null) {
						renderPlayerNormalArmsVolarkite = new RenderPlayerVolarkite(event.getRenderer().getRenderManager(), false);
					}
					playerRenderer = renderPlayerNormalArmsVolarkite;
				}

				playerRenderer.doRender(player, event.getX(), event.getY(), event.getZ(), (float)interpolate(player.prevRotationYaw, player.rotationYaw, event.getPartialRenderTick()), event.getPartialRenderTick());

				RenderHelper.enableStandardItemLighting();

				GlStateManager.popMatrix();
			}
		}
	}

@Override
	public void doRender(EntityVolatileSoul entity, double x, double y, double z, float yaw, float partialTicks) {
		float rx = ActiveRenderInfo.getRotationX();
		float rxz = ActiveRenderInfo.getRotationXZ();
		float rz = ActiveRenderInfo.getRotationZ();
		float ryz = ActiveRenderInfo.getRotationYZ();
		float rxy = ActiveRenderInfo.getRotationXY();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		float scale = 0.25F;

		float minU = 0;
		float maxU = 1;
		float minV = 0;
		float maxV = 1;

		this.bindTexture(TEXTURE);

		y += 0.2D;

		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.blendFunc(GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE);

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		buffer.pos((double)(x - rx * scale - ryz * scale), (double)(y - rxz * scale), (double)(z - rz * scale - rxy * scale)).tex((double)maxU, (double)maxV).color(255, 255, 255, 255).endVertex();
		buffer.pos((double)(x - rx * scale + ryz * scale), (double)(y + rxz * scale), (double)(z - rz * scale + rxy * scale)).tex((double)maxU, (double)minV).color(255, 255, 255, 255).endVertex();
		buffer.pos((double)(x + rx * scale + ryz * scale), (double)(y + rxz * scale), (double)(z + rz * scale + rxy * scale)).tex((double)minU, (double)minV).color(255, 255, 255, 255).endVertex();
		buffer.pos((double)(x + rx * scale - ryz * scale), (double)(y - rxz * scale), (double)(z + rz * scale - rxy * scale)).tex((double)minU, (double)maxV).color(255, 255, 255, 255).endVertex();

		tessellator.draw();

		this.bindTexture(TEXTURE_TRAIL);

		GlStateManager.depthMask(false);
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.004F);
		GlStateManager.color(1, 1, 1, 1);

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		double trailOffsetX = (x - (entity.lastTickPosX + (entity.posX - entity.lastTickPosX) * partialTicks));
		double trailOffsetY = (y - (entity.lastTickPosY + (entity.posY - entity.lastTickPosY) * partialTicks));
		double trailOffsetZ = (z - (entity.lastTickPosZ + (entity.posZ - entity.lastTickPosZ) * partialTicks));
		int interpSteps = 10;
		float alpha = 1.0F;
		float alphaDecr = alpha / entity.getTrail().size() / (float)interpSteps;
		scale = 0.08F;
		float scaleDecr = scale / entity.getTrail().size() / (float)interpSteps;
		Vec3d prevTrailPos = null;
		for(Vec3d trailPos : entity.getTrail()) {
			if(prevTrailPos != null) {
				for(int s = 0; s < interpSteps; s++) {
					double tx = prevTrailPos.x + (trailPos.x - prevTrailPos.x) / (float)interpSteps * s + trailOffsetX;
					double ty = prevTrailPos.y + (trailPos.y - prevTrailPos.y) / (float)interpSteps * s + trailOffsetY;
					double tz = prevTrailPos.z + (trailPos.z - prevTrailPos.z) / (float)interpSteps * s + trailOffsetZ;
					buffer.pos((double)(tx - rx * scale - ryz * scale), (double)(ty - rxz * scale), (double)(tz - rz * scale - rxy * scale)).tex((double)maxU, (double)maxV).color(alpha, alpha, alpha, 1).endVertex();
					buffer.pos((double)(tx - rx * scale + ryz * scale), (double)(ty + rxz * scale), (double)(tz - rz * scale + rxy * scale)).tex((double)maxU, (double)minV).color(alpha, alpha, alpha, 1).endVertex();
					buffer.pos((double)(tx + rx * scale + ryz * scale), (double)(ty + rxz * scale), (double)(tz + rz * scale + rxy * scale)).tex((double)minU, (double)minV).color(alpha, alpha, alpha, 1).endVertex();
					buffer.pos((double)(tx + rx * scale - ryz * scale), (double)(ty - rxz * scale), (double)(tz + rz * scale - rxy * scale)).tex((double)minU, (double)maxV).color(alpha, alpha, alpha, 1).endVertex();
					scale -= scaleDecr;
					alpha -= alphaDecr;
				}
			}
			prevTrailPos = trailPos;
		}

		tessellator.draw();

		GlStateManager.depthMask(true);
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
	}

public RenderWallHole(RenderManager renderManager, ModelBase model, ResourceLocation modelTexture) {
		super(renderManager, model, 0);

		this.modelTexture = modelTexture;
		this.model = model;
		this.modelBlockTextured = new ModelWallHole(true);
		this.modelNormal = new ModelWallHole(false);

		this.addLayer(new LayerOverlay<T>(this, WALL_TEXTURE_OVERLAY) {
			@Override
			protected ModelBase[] getModels(T entity) {
				return new ModelBase[] { RenderWallHole.this.modelNormal };
			}
		});

		this.addLayer(new LayerOverlay<T>(this) {
			@Override
			protected ModelBase[] getModels(T entity) {
				return new ModelBase[] { RenderWallHole.this.modelNormal };
			}

			@Override
			protected ResourceLocation getTexture(T entity, int index) {
				int damage = MathHelper.ceil((1.0F - entity.getHealth() / entity.getMaxHealth()) * 10.0F);
				if(damage > 0 && damage <= 10) {
					return DESTROY_STAGES[damage - 1];
				}
				return null;
			}

			@Override
			protected void renderOverlay(T entity, ModelBase model, float limbSwing,
					float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch,
					float scale) {
				this.preRenderDamagedBlocks();
				super.renderOverlay(entity, model, limbSwing, limbSwingAmount, partialTicks, ageInTicks, netHeadYaw, headPitch, scale);
				this.postRenderDamagedBlocks();
			}

			private void preRenderDamagedBlocks() {
				GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.DST_COLOR, GlStateManager.DestFactor.SRC_COLOR, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
				GlStateManager.enableBlend();
				GlStateManager.color(1.0F, 1.0F, 1.0F, 0.5F);
				GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1F);
				GlStateManager.enableAlpha();

				GlStateManager.matrixMode(GL11.GL_TEXTURE);
				GlStateManager.pushMatrix();
				GlStateManager.loadIdentity();
				GlStateManager.scale(4f, 4f, 0);
				GlStateManager.matrixMode(GL11.GL_MODELVIEW);
			}

			private void postRenderDamagedBlocks() {
				GlStateManager.disableAlpha();
				GlStateManager.enableAlpha();
				GlStateManager.depthMask(true);
				GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
				GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

				GlStateManager.matrixMode(GL11.GL_TEXTURE);
				GlStateManager.popMatrix();
				GlStateManager.matrixMode(GL11.GL_MODELVIEW);
			}
		});
	}

@Override
	public void doRender(T entity, double x, double y, double z, float entityYaw, float partialTicks) {
		this.partialTicks = partialTicks;

		Framebuffer fbo = Minecraft.getMinecraft().getFramebuffer();

		try(Stencil stencil = Stencil.reserve(fbo)) {
			if(stencil.valid()) {
				GL11.glEnable(GL11.GL_STENCIL_TEST);

				stencil.clear(false);

				stencil.func(GL11.GL_ALWAYS, true);
				stencil.op(GL11.GL_REPLACE, GL11.GL_KEEP, GL11.GL_REPLACE);

				GlStateManager.depthMask(false);
				GlStateManager.colorMask(false, false, false, false);
				GlStateManager.alphaFunc(GL11.GL_GREATER, 0.5F);

				GlStateManager.disableAlpha();
				GlStateManager.disableBlend();
				GlStateManager.disableTexture2D();

				//Polygon offset required so that there's no z fighting with the window and background wall
				GlStateManager.enablePolygonOffset();
				GlStateManager.doPolygonOffset(-5.0F, -5.0F);

				//Render window through which the hole will be visible
				this.modelBlockTextured.frontPiece1.showModel = false;
				this.modelBlockTextured.window.showModel = true;
				this.modelBlockTextured.setWindowZOffsetPercent(-0.001F);
				this.renderPass = 0;
				super.doRender(entity, x, y, z, entityYaw, partialTicks);
				this.modelBlockTextured.frontPiece1.showModel = true;
				this.modelBlockTextured.window.showModel = false;

				GlStateManager.disablePolygonOffset();

				GlStateManager.enableAlpha();
				GlStateManager.enableBlend();
				GlStateManager.enableTexture2D();

				GlStateManager.depthMask(true);
				GlStateManager.colorMask(true, true, true, true);
				GlStateManager.alphaFunc(GL11.GL_GREATER, 0.0F);

				stencil.func(GL11.GL_EQUAL, true);
				stencil.op(GL11.GL_KEEP);
			}

			//Render to depth only with reversed depth test such that in the next pass it can be rendered normally
			GlStateManager.depthFunc(GL11.GL_GEQUAL);
			GlStateManager.colorMask(false, false, false, false);

			this.renderPass = 1;
			super.doRender(entity, x, y, z, entityYaw, partialTicks);

			GlStateManager.colorMask(true, true, true, true);
			GlStateManager.depthFunc(GL11.GL_LEQUAL);

			GL11.glDisable(GL11.GL_STENCIL_TEST);
		}

		//Render visible pass
		this.renderPass = 2;

		this.modelBlockTextured.window.showModel = true;
		this.modelBlockTextured.setWindowZOffsetPercent(this.getHoleDepthPercent(entity, partialTicks));

		super.doRender(entity, x, y, z, entityYaw, partialTicks);

		this.modelBlockTextured.window.showModel = false;
	}

@Override
	protected void renderModel(T entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch, float scaleFactor) {
		this.mainModel = this.modelBlockTextured;
		this.renderWall = true;

		TextureAtlasSprite wallSprite = this.getWallSprite(entity);

		if(wallSprite != null) {
			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.pushMatrix();
			GlStateManager.translate(wallSprite.getMinU(), wallSprite.getMinV(), 0);
			GlStateManager.scale(wallSprite.getMaxU() - wallSprite.getMinU(), wallSprite.getMaxV() - wallSprite.getMinV(), 1);
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		}

		this.renderEntityModel(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scaleFactor, this.partialTicks);

		if(wallSprite != null) {
			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.popMatrix();
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		}

		this.mainModel = this.model;
		this.renderWall = false;

		if(this.renderPass == 2 && this.getMainModelVisibilityPercent(entity, this.partialTicks) > 0.001F) {
			GlStateManager.pushMatrix();
			GlStateManager.translate(0, -0.55D, -0.3D);
			this.applyDeathAndEasterEggRotations(entity);
			this.renderEntityModel(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scaleFactor, this.partialTicks);
			GlStateManager.popMatrix();
		}
	}

protected void applyDeathAndEasterEggRotations(T entity) {
		float yOffset = 1.1F;

		GlStateManager.translate(0, yOffset, 0);

		if (entity.deathTime > 0) {
			float deathPercent = ((float)entity.deathTime + this.partialTicks - 1.0F) / 20.0F * 1.6F;
			deathPercent = MathHelper.sqrt(deathPercent);

			if (deathPercent > 1.0F) {
				deathPercent = 1.0F;
			}

			GlStateManager.rotate(deathPercent * this.getDeathMaxRotation(entity) * this.getMainModelVisibilityPercent(entity, this.partialTicks), 0.0F, 0.0F, 1.0F);
		} else {
			String s = TextFormatting.getTextWithoutFormattingCodes(entity.getName());

			if (s != null && ("Dinnerbone".equals(s) || "Grumm".equals(s))) {
				GlStateManager.translate(0.0F, entity.height + 0.1F, 0.0F);
				GlStateManager.rotate(180.0F, 0.0F, 0.0F, 1.0F);
			}
		}

		GlStateManager.translate(0, -yOffset, 0);
	}

protected void renderRootModel(EntityWallLivingRoot entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch, float scale, float partialTicks) {
		this.bindEntityTexture(entity);

		GlStateManager.pushMatrix();

		//Undo model transforms because arms are in world space relative to entity pos
		GlStateManager.translate(0.0F, 1.501F, 0.0F);	
		GlStateManager.translate(0, -entity.width / 2, 0);
		GlStateManager.rotate(-(entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks), 1, 0, 0);
		GlStateManager.translate(0, entity.width / 2, 0);
		GlStateManager.scale(-1.0F, -1.0F, 1.0F);
		GlStateManager.rotate(-(180.0F - entity.renderYawOffset), 0.0F, 1.0F, 0.0F);

		GlStateManager.color(1, 1, 1, 1);

		this.renderBodyHull(entity, partialTicks);

		GlStateManager.popMatrix();
	}

protected void renderBodyHull(EntityWallLivingRoot entity, float partialTicks) {
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder bufferBuilder = tessellator.getBuffer();

		bufferBuilder.begin(GL11.GL_QUADS, DefaultVertexFormats.OLDMODEL_POSITION_TEX_NORMAL);

		float uOffset = 0;

		int i = 0;

		float armSize = entity.getArmSize(partialTicks);

		float uvScale = this.getUvScale(entity, partialTicks) / Math.max(0.001f, armSize);

		double pos1X = 0, pos1Y = 0, pos1Z = 0;
		ArmSegment segment1 = null;
		for(ArmSegment segment2 : entity.armSegments) {
			Vec3d pos = segment2.pos;
			Vec3d prevPos = segment2.prevPos;

			double pos2X = lerp(prevPos.x, pos.x, partialTicks);
			double pos2Y = lerp(prevPos.y, pos.y, partialTicks);
			double pos2Z = lerp(prevPos.z, pos.z, partialTicks);

			if(segment1 != null) {
				float maxUW = 0;

				int hullVerts = Math.min(segment1.offsetX.length, segment2.offsetX.length);

				for(int vertIndex = 0; vertIndex < hullVerts; vertIndex++) {
					int nextVertIndex = (vertIndex + 1) % hullVerts;

					float contraction1 = this.calculateHullContraction(entity, i - 1, armSize, partialTicks);
					float contraction2 = this.calculateHullContraction(entity, i, armSize, partialTicks);

					double v11x = pos1X + segment1.offsetX[vertIndex] * contraction1;
					double v11y = pos1Y + segment1.offsetY[vertIndex] * contraction1;
					double v11z = pos1Z + segment1.offsetZ[vertIndex] * contraction1;

					double v12x = pos1X + segment1.offsetX[nextVertIndex] * contraction1;
					double v12y = pos1Y + segment1.offsetY[nextVertIndex] * contraction1;
					double v12z = pos1Z + segment1.offsetZ[nextVertIndex] * contraction1;

					double v21x = pos2X + segment2.offsetX[vertIndex] * contraction2;
					double v21y = pos2Y + segment2.offsetY[vertIndex] * contraction2;
					double v21z = pos2Z + segment2.offsetZ[vertIndex] * contraction2;

					double v22x = pos2X + segment2.offsetX[nextVertIndex] * contraction2;
					double v22y = pos2Y + segment2.offsetY[nextVertIndex] * contraction2;
					double v22z = pos2Z + segment2.offsetZ[nextVertIndex] * contraction2;

					float uw1 = dist(v12x, v12y, v12z, v11x, v11y, v11z) * 0.5F * uvScale;
					float vw1 = dist(v21x, v21y, v21z, v11x, v11y, v11z) * uvScale;

					float uw2 = dist(v22x, v22y, v22z, v21x, v21y, v21z) * 0.5F * uvScale;
					float vw2 = dist(v22x, v22y, v22z, v12x, v12y, v12z) * uvScale;

					float uw = Math.max(uw1, uw2);
					float vw = Math.max(vw1, vw2);

					float d1x = (float) (v21x - v12x);
					float d1y = (float) (v21y - v12y);
					float d1z = (float) (v21z - v12z);

					float d2x = (float) (v22x - v11x);
					float d2y = (float) (v22y - v11y);
					float d2z = (float) (v22z - v11z);

					float nx = d1y * d2z - d1z * d2y;
					float ny = d1z * d2x - d1x * d2z;
					float nz = d1x * d2y - d1y * d2x;

					float len = len(nx, ny, nz);

					nx /= len;
					ny /= len;
					nz /= len;

					float us = uOffset;
					float vs = 0;

					bufferBuilder.pos(v11x, v11y, v11z).tex(us, vs).normal(nx, ny, nz).endVertex();
					bufferBuilder.pos(v21x, v21y, v21z).tex(us, vs + vw).normal(nx, ny, nz).endVertex();
					bufferBuilder.pos(v22x, v22y, v22z).tex(us + uw, vs + vw).normal(nx, ny, nz).endVertex();
					bufferBuilder.pos(v12x, v12y, v12z).tex(us + uw, vs).normal(nx, ny, nz).endVertex();

					maxUW = Math.max(maxUW, uw);
				}

				uOffset += maxUW;
			}

			segment1 = segment2;
			pos1X = pos2X;
			pos1Y = pos2Y;
			pos1Z = pos2Z;

			i++;
		}

		tessellator.draw();
	}

@Override
    public void doRender(EntityWeedwoodRowboat rowboat, double x, double y, double z, float yaw, float delta) {
        double wave = rowboat.getWaveHeight(delta);
        Lantern lantern = rowboat.getLantern();
        Vec3d anchor = Vec3d.ZERO, light = Vec3d.ZERO;
        if (lantern != null) {
            anchor = rowboat.getLocalLanternPosition(delta);
            Matrix m = new Matrix();
            m.translate(
                rowboat.lastTickPosX + (rowboat.posX - rowboat.lastTickPosX) * delta + anchor.x,
                rowboat.lastTickPosY + (rowboat.posY - rowboat.lastTickPosY) * delta + anchor.y + wave,
                rowboat.lastTickPosZ + (rowboat.posZ - rowboat.lastTickPosZ) * delta + anchor.z
            );
            m.rotate(lantern.getAngle(delta), 1, 0, 0);
            m.translate(0, -3.5 / 16, 0);
            light = m.transform(Vec3d.ZERO);
        }
        float scale = 0.6F;
        if (MinecraftForgeClient.getRenderPass() == 0) {
            model.animateOar(rowboat, ShipSide.STARBOARD, delta);
            model.animateOar(rowboat, ShipSide.PORT, delta);
            GlStateManager.pushMatrix();
            GlStateManager.translate(x, y + wave, z);
            GlStateManager.pushMatrix();
            roll(rowboat, yaw, delta);
            bindEntityTexture(rowboat);
            GlStateManager.scale(-1, -1, 1);
            model.render(rowboat, lantern != null, 0.0625F, delta);
            GlStateManager.popMatrix();
            if (lantern != null) {
                GlStateManager.translate(anchor.x, anchor.y, anchor.z);
                GlStateManager.rotate(-yaw, 0, 1, 0);
                GlStateManager.scale(-1, -1, 1);
                lanternModel.render(lantern, 0.0625F, delta);
                if (ShaderHelper.INSTANCE.isWorldShaderActive()) {
                    RenderFirefly.addFireflyLight(light.x, light.y, light.z, scale * 7.0F);
                }
            }
            GlStateManager.popMatrix();
        } else if (lantern != null) {
            GlStateManager.disableLighting();
            RenderFirefly.renderFireflyGlow(light.x - renderManager.renderPosX, light.y - renderManager.renderPosY, light.z - renderManager.renderPosZ, scale);
            GlStateManager.enableLighting();
        }
    }

private void calculateGrip(EntityWeedwoodRowboat rowboat, ShipSide side, float delta) {
        int dir = side == ShipSide.PORT ? 1 : -1;
        matrix.setIdentity();
        float yaw = (rowboat.prevRotationYaw + (rowboat.rotationYaw - rowboat.prevRotationYaw) * delta) * MathUtils.DEG_TO_RAD;
        double pelvis = 0.75;
        matrix.translate(0, pelvis - 1.5, 0);
        matrix.rotate(yaw , 0, 1, 0);
        matrix.rotate(rowboat.getRotation(delta));
        matrix.rotate(-yaw, 0, 1, 0);
        matrix.translate(0, 1.5, 0);
        matrix.scale(-1, -1, 1);
        matrix.translate(-9 / 16D * dir, pelvis + 10 / 16D, -7 / 16D);
        createOarTransformationMatrix(side);
        grips.put(side, matrix.transform(new Vec3d(0, -6 / 16D, 0)));
    }

private void articulateArm(ShipSide side, float yaw) {
        int dir = side == ShipSide.PORT ? 1 : -1;
        createBodyTransformationMatrix();
        // move to shoulder joint
        matrix.translate(-6 / 16F * dir, -10 / 16F, shoulderZ.get(side));
        Vec3d arm = matrix.transform(Vec3d.ZERO);
        Vec3d grip = grips.get(side);
        float targetX = (float) (grip.x - arm.x);
        float targetY = (float) (grip.y - arm.y);
        float targetZ = (float) (grip.z - arm.z);
        float horizontalDistSq = targetX * targetX + targetZ * targetZ;
        float targetPitch = (float) Math.atan2(targetY, MathHelper.sqrt(horizontalDistSq));
        float targetLen = MathHelper.sqrt(horizontalDistSq + targetY * targetY);
        float upperArmLen = 4 / 16F, lowerArmLen = 4.25F / 16;
        float shoulderAngle = (float) Math.acos((upperArmLen * upperArmLen + targetLen * targetLen - lowerArmLen * lowerArmLen) / (2 * upperArmLen * targetLen));
        float flexionAngle = (float) Math.acos((upperArmLen * upperArmLen + lowerArmLen * lowerArmLen - targetLen * targetLen) / (2 * upperArmLen * lowerArmLen));
        ArmArticulation armArt = arms.get(side);
        // If shoulderAngle is NaN then the target is out of reach so the arm should simply point in that direction.
        armArt.shoulderAngleX = (shoulderAngle != shoulderAngle ? -MathUtils.PI / 2 - targetPitch : (shoulderAngle - MathUtils.PI / 2 - targetPitch)) - bodyRotateAngleX;
        armArt.shoulderAngleY = (float) Math.atan2(targetZ, targetX) + MathUtils.PI / 2 - bodyRotateAngleY;
        armArt.flexionAngle = shoulderAngle != shoulderAngle ? 0 : (flexionAngle - MathUtils.PI) * MathUtils.RAD_TO_DEG;
        armArt.shoulderZ = shoulderZ.get(side);
    }

private void createBodyTransformationMatrix() {
        matrix.setIdentity();
        // player yOffset
        matrix.translate(0, -1.62, 0);
        // regular scale
        matrix.scale(-1, -1, 1);
        // player scale
        matrix.scale(15 / 16F, 15 / 16F, 15 / 16F);
        // regular translate
        matrix.translate(0, -24 / 16F - 0.0078125, 0);
        // body rotation point
        matrix.translate(0, 12 / 16F, 0);
        matrix.rotate(bodyRotateAngleY, 0, 1, 0);
        matrix.rotate(bodyRotateAngleX, 1, 0, 0);
    }

private void renderWaterMask() {
        if (maskId == -1) {
            maskId = GLAllocation.generateDisplayLists(1);
            Tessellator tessellator = Tessellator.getInstance();
            BufferBuilder vb = tessellator.getBuffer();
            vb.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION);
            double y = 0.813;
            double midWidth = 0.55;
            double midDepth = 0.65;
            double endWidth = 0.4;
            double endDepth = 0.16;
            double endOffset = 0.81;
            vb.pos(-midWidth, y, midDepth).endVertex();
            vb.pos(midWidth, y, midDepth).endVertex();
            vb.pos(midWidth, y, -midDepth).endVertex();
            vb.pos(-midWidth, y, -midDepth).endVertex();
            vb.pos(-endWidth, y, endDepth - endOffset).endVertex();
            vb.pos(endWidth, y, endDepth - endOffset).endVertex();
            vb.pos(endWidth, y, -endDepth - endOffset).endVertex();
            vb.pos(-endWidth, y, -endDepth - endOffset).endVertex();
            vb.pos(-endWidth, y, endDepth + endOffset).endVertex();
            vb.pos(endWidth, y, endDepth + endOffset).endVertex();
            vb.pos(endWidth, y, -endDepth + endOffset).endVertex();
            vb.pos(-endWidth, y, -endDepth + endOffset).endVertex();
            GlStateManager.glNewList(maskId, GL11.GL_COMPILE_AND_EXECUTE);
            GlStateManager.disableTexture2D();
            GlStateManager.colorMask(false, false, false, false);
            tessellator.draw();
            GlStateManager.colorMask(true, true, true, true);
            GlStateManager.enableTexture2D();
            GlStateManager.glEndList();
        } else {
            GlStateManager.callList(maskId);
        }
    }

@Override
	protected void preRenderCallback(EntityWight entity, float partialTicks) {
		if (ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 10.0f, -1, -1, -1));
		}

		float scale = 0.9F / 40F * (entity.getGrowthFactor(partialTicks));
		GlStateManager.scale(0.9F, scale, 0.9F);

		if(entity.isVolatile()) {
			GlStateManager.scale(0.5D, 0.5D, 0.5D);
			GlStateManager.translate(0, 1.0D, 0);
		}
	}

@Override
	public void doRender(EntityWight entity, double x, double y, double z, float entityYaw, float partialTicks) {
		if(!entity.isVolatile()) {
			GlStateManager.pushMatrix();
			GlStateManager.disableBlend();
			GlStateManager.colorMask(false, false, false, false);
			GlStateManager.color(1, 1, 1, 1);

			super.doRender(entity, x, y, z, entityYaw, partialTicks);

			GlStateManager.colorMask(true, true, true, true);
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1F, 1F, 1F, 1F - entity.getHidingAnimation(partialTicks) * 0.5F);

			super.doRender(entity, x, y, z, entityYaw, partialTicks);

			GlStateManager.popMatrix();
		} else {
			this.mainModel = MODEL_HEAD_ONLY;

			GlStateManager.pushMatrix();
			GlStateManager.disableBlend();
			GlStateManager.colorMask(false, false, false, false);
			GlStateManager.color(1, 1, 1, 1);

			if (entity.getRidingEntity() != null) {
				GlStateManager.translate(x, y, z);
				GlStateManager.enableRescaleNormal();
				GlStateManager.scale(-1.0F, -1.0F, 1.0F);
				GlStateManager.rotate((float) (entity.ticksExisted + partialTicks) / 30.0F * 360.0F, 0, 1, 0);
				GlStateManager.rotate(180, 0, 1, 0);
				GlStateManager.translate(0, -entity.getRidingEntity().getEyeHeight() + 1.65D, 0.8D);
				GlStateManager.scale(0.5D, 0.5D, 0.5D);

				this.bindEntityTexture(entity);

				MODEL_HEAD_ONLY.render(entity, 0.0F, 0.0F, entity.ticksExisted + partialTicks, 0.0F, 0.0F, 0.0625F);

				GlStateManager.colorMask(true, true, true, true);
				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				GlStateManager.color(1F, 1F, 1F, 0.4F);

				MODEL_HEAD_ONLY.render(entity, 0.0F, 0.0F, entity.ticksExisted + partialTicks, 0.0F, 0.0F, 0.0625F);
			} else {
				super.doRender(entity, x, y, z, entityYaw, partialTicks);

				GlStateManager.colorMask(true, true, true, true);
				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				GlStateManager.color(1F, 1F, 1F, 0.4F);

				super.doRender(entity, x, y, z, entityYaw, partialTicks);
			}

			GlStateManager.popMatrix();

			this.mainModel = MODEL;
		}
	}

@Override
	public void doRenderLayer(T entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.depthMask(!entity.isInvisible());

		float scrollTimer = entity.ticksExisted + partialTicks;
		this.renderer.bindTexture(this.overlay);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float yScroll = scrollTimer * 0.002F;
		GlStateManager.translate(0F, -yScroll, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		float colour = 0.5F;
		GlStateManager.color(colour, colour, colour, 1.0F);

		GlStateManager.enablePolygonOffset();
		GlStateManager.doPolygonOffset(0.0F, -5.0F);

		ModelBase mainModel = this.renderer.getMainModel();
		mainModel.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		mainModel.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale, entity);
