@Override
	public void renderParticle(BufferBuilder vertexBuffer, Entity entity, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		Minecraft.getMinecraft().getTextureManager().bindTexture(TEXTURE);

		float umin = 0;
		float umax = 1;
		float vmin = this.textureStart;
		float vmax = this.textureStart + TEXTURE_HEIGHT;
		float scale = this.particleScale;

		float ipx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ipy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float ipz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);
		int brightness = this.getBrightnessForRender(partialTicks);
		int lightmapX = brightness >> 16 & 65535;
		int lightmapY = brightness & 65535;
		Vec3d[] rotation = new Vec3d[] {new Vec3d((double)(-rotationX * scale - rotationXY * scale), (double)(-rotationZ * scale), (double)(-rotationYZ * scale - rotationXZ * scale)), new Vec3d((double)(-rotationX * scale + rotationXY * scale), (double)(rotationZ * scale), (double)(-rotationYZ * scale + rotationXZ * scale)), new Vec3d((double)(rotationX * scale + rotationXY * scale), (double)(rotationZ * scale), (double)(rotationYZ * scale + rotationXZ * scale)), new Vec3d((double)(rotationX * scale - rotationXY * scale), (double)(-rotationZ * scale), (double)(rotationYZ * scale - rotationXZ * scale))};

		if (this.particleAngle != 0.0F) {
			float interpolatedRoll = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
			float cos = MathHelper.cos(interpolatedRoll * 0.5F);
			float lookX = MathHelper.sin(interpolatedRoll * 0.5F) * (float)cameraViewDir.x;
			float lookY = MathHelper.sin(interpolatedRoll * 0.5F) * (float)cameraViewDir.y;
			float lookZ = MathHelper.sin(interpolatedRoll * 0.5F) * (float)cameraViewDir.z;
			Vec3d look = new Vec3d((double)lookX, (double)lookY, (double)lookZ);

			for (int l = 0; l < 4; ++l) {
				rotation[l] = look.scale(2.0D * rotation[l].dotProduct(look)).add(rotation[l].scale((double)(cos * cos) - look.dotProduct(look))).add(look.crossProduct(rotation[l]).scale((double)(2.0F * cos)));
			}
		}

		Vec3d look = new Vec3d(cameraViewDir.x, cameraViewDir.y, cameraViewDir.z).normalize();
		Vec3d diff = new Vec3d(this.posX - interpPosX, this.posY - interpPosY, this.posZ - interpPosZ).normalize();
		float angle = (float) Math.toDegrees(Math.acos(look.dotProduct(diff)));

		float fogEnd = FogHandler.getCurrentFogEnd();
		float fogStart = FogHandler.getCurrentFogStart();
		Entity renderView = Minecraft.getMinecraft().getRenderViewEntity();
		float particleDist = renderView == null ? 0.0F : (float)renderView.getDistance(this.posX, this.posY, this.posZ);
		float fadeStart = Math.max(fogStart + (fogEnd - fogStart) / 3.0F, 12.0F);
		float fadeEnd = 8.0F;

		float alpha = 1.0F;

		if(particleDist < fadeStart) {
			alpha = Math.max(1.0F - (fadeStart - particleDist) / (fadeStart - fadeEnd), 0.0F);
		}

		if(this.particleAge < 40) {
			alpha *= this.particleAge / 40.0F;
		} else if(this.particleAge > this.particleMaxAge - 40) {
			alpha *= (this.particleMaxAge - this.particleAge) / 40.0F;
		}

		alpha = Math.min(alpha * 1.75F, 1.0F);

		if(angle < 30.0F) {
			alpha *= Math.pow((angle / 30.0F), 2);
		}

		GlStateManager.alphaFunc(GL11.GL_GREATER, 0);
		GlStateManager.depthMask(false);
		GlStateManager.enableTexture2D();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);

		vertexBuffer.begin(GL11.GL_QUADS, DefaultVertexFormats.PARTICLE_POSITION_TEX_COLOR_LMAP);
		vertexBuffer.pos((double)ipx + rotation[0].x, (double)ipy + rotation[0].y * 1.8F, (double)ipz + rotation[0].z).tex((double)umax, (double)vmax).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(lightmapX, lightmapY).endVertex();
		vertexBuffer.pos((double)ipx + rotation[1].x, (double)ipy + rotation[1].y * 1.8F, (double)ipz + rotation[1].z).tex((double)umax, (double)vmin).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(lightmapX, lightmapY).endVertex();
		vertexBuffer.pos((double)ipx + rotation[2].x, (double)ipy + rotation[2].y * 1.8F, (double)ipz + rotation[2].z).tex((double)umin, (double)vmin).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(lightmapX, lightmapY).endVertex();
		vertexBuffer.pos((double)ipx + rotation[3].x, (double)ipy + rotation[3].y * 1.8F, (double)ipz + rotation[3].z).tex((double)umin, (double)vmax).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(lightmapX, lightmapY).endVertex();
		Tessellator.getInstance().draw();

		GlStateManager.disableBlend();
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1F);
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		if(this.renderer == null) {
			this.renderer = new SpikeRenderer(this.length, this.width, 1.0F, 1, this.seed).build(DefaultVertexFormats.OLDMODEL_POSITION_TEX_NORMAL, particleTexture);
		}

		int i = this.getBrightnessForRender(partialTicks);
		int j = i % 65536;
		int k = i / 65536;

		RenderHelper.enableStandardItemLighting();
		GlStateManager.enableLighting();

		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, (float)j, (float)k);

		Minecraft.getMinecraft().getTextureManager().bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		float rx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ry = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		GlStateManager.pushMatrix();

		float alpha = 1.0F;

		if((this.particleAge + partialTicks) >= this.particleMaxAge - 10) {
			alpha = 1.0F - ((this.particleAge + partialTicks) - (this.particleMaxAge - 10)) / 10.0F;
		}

		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.CONSTANT_ALPHA, DestFactor.ONE_MINUS_CONSTANT_ALPHA);
		GL14.glBlendColor(1, 1, 1, alpha);
		GlStateManager.color(1.0F, 1.0F, 1.0F, alpha);

		GlStateManager.translate(rx, ry, rz);

		double mx = this.prevMotionX + (this.motionX - this.prevMotionX) * partialTicks;
		double my = this.prevMotionY + (this.motionY - this.prevMotionY) * partialTicks;
		double mz = this.prevMotionZ + (this.motionZ - this.prevMotionZ) * partialTicks;

		GlStateManager.rotate(-(float)Math.toDegrees(Math.atan2(mz, mx)), 0, 1, 0);
		GlStateManager.rotate((float)Math.toDegrees(Math.atan2(Math.sqrt(mx * mx + mz * mz), -my)) + 180, 0, 0, 1);

		GlStateManager.translate(0, -0.5F * this.scale, 0);

		GlStateManager.scale(this.scale, this.scale, this.scale);

		Minecraft.getMinecraft().getTextureManager().bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		this.renderer.render();

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GL14.glBlendColor(1, 1, 1, 1);

		GlStateManager.popMatrix();
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		if(this.alphaSupplier != null) {
			this.particleAlpha = this.alphaSupplier.get();
		}

		int brightness = this.getBrightnessForRender(1);
		this.lightmapX = (brightness >> 16) & 65535;
		this.lightmapY = brightness & 65535;

		float distortion = 0.02f + MathHelper.sin(this.particleAge * 0.01f) * MathHelper.cos(this.particleAge * 0.03f) * MathHelper.cos(this.particleAge * 0.1f) * 0.05f;

		this.prevDistortion1X = this.distortion1X;
		this.prevDistortion1Y = this.distortion1Y;
		this.distortion1X = MathHelper.cos(this.particleAge * 0.1f) * distortion;
		this.distortion1Y = MathHelper.sin(this.particleAge * 0.1f) * distortion;

		this.prevDistortion2X = this.distortion2X;
		this.prevDistortion2Y = this.distortion2Y;
		this.distortion2X = MathHelper.cos(this.particleAge * 0.12f) * distortion;
		this.distortion2Y = MathHelper.sin(this.particleAge * 0.12f) * distortion;


		this.prevDistortion3X = this.distortion3X;
		this.prevDistortion3Y = this.distortion3Y;
		this.distortion3X = MathHelper.cos(this.particleAge * 0.14f) * distortion;
		this.distortion3Y = MathHelper.sin(this.particleAge * 0.14f) * distortion;


		this.prevDistortion4X = this.distortion4X;
		this.prevDistortion4Y = this.distortion4Y;
		this.distortion4X = MathHelper.cos(this.particleAge * 0.16f) * distortion;
		this.distortion4Y = MathHelper.sin(this.particleAge * 0.16f) * distortion;
	}

@Override
	public void renderParticle(BufferBuilder buff, Entity entityIn, float partialTicks, float rx, float rz, float ryz, float rxy, float rxz) {
		float minU = (float)this.particleTextureIndexX / 16.0F;
		float maxU = minU + 0.0624375F;
		float minV = (float)this.particleTextureIndexY / 16.0F;
		float maxV = minV + 0.0624375F;
		float scale = 0.1F * this.particleScale * 2;

		if(this.particleTexture != null) {
			minU = this.particleTexture.getMinU();
			maxU = this.particleTexture.getMaxU();
			minV = this.particleTexture.getMinV();
			maxV = this.particleTexture.getMaxV();
		}

		//remove 1px border to avoid artifacts from smooth filtering
		float borderU = (maxU - minU) / this.particleTexture.getIconWidth();
		float borderV = (maxV - minV) / this.particleTexture.getIconHeight();

		minU += borderU;
		maxU -= borderU;
		minV += borderV;
		maxV -= borderV;

		float rpx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float rpy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rpz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		double lcx = this.cx - interpPosX;
		double lcy = this.cy - interpPosY;
		double lcz = this.cz - interpPosZ;

		float normalX = (float)(rpx - lcx);
		float normalY = (float)(rpy - lcy);
		float normalZ = (float)(rpz - lcz);
		float invLen = (float) MathHelper.fastInvSqrt(normalX * normalX + normalY * normalY + normalZ * normalZ);
		normalX *= invLen;
		normalY *= invLen;
		normalZ *= invLen;

		float pp1x = 0, pp1y = 0, pp1z = 0;
		switch(EnumFacing.getFacingFromVector(normalX, normalY, normalZ)) {
		case UP:
			pp1x = 1;
			break;
		case DOWN:
			pp1x = -1;
			break;
		default:
			pp1y = 1;
			break;
		}

		float pp2x = crossX(pp1x, pp1y, pp1z, normalX, normalY, normalZ);
		float pp2y = crossY(pp1x, pp1y, pp1z, normalX, normalY, normalZ);
		float pp2z = crossZ(pp1x, pp1y, pp1z, normalX, normalY, normalZ);

		pp1x = -crossX(pp2x, pp2y, pp2z, normalX, normalY, normalZ);
		pp1y = -crossY(pp2x, pp2y, pp2z, normalX, normalY, normalZ);
		pp1z = -crossZ(pp2x, pp2y, pp2z, normalX, normalY, normalZ);

		float v1x = (pp1x - pp2x) * scale;
		float v1y = (pp1y - pp2y) * scale;
		float v1z = (pp1z - pp2z) * scale;
		float v2x = (-pp1x - pp2x) * scale;
		float v2y = (-pp1y - pp2y) * scale;
		float v2z = (-pp1z - pp2z) * scale;
		float v3x = (-pp1x + pp2x) * scale;
		float v3y = (-pp1y + pp2y) * scale;
		float v3z = (-pp1z + pp2z) * scale;
		float v4x = (pp1x + pp2x) * scale;
		float v4y = (pp1y + pp2y) * scale;
		float v4z = (pp1z + pp2z) * scale;

		if(this.particleAngle != 0.0F) {
			float angle = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
			float cos = MathHelper.cos(angle * 0.5F);
			float rdx = MathHelper.sin(angle * 0.5F) * normalX;
			float rdy = MathHelper.sin(angle * 0.5F) * normalY;
			float rdz = MathHelper.sin(angle * 0.5F) * normalZ;

			float dotrdrd = cos * cos - dot(rdx, rdy, rdz, rdx, rdy, rdz);

			float dotvrd = 2 * dot(v1x, v1y, v1z, rdx, rdy, rdz);
			float nx = rdx * dotvrd + v1x * dotrdrd + crossX(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			float ny = rdy * dotvrd + v1y * dotrdrd + crossY(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			float nz = rdz * dotvrd + v1z * dotrdrd + crossZ(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			v1x = nx;
			v1y = ny;
			v1z = nz;

			dotvrd = 2 * dot(v2x, v2y, v2z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v2x * dotrdrd + crossX(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			ny = rdy * dotvrd + v2y * dotrdrd + crossY(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			nz = rdz * dotvrd + v2z * dotrdrd + crossZ(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			v2x = nx;
			v2y = ny;
			v2z = nz;

			dotvrd = 2 * dot(v3x, v3y, v3z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v3x * dotrdrd + crossX(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			ny = rdy * dotvrd + v3y * dotrdrd + crossY(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			nz = rdz * dotvrd + v3z * dotrdrd + crossZ(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			v3x = nx;
			v3y = ny;
			v3z = nz;

			dotvrd = 2 * dot(v4x, v4y, v4z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v4x * dotrdrd + crossX(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			ny = rdy * dotvrd + v4y * dotrdrd + crossY(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			nz = rdz * dotvrd + v4z * dotrdrd + crossZ(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			v4x = nx;
			v4y = ny;
			v4z = nz;
		}

		float n1x = -(float)(rpx + v1x - lcx);
		float n1y = -(float)(rpy + v1y - lcy);
		float n1z = -(float)(rpz + v1z - lcz);

		float n2x = -(float)(rpx + v2x - lcx);
		float n2y = -(float)(rpy + v2y - lcy);
		float n2z = -(float)(rpz + v2z - lcz);

		float n3x = -(float)(rpx + v3x - lcx);
		float n3y = -(float)(rpy + v3y - lcy);
		float n3z = -(float)(rpz + v3z - lcz);

		float n4x = -(float)(rpx + v4x - lcx);
		float n4y = -(float)(rpy + v4y - lcy);
		float n4z = -(float)(rpz + v4z - lcz);

		float dx = this.prevDistortion1X + (this.distortion1X - this.prevDistortion1X) * partialTicks;
		float dy = this.prevDistortion1Y + (this.distortion1Y - this.prevDistortion1Y) * partialTicks;
		v1x += (v1x * dx + v2x * dy);
		v1y += (v1y * dx + v2y * dy);
		v1z += (v1z * dx + v2z * dy);

		dx = this.prevDistortion2X + (this.distortion2X - this.prevDistortion2X) * partialTicks;
		dy = this.prevDistortion2Y + (this.distortion2Y - this.prevDistortion2Y) * partialTicks;
		v2x += (v1x * dx + v2x * dy);
		v2y += (v1y * dx + v2y * dy);
		v2z += (v1z * dx + v2z * dy);

		dx = this.prevDistortion3X + (this.distortion3X - this.prevDistortion3X) * partialTicks;
		dy = this.prevDistortion3Y + (this.distortion3Y - this.prevDistortion3Y) * partialTicks;
		v3x += (v1x * dx + v2x * dy);
		v3y += (v1y * dx + v2y * dy);
		v3z += (v1z * dx + v2z * dy);

		dx = this.prevDistortion4X + (this.distortion4X - this.prevDistortion4X) * partialTicks;
		dy = this.prevDistortion4Y + (this.distortion4Y - this.prevDistortion4Y) * partialTicks;
		v4x += (v1x * dx + v2x * dy);
		v4y += (v1y * dx + v2y * dy);
		v4z += (v1z * dx + v2z * dy);

		float alpha;
		if(this.particleAge >= this.particleMaxAge - 40) {
			alpha = this.particleAlpha * (this.particleMaxAge - this.particleAge) / 40.0f;
		} else if(this.particleAge <= 40) {
			alpha = this.particleAlpha * this.particleAge / 40.0f;
		} else {
			alpha = this.particleAlpha;
		}

		emit(buff, rpx + v1x, rpy + v1y, rpz + v1z, this.particleRed, this.particleGreen, this.particleBlue, alpha, maxU, maxV, this.lightmapX, this.lightmapY, n1x, n1y, n1z);
		emit(buff, rpx + v2x, rpy + v2y, rpz + v2z, this.particleRed, this.particleGreen, this.particleBlue, alpha, maxU, minV, this.lightmapX, this.lightmapY, n2x, n2y, n2z);
		emit(buff, rpx + v3x, rpy + v3y, rpz + v3z, this.particleRed, this.particleGreen, this.particleBlue, alpha, minU, minV, this.lightmapX, this.lightmapY, n3x, n3y, n3z);
		emit(buff, rpx + v4x, rpy + v4y, rpz + v4z, this.particleRed, this.particleGreen, this.particleBlue, alpha, minU, maxV, this.lightmapX, this.lightmapY, n4x, n4y, n4z);
	}

@Override
	public void renderParticle(BufferBuilder buff, Entity entityIn, float partialTicks, float rx, float rz, float ryz, float rxy, float rxz) {
		float minU = (float)this.particleTextureIndexX / 16.0F;
		float maxU = minU + 0.0624375F;
		float minV = (float)this.particleTextureIndexY / 16.0F;
		float maxV = minV + 0.0624375F;
		float scale = 0.1F * this.particleScale;

		if (this.particleTexture != null) {
			minU = this.particleTexture.getMinU();
			maxU = this.particleTexture.getMaxU();
			minV = this.particleTexture.getMinV();
			maxV = this.particleTexture.getMaxV();
		}

		float rpx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float rpy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rpz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);
		int brightness = this.getBrightnessForRender(partialTicks);
		int lightmapX = brightness >> 16 & 65535;
		int lightmapY = brightness & 65535;

		buff.pos(rpx - scale, rpy, rpz - scale).tex((double)maxU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos(rpx - scale, rpy, rpz + scale).tex((double)maxU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos(rpx + scale, rpy, rpz + scale).tex((double)minU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos(rpx + scale, rpy, rpz - scale).tex((double)minU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
	}

@Override
	public void renderParticle(BufferBuilder buff, Entity entityIn, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		this.particleScale = (this.prevFlameScale + (this.flameScale - this.prevFlameScale) * partialTicks);

		float scale = 0.1F * this.particleScale;

		float minU = this.particleTexture.getMinU();
		float maxU = this.particleTexture.getMaxU();
		float minV = this.particleTexture.getMinV();
		float maxV = this.particleTexture.getMaxV();

		//remove 1px border to avoid artifacts from smooth filtering
		float borderU = (maxU - minU) / this.particleTexture.getIconWidth();
		float borderV = (maxV - minV) / this.particleTexture.getIconHeight();

		minU += borderU;
		maxU -= borderU;
		minV += borderV;
		maxV -= borderV;

		float rpx = (float) (this.prevPosX + (this.posX - this.prevPosX) * partialTicks - interpPosX);
		float rpy = (float) (this.prevPosY + (this.posY - this.prevPosY) * partialTicks - interpPosY);
		float rpz = (float) (this.prevPosZ + (this.posZ - this.prevPosZ) * partialTicks - interpPosZ);

		int brightness = this.getBrightnessForRender(partialTicks);
		int lightmapX = (brightness >> 16) & 65535;
		int lightmapY = brightness & 65535;

		float v1x = -rotationX * scale - rotationXY * scale;
		float v1y = -rotationZ * scale;
		float v1z = -rotationYZ * scale - rotationXZ * scale;
		float v2x = -rotationX * scale + rotationXY * scale;
		float v2y = rotationZ * scale;
		float v2z = -rotationYZ * scale + rotationXZ * scale;
		float v3x = rotationX * scale + rotationXY * scale;
		float v3y = rotationZ * scale;
		float v3z = rotationYZ * scale + rotationXZ * scale;
		float v4x = rotationX * scale - rotationXY * scale;
		float v4y = -rotationZ * scale;
		float v4z = rotationYZ * scale - rotationXZ * scale;

		if(this.particleAngle != 0.0F) {
			float angle = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
			float cos = MathHelper.cos(angle * 0.5F);
			float rdx = MathHelper.sin(angle * 0.5F) * (float) cameraViewDir.x;
			float rdy = MathHelper.sin(angle * 0.5F) * (float) cameraViewDir.y;
			float rdz = MathHelper.sin(angle * 0.5F) * (float) cameraViewDir.z;

			float dotrdrd = cos * cos - dot(rdx, rdy, rdz, rdx, rdy, rdz);

			float dotvrd = 2 * dot(v1x, v1y, v1z, rdx, rdy, rdz);
			float nx = rdx * dotvrd + v1x * dotrdrd + crossX(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			float ny = rdy * dotvrd + v1y * dotrdrd + crossY(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			float nz = rdz * dotvrd + v1z * dotrdrd + crossZ(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			v1x = nx;
			v1y = ny;
			v1z = nz;

			dotvrd = 2 * dot(v2x, v2y, v2z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v2x * dotrdrd + crossX(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			ny = rdy * dotvrd + v2y * dotrdrd + crossY(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			nz = rdz * dotvrd + v2z * dotrdrd + crossZ(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			v2x = nx;
			v2y = ny;
			v2z = nz;

			dotvrd = 2 * dot(v3x, v3y, v3z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v3x * dotrdrd + crossX(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			ny = rdy * dotvrd + v3y * dotrdrd + crossY(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			nz = rdz * dotvrd + v3z * dotrdrd + crossZ(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			v3x = nx;
			v3y = ny;
			v3z = nz;

			dotvrd = 2 * dot(v4x, v4y, v4z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v4x * dotrdrd + crossX(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			ny = rdy * dotvrd + v4y * dotrdrd + crossY(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			nz = rdz * dotvrd + v4z * dotrdrd + crossZ(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			v4x = nx;
			v4y = ny;
			v4z = nz;
		}

