@Override public void render(T entity, float yaw, float partialTicks, PoseStack matrix, MultiBufferSource buffer, int packedLight) {
        super.render(entity, yaw, partialTicks, matrix, buffer, packedLight);
        matrix.pushPose();
        matrix.scale(.5F, .5F, .5F);
        matrix.mulPose(entityRenderDispatcher.cameraOrientation());
        PoseStack.Pose matrixEntry = matrix.last();
        Matrix4f matrix4f = matrixEntry.pose();
        Matrix3f normal = matrixEntry.normal();
        VertexConsumer vertexBuilder = buffer.getBuffer(renderType);
        pos(vertexBuilder, matrix4f, normal, packedLight, 0, 0, 0, 1);
        pos(vertexBuilder, matrix4f, normal, packedLight, 1, 0, 1, 1);
        pos(vertexBuilder, matrix4f, normal, packedLight, 1, 1, 1, 0);
        pos(vertexBuilder, matrix4f, normal, packedLight, 0, 1, 0, 0);
        matrix.popPose();
    }

@Override public void render(T entity, float yaw, float partialTicks, PoseStack matrix, MultiBufferSource buffer, int packedLight) {
        if(entity.tickCount > 2 || !(entityRenderDispatcher.camera.getEntity().distanceToSqr(entity) < 12.25)) {
            super.render(entity, yaw, partialTicks, matrix, buffer, packedLight);
            matrix.pushPose();
            matrix.scale(.5F, .5F, .5F);
            matrix.mulPose(entityRenderDispatcher.cameraOrientation());
            PoseStack.Pose matrixEntry = matrix.last();
            Matrix4f matrix4f = matrixEntry.pose();
            VertexConsumer vertexBuilder = buffer.getBuffer(renderType);

            pos(vertexBuilder, matrix4f, packedLight, 0, 0, 0, 1);
            pos(vertexBuilder, matrix4f, packedLight, 1, 0, 1, 1);
            pos(vertexBuilder, matrix4f, packedLight, 1, 1, 1, 0);
            pos(vertexBuilder, matrix4f, packedLight, 0, 1, 0, 0);
            matrix.popPose();
        }
    }

@Override protected void setupRotations(EntityGemFin entity, PoseStack poseStack, float bob, float yBodyRot, float partialTick, float scale) {
        super.setupRotations(entity, poseStack, bob, yBodyRot, partialTick, scale);
        float f = 4.3F * Mth.sin(.6F * bob);
        poseStack.mulPose(Axis.YP.rotationDegrees(f));
        if(!entity.isInWater()) {
            poseStack.translate(.2F, .2F, 0);
            poseStack.mulPose(Axis.ZP.rotationDegrees(90));
        }
    }

@Override protected void setupRotations(EntityAequorea entity, PoseStack poseStack, float bob, float yBodyRot, float partialTick, float scale) {
		float f = Mth.lerp(partialTick, entity.xBodyRotO, entity.xBodyRot);
		float f1 = Mth.lerp(partialTick, entity.zBodyRotO, entity.zBodyRot);
		poseStack.translate(0, .25F, 0);
		poseStack.mulPose(Axis.YP.rotationDegrees(180 - yBodyRot));
		poseStack.mulPose(Axis.XP.rotationDegrees(f));
		poseStack.mulPose(Axis.YP.rotationDegrees(f1));
		poseStack.translate(0, -.6F, 0);
	}

