public void render(T pEntity, float pYaw, float pPartialTicks, PoseStack pPoseStack, MultiBufferSource pBuffer, int pPackedLight) {
        pPoseStack.pushPose();
        pPoseStack.translate(0, pEntity.getBoundingBox().getYsize() * 0.5F, 0);
        this.scale(pEntity, pPoseStack, 1.0F);
        Vec3 vec3 = pEntity.getDeltaMovement();
        float xRot = -((float) (Mth.atan2(vec3.horizontalDistance(), vec3.y) * (double) (180F / (float) Math.PI)) - 90.0F);
        float yRot = -((float) (Mth.atan2(vec3.z, vec3.x) * (double) (180.0F / (float) Math.PI)) + 90.0F);
        pPoseStack.mulPose(Axis.YP.rotationDegrees(yRot));
        pPoseStack.mulPose(Axis.XP.rotationDegrees(xRot));
        VertexConsumer consumer = pBuffer.getBuffer(RenderType.entityCutoutNoCull(getTextureLocation(pEntity)));
        this.model.renderToBuffer(pPoseStack, consumer, LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 0.5F);
        pPoseStack.popPose();

        super.render(pEntity, pYaw, pPartialTicks, pPoseStack, pBuffer, pPackedLight);
    }

public void render(T pEntity, float pEntityYaw, float pPartialTicks, PoseStack pMatrixStack, MultiBufferSource pBuffer, int pPackedLight) {
        float f = Math.min(pEntity.localEmergingTime(), pEntity.getAge());
        pMatrixStack.pushPose();
        pMatrixStack.mulPose(Axis.YP.rotationDegrees(pEntity.getYRot()));
        pMatrixStack.scale(-1.0F, -1.0F, 1.0F);
        pMatrixStack.translate(0.0D, 0.0D, 0.0D);
        pMatrixStack.scale(1.0F, 1.0F, 1.0F);
        this.model.setupAnim(pEntity, f, 0.0F, pPartialTicks, pEntity.getYRot(), pEntity.getXRot());
        VertexConsumer ivertexbuilder = pBuffer.getBuffer(this.model.renderType(getTextureLocation(pEntity)));
        this.model.renderToBuffer(pMatrixStack, ivertexbuilder, pPackedLight, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        if (!pEntity.isEmerging() && !pEntity.isInvisible()) {
            RenderType renderType = getActivatedTextureLocation(pEntity);
            if (renderType != null) {
                VertexConsumer vertexconsumer = pBuffer.getBuffer(renderType);
                this.model.renderToBuffer(pMatrixStack, vertexconsumer, pPackedLight, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
            }
            Map<AbstractMonolith.Crackiness, ResourceLocation> locationMap = cracknessLocation();
            if (locationMap != null) {
                AbstractMonolith.Crackiness irongolem$crackiness = pEntity.getCrackiness();
                if (irongolem$crackiness != AbstractMonolith.Crackiness.NONE) {
                    ResourceLocation resourcelocation = locationMap.get(irongolem$crackiness);
                    renderColoredCutoutModel(this.model, resourcelocation, pMatrixStack, pBuffer, pPackedLight, 1.0F, 1.0F, 1.0F);
                }
            }
            this.extraLayer(pEntity, pEntityYaw, pPartialTicks, pMatrixStack, pBuffer, pPackedLight);
        }
        pMatrixStack.popPose();
        super.render(pEntity, pEntityYaw, pPartialTicks, pMatrixStack, pBuffer, pPackedLight);
    }

@Override
    public void render(Apostle pEntity, float pEntityYaw, float pPartialTicks, PoseStack pMatrixStack, MultiBufferSource pBuffer, int pPackedLight) {
        super.render(pEntity, pEntityYaw, pPartialTicks, pMatrixStack, pBuffer, pPackedLight);
        if (pEntity.deathTime > 0) {
            pMatrixStack.pushPose();
            boolean flag = pEntity.hurtTime > 0;
            float f = Mth.rotLerp(pPartialTicks, pEntity.yBodyRotO, pEntity.yBodyRot);
            float f1 = Mth.rotLerp(pPartialTicks, pEntity.yHeadRotO, pEntity.yHeadRot);
            float f2 = f1 - f;
            float f6 = Mth.lerp(pPartialTicks, pEntity.xRotO, pEntity.getXRot());
            float f71 = this.getBob(pEntity, pPartialTicks);
            this.setupRotations(pEntity, pMatrixStack, f71, f, pPartialTicks);
            pMatrixStack.scale(-1.0F, -1.0F, 1.0F);
            this.scale(pEntity, pMatrixStack, pPartialTicks);
            pMatrixStack.translate(0.0D, (double)-1.501F, 0.0D);
            this.model.prepareMobModel(pEntity, 0.0F, 0.0F, pPartialTicks);
            this.model.setupAnim(pEntity, 0.0F, 0.0F, f71, f2, f6);
            float f8 = MobsConfig.FancierApostleDeath.get() || pEntity.level.dimension() == Level.NETHER ? 300.0F : 30.0F;
            float f9 = (float)pEntity.deathTime / f8;
            VertexConsumer vertexconsumer = pBuffer.getBuffer(RenderType.dragonExplosionAlpha(EXPLODE));
            this.model.renderToBuffer(pMatrixStack, vertexconsumer, pPackedLight, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, f9);
            VertexConsumer ivertexbuilder1 = pBuffer.getBuffer(RenderType.entityDecal(this.getTextureLocation(pEntity)));
            this.model.renderToBuffer(pMatrixStack, ivertexbuilder1, pPackedLight, OverlayTexture.pack(0.0F, flag), 1.0F, 1.0F, 1.0F, 1.0F);
            pMatrixStack.popPose();

            if (MobsConfig.FancierApostleDeath.get() || pEntity.level.dimension() == Level.NETHER) {
                if (pEntity.deathTime > 20) {
                    float f5 = ((float) pEntity.deathTime + pPartialTicks) / 200.0F;
                    float f7 = Math.min(f5 > 0.8F ? (f5 - 0.8F) / 0.2F : 0.0F, 1.0F);
                    Random random = new Random(432L);
                    VertexConsumer ivertexbuilder2 = pBuffer.getBuffer(RenderType.lightning());
                    pMatrixStack.pushPose();
                    pMatrixStack.translate(0.0D, 1.0D, 0.0D);

                    for (int i = 0; (float) i < (f5 + f5 * f5) / 2.0F * 10.0F; ++i) {
                        pMatrixStack.mulPose(Axis.XP.rotationDegrees(random.nextFloat() * 360.0F));
                        pMatrixStack.mulPose(Axis.YP.rotationDegrees(random.nextFloat() * 360.0F));
                        pMatrixStack.mulPose(Axis.ZP.rotationDegrees(random.nextFloat() * 360.0F));
                        pMatrixStack.mulPose(Axis.XP.rotationDegrees(random.nextFloat() * 360.0F));
                        pMatrixStack.mulPose(Axis.YP.rotationDegrees(random.nextFloat() * 360.0F));
                        pMatrixStack.mulPose(Axis.ZP.rotationDegrees(random.nextFloat() * 360.0F + f5 * 90.0F));
                        float f3 = random.nextFloat() * 2.0F + 5.0F + f7 * 10.0F;
                        float f4 = random.nextFloat() + 1.0F + f7;
                        Matrix4f matrix4f = pMatrixStack.last().pose();
                        int j = (int) (255.0F * (1.0F - f7));
                        vertex01(ivertexbuilder2, matrix4f, j);
                        vertex2(ivertexbuilder2, matrix4f, f3, f4);
                        vertex3(ivertexbuilder2, matrix4f, f3, f4);
                        vertex01(ivertexbuilder2, matrix4f, j);
                        vertex3(ivertexbuilder2, matrix4f, f3, f4);
                        vertex4(ivertexbuilder2, matrix4f, f3, f4);
                        vertex01(ivertexbuilder2, matrix4f, j);
                        vertex4(ivertexbuilder2, matrix4f, f3, f4);
                        vertex2(ivertexbuilder2, matrix4f, f3, f4);
                    }

                    pMatrixStack.popPose();
                }
            }
