@Override
    public void render(Meganeura meganeura, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        poseStack.pushPose();
        if (meganeura.getAttachSystem().attachStarted()) {
            Direction face = meganeura.getAttachSystem().getAttachmentFace();
            Vec3i normal = face.getNormal();
            float yRot = toPoseStackRotation(face.getOpposite().toYRot());
            float xRot = (float) -Mth.atan2(Mth.sqrt(normal.getX() * normal.getX() + normal.getZ() * normal.getZ()), 0) * Mth.RAD_TO_DEG;
            float translate = meganeura.getBbWidth() / 2;
            float yTranslate = 0.2f;
            if (!meganeura.getAttachSystem().isAttached()) {
                //Is approaching
                Vec3 pos = meganeura.getAttachSystem().getAttachmentPos();
                double dist = pos.distanceTo(meganeura.position());
                if (dist < 1) {
                    //TODO: Use initial dist as base value so that it still looks good when starting closer than 1
                    xRot *= (float) Math.min((-dist + 1) * 1.2, 1);
                    translate *= (float) Math.min((-dist + 1) * 1.2, 1);
                    yTranslate *= (float) Math.min((-dist + 1) * 1.2, 1);
                } else {
                    xRot = 0;
                    translate = 0;
                    yTranslate = 0;
                }
                Vec3 offset = pos.subtract(meganeura.position());
                double yawDiff = (Mth.atan2(offset.z, offset.x) * Mth.RAD_TO_DEG);
                yRot = toPoseStackRotation(Util.clampTo360(Util.yawToYRot(yawDiff)));
            }
            yRot += entityYaw;
            poseStack.translate(-normal.getX() * translate, yTranslate, -normal.getZ() * translate);
            //Could apply z rotation depending on approach angle
            poseStack.mulPose(Vector3f.YP.rotationDegrees(yRot));
            poseStack.mulPose(Vector3f.XP.rotationDegrees(xRot));
        }
        super.render(meganeura, entityYaw, partialTick, poseStack, buffer, packedLight);
        poseStack.popPose();
    }

@Override
    public void render(T entity, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        this.shadowRadius = entity.getBbWidth() * 0.45F;
        poseStack.pushPose();
        if (entity.getClimbingDirection() != Direction.UP || (entity.prevClimbDirection != Direction.UP && entity.climbTick > 0)) {
            float progress = Mth.lerp(partialTick, entity.prevClimbTick, entity.climbTick) / 5f;
            Direction dir = entity.getClimbingDirection() != Direction.UP ? entity.getClimbingDirection() : entity.prevClimbDirection;
            float offset = entity.getBbWidth() / 2 * progress;
            poseStack.translate(dir.getStepX() * offset, 0.5 * progress, dir.getStepZ() * offset);
            Direction dirRot = dir.getClockWise();
            poseStack.mulPose(new Vector3f(dirRot.getStepX(), 0, dirRot.getStepZ()).rotationDegrees(90 * progress));
        }
        super.render(entity, entityYaw, partialTick, poseStack, buffer, packedLight);
        poseStack.popPose();
    }

@Override
    protected void applyRotations(T animatable, PoseStack poseStack, float ageInTicks, float rotationYaw, float partialTick) {
        poseStack.mulPose(Vector3f.YP.rotationDegrees(180f - rotationYaw));
        if (animatable.deathTime > 0) {
            float deathRotation = (animatable.deathTime + partialTick - 1f) / 20f * 1.6f;

            poseStack.mulPose(Vector3f.ZP.rotationDegrees(Math.min(Mth.sqrt(deathRotation), 1) * getDeathMaxRotation(animatable)));
        } else if (animatable.hasCustomName()) {
            String name = ChatFormatting.stripFormatting(animatable.getName().getString());

            if (name != null && (name.equals("Dinnerbone") || name.equalsIgnoreCase("Grumm"))) {
                poseStack.translate(0, animatable.getBbHeight() + 0.1f, 0);
                poseStack.mulPose(Vector3f.ZP.rotationDegrees(180f));
            }
        }
    }

@Override
    public void render(PrehistoricSkeleton animatable, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight) {
        setCurrentModelRenderCycle(EModelRenderCycle.INITIAL);
        poseStack.pushPose();
        dispatchedMat = poseStack.last().pose().copy();
        GeoModel model = geoModel.getModel(geoModel.getModelLocation(animatable));
        poseStack.translate(0, 0.01f, 0);
        RenderSystem.setShaderTexture(0, getTextureLocation(animatable));

        if (!animatable.isInvisibleTo(Minecraft.getInstance().player)) {
            poseStack.mulPose(Vector3f.YP.rotationDegrees(180f - animatable.getYRot()));

            Color renderColor = getRenderColor(animatable, partialTick, poseStack, bufferSource, null, packedLight);
            RenderType renderType = getRenderType(animatable, partialTick, poseStack, bufferSource, null, packedLight, getTextureLocation(animatable));

            VertexConsumer glintBuffer = bufferSource.getBuffer(RenderType.entityGlintDirect());
            VertexConsumer translucentBuffer = bufferSource.getBuffer(RenderType.entityTranslucentCull(getTextureLocation(animatable)));

            render(model, animatable, partialTick, renderType, poseStack, bufferSource,
                    glintBuffer != translucentBuffer ? VertexMultiConsumer.create(glintBuffer, translucentBuffer) : null,
                    packedLight, OverlayTexture.pack(OverlayTexture.u(0), OverlayTexture.v(false)), renderColor.getRed() / 255f, renderColor.getGreen() / 255f, renderColor.getBlue() / 255f, renderColor.getAlpha() / 255f);
        }

        poseStack.popPose();
        super.render(animatable, entityYaw, partialTick, poseStack, bufferSource, packedLight);
    }

@Override
    public void renderRecursively(GeoBone bone, PoseStack poseStack, VertexConsumer buffer, int packedLight, int packedOverlay, float red, float green, float blue, float alpha) {
        poseStack.pushPose();
        RenderUtils.translateMatrixToBone(poseStack, bone);
        RenderUtils.translateToPivotPoint(poseStack, bone);

        boolean rotOverride = bone.rotMat != null;

        if (rotOverride) {
            poseStack.last().pose().multiply(bone.rotMat);
            poseStack.last().normal().mul(new Matrix3f(bone.rotMat));
        } else {
            RenderUtils.rotateMatrixAroundBone(poseStack, bone);
        }

        RenderUtils.scaleMatrixForBone(poseStack, bone);

        if (bone.isTrackingXform()) {
            Matrix4f poseState = poseStack.last().pose().copy();
            Matrix4f localMatrix = RenderUtils.invertAndMultiplyMatrices(poseState, this.dispatchedMat);

            bone.setModelSpaceXform(RenderUtils.invertAndMultiplyMatrices(poseState, this.renderEarlyMat));
            localMatrix.translate(new Vector3f(getRenderOffset(this.animatable, 1)));
            bone.setLocalSpaceXform(localMatrix);

            Matrix4f worldState = localMatrix.copy();

            worldState.translate(new Vector3f(this.animatable.position()));
            bone.setWorldSpaceXform(worldState);
        }

        RenderUtils.translateAwayFromPivotPoint(poseStack, bone);

        if (!bone.isHidden) {
            if (!bone.cubesAreHidden()) {
                for (GeoCube geoCube : bone.childCubes) {
                    poseStack.pushPose();
                    renderCube(geoCube, poseStack, buffer, packedLight, packedOverlay, red, green, blue, alpha);
                    poseStack.popPose();
                }
            }

            for (GeoBone childBone : bone.childBones) {
                renderRecursively(childBone, poseStack, buffer, packedLight, packedOverlay, red, green, blue, alpha);
            }
        }

        poseStack.popPose();
    }

