@Override
	public void submit(S state, PoseStack stack, SubmitNodeCollector buffer, CameraRenderState cameraRenderState) {
		stack.pushPose();

		this.setupRotations(state, stack, state.partialTick);
		stack.scale(-1.0F, -1.0F, 1.0F);
		stack.translate(0.0D, -1.501F, 0.0D);
		this.model.setupAnim(state);
		boolean visible = !state.isInvisible;
		boolean ghostly = !visible && !state.isInvisibleToPlayer;
		boolean glowing = state.appearsGlowing;
		RenderType rendertype = this.getRenderType(state, visible, ghostly, glowing);
		if (rendertype != null) {
			int overlay = this.getOverlayCoords(state);
			int j = ghostly ? 654311423 : -1;
			int k = ARGB.multiply(j, this.getModelTint(state));
			buffer.submitModel(this.model, state, stack, rendertype, state.lightCoords, overlay, k, null, state.outlineColor, null);
		}

		stack.popPose();
		super.submit(state, stack, buffer, cameraRenderState);
	}

protected void setupRotations(S state, PoseStack stack, float partialTicks) {
		if (state.deathTime > 0) {
			float f = (state.deathTime + partialTicks - 1.0F) / 20.0F * 1.6F;
			f = Mth.sqrt(f);
			if (f > 1.0F) {
				f = 1.0F;
			}

			stack.mulPose(Axis.ZP.rotationDegrees(f * this.getFlipDegrees()));
		} else if (state.isUpsideDown) {
			stack.translate(0.0F, (state.boundingBoxHeight + 0.1F) / partialTicks, 0.0F);
			stack.mulPose(Axis.ZP.rotationDegrees(180.0F));
		}
	}

@Override
	public void submit(ThrownWepRenderState state, PoseStack stack, SubmitNodeCollector collector, CameraRenderState camera) {
		stack.pushPose();
		float spin = state.ageInTicks * 10.0F;
		// size up
		stack.scale(1.25F, 1.25F, 1.25F);
		stack.mulPose(Axis.YP.rotationDegrees(state.yRot + 90.0F));
		stack.mulPose(Axis.ZP.rotationDegrees(spin));
		float f9 = 0.5F;
		float f10 = 0.25F;
		float f12 = 0.0625F;
		float f11 = 0.021875F;
		stack.translate(-f9, -f10, -(f12 + f11));
		stack.translate(0.0F, 0.0F, f12 + f11);

		if (!state.item.isEmpty()) {
			state.item.submit(stack, collector, state.lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor);
		}
		stack.popPose();
	}

@Override
	protected void scale(LivingEntityRenderState state, PoseStack stack) {
		stack.translate(0.0F, Mth.sin(state.ageInTicks * 0.2F) * 0.15F, 0.0F);

		// flash
		if (state.deathTime > 0.0F) {
			int deathTick = (int) state.deathTime;
			float wobble = 1.0F + Mth.lerp(state.deathTime - deathTick, this.wobbleAt(deathTick), this.wobbleAt(deathTick + 1));

			float growth = Math.min(state.deathTime, 1.0F);
			growth *= growth;
			growth *= growth;

			float horizontal = (1.0F + growth * 0.4F) * wobble;
			float vertical = (1.0F + growth * 0.1F) / wobble;
			stack.scale(horizontal, vertical, horizontal);
		}
	}

@Override
	public void submit(PoseStack stack, SubmitNodeCollector submitNodeCollector, int light, S state, float netHeadYaw, float headPitch) {
		Double count = state.getRenderData(FROST_COUNT_KEY);
		if (count == null)
			return;
		Integer id = state.getRenderData(FROST_ID_KEY);
		if (id == null)
			return;

		Minecraft.getInstance().getBlockModelResolver().update(iceModel, Blocks.ICE.defaultBlockState(), displayContext);

		random.setSeed(id * id * 3121L + id * 45238971L);

		int numCubes = (int) (state.boundingBoxHeight / 0.4F) + (int) (count / FrostedEffect.FROST_MULTIPLIER) + 1; //Number of cubes, adds more cubes based on the level of the effect

		float specialOffset = getParentModel() instanceof DeathTomeModel ? 1.0F : 0.0F;

		for (int i = 0; i < numCubes; i++) { //Render cubes
			stack.pushPose();
			float dx = ((random.nextFloat() * (state.boundingBoxWidth * 2.0F)) - state.boundingBoxWidth) * 0.1F;
			float dy = Math.max(1.5F - (random.nextFloat()) * (state.boundingBoxHeight - specialOffset), -0.1F) - specialOffset; //Gotta limit the height because otherwise frozen giants make blocks spawn like 10 blocks above them
			float dz = ((random.nextFloat() * (state.boundingBoxWidth * 2.0F)) - state.boundingBoxWidth) * 0.1F;
			stack.translate(dx, dy, dz);
			stack.scale(0.5F, 0.5F, 0.5F);
			stack.mulPose(Axis.XP.rotationDegrees(random.nextFloat() * 360F));
			stack.mulPose(Axis.YP.rotationDegrees(random.nextFloat() * 360F));
			stack.mulPose(Axis.ZP.rotationDegrees(random.nextFloat() * 360F));
			stack.translate(-0.5F, -0.5F, -0.5F);

			iceModel.submit(stack, submitNodeCollector, light, OverlayTexture.NO_OVERLAY, 0);

			stack.popPose();
		}
	}

private void renderShields(PoseStack stack, SubmitNodeCollector collector, S state, int count) {
		QuadCollection shieldModel = Minecraft.getInstance().getModelManager().getStandaloneModel(SHIELD_MODEL);
		if (shieldModel == null)
			return;

		List<BakedQuad> quads = shieldModel.getAll();
		if (quads.isEmpty())
			return;

		QuadInstance instance = new QuadInstance();

		float age = state.ageInTicks;
		float rotateAngleY = age / -5.0F;
		float rotateAngleX = Mth.sin(age / 5.0F) / 4.0F;
		float rotateAngleZ = Mth.cos(age / 5.0F) / 4.0F;

		for (int c = 0; c < count; c++) {
			stack.pushPose();

			// perform the rotations, accounting for the fact that baked models are corner-based
			// Z gets extra 180 degrees to flip visual upside-down, since scaling y by -1 will cause back-faces to render instead
			stack.mulPose(Axis.ZP.rotationDegrees(180.0F + rotateAngleZ * (180.0F / Mth.PI)));
			stack.mulPose(Axis.YP.rotationDegrees(rotateAngleY * (180.0F / Mth.PI) + (c * (360.0F / count))));
			stack.mulPose(Axis.XP.rotationDegrees(rotateAngleX * (180.0F / Mth.PI)));
			stack.translate(-0.5F, -0.65F, -0.5F);

			// push the shields outwards from the center of rotation
			stack.translate(0.0F, 0.0F, -0.7F);

			collector.submitCustomGeometry(stack, Sheets.translucentItemSheet(), (pose, buffer) -> {
				for (BakedQuad quad : quads) {
					buffer.putBakedQuad(pose, quad, instance);
				}
			});

			stack.popPose();
		}
	}

