@Override
	public void render(PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, AbstractClientPlayer player, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float netHeadPitch) {
		if (!player.isInvisible() && AoAConfigs.CLIENT.showPlayerHalos.get()) {
			PlayerHaloManager.getHaloForRender(player.getUUID()).ifPresent(halo -> {
				if (halo == HaloTypes.TSLAT) {
					VertexConsumer vertexConsumer = bufferSource.getBuffer(TSLAT_HALO_RENDER_TYPE);

					this.model.root.copyFrom(getParentModel().getHead());
					this.model.renderToBuffer(poseStack, vertexConsumer, LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, ColourUtil.ARGB(0, 0, 0, 0.1f));

					return;
				}

				float red = 0;
				float green = 0;
				float blue = 0;

				switch (halo) {
					case DONATOR -> {
						red = 1;
						green = 1;
					}
					case SUPER_DONATOR -> red = 1;
					case STAFF -> {
						red = 0.6f;
						green = 1;
						blue = 1;
					}
					case WIKI_EDITOR -> blue = 1;
				}

				RenderSystem.enableBlend();
				RenderSystem.disableDepthTest();
				this.model.root.copyFrom(getParentModel().getHead());
				this.model.renderToBuffer(poseStack, bufferSource.getBuffer(RenderType.entityTranslucent(getTextureLocation(player))), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, ColourUtil.ARGB(red, green, blue, 0.1f));
				RenderSystem.enableDepthTest();
				RenderSystem.disableBlend();
			});
		}
	}

@Override
    public void render(EarthquakeBlockEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        final BlockState blockState = entity.getBlock();

        if (blockState.getRenderShape() != RenderShape.MODEL)
            return;

        BlockPos blockPos = BlockPos.containing(entity.getX(), entity.getBoundingBox().maxY, entity.getZ());
        BakedModel model = this.dispatcher.getBlockModel(blockState);
        long seed = blockState.getSeed(entity.getBlockOrigin());

        poseStack.pushPose();
        poseStack.translate(-0.5f, 0, -0.5f);

        for (var renderType : model.getRenderTypes(blockState, RandomSource.create(seed), ModelData.EMPTY)) {
            this.dispatcher.getModelRenderer().tesselateBlock(entity.level(), model, blockState, blockPos, poseStack, buffer.getBuffer(RenderTypeHelper.getMovingBlockRenderType(renderType)), false, RandomSource.create(), seed, OverlayTexture.NO_OVERLAY, ModelData.EMPTY, renderType);
        }

        poseStack.popPose();

        super.render(entity, entityYaw, partialTicks, poseStack, buffer, packedLight);
    }

@Override
    public void render(FakeTntEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        poseStack.pushPose();
        poseStack.translate(0, 0.5f, 0);

        final float fuseTick = (float)entity.getFuse();

        if (fuseTick - partialTicks + 1f < 10) {
            float swell = Mth.clamp(1f - (fuseTick - partialTicks + 1f) / 10f, 0, 1f);
            float scale = 1f + swell * swell * swell * 0.3f;

            poseStack.scale(scale, scale, scale);
        }

        poseStack.mulPose(Axis.YP.rotationDegrees(-90f));
        poseStack.translate(-0.5f, -0.5f, 0.5f);
        poseStack.mulPose(Axis.YP.rotationDegrees(90f));
        TntMinecartRenderer.renderWhiteSolidBlock(this.blockRenderer, Blocks.TNT.defaultBlockState(), poseStack, buffer, packedLight, ((int)fuseTick) / 5 % 2 == 0);
        poseStack.popPose();

