private static void onWorldRender(final RenderWorldLastEvent ev) {
		if (occultBlockMap.isEmpty())
			return;

		ArrayList<Integer> expiredBlocks = null;

		for (Map.Entry<Integer, ArrayList<Pair<BlockPos, BlockState>>> entry : occultBlockMap.entrySet()) {
			if (GlobalEvents.tick >= entry.getKey()) {
				if (expiredBlocks == null)
					expiredBlocks = new ArrayList<Integer>();

				expiredBlocks.add(entry.getKey());
			}
			else {
				ArrayList<Pair<BlockPos, BlockState>> invalidBlocks = null;
				Minecraft mc = Minecraft.getInstance();
				MatrixStack matrix = ev.getMatrixStack();
				Vector3d cameraPos = mc.gameRenderer.getMainCamera().getPosition();
				Tessellator tess = Tessellator.getInstance();
				BufferBuilder buff = tess.getBuilder();

				matrix.pushPose();
				matrix.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());

				RenderSystem.pushMatrix();
				RenderSystem.multMatrix(matrix.last().pose());

				RenderSystem.disableTexture();
				RenderSystem.disableDepthTest();
				RenderSystem.depthMask(false);
				RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_LINE);
				RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				RenderSystem.enableBlend();
				RenderSystem.lineWidth(4f);

				for (Pair<BlockPos, BlockState> block : entry.getValue()) {
					if (GlobalEvents.tick % 2 == 1 && mc.player.level.getBlockState(block.getFirst()) != block.getSecond()) {
						if (invalidBlocks == null)
							invalidBlocks = new ArrayList<Pair<BlockPos, BlockState>>();

						invalidBlocks.add(block);

						continue;
					}

					Vector4f colour = getColourForBlock(block.getSecond());
					BlockPos pos = block.getFirst();

					RenderSystem.pushMatrix();
					RenderSystem.translated(pos.getX(), pos.getY(), pos.getZ());
					buff.begin(GL_LINES, DefaultVertexFormats.POSITION_COLOR);
					RenderUtil.renderBlockOutline(buff, colour.x(), colour.y(), colour.z(), colour.w());
					tess.end();
					RenderSystem.popMatrix();
				}

				RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_FILL);
				RenderSystem.disableBlend();
				RenderSystem.enableDepthTest();
				RenderSystem.depthMask(true);
				RenderSystem.enableTexture();

				RenderSystem.popMatrix();
				matrix.popPose();

				if (invalidBlocks != null)
					entry.getValue().removeAll(invalidBlocks);
			}
		}

		if (expiredBlocks != null) {
			for (Integer tick : expiredBlocks) {
				occultBlockMap.remove(tick);
			}
		}
	}

@Override
	protected void setupRotations(DoppelgangerEntity doppelganger, MatrixStack matrixStack, float age, float yawRot, float partialTicks) {
		if (doppelganger.isFallFlying()) {
			super.setupRotations(doppelganger, matrixStack, age, yawRot, partialTicks);

			float lerpFallTicks = (float)doppelganger.getFallFlyingTicks() + partialTicks;

			if (!doppelganger.isAutoSpinAttack())
				matrixStack.mulPose(Vector3f.XP.rotationDegrees(MathHelper.clamp(lerpFallTicks * lerpFallTicks / 100.0F, 0.0F, 1.0F) * (-90.0F - doppelganger.xRot)));

			Vector3d viewVec = doppelganger.getViewVector(partialTicks);
			Vector3d velocity = doppelganger.getDeltaMovement();
			double velocityScaleOffset = Entity.getHorizontalDistanceSqr(velocity);
			double viewScaleOffset = Entity.getHorizontalDistanceSqr(viewVec);

			if (velocityScaleOffset > 0 && viewScaleOffset > 0)
				matrixStack.mulPose(Vector3f.YP.rotation((float)(Math.signum(velocity.x * viewVec.z - velocity.z * viewVec.x) * Math.acos((velocity.x * viewVec.x + velocity.z * viewVec.z) / Math.sqrt(velocityScaleOffset * viewScaleOffset)))));
		}
		else if (doppelganger.getSwimAmount(partialTicks) > 0) {
			super.setupRotations(doppelganger, matrixStack, age, yawRot, partialTicks);

			matrixStack.mulPose(Vector3f.XP.rotationDegrees(MathHelper.lerp(doppelganger.getSwimAmount(partialTicks), 0, doppelganger.isInWater() ? -90 - doppelganger.xRot : -90)));

			if (doppelganger.isVisuallySwimming())
				matrixStack.translate(9, -1, 0.3f);
		}
		else {
			super.setupRotations(doppelganger, matrixStack, age, yawRot, partialTicks);
		}
	}

@Override
	public void render(MobEntity entity, float entityYaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);

		CopyOnWriteArrayList<Pair<Integer, Vector3d>> clones = ((OcculentEntity)entity).clones;
		BlockPos.Mutable mutablePos = new BlockPos.Mutable();

		if (!clones.isEmpty())
			clones.removeIf(clone -> clone.getFirst() <= GlobalEvents.tick);

		for (Pair<Integer, Vector3d> clone : clones) {
			Vector3d cloneOffset = clone.getSecond();
			double lerpX = MathHelper.lerp(partialTicks, entity.xOld, entity.getX());
			double lerpZ = MathHelper.lerp(partialTicks, entity.zOld, entity.getZ());

			if (!entity.level.getBlockState(mutablePos.set(lerpX + cloneOffset.x(), entity.blockPosition().getY() - 1, lerpZ + cloneOffset.z())).entityCanStandOn(entity.level, mutablePos, entity))
				continue;

			if (entity.level.getBlockState(mutablePos.move(Direction.UP)).getMaterial().blocksMotion())
				continue;

			matrix.pushPose();
			matrix.translate(cloneOffset.x(), 0, cloneOffset.z());

			super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);

			matrix.popPose();
		}
	}

@Override
	public void render(DryadSpriteEntity entity, float entityYaw, float partialTicks, MatrixStack stack, IRenderTypeBuffer bufferIn, int packedLightIn) {
		stack.pushPose();
		boolean shouldSit = entity.isPassenger() && (entity.getVehicle() != null && entity.getVehicle().shouldRiderSit());
		EntityModelData entityModelData = new EntityModelData();
		entityModelData.isSitting = shouldSit;
		entityModelData.isChild = entity.isBaby();

		float lerpBodyRot = MathHelper.rotLerp(partialTicks, entity.yBodyRotO, entity.yBodyRot);
		float lerpHeadRot = MathHelper.rotLerp(partialTicks, entity.yHeadRotO, entity.yHeadRot);
		float netHeadYaw = lerpHeadRot - lerpBodyRot;

		if (shouldSit && entity.getVehicle() instanceof LivingEntity) {
			LivingEntity vehicle = (LivingEntity) entity.getVehicle();
			lerpBodyRot = MathHelper.rotLerp(partialTicks, vehicle.yBodyRotO, vehicle.yBodyRot);
			netHeadYaw = lerpHeadRot - lerpBodyRot;
			float finalHeadYaw = MathHelper.clamp(MathHelper.wrapDegrees(netHeadYaw), -85, 85);

			lerpBodyRot = lerpHeadRot - finalHeadYaw;

			if (finalHeadYaw * finalHeadYaw > 2500)
				lerpBodyRot += finalHeadYaw * 0.2F;

			netHeadYaw = lerpHeadRot - lerpBodyRot;
		}

		float headPitch = MathHelper.lerp(partialTicks, entity.xRotO, entity.xRot);

		if (entity.getPose() == Pose.SLEEPING) {
			Direction direction = entity.getBedOrientation();

			if (direction != null) {
				float eyeHeight = entity.getEyeHeight(Pose.STANDING) - 0.1F;

				stack.translate((float) (-direction.getStepX()) * eyeHeight, 0.0D, (float) (-direction.getStepZ()) * eyeHeight);
			}
		}

		float lerpAge = this.handleRotationFloat(entity, partialTicks);
		this.applyRotations(entity, stack, lerpAge, lerpBodyRot, partialTicks);

		float limbSwingAmount = 0;
		float limbSwing = 0;

		if (!shouldSit && entity.isAlive()) {
			limbSwingAmount = MathHelper.lerp(partialTicks, entity.animationSpeedOld, entity.animationSpeed);
			limbSwing = entity.animationPosition - entity.animationSpeed * (1.0F - partialTicks);

			if (entity.isBaby())
				limbSwing *= 3;

			if (limbSwingAmount > 1)
				limbSwingAmount = 1;
		}

		entityModelData.headPitch = -headPitch;
		entityModelData.netHeadYaw = -netHeadYaw;

		AnimationEvent<DryadSpriteEntity> predicate = new AnimationEvent<DryadSpriteEntity>(entity, limbSwing, limbSwingAmount, partialTicks, !(limbSwingAmount > -0.15F && limbSwingAmount < 0.15F), Collections.singletonList(entityModelData));
		GeoModelProvider<DryadSpriteEntity> modelProvider = getGeoModelProvider();
		GeoModel model = modelProvider.getModel(modelProvider.getModelLocation(entity));

		if (modelProvider instanceof IAnimatableModel)
			((IAnimatableModel<DryadSpriteEntity>) modelProvider).setLivingAnimations(entity, this.getUniqueID(entity), predicate);

		stack.translate(0, 0.01f, 0);

		Minecraft.getInstance().textureManager.bind(getTextureLocation(entity));

		Color renderColor = getRenderColor(entity, partialTicks, stack, bufferIn, null, packedLightIn);
		RenderType renderType = getRenderType(entity, partialTicks, stack, bufferIn, null, packedLightIn, getTextureLocation(entity));
		float red = renderColor.getRed() / 255f;
		float green = renderColor.getGreen() / 255f;
		float blue = renderColor.getBlue() / 255f;
		float alpha = entity.isInvisibleTo(Minecraft.getInstance().player) ? 0 : renderColor.getAlpha() / 255f;

		render(model, entity, partialTicks, renderType, stack, bufferIn, null, packedLightIn, getOverlay(entity, 0), red, green, blue, alpha);

		if (!entity.isSpectator()) {
			for (GeoLayerRenderer<DryadSpriteEntity> layerRenderer : this.layerRenderers) {
				layerRenderer.render(stack, bufferIn, packedLightIn, entity, limbSwing, limbSwingAmount, partialTicks, lerpAge, netHeadYaw, headPitch);
			}
		}

		if (ModList.get().isLoaded("patchouli"))
			PatchouliCompat.patchouliLoaded(stack);

		stack.popPose();

		RenderNameplateEvent renderNameplateEvent = new RenderNameplateEvent(entity, entity.getDisplayName(), this, stack, bufferIn, packedLightIn, partialTicks);
		MinecraftForge.EVENT_BUS.post(renderNameplateEvent);

		if (renderNameplateEvent.getResult() != Event.Result.DENY && (renderNameplateEvent.getResult() == Event.Result.ALLOW || this.shouldShowName(entity)))
			renderNameTag(entity, renderNameplateEvent.getContent(), stack, bufferIn, packedLightIn);
	}

@Override
	public void render(T entity, float yaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		matrix.pushPose();
		matrix.scale(-1.0F, -1.0F, 1.0F);
		preRenderCallback(entity, matrix, partialTicks);

		float pitch = MathHelper.lerp(partialTicks, entity.xRotO, entity.xRot);

		model.prepareMobModel(entity, 0, 0, partialTicks);
		model.setupAnim(entity, 0, partialTicks, entity.tickCount, 0, pitch);
		matrix.translate(0.0D, -1.6f, 0.0D);

		boolean visible = !entity.isInvisible();
		boolean shade = !visible && !entity.isInvisibleTo(Minecraft.getInstance().player);
		RenderType rendertype = getRenderType(entity, visible, shade);

		if (rendertype != null) {
			IVertexBuilder ivertexbuilder = buffer.getBuffer(rendertype);

			this.model.renderToBuffer(matrix, ivertexbuilder, packedLight, ColourUtil.WHITE, 1f, 1f, 1f, shade ? 0.15f : 1f);
		}

		matrix.popPose();
		super.render(entity, yaw, partialTicks, matrix, buffer, packedLight);
	}

