@Override
	public void render(LunarCreationTableTileEntity tileEntity, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int combinedLight, int combinedOverlay) {
		NonNullList<ItemStack> contents = tileEntity.getContents();
		ItemRenderer renderer = Minecraft.getInstance().getItemRenderer();
		World world = tileEntity.getLevel();
		BlockPos abovePos = tileEntity.getBlockPos().above();

		if (world != null) {
			if (world.getBlockState(abovePos).isSolidRender(world, abovePos))
				return;

			combinedLight = WorldRenderer.getLightColor(world, abovePos);
		}
		else {
			combinedLight = 15728880;
		}

		matrix.pushPose();

		matrix.scale(0.25f, 0.25f, 0.25f);
		matrix.translate(1.25f, 4.25f, 1.25f);
		matrix.mulPose(Vector3f.YP.rotationDegrees(180f));

		for (int i = 0; i < 9; i++) {
			ItemStack stack = contents.get(i);

			if (stack.isEmpty())
				continue;

			matrix.pushPose();
			matrix.translate(-0.75f * (i % 3), 0, -0.75f * (i / 3));

			if (!(stack.getItem() instanceof BlockItem))
				matrix.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(stack, ItemCameraTransforms.TransformType.FIXED, combinedLight, combinedOverlay, matrix, buffer);
			matrix.popPose();
		}

		matrix.popPose();
	}

@Override
	public void render(TrophyTileEntity tileEntity, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int combinedLight, int combinedOverlay) {
		Entity entity = tileEntity.getCachedEntity();

		if (entity == null && "minecraft:player".equals(tileEntity.getEntityId()))
			entity = Minecraft.getInstance().player;

		if (entity != null) {
			try {
				matrix.pushPose();
				matrix.translate(0.5f, 0, 0.5f);

				float scale = 0.53125F;
				float maxScale = Math.max(entity.getBbWidth(), entity.getBbHeight());
				double hover = (MathHelper.sin((float)tileEntity.hoverStep + partialTicks) / 30d);
				tileEntity.hoverStep += hover * 0.01f;
				EntityRendererManager entityRenderer = Minecraft.getInstance().getEntityRenderDispatcher();

				if (maxScale > 1.0D)
					scale /= maxScale;

				matrix.translate(0, -0.1, 0);
				matrix.scale(scale, scale, scale);
				matrix.translate(0, (1 / scale), 0);

				if (tileEntity.isOriginal() && partialTicks > 0.95f)
					entity.level.addParticle(new CustomisableParticleType.Data(AoAParticleTypes.FLICKERING_SPARKLER.get(), 0.005f, 10, ColourUtil.RGB(255, 200, 0)), tileEntity.getBlockPos().getX() + 0.5f, tileEntity.getBlockPos().getY() + 0.9 + ((entity.getBbHeight() / 2f) * scale), tileEntity.getBlockPos().getZ() + 0.5f, RandomUtil.randomGaussianValue() * 0.5f, RandomUtil.randomGaussianValue() * 0.5f, RandomUtil.randomGaussianValue() * 0.5f);

				if (AoAConfig.CLIENT.rotatingTrophies.get())
					matrix.mulPose(Vector3f.YP.rotationDegrees(MathHelper.lerp(partialTicks, tileEntity.getPrevMobRotation(), tileEntity.getMobRotation()) * 30.0F));

				entityRenderer.setRenderShadow(false);
				entityRenderer.render(entity, 0, 0, 0, 0, 0, matrix, buffer, combinedLight);
				entityRenderer.setRenderShadow(true);
				matrix.popPose();
			}
			catch (Exception ex) {}
		}
	}

@Override
	public void render(TotemOfHoldingEntity entity, float entityYaw, float partialTicks, @NotNull PoseStack matrixStackIn, @NotNull MultiBufferSource bufferIn, int packedLightIn) {
		int deathTicks = entity.getDeathTicks();
		boolean dying = entity.isDying();
		float time = entity.tickCount + partialTicks;
		float scale = !dying ? 1F : Math.max(0, TotemOfHoldingEntity.DEATH_TIME - (deathTicks + partialTicks)) / TotemOfHoldingEntity.DEATH_TIME;
		float rotation = time + (!dying ? 0 : (deathTicks + partialTicks) * 5);
		double translation = !dying ? (Math.sin(time * 0.03) * 0.1) : ((deathTicks + partialTicks) / TotemOfHoldingEntity.DEATH_TIME * 5);

		Minecraft mc = Minecraft.getInstance();
		BlockRenderDispatcher dispatcher = mc.getBlockRenderer();
		ModelManager modelManager = mc.getModelManager();

		matrixStackIn.pushPose();
		matrixStackIn.mulPose(Axis.YP.rotationDegrees(rotation));
		matrixStackIn.translate(0, translation, 0);
		matrixStackIn.scale(scale, scale, scale);
		matrixStackIn.translate(-0.5, 0, -0.5);
		dispatcher.getModelRenderer().renderModel(matrixStackIn.last(), bufferIn.getBuffer(Sheets.cutoutBlockSheet()),
				null,
				modelManager.getModel(LOCATION_MODEL), 1.0F, 1.0F, 1.0F, packedLightIn, OverlayTexture.NO_OVERLAY);
		matrixStackIn.popPose();

		super.render(entity, entityYaw, partialTicks, matrixStackIn, bufferIn, packedLightIn);
	}

@Override
	public void render(@NotNull GlassItemFrame frame, float yaw, float partialTicks, @NotNull PoseStack matrix, @NotNull MultiBufferSource buffer, int light) {
		super.render(frame, yaw, partialTicks, matrix, buffer, light);
		matrix.pushPose();
		Direction direction = frame.getDirection();
		Vec3 Vector3d = this.getRenderOffset(frame, partialTicks);
		matrix.translate(-Vector3d.x(), -Vector3d.y(), -Vector3d.z());
		matrix.translate((double) direction.getStepX() * 0.46875D, (double) direction.getStepY() * 0.46875D, (double) direction.getStepZ() * 0.46875D);
		matrix.mulPose(Axis.XP.rotationDegrees(frame.getXRot()));
		matrix.mulPose(Axis.YP.rotationDegrees(180.0F - frame.getYRot()));
		BlockRenderDispatcher blockRenderer = this.mc.getBlockRenderer();
		ModelManager modelmanager = blockRenderer.getBlockModelShaper().getModelManager();

		ItemStack itemstack = frame.getItem();

		if(frame.getEntityData().get(GlassItemFrame.IS_SHINY))
			light = 15728880; //0xF000F0

		if(itemstack.isEmpty()) {
			matrix.pushPose();
			matrix.translate(-0.5D, -0.5D, -0.5D);
			blockRenderer.getModelRenderer().renderModel(matrix.last(), buffer.getBuffer(Sheets.cutoutBlockSheet()), null, modelmanager.getModel(LOCATION_MODEL), 1.0F, 1.0F, 1.0F, light, OverlayTexture.NO_OVERLAY);
			matrix.popPose();
		} else {
			renderItemStack(frame, matrix, buffer, light, itemstack);
		}

		matrix.popPose();
	}

protected void renderItemStack(GlassItemFrame itemFrame, PoseStack matrix, MultiBufferSource buff, int light, ItemStack stack) {
		if(!stack.isEmpty()) {
			matrix.pushPose();
			MapItemSavedData mapdata = MapItem.getSavedData(stack, itemFrame.level());

			if(itemFrame.isOnSign()) {
				SignAttachment attach = itemFrame.getSignAttachment();

				Direction ourDirection = itemFrame.getDirection().getOpposite();
				int signRotation = itemFrame.getOnSignRotation();

				int ourRotation = SIGN_DIRECTIONS.indexOf(ourDirection) * 4;
				int rotation = signRotation - ourRotation;
				float angle = -rotation * 22.5F;
				float scale = 0.32F;

				switch(attach) {
					case STANDING_BEHIND -> angle += 180F;
					case WALL_SIGN -> {
						angle = 0;
						matrix.translate(0.0, -0.3, 0.44);
					}
					case HANGING_FROM_WALL -> {
						angle = 0;
						matrix.translate(0.0, -0.52, -0.02);
					}
				}

				matrix.translate(0, 0.35, 0.98);
				matrix.scale(scale, scale, scale);
				matrix.mulPose(Axis.YP.rotationDegrees(angle));

				switch(attach) {
					case HANGING_IN_FRONT -> matrix.translate(0.0, -0.52 / scale, -0.075);
					case HANGING_BEHIND -> matrix.translate(0.0, -0.52 / scale, 0.3);
				}

				matrix.translate(0, 0, -0.5);
				matrix.translate(0, 0, -0.085);
			}

			int rotation = mapdata != null ? itemFrame.getRotation() % 4 * 2 : itemFrame.getRotation();
			matrix.mulPose(Axis.ZP.rotationDegrees((float) rotation * 360.0F / 8.0F));

			if(!NeoForge.EVENT_BUS.post(new RenderItemInFrameEvent(itemFrame, defaultRenderer, matrix, buff, light)).isCanceled()) {
				if(mapdata != null) {
					matrix.mulPose(Axis.ZP.rotationDegrees(180.0F));
					matrix.scale(0.0078125F, 0.0078125F, 0.0078125F);
					matrix.translate(-64.0F, -64.0F, 62.5F); // <- Use 62.5 instead of 64 to prevent z-fighting

					MapId mapID = stack.get(DataComponents.MAP_ID);
					this.mc.gameRenderer.getMapRenderer().render(matrix, buff, mapID, mapdata, true, light);
				} else {
					float s = (float) GlassItemFrameModule.itemRenderScale;
					if(stack.getItem() instanceof BannerItem bannerItem) {
						banner.fromItem(stack, bannerItem.getColor());
						BannerPatternLayers patterns = banner.getPatterns();

						matrix.pushPose();
						matrix.translate(0.0001F, -0.5001F, 0.55F);
						matrix.scale(0.799999F, 0.399999F, 0.5F);
						BannerRenderer.renderPatterns(matrix, buff, light, OverlayTexture.NO_OVERLAY, bannerModel, ModelBakery.BANNER_BASE, true, bannerItem.getColor(), patterns);
						matrix.popPose();
					} else {
						if(stack.getItem() instanceof ShieldItem) {
							s *= 2.66666667F;
							matrix.translate(-0.25F, 0F, 0.5F);
							matrix.scale(s, s, s);
						} else {
							matrix.translate(0F, 0F, 0.475F);
							matrix.scale(s, s, s);
						}
						matrix.scale(0.5F, 0.5F, 0.5F);
						this.itemRenderer.renderStatic(stack, ItemDisplayContext.FIXED, light, OverlayTexture.NO_OVERLAY, matrix, buff, mc.level, 0);
					}
				}
			}

			matrix.popPose();
		}
	}

@Override
	public void render(AbstractPickarang<?> entity, float yaw, float partialTicks, @NotNull PoseStack matrix, @NotNull MultiBufferSource buffer, int light) {
