		stack.mulPose(Axis.XP.rotationDegrees((Mth.rotLerp(partialTicks, jellyfish.xRotO, jellyfish.getXRot()) + 90.0F) % 360.0F));
		stack.translate(0.0F, -translateY, 0.0F);
	}

