private static void renderBlockOverlays(GuiGraphics graphics, DeltaTracker delta)
	{
		Player player = ClientUtils.mc().player;
		if(player==null||ClientUtils.mc().hitResult==null)
			return;
		int scaledWidth = ClientUtils.mc().getWindow().getGuiScaledWidth();
		int scaledHeight = ClientUtils.mc().getWindow().getGuiScaledHeight();

		ItemStack held = player.getItemInHand(InteractionHand.MAIN_HAND);
		boolean hammer = !held.isEmpty()&&Utils.isHammer(held);
		HitResult mop = ClientUtils.mc().hitResult;
		if(mop instanceof EntityHitResult)
		{
			Entity entity = ((EntityHitResult)mop).getEntity();
			if(entity instanceof ItemFrame)
				BlockOverlayUtils.renderOreveinMapOverlays(graphics, (ItemFrame)entity, mop, scaledWidth, scaledHeight);
			else if(entity instanceof IEMinecartEntity<?> ieMinecart&&ieMinecart.getContainedBlockEntity() instanceof IBlockOverlayText overlayText)
			{
				Component[] text = overlayText.getOverlayText(null, player, mop, false);
				BlockOverlayUtils.drawBlockOverlayText(graphics, text, scaledWidth, scaledHeight);
			}
		}
		else if(mop instanceof BlockHitResult bhr)
		{
			BlockPos pos = bhr.getBlockPos();
			Direction face = bhr.getDirection();
			BlockState blockState = player.level().getBlockState(pos);
			BlockEntity tileEntity = player.level().getBlockEntity(pos);
			if(tileEntity instanceof IBlockOverlayText overlayBlock)
			{
				Component[] text = overlayBlock.getOverlayText(blockState, player, mop, hammer);
				BlockOverlayUtils.drawBlockOverlayText(graphics, text, scaledWidth, scaledHeight);
			}
			else if(blockState.getBlock() instanceof IBlockOverlayText overlayBlock)
			{
				Component[] text = overlayBlock.getOverlayText(blockState, player, mop, hammer);
				BlockOverlayUtils.drawBlockOverlayText(graphics, text, scaledWidth, scaledHeight);
			}
			else if(!(tileEntity instanceof IMultiblockBE<?> multiblock)||!renderMultiblockOverlay(
					graphics, multiblock, bhr, hammer, scaledWidth, scaledHeight
			))
			{
				List<ItemFrame> list = player.level().getEntitiesOfClass(ItemFrame.class,
						new AABB(pos.relative(face)), entity -> entity!=null&&entity.getDirection()==face);
				if(list.size()==1)
					BlockOverlayUtils.renderOreveinMapOverlays(graphics, list.get(0), mop, scaledWidth, scaledHeight);
			}
		}
	}

public static void drawCircularRotationArrows(MultiBufferSource buffer, PoseStack transform, float rotation, boolean flip, boolean halfCircle)
	{
		transform.pushPose();
		transform.translate(0, 0.502, 0);
		Vec2[] rotationArrowCoords;
		Vec2[] rotationArrowQuads;
		if(halfCircle)
		{
			rotationArrowCoords = halfRotationArrowCoords;
			rotationArrowQuads = halfRotationArrowQuads;
		}
		else
		{
			rotationArrowCoords = quarterRotationArrowCoords;
			rotationArrowQuads = quarterRotationArrowQuads;
		}

		int[] vertexOrder;
		if(flip)
		{
			transform.mulPose(new Quaternionf().rotateXYZ(0, -rotation, 0));
			transform.scale(1, 1, -1);
			vertexOrder = new int[]{2, 3, 1, 0};
		}
		else
		{
			transform.mulPose(new Quaternionf().rotateXYZ(0, rotation, 0));
			vertexOrder = new int[]{0, 1, 3, 2};
		}
		transform.pushPose();
		VertexConsumer builder = buffer.getBuffer(IERenderTypes.LINES);
		for(int arrowId = 0; arrowId < 2; ++arrowId)
		{
			Matrix4f mat = transform.last().pose();
			for(int i = 0; i < rotationArrowCoords.length; i++)
			{
				Vec2 here = rotationArrowCoords[i];
				Vec2 next = rotationArrowCoords[(i+1)%rotationArrowCoords.length];
				Vec2 diff = new Vec2(next.x-here.x, next.y-here.y).normalized();
				for(Vec2 v : ImmutableList.of(here, next))
					builder.addVertex(mat, v.x, 0, v.y)
							.setColor(0, 0, 0, 0.4F)
							.setNormal(transform.last(), diff.x, 0, diff.y);
			}
			transform.mulPose(new Quaternionf().rotateXYZ(0, Mth.PI, 0));
		}
		transform.popPose();
		transform.pushPose();
		builder = buffer.getBuffer(IERenderTypes.TRANSLUCENT_POSITION_COLOR);
		for(int arrowId = 0; arrowId < 2; ++arrowId)
		{
			Matrix4f mat = transform.last().pose();
			for(int i = 0; i+3 < rotationArrowQuads.length; i += 2)
				for(int offset : vertexOrder)
				{
					Vec2 p = rotationArrowQuads[i+offset];
					builder.addVertex(mat, p.x, 0, p.y)
							.setColor(Lib.COLOUR_F_ImmersiveOrange[0], Lib.COLOUR_F_ImmersiveOrange[1], Lib.COLOUR_F_ImmersiveOrange[2], 0.4F);
				}
			transform.mulPose(new Quaternionf().rotateXYZ(0, Mth.PI, 0));
		}
		transform.popPose();
		transform.popPose();
	}

public static void drawBlockOverlayArrow(Pose transform, MultiBufferSource buffers, Vec3 directionVec,
											 Direction side, AABB targetedBB)
	{
		Vec3[] translatedPositions = new Vec3[arrowCoords.length];
		Matrix4 mat = new Matrix4();
		Vec3 defaultDir = side.getAxis()==Axis.Y?new Vec3(0, 0, 1): new Vec3(0, 1, 0);
		directionVec = directionVec.normalize();
		double angle = Math.acos(defaultDir.dot(directionVec));
		Vec3 axis = defaultDir.cross(directionVec);
		mat.rotate(angle, axis.x, axis.y, axis.z);
		if(side.getAxis()==Axis.Z)
			mat.rotate(Math.PI/2, 1, 0, 0).rotate(Math.PI, 0, 1, 0);
		else if(side.getAxis()==Axis.X)
			mat.rotate(Math.PI/2, 0, 0, 1).rotate(Math.PI/2, 0, 1, 0);
		for(int i = 0; i < translatedPositions.length; i++)
		{
			Vec3 vec = mat.apply(new Vec3(arrowCoords[i][0], 0, arrowCoords[i][1])).add(.5, .5, .5);
			if(targetedBB!=null)
				vec = new Vec3(side==Direction.WEST?targetedBB.minX-.002: side==Direction.EAST?targetedBB.maxX+.002: vec.x, side==Direction.DOWN?targetedBB.minY-.002: side==Direction.UP?targetedBB.maxY+.002: vec.y, side==Direction.NORTH?targetedBB.minZ-.002: side==Direction.SOUTH?targetedBB.maxZ+.002: vec.z);
			translatedPositions[i] = vec;
		}

		VertexConsumer triBuilder = buffers.getBuffer(IERenderTypes.TRANSLUCENT_TRIANGLES);
		Vec3 center = translatedPositions[0];
		for(int i = 2; i < translatedPositions.length; i++)
		{
			Vec3 point = translatedPositions[i];
			Vec3 prevPoint = translatedPositions[i-1];
			for(Vec3 p : new Vec3[]{center, prevPoint, point})
				triBuilder.addVertex(transform.pose(), (float)p.x, (float)p.y, (float)p.z)
						.setColor(Lib.COLOUR_F_ImmersiveOrange[0], Lib.COLOUR_F_ImmersiveOrange[1], Lib.COLOUR_F_ImmersiveOrange[2], 0.4F);
		}
		VertexConsumer lineBuilder = buffers.getBuffer(IERenderTypes.LINES);
		for(int i = 0; i < translatedPositions.length; i++)
		{
			Vec3 point = translatedPositions[i];
			Vec3 next = translatedPositions[(i+1)%translatedPositions.length];
			Vec3 diff = next.subtract(point).normalize();
			for(Vec3 p : ImmutableList.of(point, next))
				lineBuilder.addVertex(transform.pose(), (float)p.x, (float)p.y, (float)p.z)
						.setColor(0, 0, 0, 0.4F)
						.setNormal(transform, (float)diff.x, (float)diff.y, (float)diff.z);
		}
	}

@SubscribeEvent
	public void onRenderItemFrame(RenderItemInFrameEvent event)
	{
		if(event.getItemStack().getItem() instanceof EngineersBlueprintItem)
		{
			double playerDistanceSq = ClientUtils.mc().player.distanceToSqr(event.getItemFrameEntity());

			if(playerDistanceSq < 1000)
			{
				List<RecipeHolder<BlueprintCraftingRecipe>> recipes = BlueprintCraftingRecipe.findRecipes(
						event.getItemFrameEntity().level(), IEApiDataComponents.getBlueprintType(event.getItemStack())
				);
				if(!recipes.isEmpty())
				{
					int i = event.getItemFrameEntity().getRotation();
					BlueprintCraftingRecipe recipe = recipes.get(i%recipes.size()).value();
					BlueprintLines blueprint = recipe==null?null: BlueprintRenderer.getBlueprintDrawable(recipe, event.getItemFrameEntity().getCommandSenderWorld());
					if(blueprint!=null)
					{
						PoseStack transform = event.getPoseStack();
						transform.pushPose();
						MultiBufferSource buffer = event.getMultiBufferSource();
						transform.mulPose(new Quaternionf().rotateXYZ(0, 0, -i*Mth.PI/4));
						transform.translate(-.5, .5, -.001);
						VertexConsumer builder = buffer.getBuffer(RenderType.entityCutout(rl("textures/models/blueprint_frame.png")));
						GuiHelper.drawTexturedColoredRect(builder, transform, .125f, -.875f, .75f, .75f, 1, 1, 1, 1, 1, 0, 1, 0);
						transform.translate(.796875, -.25, -.002);
						float scale = .0375f/(blueprint.getTextureScale()/16f);
						transform.scale(-scale, -scale, scale);

						blueprint.draw(transform, buffer, event.getPackedLight());

						transform.popPose();
						event.setCanceled(true);
					}
				}
			}
		}
	}

@SubscribeEvent
	public void onRenderOverlayPre(RenderGuiLayerEvent.Pre event)
	{
		if(event.getName().equals(VanillaGuiLayers.SUBTITLE_OVERLAY))
			ItemOverlayUtils.handleTooltipOffset(event.getGuiGraphics(), true);

		// early exit if not handling zooming
		if(!event.getName().equals(VanillaGuiLayers.CROSSHAIR)||!ZoomHandler.isZooming)
			return;

		// check for a zoom tool and get its step array
		Player player = ClientUtils.mc().player;
		float[] zoomSteps = Arrays.stream(InteractionHand.values())
				.map(player::getItemInHand)
				.mapMulti((BiConsumer<ItemStack, Consumer<float[]>>)(itemStack, consumer) -> {
					if(itemStack.getItem() instanceof IZoomTool zoomTool&&zoomTool.canZoom(itemStack, player))
						consumer.accept(zoomTool.getZoomSteps(itemStack, player));
				}).findFirst().orElse(null);

		if(zoomSteps==null||zoomSteps.length <= 1)
			return;

		// cancel default crosshair
		event.setCanceled(true);

		GuiGraphics graphics = event.getGuiGraphics();
		PoseStack transform = graphics.pose();
		transform.pushPose();
		int width = ClientUtils.mc().getWindow().getGuiScaledWidth();
		int height = ClientUtils.mc().getWindow().getGuiScaledHeight();
		int resMin = Math.min(width, height);
		float offsetX = Math.round((width-resMin)/2f);
		float offsetY = Math.round((height-resMin)/2f);

		if(resMin==width)
		{
			graphics.fill(0, 0, width, (int)offsetY+1, 0xff000000);
			graphics.fill(0, (int)offsetY+resMin, width, (int)(offsetY+resMin+offsetY+1), 0xff000000);
		}
		else
		{
			graphics.fill(0, 0, (int)offsetX+1, height, 0xff000000);
			graphics.fill((int)offsetX+resMin, 0, (int)(offsetX+resMin+offsetX+1), height, 0xff000000);
		}
		transform.translate(offsetX, offsetY, 0);

		RenderSystem.enableBlend();
		graphics.blitSprite(ieLoc("hud/scope"), 0, 0, resMin, resMin);
		RenderSystem.disableBlend();

		// draw gauge on the right side
		transform.translate(218/256f*resMin, 64/256f*resMin, 0);
		graphics.blitSprite(ieLoc("hud/gauge_vertical"), 0, 0, Math.round(24/256f*resMin), Math.round(128/256f*resMin));

		float stepLength = 118/(float)zoomSteps.length;
		float stepOffset = (stepLength-7)/2f;
		// move inside the gauge
		RenderSystem.enableBlend();
		transform.translate(5/256f*resMin, (5+stepOffset)/256f*resMin, 0);

		// draw markers for the possible steps
		int curStep = -1;
		float dist = 0;
		int innerWidth = Math.round(14/256f*resMin);
		int innerHeight = Math.round(7/256f*resMin);

		for(int i = 0; i < zoomSteps.length; i++)
		{
			graphics.blitSprite(ieLoc("hud/gauge_vertical_step"), 0, 0, innerWidth, innerHeight);
			transform.translate(0, stepLength/256*resMin, 0);
			if(curStep==-1||Math.abs(zoomSteps[i]-ZoomHandler.fovZoom) < dist)
			{
				curStep = i;
				dist = Math.abs(zoomSteps[i]-ZoomHandler.fovZoom);
			}
		}
		transform.translate(0, -118/256f*resMin, 0);

		// draw the pointer and text for current level
		transform.translate(0, curStep*stepLength/256*resMin, 0);
		graphics.blitSprite(ieLoc("hud/gauge_vertical_pointer"), 0, 0, innerWidth, innerHeight);
		transform.translate(16/256f*resMin, 1/256f*resMin, 0);
		graphics.drawString(ClientUtils.font(), (1/zoomSteps[curStep])+"x", 0, 0, 0xffffff, false);
		RenderSystem.disableBlend();
		transform.popPose();
	}

@SubscribeEvent()
	public void renderAdditionalBlockBounds(RenderHighlightEvent.Block event)
	{
		if(event.getTarget().getType()==Type.BLOCK&&event.getCamera().getEntity() instanceof LivingEntity living)
		{
			PoseStack transform = event.getPoseStack();
			MultiBufferSource buffer = event.getMultiBufferSource();
			BlockHitResult rtr = event.getTarget();
			BlockPos pos = rtr.getBlockPos();
			Level world = living.level();
			BlockState targetBlock = world.getBlockState(rtr.getBlockPos());
			Vec3 renderView = event.getCamera().getPosition();
			transform.pushPose();
			transform.translate(-renderView.x, -renderView.y, -renderView.z);
			transform.translate(pos.getX(), pos.getY(), pos.getZ());
			BlockEntity tile = living.level().getBlockEntity(rtr.getBlockPos());
			ItemStack stack = living.getItemInHand(InteractionHand.MAIN_HAND);

			if(tile instanceof TurntableBlockEntity turntableTile&&Utils.isHammer(stack))
			{
				Direction side = rtr.getDirection();
				Direction facing = turntableTile.getFacing();
				if(side.getAxis()!=facing.getAxis())
				{
					transform.pushPose();
					transform.translate(0.5, 0.5, 0.5);
					transform.pushTransformation(ClientUtils.toModelRotation(side).getRotation());
					transform.mulPose(new Quaternionf().rotateXYZ(-Mth.HALF_PI, 0, 0));
					Rotation rotation = turntableTile.getRotationFromSide(side);
					boolean cw180 = rotation==Rotation.CLOCKWISE_180;
					double angle;
					if(cw180)
						angle = living.tickCount%40/20d;
					else
						angle = living.tickCount%80/40d;
					double stepDistance = (cw180?2: 4)*Math.PI;
					angle = -(angle-Math.sin(angle*stepDistance)/stepDistance)*Math.PI;
					BlockOverlayUtils.drawCircularRotationArrows(buffer, transform, (float)angle, rotation==Rotation.COUNTERCLOCKWISE_90, cw180);
					transform.popPose();
					transform.popPose();
				}
			}

			if(!stack.isEmpty()&&ConveyorHandler.isConveyorBlock(Block.byItem(stack.getItem()))&&rtr.getDirection().getAxis()==Axis.Y)
			{
				Direction side = rtr.getDirection();
				VoxelShape shape = world.getBlockState(pos).getBlockSupportShape(world, pos);
				AABB targetedBB = null;
				if(!shape.isEmpty())
					targetedBB = shape.bounds();
				BlockOverlayUtils.drawQuadrantX(transform, buffer, side, targetedBB, 0.002f);

				float xFromMid = side.getAxis()==Axis.X?0: (float)rtr.getLocation().x-pos.getX()-.5f;
				float yFromMid = side.getAxis()==Axis.Y?0: (float)rtr.getLocation().y-pos.getY()-.5f;
				float zFromMid = side.getAxis()==Axis.Z?0: (float)rtr.getLocation().z-pos.getZ()-.5f;
				float max = Math.max(Math.abs(yFromMid), Math.max(Math.abs(xFromMid), Math.abs(zFromMid)));
				Vec3 dir = new Vec3(max==Math.abs(xFromMid)?Math.signum(xFromMid): 0, max==Math.abs(yFromMid)?Math.signum(yFromMid): 0, max==Math.abs(zFromMid)?Math.signum(zFromMid): 0);
				BlockOverlayUtils.drawBlockOverlayArrow(transform.last(), buffer, dir, side, targetedBB);
			}

			if(targetBlock.getBlock() instanceof CatwalkBlock&&Utils.isHammer(stack)&&rtr.getDirection()==Direction.UP&&living.isShiftKeyDown())
			{
				AABB targetedBB = new AABB(0, 0, 0, 1, .125, 1);
				BlockOverlayUtils.drawQuadrantX(transform, buffer, Direction.UP, targetedBB, 0.002f);
			}


			transform.popPose();
			// fix lines overlaying on translucent blocks
			if(targetBlock.getBlock() instanceof WindowBlock)
			{
				((WorldRendererAccess)event.getLevelRenderer()).callRenderHitOutline(
						transform, buffer.getBuffer(IERenderTypes.LINES_NONTRANSLUCENT),
						living, renderView.x, renderView.y, renderView.z,
						pos, targetBlock
				);
				event.setCanceled(true);
			}

			if(stack.getItem() instanceof DrillItem drillItem&&drillItem.isEffective(stack, targetBlock))
			{
				ItemStack head = drillItem.getHead(stack);
				if(!head.isEmpty()&&living instanceof Player player&&!living.isShiftKeyDown()&&!DrillItem.isSingleBlockMode(stack))
				{
					ImmutableList<BlockPos> potentialBlocks = ((IDrillHead)head.getItem()).getExtraBlocksDug(
							head, world, player, event.getTarget()
					);
					List<BlockPos> breakingBlocks = new ArrayList<>();
					for(BlockPos candidate : potentialBlocks)
					{
						BlockState targetState = world.getBlockState(candidate);
						if(drillItem.canBreakExtraBlock(world, candidate, targetState, player, stack, head))
							breakingBlocks.add(candidate);
					}
					BlockOverlayUtils.drawAdditionalBlockbreak(event, player, breakingBlocks);
				}
			}
		}
	}

@SubscribeEvent()
	public void onRenderLivingPre(RenderLivingEvent.Pre<LivingEntity, ?> event)
	{
		if(event.getEntity().getPersistentData().contains("headshot"))
			enableHead(event.getRenderer(), false);
		if(event.getEntity() instanceof Player player&&player.isCrouching()&&player.getItemBySlot(EquipmentSlot.CHEST).getItem() instanceof CrateItem crateItem)
			if(CrateItem.incognitoPlayers.contains(player.getId()))
			{
				ClientUtils.mc().getEntityRenderDispatcher().setRenderShadow(false);
				event.setCanceled(true);
				PoseStack pose = event.getPoseStack();
				pose.pushPose();

				var partialTick = event.getPartialTick();
				double posX = Mth.lerp(partialTick, player.xOld, player.getX());
				double posZ = Mth.lerp(partialTick, player.zOld, player.getZ());

				@SuppressWarnings("unchecked")
				Vec3 crouchOffset = event.getRenderer().getRenderOffset(player, partialTick);
				double x = Math.floor(posX)-posX;
				double z = Math.floor(posZ)-posZ;
				pose.translate(x, -crouchOffset.y, z);
				ClientUtils.mc().getBlockRenderer().renderSingleBlock(
						crateItem.getBlock().defaultBlockState(),
						pose,
						event.getMultiBufferSource(),
						event.getPackedLight(),
						OverlayTexture.NO_OVERLAY,
						ModelData.EMPTY,
						RenderType.solid()
				);
				pose.popPose();
			}
			else
				enableUpperBody(event.getRenderer(), false);
	}

@SubscribeEvent()
	public void onRenderLivingPost(RenderLivingEvent.Post<LivingEntity, ?> event)
	{
		if(event.getEntity().getPersistentData().contains("headshot"))
			enableHead(event.getRenderer(), true);
		if(event.getEntity() instanceof Player player&&player.isCrouching()&&player.getItemBySlot(EquipmentSlot.CHEST).getItem() instanceof CrateItem)
		{
			ClientUtils.mc().getEntityRenderDispatcher().setRenderShadow(true);
			enableUpperBody(event.getRenderer(), true);
		}
	}

public static void renderItemOverlays(GuiGraphics graphics, DeltaTracker delta)
	{
		Player player = ClientUtils.mc().player;
		if(player==null)
			return;
		int scaledWidth = ClientUtils.mc().getWindow().getGuiScaledWidth();
		int scaledHeight = ClientUtils.mc().getWindow().getGuiScaledHeight();

		for(InteractionHand hand : InteractionHand.values())
			if(!player.getItemInHand(hand).isEmpty())
			{
				ItemStack equipped = player.getItemInHand(hand);
				if(equipped.is(Tools.VOLTMETER.asItem())||equipped.getItem() instanceof IWireCoil)
					renderWireCoilOverlay(graphics, equipped, player, scaledWidth, scaledHeight);
				else if(equipped.getItem()==Misc.FLUORESCENT_TUBE.get())
					renderFluorescentTubeOverlay(graphics, equipped, scaledWidth, scaledHeight);
				else if(equipped.getItem() instanceof RevolverItem||equipped.getItem() instanceof SpeedloaderItem)
					renderRevolverOverlay(graphics, scaledWidth, scaledHeight, player, hand, equipped);
				else if(equipped.getItem() instanceof RailgunItem)
					renderRailgunOverlay(graphics, scaledWidth, scaledHeight, player, hand, equipped);
				else if(equipped.getItem() instanceof DrillItem)
					renderDrillOverlay(graphics, scaledWidth, scaledHeight, player, hand, equipped);
				else if(equipped.getItem() instanceof BuzzsawItem)
					renderBuzzsawOverlay(graphics, scaledWidth, scaledHeight, player, hand, equipped);
				else if(equipped.getItem() instanceof ChemthrowerItem)
					renderChemthrowerOverlay(graphics, scaledWidth, scaledHeight, player, hand, equipped);
				else if(equipped.getItem() instanceof IEShieldItem)
					renderShieldOverlay(graphics, scaledWidth, scaledHeight, player, hand, equipped);
				if(equipped.getItem()==Tools.VOLTMETER.get())
					renderVoltmeterOverlay(graphics, player, scaledWidth, scaledHeight);
			}
	}

public static void renderRailgunOverlay(GuiGraphics graphics, int scaledWidth, int scaledHeight,
											Player player, InteractionHand hand, ItemStack equipped)
	{
		int duration = 72000-(player.isUsingItem()&&player.getUsedItemHand()==hand?player.getUseItemRemainingTicks(): 0);
		int chargeTime = RailgunItem.getChargeTime(equipped);
		int chargeLevel = duration < 72000?Math.min(99, (int)(duration/(float)chargeTime*100)): 0;
		float scale = 1.5f;

		boolean boundLeft = ItemUtils.getLivingHand(player, hand)==HumanoidArm.LEFT;
		int dx = boundLeft?24: (scaledWidth-24-64);
		int dy = scaledHeight-16;
		var transform = graphics.pose();
		transform.pushPose();
		transform.translate(dx, dy, 0);
		graphics.blitSprite(ieLoc("hud/railgun_base"), 0, -32, 64, 32);

		ItemStack ammo = RailgunItem.findAmmo(equipped, player);
		if(!ammo.isEmpty())
			GuiHelper.renderItemWithOverlayIntoGUI(graphics, ammo, 6, -22, player.level());

		transform.translate(30, -27.5, 0);
		transform.scale(scale, scale, 1);
		String chargeTxt = chargeLevel < 10?"0 "+chargeLevel: chargeLevel/10+" "+chargeLevel%10;
		graphics.drawString(
				ClientUtils.font(), chargeTxt, 0, 0, Lib.COLOUR_I_ImmersiveOrange, true
		);
		transform.popPose();
	}

public static void renderFluidTankOverlay(GuiGraphics graphics, int xStart, int scaledHeight,
											  Player player, InteractionHand hand, ItemStack equipped, boolean renderFluidUse,
											  BiConsumer<GuiGraphics, IFluidHandlerItem> additionalRender)
	{
		var transform = graphics.pose();
		float dx = xStart;
		float dy = scaledHeight;
		transform.pushPose();
		transform.translate(dx, dy, 0);
		graphics.blitSprite(ieLoc("hud/gauge_full_empty"), -24, -68, 31, 62);

		transform.translate(-23, -37, 0);
		IFluidHandlerItem handler = equipped.getCapability(FluidHandler.ITEM);
		if(handler!=null)
		{
			int capacity = -1;
			if(handler.getTanks() > 0)
				capacity = handler.getTankCapacity(0);
			if(capacity > 0)
			{
				FluidStack fuel = handler.getFluidInTank(0);
				int amount = fuel.getAmount();
				if(renderFluidUse&&player.isUsingItem()&&player.getUsedItemHand()==hand)
				{
					int use = player.getTicksUsingItem();
					amount -= use*IEServerConfig.TOOLS.chemthrower_consumption.get();
				}
				float cap = (float)capacity;
				float angle = 83-(166*amount/cap);
				transform.pushPose();
				transform.mulPose(new Quaternionf().rotateZ(angle*Mth.DEG_TO_RAD));
				graphics.blitSprite(ieLoc("hud/gauge_pointer"), 6, -2, 24, 4);
				transform.popPose();
				transform.translate(23, 37, 0);

				additionalRender.accept(graphics, handler);
			}
		}
		transform.popPose();
	}

private static void renderVoltmeterOverlay(GuiGraphics graphics, Player player, int scaledWidth, int scaledHeight)
	{
		HitResult rrt = ClientUtils.mc().hitResult;
		Either<BlockPos, Integer> pos = null;
		if(rrt instanceof BlockHitResult mop)
			pos = Either.left(mop.getBlockPos());
		else if(rrt instanceof EntityHitResult ehr)
			pos = Either.right(ehr.getEntity().getId());

		if(pos==null)
			return;

		ArrayList<Component> text = new ArrayList<>();

		boolean matches = VoltmeterItem.lastEnergyUpdate.pos().equals(pos);
		long sinceLast = player.level().getGameTime()-VoltmeterItem.lastEnergyUpdate.measuredInTick();
		if(!matches||sinceLast > 20)
			PacketDistributor.sendToServer(new MessageRequestEnergyUpdate(pos));

		if(VoltmeterItem.lastEnergyUpdate.isValid()&&matches)
		{
			int maxStorage = VoltmeterItem.lastEnergyUpdate.capacity();
			int storage = VoltmeterItem.lastEnergyUpdate.stored();
			String storageText = Utils.toScientificNotation(storage, "0##", 100000);
			String capacityText = Utils.toScientificNotation(maxStorage, "0##", 100000);
			text.add(Component.translatable(Lib.DESC_INFO+"energyStored", storageText+" / "+capacityText));
		}

		if(rrt instanceof BlockHitResult mop)
		{
			matches = VoltmeterItem.lastRedstoneUpdate.pos().equals(mop.getBlockPos());
			sinceLast = player.level().getGameTime()-VoltmeterItem.lastRedstoneUpdate.measuredInTick();
			if(!matches||sinceLast > 20)
				PacketDistributor.sendToServer(new MessageRequestRedstoneUpdate(mop.getBlockPos()));

			if(VoltmeterItem.lastRedstoneUpdate.isSignalSource()&&matches)
				VoltmeterItem.lastRedstoneUpdate.rsLevels().consume(
						aByte -> text.add(Component.translatable(Lib.DESC_INFO+"redstone_level", String.valueOf(aByte))),
						pairs -> {
							if(pairs.length > 0)
							{
								text.add(Component.translatable(Lib.DESC_INFO+"redstone_level", ""));
								for(Pair<DyeColor, Byte> p : pairs)
								{
									Component c = Component.translatable(Lib.DESC_INFO+"redstone_level_on_channel",
											p.getSecond(),
											getRedstoneColorComponent(p.getFirst())
									);
									// if the value is less than 10, we want a space before it which has the same width as a digit
									text.add(p.getSecond() < 10?new SpacerComponent("0").append(c): c);
								}
							}
						}
				);
		}

		BlockOverlayUtils.drawBlockOverlayText(graphics, text, scaledWidth, scaledHeight);
	}

private static void renderMineralVeinDebug(RenderLevelStageEvent event)
	{
		// !isProduction: Safety feature to make sure this doesn't run even if the enable flag is left on by accident
		boolean show = ENABLE_VEIN_DEBUG&&!FMLLoader.isProduction();
		if(!show)
			return;
		// Default <=> shift is sneak, use ctrl instead
		if(Minecraft.getInstance().options.keyShift.isDefault())
			show = Screen.hasControlDown();
		else
			show = Screen.hasShiftDown();
		if(!show)
			return;
		final Pair<PoseStack, BufferSource> context = prepare(event);
		final PoseStack transform = context.getFirst();
		ResourceKey<Level> dimension = mc().player.getCommandSenderWorld().dimension();
		List<ResourceLocation> keyList = new ArrayList<>(MineralMix.RECIPES.getRecipeNames(mc().level));
		keyList.sort(Comparator.comparing(ResourceLocation::toString));
		BlockPos feetPos = mc().player.blockPosition();
		final ColumnPos playerCol = new ColumnPos(feetPos.getX(), feetPos.getZ());
		// 24: very roughly 16 * sqrt(2)
		final long maxDistance = mc().options.renderDistance().get()*24L;
		final long maxDistanceSq = maxDistance*maxDistance;
		Multimap<ResourceKey<Level>, MineralVein> minerals;
		final var minHeight = mc().level.getMinBuildHeight();
		final var maxHeight = mc().level.getMaxBuildHeight();
		synchronized(minerals = ExcavatorHandler.getMineralVeinList())
		{
			for(MineralVein vein : minerals.get(dimension))
			{
				MineralMix mineral = vein.getMineral(mc().level);
				if(mineral==null)
					continue;
				ColumnPos pos = vein.getPos();
				final long xDiff = pos.x()-playerCol.x();
				final long zDiff = pos.z()-playerCol.z();
				long distToPlayerSq = xDiff*xDiff+zDiff*zDiff;
				if(distToPlayerSq > maxDistanceSq)
					continue;
				int iC = keyList.indexOf(vein.getMineralName());
				DyeColor color = DyeColor.values()[iC%16];
				var rgb = Utils.vec4fFromDye(color);
				transform.pushPose();
				transform.translate(pos.x(), 0, pos.z());
				VertexConsumer bufferBuilder = context.getSecond().getBuffer(IERenderTypes.CHUNK_MARKER);
				Matrix4f mat = transform.last().pose();
				bufferBuilder.addVertex(mat, 0, minHeight, 0).setColor(rgb.x, rgb.y, rgb.z, .75f).setNormal(transform.last(), 0, 1, 0);
				bufferBuilder.addVertex(mat, 0, maxHeight, 0).setColor(rgb.x, rgb.y, rgb.z, .75f).setNormal(transform.last(), 0, 1, 0);
				int radius = vein.getRadius();
				List<Vector3f> positions = new ArrayList<>();
				for(int p = 0; p < 12; p++)
				{
					final float angle = 360.0f/12*p;
					final double x1 = radius*Math.cos(angle*Math.PI/180);
					final double z1 = radius*Math.sin(angle*Math.PI/180);
					positions.add(new Vector3f((float)x1, (float)(Minecraft.getInstance().player.position().y+10), (float)z1));
				}
				for(int p = 0; p < 12; p++)
				{
					Vector3f pointA = positions.get(p);
					Vector3f pointB = positions.get((p+1)%positions.size());
					Vector3f diff = new Vector3f(pointB);
					diff.sub(pointA);
					diff.normalize();
					for(Vector3f point : List.of(pointA, pointB))
						bufferBuilder.addVertex(mat, point.x(), point.y(), point.z())
								.setColor(rgb.x, rgb.y, rgb.z, .75f)
								//Not actually a normal, just the direction of the line
								.setNormal(transform.last(), diff.x(), diff.y(), diff.z());
				}
				transform.popPose();
			}
		}
		finish(context);
	}

private static void renderFailedConnections(RenderLevelStageEvent event)
	{
		final Pair<PoseStack, BufferSource> context = prepare(event);
		VertexConsumer builder = context.getSecond().getBuffer(IERenderTypes.CHUNK_MARKER);
		final PoseStack transform = context.getFirst();
		for(Entry<Connection, Pair<Collection<BlockPos>, MutableInt>> entry : FAILED_CONNECTIONS.entrySet())
		{
			Connection conn = entry.getKey();
			transform.pushPose();
			transform.translate(conn.getEndA().getX(), conn.getEndA().getY(), conn.getEndA().getZ());
			Matrix4f mat = transform.last().pose();
			int time = entry.getValue().getSecond().intValue();
			float alpha = (float)Math.min((2+Math.sin(time*Math.PI/40))/3, time/20F);
			Vec3 prev = conn.getPoint(0, conn.getEndA());
			for(int i = 0; i < Connection.RENDER_POINTS_PER_WIRE; i++)
			{
				Vec3 next = conn.getCatenaryData().getRenderPoint(i+1);
				Vec3 diff = next.subtract(prev).normalize();
				builder.addVertex(mat, (float)prev.x, (float)prev.y, (float)prev.z)
						.setColor(1, 0, 0, alpha)
						.setNormal(transform.last(), (float)diff.x, (float)diff.y, (float)diff.z);
				alpha = (float)Math.min((2+Math.sin((time+(i+1)*8)*Math.PI/40))/3, time/20F);
				builder.addVertex(mat, (float)next.x, (float)next.y, (float)next.z)
						.setColor(1, 0, 0, alpha)
						.setNormal(transform.last(), (float)diff.x, (float)diff.y, (float)diff.z);
				prev = next;
			}
			transform.popPose();
		}
		renderObstructingBlocks(context);
		finish(context);
	}

private static void renderObstructingBlocks(Pair<PoseStack, BufferSource> context)
	{
		final PoseStack transform = context.getFirst();
		TransformingVertexBuilder builder = new TransformingVertexBuilder(
				context.getSecond(), IERenderTypes.TRANSLUCENT_POSITION_COLOR
		);
		builder.defaultColor(255, 0, 0, 128);
		for(Entry<Connection, Pair<Collection<BlockPos>, MutableInt>> entry : FAILED_CONNECTIONS.entrySet())
		{
			for(BlockPos obstruction : entry.getValue().getFirst())
			{
				transform.pushPose();
				transform.translate(obstruction.getX(), obstruction.getY(), obstruction.getZ());
				final float eps = 1e-3f;
				RenderUtils.renderBox(builder, transform, -eps, -eps, -eps, 1+eps, 1+eps, 1+eps);
				transform.popPose();
			}
		}
		builder.unsetDefaultColor();
	}

public List<Pair<RenderType, Consumer<VertexConsumer>>> render(float partialTicks, PoseStack matrixStack)
	{
		float mod = (age+partialTicks)/(float)lifetime;
		int iStartMut = 0;
		int iEndMut = pointsList.length;
		if(mod >= .76)
		{
			float rem = (((mod-.7599f)%.25f)*48)/2f;
			iStartMut += Math.ceil(rem);
			iEndMut -= Math.floor(rem);
		}
		final int iStart = iStartMut;
		final int iEnd = iEndMut;
		mod = .3f+mod*mod;
		matrixStack.pushPose();
		matrixStack.translate(x, y, z);
		matrixStack.scale(mod, mod, mod);
		matrixStack.mulPose(new Quaternionf().rotateXYZ(0, Mth.PI*mod, 0));
		Matrix4f transform = matrixStack.last().pose();
		Matrix3f transformN = matrixStack.last().normal();
		matrixStack.popPose();

		LinePointProcessor putLinePoint = (buffer, i, color) -> {
			int correctIndex = getCyclicIndexInRange(iStart, iEnd, i);
			Vector3f vecRender = pointsList[correctIndex];
			if(i!=iStart)
			{
				Vector3f last = pointsList[getCyclicIndexInRange(iStart, iEnd, i-1)];
				renderLinePoint(transformN, transform, vecRender, last, color, buffer, false);
			}
			if(i!=iEnd)
			{
				Vector3f next = pointsList[getCyclicIndexInRange(iStart, iEnd, i+1)];
				renderLinePoint(transformN, transform, next, vecRender, color, buffer, true);
			}
		};

		List<Pair<RenderType, Consumer<VertexConsumer>>> ret = new ArrayList<>();
		ret.add(Pair.of(IERenderTypes.getParticleLines(4f), buffer -> {
			for(int i = iStart; i <= iEnd; i++)
				putLinePoint.draw(buffer, i, colourOut);
		}));

		ret.add(Pair.of(IERenderTypes.getParticleLines(1f), buffer -> {
			for(int i = iStart; i <= iEnd; i++)
				putLinePoint.draw(buffer, i, colourIn);
		}));

		ret.add(Pair.of(IERenderTypes.POINTS, buffer -> {
			for(int i = iStart; i < iEnd; i++)
				drawPoint(buffer, transform, pointsList[i], 8, colourOut);
		}));

		ret.add(Pair.of(IERenderTypes.POINTS, buffer -> {
			for(int i = iEnd-1; i >= iStart; i--)
				drawPoint(buffer, transform, pointsList[i], 2, colourIn);
		}));
		return ret;
	}

@Override
	public void render(GuiGraphics graphics, ManualScreen gui, int x, int y, int mouseX, int mouseY)
	{
		if(multiblock.getStructure(level)!=null)
		{
			PoseStack transform = graphics.pose();
			PoseStack.Pose lastEntryBeforeTry = transform.last();
			try
			{
				long currentTime = System.currentTimeMillis();
				if(lastStep < 0)
					lastStep = currentTime;
				else if(canTick&&currentTime-lastStep > 500)
				{
					renderInfo.step();
					lastStep = currentTime;
				}

				int structureLength = renderInfo.structureLength;
				int structureWidth = renderInfo.structureWidth;
				int structureHeight = renderInfo.structureHeight;

				transform.pushPose();

				final BlockRenderDispatcher blockRender = Minecraft.getInstance().getBlockRenderer();

				transform.translate(transX, transY, Math.max(structureHeight, Math.max(structureWidth, structureLength)));
				transform.scale(scale, -scale, 1);
				transform.pushTransformation(additionalTransform);
				transform.mulPose(new Quaternionf().rotateXYZ(0, Mth.HALF_PI, 0));

				transform.translate(structureLength/-2f, structureHeight/-2f, structureWidth/-2f);

				if(showCompleted&&renderProperties.canRenderFormedStructure())
				{
					transform.pushPose();
					renderProperties.renderFormedStructure(transform, graphics.bufferSource());
					transform.popPose();
				}
				else
				{
					TransformingVertexBuilder translucentFullbright = new TransformingVertexBuilder(
							graphics.bufferSource(), IERenderTypes.TRANSLUCENT_FULLBRIGHT
					);
					for(int h = 0; h < structureHeight; h++)
						for(int l = 0; l < structureLength; l++)
							for(int w = 0; w < structureWidth; w++)
							{
								BlockPos pos = new BlockPos(l, h, w);
								BlockState state = structureWorld.getBlockState(pos);
								if(!state.isAir())
								{
									transform.pushPose();
									transform.translate(l, h, w);
									int overlay;
									if(pos.equals(multiblock.getTriggerOffset()))
										overlay = OverlayTexture.pack(0, true);
									else
										overlay = OverlayTexture.NO_OVERLAY;
									translucentFullbright.setDefaultOverlay(overlay);
									ModelData modelData = ModelData.EMPTY;
									BlockEntity te = structureWorld.getBlockEntity(pos);
									if(te!=null)
										modelData = te.getModelData();
									final BakedModel model = blockRender.getBlockModel(state);
									modelData = model.getModelData(structureWorld, pos, state, modelData);
									blockRender.getModelRenderer().tesselateBlock(
											structureWorld, model, state, pos, transform,
											translucentFullbright, false, structureWorld.random, state.getSeed(pos),
											overlay, modelData, null
									);
									transform.popPose();
								}
							}
				}
				transform.popPose();
				transform.popPose();
			} catch(Exception e)
			{
				final long now = System.currentTimeMillis();
				if(now > lastPrintedErrorTimeMs+1000)
				{
					e.printStackTrace();
					lastPrintedErrorTimeMs = now;
				}
				while(lastEntryBeforeTry!=transform.last())
					transform.popPose();
			}

			if(componentTooltip!=null)
			{
				graphics.drawString(manual.fontRenderer(), "?", 116, yOffTotal/2-4, manual.getTextColour());
				if(mouseX >= 116&&mouseX < 122&&mouseY >= yOffTotal/2-4&&mouseY < yOffTotal/2+4)
					graphics.renderTooltip(manual.fontRenderer(), Language.getInstance().getVisualOrder(
							Collections.unmodifiableList(componentTooltip)
					), mouseX, mouseY);
			}
		}
	}

