@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final State state = ctx.getState();
		float piston = 0;
		float[] shift = new float[state.processor.getQueueSize()];

		Level level = ctx.getLevel().getRawLevel();
		for(int i = 0; i < shift.length; i++)
		{
			MultiblockProcess<MetalPressRecipe, ?> process = state.processor.getQueue().get(i);
			float processMaxTicks = process.getMaxTicks(level);
			float transportTime = getTransportTime(processMaxTicks);
			float pressTime = getPressTime(processMaxTicks);
			//+partialTicks
			float fProcess = process.processTick;

			if(fProcess < transportTime)
				shift[i] = .5f*fProcess/transportTime;
			else if(fProcess < (processMaxTicks-transportTime))
				shift[i] = .5f;
			else
				shift[i] = .5f+.5f*(fProcess-(processMaxTicks-transportTime))/transportTime;
			if(!state.mold.isEmpty())
				if(fProcess >= transportTime&&fProcess < (processMaxTicks-transportTime))
				{
					if(fProcess < (transportTime+pressTime))
						piston = (fProcess-transportTime)/pressTime;
					else if(fProcess < (processMaxTicks-transportTime-pressTime))
						piston = 1;
					else
						piston = 1-(fProcess-(processMaxTicks-transportTime-pressTime))/pressTime;
				}
		}

		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);
		MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		Direction effectiveFacing = orientation.mirrored()?orientation.front().getOpposite(): orientation.front();
		rotateForFacingNoCentering(matrixStack, effectiveFacing);
		matrixStack.pushPose();
		matrixStack.translate(0, -piston*.6875f, 0);
		matrixStack.pushPose();
		matrixStack.translate(-0.5, -0.5, -0.5);
		final BlockRenderDispatcher blockRenderer = Minecraft.getInstance().getBlockRenderer();
		BakedModel pistonModel = PISTON.get();
		blockRenderer.getModelRenderer().renderModel(
				matrixStack.last(), bufferIn.getBuffer(RenderType.solid()), null, pistonModel,
				1, 1, 1,
				combinedLightIn, combinedOverlayIn, ModelData.EMPTY, RenderType.solid()
		);
		matrixStack.popPose();

		if(!state.mold.isEmpty())
		{
			matrixStack.translate(0, .34, 0);
			matrixStack.mulPose(new Quaternionf().rotateX(-Mth.HALF_PI));
			float scale = .75f;
			matrixStack.scale(scale, scale, 1);
			ClientUtils.mc().getItemRenderer().renderStatic(
					state.mold, ItemDisplayContext.FIXED,
					combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
					level, 0
			);
		}
		matrixStack.popPose();
		matrixStack.translate(-1.25, -.35, 0);
		for(int i = 0; i < shift.length; i++)
		{
			MultiblockProcess<?, ?> process = state.processor.getQueue().get(i);
			if(!(process instanceof MultiblockProcessInWorld<?> inWorld))
				continue;
			List<ItemStack> displays = inWorld.getDisplayItem(level);
			if(displays.isEmpty())
				continue;
			matrixStack.pushPose();
			matrixStack.translate(TRANSLATION_DISTANCE*shift[i], 0, 0);
			if(piston > .92)
				matrixStack.translate(0, .92-piston, 0);

			matrixStack.mulPose(new Quaternionf().rotateX(-Mth.HALF_PI));
			float scale = .625f;
			matrixStack.scale(scale, scale, 1);
			ClientUtils.mc().getItemRenderer().renderStatic(
					displays.get(0), ItemDisplayContext.FIXED,
					combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
					level, 0);
			matrixStack.popPose();
		}
		matrixStack.popPose();
	}

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final State state = ctx.getState();
		final MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		final BlockRenderDispatcher blockRenderer = Minecraft.getInstance().getBlockRenderer();

		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);

		bufferIn = BERenderUtils.mirror(orientation, matrixStack, bufferIn);
		matrixStack.pushPose();
		final Direction front = orientation.front();
		matrixStack.translate(front==Direction.SOUTH||front==Direction.WEST?-.5: .5, 0, front==Direction.SOUTH||front==Direction.EAST?.5: -.5);
		float agitator = state.animation_agitator-(!state.isActive?0: (1-partialTicks)*9f);
		matrixStack.mulPose(new Quaternionf().rotateY(agitator *Mth.DEG_TO_RAD));

		matrixStack.translate(-0.5, -0.5, -0.5);
		blockRenderer.getModelRenderer().renderModel(
				matrixStack.last(), bufferIn.getBuffer(RenderType.solid()), null, AGITATOR.get(),
				1, 1, 1,
				combinedLightIn, combinedOverlayIn, ModelData.EMPTY, RenderType.solid()
		);

		matrixStack.popPose();

		matrixStack.translate(front==Direction.SOUTH||front==Direction.WEST?-.5: .5, -.625f, front==Direction.SOUTH||front==Direction.EAST?.5: -.5);
		matrixStack.scale(.0625f, 1, .0625f);
		matrixStack.mulPose(new Quaternionf().rotateX(Mth.HALF_PI));

		for(int i = state.tank.getFluidTypes()-1; i >= 0; i--)
		{
			FluidStack fs = state.tank.fluids.get(i);
			if(fs!=null&&fs.getFluid()!=null)
			{
				float yy = fs.getAmount()/(float)state.tank.getCapacity()*1.0625f;
				matrixStack.translate(0, 0, -yy);
				float w = (i < state.tank.getFluidTypes()-1||yy >= .125)?26: 16+yy/.0125f;
				GuiHelper.drawRepeatedFluidSprite(bufferIn.getBuffer(RenderType.translucent()), matrixStack, fs,
						-w/2, -w/2, w, w);
			}
		}

		matrixStack.popPose();
	}

@Override
	public void render(ModWorkbenchBlockEntity te, float partialTicks, PoseStack transform, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		if(te.isDummy()||!te.getLevelNonnull().hasChunkAt(te.getBlockPos()))
			return;

		transform.pushPose();
		transform.translate(.5, .5, .5);

		Direction facing = te.getFacing();

		float angle = facing==Direction.NORTH?0: facing==Direction.WEST?Mth.HALF_PI: facing==Direction.EAST?-Mth.HALF_PI: Mth.PI;

		transform.mulPose(new Quaternionf().rotateY(angle));

		ItemStack stack = te.getInventory().get(0);
		boolean showIngredients = true;
		if(!stack.isEmpty())
		{
			if(stack.getItem() instanceof EngineersBlueprintItem)
			{
				double playerDistanceSq = ClientUtils.mc().player.distanceToSqr(Vec3.atCenterOf(te.getBlockPos()));
				if(playerDistanceSq < 120)
				{
					final String category = IEApiDataComponents.getBlueprintType(stack);
					if(!category.isEmpty() && !IEApiDataComponents.INVALID_BLUEPRINT.equals(category))
					{
						final ClientLevel level = ClientUtils.mc().level;
						List<RecipeHolder<BlueprintCraftingRecipe>> recipes = BlueprintCraftingRecipe.findRecipes(level, category);
						if(!recipes.isEmpty())
						{
							IVertexBufferHolder vbo = VBO_BY_BLUEPRINT.computeIfAbsent(category, this::buildVBO);
							vbo.render(BlueprintRenderer.RENDER_TYPE, combinedLightIn, combinedOverlayIn, bufferIn, transform);
						}
					}
				}
			}
			else
			{
				showIngredients = false;
				transform.pushPose();
				transform.translate(0, .5625, 0);

				transform.mulPose(new Quaternionf().rotateY(Mth.PI).rotateX(Mth.HALF_PI));
				transform.translate(-.875, 0, 0);
				transform.scale(.75f, .75f, .75f);
				ClientUtils.mc().getItemRenderer().renderStatic(stack, ItemDisplayContext.FIXED,
						combinedLightIn, combinedOverlayIn, transform, bufferIn, te.getLevel(), 0);
				transform.popPose();
			}
		}
		if(showIngredients)
		{
			for(int i = 1; i < te.getInventory().size(); i++)
			{
				double dX, dZ;
				if(i < 5)
				{
					dX = -.5+(i==2?-.0625: i==4?.03215: 0);
					dZ = i*.25-.625;
				}
				else
				{
					dX = -1.25;
					dZ = -.125+(i-5)*-.25;
				}

				stack = te.getInventory().get(i);
				if(!stack.isEmpty())
				{
					transform.pushPose();
					transform.mulPose(new Quaternionf().rotateY(Mth.PI).rotateX(Mth.HALF_PI));
					transform.translate(dX, dZ, -.515);
					transform.scale(.25f, .25f, .25f);
					{
						try
						{
							ClientUtils.mc().getItemRenderer().renderStatic(stack, ItemDisplayContext.FIXED,
									combinedLightIn, combinedOverlayIn, transform, bufferIn, te.getLevel(), 0);
						} catch(Exception e)
						{
							e.printStackTrace();
						}
					}
					transform.popPose();
				}
			}
		}
		transform.popPose();
	}

private IVertexBufferHolder buildVBO(String category)
	{
		return IVertexBufferHolder.create((builder, transform, light, overlay) -> {
			final ClientLevel level = ClientUtils.mc().level;
			List<RecipeHolder<BlueprintCraftingRecipe>> recipes = BlueprintCraftingRecipe.findRecipes(level, category);
			transform.pushPose();
			int numRecipes = Math.min(recipes.size(), 9);
			int perRow;
			if(numRecipes > 6) perRow = numRecipes-3;
			else if(numRecipes > 4) perRow = numRecipes-2;
			else if(numRecipes==1) perRow = 2;
			else if(numRecipes==2) perRow = 3;
			else perRow = numRecipes;
			transform.translate(0, .502, 0);
			transform.mulPose(new Quaternionf().rotateY(-Mth.PI/8).rotateX(-Mth.HALF_PI));
			transform.translate(0.39, numRecipes > 4?.72: .78, 0);
			float scale = numRecipes > 4?.009375f: .012f;
			transform.scale(scale, -scale, scale);
			int rendered = 0;
			for(int i = 0; i < numRecipes; i++)
			{
				BlueprintCraftingRecipe recipe = recipes.get(i%recipes.size()).value();
				BlueprintLines blueprint = recipe==null?null: BlueprintRenderer.getBlueprintDrawable(recipe, level);
				if(blueprint!=null)
				{
					double dX = rendered < perRow?(.93725/scale-perRow*16.6)+rendered*16.6: (.70375/scale-rendered%perRow*16.6);
					double dY = rendered < perRow?0: -.15625;
					transform.translate(dX, dY/scale, 0);

					//Width depends on distance
					float texScale = blueprint.textureScale/16f;
					transform.scale(1/texScale, 1/texScale, 1/texScale);
					blueprint.draw(transform, builder, light);
					transform.scale(texScale, texScale, texScale);
					transform.translate(-dX, -dY/scale, 0);
					rendered++;
				}
			}
			transform.popPose();
		});
	}

@Override
	public void render(SampleDrillBlockEntity tile, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		if(!tile.getLevelNonnull().hasChunkAt(tile.getBlockPos()))
			return;

		BlockState state = tile.getLevelNonnull().getBlockState(tile.getBlockPos());
		if(state.getBlock()!=MetalDevices.SAMPLE_DRILL.get())
			return;

		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);

		int max = IEServerConfig.MACHINES.coredrill_time.get();
		if(tile.process > 0&&tile.process < max)
		{
			float currentProcess = tile.process;
			if (tile.isRunning)
				currentProcess += partialTicks;
			matrixStack.mulPose(new Quaternionf().rotateY( (currentProcess*22.5f)%360f *Mth.DEG_TO_RAD));
			float push = tile.process/(float)max;
			if(tile.process > max/2)
				push = 1-push;
			matrixStack.translate(0, -2.8f*push, 0);
		}

		matrixStack.translate(-0.5, -0.5, -0.5);
		List<BakedQuad> quads = DRILL.getNullQuads();
		RenderUtils.renderModelTESRFast(
				quads, bufferIn.getBuffer(RenderType.solid()), matrixStack, combinedLightIn, combinedOverlayIn
		);
		matrixStack.popPose();
	}

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final IMultiblockLevel level = ctx.getLevel();
		final State state = ctx.getState();

		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		matrixStack.translate(.5, 0, .5);
		bufferIn = BERenderUtils.mirror(level.getOrientation(), matrixStack, bufferIn);


		VertexConsumer solidBuilder = bufferIn.getBuffer(RenderType.solid());

		Direction facing = level.getOrientation().front();
		float dir = facing==Direction.SOUTH?Mth.PI: facing==Direction.NORTH?0: facing==Direction.EAST?-Mth.HALF_PI: Mth.HALF_PI;
		matrixStack.mulPose(new Quaternionf().rotateY(dir));

		// Sawblade
		boolean sawblade = !state.sawblade.isEmpty();
		if(sawblade)
		{
			matrixStack.pushPose();
			matrixStack.translate(1, .125, -.5);
			float spin = state.animation_bladeRotation;
			if(state.active!=ActiveState.NOT_RUNNING)
				spin += 36f*partialTicks;
			matrixStack.mulPose(new Quaternionf().rotateZ(spin*Mth.DEG_TO_RAD));
			RenderUtils.renderModelTESRFast(
					BLADE.getNullQuads(), solidBuilder, matrixStack, combinedLightIn, combinedOverlayIn
			);
			matrixStack.popPose();
		}

		// Items
		for(SawmillProcess process : state.sawmillProcessQueue)
		{
			float relative = process.getRelativeProcessStep(level.getRawLevel());
			ItemStack rendered = process.getCurrentStack(level.getRawLevel(), sawblade);
			renderItem(rendered, relative, matrixStack, bufferIn, combinedLightIn, combinedOverlayIn, level.getRawLevel());
		}
		matrixStack.popPose();
	}

private void renderItem(
			ItemStack stack, float progress,
			PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn, Level level
	)
	{
		float xOffset = -2.5f+progress*5;
		matrixStack.pushPose();
		matrixStack.translate(xOffset, .375, 0);
		matrixStack.mulPose(new Quaternionf().rotateZ(Mth.HALF_PI));
		ClientUtils.mc().getItemRenderer().renderStatic(
				stack, ItemDisplayContext.FIXED,
				combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
				level, 0
		);
		matrixStack.popPose();
	}

@Override
	public void render(ShaderBannerBlockEntity te, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		long time = te.getLevelNonnull().getGameTime();
		matrixStack.pushPose();

		// Check which of the two blocks we are so we can calculate the orientation.
		if(te.getState().getBlock()==Cloth.SHADER_BANNER.get())
		{
			// Standing banner, we have 16 different rotations.
			int orientation = te.getState().getValue(ShaderBannerStandingBlock.ROTATION);
			matrixStack.translate(0.5F, 0.5F, 0.5F);
			float f1 = (float)(orientation*360)/16.0F;
			matrixStack.mulPose(new Quaternionf().rotateY(-f1 * Mth.DEG_TO_RAD));
			standingModel.visible = true;
		}
		else
		{
			// Must be the wall banner, attaches to the side of the block with no support pillar.
			assert te.getState().getBlock()==Cloth.SHADER_BANNER_WALL.get();

			Direction facing = te.getState().getValue(ShaderBannerWallBlock.FACING);
			float rotation = facing.toYRot();

			matrixStack.translate(0.5F, -1/6f, 0.5F);
			matrixStack.mulPose(new Quaternionf().rotateY(-rotation * Mth.DEG_TO_RAD));
			matrixStack.translate(0.0F, -0.3125F, -0.4375F);
			standingModel.visible = false;
		}

		BlockPos blockpos = te.getBlockPos();
		float f3 = (float)(blockpos.getX()*7+blockpos.getY()*9+blockpos.getZ()*13)+(float)time+partialTicks;
		clothModel.xRot = (-0.0125F+0.01F*Mth.cos(f3*(float)Math.PI*0.02F))*(float)Math.PI;
		clothModel.y = -32.0F;
		ResourceLocation resourcelocation = this.getBannerResourceLocation(te);

		if(resourcelocation!=null)
		{
			matrixStack.pushPose();

			matrixStack.scale(2f/3, -2f/3, -2f/3);
			VertexConsumer builder;
			builder = bufferIn.getBuffer(RenderType.entitySolid(resourcelocation));
			this.clothModel.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);
			builder = ModelBakery.BANNER_BASE.buffer(bufferIn, RenderType::entitySolid);
			this.crossbar.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);
			this.standingModel.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);

			matrixStack.popPose();
		}

		matrixStack.popPose();
	}

@Override
	public void render(IMultiblockContext<State> context, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final State state = context.getState();
		matrixStack.pushPose();

		matrixStack.translate(.5, 0, .5);

		FluidStack fs = state.tank.getFluid();
		matrixStack.translate(0, 3.5f, 0);
		float baseScale = .0625f;
		matrixStack.scale(baseScale, -baseScale, baseScale);

		float xx = -.5f;
		float zz = 1.5f-.004f;
		xx /= baseScale;
		zz /= baseScale;
		for(int i = 0; i < 4; i++)
		{
			matrixStack.pushPose();
			matrixStack.translate(xx, 0, zz);

			Matrix4f mat = matrixStack.last().pose();
			final VertexConsumer builder = bufferIn.getBuffer(IERenderTypes.TRANSLUCENT_POSITION_COLOR);
			builder.addVertex(mat, -4, -4, 0).setColor(0x22, 0x22, 0x22, 0xff);
			builder.addVertex(mat, -4, 20, 0).setColor(0x22, 0x22, 0x22, 0xff);
			builder.addVertex(mat, 20, 20, 0).setColor(0x22, 0x22, 0x22, 0xff);
			builder.addVertex(mat, 20, -4, 0).setColor(0x22, 0x22, 0x22, 0xff);

			if(!fs.isEmpty())
			{
				float h = fs.getAmount()/(float)state.tank.getCapacity();
				matrixStack.translate(0, 0, .004f);
				GuiHelper.drawRepeatedFluidSprite(bufferIn.getBuffer(RenderType.solid()), matrixStack, fs,
						0, 0+(1-h)*16, 16, h*16);
			}
			matrixStack.popPose();
			matrixStack.mulPose(new Quaternionf().rotateY(Mth.HALF_PI));
		}
		matrixStack.popPose();
	}

@Override
	public void render(IMultiblockContext<State> context, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final State state = context.getState();
		if(state.identStack.isEmpty())
			return;
		matrixStack.pushPose();

		matrixStack.translate(.5, 5, .5);
		float baseScale = .0625f;
		float itemScale = .5f;
		float flatScale = .001f;
		float textScale = .375f*0.75f;
		matrixStack.scale(baseScale, baseScale, baseScale);
		String label = ""+state.storageAmount;
		float w = ClientUtils.mc().font.width(label);

		float zz = 1.501f;
		zz /= baseScale;
		w *= textScale;
		for(int i = 0; i < 4; i++)
		{
			matrixStack.pushPose();
			matrixStack.translate(0, 0, zz);

			matrixStack.pushPose();
			// Do not multiply the normal matrix here, it messes up lighting for some reason
			matrixStack.last().pose().scale(itemScale/baseScale, itemScale/baseScale, flatScale)
			;
			matrixStack.translate(0, -0.75, 0);
			ClientUtils.mc().getItemRenderer().renderStatic(
					state.identStack, ItemDisplayContext.GUI,
					combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
					context.getLevel().getRawLevel(), 0
			);
			matrixStack.popPose();

			matrixStack.pushPose();
			matrixStack.translate(-w/2, -11, .001f);
			matrixStack.scale(textScale, -textScale, 1);
			ClientUtils.font().drawInBatch(
					label, 0, 0, 0x888888, true, matrixStack.last().pose(), bufferIn, DisplayMode.NORMAL, 0, combinedLightIn
			);
			matrixStack.popPose();

			matrixStack.popPose();
			matrixStack.mulPose(new Quaternionf().rotateY(Mth.HALF_PI));
		}
		matrixStack.popPose();
	}

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final BlockRenderDispatcher blockRenderer = Minecraft.getInstance().getBlockRenderer();
		BakedModel model = PISTON.get();
		final MultiblockOrientation orientation = ctx.getLevel().getOrientation();

		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);
		bufferIn = BERenderUtils.mirror(orientation, matrixStack, bufferIn);
		VertexConsumer buffer = bufferIn.getBuffer(RenderType.solid());

		float piston = ctx.getState().animation_piston;
		//Smoothstep! TODO partial ticks?
		piston = piston*piston*(3.0f-2.0f*piston);

		matrixStack.translate(0, piston, 0);

		matrixStack.translate(-.5, -.5, -.5);
		rotateForFacing(matrixStack, orientation.front());
		blockRenderer.getModelRenderer().renderModel(
				matrixStack.last(), buffer, null, model,
				1, 1, 1,
				combinedLightIn, combinedOverlayIn, ModelData.EMPTY, RenderType.solid()
		);

		matrixStack.popPose();
	}

