@Override
	public void render(TurretBlockEntity<?> tile, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		if(!tile.getLevelNonnull().hasChunkAt(tile.getBlockPos()))
			return;

		BlockState state = tile.getBlockState();
		if(state.getBlock()!=MetalDevices.TURRET_CHEM.get()&&state.getBlock()!=MetalDevices.TURRET_GUN.get())
			return;
		BakedModel model = MODELS_BY_BLOCK.get(BuiltInRegistries.BLOCK.getKey(state.getBlock())).get();

		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);

		float defaultYaw = 180-tile.getFacing().toYRot();
		matrixStack.mulPose(new Quaternionf()
				.rotateY((tile.rotationYaw+defaultYaw)*Mth.DEG_TO_RAD)
				.rotateX(-tile.rotationPitch*Mth.DEG_TO_RAD)
		);

		renderModelPart(bufferIn, matrixStack, tile.getLevelNonnull(), state, model, tile.getBlockPos(), true, combinedLightIn, "gun");
		if(tile instanceof TurretGunBlockEntity gunTurret)
		{
			if(gunTurret.cycleRender > 0)
			{
				float cycle = 0;
				if(gunTurret.cycleRender > 3)
					cycle = (5-gunTurret.cycleRender)/2f;
				else
					cycle = gunTurret.cycleRender/3f;

				matrixStack.translate(0, 0, cycle*.3125);
			}
			renderModelPart(bufferIn, matrixStack, tile.getLevelNonnull(), state, model, tile.getBlockPos(), false, combinedLightIn, "action");
		}

		matrixStack.popPose();
	}

@Override
	public void render(WatermillBlockEntity tile, float partialTicks, PoseStack transform, MultiBufferSource bufferIn,
					   int combinedLightIn, int combinedOverlayIn)
	{
		if(!SafeChunkUtils.isChunkSafe(tile.getLevelNonnull(), tile.getBlockPos()))
			return;
		transform.pushPose();
		transform.translate(.5, .5, .5);
		if(tile.getFacing().getAxis()==Axis.X)
			transform.mulPose(new Quaternionf().rotateY(Mth.HALF_PI));
		float wheelRotation = (float)(Mth.TWO_PI*(tile.getRotation()+partialTicks*tile.getSpeed()));
		transform.mulPose(new Quaternionf().rotateZ(wheelRotation));
		transform.translate(-.5, -.5, -.5);
		MODEL_BUFFER.render(RenderType.cutoutMipped(), combinedLightIn, combinedOverlayIn, bufferIn, transform);
		transform.popPose();
	}

@Override
	public void render(WindmillBlockEntity tile, float partialTicks, PoseStack transform, MultiBufferSource bufferIn,
					   int combinedLightIn, int combinedOverlayIn)
	{
		if(!tile.getLevelNonnull().hasChunkAt(tile.getBlockPos()))
			return;
		transform.pushPose();
		transform.translate(.5, .5, .5);

		float dir = tile.getFacing()==Direction.SOUTH?0: tile.getFacing()==Direction.NORTH?Mth.PI: tile.getFacing()==Direction.EAST?Mth.HALF_PI: -Mth.HALF_PI;
		float rot = (float)(Mth.TWO_PI*(tile.rotation+partialTicks*tile.getActualTurnSpeed()));

		transform.mulPose(new Quaternionf()
				.rotateAxis(rot, new Vector3f(tile.getFacing().getAxis()==Axis.X?1: 0, 0, tile.getFacing().getAxis()==Axis.Z?1: 0))
				.rotateY(dir)
		);

		transform.translate(-.5, -.5, -.5);
		getBufferHolder(tile.sails)
				.render(RenderType.cutout(), combinedLightIn, combinedOverlayIn, bufferIn, transform);
		transform.popPose();
	}

public void pipe(VertexConsumer out)
		{
			for(Element e : order)
				switch(e)
				{
					case POSITION -> out.addVertex(position[0], position[1], position[2]);
					case COLOR -> out.setColor(color[0], color[1], color[2], color[3]);
					case UV -> out.setUv(uv[0], uv[1]);
					case OVERLAY -> out.setUv1(overlay[0], overlay[1]);
					case UV2 -> out.setUv2(uv2[0], uv2[1]);
					case NORMAL -> out.setNormal(normal[0], normal[1], normal[2]);
				}
		}

public static void colouredBlit(GuiGraphics graphics, ResourceLocation atlasLocation, int x, int y, int blitOffset, int width, int height, int u, int v, float red, float green, float blue, float alpha)
	{
		RenderSystem.setShaderTexture(0, atlasLocation);
		RenderSystem.setShader(GameRenderer::getPositionTexColorShader);
		RenderSystem.enableBlend();
		Matrix4f matrix4f = graphics.pose().last().pose();
		BufferBuilder bufferbuilder = Tesselator.getInstance().begin(Mode.QUADS, DefaultVertexFormat.POSITION_TEX_COLOR);
		bufferbuilder.addVertex(matrix4f, x, y, blitOffset).setUv(u/256f, v/256f).setColor(red, green, blue, alpha);
		bufferbuilder.addVertex(matrix4f, x, y+height, blitOffset).setUv(u/256f, (v+height)/256f).setColor(red, green, blue, alpha);
		bufferbuilder.addVertex(matrix4f, x+width, y+height, blitOffset).setUv((u+width)/256f, (v+height)/256f).setColor(red, green, blue, alpha);
		bufferbuilder.addVertex(matrix4f, x+width, y, blitOffset).setUv((u+width)/256f, v/256f).setColor(red, green, blue, alpha);
		BufferUploader.drawWithShader(bufferbuilder.buildOrThrow());
		RenderSystem.disableBlend();
	}

public static void drawTexturedColoredRect(
			VertexConsumer builder, PoseStack transform,
			float x, float y, float w, float h,
			float r, float g, float b, float alpha,
			float u0, float u1, float v0, float v1
	)
	{
		TransformingVertexBuilder innerBuilder = new TransformingVertexBuilder(builder, transform);
		innerBuilder.defaultColor(r, g, b, alpha);
		innerBuilder.setDefaultLight(LightTexture.FULL_BRIGHT);
		innerBuilder.setDefaultOverlay(OverlayTexture.NO_OVERLAY);
		innerBuilder.setDefaultNormal(1, 1, 1);
		innerBuilder.addVertex(x, y+h, 0).setUv(u0, v1);
		innerBuilder.addVertex(x+w, y+h, 0).setUv(u1, v1);
		innerBuilder.addVertex(x+w, y, 0).setUv(u1, v0);
		innerBuilder.addVertex(x, y, 0).setUv(u0, v0);
		innerBuilder.unsetDefaultColor();
	}

