public static void render(PoseStack poseStack, MultiBufferSource bufferSource, LocalPlayer player, Vec3 cameraPos) {
		if(client.hitResult instanceof BlockHitResult hitResult && ArcanusComponents.isBlockWarded(player.clientLevel, hitResult.getBlockPos()) && player.swinging) {
			BlockPos blockPos = hitResult.getBlockPos();

			if(client.options.keyAttack.isDown() && player.attackAnim == 0)
				hitTimer = 20;

			if(!ArcanusComponents.isOwnerOfBlock(player, blockPos) || hitTimer > 0) {
				float alpha = Mth.clamp(hitTimer / 20f, 0f, 1f);

				renderWardedBlock(poseStack, bufferSource, player.clientLevel, cameraPos, blockPos, alpha);
				player.displayClientMessage(Component.translatable(TranslationKeys.BLOCK_IS_WARDED).withStyle(ChatFormatting.RED), true);
			}

			if(hitTimer > 0)
				hitTimer -= 1;
		}

		if(player.getMainHandItem().is(ArcanusItemTags.STAVES) || player.getOffhandItem().is(ArcanusItemTags.STAVES)) {
			AtomicReferenceArray<LevelChunk> chunks = player.clientLevel.getChunkSource().storage.chunks;
			float alpha = Mth.sin(player.clientLevel.getGameTime() * 0.06f) * 0.4f + 0.6f;

			for(int i = 0; i < chunks.length(); i++) {
				ChunkAccess chunk = chunks.get(i);

				if(chunk != null) {
					ArcanusComponents.getWardedBlocks(chunk).forEach((blockPos, uuid) -> {
						if(blockPos.distSqr(BlockPos.containing(cameraPos)) < 256)
							renderWardedBlock(poseStack, bufferSource, player.clientLevel, cameraPos, blockPos, alpha);
					});
				}
			}
		}
	}

private static void renderWardedBlock(PoseStack poseStack, MultiBufferSource buffer, Level level, Vec3 cameraPos, BlockPos blockPos, float alpha) {
		VertexConsumer consumer = buffer.getBuffer(WARDED_BLOCK);
		Vec3 pos = Vec3.atCenterOf(blockPos);

		poseStack.pushPose();
		poseStack.translate(pos.x() - cameraPos.x(), pos.y() - cameraPos.y(), pos.z() - cameraPos.z());
		poseStack.scale(1.001f, 1.001f, 1.001f);
		poseStack.translate(-0.5, -0.5, -0.5);

		PoseStack.Pose pose = poseStack.last();
		Matrix4f matrix4f = pose.pose();
		Color color = ArcanusHelper.getMagicColor(ArcanusComponents.getWardedBlocks(level.getChunk(blockPos)).get(blockPos));
		int light = level.getMaxLocalRawBrightness(blockPos);
		int overlay = OverlayTexture.NO_OVERLAY;
		float r = Mth.clamp(color.redF() * alpha, 0f, 1f);
		float g = Mth.clamp(color.greenF() * alpha, 0f, 1f);
		float b = Mth.clamp(color.blueF() * alpha, 0f, 1f);

		color = Color.fromFloatsRGB(r, g, b);

		for(Direction direction : Direction.values()) {
			BlockPos posToSide = blockPos.relative(direction);
			BlockState stateToSide = level.getBlockState(posToSide);

			if(stateToSide.isFaceSturdy(level, posToSide, direction.getOpposite(), SupportType.FULL) || ArcanusComponents.isBlockWarded(level, posToSide))
				continue;

			switch(direction) {
				case SOUTH ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 0f, 1f, 1f, 1f, 1f, 1f, color, light, overlay, pose, Direction.SOUTH);
				case NORTH ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 1f, 0f, 0f, 0f, 0f, 0f, color, light, overlay, pose, Direction.NORTH);
				case EAST ->
					ArcanusClient.renderQuad(matrix4f, consumer, 1f, 1f, 1f, 0f, 0f, 1f, 1f, 0f, color, light, overlay, pose, Direction.EAST);
				case WEST ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 0f, 0f, 1f, 0f, 1f, 1f, 0f, color, light, overlay, pose, Direction.WEST);
				case DOWN ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 0f, 0f, 0f, 0f, 1f, 1f, color, light, overlay, pose, Direction.DOWN);
				case UP ->
					ArcanusClient.renderQuad(matrix4f, consumer, 0f, 1f, 1f, 1f, 1f, 1f, 0f, 0f, color, light, overlay, pose, Direction.UP);
			}
		}

		poseStack.popPose();
	}

private void setupRenderLevelAndRenderedBlockEntities() {
		for (StructureBlockInfo info : contraption.getBlocks().values()) {
			renderLevel.setBlock(info.pos(), info.state(), 0);

			BlockEntity blockEntity = readBlockEntity(renderLevel, info, contraption.getIsLegacy().getBoolean(info.pos()));

			if (blockEntity != null) {
				renderLevel.setBlockEntity(blockEntity);

				// Don't render block entities that have an actor renderer registered in the MovementBehaviour.
				MovementBehaviour movementBehaviour = MovementBehaviour.REGISTRY.get(info.state());
				if (movementBehaviour == null || !movementBehaviour.disableBlockEntityRendering()) {
					renderedBlockEntities.add(blockEntity);
				}
			}
		}

		shouldRenderBlockEntities.set(0, renderedBlockEntities.size());

		renderLevel.runLightEngine();
	}

private static SuperByteBuffer buildStructureBuffer(Contraption contraption, VirtualRenderWorld renderWorld, RenderType layer) {
		BlockRenderDispatcher dispatcher = Minecraft.getInstance().getBlockRenderer();
		ModelBlockRenderer renderer = dispatcher.getModelRenderer();
		ThreadLocalObjects objects = THREAD_LOCAL_OBJECTS.get();

		PoseStack poseStack = objects.poseStack;
		RandomSource random = objects.random;
		var clientContraption = contraption.getOrCreateClientContraptionLazy();
		RenderedBlocks blocks = clientContraption.getRenderedBlocks();

		ShadedBlockSbbBuilder sbbBuilder = objects.sbbBuilder;
		sbbBuilder.begin();

		ModelBlockRenderer.enableCaching();
		for (BlockPos pos : blocks.positions()) {
			BlockState state = blocks.lookup().apply(pos);
			if (state.getRenderShape() == RenderShape.MODEL) {
				BakedModel model = dispatcher.getBlockModel(state);
				ModelData modelData = renderWorld.getModelData(pos);
				modelData = model.getModelData(renderWorld, pos, state, modelData);
				long randomSeed = state.getSeed(pos);
				random.setSeed(randomSeed);
				if (model.getRenderTypes(state, random, modelData).contains(layer)) {
					poseStack.pushPose();
					poseStack.translate(pos.getX(), pos.getY(), pos.getZ());
					renderer.tesselateBlock(renderWorld, model, state, pos, poseStack, sbbBuilder, true, random, randomSeed, OverlayTexture.NO_OVERLAY, modelData, layer);
					poseStack.popPose();
				}
			}
		}
		ModelBlockRenderer.clearCache();

		return sbbBuilder.end();
	}

@Override
	public void render(C entity, float yaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffers,
		int overlay) {
		super.render(entity, yaw, partialTicks, poseStack, buffers, overlay);

		Contraption contraption = entity.getContraption();
		if (contraption == null) {
			return;
		}

		Level level = entity.level();
		ClientContraption clientContraption = contraption.getOrCreateClientContraptionLazy();
		VirtualRenderWorld renderWorld = clientContraption.getRenderLevel();
		ContraptionMatrices matrices = clientContraption.getMatrices();
		matrices.setup(poseStack, entity);

		if (!VisualizationManager.supportsVisualization(level)) {
			for (RenderType renderType : RenderType.chunkBufferLayers()) {
				SuperByteBuffer sbb = getBuffer(contraption, renderWorld, renderType);
				if (!sbb.isEmpty()) {
					VertexConsumer vc = buffers.getBuffer(renderType);
					sbb.transform(matrices.getModel())
						.useLevelLight(level, matrices.getWorld())
						.renderInto(poseStack, vc);
				}
			}
		}

		var adjustRenderedBlockEntities = clientContraption.getAndAdjustShouldRenderBlockEntities();

		clientContraption.scratchErroredBlockEntities.clear();

		BlockEntityRenderHelper.renderBlockEntities(clientContraption.renderedBlockEntityView, adjustRenderedBlockEntities, clientContraption.scratchErroredBlockEntities, renderWorld, level, matrices.getModelViewProjection(), matrices.getLight(), buffers, AnimationTickHolder.getPartialTicks());

		clientContraption.shouldRenderBlockEntities.andNot(clientContraption.scratchErroredBlockEntities);
		renderActors(level, renderWorld, contraption, matrices, buffers);

		matrices.clear();
	}

private static void renderActors(Level level, VirtualRenderWorld renderWorld, Contraption c,
		ContraptionMatrices matrices, MultiBufferSource buffer) {
		PoseStack m = matrices.getModel();

		for (Pair<StructureTemplate.StructureBlockInfo, MovementContext> actor : c.getActors()) {
			MovementContext context = actor.getRight();
			if (context == null)
				continue;
			if (context.world == null)
				context.world = level;
			StructureTemplate.StructureBlockInfo blockInfo = actor.getLeft();

			MovementBehaviour movementBehaviour = MovementBehaviour.REGISTRY.get(blockInfo.state());
			if (movementBehaviour != null) {
				if (c.isHiddenInPortal(blockInfo.pos()))
					continue;
				m.pushPose();
				TransformStack.of(m)
					.translate(blockInfo.pos());
				movementBehaviour.renderInContraption(context, renderWorld, matrices, buffer);
				m.popPose();
			}
		}
	}

private void setupStructure(ClientContraption clientContraption) {
		var renderLevel = clientContraption.getRenderLevel();

		RenderedBlocks blocks = clientContraption.getRenderedBlocks();
		// Must wrap the render level so that the differences between the contraption's actual structure and the rendered blocks are accounted for in e.g. ambient occlusion.
		BlockAndTintGetter modelWorld = new WrappedBlockAndTintGetter(renderLevel) {
			@Override
			public BlockState getBlockState(BlockPos pos) {
				return blocks.lookup().apply(pos);
			}
		};

		var model = new BlockModelBuilder(modelWorld, blocks.positions())
			.materialFunc((renderType, shaded, ao) -> {
				Material material = ModelUtil.getMaterial(renderType, shaded, ao);
				if (material != null && material.cardinalLightingMode() == CardinalLightingMode.ENTITY) {
					return SimpleMaterial.builderOf(material)
						.cardinalLightingMode(CardinalLightingMode.CHUNK)
						.build();
				} else {
					return material;
				}
			})
			.build();

		var instancer = embedding.instancerProvider()
			.instancer(InstanceTypes.TRANSFORMED, model);

		// Null in ctor, so we need to create it
		// But we can steal it if it already exists
		if (structure == null) {
			structure = instancer.createInstance();
		} else {
			instancer.stealInstance(structure);
		}

		structure.setChanged();

		lastStructureVersion = clientContraption.structureVersion();
	}

private void setEmbeddingMatrices(float partialTick) {
		var origin = renderOrigin();
		double x;
		double y;
		double z;
		if (entity.isPrevPosInvalid()) {
			// When the visual is created the entity's old position is often zero
			x = entity.getX() - origin.getX();
			y = entity.getY() - origin.getY();
			z = entity.getZ() - origin.getZ();

		} else {
			x = Mth.lerp(partialTick, entity.xo, entity.getX()) - origin.getX();
			y = Mth.lerp(partialTick, entity.yo, entity.getY()) - origin.getY();
			z = Mth.lerp(partialTick, entity.zo, entity.getZ()) - origin.getZ();
		}

		contraptionMatrix.setIdentity();
		contraptionMatrix.translate(x, y, z);
		entity.applyLocalTransforms(contraptionMatrix, partialTick);

		embedding.transforms(contraptionMatrix.last().pose(), contraptionMatrix.last().normal());
	}

public void tick() {
		if (!isActive())
			return;

		LocalPlayer player = Minecraft.getInstance().player;
		if (AllKeys.ACTIVATE_TOOL.isPressed()) {
			float pt = AnimationTickHolder.getPartialTicks();
			Vec3 targetVec = player.getEyePosition(pt)
				.add(player.getLookAngle()
					.scale(range));
			selectedPos = BlockPos.containing(targetVec);

		} else {
			BlockHitResult trace = RaycastHelper.rayTraceRange(player.level(), player, 75);
			if (trace != null && trace.getType() == Type.BLOCK) {

				BlockPos hit = trace.getBlockPos();
				boolean replaceable = player.level().getBlockState(hit)
					.canBeReplaced(new BlockPlaceContext(new UseOnContext(player, InteractionHand.MAIN_HAND, trace)));
				if (trace.getDirection()
					.getAxis()
					.isVertical() && !replaceable)
					hit = hit.relative(trace.getDirection());
				selectedPos = hit;
			} else
				selectedPos = null;
		}

		selectedFace = null;
		if (secondPos != null) {
			AABB bb = new AABB(Vec3.atLowerCornerOf(firstPos), Vec3.atLowerCornerOf(secondPos)).expandTowards(1, 1, 1)
				.inflate(.45f);
			Vec3 projectedView = Minecraft.getInstance().gameRenderer.getMainCamera()
				.getPosition();
			boolean inside = bb.contains(projectedView);
			PredicateTraceResult result =
				RaycastHelper.rayTraceUntil(player, 70, pos -> inside ^ bb.contains(VecHelper.getCenterOf(pos)));
			selectedFace = result.missed() ? null
				: inside ? result.getFacing()
				.getOpposite() : result.getFacing();
		}

		AABB currentSelectionBox = getCurrentSelectionBox();
		if (currentSelectionBox != null)
			outliner().chaseAABB(outlineSlot, currentSelectionBox)
				.colored(0x6886c5)
				.withFaceTextures(AllSpecialTextures.CHECKERED, AllSpecialTextures.HIGHLIGHT_CHECKERED)
				.lineWidth(1 / 16f)
				.highlightFace(selectedFace);
	}

