			// -> Moved this in here so it isn't called every tick
			RayTraceResult rayTrace = RayTracer.standardEntityRayTrace(mc.world, mc.player, 16, false);

			if(rayTrace != null && rayTrace.entityHit == event.getEntity()){

				Tessellator tessellator = Tessellator.getInstance();
				BufferBuilder buffer = tessellator.getBuffer();

				GlStateManager.pushMatrix();

				GlStateManager.disableCull();
				GlStateManager.disableLighting();
				OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
				// Disabling depth test allows it to be seen through everything.
				GlStateManager.disableDepth();
				GlStateManager.color(1, 1, 1, 1);

				GlStateManager.translate(event.getX(), event.getY() + event.getEntity().height + 0.5, event.getZ());

				// This counteracts the reverse rotation behaviour when in front f5 view.
				// Fun fact: this is a bug with vanilla too! Look at a snowball in front f5 view, for example.
				float yaw = mc.gameSettings.thirdPersonView == 2 ? renderManager.playerViewX : -renderManager.playerViewX;
				GlStateManager.rotate(180 - renderManager.playerViewY, 0.0F, 1.0F, 0.0F);
				GlStateManager.rotate(yaw, 1.0F, 0.0F, 0.0F);

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

				mc.renderEngine.bindTexture(TARGET_POINTER_TEXTURE);

				buffer.pos(-0.2, 0.24, 0).tex(0, 0).endVertex();
				buffer.pos(0.2, 0.24, 0).tex(9f / 16f, 0).endVertex();
				buffer.pos(0.2, -0.24, 0).tex(9f / 16f, 11f / 16f).endVertex();
				buffer.pos(-0.2, -0.24, 0).tex(0, 11f / 16f).endVertex();

				tessellator.draw();

				GlStateManager.enableCull();
				GlStateManager.enableLighting();
				GlStateManager.enableDepth();

				GlStateManager.popMatrix();
			}
		}

		// Summoned creature selection pointer
		if(data != null && data.selectedMinion != null && data.selectedMinion.get() == event.getEntity()){

			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();

			GlStateManager.pushMatrix();

			GlStateManager.disableCull();
			GlStateManager.disableLighting();
			OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
			// Disabling depth test allows it to be seen through everything.
			GlStateManager.disableDepth();
			GlStateManager.color(1, 1, 1, 1);

			GlStateManager.translate(event.getX(), event.getY() + event.getEntity().height + 0.5, event.getZ());

			// This counteracts the reverse rotation behaviour when in front f5 view.
			// Fun fact: this is a bug with vanilla too! Look at a snowball in front f5 view, for example.
			float yaw = mc.gameSettings.thirdPersonView == 2 ? renderManager.playerViewX : -renderManager.playerViewX;
			GlStateManager.rotate(180 - renderManager.playerViewY, 0.0F, 1.0F, 0.0F);
			GlStateManager.rotate(yaw, 1.0F, 0.0F, 0.0F);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

			mc.renderEngine.bindTexture(POINTER_TEXTURE);

			buffer.pos(-0.2, 0.24, 0).tex(0, 0).endVertex();
			buffer.pos(0.2, 0.24, 0).tex(9f / 16f, 0).endVertex();
			buffer.pos(0.2, -0.24, 0).tex(9f / 16f, 11f / 16f).endVertex();
			buffer.pos(-0.2, -0.24, 0).tex(0, 11f / 16f).endVertex();

			tessellator.draw();

			GlStateManager.enableCull();
			GlStateManager.enableLighting();
			GlStateManager.enableDepth();

			GlStateManager.popMatrix();
		}
	}

@SubscribeEvent
	public static void onRenderWorldLastEvent(RenderWorldLastEvent event){

		// Only render in first person
		if(Minecraft.getMinecraft().gameSettings.thirdPersonView != 0) return;

		EntityPlayer player = Minecraft.getMinecraft().player;

		ItemStack stack = player.getHeldItemMainhand();
		if(!(stack.getItem() instanceof ISpellCastingItem)){
			stack = player.getHeldItemOffhand();
			if(!(stack.getItem() instanceof ISpellCastingItem)) return;
		}

		if(((ISpellCastingItem)stack.getItem()).getCurrentSpell(stack) == Spells.transportation
				&& ItemArtefact.isArtefactActive(player, WizardryItems.charm_transportation)){

			WizardData data = WizardData.get(player);
			if(data == null) return;

			List<Location> locations = data.getVariable(Transportation.LOCATIONS_KEY);

			if(locations == null) return;

			GlStateManager.pushMatrix();

			Vec3d origin = player.getPositionEyes(event.getPartialTicks());
			GlStateManager.translate(0, origin.y - Minecraft.getMinecraft().getRenderManager().viewerPosY, 0);

			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();

			Location target = Transportation.getLocationAimedAt(player, locations, event.getPartialTicks());

			for(Location location : locations){

				if(location.dimension != player.dimension) continue;

				GlStateManager.pushMatrix();
				GlStateManager.enableBlend();
				GlStateManager.disableLighting();
				GlStateManager.disableDepth();
				OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240, 240);
				GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
				GlStateManager.color(1, 1, 1, 1);

				Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

				Vec3d position = GeometryUtils.getCentre(location.pos).subtract(origin);
				double distance = position.length();
				// The icon lines up perfectly if you render it at actual distance, otherwise view bobbing messes things up
				// However, if that's outside the render distance it won't render at all! To fudge our way around this
				// problem, we're capping the distance to just below the render distance and adjusting the scale accordingly
				double distanceCap = Minecraft.getMinecraft().gameSettings.renderDistanceChunks * 16 - 8;
				double displayDist = Math.min(distance, distanceCap);
				double factor = displayDist/distance;

				GlStateManager.translate(position.x * factor, position.y * factor, position.z * factor);

				GlStateManager.rotate(-Minecraft.getMinecraft().getRenderManager().playerViewY, 0.0F, 1.0F, 0.0F);
				GlStateManager.rotate(Minecraft.getMinecraft().getRenderManager().playerViewX, 1.0F, 0.0F, 0.0F);

				// Get the angle between the player's look vector and the direction of the stone circle
				double angle = Transportation.getLookDeviationAngle(player, location.pos, event.getPartialTicks());
				double iconSize = Transportation.getIconSize(distance);

				// Now apply a fancy formula to make it enlarge with a nice smooth animation:
				double proximityFactor = Math.max(0, Math.pow(1 - angle/iconSize * angle/iconSize, 3));
				iconSize *= 1 + 0.3 * proximityFactor;
				iconSize *= displayDist; // Adjust the icon size for perspective

				float f = location == target ? 1 : 0.5f; // Makes it obvious which one is being aimed at

				buffer.pos(-iconSize,  iconSize, 0).tex(0, 0).color(f, 1, f, f).endVertex();
				buffer.pos( iconSize,  iconSize, 0).tex(1, 0).color(f, 1, f, f).endVertex();
				buffer.pos( iconSize, -iconSize, 0).tex(1, 1).color(f, 1, f, f).endVertex();
				buffer.pos(-iconSize, -iconSize, 0).tex(0, 1).color(f, 1, f, f).endVertex();

				tessellator.draw();

				GlStateManager.popMatrix();

				if(location == target){
					String label = location.pos.getX() + ", " + location.pos.getY() + ", " + location.pos.getZ();
					drawLabel(Minecraft.getMinecraft().fontRenderer, label, (float)(position.x * factor),
							(float)(position.y * factor + iconSize*1.5f), (float)(position.z * factor), (float)displayDist * 0.2f, 0,
							Minecraft.getMinecraft().getRenderManager().playerViewY, Minecraft.getMinecraft().getRenderManager().playerViewX);
				}
			}

			GlStateManager.disableBlend();
			GlStateManager.enableTexture2D();
			GlStateManager.enableLighting();
			GlStateManager.enableDepth();
			GlStateManager.disableRescaleNormal();
			GlStateManager.popMatrix();
		}
	}

private static void drawLabel(FontRenderer fontRendererIn, String str, float x, float y, float z, float scale, int verticalShift, float viewerYaw, float viewerPitch){

		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y, z);
		GlStateManager.glNormal3f(0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(-viewerYaw, 0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(viewerPitch, 1.0F, 0.0F, 0.0F);
		GlStateManager.scale(-0.025F, -0.025F, 0.025F);
		GlStateManager.scale(scale, scale, scale);
		GlStateManager.disableLighting();
		GlStateManager.depthMask(false);

		GlStateManager.disableDepth();

		GlStateManager.enableBlend();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
		int i = fontRendererIn.getStringWidth(str) / 2;
		GlStateManager.disableTexture2D();
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder bufferbuilder = tessellator.getBuffer();
		bufferbuilder.begin(7, DefaultVertexFormats.POSITION_COLOR);
		bufferbuilder.pos((-i - 1), (-1 + verticalShift), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		bufferbuilder.pos((-i - 1), ( 8 + verticalShift), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		bufferbuilder.pos(( i + 1), ( 8 + verticalShift), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		bufferbuilder.pos(( i + 1), (-1 + verticalShift), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		tessellator.draw();
		GlStateManager.enableTexture2D();

		fontRendererIn.drawString(str, -fontRendererIn.getStringWidth(str) / 2, verticalShift, 0x86ff65);
		GlStateManager.enableDepth();

		GlStateManager.depthMask(true);
		fontRendererIn.drawString(str, -fontRendererIn.getStringWidth(str) / 2, verticalShift, 0x86ff65);
		GlStateManager.enableLighting();
		GlStateManager.disableBlend();
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();
	}

@SubscribeEvent
	public static void onRenderWorldLastEvent(RenderWorldLastEvent event){

		EntityPlayer player = Minecraft.getMinecraft().player;
		World world = Minecraft.getMinecraft().world;
		Vec3d origin = player.getPositionEyes(event.getPartialTicks());
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		boolean flag = false;
		boolean lighting = false;

		// Someone managed to get a CME here so let's iterate manually to be safe (don't copy the list, it's expensive!)
		// It's only cosmetic so if a tileentity somehow gets removed while we're rendering them it's not a big deal
		for(int i=0; i<world.loadedTileEntityList.size(); i++){

			TileEntity tileentity = world.loadedTileEntityList.get(i);

			if(tileentity == null) continue; // What the heck VoxelMap

			if(tileentity.getDistanceSq(origin.x, origin.y, origin.z) <= tileentity.getMaxRenderDistanceSquared()
					&& tileentity.getTileData().hasUniqueId(ArcaneLock.NBT_KEY)){

				if(!flag){

					flag = true;

					GlStateManager.pushMatrix();
					GlStateManager.enableBlend();
					GlStateManager.enableDepth();
					GlStateManager.depthMask(true);
					GlStateManager.disableCull();
					lighting = GL11.glIsEnabled(GL11.GL_LIGHTING);
					GlStateManager.disableLighting();
					GlStateManager.setActiveTexture(OpenGlHelper.defaultTexUnit);
					OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240, 240);
					GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

					GlStateManager.translate(-origin.x, -origin.y + player.getEyeHeight(), -origin.z);

					GlStateManager.color(1, 1, 1, 1);

					Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURES[(player.ticksExisted % (TEXTURES.length * 2))/2]);

					buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
				}

				Vec3d[] vertices = GeometryUtils.getVertices(world.getBlockState(tileentity.getPos()).getBoundingBox(world, tileentity.getPos()).grow(0.05).offset(tileentity.getPos()));

				drawFace(buffer, vertices[0], vertices[1], vertices[3], vertices[2], 0, 0, 1, 1); // Bottom
				drawFace(buffer, vertices[6], vertices[7], vertices[2], vertices[3], 0, 0, 1, 1); // South
				drawFace(buffer, vertices[5], vertices[6], vertices[1], vertices[2], 0, 0, 1, 1); // East
				drawFace(buffer, vertices[4], vertices[5], vertices[0], vertices[1], 0, 0, 1, 1); // North
				drawFace(buffer, vertices[7], vertices[4], vertices[3], vertices[0], 0, 0, 1, 1); // West
				drawFace(buffer, vertices[5], vertices[4], vertices[6], vertices[7], 0, 0, 1, 1); // Top

			}
		}

		if(flag){

			tessellator.draw();

			GlStateManager.enableCull();
			GlStateManager.disableBlend();
			GlStateManager.enableTexture2D();
			if(lighting){
				GlStateManager.enableLighting();
			}
			GlStateManager.disableRescaleNormal();
			GlStateManager.popMatrix();
		}

	}

@Override
	public void render(TileEntityArcaneWorkbench tileentity, double x, double y, double z, float partialTicks, int destroyStage, float alpha){

		GlStateManager.pushMatrix();
		// This line makes stuff render in the same place relative to the world wherever the player is.
		GlStateManager.translate((float)x + 0.5F, (float)y + 1.5F, (float)z + 0.5F);
		GlStateManager.rotate(180, 0F, 0F, 1F);
		GlStateManager.pushMatrix();
		double angle;
		if(x < -0.5){
			angle = Math.toDegrees(Math.atan((z + 0.5) / (x + 0.5))) + 180;
		}else{
			angle = Math.toDegrees(Math.atan((z + 0.5) / (x + 0.5)));
		}
		this.renderEffect(tileentity, partialTicks);
		this.renderWand(tileentity, angle, partialTicks);
		GlStateManager.popMatrix();
		GlStateManager.popMatrix();
	}

private void renderEffect(TileEntityArcaneWorkbench tileentity, float partialTicks){

		ItemStack itemstack = tileentity.getStackInSlot(ContainerArcaneWorkbench.CENTRE_SLOT);

		if(!itemstack.isEmpty()){
			GlStateManager.pushMatrix();
			GlStateManager.disableLighting();
			OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA); // This line fixes the weird brightness bug.
			GlStateManager.rotate(tileentity.timer + partialTicks, 0.0f, 1.0f, 0.0f);
			GlStateManager.translate(0.0f, 0.65f, 0.0f);
			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();
			bindTexture(RUNE_TEXTURE);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-0.5f, 0, -0.5f).tex(0, 0).endVertex();
			buffer.pos(0.5f, 0, -0.5f).tex(1, 0).endVertex();
			buffer.pos(0.5f, 0, 0.5f).tex(1, 1).endVertex();
			buffer.pos(-0.5f, 0, 0.5f).tex(0, 1).endVertex();
			tessellator.draw();

			GlStateManager.disableBlend();
			GlStateManager.enableLighting();
			GlStateManager.popMatrix();
		}
	}

private void renderWand(TileEntityArcaneWorkbench tileentity, double viewAngle, float partialTicks){

		ItemStack stack = tileentity.getStackInSlot(ContainerArcaneWorkbench.CENTRE_SLOT);

		if(!stack.isEmpty()){

			GlStateManager.pushMatrix();
			//GlStateManager.rotate(180.0F, 1.0F, 0.0F, 0.0F);
			GlStateManager.rotate(90.0F, 1.0F, 0.0F, 0.0F);

			GlStateManager.rotate(180, 0, 1, 0);
			GlStateManager.rotate((float)(viewAngle - 90f), 0, 0, 1);
			// Does the floaty thing		<- #bestcommentever
			GlStateManager.translate(0.0F, 0.0F, 0.56f + 0.05f * MathHelper.sin((tileentity.timer + partialTicks)/15));//(float)tileentity.yOffset / 5000.0F + 0.55f);
			GlStateManager.scale(0.75F, 0.75F, 0.75F);
			// This is what the item frame uses so it's definitely what we want.
			Minecraft.getMinecraft().getRenderItem().renderItem(stack, TransformType.FIXED);
			GlStateManager.popMatrix();
		}
	}

@Override
	public void render(TileEntityImbuementAltar tileentity, double x, double y, double z, float partialTicks, int destroyStage, float alpha){

		GlStateManager.pushMatrix();

