private void renderItem(TileEntityImbuementAltar tileentity, float t){

		ItemStack stack = tileentity.getStack();

		if(!stack.isEmpty()){

			GlStateManager.pushMatrix();

			GlStateManager.rotate(180, 1, 0, 0);
			GlStateManager.rotate(t, 0, 1, 0);
			GlStateManager.scale(0.85F, 0.85F, 0.85F);

			Minecraft.getMinecraft().getRenderItem().renderItem(stack, TransformType.FIXED);

			GlStateManager.popMatrix();
		}
	}

private void renderRays(TileEntityImbuementAltar tileentity, float partialTicks){

		float t = Minecraft.getMinecraft().player.ticksExisted + partialTicks;

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();
		Random random = new Random(tileentity.getPos().toLong()); // Use position to get a constant seed

		int[] colours = BlockReceptacle.PARTICLE_COLOURS.get(tileentity.getDisplayElement());

		if(colours == null) return; // Shouldn't happen

		GlStateManager.disableCull();
		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.disableTexture2D();
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE);
		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		GlStateManager.disableLighting();
		GlStateManager.depthMask(false);
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
		RenderHelper.disableStandardItemLighting();

		int r1 = colours[1] >> 16 & 255;
		int g1 = colours[1] >> 8 & 255;
		int b1 = colours[1] & 255;

		int r2 = colours[2] >> 16 & 255;
		int g2 = colours[2] >> 8 & 255;
		int b2 = colours[2] & 255;

		for(int j = 0; j < 30; j++){

			int m = random.nextInt(10);
			int n = random.nextInt(10);

			int sliceAngle = 20 + m;
			float scale = 0.5f;

			GlStateManager.pushMatrix();

			float progress = Math.min(tileentity.getImbuementProgress() + partialTicks/141, 1);
			float s = 1 - progress;
			s = 1 - s*s;
			GlStateManager.scale(s, s, s);

			// TODO: This needs optimising! We should easily be able to do this with a single draw() call
			// Same for magic light and black hole, which don't need ray textures either!
			GlStateManager.rotate(31 * m, 1, 0, 0);
			GlStateManager.rotate(31 * n, 0, 0, 1);

			buffer.begin(5, DefaultVertexFormats.POSITION_COLOR);

			float fade = (Math.min(1, 1.9f - progress) - 0.9f) * 10;

			buffer.pos(0, 0, 0).color(r1, g1, b1, (int)(255 * fade)).endVertex();
			buffer.pos(0, 0, 0).color(r1, g1, b1, (int)(255 * fade)).endVertex();

			double x1 = scale * MathHelper.sin((t + 40 * j) * ((float)Math.PI / 180));
			double z1 = scale * MathHelper.cos((t + 40 * j) * ((float)Math.PI / 180));

			double x2 = scale * MathHelper.sin((t + 40 * j - sliceAngle) * ((float)Math.PI / 180));
			double z2 = scale * MathHelper.cos((t + 40 * j - sliceAngle) * ((float)Math.PI / 180));

			buffer.pos(x1, 0, z1).color(r2, g2, b2, 0).endVertex();
			buffer.pos(x2, 0, z2).color(r2, g2, b2, 0).endVertex();

			tessellator.draw();

			GlStateManager.popMatrix();
		}

		GlStateManager.shadeModel(GL11.GL_FLAT);
		GlStateManager.enableCull();
		GlStateManager.disableBlend();
		GlStateManager.disableAlpha();
		GlStateManager.depthMask(true);
		GlStateManager.enableTexture2D();
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
		GlStateManager.enableLighting();
		RenderHelper.enableStandardItemLighting();
	}

@Override
	public void render(TileEntityLectern te, double x, double y, double z, float partialTicks, int destroyStage, float alpha){

		GlStateManager.pushMatrix();
		GlStateManager.translate((float)x + 0.5F, (float)y + 1, (float)z + 0.5F);
		GlStateManager.rotate(90 - te.getWorld().getBlockState(te.getPos()).getValue(BlockHorizontal.FACING).getHorizontalAngle(), 0, 1, 0);

		float time = (float)te.ticksExisted + partialTicks;

		float spread = te.bookSpreadPrev + (te.bookSpread - te.bookSpreadPrev) * partialTicks;

		GlStateManager.translate(0, 0.12, 0);
		if(spread > 0.3) GlStateManager.translate(0, MathHelper.sin(time * 0.1F) * 0.01F, 0);

		GlStateManager.rotate(112.5F, 0, 0, 1);

		GlStateManager.translate(0, 0.04 + (1 - spread) * 0.09, (1 - spread) * -0.1875);

		GlStateManager.rotate((1 - spread) * -90, 0, 1, 0);

		this.bindTexture(BOOK_TEXTURE);

		float f3 = te.pageFlipPrev + (te.pageFlip - te.pageFlipPrev) * partialTicks + 0.25F;
		float f4 = te.pageFlipPrev + (te.pageFlip - te.pageFlipPrev) * partialTicks + 0.75F;
		f3 = (f3 - (float)MathHelper.fastFloor(f3)) * 1.6F - 0.3F;
		f4 = (f4 - (float)MathHelper.fastFloor(f4)) * 1.6F - 0.3F;

		f3 = MathHelper.clamp(f3, 0, 1);
		f4 = MathHelper.clamp(f4, 0, 1);

		GlStateManager.enableCull();
		this.modelBook.render(null, time, f3, f4, spread, 0.0F, 0.0625F);
		GlStateManager.popMatrix();

	}

@Override
	public void render(TileEntityMagicLight tileentity, double x, double y, double z, float partialTicks,
			int destroyStage, float alpha){

		GlStateManager.pushMatrix();

		GlStateManager.disableCull();
		GlStateManager.enableBlend();
		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		GlStateManager.disableLighting();
		GlStateManager.depthMask(false);
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
		RenderHelper.disableStandardItemLighting();

		GlStateManager.translate(x + 0.5, y + 0.5, z + 0.5);

		float s = DrawingUtils.smoothScaleFactor(tileentity.getLifetime(), tileentity.timer, partialTicks, 10, 10);
		GlStateManager.scale(s, s, s);

		// Renders the aura effect

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.pushMatrix();

		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		// This counteracts the reverse rotation behaviour when in front f5 view.
		// Fun fact: this is a bug with vanilla too! Look at a snowball in front f5 view, for example.
		float yaw = Minecraft.getMinecraft().gameSettings.thirdPersonView == 2
				? Minecraft.getMinecraft().getRenderManager().playerViewX
				: -Minecraft.getMinecraft().getRenderManager().playerViewX;
		GlStateManager.rotate(180.0F - Minecraft.getMinecraft().getRenderManager().playerViewY, 0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(yaw, 1.0F, 0.0F, 0.0F);

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

		this.bindTexture(FLARE_TEXTURE);

		buffer.pos(-0.6, 0.6, 0).tex(0, 0).endVertex();
		buffer.pos(0.6, 0.6, 0).tex(1, 0).endVertex();
		buffer.pos(0.6, -0.6, 0).tex(1, 1).endVertex();
		buffer.pos(-0.6, -0.6, 0).tex(0, 1).endVertex();

		tessellator.draw();

		GlStateManager.popMatrix();

		// Renders the rays

		// For some reason, the old blend function (GL11.GL_SRC_ALPHA, GL11.GL_SRC_ALPHA) caused the innermost
		// ends of the rays to appear black, so I have changed it to this, which looks very slightly different.
		GlStateManager.blendFunc(GL11.GL_ONE, GL11.GL_SRC_ALPHA);

		this.bindTexture(RAY_TEXTURE);

		if(tileentity.randomiser.length >= 30){
			for(int j = 0; j < 30; j++){

				int sliceAngle = 20 + tileentity.randomiser[j];
				float scale = 0.5f;

				GlStateManager.pushMatrix();

				GlStateManager.rotate(31 * tileentity.randomiser[j], 1, 0, 0);
				GlStateManager.rotate(31 * tileentity.randomiser2[j], 0, 0, 1);

				/* OK, so here are the changes to rendering as far as I know: Vertex formats specify how the methods are
				 * arranged Color has to be called for every vertex, I think. The new methods thing is a bit weird,
				 * because other than the number of arguments there is essentially no difference between pos, tex,
				 * color, normal and lightmap. At least they make the code more readable. */

				buffer.begin(5, DefaultVertexFormats.POSITION_TEX_COLOR);

				buffer.pos(0, 0, 0).tex(0, 0).color(255, 255, 255, 0).endVertex();
				buffer.pos(0, 0, 0).tex(0, 1).color(255, 255, 255, 0).endVertex();

				double x1 = scale * MathHelper.sin((tileentity.timer + 40 * j) * ((float)Math.PI / 180));
				// double y1 = 0.7*MathHelper.cos((timerentity.timer - 40*j)*(Math.PI/180))*j/10;
				double z1 = scale * MathHelper.cos((tileentity.timer + 40 * j) * ((float)Math.PI / 180));

				double x2 = scale * MathHelper.sin((tileentity.timer + 40 * j - sliceAngle) * ((float)Math.PI / 180));
				// double y2 = 0.7*MathHelper.sin((timerentity.timer - 40*j)*(Math.PI/180))*j/10;
				double z2 = scale * MathHelper.cos((tileentity.timer + 40 * j - sliceAngle) * ((float)Math.PI / 180));

				buffer.pos(x1, 0, z1).tex(1, 0).color(0, 0, 0, 255).endVertex();
				buffer.pos(x2, 0, z2).tex(1, 1).color(0, 0, 0, 255).endVertex();

				tessellator.draw();

				GlStateManager.popMatrix();
			}
		}

		GlStateManager.shadeModel(GL11.GL_FLAT);
		GlStateManager.enableCull();
		GlStateManager.disableBlend();
		GlStateManager.enableLighting();
		GlStateManager.depthMask(true);
		RenderHelper.enableStandardItemLighting();

		GlStateManager.popMatrix();
	}

@Override
	public void render(TileEntityStatue statue, double x, double y, double z, float partialTicks,
			int destroyStage, float alpha){

		// Multiblock support for the breaking animation. The chest has its own way of doing this in
		// TileEntityRendererDispatcher, but I don't have access to that.
		if(statue.position != 1 && destroyStage >= 0){
			TileEntity tileentity = statue.getWorld().getTileEntity(statue.getPos().down(statue.position - 1));
			// System.out.println(tileentity);
			if(tileentity instanceof TileEntityStatue){
				// If this is the block breaking animation pass and this isn't the bottom block, divert the call to
				// the bottom block.
				this.render((TileEntityStatue)tileentity, x, y - (statue.position - 1), z, partialTicks,
						destroyStage, alpha);
			}
		}

		if(statue.creature != null && statue.position == 1){

			this.destroyStage = destroyStage;

			GlStateManager.pushMatrix();
			// The next line makes stuff render in the same place relative to the world wherever the player is.
			GlStateManager.translate((float)x + 0.5F, (float)y, (float)z + 0.5F);
			GlStateManager.enableLighting();

			float yaw = statue.creature.prevRotationYaw;
			int i = statue.creature.getBrightnessForRender();

			int j = i % 65536;
			int k = i / 65536;
			OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, (float)j / 1.0F, (float)k / 1.0F);
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

			GlStateManager.rotate(-yaw, 0F, 1F, 0F);
			// Stops the normal model from rendering.
			if(!statue.isIce) statue.creature.setInvisible(true);
			// Setting the last parameter to true prevents the debug bounding box from rendering.
			// For some reason, passing in the partialTicks causes the entity to spin round really fast
			Minecraft.getMinecraft().getRenderManager().renderEntity(statue.creature, 0, 0, 0, 0, 0, true);
			if(!statue.isIce) statue.creature.setInvisible(false);

			GlStateManager.popMatrix();

		}
	}

@SubscribeEvent
  public void onRenderWorldLast(RenderLevelStageEvent event) {
    if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_ENTITIES) { // was AFTER_SOLID_BLOCKS / AFTER_TRANSLUCENT_BLOCKS / AFTER_PARTICLES - testing the very last stage
      return; //send it
    }
    Minecraft mc = Minecraft.getInstance();
    Player player = mc.player;
    if (player == null) {
      return;
    }
    Level world = player.level();
    ItemStack stack = ItemStack.EMPTY;
    List<BlockPos> putBoxHere = new ArrayList<>();
    /****************** rendering outline ********************/
    stack = OreProspector.getIfHeld(player);
    if (stack.getItem() instanceof OreProspector) {
      List<BlockPosDim> coords = OreProspector.getPosition(stack);
      for (BlockPosDim loc : coords) {
        if (loc != null) {
          if (loc.getDimension() == null ||
              loc.getDimension().equalsIgnoreCase(LevelWorldUtil.dimensionToString(world))) {
            RenderBlockUtils.createBox(event.getPoseStack(), loc.getPos());
            putBoxHere.add(loc.getPos());
          }
        }
      }
    }
    /****************** end rendering outline,. start cubes ********************/
    double range = 6F;
    float alpha = 1; //0.125F * 2;
    Map<BlockPos, Color> renderCubes = new HashMap<>();
    ///////////////////// BuilderItem
    stack = BuilderItem.getIfHeld(player);
    if (stack.getItem() instanceof BuilderItem) {
      BlockHitResult lookingAt = (BlockHitResult) player.pick(range, 0F, false);
      if (!world.isEmptyBlock(lookingAt.getBlockPos())) {
        BlockPos pos = lookingAt.getBlockPos();
        BuildStyle buildStyle = ((BuilderItem) stack.getItem()).style;
        if (buildStyle.isOffset() && lookingAt.getDirection() != null) {
          pos = pos.relative(lookingAt.getDirection());
        }
        alpha = .01f;
        //now the item has a build area
        List<BlockPos> coordinates = PacketSwapBlock.getSelectedBlocks(world, pos, BuilderItem.getActionType(stack), lookingAt.getDirection(), buildStyle);
        for (BlockPos coordinate : coordinates) {
          putBoxHere.add(coordinate);
        }
      }
    }
    ///////////////////// RandomizerItem
    stack = RandomizerItem.getIfHeld(player);
    if (stack.getItem() instanceof RandomizerItem) {
      BlockHitResult lookingAt = RenderBlockUtils.getLookingAt(player, (int) range);
      if (world.getBlockState(lookingAt.getBlockPos()).isAir()) {
        return;
      }
      List<BlockPos> coords = RandomizerItem.getPlaces(lookingAt.getBlockPos(), lookingAt.getDirection(), stack);
      for (BlockPos e : coords) {
        BlockState stHere = world.getBlockState(e);
        if (!RandomizerItem.canMove(stHere, world, e) && !stHere.isAir()) {
          renderCubes.put(e, Color.RED);
        }
        else if (!stHere.isAir()) {
          putBoxHere.add(e);
        }
      }
    }
    stack = player.getMainHandItem();

    ///////////////////// LocationGpsItem
    if (stack.getItem() instanceof LocationGpsCard) {
      BlockPosDim loc = LocationGpsCard.getPosition(stack);
      if (loc != null) {
        if (loc.getDimension() == null ||
            loc.getDimension().equalsIgnoreCase(LevelWorldUtil.dimensionToString(world))) {
          renderCubes.put(loc.getPos(), ClientConfigCyclic.getColor(stack));
        }
      }
    }
    ///////////////////////////////////////ShapeCard
    if (stack.getItem() instanceof ShapeCard) {
      RelativeShape shape = RelativeShape.read(stack);
      if (shape != null) {
        BlockPos here = player.blockPosition();
        for (BlockPos s : shape.getShape()) {
          putBoxHere.add(here.offset(s));
        }
      }
    }
    //the block edge outline
    for (BlockPos coordinate : putBoxHere) {
      RenderBlockUtils.createBox(event.getPoseStack(), coordinate);
    }
    //render the pos->colour map 
    if (renderCubes.keySet().size() > 0) {
      float scale = 1;
      PoseStack matrix = event.getPoseStack();
      Vec3 view = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
      RenderBlockUtils.renderColourCubes(matrix, view, renderCubes, scale, alpha);
    }
    /****************** end rendering cubes. start laser beam render ********************/
    stack = LaserItem.getIfHeld(player);
    if (!stack.isEmpty() && player.isUsingItem()) {
      IEnergyStorage storage = CapabilityUtil.energy(stack);
      if (storage == null || storage.getEnergyStored() < ConfigRegistry.LaserItemEnergy.get()) {
        return;
      }
      // RayTraceResult  became HitResult
      // objectMouseOver became hitResult
      java.awt.Color laserColor;
      try {
        laserColor = java.awt.Color.decode(ClientConfigCyclic.LASER_COLOR.get());
      }
      catch (Exception e) {
        laserColor = new java.awt.Color(100, 0, 2);
      }
      float lr = laserColor.getRed() / 255f;
      float lg = laserColor.getGreen() / 255f;
      float lb = laserColor.getBlue() / 255f;
      if (mc.crosshairPickEntity != null) {
        //Render and Shoot. closerange version
        RenderEntityToBlockLaser.renderLaser(event, player, mc.getTimer().getGameTimeDeltaPartialTick(false), stack, InteractionHand.MAIN_HAND, 18, -0.02F, lr, lg, lb);
        if (world.getGameTime() % 4 == 0) {
          PacketDistributor.sendToServer(new PacketEntityLaser(mc.crosshairPickEntity.getId(), true));
          SoundUtil.playSound(player, SoundRegistry.LASERBEANPEW.get(), 0.2F);
        }
      }
      else {
        //out of range- do custom raytrace for longrange version
        final int laserRange = ConfigRegistry.LaserItemRange.get();
        double laserGamemodeRange = laserRange;// mc.gameMode.getPickRange() * LaserItem.RANGE_FACTOR;
        Entity camera = mc.getCameraEntity();
        Vec3 cameraViewVector = camera.getViewVector(1.0F);
        Vec3 cameraEyePosition = camera.getEyePosition(1.0F);
        Vec3 cameraEyeViewRay = cameraEyePosition.add(cameraViewVector.x * laserGamemodeRange, cameraViewVector.y * laserGamemodeRange, cameraViewVector.z * laserGamemodeRange);
        AABB aabb = camera.getBoundingBox().expandTowards(cameraViewVector.scale(laserGamemodeRange)).inflate(1.0D, 1.0D, 1.0D);
        //
        //
        EntityHitResult ehr = ProjectileUtil.getEntityHitResult(camera, cameraEyePosition, cameraEyeViewRay, aabb, (ent) -> {
          return ent.isAttackable() && ent.isAlive();
        }, 0);
        if (ehr != null) {
          Vec3 entityHitResultLocation = ehr.getLocation();
          double distance = Math.sqrt(cameraEyePosition.distanceToSqr(entityHitResultLocation));
          if (distance < laserRange) {
            //first vector is FROM, second is TO
            BlockHitResult miss = mc.level.clip(new ClipContext(cameraEyePosition, entityHitResultLocation, ClipContext.Block.VISUAL, ClipContext.Fluid.NONE, mc.player));
            if (miss.getType() != HitResult.Type.BLOCK) {
              //  dont shoot thru walls
              RenderEntityToBlockLaser.renderLaser(event, player, mc.getTimer().getGameTimeDeltaPartialTick(false), stack, InteractionHand.MAIN_HAND, lr, lg, lb);
              if (world.getGameTime() % 4 == 0) {
                PacketDistributor.sendToServer(new PacketEntityLaser(ehr.getEntity().getId(), false));
                SoundUtil.playSound(player, SoundRegistry.LASERBEANPEW.get(), 0.2F);
              }
            }
          }
        }
        else {
          //we missed. Do we render on a miss?
          if (ConfigRegistry.LaserRenderMisses.get()) {
            RenderEntityToBlockLaser.renderLaser(event, player, mc.getTimer().getGameTimeDeltaPartialTick(false), stack, InteractionHand.MAIN_HAND, lr, lg, lb);
          }
          else { //if we dont render the miss, show a message for better user experience
            ChatUtil.sendStatusMessage(player, "item.cyclic.laser_cannon.notarget");
          }
        }
      }
    }
  }

@Override
  public void renderByItem(ItemStack stackIn, ItemDisplayContext type, PoseStack ps, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
    ps.pushPose();
    ps.scale(1, -1, -1);
    boolean isBanner = stackIn.has(DataComponents.BANNER_PATTERNS);
    Material rendermaterial = isBanner ? ModelBakery.SHIELD_BASE : ModelBakery.NO_PATTERN_SHIELD;
    if (stackIn.is(ItemRegistry.SHIELD_WOOD.get())) {
      rendermaterial = isBanner ? MaterialShieldRegistry.SHIELD_BASE_WOOD : MaterialShieldRegistry.SHIELD_BASE_WOOD_NOPATTERN;
    }
    else if (stackIn.is(ItemRegistry.SHIELD_LEATHER.get())) {
      rendermaterial = isBanner ? MaterialShieldRegistry.SHIELD_BASE_LEATHER : MaterialShieldRegistry.SHIELD_BASE_LEATHER_NOPATTERN;
    }
    else if (stackIn.is(ItemRegistry.SHIELD_FLINT.get())) {
      rendermaterial = isBanner ? MaterialShieldRegistry.SHIELD_BASE_FLINT : MaterialShieldRegistry.SHIELD_BASE_FLINT_NOPATTERN;
    }
    else if (stackIn.is(ItemRegistry.SHIELD_BONE.get())) {
      rendermaterial = isBanner ? MaterialShieldRegistry.SHIELD_BASE_BONE : MaterialShieldRegistry.SHIELD_BASE_BONE_NOPATTERN;
    }
    else if (stackIn.is(ItemRegistry.SHIELD_OBSIDIAN.get())) {
      rendermaterial = isBanner ? MaterialShieldRegistry.SHIELD_BASE_OBSIDIAN : MaterialShieldRegistry.SHIELD_BASE_OBSIDIAN_NOPATTERN;
    }
    ShieldModel model = isBanner ? shieldBody : shieldNoPattern;
    var vertex = rendermaterial.sprite().wrap(ItemRenderer.getFoilBufferDirect(buffer, model.renderType(rendermaterial.atlasLocation()), true, stackIn.hasFoil()));
    model.renderToBuffer(ps, vertex, combinedLight, combinedOverlay);
    ps.popPose();
  }

public static void render(ModelResourceLocation key, float angleDeg, PoseStack matrix,
      MultiBufferSource buffers, int light, int overlay) {
    BakedModel model = Minecraft.getInstance().getModelManager().getModel(key);
    if (model == null) {
      return;
    }
    VertexConsumer vc = buffers.getBuffer(RenderType.cutout());
    matrix.pushPose();
    matrix.translate(0.5D, 0D, 0.5D);
    matrix.mulPose(Axis.YP.rotationDegrees(angleDeg));
    matrix.translate(-0.5D, 0D, -0.5D);
    PoseStack.Pose pose = matrix.last();
    for (BakedQuad q : model.getQuads(null, null, RANDOM)) {
      vc.putBulkData(pose, q, 1f, 1f, 1f, 1f, light, overlay);
    }
    for (Direction d : Direction.values()) {
      for (BakedQuad q : model.getQuads(null, d, RANDOM)) {
        vc.putBulkData(pose, q, 1f, 1f, 1f, 1f, light, overlay);
      }
    }
    matrix.popPose();
  }

public static void renderBeaconBeam(PoseStack ms, MultiBufferSource buf, ResourceLocation rl,
                                      float partial, float textureScale, long time,
                                      int yOffset, int height, float[] rgb,
                                      float innerRadius, float outerRadius) {
    int top = yOffset + height;
    ms.pushPose();
    ms.translate(0.5D, 0.0D, 0.5D);
    float f = Math.floorMod(time, 40) + partial;
    float f1 = height < 0 ? f : -f;
    float f2 = Mth.frac(f1 * 0.2F - Mth.floor(f1 * 0.1F));
    float r = rgb[0];
    float g = rgb[1];
    float b = rgb[2];
    ms.pushPose();
    ms.mulPose(Axis.YP.rotationDegrees(f * 2.25F - 45.0F));
    float f9 = -innerRadius;
    float f12 = -innerRadius;
    float f15 = -1.0F + f2;
    float f16 = height * textureScale * (0.5F / innerRadius) + f15;
    renderPart(ms, buf.getBuffer(RenderType.beaconBeam(rl, false)), r, g, b, 1.0F, yOffset, top,
        0.0F, innerRadius, innerRadius, 0.0F, f9, 0.0F, 0.0F, f12, 0.0F, 1.0F, f16, f15);
    ms.popPose();
    float f6 = -outerRadius;
    float f7 = -outerRadius;
    float f8 = -outerRadius;
    f9 = -outerRadius;
    f15 = -1.0F + f2;
    f16 = height * textureScale + f15;
    renderPart(ms, buf.getBuffer(RenderType.beaconBeam(rl, true)), r, g, b, 0.125F, yOffset, top,
        f6, f7, outerRadius, f8, f9, outerRadius, outerRadius, outerRadius, 0.0F, 1.0F, f16, f15);
    ms.popPose();
  }

