static void updateBeam(Level level, BlockPos pos, BeamStuff beamStuff) {
    BlockPos blockpos;
    if (beamStuff.lastCheckY < pos.getY()) {
      blockpos = pos;
      beamStuff.checkingBeamSections = new ArrayList<>();
      beamStuff.lastCheckY = pos.getY() - 1;
    }
    else {
      blockpos = new BlockPos(pos.getX(), beamStuff.lastCheckY + 1, pos.getZ());
    }
    BeaconBlockEntity.BeaconBeamSection currentSection = beamStuff.checkingBeamSections.isEmpty()
        ? null
        : beamStuff.checkingBeamSections.get(beamStuff.checkingBeamSections.size() - 1);
    int surfaceHeight = level.getHeight(Heightmap.Types.WORLD_SURFACE, pos.getX(), pos.getZ());
    for (int yLoop = 0; yLoop < 10 && blockpos.getY() <= surfaceHeight; ++yLoop) {
      BlockState blockstate = level.getBlockState(blockpos);
      if (blockstate.getBlock() instanceof BeaconBeamBlock beamBlock) {
        int beamColor = beamBlock.getColor().getTextureDiffuseColor();
        if (beamStuff.checkingBeamSections.size() <= 1) {
          currentSection = new BeaconBlockEntity.BeaconBeamSection(beamColor);
          beamStuff.checkingBeamSections.add(currentSection);
        }
        else if (currentSection != null) {
          if (beamColor == currentSection.getColor()) {
            currentSection.increaseHeight();
          }
          else {
            int blended = FastColor.ARGB32.average(currentSection.getColor(), beamColor);
            currentSection = new BeaconBlockEntity.BeaconBeamSection(blended);
            beamStuff.checkingBeamSections.add(currentSection);
          }
        }
      }
      else {
        if (currentSection == null
            || (blockstate.getLightBlock(level, blockpos) >= 15 && !blockstate.is(Blocks.BEDROCK))) {
          beamStuff.checkingBeamSections.clear();
          beamStuff.lastCheckY = surfaceHeight;
          break;
        }
        currentSection.increaseHeight();
      }
      blockpos = blockpos.above();
      ++beamStuff.lastCheckY;
    }
    if (level.getGameTime() % 80L == 0L) {
      if (!beamStuff.beamSections.isEmpty()) {
        SoundUtil.playSound(level, pos, SoundEvents.BEACON_AMBIENT);
      }
    }
    if (beamStuff.lastCheckY >= surfaceHeight) {
      beamStuff.lastCheckY = level.getMinBuildHeight() - 1;
      beamStuff.beamSections = beamStuff.checkingBeamSections;
    }
  }

@Override
  public void render(T tile, float partial, PoseStack ms, MultiBufferSource buf, int light, int overlay) {
    if (!tile.isBeamActive()) {
      return;
    }
    long time = tile.getLevel().getGameTime();
    List<BeaconBlockEntity.BeaconBeamSection> sections = tile.getBeamSections();
    int yOffset = 0;
    for (int k = 0; k < sections.size(); ++k) {
      BeaconBlockEntity.BeaconBeamSection section = sections.get(k);
      int height = (k == sections.size() - 1) ? 1024 : section.getHeight();
      BeaconBeamRenderer.drawBeam(ms, buf, partial, time, yOffset, height, section.getColor());
      yOffset += section.getHeight();
    }
  }

@Override
    public void tick() {
        super.tick();
        setSpriteFromAge(this.sprites);
        updateColors();

        if (age > this.delay) {
//            Vec2 n = new Vec2((float) (tarX - x), (float) (tarZ - z)).normalized().scale(0.1f + 1.2f * (1 - 1f * age / lifetime));
            Vec2 n = new Vec2((float) (tarX - x), (float) (tarZ - z)).scale(getApproxNormScale((float) (tarX - x), (float) (tarZ - z)));
            n = n.scale(getApproxNormScale(n.x, n.y) * 0.5f);
            if (age < lifetime - 10) {
                n = new Vec2((float) (tarX - x - n.y), (float) (tarZ - z + n.x));
                n = n.scale(getApproxNormScale(n.x, n.y));
            }
            xd = xd * 0.85 + n.x * 0.04;
            zd = zd * 0.85 + n.y * 0.04;

            yd = yd * 0.9 + (tarY - y + Math.sin(age / 10f + lifetime) * 0.2) * 0.005;
        } else {
            xd = xd * 0.95;
            yd = yd * 0.95;
            zd = zd * 0.95;
        }
    }

@Override
	public void render(T entity, float yaw, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
		matrices.push();
		matrices.translate(0, -1, 0);
		matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(90 - yaw + 90));
		matrices.translate(0, 0, -0.35);
		model.setAngles(entity, yaw, 0, entity.age + entity.getId(), 0, 0);
		model.render(matrices, vertexConsumers.getBuffer(model.getLayer(getTexture(entity))), light, OverlayTexture.DEFAULT_UV, 1, 1, 1, 1);
		matrices.pop();
		super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
	}

