@Override
	public void render(BrazierBlockEntity entity, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay) {
		double yOffset = entity.getCachedState().get(Properties.HANGING) ? -0.815 : 0;
		matrices.translate(0.5, 0.925 + yOffset, 0.5);
		matrices.scale(0.5f, 0.5f, 0.5f);
		for (int i = 0; i < 4; i++) {
			matrices.translate(0, 0.06, 0);
			matrices.push();
			matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees((90 + (180 * i)) % 360));
			matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(90 * i));
			MinecraftClient.getInstance().getItemRenderer().renderItem(entity.getStack(i), ModelTransformationMode.FIXED, light, overlay, matrices, vertexConsumers, entity.getWorld(), 0);
			matrices.pop();
		}
	}

@Override
	public void render(PoppetShelfBlockEntity entity, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay) {
		Direction direction = entity.getCachedState().get(Properties.HORIZONTAL_FACING);
		float rotation = -direction.asRotation();
		matrices.translate(0.5f, 0, 0.5f);
		matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(rotation));
		matrices.scale(1 / 5f, 1 / 5f, 1 / 5f);
		renderRow(entity.getWorld(), entity.clientInventory.get(0), entity.clientInventory.get(1), entity.clientInventory.get(2), 0.8f, matrices, vertexConsumers, light, overlay);
		renderRow(entity.getWorld(), entity.clientInventory.get(3), entity.clientInventory.get(4), entity.clientInventory.get(5), 0.5f, matrices, vertexConsumers, light, overlay);
		renderRow(entity.getWorld(), entity.clientInventory.get(6), entity.clientInventory.get(7), entity.clientInventory.get(8), 0.2f, matrices, vertexConsumers, light, overlay);
	}

private static void renderRow(World world, ItemStack one, ItemStack two, ItemStack three, float yOffset, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay) {
		matrices.push();
		double xOffset = 0.32 * 5;
		double zOffset = 0.45 * 5;
		yOffset *= 5;
		matrices.translate(0, yOffset, zOffset);
		MinecraftClient.getInstance().getItemRenderer().renderItem(two, ModelTransformationMode.FIXED, light, overlay, matrices, vertexConsumers, world, 0);
		matrices.translate(xOffset, 0, 0);
		MinecraftClient.getInstance().getItemRenderer().renderItem(one, ModelTransformationMode.FIXED, light, overlay, matrices, vertexConsumers, world, 0);
		matrices.translate(-xOffset * 2, 0, 0);
		MinecraftClient.getInstance().getItemRenderer().renderItem(three, ModelTransformationMode.FIXED, light, overlay, matrices, vertexConsumers, world, 0);
		matrices.pop();
	}

@Override
	public void render(WitchAltarBlockEntity entity, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay) {
		matrices.translate(0.5, 1, 0.5);
		Direction direction = entity.getCachedState().get(Properties.HORIZONTAL_FACING);
		float rotation = direction.asRotation() + ((direction == Direction.WEST || direction == Direction.EAST) ? 180 : 0); // Offset rotation when facing WEST or EAST
		matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(rotation));
		ItemStack sword = entity.getStack(0);
		ItemStack pentacle = entity.getStack(1);
		ItemStack wand = entity.getStack(2);
		matrices.push();
		renderStack(entity.getWorld(), matrices, vertexConsumers, light, overlay, 0.25f, -0.25f, sword, direction);
		matrices.pop();
		matrices.push();
		renderStack(entity.getWorld(), matrices, vertexConsumers, light, overlay, 0f, 0.25f, pentacle, direction);
		matrices.pop();
		matrices.push();
		renderStack(entity.getWorld(), matrices, vertexConsumers, light, overlay, -0.25f, -0.25f, wand, direction);
		matrices.pop();
	}

private void renderStack(World world, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay, float x, float z, ItemStack stack, Direction direction) {
		if (stack.isIn(BWTags.SKULLS)) {
			matrices.translate(x, 0.125, z);
			matrices.scale(0.5f, 0.5f, 0.5f);
		} else if (stack.getItem() instanceof BlockItem blockItem) {
			matrices.translate(x + 0.25, 0, z - 0.25);
			matrices.scale(0.5f, 0.5f, 0.5f);
			matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-90));
			BlockState state = blockItem.getBlock().getDefaultState();
			if (state.getProperties().contains(Properties.HORIZONTAL_FACING)) {
				state = state.with(Properties.HORIZONTAL_FACING, direction.getOpposite());
			}
			if (state.getProperties().contains(Properties.FACING)) {
				state = state.with(Properties.FACING, Direction.UP);
			}
			MinecraftClient.getInstance().getBlockRenderManager().getModelRenderer().render(matrices.peek(), vertexConsumers.getBuffer(RenderLayers.getEntityBlockLayer(state, false)), state, MinecraftClient.getInstance().getBlockRenderManager().getModels().getModel(state), 1, 1, 1, light, overlay);
			return;
		} else {
			matrices.translate(x, 0.01, z);
			matrices.scale(1 / 3f, 1 / 3f, 1 / 3f);
			matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(90));
		}
		MinecraftClient.getInstance().getItemRenderer().renderItem(stack, ModelTransformationMode.FIXED, light, overlay, matrices, vertexConsumers, world, 0);
	}

@Override
	public void render(WitchCauldronBlockEntity entity, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay) {
		World world = entity.getWorld();
		if (world != null) {
			BlockPos pos = entity.getPos();
			renderName(entity.name, pos, matrices, vertexConsumers, light);
			int level = entity.getCachedState().get(BWProperties.LEVEL);
			if (level > 0) {
				matrices.push();
				matrices.translate(0, HEIGHT[level], 0);
				if (entity.mode == WitchCauldronBlockEntity.Mode.TELEPORTATION) {
					renderPortal(matrices, vertexConsumers);
				}
				renderWater(entity.color, matrices, vertexConsumers, light, overlay, SpriteIdentifiers.CAULDRON_WATER.getSprite());
				matrices.pop();
				if (entity.heatTimer >= 60 && !MinecraftClient.getInstance().isPaused()) {
					float fluidHeight = 0;
					float width = 0.35f;
					switch (entity.getCachedState().get(BWProperties.LEVEL)) {
						case 1 -> fluidHeight = 0.225f;
						case 2 -> {
							fluidHeight = 0.425f;
							width = 0.3f;
						}
						case 3 -> fluidHeight = 0.625f;
					}
					if (fluidHeight > 0) {
						if (entity.mode == WitchCauldronBlockEntity.Mode.TELEPORTATION) {
							world.addParticle(new DustParticleEffect(new Vector3f(((entity.color >> 16) & 0xff) / 255f, ((entity.color >> 8) & 0xff) / 255f, (entity.color & 0xff) / 255f), 1), pos.getX() + 0.5 + MathHelper.nextDouble(world.random, -width, width), pos.getY() + fluidHeight, pos.getZ() + 0.5 + MathHelper.nextDouble(world.random, -width, width), 0, 0, 0);
						}
						if (entity.mode == WitchCauldronBlockEntity.Mode.OIL_CRAFTING && entity.color != 0xfc00fc) {
							world.addParticle(ParticleTypes.ENCHANTED_HIT, pos.getX() + 0.5 + MathHelper.nextDouble(world.random, -width, width), pos.getY() + fluidHeight, pos.getZ() + 0.5 + MathHelper.nextDouble(world.random, -width, width), 0, 0, 0);
						}
						if (entity.mode == WitchCauldronBlockEntity.Mode.BREWING) {
							world.addParticle(ParticleTypes.ENTITY_EFFECT, pos.getX() + 0.5 + MathHelper.nextDouble(world.random, -width, width), pos.getY() + fluidHeight, pos.getZ() + 0.5 + MathHelper.nextDouble(world.random, -width, width), ((entity.color >> 16) & 0xff) / 255f, ((entity.color >> 8) & 0xff) / 255f, (entity.color & 0xff) / 255f);
						}
						world.addParticle((ParticleEffect) BWParticleTypes.CAULDRON_BUBBLE, pos.getX() + 0.5 + MathHelper.nextDouble(world.random, -width, width), pos.getY() + fluidHeight, pos.getZ() + 0.5 + MathHelper.nextDouble(world.random, -width, width), ((entity.color >> 16) & 0xff) / 255f, ((entity.color >> 8) & 0xff) / 255f, (entity.color & 0xff) / 255f);
					}
				}
			}
		}
	}

private void renderName(String name, BlockPos pos, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
		if (name != null && pos.getSquaredDistance(MinecraftClient.getInstance().getEntityRenderDispatcher().camera.getPos()) <= 256) {
			int x = -MinecraftClient.getInstance().textRenderer.getWidth(name) / 2;
			matrices.push();
			Matrix4f mat = matrices.peek().getPositionMatrix();
			matrices.translate(0.5, 1, 0.5);
			matrices.multiply(MinecraftClient.getInstance().getEntityRenderDispatcher().camera.getRotation());
			matrices.scale(-0.025f, -0.025f, 0.025f);
			MinecraftClient.getInstance().textRenderer.draw(name, x, 0, 0x20FFFFFF, false, mat, vertexConsumers, TextRenderer.TextLayerType.SEE_THROUGH, (int) (MinecraftClient.getInstance().options.getTextBackgroundOpacity(0.25f) * 255f) << 24, light);
			MinecraftClient.getInstance().textRenderer.draw(name, x, 0, -1, false, mat, vertexConsumers, TextRenderer.TextLayerType.NORMAL, 0, light);
			matrices.pop();
		}
	}

private void renderWater(int color, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light, int overlay, Sprite sprite) {
		float sizeFactor = 0.125F;
		float maxV = (sprite.getMaxV() - sprite.getMinV()) * sizeFactor;
		float minV = (sprite.getMaxV() - sprite.getMinV()) * (1 - sizeFactor);
		int red = (color >> 16) & 0xFF;
		int green = (color >> 8) & 0xFF;
		int blue = color & 0xFF;
		matrices.push();
		Matrix4f mat = matrices.peek().getPositionMatrix();
		VertexConsumer vertexConsumer = vertexConsumers.getBuffer(RenderLayer.getTranslucent());
		vertexConsumer.vertex(mat, sizeFactor, 0, 1 - sizeFactor).color(red, green, blue, 255).texture(sprite.getMinU(), sprite.getMinV() + maxV).light(light).overlay(overlay).normal(1, 1, 1).next();
		vertexConsumer.vertex(mat, 1 - sizeFactor, 0, 1 - sizeFactor).color(red, green, blue, 255).texture(sprite.getMaxU(), sprite.getMinV() + maxV).light(light).overlay(overlay).normal(1, 1, 1).next();
		vertexConsumer.vertex(mat, 1 - sizeFactor, 0, sizeFactor).color(red, green, blue, 255).texture(sprite.getMaxU(), sprite.getMinV() + minV).light(light).overlay(overlay).normal(1, 1, 1).next();
		vertexConsumer.vertex(mat, sizeFactor, 0, sizeFactor).color(red, green, blue, 255).texture(sprite.getMinU(), sprite.getMinV() + minV).light(light).overlay(overlay).normal(1, 1, 1).next();
		matrices.pop();
	}

@Override
	public void render(HornedSpearEntity entity, float yaw, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
		ItemStack spear = entity.spear;
		if (spear.isEmpty()) {
			spear = HerneEntityModel.HORNED_SPEAR;
		}
		matrices.push();
		matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(MathHelper.lerp(tickDelta, entity.prevYaw, entity.getYaw()) - 90));
		matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(MathHelper.lerp(tickDelta, entity.prevPitch, entity.getPitch()) + 225));
		matrices.scale(1.5f, 1.5f, 1.5f);
		MinecraftClient.getInstance().getItemRenderer().renderItem(spear, ModelTransformationMode.FIXED, light, OverlayTexture.DEFAULT_UV, matrices, vertexConsumers, entity.getWorld(), 0);
		matrices.pop();
		super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
	}

@Override
