	}

@Override
	public void render(ApothecaryMortarBlockEntity tile, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight,
			int packedOverlay) {
		Direction direction = tile.getBlockState().getValue(ApothecaryMortarBlock.FACING);
		float horizontalRotation = direction == Direction.UP ? 0F : direction.get2DDataValue() * 90F;

		NonNullList<ItemStack> mortarItems = tile.getItemStacks();

		poseStack.pushPose();
		poseStack.translate(0.5D, 0.3D, 0.5D);
		poseStack.mulPose(Axis.YN.rotationDegrees(horizontalRotation));

		renderMortarItem(poseStack, buffer, packedLight, () -> {
			poseStack.mulPose(Axis.ZP.rotationDegrees(40F));
			poseStack.mulPose(Axis.YP.rotationDegrees(90F));
		}, mortarItems.get(0), -0.09F, 0F, packedOverlay);

		renderMortarItem(poseStack, buffer, packedLight, () -> {
			poseStack.mulPose(Axis.XP.rotationDegrees(40F));
			poseStack.mulPose(Axis.YP.rotationDegrees(180F));
		}, mortarItems.get(1), 0F, 0.09F, packedOverlay);

		renderMortarItem(poseStack, buffer, packedLight, () -> {
			poseStack.mulPose(Axis.ZN.rotationDegrees(40F));
			poseStack.mulPose(Axis.YP.rotationDegrees(270F));
		}, mortarItems.get(2), 0.09F, 0F, packedOverlay);

		poseStack.popPose();
	}

private void renderMortarItem(PoseStack poseStack, MultiBufferSource buffer, int packedLight, Runnable processRotationTransforms, ItemStack itemToRender,
			float translateX, float translateZ, int packedOverlay) {
		if (!itemToRender.isEmpty()) {
			poseStack.pushPose();
			poseStack.translate(translateX, 0F, translateZ);
			processRotationTransforms.run();
			poseStack.scale(0.60F, 0.60F, 0.60F);
			Minecraft.getInstance().getItemRenderer().renderStatic(itemToRender, ItemDisplayContext.GROUND, packedLight, packedOverlay, poseStack, buffer, null,
					0);
			poseStack.popPose();
		}
	}

@Override
	public void render(PassivePedestalBlockEntity te, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight, int packedOverlay) {
		if (!te.getItem().isEmpty()) {
			ItemStack stack = te.getItem();
			poseStack.pushPose();
			float yDiff = Mth.sin((System.currentTimeMillis() % 86400000) / 1000F) * 0.1F + 0.1F;
			poseStack.translate(0.5D, 0.9D + yDiff, 0.5D);
			float f3 = ((System.currentTimeMillis() % 86400000) / 2000F) * (180F / (float) Math.PI);
			poseStack.mulPose(Axis.YP.rotationDegrees(f3));
			poseStack.scale(0.75F, 0.75F, 0.75F);
			Minecraft.getInstance().getItemRenderer().renderStatic(stack, ItemDisplayContext.GROUND, packedLight, OverlayTexture.NO_OVERLAY, poseStack, buffer,
					null, 0);
			poseStack.popPose();
		}
	}

private void renderHook(PedestalBlockEntity te, PoseStack poseStack, MultiBufferSource buffer, int packedLight, Object itemData) {
		LocalPlayer player = Minecraft.getInstance().player;
		if (player == null || !(itemData instanceof HookRenderingData hookData)) {
			return;
		}

		double translateX = hookData.hookX - te.getBlockPos().getX();
		double translateY = hookData.hookY - te.getBlockPos().getY();
		double translateZ = hookData.hookZ - te.getBlockPos().getZ();

		poseStack.pushPose();
		poseStack.translate(translateX, translateY, translateZ);
		poseStack.pushPose();
		poseStack.scale(0.5F, 0.5F, 0.5F);
		poseStack.mulPose(Axis.YN.rotationDegrees(player.yHeadRot + 180F));

		PoseStack.Pose pose = poseStack.last();
		VertexConsumer vertexBuilder = buffer.getBuffer(ENTITY_CUTOUT);

		addVertex(vertexBuilder, pose, packedLight, 0.0F, 0, 0, 1);
		addVertex(vertexBuilder, pose, packedLight, 1.0F, 0, 1, 1);
		addVertex(vertexBuilder, pose, packedLight, 1.0F, 1, 1, 0);
		addVertex(vertexBuilder, pose, packedLight, 0.0F, 1, 0, 0);
		poseStack.popPose();

		double pedestalX = te.getBlockPos().getX() + 0.5D;
		double pedestalY = te.getBlockPos().getY() + 0.45D;
		double pedestalZ = te.getBlockPos().getZ() + 0.5D;

		double hookX = hookData.hookX;
		double hookY = hookData.hookY;
		double hookZ = hookData.hookZ;

		float xDiff = (float) (pedestalX - hookX);
		float yDiff = (float) (pedestalY - hookY);
		float zDiff = (float) (pedestalZ - hookZ);

		VertexConsumer vertextConsumer2 = buffer.getBuffer(RenderType.lineStrip());
		pose = poseStack.last();

		for (int k = 0; k < 16; ++k) {
			stringVertex(xDiff, yDiff, zDiff, vertextConsumer2, pose, (float) k / (float) 16, (float) (k + 1) / (float) 16);
		}

		poseStack.popPose();
	}

