@SubscribeEvent
    public static void RenderWorldLast(RenderLevelStageEvent event) {
        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS) {
            return;
        }
        Minecraft minecraft = Minecraft.getInstance();
        Player player = minecraft.player;
        ClientLevel level = minecraft.level;
        if (level != null) {
            List<AbstractClientPlayer> players = level.players();
            if (player != null) {
                Level world = player.level;
                Map<BlockPos, ColorUtil> renderCubes = new HashMap<>();
                if (player.isHolding(itemStack -> itemStack.getItem() instanceof IShowOutlines)) {
                    for (InteractionHand hand : InteractionHand.values()) {
                        ItemStack stack = player.getItemInHand(hand);
                        if (stack.getItem() instanceof WaystoneItem) {
                            if (stack.getTag() != null) {
                                GlobalPos loc = WaystoneItem.getPosition(stack);
                                if (loc != null) {
                                    if (loc.dimension() == world.dimension()) {
                                        renderCubes.put(loc.pos(), CUBE_COLOR);
                                    }
                                }
                            }
                        }
                        if (stack.getItem() instanceof IPosHolder) {
                            if (stack.getTag() != null) {
                                GlobalPos loc = IPosHolder.getPosition(stack);
                                if (loc != null) {
                                    if (loc.dimension() == world.dimension()) {
                                        renderCubes.put(loc.pos(), CUBE_COLOR);
                                    }
                                }
                            }
                        }
                        if (stack.getItem() instanceof PatrolPlan) {
                            if (stack.getTag() != null) {
                                if (!PatrolPlan.getList(stack).isEmpty()) {
                                    for (GlobalPos pos : PatrolPlan.getList(stack)) {
                                        if (pos.dimension() == world.dimension()) {
                                            renderCubes.put(pos.pos(), CUBE_COLOR);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                if (!renderCubes.keySet().isEmpty()) {
                    PoseStack matrix = event.getPoseStack();
                    Vec3 view = minecraft.gameRenderer.getMainCamera().getPosition();
                    RenderBlockUtils.renderColourCubes(matrix, view, renderCubes, 1.0F, 1.0F);
                }
                for (Player player1 : players) {
                    if (player1.distanceToSqr(player) > 500.0F) {
                        continue;
                    }

                    if (player1.isUsingItem()) {
                        if (WandUtil.getSpell(player1) instanceof BurrowingSpell) {
                            BurrowingLaserRenderer.renderLaser(event, player1, minecraft.getFrameTime());
                        } else if (WandUtil.getSpell(player1) instanceof PrismaBeamSpell) {
                            PrismaBeamRenderer.renderLaser(event, player1, minecraft.getFrameTime());
                        } else if (WandUtil.getSpell(player1) instanceof WaterJetSpell) {
                            WaterJetRenderer.renderWaterJet(event, player1, minecraft.getFrameTime());
                        }
                    }
                }
            }
        }
    }

@SubscribeEvent
    public static void renderBeams(RenderLevelStageEvent event) {
        if (event.getStage() == RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS) {
            Minecraft minecraft = Minecraft.getInstance();
            ClientLevel level = minecraft.level;
            if (level != null) {
                float partialTick = event.getPartialTick();
                Vec3 origin = event.getCamera().getPosition();
                Frustum frustum = event.getFrustum();
                MultiBufferSource.BufferSource bufferSource = minecraft.renderBuffers().bufferSource();
                CorruptedBeamRenderer.renderQueued(bufferSource);
                boolean drewAny = false;

                for (Entity entity : level.entitiesForRendering()) {
                    if (!(entity instanceof LivingEntity enchanted) || enchanted.isRemoved()) {
                        continue;
                    }
                    Entity enchanter = MiscCapHelper.getEnchanter(enchanted);
                    if (enchanter == null || enchanter.isRemoved()) {
                        continue;
                    }
                    Vec3 target = getTargetPos(enchanted, partialTick);
                    Vec3 source = getSourcePos(enchanter, partialTick);
                    if (!frustum.isVisible(beamBounds(source, target))) {
                        continue;
                    }
                    renderBeam(enchanted, source, target, origin, partialTick, event.getPoseStack(), bufferSource);
                    drewAny = true;
                }

                if (drewAny) {
                    bufferSource.endBatch(ModRenderType.enchantedBeam(BEAM_TEXTURE));
                }
            }
        }
    }

private static void renderRibbon(Vec3 origin, Vec3 from, Vec3 to, float arcPhase, float width, int argb, PoseStack poseStack, VertexConsumer consumer) {
        double distance = to.distanceTo(from);
        if (distance < 1.0E-4D) {
            return;
        }

        Vec3 camera = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        double arc = Mth.sin(arcPhase * Mth.PI) * ARC_AMOUNT * distance;
        Vec3 tangent0 = new Vec3(0.0D, arc, 0.0D);
        Vec3 tangent1 = new Vec3(0.0D, -0.125D * distance, 0.0D);

        Matrix4f pose = poseStack.last().pose();
        float half = width * 0.5F;
        Vec3 previous = from;

        for (int i = 0; i < SEGMENTS; ++i) {
            float t0 = (float) i / SEGMENTS;
            float t1 = (float) (i + 1) / SEGMENTS;
            Vec3 current = hermite(from, to, tangent0, tangent1, t1);

            Vec3 segment = current.subtract(previous);
            Vec3 toCamera = previous.subtract(camera);
            if (segment.lengthSqr() < 1.0E-8D || toCamera.lengthSqr() < 1.0E-8D) {
                previous = current;
                continue;
            }

            Vec3 side = segment.normalize().cross(toCamera.normalize());
            if (side.lengthSqr() < 1.0E-8D) {
                previous = current;
                continue;
            }
            side = side.normalize().scale(half);

            float v0 = t0 * (float) distance * UV_TILING;
            float v1 = t1 * (float) distance * UV_TILING;

            vertexAt(consumer, pose, previous.add(side).subtract(origin), 0.0F, v0, argb);
            vertexAt(consumer, pose, previous.subtract(side).subtract(origin), 1.0F, v0, argb);
            vertexAt(consumer, pose, current.subtract(side).subtract(origin), 1.0F, v1, argb);
            vertexAt(consumer, pose, current.add(side).subtract(origin), 0.0F, v1, argb);

            previous = current;
        }
    }

public void createResult() {
        ItemStack itemstack = this.inputSlots.getItem(0);
        this.cost.set(1);
        int i = 0;
        int j = 0;
        int k = 0;
        if (itemstack.isEmpty()) {
            this.resultSlots.setItem(0, ItemStack.EMPTY);
            this.cost.set(0);
        } else {
            ItemStack itemstack1 = itemstack.copy();
            ItemStack itemstack2 = this.inputSlots.getItem(1);
            Map<Enchantment, Integer> map = EnchantmentHelper.getEnchantments(itemstack1);
            j += itemstack.getBaseRepairCost() + (itemstack2.isEmpty() ? 0 : itemstack2.getBaseRepairCost());
            this.repairItemCountCost = 0;
            boolean flag = false;

            if (!net.minecraftforge.common.ForgeHooks.onAnvilChange(this, itemstack, itemstack2, resultSlots, itemName, j, this.player)) return;
            if (!itemstack2.isEmpty()) {
                flag = itemstack2.getItem() == Items.ENCHANTED_BOOK && !EnchantedBookItem.getEnchantments(itemstack2).isEmpty();
                if (itemstack1.isDamageableItem() && itemstack1.getItem().isValidRepairItem(itemstack, itemstack2)) {
                    int l2 = Math.min(itemstack1.getDamageValue(), itemstack1.getMaxDamage() / 4);
                    if (l2 <= 0) {
                        this.resultSlots.setItem(0, ItemStack.EMPTY);
                        this.cost.set(0);
                        return;
                    }

                    int i3;
                    for(i3 = 0; l2 > 0 && i3 < itemstack2.getCount(); ++i3) {
                        int j3 = itemstack1.getDamageValue() - l2;
                        itemstack1.setDamageValue(j3);
                        ++i;
                        l2 = Math.min(itemstack1.getDamageValue(), itemstack1.getMaxDamage() / 4);
                    }

                    this.repairItemCountCost = i3;
                } else {
                    if (!flag && (!itemstack1.is(itemstack2.getItem()) || !itemstack1.isDamageableItem())) {
                        this.resultSlots.setItem(0, ItemStack.EMPTY);
                        this.cost.set(0);
                        return;
                    }

                    if (itemstack1.isDamageableItem() && !flag) {
                        int l = itemstack.getMaxDamage() - itemstack.getDamageValue();
                        int i1 = itemstack2.getMaxDamage() - itemstack2.getDamageValue();
                        int j1 = i1 + itemstack1.getMaxDamage() * 12 / 100;
                        int k1 = l + j1;
                        int l1 = itemstack1.getMaxDamage() - k1;
                        if (l1 < 0) {
                            l1 = 0;
                        }

                        if (l1 < itemstack1.getDamageValue()) {
                            itemstack1.setDamageValue(l1);
                            i += 2;
                        }
                    }

                    Map<Enchantment, Integer> map1 = EnchantmentHelper.getEnchantments(itemstack2);
                    boolean flag2 = false;
                    boolean flag3 = false;

                    for(Enchantment enchantment1 : map1.keySet()) {
                        if (enchantment1 != null) {
                            int i2 = map.getOrDefault(enchantment1, 0);
                            int j2 = map1.get(enchantment1);
                            j2 = i2 == j2 ? j2 + 1 : Math.max(j2, i2);
                            boolean flag1 = enchantment1.canEnchant(itemstack);
                            if (this.player.getAbilities().instabuild || itemstack.is(Items.ENCHANTED_BOOK)) {
                                flag1 = true;
                            }

                            for(Enchantment enchantment : map.keySet()) {
                                if (enchantment != enchantment1 && !enchantment1.isCompatibleWith(enchantment)) {
                                    flag1 = false;
                                    ++i;
                                }
                            }

                            if (!flag1) {
                                flag3 = true;
                            } else {
                                flag2 = true;
                                if (!MainConfig.DarkAnvilIgnoreMaxLevels.get() && j2 > enchantment1.getMaxLevel()) {
                                    j2 = enchantment1.getMaxLevel();
                                }

                                int maxLevel = Math.max(map.getOrDefault(enchantment1, 0), map1.get(enchantment1));
                                maxLevel = Math.max(maxLevel, j2);
                                if (maxLevel != j2) {
                                    j2 = maxLevel;
                                }

                                map.put(enchantment1, j2);
                                int k3 = switch (enchantment1.getRarity()) {
                                    case COMMON -> 1;
                                    case UNCOMMON -> 2;
                                    case RARE -> 4;
                                    case VERY_RARE -> 8;
                                };

                                if (flag) {
                                    k3 = Math.max(1, k3 / 2);
                                }

                                i += k3 * j2;
                                if (itemstack.getCount() > 1) {
                                    i = MainConfig.DarkAnvilRepairCost.get();
                                }
                            }
                        }
                    }

                    if (flag3 && !flag2) {
                        this.resultSlots.setItem(0, ItemStack.EMPTY);
                        this.cost.set(0);
                        return;
                    }
                }
            }

            if (this.itemName != null && !Util.isBlank(this.itemName)) {
                if (!this.itemName.equals(itemstack.getHoverName().getString())) {
                    k = 1;
                    i += k;
                    itemstack1.setHoverName(Component.literal(this.itemName));
                }
            } else if (itemstack.hasCustomHoverName()) {
                k = 1;
                i += k;
                itemstack1.resetHoverName();
            }
            if (flag && !itemstack1.isBookEnchantable(itemstack2)) {
                itemstack1 = ItemStack.EMPTY;
            }

            this.cost.set(j + i);
            if (i <= 0) {
                itemstack1 = ItemStack.EMPTY;
            }

            if (this.cost.get() > MainConfig.DarkAnvilRepairCost.get()){
                this.cost.set(MainConfig.DarkAnvilRepairCost.get());
            }

            if (k == i && k > 0) {
                this.cost.set(1);
            }

            if (MainConfig.DarkAnvilCap.get() && this.cost.get() >= MainConfig.DarkAnvilRepairCost.get() && !this.player.getAbilities().instabuild) {
                itemstack1 = ItemStack.EMPTY;
            }

            if (!itemstack1.isEmpty()) {
                int k2 = itemstack1.getBaseRepairCost();
                if (!itemstack2.isEmpty() && k2 < itemstack2.getBaseRepairCost()) {
                    k2 = itemstack2.getBaseRepairCost();
                }

                if (k != i || k == 0) {
                    k2 = calculateIncreasedRepairCost(k2);
                }

                itemstack1.setRepairCost(k2);
                EnchantmentHelper.setEnchantments(map, itemstack1);
            }

            this.resultSlots.setItem(0, itemstack1);
            this.broadcastChanges();
        }
    }

