        PoseStack.Pose pose = stack.last();
        if (smoothAge < lifetime) {
            float flashProgress = Easing.IN_OUT_SINE.calculate(1 - Math.abs(smoothAge - halfLife) / halfLife);
            float flashDistFromCenter = Mth.lerp(flashProgress, smoothAge < halfLife ? 0.75f : 0.9f, 0.65f);
            float flashHeight = 2.5f * flashProgress;

            int baseColor = FastColor.ARGB32.color(Math.round(Mth.lerp(flashProgress, 0.5F, 1.0F) * 255), Math.round(rCol * 255), Math.round(gCol * 255), Math.round(bCol * 255));
            int topColor = FastColor.ARGB32.color(0, Math.round(rCol * 255), Math.round(gCol * 255), Math.round(bCol * 255));

            buffer.vertex(pose.pose(), -flashDistFromCenter, 0, -flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), -flashDistFromCenter, 0, flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), -flashDistFromCenter, flashHeight, flashDistFromCenter).color(topColor).endVertex();
            buffer.vertex(pose.pose(), -flashDistFromCenter, flashHeight, -flashDistFromCenter).color(topColor).endVertex();

            buffer.vertex(pose.pose(), -flashDistFromCenter, 0, -flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, 0, -flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, flashHeight, -flashDistFromCenter).color(topColor).endVertex();
            buffer.vertex(pose.pose(), -flashDistFromCenter, flashHeight, -flashDistFromCenter).color(topColor).endVertex();

            buffer.vertex(pose.pose(), flashDistFromCenter, 0, -flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, 0, flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, flashHeight, flashDistFromCenter).color(topColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, flashHeight, -flashDistFromCenter).color(topColor).endVertex();

            buffer.vertex(pose.pose(), -flashDistFromCenter, 0, flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, 0, flashDistFromCenter).color(baseColor).endVertex();
            buffer.vertex(pose.pose(), flashDistFromCenter, flashHeight, flashDistFromCenter).color(topColor).endVertex();
            buffer.vertex(pose.pose(), -flashDistFromCenter, flashHeight, flashDistFromCenter).color(topColor).endVertex();
        }
        stack.popPose();
    }

public void renderRotatedParticle(VertexConsumer p_233989_, Camera p_233990_, float p_233991_, Consumer<Quaternionf> p_233992_) {
        Vec3 vec3 = p_233990_.getPosition();
        float f = (float)(Mth.lerp((double)p_233991_, this.xo, this.x) - vec3.x());
        float f1 = (float)(Mth.lerp((double)p_233991_, this.yo, this.y) - vec3.y());
        float f2 = (float)(Mth.lerp((double)p_233991_, this.zo, this.z) - vec3.z());
        Quaternionf quaternionf = (new Quaternionf()).setAngleAxis(0.0F, ROTATION_VECTOR.x(), ROTATION_VECTOR.y(), ROTATION_VECTOR.z());
        p_233992_.accept(quaternionf);
        quaternionf.transform(TRANSFORM_VECTOR);
        Vector3f[] avector3f = new Vector3f[]{new Vector3f(-1.0F, -1.0F, 0.0F), new Vector3f(-1.0F, 1.0F, 0.0F), new Vector3f(1.0F, 1.0F, 0.0F), new Vector3f(1.0F, -1.0F, 0.0F)};
        float f3 = this.getQuadSize(p_233991_);

        for(int i = 0; i < 4; ++i) {
            Vector3f vector3f = avector3f[i];
            vector3f.rotate(quaternionf);
            vector3f.mul(f3);
            vector3f.add(f, f1, f2);
