public void render(PoseStack p_116615_, MultiBufferSource p_116616_, int p_116617_, Doppelganger p_116618_, float p_116619_, float p_116620_, float p_116621_, float p_116622_, float p_116623_, float p_116624_) {
      if (p_116618_.isCapeLoaded() && !p_116618_.isInvisible() && p_116618_.isModelPartShown(PlayerModelPart.CAPE) && p_116618_.getCloakTextureLocation() != null) {
         ItemStack itemstack = p_116618_.getItemBySlot(EquipmentSlot.CHEST);
         if (!itemstack.is(Items.ELYTRA)) {
            p_116615_.pushPose();
            p_116615_.translate(0.0D, 0.0D, 0.125D);
            double d0 = Mth.lerp((double)p_116621_, p_116618_.xCloakO, p_116618_.xCloak) - Mth.lerp((double)p_116621_, p_116618_.xo, p_116618_.getX());
            double d1 = Mth.lerp((double)p_116621_, p_116618_.yCloakO, p_116618_.yCloak) - Mth.lerp((double)p_116621_, p_116618_.yo, p_116618_.getY());
            double d2 = Mth.lerp((double)p_116621_, p_116618_.zCloakO, p_116618_.zCloak) - Mth.lerp((double)p_116621_, p_116618_.zo, p_116618_.getZ());
            float f = p_116618_.yBodyRotO + (p_116618_.yBodyRot - p_116618_.yBodyRotO);
            double d3 = (double)Mth.sin(f * ((float)Math.PI / 180F));
            double d4 = (double)(-Mth.cos(f * ((float)Math.PI / 180F)));
            float f1 = (float)d1 * 10.0F;
            f1 = Mth.clamp(f1, -6.0F, 32.0F);
            float f2 = (float)(d0 * d3 + d2 * d4) * 100.0F;
            f2 = Mth.clamp(f2, 0.0F, 150.0F);
            float f3 = (float)(d0 * d4 - d2 * d3) * 100.0F;
            f3 = Mth.clamp(f3, -20.0F, 20.0F);
            if (f2 < 0.0F) {
               f2 = 0.0F;
            }

            float f4 = Mth.lerp(p_116621_, p_116618_.oBob, p_116618_.bob);
            f1 += Mth.sin(Mth.lerp(p_116621_, p_116618_.walkDistO, p_116618_.walkDist) * 6.0F) * 32.0F * f4;
            if (p_116618_.isCrouching()) {
               f1 += 25.0F;
            }

            p_116615_.mulPose(Axis.XP.rotationDegrees(6.0F + f2 / 2.0F + f1));
            p_116615_.mulPose(Axis.ZP.rotationDegrees(f3 / 2.0F));
            p_116615_.mulPose(Axis.YP.rotationDegrees(180.0F - f3 / 2.0F));
            VertexConsumer vertexconsumer = p_116616_.getBuffer(RenderType.entitySolid(p_116618_.getCloakTextureLocation()));
            this.getParentModel().renderCloak(p_116615_, vertexconsumer, p_116617_, OverlayTexture.NO_OVERLAY);
            p_116615_.popPose();
         }
      }
   }

@Override
    public void render(@Nonnull PoseStack matrixStack, @Nonnull MultiBufferSource renderTypeBuffer,
                       int light, @Nonnull T livingEntity, float limbSwing, float limbSwingAmount,
                       float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        matrixStack.pushPose();
        CuriosApi.getCuriosInventory(livingEntity)
                .ifPresent(handler -> handler.getCurios().forEach((id, stacksHandler) -> {
                    IDynamicStackHandler stackHandler = stacksHandler.getStacks();
                    IDynamicStackHandler cosmeticStacksHandler = stacksHandler.getCosmeticStacks();

                    for (int i = 0; i < stackHandler.getSlots(); i++) {
                        ItemStack stack = cosmeticStacksHandler.getStackInSlot(i);
                        boolean cosmetic = true;
                        NonNullList<Boolean> renderStates = stacksHandler.getRenders();
                        boolean renderable = renderStates.size() > i && renderStates.get(i);

                        if (stack.isEmpty() && renderable) {
                            stack = stackHandler.getStackInSlot(i);
                            cosmetic = false;
                        }

                        if (!stack.isEmpty()) {
                            SlotContext slotContext = new SlotContext(id, livingEntity, i, cosmetic, renderable);
                            ItemStack finalStack = stack;
                            CuriosRendererRegistry.getRenderer(stack.getItem()).ifPresent(
                                    renderer -> renderer
                                            .render(finalStack, slotContext, matrixStack, renderLayerParent,
                                                    renderTypeBuffer, light, limbSwing, limbSwingAmount, partialTicks,
                                                    ageInTicks, netHeadYaw, headPitch));
                        }
                    }
                }));
        matrixStack.popPose();
    }

private void renderShields(PoseStack stack, MultiBufferSource buffer, T entity, float partialTicks) {
        float age = entity.tickCount + partialTicks;
        float rotateAngleY = age / 10.0F;

        int count = MiscCapHelper.getShields(entity);
        for (int c = 0; c < count; c++) {
            stack.pushPose();

            stack.translate(-0.5D, 1.0D, -0.5D);

            // invert Y
            stack.scale(1.0F, -1.0F, 1.0F);

            stack.translate(0.5D, 0.5D, 0.5D);
            stack.mulPose(Axis.YP.rotationDegrees(rotateAngleY * (180F / (float) Math.PI) + (c * (360F / count))));
            stack.mulPose(Axis.XP.rotationDegrees(15.0F));
            stack.translate(-0.5D, -0.5D, -0.5D);

            // push the shields outwards from the center of rotation
            stack.translate(0.0D, 0.0D, -1.0D);

            BakedModel model = Minecraft.getInstance().getModelManager().getModel(SHIELD);
            for (Direction dir : DIRECTIONS) {
                Minecraft.getInstance().getItemRenderer().renderQuadList(
                        stack,
                        buffer.getBuffer(Sheets.translucentCullBlockSheet()),
                        model.getQuads(null, dir, entity.getRandom(), ModelData.EMPTY, Sheets.translucentCullBlockSheet()),
                        ItemStack.EMPTY,
                        0xF000F0,
                        OverlayTexture.NO_OVERLAY
                );
            }

            stack.popPose();
        }
    }

