                this.getParentModel().renderCape(pMatrixStack, ivertexbuilder, pPackedLight, OverlayTexture.NO_OVERLAY);
                pMatrixStack.popPose();
            }
        }
    }

@SubscribeEvent
    public static void renderBossBeams(net.neoforged.neoforge.client.event.SubmitCustomGeometryEvent e) {
        if (BOSS_SPAWNS.isEmpty()) {
            return;
        }

        net.minecraft.world.phys.Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        com.mojang.blaze3d.vertex.PoseStack poseStack = e.getPoseStack();
        net.minecraft.client.renderer.SubmitNodeCollector collector = e.getSubmitNodeCollector();
        float animTime = e.getLevelRenderState().gameTime;

        for (BossSpawnData data : BOSS_SPAWNS) {
            BlockPos pos = data.pos();
            int color = 0xFF000000 | data.rarity().color().getValue();

            poseStack.pushPose();
            poseStack.translate(pos.getX() - camPos.x, pos.getY() - camPos.y, pos.getZ() - camPos.z);
            net.minecraft.client.renderer.blockentity.BeaconRenderer.submitBeaconBeam(
                poseStack, collector,
                net.minecraft.client.renderer.blockentity.BeaconRenderer.BEAM_LOCATION,
                1.0F, animTime, 0, 1024, color, 0.2F, 0.25F);
            poseStack.popPose();
        }
    }

@SubscribeEvent
    public static void submitBeams(SubmitCustomGeometryEvent e) {
        if (!AdventureConfig.enableAffixItemEffects) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        if (mc.level == null) {
            return;
        }

        Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        PoseStack pose = e.getPoseStack();
        SubmitNodeCollector collector = e.getSubmitNodeCollector();
        float partials = mc.getDeltaTracker().getGameTimeDeltaPartialTick(false);
        long gameTime = mc.level.getGameTime();

        for (Entity ent : mc.level.entitiesForRendering()) {
            if (!(ent instanceof ItemEntity item)) {
                continue;
            }

            ItemStack stack = item.getItem();
            DynamicHolder<LootRarity> rarityHolder = AffixHelper.getRarity(stack);
            if (!rarityHolder.isBound() || !item.onGround()) {
                item.setData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED, false);
                continue;
            }

            if (!item.getData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED)) {
                item.setData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED, true);
                item.setData(Apoth.Attachments.AFFIX_EFFECT_START_TIME, item.tickCount);
            }

            LootRarity rarity = rarityHolder.get();
            RarityRenderData renderData = rarity.renderData();
            int color = rarity.color().getValue();

            float progress = Mth.clamp(item.tickCount - item.getData(Apoth.Attachments.AFFIX_EFFECT_START_TIME) + partials, 0, GROW_IN_TICKS) / GROW_IN_TICKS;

            double x = Mth.lerp(partials, item.xOld, item.getX());
            double y = Mth.lerp(partials, item.yOld, item.getY());
            double z = Mth.lerp(partials, item.zOld, item.getZ());

            // Translate to the item entity in camera space; shadow rendering relies on this outer translation.
            pose.pushPose();
            pose.translate(x - camPos.x, y - camPos.y, z - camPos.z);

            float beamHeight = renderData.beamHeight();
            if (beamHeight > 0) {
                // Center the beam under the item (the beam origin is at the NW corner of a 1x1 block).
                pose.pushPose();
                pose.translate(-item.getBbWidth() * 2, 0, -item.getBbWidth() * 2);

                float beamRadius = renderData.beamRadius();
                float glowRadius = renderData.glowRadius();
                float height = beamHeight * progress;

                // Render four segments of the beam to produce a transparency gradient (fade in, ramp up, solid, fade out).
                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    0.0F, Math.min(height, 0.5F), color(ALPHA_ZERO, color), color(ALPHA_LOW, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    0.5F, Mth.clamp(height, 0, 0.5F), color(ALPHA_LOW, color), color(ALPHA_MAX, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    1.0F, Mth.clamp(height, 0, 0.5F), color(ALPHA_MAX, color), color(ALPHA_MAX, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    1.5F, Mth.clamp(height, 0, beamHeight), color(ALPHA_MAX, color), color(ALPHA_ZERO, color), beamRadius, glowRadius);

                pose.popPose();
            }

            ShadowData shadow = renderData.shadow();
            ShadowRenderer.renderShadow(pose, collector, item, partials, mc.level, shadow, ARGB.color(shadow.alpha(), color));

            pose.popPose();
        }
    }

public static void renderBeaconBeam(
        PoseStack poseStack, SubmitNodeCollector collector, Identifier beamLocation, Identifier glowLocation, float partialTick, float textureScale,
        long gameTime, float yOffset, float height, int colorBot, int colorTop, float beamRadius, float glowRadius) {

        if (height < 0) {
            return;
        }

        final float maxY = yOffset + height;
        poseStack.pushPose();
        poseStack.translate(0.5, 0.0, 0.5);
        float f = Math.floorMod(gameTime, 40) + partialTick;
        float f1 = height < 0 ? f : -f;
        float f2 = Mth.frac(f1 * 0.2F - Mth.floor(f1 * 0.1F));
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(f * 2.25F - 45.0F));
        final float f6 = -beamRadius;
        final float f9 = -beamRadius;
        final float f12 = -1.0F + f2;
        final float f13 = height * textureScale * (0.5F / beamRadius) + f12;
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixBeam(beamLocation, true), (pose, buffer) -> renderPart(
            pose, buffer, colorBot, colorTop, yOffset, maxY,
            0.0F, beamRadius, beamRadius, 0.0F, f6, 0.0F, 0.0F, f9,
            0.0F, 1.0F, f13, f12));
        poseStack.popPose();
        final float g3 = -glowRadius;
        final float g4 = -glowRadius;
        final float g5 = -glowRadius;
        final float g6 = -glowRadius;
        final float g12 = -1.0F + f2;
        final float g13 = height * textureScale + g12;
        final int glowBot = ARGB.alpha(colorBot) / 2 << 24 | colorBot & 0x00FFFFFF;
        final int glowTop = ARGB.alpha(colorTop) / 2 << 24 | colorTop & 0x00FFFFFF;
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixBeam(glowLocation, true), (pose, buffer) -> renderPart(
            pose, buffer, glowBot, glowTop, yOffset, maxY,
            g3, g4, glowRadius, g5, g6, glowRadius, glowRadius, glowRadius,
            0.0F, 1.0F, g13, g12));
        poseStack.popPose();
    }

private static void addVertex(
        PoseStack.Pose pose, VertexConsumer consumer, int color, float y, float x, float z, float u, float v) {
        consumer.addVertex(pose, x, y, z)
            .setColor(color)
            .setUv(u, v)
            .setOverlay(OverlayTexture.NO_OVERLAY)
            .setLight(15728880)
            .setNormal(pose, 0.0F, 1.0F, 0.0F);
    }

@SubscribeEvent
    public static void submitOutlines(SubmitCustomGeometryEvent e) {
        Set<BlockPos> blocks = getAOEBlocks();
        if (blocks.isEmpty()) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        Level level = mc.level;
        if (level == null) {
            return;
        }

        Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        PoseStack pose = e.getPoseStack();
        SubmitNodeCollector collector = e.getSubmitNodeCollector();

        for (BlockPos pos : blocks) {
            BlockState state = level.getBlockState(pos);
            if (state.isAir()) {
                continue;
            }

            VoxelShape shape = state.getShape(level, pos);
            if (shape.isEmpty()) {
                continue;
            }

            double x = pos.getX() - camPos.x;
            double y = pos.getY() - camPos.y;
            double z = pos.getZ() - camPos.z;

            collector.submitCustomGeometry(pose, RenderTypes.lines(), (p, buffer) -> {
                shape.forAllEdges((x1, y1, z1, x2, y2, z2) -> {
                    org.joml.Vector3f normal = new org.joml.Vector3f((float) (x2 - x1), (float) (y2 - y1), (float) (z2 - z1)).normalize();
                    buffer.addVertex(p, (float) (x1 + x), (float) (y1 + y), (float) (z1 + z))
                        .setColor(0, 0, 0, 102).setNormal(p, normal).setLineWidth(2F);
                    buffer.addVertex(p, (float) (x2 + x), (float) (y2 + y), (float) (z2 + z))
                        .setColor(0, 0, 0, 102).setNormal(p, normal).setLineWidth(2F);
                });
            });
        }

        submitCrumbling(e, blocks, mc, level, camPos, pose, collector);
    }

@Override
    public void extractRenderState(GuiGraphicsExtractor gfx, int mouseX, int mouseY, float partialTick) {
        super.extractRenderState(gfx, mouseX, mouseY, partialTick);

        int leftPos = (this.width - WorldTierSelectScreen.IMAGE_WIDTH) / 2 + 26;
        int topPos = (this.height - WorldTierSelectScreen.IMAGE_HEIGHT) / 2 + 30;

        LocalPlayer player = Minecraft.getInstance().player;
        AttributeTooltipContext ctx = AttributeTooltipContext.of(player, TooltipContext.of(player.level()), net.minecraft.world.item.component.TooltipDisplay.DEFAULT, ApothicAttributes.getTooltipFlag());
        float effectiveLuck = Minecraft.getInstance().hasShiftDown() ? 0 : player.getLuck(); // Show default values on shift, "real" values otherwise.

        for (int i = 0; i < 3; i++) {

            if (i == 2) {
                int x = leftPos + i * (BOX_WIDTH + 16);
                int y = topPos;

                Component header = Apotheosis.lang("text", "monster_augments").withStyle(ChatFormatting.RED, ChatFormatting.BOLD);
                drawCenteredString(gfx, this.font, header, x + BOX_WIDTH / 2, y + 12, 0xFF000000);

                y += 20;

                for (TierAugment aug : TierAugmentRegistry.getAugments(this.tier, Target.MONSTERS)) {
                    y += 12;
                    Component comp = aug.getDescription(ctx).plainCopy().withStyle(ChatFormatting.RED);
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFF000000);
                }

            }
            else if (i == 1) {
                int x = leftPos + i * (BOX_WIDTH + 16);
                int y = topPos;

                Component header = Apotheosis.lang("text", "player_augments").withColor(0x00AAFF).withStyle(ChatFormatting.BOLD);
                drawCenteredString(gfx, this.font, header, x + BOX_WIDTH / 2, y + 12, 0xFF000000);

                y += 20;

                for (TierAugment aug : TierAugmentRegistry.getAugments(this.tier, Target.PLAYERS)) {
                    y += 12;
                    Component comp = aug.getDescription(ctx).plainCopy().withColor(0x00AAFF);
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFF000000);
                }

            }
            else if (i == 0) {
                int x = leftPos + i * (BOX_WIDTH + 16);
                int y = topPos;

                Component header = Apotheosis.lang("text", "drop_chances").withStyle(ChatFormatting.GOLD).withStyle(ChatFormatting.BOLD);
                drawCenteredString(gfx, this.font, header, x + BOX_WIDTH / 2, y + 12, 0xFF000000);

                Component rarityHeader = Apotheosis.lang("text", "rarities").withStyle(ChatFormatting.GOLD).withStyle(ChatFormatting.UNDERLINE);
                drawCenteredString(gfx, this.font, rarityHeader, x + BOX_WIDTH / 2, y + 33, 0xFF000000);

                y += 35;

                int totalWeight = RarityRegistry.INSTANCE.getValues().stream().mapToInt(r -> r.weights().getWeight(this.tier, effectiveLuck)).sum();
                for (LootRarity rarity : RarityRegistry.getSortedRarities()) {
                    y += 12;
                    float percent = rarity.weights().getWeight(this.tier, effectiveLuck) / (float) totalWeight;
                    MutableComponent comp = rarity.toComponent();
                    comp.append(Component.translatable(": %s", Affix.fmt(100 * percent) + "%").withStyle(s -> s.withColor(rarity.color())));
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFFFFFFFF);
                }

                Component purityHeader = Apotheosis.lang("text", "purities").withStyle(ChatFormatting.GOLD).withStyle(ChatFormatting.UNDERLINE);
                drawCenteredString(gfx, this.font, purityHeader, x + BOX_WIDTH / 2, y + 13, 0xFF000000);

                y += 15;

                Purity[] values = Purity.values();
                totalWeight = Arrays.stream(values).mapToInt(r -> r.weights().getWeight(this.tier, effectiveLuck)).sum();
                for (Purity purity : values) {
                    y += 12;
                    float percent = purity.weights().getWeight(this.tier, effectiveLuck) / (float) totalWeight;
                    MutableComponent comp = purity.toComponent();
                    comp.append(Component.translatable(": %s", Affix.fmt(100 * percent) + "%").withStyle(s -> s.withColor(purity.getColor())));
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFFFFFFFF);
                }
            }

        }
    }

@SuppressWarnings({"UnstableApiUsage", "deprecation"})  // no thanks forge, I'm matching vanilla behavior so I'll call the methods there
  // seriously forge, how am I supposed to implement something like vanilla if I cannot create events?
  @Override
  public void render(T frame, float entityYaw, float partialTicks, PoseStack matrices, MultiBufferSource bufferIn, int packedLight) {
    FrameType frameType = frame.getFrameType();

    // base entity rendering logic, since calling super gives us the item frame renderer that we are replacing
    RenderNameTagEvent renderNameplate = new RenderNameTagEvent(frame, frame.getDisplayName(), this, matrices, bufferIn, packedLight, partialTicks);
    MinecraftForge.EVENT_BUS.post(renderNameplate);
    if (renderNameplate.getResult() == Result.ALLOW || (renderNameplate.getResult() != Result.DENY && this.shouldShowName(frame))) {
      this.renderNameTag(frame, renderNameplate.getContent(), matrices, bufferIn, packedLight);
    }

    // orient the renderer
    matrices.pushPose();
    Direction facing = frame.getDirection();
    Vec3 offset = this.getRenderOffset(frame, partialTicks);
    matrices.translate(facing.getStepX() * 0.46875D - offset.x(), facing.getStepY() * 0.46875D - offset.y(), facing.getStepZ() * 0.46875D - offset.z());
    matrices.mulPose(Axis.XP.rotationDegrees(frame.getXRot()));
    matrices.mulPose(Axis.YP.rotationDegrees(180.0F - frame.getYRot()));

    // render the frame
    ItemStack stack = frame.getItem();
    boolean isMap = !stack.isEmpty() && stack.getItem() instanceof MapItem;
    // clear does not render the frame if filled
    boolean frameVisible = !frame.isInvisible() && (frameType != FrameType.CLEAR || stack.isEmpty());
    if (frameVisible) {
      matrices.pushPose();
      matrices.translate(-0.5D, -0.5D, -0.5D);
      blockRenderer.getModelRenderer().renderModel(
        matrices.last(), bufferIn.getBuffer(Sheets.cutoutBlockSheet()), null,
        blockRenderer.getBlockModelShaper().getModelManager().getModel(isMap ? LOCATIONS_MODEL_MAP.get(frameType) : LOCATIONS_MODEL.get(frameType)),
        1.0F, 1.0F, 1.0F, packedLight, OverlayTexture.NO_OVERLAY);
      matrices.popPose();
    }

    // render the item
    if (!stack.isEmpty()) {
      // if no frame, offset the item farther back
      matrices.translate(0.0D, 0.0D, 0.4375D);

      // determine rotation for the item inside
      MapItemSavedData mapdata = null;
      if (isMap) {
        mapdata = MapItem.getSavedData(stack, frame.level());
      }
      int frameRotation = frame.getRotation();
      // for diamond, render the timer as a partial rotation
      if (frameType.hasMoreRotations()) {
        int rotation = mapdata != null ? (frameRotation + 2) % 4 * 4 : frameRotation;
        matrices.mulPose(Axis.ZP.rotationDegrees(rotation * 360f / 16f));
      } else {
        int rotation = mapdata != null ? (frameRotation + 2) % 4 * 2 : frameRotation;
        matrices.mulPose(Axis.ZP.rotationDegrees(rotation * 360f / 8f));
      }
      if (!MinecraftForge.EVENT_BUS.post(new RenderItemInFrameEvent(frame, this, matrices, bufferIn, packedLight))) {
        if (mapdata != null) {
          matrices.scale(0.0078125F, 0.0078125F, 0.0078125F);
          matrices.translate(-64.0D, -64.0D, -1.0D);
          int light = frameType == FrameType.MANYULLYN ? 0x00F000F0 : packedLight;
          Integer mapId = MapItem.getMapId(stack);
          assert mapId != null;
          Minecraft.getInstance().gameRenderer.getMapRenderer().render(matrices, bufferIn, mapId, mapdata, true, light);
        } else {
          float scale = frameType == FrameType.CLEAR ? 0.75f : 0.5f;
          matrices.scale(scale, scale, scale);
          int light = frameType == FrameType.MANYULLYN ? 0x00F000F0 : packedLight;
          this.itemRenderer.renderStatic(stack, ItemDisplayContext.FIXED, light, OverlayTexture.NO_OVERLAY, matrices, bufferIn, frame.level(), frame.getId());
        }
      }
    }

    matrices.popPose();
  }

public static void renderTiledFluid(PoseStack matrices, AbstractContainerScreen<?> screen, FluidStack stack, int x, int y, int width, int height, int depth) {
    if (!stack.isEmpty()) {
      IClientFluidTypeExtensions clientFluid = IClientFluidTypeExtensions.of(stack.getFluid());
      TextureAtlasSprite fluidSprite = screen.getMinecraft().getTextureAtlas(InventoryMenu.BLOCK_ATLAS).apply(clientFluid.getStillTexture(stack));
      RenderUtils.setColorRGBA(clientFluid.getTintColor(stack));
      renderTiledTextureAtlas(matrices, screen, fluidSprite, x, y, width, height, depth, stack.getFluid().getFluidType().isLighterThanAir());
      RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 1.0f);
    }
  }

public static void renderTransparentCuboid(PoseStack matrices, MultiBufferSource buffer, FluidCuboid cube, FluidStack fluid, int opacity, int light) {
    // nothing to render? skip
    if (opacity < 0 || fluid.isEmpty()) {
      return;
    }

    IClientFluidTypeExtensions attributes = IClientFluidTypeExtensions.of(fluid.getFluid());
    TextureAtlasSprite still = FluidRenderer.getBlockSprite(attributes.getStillTexture(fluid));
    TextureAtlasSprite flowing = FluidRenderer.getBlockSprite(attributes.getFlowingTexture(fluid));
    FluidType fluidType = fluid.getFluid().getFluidType();
    boolean isGas = fluidType.isLighterThanAir();
    light = FluidRenderer.withBlockLight(light, fluidType.getLightLevel(fluid));

    // add in fluid opacity if given
    int color = attributes.getTintColor(fluid);
    if (opacity < 0xFF) {
      // alpha is top 8 bits, multiply by opacity and divide out remainder
      int alpha = ((color >> 24) & 0xFF) * opacity / 0xFF;
      // clear bits in color and or in the new alpha
      color = (color & 0xFFFFFF) | (alpha << 24);
    }
    FluidRenderer.renderCuboid(matrices, buffer.getBuffer(MantleRenderTypes.FLUID), cube, still, flowing, cube.getFromScaled(), cube.getToScaled(), color, light, isGas);
  }

public static void renderFluidTank(PoseStack matrices, MultiBufferSource buffer, FluidCuboid cube, FluidTankAnimated tank, int light, float partialTicks, boolean flipGas) {
    // render liquid if present
    FluidStack liquid = tank.getFluid();
    int capacity = tank.getCapacity();
    if (!liquid.isEmpty() && capacity > 0) {
      // update render offset
      float offset = tank.getRenderOffset();
      if (offset > 1.2f || offset < -1.2f) {
        offset = offset - ((offset / 12f + 0.1f) * partialTicks);
        tank.setRenderOffset(offset);
      } else {
        tank.setRenderOffset(0);
      }

      // fetch fluid information from the model
      FluidRenderer.renderScaledCuboid(matrices, buffer, cube, liquid, offset, capacity, light, flipGas);
    } else {
      // clear render offet if no liquid
      tank.setRenderOffset(0);
    }
  }

@Override
  public boolean applyForgeHandTransform(PoseStack poseStack, LocalPlayer player, HumanoidArm arm, ItemStack stack, float partialTicks, float equipProgress, float swingProgress) {
    // forge: why don't you give me the arm that is used on the next line???
    InteractionHand hand = arm == player.getMainArm() ? InteractionHand.MAIN_HAND : InteractionHand.OFF_HAND;
    // this code is copied from ItemInHandRenderer#renderArmWithItem with changes made for Tinker tools
    // to avoid redundant operations, we copied even methods that are unmodified, changes are noted below
    int sideOffset = arm == HumanoidArm.RIGHT ? 1 : -1;
    if (player.isUsingItem() && player.getUseItemRemainingTicks() > 0 && player.getUsedItemHand() == hand) {
      UseAnim anim = stack.getUseAnimation();
      switch (anim) {
        // merged BLOCK and NONE - same code
        case NONE, BLOCK:
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          break;

        case EAT:
        case DRINK:
          // start: applyEatTransform
          float timeLeft = player.getUseItemRemainingTicks() - partialTicks + 1;
          float percentage = timeLeft / stack.getUseDuration();
          if (percentage < 0.8f) {
            poseStack.translate(0, Mth.abs(Mth.cos(timeLeft / 4f * PI) * 0.1f), 0);
          }

          float speed = 1 - (float)Math.pow(percentage, 27);
          int sideOffset1 = arm == HumanoidArm.RIGHT ? 1 : -1;
          poseStack.translate(speed * 0.6F * (float) sideOffset1, speed * -0.5f, speed * 0);
          poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset1 * speed * 90));
          poseStack.mulPose(Axis.XP.rotationDegrees(speed * 10));
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset1 * speed * 30));
          // end: applyEatTransform
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          break;

        // crossbow is moved from the vanilla special case to a general animation
        case BOW:
        case CROSSBOW: {
          boolean isBow = anim == UseAnim.BOW;
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          // change: merged in crossbow
          if (isBow) {
            poseStack.translate(sideOffset * -0.2785682f, 0.18344387f, 0.15731531f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-13.935f));
            poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 35.3f));
          } else {
            poseStack.translate(sideOffset * -0.4785682f, -0.094387f, 0.05731531f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-11.935f));
            poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 65.3f));
          }
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -9.785f));

          float remainingTime = (float) stack.getUseDuration() - ((float) player.getUseItemRemainingTicks() - partialTicks + 1);
          // change: scale charge by drawtime instead of a flat 20f or the crossbow enchantment
          float charge = remainingTime / ModifierUtil.getPersistentInt(stack, GeneralInteractionModifierHook.KEY_DRAWTIME, 20);
          // only bows do this weird charge formula
          if (isBow) {
            charge = (charge * charge + charge * 2) / 3;
          }
          if (charge > 1) {
            charge = 1;
          }

          if (charge > 0.1f) {
            // change: inlined expressions, replaced (value * 0) with 0
            poseStack.translate(0, Mth.sin((remainingTime - 0.1f) * 1.3f) * (charge - 0.1f) * 0.004f, 0);
          }
          // change: replaced (value * 0) with 0
          poseStack.translate(0, 0, charge * 0.04f);
          poseStack.scale(1, 1, 1 + charge * 0.2f);
          poseStack.mulPose(Axis.YN.rotationDegrees(sideOffset * 45));
          break;
        }

        case SPEAR:
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          poseStack.translate(sideOffset * -0.5f, 0.7f, 0.1f);
          // change: added 45 degrees to take into account tools being diagonal
          poseStack.mulPose(Axis.XP.rotationDegrees(-90));
          poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 35.3f));
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -9.785f));
          float sRemainingTime = stack.getUseDuration() - (player.getUseItemRemainingTicks() - partialTicks + 1);
          // change: scale charge by drawtime instead of a flat 10f, tridents have 2.0 drawspeed I decided
          float sCharge = sRemainingTime / ModifierUtil.getPersistentInt(stack, GeneralInteractionModifierHook.KEY_DRAWTIME, 20);
          if (sCharge > 1) {
            sCharge = 1;
          }

          if (sCharge > 0.1F) {
            // change: inlined expressions, replaced (value * 0) with 0
            poseStack.translate(0, Mth.sin((sRemainingTime - 0.1F) * 1.3F) * (sCharge - 0.1F) * 0.004F, 0);
          }
          poseStack.translate(0, 0, sCharge * 0.2f);
          poseStack.scale(1, 1, 1 + sCharge * 0.2f);
          poseStack.mulPose(Axis.YN.rotationDegrees(sideOffset * 45));
          break;

        case BRUSH:
          // start: applyBrushTransform
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          float xRot = -15 + 75 * Mth.cos((1 - ((float) (player.getUseItemRemainingTicks() % 10) - partialTicks + 1) / 10) * 2 * PI);
          if (arm != HumanoidArm.RIGHT) {
            poseStack.translate(0.1, 0.83, 0.35);
            poseStack.mulPose(Axis.XP.rotationDegrees(-80));
            poseStack.mulPose(Axis.YP.rotationDegrees(-90));
            poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
            poseStack.translate(-0.3, 0.22, 0.35);
          } else {
            poseStack.translate(-0.25, 0.22, 0.35);
            poseStack.mulPose(Axis.XP.rotationDegrees(-80));
            poseStack.mulPose(Axis.YP.rotationDegrees(90));
            poseStack.mulPose(Axis.ZP.rotationDegrees(0));
            poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
          }
          // end: applyBrushTransform
      }
    } else if (player.isAutoSpinAttack()) {
      applyItemArmTransform(poseStack, equipProgress, sideOffset);
      poseStack.translate(sideOffset * -0.4f, 0.8f, 0.3f);
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 105));
      poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -85));
    } else {
      poseStack.translate(
        sideOffset * -0.4f * Mth.sin(Mth.sqrt(swingProgress) * PI),
        0.2f * Mth.sin(Mth.sqrt(swingProgress) * PI * 2),
        -0.2f * Mth.sin(swingProgress * PI));
      applyItemArmTransform(poseStack, equipProgress, sideOffset);
      // begin: applyItemArmAttackTransform
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * (45 + Mth.sin(swingProgress * swingProgress * (float)Math.PI) * -20)));
      float rotation = Mth.sin(Mth.sqrt(swingProgress) * PI);
      poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * rotation * -20));
      poseStack.mulPose(Axis.XP.rotationDegrees(rotation * -80));
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * -45));
      // end: applyItemArmAttackTransform
    }
    return true;
  }

public static void renderIcon(GuiGraphics graphics, Modifier modifier, int x, int y, int z, int size) {
    TextureAtlas atlas = Minecraft.getInstance().getModelManager().getAtlas(InventoryMenu.BLOCK_ATLAS);

    List<ResourceLocation> icons = modifierIcons.getOrDefault(modifier.getId(), Collections.emptyList());
    if (!icons.isEmpty()) {
      for (ResourceLocation icon : icons) {
        graphics.blit(x, y, z, size, size, atlas.getSprite(icon));
      }
    } else {
      graphics.blit(x, y, z, size, size, atlas.getSprite(DEFAULT_PAGES));
      RenderUtils.setColorRGBA(0xFF000000 | modifier.getColor());
      graphics.blit(x, y, z, size, size, atlas.getSprite(DEFAULT_COVER));
      RenderUtils.setColorRGBA(-1);
    }
  }

@Override
  public void render(CastingBlockEntity casting, float partialTicks, PoseStack matrices, MultiBufferSource buffer, int light, int combinedOverlayIn) {
    BlockState state = casting.getBlockState();
    List<FluidCuboid> fluids = FluidCuboid.REGISTRY.get(state, List.of());
    List<RenderItem> renderItems = RenderItem.STATE_REGISTRY.get(state, List.of());

    // rotate the matrix
    if (!fluids.isEmpty() || !renderItems.isEmpty()) {
      boolean isRotated = RenderingHelper.applyRotation(matrices, state);

      // if the recipe is in progress, start fading the item away
      int timer = casting.getTimer();
      int totalTime = casting.getCoolingTime();
      int itemOpacity = 0;
      int fluidOpacity = 0xFF;
      if (timer > 0 && totalTime > 0) {
        int opacity = (4 * 0xFF) * timer / totalTime;
        // fade item in
        itemOpacity = opacity / 4;

        // fade fluid and temperature out during last 10%
        if (opacity > 3 * 0xFF) {
          fluidOpacity = (4 * 0xFF) - opacity;
        }
      }

      // render fluids
      if (!fluids.isEmpty()) {
        CastingFluidHandler tank = casting.getTank();
        FluidStack fluidStack = tank.getFluid();
        int capacity = tank.getCapacity();
        // if full, start rendering with opacity for progress
        if (fluidStack.getAmount() == capacity) {
          for (FluidCuboid fluid : fluids) {
            RenderUtils.renderTransparentCuboid(matrices, buffer, fluid, fluidStack, fluidOpacity, light);
          }
        } else {
          // not strictly useful to scale the fluids down, but who knows what the modeler does
          for (FluidCuboid fluid : fluids) {
            FluidRenderer.renderScaledCuboid(matrices, buffer, fluid, fluidStack, 0, capacity, light, false);
          }
        }
      }

      // render renderItems
      if (!renderItems.isEmpty()) {
        // render renderItems
        // input is normal
        RenderingHelper.renderItem(matrices, buffer, casting.getItem(0), renderItems.get(0), light);

        // output may be the recipe output instead of the current item
        if (renderItems.size() >= 2) {
          RenderItem outputModel = renderItems.get(1);
          if (!outputModel.isHidden()) {
            // get output stack
            ItemStack output = casting.getItem(1);
            MultiBufferSource outputBuffer = buffer;
            if (itemOpacity > 0 && output.isEmpty()) {
              output = casting.getRecipeOutput();
              // apply a buffer wrapper to tint and add opacity
              outputBuffer = new CastingItemRenderTypeBuffer(buffer, itemOpacity, fluidOpacity);
            }
            RenderingHelper.renderItem(matrices, outputBuffer, output, outputModel, light);
          }
        }
      }

      // pop back rotation
      if (isRotated) {
        matrices.popPose();
      }
    }
  }

@Override
	public void render(ChannelBlockEntity te, float partialTicks, PoseStack matrices, MultiBufferSource buffer, int light, int combinedOverlayIn)  {
		FluidStack fluid = te.getFluid();
		if (fluid.isEmpty()) {
			return;
		}

		// fetch model properties
		Level world = te.getLevel();
		if (world == null) {
			return;
		}
		BlockPos pos = te.getBlockPos();
		BlockState state = te.getBlockState();
		ChannelFluids model = ChannelFluids.REGISTRY.get(state.getBlock());
		if (model == null) {
			return;
		}

		// fluid attributes
		IClientFluidTypeExtensions attributes = IClientFluidTypeExtensions.of(fluid.getFluid());
		TextureAtlasSprite still = FluidRenderer.getBlockSprite(attributes.getStillTexture(fluid));
		TextureAtlasSprite flowing = FluidRenderer.getBlockSprite(attributes.getFlowingTexture(fluid));
		VertexConsumer builder = buffer.getBuffer(MantleRenderTypes.FLUID);
		int color = attributes.getTintColor(fluid);
		light = FluidRenderer.withBlockLight(light, fluid.getFluid().getFluidType().getLightLevel(fluid));

		// render sides first, while doing so we will determine center "flow"
		FluidCuboid cube;
		boolean isRotated;
		Direction centerFlow = Direction.UP;
		for (Direction direction : Plane.HORIZONTAL) {
			// check if we have that side on the block
			ChannelConnection connection = state.getValue(ChannelBlock.DIRECTION_MAP.get(direction));
			if (connection.canFlow()) {
				// apply rotation for the side
				isRotated = RenderingHelper.applyRotation(matrices, direction);
				// get the relevant fluid model, render it
				if (te.isFlowing(direction)) {
					cube = model.side().flow(connection == ChannelConnection.OUT);

					// add to center direction
					if (connection == ChannelConnection.OUT) {
						// if unset (up), use this direction
						if (centerFlow == Direction.UP) {
							centerFlow = direction;
							// if set and it disagrees, set the fail state (down)
						} else if (centerFlow != direction) {
							centerFlow = Direction.DOWN;
						}
					}
					// render the extra edge against other blocks
					if (!world.getBlockState(pos.relative(direction)).is(state.getBlock())) {
						FluidRenderer.renderCuboid(matrices, builder, model.side().edge(), 0, still, flowing, color, light, false);
					}
				} else {
					cube = model.side().still();
				}
				FluidRenderer.renderCuboid(matrices, builder, cube, 0, still, flowing, color, light, false);
				// undo rotation
				if (isRotated) {
					matrices.popPose();
				}
			}
		}

		// render center
		isRotated = false;
		if (centerFlow.getAxis().isVertical()) {
			cube = model.center(false);
		} else {
			cube = model.center(true);
			isRotated = RenderingHelper.applyRotation(matrices, centerFlow);
		}
		// render the cube and pop back
		FluidRenderer.renderCuboid(matrices, builder, cube, 0, still, flowing, color, light, false);
		if (isRotated) {
			matrices.popPose();
		}

		// render flow downwards
		if (state.getValue(ChannelBlock.DOWN) && te.isFlowing(Direction.DOWN)) {
			cube = model.down();
			FluidRenderer.renderCuboid(matrices, builder, cube, 0, still, flowing, color, light, false);

			// render into the block(s) below
			RenderingHelper.renderFaucetFluids(world, pos, Direction.DOWN, matrices, builder, still, flowing, color, light);
		}
	}

@Override
  public void render(FaucetBlockEntity tileEntity, float partialTicks, PoseStack matrices, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
    FluidStack renderFluid = tileEntity.getRenderFluid();
    if (!tileEntity.isPouring() || renderFluid.isEmpty()) {
      return;
    }

    // safety
    Level world = tileEntity.getLevel();
    if (world == null) {
      return;
    }

    // fetch faucet model to determine where to render fluids
    BlockState state = tileEntity.getBlockState();
    List<FluidCuboid> fluids = FluidCuboid.REGISTRY.get(state, List.of());
    if (!fluids.isEmpty()) {
      // if side, rotate fluid model
      Direction direction = state.getValue(FaucetBlock.FACING);
      boolean isRotated = RenderingHelper.applyRotation(matrices, direction);

      // fluid props
      IClientFluidTypeExtensions attributes = IClientFluidTypeExtensions.of(renderFluid.getFluid());
      int color = attributes.getTintColor(renderFluid);
      Function<ResourceLocation, TextureAtlasSprite> spriteGetter = Minecraft.getInstance().getTextureAtlas(InventoryMenu.BLOCK_ATLAS);
      TextureAtlasSprite still = spriteGetter.apply(attributes.getStillTexture(renderFluid));
      TextureAtlasSprite flowing = spriteGetter.apply(attributes.getFlowingTexture(renderFluid));
      FluidType fluidType = renderFluid.getFluid().getFluidType();
      combinedLightIn = FluidRenderer.withBlockLight(combinedLightIn, fluidType.getLightLevel(renderFluid));

      // render all cubes in the model
      VertexConsumer buffer = bufferIn.getBuffer(MantleRenderTypes.FLUID);
      for (FluidCuboid cube : fluids) {
        FluidRenderer.renderCuboid(matrices, buffer, cube, 0, still, flowing, color, combinedLightIn, false);
      }

      // render into the block(s) below
      RenderingHelper.renderFaucetFluids(world, tileEntity.getBlockPos(), direction, matrices, buffer, still, flowing, color, combinedLightIn);

      // if rotated, pop back rotation
      if(isRotated) {
        matrices.popPose();
      }
    }
  }

@Override
  public void render(HeatingStructureBlockEntity smeltery, float partialTicks, PoseStack matrices, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
    Level world = smeltery.getLevel();
    if (world == null) return;
    BlockState state = smeltery.getBlockState();
    StructureData structure = smeltery.getStructure();
    boolean structureValid = state.getValue(ControllerBlock.IN_STRUCTURE) && structure != null;

    // render erroring block, done whether in the structure or not
    BlockPos errorPos = smeltery.getErrorPos();
    if (errorPos != null && Minecraft.getInstance().player != null) {
      // either we must be holding the book, or the structure must be erroring and it be within 10 seconds of last update
      boolean highlightError = smeltery.isHighlightError();
      if ((!structureValid && highlightError) || smeltery.showDebugBlockBorder(Minecraft.getInstance().player)) {
        // distance check, 512 is the squared length of the diagonal of a max size structure
        BlockPos pos = smeltery.getBlockPos();
        BlockPos playerPos = Minecraft.getInstance().player.blockPosition();
        int dx = playerPos.getX() - pos.getX();
        int dz = playerPos.getZ() - pos.getZ();
        if ((dx * dx + dz * dz) < 512) {
          // color will be yellow if the structure is valid (expanding), red if invalid
          VertexConsumer vertexBuilder = buffer.getBuffer(highlightError ? TinkerRenderTypes.ERROR_BLOCK : RenderType.LINES);
          LevelRenderer.renderShape(matrices, vertexBuilder, Shapes.block(), errorPos.getX() - pos.getX(), errorPos.getY() - pos.getY(), errorPos.getZ() - pos.getZ(), 1f, structureValid ? 1f : 0f, 0f, 0.5f);
        }
      }
    }

    // if no structure, nothing else to do
    if (!structureValid) {
      return;
    }

    // relevant positions
    BlockPos pos = smeltery.getBlockPos();
    BlockPos minPos = structure.getMinInside();
    BlockPos maxPos = structure.getMaxInside();

    // offset to make rendering min pos relative
    matrices.pushPose();
    matrices.translate(minPos.getX() - pos.getX(), minPos.getY() - pos.getY(), minPos.getZ() - pos.getZ());
    // render tank fluids, use minPos for brightness
    SmelteryTankRenderer.renderFluids(matrices, buffer, smeltery.getTank(), minPos, maxPos, LevelRenderer.getLightColor(world, minPos));

    // render items
    int xd = 1 + maxPos.getX() - minPos.getX();
    int zd = 1 + maxPos.getZ() - minPos.getZ();
    int layer = xd * zd;
    Direction facing = state.getValue(ControllerBlock.FACING);
    Quaternionf itemRotation = Axis.YP.rotationDegrees(-90.0F * (float)facing.get2DDataValue());
    MeltingModuleInventory inventory = smeltery.getMeltingInventory();
    Minecraft mc = Minecraft.getInstance();
    ItemRenderer itemRenderer = mc.getItemRenderer();
    int max = Config.CLIENT.maxSmelteryItemQuads.get();
    if (max != 0) {
      int quadsRendered = 0;
      for (int i = 0; i < inventory.getSlots(); i++) {
        ItemStack stack = inventory.getStackInSlot(i);
        if (!stack.isEmpty()) {
          // calculate position inside the smeltery from slot index
          int height = i / layer;
          int layerIndex = i % layer;
          int offsetX = layerIndex % xd;
          int offsetZ = layerIndex / xd;
          BlockPos itemPos = minPos.offset(offsetX, height, offsetZ);

          // offset to the slot position in the structure, scale, and rotate the item
          matrices.pushPose();
          matrices.translate(offsetX + 0.5f, height + 0.5f, offsetZ + 0.5f);
          matrices.mulPose(itemRotation);
          matrices.scale(ITEM_SCALE, ITEM_SCALE, ITEM_SCALE);
          BakedModel model = itemRenderer.getModel(stack, world, null, 0);
          itemRenderer.render(stack, TinkerItemDisplays.MELTER, false, matrices, buffer, LevelRenderer.getLightColor(world, itemPos), OverlayTexture.NO_OVERLAY, model);
          matrices.popPose();

          // done as quads rather than items as its not that expensive to draw blocks, items are the problem
          if (max != -1) {
            // builtin has no quads, lets pretend its 100 as they are more expensive
            if (model.isCustomRenderer()) {
              quadsRendered += 100;
            } else {
              RandomSource random = smeltery.getLevel().getRandom();
              // not setting the seed on the random and ignoring the forge layered model stuff means this is just an estimate, but since this is for the sake of performance its not a huge deal for it to be exact
              for (Direction direction : Direction.values()) {
                quadsRendered += model.getQuads(null, direction, random, ModelData.EMPTY, null).size();
              }
              quadsRendered += model.getQuads(null, null, random, ModelData.EMPTY, null).size();
            }
            if (quadsRendered > max) {
              break;
            }
          }
        }
      }
    }

    matrices.popPose();
  }

private static void renderLargeFluidCuboid(PoseStack matrices, VertexConsumer builder, FluidStack fluid, int brightness,
                                             int xd, float[] xBounds, int zd, float[] zBounds, float yMin, float yMax) {
    if(yMin >= yMax || fluid.isEmpty()) {
      return;
    }
    // fluid attributes
    IClientFluidTypeExtensions attributes = IClientFluidTypeExtensions.of(fluid.getFluid());
    TextureAtlasSprite still = FluidRenderer.getBlockSprite(attributes.getStillTexture(fluid));
    int color = attributes.getTintColor(fluid);
    FluidType fluidType = fluid.getFluid().getFluidType();
    brightness = FluidRenderer.withBlockLight(brightness, fluidType.getLightLevel(fluid));
    boolean upsideDown = fluidType.isLighterThanAir();

    // the liquid can stretch over more blocks than the subtracted height is if yMin's decimal is bigger than yMax's decimal (causing UV over 1)
    // ignoring the decimals prevents this, as yd then equals exactly how many ints are between the two
    // for example, if yMax = 5.1 and yMin = 2.3, 2.8 (which rounds to 2), with the face array becoming 2.3, 3, 4, 5.1
    int yd = (int) (yMax - (int) yMin);
    // except in the rare case of yMax perfectly aligned with the block, causing the top face to render multiple times
    // for example, if yMax = 3 and yMin = 1, the values of the face array become 1, 2, 3, 3 as we then have middle ints
    if (yMax % 1d == 0) yd--;
    float[] yBounds = getBlockBounds(yd, yMin, yMax);

    // render each side
    Matrix4f matrix = matrices.last().pose();
    Vector3f from = new Vector3f();
    Vector3f to = new Vector3f();
    int rotation = upsideDown ? 180 : 0;
    for(int y = 0; y <= yd; y++) {
      for(int z = 0; z <= zd; z++) {
        for(int x = 0; x <= xd; x++) {
          from.set(xBounds[x], yBounds[y], zBounds[z]);
          to.set(xBounds[x + 1], yBounds[y + 1], zBounds[z + 1]);
          if (x == 0)  FluidRenderer.putTexturedQuad(builder, matrix, still, from, to, Direction.WEST,  color, brightness, rotation, false);
          if (x == xd) FluidRenderer.putTexturedQuad(builder, matrix, still, from, to, Direction.EAST,  color, brightness, rotation, false);
          if (z == 0)  FluidRenderer.putTexturedQuad(builder, matrix, still, from, to, Direction.NORTH, color, brightness, rotation, false);
          if (z == zd) FluidRenderer.putTexturedQuad(builder, matrix, still, from, to, Direction.SOUTH, color, brightness, rotation, false);
          if (y == yd) FluidRenderer.putTexturedQuad(builder, matrix, still, from, to, Direction.UP,    color, brightness, rotation, false);
          if (y == 0) {
            // increase Y position slightly to prevent z fighting on neighboring fluids
            from.y = from.y() + 0.001f;
            FluidRenderer.putTexturedQuad(builder, matrix, still,   from, to, Direction.DOWN,  color, brightness, rotation, false);
          }
        }
      }
    }
  }

@Override
  public void updateDisplay() {
    if (canScroll()) {
      // if we can still scroll, make sure the scroll bar is in a valid position
      this.recipeIndexOffset = Math.min(this.recipeIndexOffset, getPartRecipeCount() - MAX_PATTERN);
      this.sliderProgress = this.recipeIndexOffset / 4f / this.getHiddenRows();
    } else {
      // if we can no longer scroll, reset scrollbar progress
      this.sliderProgress = 0;
      this.recipeIndexOffset = 0;
    }

    assert this.tile != null;

    // update material
    IMaterialValue materialRecipe = this.tile.getMaterialRecipe();
    if (materialRecipe != null) {
      this.setDisplayForMaterial(materialRecipe);
    } else {
      // default text
      this.infoPanelScreen.setCaption(this.getTitle());
      this.infoPanelScreen.setText(INFO_TEXT);
      this.infoPanelScreen.clearMaterialValue();
    }

    // update part recipe cost
    IPartBuilderRecipe partRecipe = this.tile.getPartRecipe();
    boolean skipCost = false;
    if (partRecipe == null) {
      partRecipe = this.tile.getFirstRecipe();
      skipCost = true;
    }
    if (partRecipe != null) {
      int cost = partRecipe.getCost();
      if (cost > 0 && !skipCost) {
        this.infoPanelScreen.setPatternCost(cost);
      } else {
        this.infoPanelScreen.clearPatternCost();
      }
      Component title = partRecipe.getTitle();
      if (title != null) {
        this.infoPanelScreen.setCaption(title);
        this.infoPanelScreen.setText(partRecipe.getText(this.tile.getInventoryWrapper()));
      }
    } else {
      this.infoPanelScreen.clearPatternCost();
    }
  }

private void setDisplayForMaterial(IMaterialValue materialRecipe) {
    if (this.tile == null) {
      return;
    }
    MaterialVariant materialVariant = materialRecipe.getMaterial();
    this.infoPanelScreen.setCaption(MaterialTooltipCache.getColoredDisplayName(materialVariant.getVariant()));

    // determine how much material we have
    // get exact number of material, rather than rounded
    float value = materialRecipe.getMaterialValue(this.tile.getInventoryWrapper());
    MutableComponent formatted = Component.literal(Util.COMMA_FORMAT.format(value));

    // if we have a part recipe, mark material red when not enough
    IPartBuilderRecipe partRecipe = this.tile.getPartRecipe();
    if (partRecipe != null && value < partRecipe.getCost()) {
      formatted = formatted.withStyle(ChatFormatting.DARK_RED);
    }
    this.infoPanelScreen.setMaterialValue(formatted);

    // update stats and traits
    List<Component> stats = Lists.newLinkedList();
    List<Component> tips = Lists.newArrayList();

    // add warning that the material is uncraftable
    if (!materialVariant.get().isCraftable() && !tile.allowUncraftable()) {
      stats.add(UNCRAFTABLE_MATERIAL);
      stats.add(Component.empty());
      tips.add(UNCRAFTABLE_MATERIAL_TOOLTIP);
      tips.add(Component.empty());
    }

    MaterialId id = materialVariant.getId();
    List<IMaterialStats> materialStats = new ArrayList<>(MaterialRegistry.getInstance().getAllStats(id));
    materialStats.sort(STATS_COMPARATOR);
    for (IMaterialStats stat : materialStats) {
      // skip repair kit, its just an internal marker and the traits are inaccurate
      if (stat == StatlessMaterialStats.REPAIR_KIT) continue;
      List<Component> info = stat.getLocalizedInfo();

      if (!info.isEmpty()) {
        stats.add(stat.getLocalizedName().withStyle(ChatFormatting.UNDERLINE));
        tips.add(Component.empty());

        stats.addAll(info);
        tips.addAll(stat.getLocalizedDescriptions());

        List<ModifierEntry> traits = MaterialRegistry.getInstance().getTraits(id, stat.getIdentifier());
        if (!traits.isEmpty()) {
          for (ModifierEntry trait : traits) {
            if (trait.isBound()) {
              Modifier mod = trait.getModifier();
              if (mod.shouldDisplay(ModifierTooltip.PART_BUILDER)) {
                stats.add(mod.getDisplayName(trait.getLevel()));
                tips.add(mod.getDescription(trait.getLevel()));
              }
            }
          }
        }

        stats.add(Component.empty());
        tips.add(Component.empty());
      }
    }

    // remove last line if empty
    if (!stats.isEmpty() && stats.get(stats.size() - 1).getString().isEmpty()) {
      stats.remove(stats.size() - 1);
      tips.remove(tips.size() - 1);
    }

    this.infoPanelScreen.setText(stats, tips);
  }

@Override
  protected void renderBg(GuiGraphics graphics, float partialTicks, int mouseX, int mouseY) {
    this.border.draw(graphics);
    BACKGROUND.drawScaled(graphics, this.leftPos + 4, this.topPos + 4, this.imageWidth - 8, this.imageHeight - 8);

    float y = 5 + this.topPos;
    float x = 5 + this.leftPos;
    int color = 0xfff0f0f0;

    // info ? in the top right corner
    if (this.hasTooltips()) {
      graphics.drawString(this.font, "?", guiRight() - this.border.w - this.font.width("?") / 2f, this.topPos + 5, 0xff5f5f5f, false);
    }

    int scaledFontHeight = this.getScaledFontHeight();
    if (this.hasCaption()) {
      int x2 = this.imageWidth / 2;
      x2 -= this.font.width(this.caption) / 2;

      graphics.drawString(this.font, this.caption.getVisualOrderText(), (float) this.leftPos + x2, y, color, true);
      y += scaledFontHeight + 3;
    }

    // Draw pattern cost
    if (this.hasPatternCost()) {
      int x2 = this.imageWidth / 2;
      x2 -= this.font.width(this.patternCost) / 2;

      graphics.drawString(this.font, this.patternCost.getVisualOrderText(), (float) this.leftPos + x2, y, color, true);
      y += scaledFontHeight + 3;
    }

    // Draw material value
    if (this.hasMaterialValue()) {
      int x2 = this.imageWidth / 2;
      x2 -= this.font.width(this.materialValue) / 2;

      graphics.drawString(this.font, this.materialValue.getVisualOrderText(), (float) this.leftPos + x2, y, color, true);
      y += scaledFontHeight + 3;
    }

    if (this.text == null || this.text.size() == 0) {
      // no text to draw
      return;
    }

    float textHeight = font.lineHeight + 0.5f;
    float lowerBound = (this.topPos + this.imageHeight - 5) / this.textScale;
    //RenderSystem.scalef(this.textScale, this.textScale, 1.0f);
    PoseStack matrices = graphics.pose();
    matrices.pushPose();
    matrices.scale(this.textScale, this.textScale, 1.0f);
    x /= this.textScale;
    y /= this.textScale;

    // render shown lines
    ListIterator<FormattedCharSequence> iter = this.getTotalLines().listIterator(this.slider.getValue());
    while (iter.hasNext()) {
      if (y + textHeight - 0.5f > lowerBound) {
        break;
      }

      FormattedCharSequence line = iter.next();
      graphics.drawString(this.font, line, x, y, color, true);
      y += textHeight;
    }

    matrices.popPose();
    //RenderSystem.scalef(1f / textScale, 1f / textScale, 1.0f);
    this.slider.update(mouseX, mouseY);
    this.slider.draw(graphics);
  }

@Override
  protected void renderBg(GuiGraphics graphics, float partialTicks, int mouseX, int mouseY) {
    this.drawBackground(graphics, TINKER_TEXTURE);

    int x = 0;
    int y = 0;

    // draw the item background
    final float scale = 3.7f;
    final float xOff = 12.5f;
    final float yOff = 22f;

    // render the background icon
    PoseStack renderPose = graphics.pose();
    renderPose.pushPose();
    renderPose.translate(xOff, yOff, 0.0F);
    renderPose.scale(scale, scale, 1.0f);
    renderIcon(graphics, currentLayout.getIcon(), (int) (this.cornerX / scale), (int) (this.cornerY / scale));
    renderPose.popPose();

    // rebind gui texture since itemstack drawing sets it to something else
    RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 0.82f);
    RenderSystem.enableBlend();
    //RenderSystem.enableAlphaTest();
    //RenderHelper.turnOff();
    RenderSystem.disableDepthTest();
    ITEM_COVER.draw(graphics, this.cornerX + 7, this.cornerY + 18);

    // slot backgrounds, are transparent
    RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 0.28f);
    if (!this.currentLayout.getToolSlot().isHidden()) {
      Slot slot = this.getMenu().getSlot(TINKER_SLOT);
      SLOT_BACKGROUND.draw(graphics, x + this.cornerX + slot.x - 1, y + this.cornerY + slot.y - 1);
    }
    for (int i = 0; i < this.activeInputs; i++) {
      Slot slot = this.getMenu().getSlot(i + INPUT_SLOT);
      SLOT_BACKGROUND.draw(graphics, x + this.cornerX + slot.x - 1, y + this.cornerY + slot.y - 1);
    }

    // slot borders, are opaque
    RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 1.0f);
    for (int i = 0; i <= maxInputs; i++) {
      Slot slot = this.getMenu().getSlot(i);
      if ((slot instanceof TinkerStationSlot tinkerSlot && (!tinkerSlot.isDormant() || slot.hasItem()))) {
        SLOT_BORDER.draw(graphics, x + this.cornerX + slot.x - 1, y + this.cornerY + slot.y - 1);
      }
    }

    // sidebar beams
    x = this.buttonsScreen.getLeftPos() - this.leftBeam.w;
    y = this.cornerY;
    // draw the beams at the top
    this.leftBeam.draw(graphics, x, y);
    x += this.leftBeam.w;
    x += this.centerBeam.drawScaledX(graphics, x, y, this.buttonsScreen.getImageWidth());
    this.rightBeam.draw(graphics, x, y);

    x = tinkerInfo.leftPos - this.leftBeam.w;
    this.leftBeam.draw(graphics, x, y);
    x += this.leftBeam.w;
    x += this.centerBeam.drawScaledX(graphics, x, y, this.tinkerInfo.imageWidth);
    this.rightBeam.draw(graphics, x, y);

    // draw the decoration for the buttons
    for (SlotButtonItem button : this.buttonsScreen.getButtons()) {
      this.buttonDecorationTop.draw(graphics, button.getX(), button.getY() - this.buttonDecorationTop.h);
      // don't draw the bottom for the buttons in the last row
      if (button.buttonId < this.buttonsScreen.getButtons().size() - COLUMN_COUNT) {
        this.buttonDecorationBot.draw(graphics, button.getX(), button.getY() + button.getHeight());
      }
    }

    // draw the decorations for the panels
    this.panelDecorationL.draw(graphics, this.tinkerInfo.leftPos + 5, this.tinkerInfo.topPos - this.panelDecorationL.h);
    this.panelDecorationR.draw(graphics, this.tinkerInfo.guiRight() - 5 - this.panelDecorationR.w, this.tinkerInfo.topPos - this.panelDecorationR.h);
    this.panelDecorationL.draw(graphics, this.modifierInfo.leftPos + 5, this.modifierInfo.topPos - this.panelDecorationL.h);
    this.panelDecorationR.draw(graphics, this.modifierInfo.guiRight() - 5 - this.panelDecorationR.w, this.modifierInfo.topPos - this.panelDecorationR.h);

    // render slot background icons
    for (int i = 0; i <= maxInputs; i++) {
      Slot slot = this.getMenu().getSlot(i);
      if (!slot.hasItem()) {
        Pattern icon = currentLayout.getSlot(i).getIcon();
        if (icon != null) {
          GuiUtil.renderPattern(graphics, icon, this.cornerX + slot.x, this.cornerY + slot.y);
        }
      }
    }

    RenderSystem.enableDepthTest();

    super.renderBg(graphics, partialTicks, mouseX, mouseY);

    this.buttonsScreen.render(graphics, mouseX, mouseY, partialTicks);

    // text field
    if (textField != null && textField.visible) {
      TEXT_BOX.draw(graphics, this.cornerX + 79, this.cornerY + 5);
      this.textField.render(graphics, mouseX, mouseY, partialTicks);
    }

    renderArmorStand(graphics);
  }

@Override
  public void render(FluidEffectProjectile pEntity, float pEntityYaw, float pPartialTicks, PoseStack pMatrixStack, MultiBufferSource pBuffer, int pPackedLight) {
    pMatrixStack.pushPose();
    pMatrixStack.translate(0.0D, 0.15F, 0.0D);
    pMatrixStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(pPartialTicks, pEntity.yRotO, pEntity.getYRot()) - 90.0F));
    pMatrixStack.mulPose(Axis.ZP.rotationDegrees(Mth.lerp(pPartialTicks, pEntity.xRotO, pEntity.getXRot())));
