    pMatrixStack.popPose();
    super.render(pEntity, pEntityYaw, pPartialTicks, pMatrixStack, pBuffer, pPackedLight);
  }

@SubscribeEvent
  static void renderHand(RenderHandEvent event) {
    Player player = Minecraft.getInstance().player;
    if (player == null) {
      return;
    }
    // when firing your melee weapon with ballista, don't render it in the other hand; makes it look like you duplicated your weapon
    InteractionHand hand = event.getHand();
    ItemStack held = player.getItemInHand(hand);
    ItemStack opposite = player.getItemInHand(Util.getOpposite(hand));
    if (!held.isEmpty() && !opposite.isEmpty() && opposite.is(TinkerTags.Items.BALLISTAS) && ModifierUtil.getPersistentInt(opposite, ModifiableBowItem.KEY_BALLISTA, 0) == ModifiableBowItem.FLAG_BALLISTA_HELD) {
      event.setCanceled(true);
      return;
    }

    // the remainder of this listener renders the hand when it wouldn't normally, so skip if invisible
    if (player.isInvisible()) {
      return;
    }

    boolean showHand;
    if (held.isEmpty()) {
      // if empty, we show the empty offhand when chestplate modifiers use it
      showHand = hand == InteractionHand.OFF_HAND && !player.isInvisible() && player.getMainHandItem().getItem() != Items.FILLED_MAP && ArmorLevelModule.getLevel(player, TinkerDataKeys.SHOW_EMPTY_OFFHAND) > 0;
    } else {
      // if filled, some items prefer to render your arm with them, like gloves
      showHand = held.is(TinkerTags.Items.SHOW_HAND);
    }
    if (showHand) {
      PoseStack matrices = event.getPoseStack();
      matrices.pushPose();
      HumanoidArm side = player.getMainArm();
      if (hand == InteractionHand.OFF_HAND) {
        side = side.getOpposite();
      }
      Minecraft.getInstance().getEntityRenderDispatcher().getItemInHandRenderer().renderPlayerArm(matrices, event.getMultiBufferSource(), event.getPackedLight(), event.getEquipProgress(), event.getSwingProgress(), side);
      matrices.popPose();
      if (held.isEmpty()) {
        event.setCanceled(true);
      }
    }
  }

@SubscribeEvent
  public static void renderHotbar(RenderGuiOverlayEvent.Post event) {
    Minecraft mc = Minecraft.getInstance();
    Player player = mc.player;
    if (mc.options.hideGui || event.getOverlay() != VanillaGuiOverlay.HOTBAR.type() || player == null || player != mc.getCameraEntity()) {
      return;
    }
    boolean renderShield = Config.CLIENT.renderShieldSlotItem.get() && !nextOffhand.isEmpty();
    boolean renderSleeves = Config.CLIENT.renderSleevesItem.get() && !currentSleeve.isEmpty();
    boolean renderItemFrame = Config.CLIENT.renderItemFrame.get() && !itemFrames.isEmpty();
    // fetch map stack instance
    float mapScale = Config.CLIENT.mapScale.get().floatValue();
    ItemStack map = ItemStack.EMPTY;
    if (mapScale > 0) {
      TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
      if (data != null) {
        map = data.get(MinimapModule.MAP, ItemStack.EMPTY);
      }
    }
    if (!renderItemFrame && !renderShield && !renderSleeves && map.isEmpty()) {
      return;
    }
    MultiPlayerGameMode playerController = mc.gameMode;
    if (playerController != null && playerController.getPlayerMode() != GameType.SPECTATOR) {
      RenderSystem.enableBlend();
      RenderSystem.defaultBlendFunc();

      int scaledWidth = mc.getWindow().getGuiScaledWidth();
      int scaledHeight = mc.getWindow().getGuiScaledHeight();
      GuiGraphics graphics = event.getGuiGraphics();
      float partialTicks = event.getPartialTick();

      // want just above the normal offhand item
      boolean emptyOffhand = player.getOffhandItem().isEmpty();
      boolean rightHanded = player.getMainArm() == HumanoidArm.RIGHT;
      if (renderShield) {
        int x = scaledWidth / 2 + (rightHanded ? -117 : 101);
        int y = scaledHeight - 38;
        graphics.blit(Icons.ICONS, x - 3, y - 3, emptyOffhand ? 211 : 189, 0, SLOT_BACKGROUND_SIZE, SLOT_BACKGROUND_SIZE, 256, 256);
        mc.gui.renderSlot(graphics, x, y, partialTicks, player, nextOffhand, 11);
      }
      // want to the side above the normal offhand item
      if (renderSleeves) {
        int x = scaledWidth / 2 + (rightHanded ? -136 : 120);
        int y = scaledHeight - 19;
        graphics.blit(Icons.ICONS, x - 3, y - 3, emptyOffhand ? 211 : rightHanded ? 145 : 123, 0, SLOT_BACKGROUND_SIZE, SLOT_BACKGROUND_SIZE, 256, 256);
        mc.gui.renderSlot(graphics, x, y, partialTicks, player, currentSleeve, 11);
      }

      // TODO: cannot remember why this was needed before. Reconfirm if bug still exists.
      // skip the non-hotbar renderers when the pause screen is open, as they can sometimes show up above elements they shouldn't
      // if (mc.screen != null && mc.screen.isPauseScreen()) {
      //   return;
      // }

      // render map
      Orientation2D mapLocation = null;
      int mapOffset = 0;
      if (!map.isEmpty() && mc.level != null) {
        MapItemSavedData data = MapItem.getSavedData(map, mc.level);
        Integer index = MapItem.getMapId(map);

        // determine placement of the map
        mapLocation = Config.CLIENT.mapLocation.get();
        Orientation1D xOrientation = mapLocation.getX();
        Orientation1D yOrientation = mapLocation.getY();
        mapOffset = (int) (MAP_SIZE * mapScale);
        int xStart = xOrientation.align(scaledWidth - mapOffset) + Config.CLIENT.mapXOffset.get();
        int yStart = yOrientation.align(scaledHeight - mapOffset) + Config.CLIENT.mapYOffset.get();

        // if top right, compute potion offset
        if (mapLocation == Orientation2D.TOP_RIGHT) {
          int effectOffset = getEffectOffset(player);
          yStart += effectOffset;
          mapOffset += effectOffset;
        }

        // setup renderer
        PoseStack poseStack = graphics.pose();
        poseStack.pushPose();
        float padding = MAP_PADDING * mapScale;
        poseStack.translate(xStart + padding, yStart + padding, 0);
        poseStack.scale(mapScale, mapScale, -1);

        // draw background
        int light = 0xF000F0;
        MultiBufferSource buffer = graphics.bufferSource();
        VertexConsumer consumer = buffer.getBuffer(data == null ? ItemInHandRenderer.MAP_BACKGROUND : ItemInHandRenderer.MAP_BACKGROUND_CHECKERBOARD);
        Matrix4f matrix = poseStack.last().pose();
        consumer.vertex(matrix,  -7, 135, 0).color(255, 255, 255, 255).uv(0, 1).uv2(light).endVertex();
        consumer.vertex(matrix, 135, 135, 0).color(255, 255, 255, 255).uv(1, 1).uv2(light).endVertex();
        consumer.vertex(matrix, 135,  -7, 0).color(255, 255, 255, 255).uv(1, 0).uv2(light).endVertex();
        consumer.vertex(matrix,  -7,  -7, 0).color(255, 255, 255, 255).uv(0, 0).uv2(light).endVertex();

        // draw map if present
        if (data != null && index != null) {
          Minecraft.getInstance().gameRenderer.getMapRenderer().render(poseStack, buffer, index, data, false, light);
        }
        poseStack.popPose();
      }

      if (renderItemFrame) {
        // determine how many items need to be rendered
        int columns = Config.CLIENT.itemsPerRow.get();
        int count = itemFrames.size();
        // need to split items over multiple lines potentially
        int rows = count / columns;
        int inLastRow = count % columns;
        // if we have an exact number, means we should have full in last row
        if (inLastRow == 0) {
          inLastRow = columns;
        } else {
          // we have an incomplete row that was not counted
          rows++;
        }
        // determine placement of the items
        Orientation2D location = Config.CLIENT.itemFrameLocation.get();
        Orientation1D xOrientation = location.getX();
        Orientation1D yOrientation = location.getY();
        int xStart = xOrientation.align(scaledWidth - SLOT_BACKGROUND_SIZE * columns) + Config.CLIENT.itemFrameXOffset.get();
        int yStart = yOrientation.align(scaledHeight - SLOT_BACKGROUND_SIZE * rows) + Config.CLIENT.itemFrameYOffset.get();
        // if the map and item frame are at the same spot, offset item frame below
        if (location == mapLocation) {
          switch (yOrientation) {
            case START -> yStart += mapOffset;
            // add in an extra half set of the slots as we don't want to center it since the map took center
            case MIDDLE -> yStart += (mapOffset + SLOT_BACKGROUND_SIZE * rows) / 2;
            case END -> yStart -= mapOffset;
          }
        }
        // handle potions as well, though its already been handled in the map offset if present
        else if (location == Orientation2D.TOP_RIGHT) {
          yStart += getEffectOffset(player);
        }

        // draw backgrounds
        int lastRow = rows - 1;
        for (int r = 0; r < lastRow; r++) {
          for (int c = 0; c < columns; c++) {
            graphics.blit(Icons.ICONS, xStart + c * SLOT_BACKGROUND_SIZE, yStart + r * SLOT_BACKGROUND_SIZE, 167, 0, SLOT_BACKGROUND_SIZE, SLOT_BACKGROUND_SIZE, 256, 256);
          }
        }
        // last row will be aligned in the direction of x orientation (center, left, or right)
        int lastRowOffset = xOrientation.align((columns - inLastRow) * 2) * SLOT_BACKGROUND_SIZE / 2;
        for (int c = 0; c < inLastRow; c++) {
          graphics.blit(Icons.ICONS, xStart + c * SLOT_BACKGROUND_SIZE + lastRowOffset, yStart + lastRow * SLOT_BACKGROUND_SIZE, 167, 0, SLOT_BACKGROUND_SIZE, SLOT_BACKGROUND_SIZE, 256, 256);
        }

        // draw items
        int i = 0;
        xStart += 3; yStart += 3; // offset from item start instead of frame start
        for (int r = 0; r < lastRow; r++) {
          for (int c = 0; c < columns; c++) {
            mc.gui.renderSlot(graphics, xStart + c * SLOT_BACKGROUND_SIZE, yStart + r * SLOT_BACKGROUND_SIZE, partialTicks, player, itemFrames.get(i), i);
            i++;
          }
        }
        // align last row
        for (int c = 0; c < inLastRow; c++) {
          mc.gui.renderSlot(graphics, xStart + c * SLOT_BACKGROUND_SIZE + lastRowOffset, yStart + lastRow * SLOT_BACKGROUND_SIZE, partialTicks, player, itemFrames.get(i), i);
          i++;
        }
      }
    }
  }

@Override
  public void renderToBuffer(PoseStack matrixStackIn, VertexConsumer vertexBuilder, int packedLightIn, int packedOverlayIn, float red, float green, float blue, float alpha) {
    if (base != null && buffer != null) {
      if (headModel != null && headTexture != null) {
        VertexConsumer heaadBuffer = ItemRenderer.getArmorFoilBuffer(buffer, RenderType.entityCutoutNoCullZOffset(headTexture), false, hasGlint);
        matrixStackIn.pushPose();
        if (base.crouching) {
          matrixStackIn.translate(0, base.head.y / 16.0F, 0);
        }
        if (base.young) {
          matrixStackIn.scale(0.85F, 0.85F, 0.85F);
          matrixStackIn.translate(0.0D, 0.9D, 0.0D);
        } else {
          matrixStackIn.scale(1.115f, 1.115f, 1.115f);
        }
        // handle head rotation directly as it fixes issues with dragon heads
        // could fix it directly, but saves us some math to handle here
        matrixStackIn.mulPose((new Quaternionf()).rotationZYX(0, base.head.yRot, base.head.xRot));
        headModel.setupAnim(walkAnimation, 0, 0);
        renderColored(headModel, matrixStackIn, heaadBuffer, packedLightIn, packedOverlayIn, headColor, red, green, blue, alpha);
        matrixStackIn.popPose();
      }
      if (model != ArmorModel.EMPTY) {
        matrixStackIn.pushPose();
        // apply rotation before translation
        // offset and resize helmet to be around head
        matrixStackIn.translate(0.0D, base.young ? -0.09D : -0.025D, 0.0D);
        matrixStackIn.scale(1.1f, 1.1f, 1.1f);
        super.renderToBuffer(matrixStackIn, vertexBuilder, packedLightIn, packedOverlayIn, red, green, blue, alpha);
        matrixStackIn.popPose();
      }
    }
  }

@SubscribeEvent
  static void renderBlockDamageProgress(RenderLevelStageEvent event) {
    // TODO: validate this is the right stage for block breaking particles, maybe I want a bit earlier
    if (event.getStage() != Stage.AFTER_TRIPWIRE_BLOCKS) {
      return;
    }

    // validate required variables are set
    MultiPlayerGameMode controller = Minecraft.getInstance().gameMode;
    if (controller == null || !controller.isDestroying()) {
      return;
    }
    Level world = Minecraft.getInstance().level;
    Player player = Minecraft.getInstance().player;
    if (world == null || player == null || Minecraft.getInstance().getCameraEntity() == null) {
      return;
    }
    // must have the right tags
    ItemStack stack = player.getMainHandItem();
    if (stack.isEmpty() || !stack.is(TinkerTags.Items.HARVEST)) {
      return;
    }
    // must be targeting a block
    HitResult result = Minecraft.getInstance().hitResult;
    if (result == null || result.getType() != Type.BLOCK) {
      return;
    }
    // must not be broken, must be right interface
    ToolStack tool = ToolStack.from(stack);
    if (tool.isBroken()) {
      return;
    }
    // find breaking progress
    BlockHitResult blockTrace = (BlockHitResult)result;
    BlockPos target = blockTrace.getBlockPos();
    BlockDestructionProgress progress = null;
    for (Int2ObjectMap.Entry<BlockDestructionProgress> entry : Minecraft.getInstance().levelRenderer.destroyingBlocks.int2ObjectEntrySet()) {
      if (entry.getValue().getPos().equals(target)) {
        progress = entry.getValue();
        break;
      }
    }
    if (progress == null) {
      return;
    }
    // determine extra blocks to highlight
    BlockState state = world.getBlockState(target);
    // must not be broken, and the tool definition must be effective
    if (!IsEffectiveToolHook.isEffective(tool, state)) {
      return;
    }
    UseOnContext context = new UseOnContext(world, player, InteractionHand.MAIN_HAND, stack, blockTrace.withDirection(BlockSideHitListener.getClientSideHit()));
    Iterator<BlockPos> extraBlocks = tool.getHook(ToolHooks.AOE_ITERATOR).getBlocks(tool, context, state, AreaOfEffectIterator.AOEMatchType.BREAKING).iterator();
    if (!extraBlocks.hasNext()) {
      return;
    }

    // set up buffers
    PoseStack matrices = event.getPoseStack();
    matrices.pushPose();
    MultiBufferSource.BufferSource vertices = event.getLevelRenderer().renderBuffers.crumblingBufferSource();
    VertexConsumer vertexBuilder = vertices.getBuffer(ModelBakery.DESTROY_TYPES.get(progress.getProgress()));

    // finally, render the blocks
    Camera renderInfo = Minecraft.getInstance().gameRenderer.getMainCamera();
    double x = renderInfo.getPosition().x;
    double y = renderInfo.getPosition().y;
    double z = renderInfo.getPosition().z;
    BlockRenderDispatcher dispatcher = Minecraft.getInstance().getBlockRenderer();
    int rendered = 0;
    do {
      BlockPos pos = extraBlocks.next();
      matrices.pushPose();
      matrices.translate(pos.getX() - x, pos.getY() - y, pos.getZ() - z);
      PoseStack.Pose entry = matrices.last();
      VertexConsumer blockBuilder = new SheetedDecalTextureGenerator(vertexBuilder, entry.pose(), entry.normal(), 1);
      // TODO: is it practical to fetch model data here?
      dispatcher.renderBreakingTexture(world.getBlockState(pos), pos, world, matrices, blockBuilder);
      matrices.popPose();
      rendered++;
    } while (rendered < MAX_BLOCKS && extraBlocks.hasNext());
    // finish rendering
    matrices.popPose();
    vertices.endBatch();
  }

@Override
  public void render(CombatFishingHook hook, float yaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
    Player player = hook.getPlayerOwner();
    if (player != null) {
      // setup rendering
      poseStack.pushPose();
      poseStack.pushPose();
      poseStack.scale(0.5F, 0.5F, 0.5F);
      poseStack.mulPose(this.entityRenderDispatcher.cameraOrientation());
      poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));

      // select material
      MaterialTexture texture = TEXTURE_CACHE.apply(hook.getMaterial());
      VertexConsumer consumer = buffer.getBuffer(texture.texture);
      int bobberLight = texture.applyLuminosity(packedLight);

      // render bobber
      PoseStack.Pose lastPose = poseStack.last();
      Matrix4f pose = lastPose.pose();
      Matrix3f normal = lastPose.normal();
      texture.vertex(consumer, pose, normal, bobberLight, 0f, 0, 0, 1);
      texture.vertex(consumer, pose, normal, bobberLight, 1f, 0, 1, 1);
      texture.vertex(consumer, pose, normal, bobberLight, 1f, 1, 1, 0);
      texture.vertex(consumer, pose, normal, bobberLight, 0f, 1, 0, 0);
      poseStack.popPose();

      // handle hand side
      int sideOffset = player.getMainArm() == HumanoidArm.RIGHT ? 1 : -1;
      ItemStack itemstack = player.getMainHandItem();
      if (!itemstack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
        sideOffset = -sideOffset;
      }

      // prepare string rendering
      double playerXo, playerYo, playerZo;
      float eyeHeight;
      if (this.entityRenderDispatcher.options.getCameraType().isFirstPerson() && player == Minecraft.getInstance().player) {
        double fov = 960.0 / this.entityRenderDispatcher.options.fov().get();
        Vec3 point = this.entityRenderDispatcher.camera.getNearPlane().getPointOnPlane(sideOffset * 0.525f, -0.1f);
        point = point.scale(fov);
        float attackSin = Mth.sin(Mth.sqrt(player.getAttackAnim(partialTicks)) * (float)Math.PI);
        point = point.yRot(attackSin * 0.5f);
        point = point.xRot(-attackSin * 0.7f);
        playerXo = Mth.lerp(partialTicks, player.xo, player.getX()) + point.x;
        playerYo = Mth.lerp(partialTicks, player.yo, player.getY()) + point.y;
        playerZo = Mth.lerp(partialTicks, player.zo, player.getZ()) + point.z;
        eyeHeight = player.getEyeHeight();
      } else {
        float rotation = Mth.lerp(partialTicks, player.yBodyRotO, player.yBodyRot) * ((float)Math.PI / 180F);
        double rotationSin = Mth.sin(rotation);
        double rotationCos = Mth.cos(rotation);
        double scaledSide = sideOffset * 0.35D;
        playerXo = Mth.lerp(partialTicks, player.xo, player.getX()) - rotationCos * scaledSide - rotationSin * 0.8D;
        playerYo = player.yo + player.getEyeHeight() + (player.getY() - player.yo) * (double)partialTicks - 0.45D;
        playerZo = Mth.lerp(partialTicks, player.zo, player.getZ()) - rotationSin * scaledSide + rotationCos * 0.8D;
        eyeHeight = player.isCrouching() ? -0.1875f : 0f;
      }

      // render the string
      float hookXOff = (float)(playerXo - Mth.lerp(partialTicks, hook.xo, hook.getX()));
      float hookYOff = (float)(playerYo - Mth.lerp(partialTicks, hook.yo, hook.getY()) - 0.25D) + eyeHeight;
      float hookZOff = (float)(playerZo - Mth.lerp(partialTicks, hook.zo, hook.getZ()));
      consumer = buffer.getBuffer(RenderType.lineStrip());
      lastPose = poseStack.last();
      for (int i = 0; i <= 16; i++) {
        FishingHookRenderer.stringVertex(hookXOff, hookYOff, hookZOff, consumer, lastPose, i / 16f, (i + 1) / 16f);
      }

      poseStack.popPose();
      super.render(hook, yaw, partialTicks, poseStack, buffer, packedLight);
    }
  }

public void vertex(VertexConsumer consumer, Matrix4f pose, Matrix3f normal, int lightmap, float pX, int pY, int pU, int pV) {
      consumer.vertex(pose, pX - 0.5f, pY - 0.5f, 0f)
        .color(red, green, blue, alpha)
        .uv(pU, pV)
        .overlayCoords(OverlayTexture.NO_OVERLAY)
        .uv2(lightmap)
        .normal(normal, 0.0F, 1.0F, 0.0F)
        .endVertex();
    }

