@Override
  public void renderToBuffer(PoseStack poseStack, VertexConsumer buffer, int light, int overlay, float red, float green, float blue, float alpha) {
    poseStack.pushPose();

    // from CustomHeadLayer#translateToHead, with final scale adjusted
    poseStack.translate(0.0F, -0.25F, 0.0F);
    poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
    poseStack.scale(0.5F, -0.5F, -0.5F);

    // simplified from ItemRender#render
    BakedModel model = ForgeHooksClient.handleCameraTransforms(poseStack, this.model, ItemDisplayContext.HEAD, false);
    poseStack.translate(-0.5F, -0.5F, -0.5F);
    // we don't really use rotation, but just in case
    if (yRot != 0 || xRot != 0) {
      poseStack.mulPose((new Quaternionf()).rotationZYX(0, yRot, xRot));
    }
    // applying tint is a pain with these, sop hope we don't need it
    if (red != 1 || green != 1 || blue != 1 || alpha != 1) {
      buffer = new TintedVertexBuilder(buffer, (int) (red * 255), (int) (green * 255), (int) (blue * 255), (int) (alpha * 255));
    }
    itemRenderer.renderModelLists(model, stack, light, overlay, poseStack, buffer);

    poseStack.popPose();
  }

@Override
  public void render(PoseStack matrices, MultiBufferSource buffer, int packedLight, T entity, float pLimbSwing, float swing, float partialTicks, float age, float headYaw, float headPitch) {
    ItemStack helmet = entity.getItemBySlot(EquipmentSlot.HEAD);
    if (!helmet.isEmpty()) {
      matrices.pushPose();
      if (lavaSlime) {
        float squish = Mth.lerp(partialTicks, entity.oSquish, entity.squish);
        if (squish < 0) {
          squish = 0;
        }
        matrices.translate(0, 1.5 - 0.425 * squish, 0);
      } else {
        matrices.translate(0, 1.5, 0);
      }
      matrices.scale(0.9f, 0.9f, 0.9f);

      Item item = helmet.getItem();
      // helmet renderer, based on humanoid armor layer
      if (item instanceof ArmorItem armor && armor.getType() == ArmorItem.Type.HELMET) {
        this.getParentModel().copyPropertiesTo(armorModel);
        armorModel.setAllVisible(false);
        armorModel.head.visible = true;
        armorModel.hat.visible = true;
        //noinspection UnstableApiUsage  I am reimplementing vanilla stuff, I will call vanilla hooks
        Model model = ForgeHooksClient.getArmorModel(entity, helmet, EquipmentSlot.HEAD, armorModel);
        boolean enchanted = helmet.hasFoil();
        if (armor instanceof DyeableLeatherItem dyeable) {
          int color = dyeable.getColor(helmet);
          float red = (color >> 16 & 255) / 255.0F;
          float green = (color >> 8 & 255) / 255.0F;
          float blue = (color & 255) / 255.0F;
          renderModel(matrices, buffer, packedLight, enchanted, model, red, green, blue, getArmorResource(entity, helmet, armor, ""));
          renderModel(matrices, buffer, packedLight, enchanted, model, 1.0F, 1.0F, 1.0F, getArmorResource(entity, helmet, armor, "_overlay"));
        } else {
          renderModel(matrices, buffer, packedLight, enchanted, model, 1.0F, 1.0F, 1.0F, getArmorResource(entity, helmet, armor, ""));
        }
      } else {
        // block model renderer, based on custom head layer

        // skull block rendering
        if (item instanceof BlockItem block && block.getBlock() instanceof AbstractSkullBlock skullBlock) {
          matrices.scale(1.1875F, -1.1875F, -1.1875F);
          GameProfile gameprofile = null;
          CompoundTag tag = helmet.getTag();
          if (tag != null && tag.contains("SkullOwner", Tag.TAG_COMPOUND)) {
            gameprofile = NbtUtils.readGameProfile(tag.getCompound("SkullOwner"));
          }
          matrices.translate(-0.5, 0.0, -0.5);
          SkullBlock.Type type = skullBlock.getType();
          SkullModelBase skullModel = this.skullModels.get(type);
          RenderType renderType = SkullBlockRenderer.getRenderType(type, gameprofile);
          SkullBlockRenderer.renderSkull(null, 180.0F, pLimbSwing, matrices, buffer, packedLight, skullModel, renderType);
        } else {
          // standard rendering
          CustomHeadLayer.translateToHead(matrices, false);
          Minecraft.getInstance().getEntityRenderDispatcher().getItemInHandRenderer().renderItem(entity, helmet, ItemDisplayContext.HEAD, false, matrices, buffer, packedLight);
        }
      }
      matrices.popPose();
    }
  }

@Override
        public void render(AddSectionGeometryEvent.SectionRenderingContext context) {
            // Render nothing if a shader pack is in use - transparent facades do not render well with shaders.
            // See GH-1062 for more details.
            if (!this.opaque && ModCompatHelper.hasIris()) {
                if (IrisApi.getInstance().isShaderPackInUse()) {
                    return;
                }
            }

            VertexConsumerWrapper wrapper = opaque ? null : new AlphaWrapper(context);

            RandomSource random = RANDOM.get();

            for (Map.Entry<BlockPos, BlockState> entry : facades.entrySet()) {
                context.getPoseStack().pushPose();
                context.getPoseStack()
                        .translate(entry.getKey().getX() & 15, entry.getKey().getY() & 15, entry.getKey().getZ() & 15);

                var state = entry.getValue();
                var pos = entry.getKey();

                random.setSeed(42L);

                var model = Minecraft.getInstance()
                        .getModelManager()
                        .getBlockModelShaper()
                        .getBlockModel(entry.getValue());

                var modelData = context.getRegion().getModelData(pos);

                modelData = model.getModelData(context.getRegion(), pos, state, modelData);

                for (var renderType : model.getRenderTypes(entry.getValue(), random, modelData)) {
                    VertexConsumer consumer = wrapper == null ? context.getOrCreateChunkBuffer(renderType) : wrapper;
                    Minecraft.getInstance()
                            .getBlockRenderer()
                            .getModelRenderer()
                            .tesselateBlock(context.getRegion(), model, state, pos, context.getPoseStack(), consumer,
                                    true, random, 42L, OverlayTexture.NO_OVERLAY, modelData, renderType);
                }

                context.getPoseStack().popPose();
            }
        }

@Override
    public void render(EnderfaceTravelTarget travelData, LevelRenderer levelRenderer, PoseStack poseStack,
            double distanceSquared, boolean active, float partialTick) {
        Minecraft minecraft = Minecraft.getInstance();
        OutlineBuffer buffer = OutlineBuffer.INSTANCE;
        int color = 0xFFFFFF;
        if (active) {
            color = ChatFormatting.GOLD.getColor() == null ? 0xFFFFFF : ChatFormatting.GOLD.getColor();
        }

        // Render Model
        BlockState blockState = minecraft.level.getBlockState(travelData.pos());

        BakedModel blockModel = minecraft.getBlockRenderer().getBlockModel(blockState);
        VertexConsumer solid = buffer.getBuffer(RenderType.solid());
        minecraft.getBlockRenderer()
                .getModelRenderer()
                .renderModel(poseStack.last(), solid, blockState, blockModel, 1, 1, 1, 0xF000F0,
                        OverlayTexture.NO_OVERLAY);

        // Render line
        RenderType lineType;
        if (distanceSquared > 85 * 85) {
            lineType = RenderType.lines();
        } else if (distanceSquared > 38 * 38) {
            lineType = BOLD_LINES;
        } else {
            lineType = VERY_BOLD_LINES;
        }
        VertexConsumer lines = buffer.getBuffer(lineType);
        LevelRenderer.renderLineBox(poseStack, lines, 0, 0, 0, 1, 1, 1, FastColor.ARGB32.red(color) / 255F,
                FastColor.ARGB32.green(color) / 255F, FastColor.ARGB32.blue(color) / 255F, 1);

        minecraft.renderBuffers().bufferSource().endBatch();
    }

@Override
    protected void renderSlotContent(int x, int y, int slotIndex, GuiGraphics guiGraphics, Font font) {
        var fluidStack = fluidStacksToDisplay().get(slotIndex);
        IClientFluidTypeExtensions props = IClientFluidTypeExtensions.of(fluidStack.getFluid());
        ResourceLocation still = props.getStillTexture(fluidStack);
        if (still != null) {
            AbstractTexture texture = Minecraft.getInstance().getTextureManager().getTexture(TextureAtlas.LOCATION_BLOCKS);
            if (texture instanceof TextureAtlas atlas) {
                TextureAtlasSprite sprite = atlas.getSprite(still);

                int color = props.getTintColor();
                RenderSystem.setShaderColor(FastColor.ARGB32.red(color) / 255.0F,
                    FastColor.ARGB32.green(color) / 255.0F, FastColor.ARGB32.blue(color) / 255.0F,
                    FastColor.ARGB32.alpha(color) / 255.0F);
                RenderSystem.enableBlend();

                int atlasWidth = (int) (sprite.contents().width() / (sprite.getU1() - sprite.getU0()));
                int atlasHeight = (int) (sprite.contents().height() / (sprite.getV1() - sprite.getV0()));
                guiGraphics.blit(TextureAtlas.LOCATION_BLOCKS, x + 1, y + 1, 16, 16, sprite.getU0() * atlasWidth,
                    sprite.getV0() * atlasHeight, sprite.contents().width(), sprite.contents().height(), atlasWidth,
                    atlasHeight);
                RenderSystem.setShaderColor(1, 1, 1, 1);
            }
        }
    }

