@Override
    public void render(AnchorTravelTarget travelData, LevelRenderer levelRenderer, PoseStack poseStack,
            double distanceSquared, boolean active, float partialTick) {
        Minecraft minecraft = Minecraft.getInstance();
        if (Objects.isNull(minecraft.level) || !travelData.isVisible()) {
            return;
        }

        poseStack.pushPose();

        Camera camera = minecraft.gameRenderer.getMainCamera();
        Vec3 cameraPos = camera.getPosition();
        Vec3 offsetToCamera = travelData.pos().getCenter().vectorTo(cameraPos);
        Vec3 towardsCamera = offsetToCamera.normalize();
        double distanceToCamera = offsetToCamera.length();

        {
            double anchorScale = (float) Math.sqrt(distanceToCamera);
            if (active) {
                anchorScale = anchorScale * 1.3;
            }
            anchorScale = anchorScale * (Math.sin(Math.toRadians(minecraft.options.fov().get() / 4d)));
            anchorScale = Math.max(anchorScale, 1.0F);

            poseStack.translate(0.5, 0.5, 0.5);
            float s = (float) anchorScale;
            poseStack.scale(s, s, s);
            poseStack.translate(-0.5, -0.5, -0.5);
        }

        OutlineBuffer buffer = OutlineBuffer.INSTANCE;
        int outlineColor = 0xFF0B4D42;
        int textColor = 0xFFFFFFFF;
        if (active) {
            textColor = ChatFormatting.AQUA.getColor() == null ? 0xFFFFFF : ChatFormatting.AQUA.getColor();
            outlineColor = textColor;
        }
        float outlineR = ((outlineColor >> 16) & 0xFF) / 255F;
        float outlineG = ((outlineColor >> 8) & 0xFF) / 255F;
        float outlineB = (outlineColor & 0xFF) / 255F;

        VertexConsumer renderBuffer = buffer.getBuffer(RenderType.tripwire());

        int packedLight = LightTexture.pack(15, 15);

        Block iconBlock = Block.byItem(travelData.icon());

        BlockState blockState;
        boolean iconIsFullBlock = false;

        if (iconBlock != Blocks.AIR && BaseConfig.CLIENT.ANCHORS_USE_ICON_AS_BLOCK.get()) {
            blockState = iconBlock.defaultBlockState();
            iconIsFullBlock = Block.isShapeFullBlock(blockState.getOcclusionShape(minecraft.level, travelData.pos()));
        } else {
            blockState = minecraft.level.getBlockState(travelData.pos());

            if (minecraft.level.getBlockEntity(travelData.pos()) instanceof PaintedTravelAnchorBlockEntity paintedTravelAnchorBlock) {
                Optional<Block> paint = paintedTravelAnchorBlock.getPrimaryPaint();

                if (paint.isPresent()) {
                    blockState = paint.get().defaultBlockState();
                }
            }
        }

        boolean hasIcon = !(travelData.icon() == Items.AIR || iconIsFullBlock);

        if (!hasIcon) {
            // Render Model
            {
                BakedModel blockModel = minecraft.getBlockRenderer().getBlockModel(blockState);
                BlockColors blockColors = minecraft.getBlockColors();

                var randomSource = RandomSource.create(42L);
                ArrayList<BakedQuad> quads = new ArrayList<>(blockModel.getQuads(blockState, null, randomSource));
                for (Direction direction : Direction.values()) {
                    randomSource.setSeed(42L);
                    quads.addAll(blockModel.getQuads(blockState, direction, randomSource));
                }

                for (BakedQuad quad : quads) {
                    int tintIndex = quad.getTintIndex();
                    float r = 1F, g = 1F, b = 1F;

                    if (tintIndex != -1) {
                        int color = blockColors.getColor(blockState, minecraft.level, travelData.pos(), tintIndex);
                        r = ((color >> 16) & 0xFF) / 255F;
                        g = ((color >> 8) & 0xFF) / 255F;
                        b = (color & 0xFF) / 255F;
                    }

                    renderBuffer.putBulkData(poseStack.last(), quad, r, g, b, 1.0F, packedLight, OverlayTexture.NO_OVERLAY);
                }
            }

            // Render outline block
            {
                poseStack.pushPose();

                float outlineSize = active ? 0.2F : 0.15F;
                float scale = 1F + 2 * outlineSize;
                Vec3 offset = towardsCamera.scale(-scale).subtract(outlineSize, outlineSize, outlineSize);

                poseStack.translate(offset.x, offset.y, offset.z);
                poseStack.scale(scale, scale, scale);

                for (BakedQuad quad : BACKDROP_QUADS.get()) {
                    renderBuffer.putBulkData(poseStack.last(), quad, outlineR, outlineG, outlineB, 1, packedLight, OverlayTexture.NO_OVERLAY);
                }

                poseStack.popPose();
            }
        } else {
            // Render Icon
            poseStack.pushPose();

            {
                Vector3f upDir = new Vec3(0, 1, 0)
                    .xRot(-camera.getXRot() * ((float) Math.PI / 180F))
                    .yRot(-camera.getYRot() * ((float) Math.PI / 180F))
                    .toVector3f();
                Vector3f direction = towardsCamera.toVector3f();
                Quaternionf iconRotation = new Quaternionf().lookAlong(direction.x(), direction.y(), direction.z(), upDir.x(), upDir.y(), upDir.z());

                Vec3 offset = towardsCamera.scale(0.9);

                poseStack.translate(offset.x() + 0.5, offset.y() + 0.5, offset.z() + 0.5);
                poseStack.mulPose(iconRotation.invert());
                float s = active ? 1.3F : 1.0F;
                poseStack.scale(-s, s, -s);
            }

            ItemStack stack = travelData.icon().getDefaultInstance();
            BakedModel bakedmodel = minecraft.getItemRenderer().getModel(stack, minecraft.level, null, 0);
            minecraft
                .getItemRenderer()
                .render(stack, ItemDisplayContext.GUI, false, poseStack, OutlineBuffer.INSTANCE, packedLight, OverlayTexture.NO_OVERLAY, bakedmodel);

            float s = 1.5F;
            poseStack.scale(s, s, s);
            poseStack.translate(-0.5, -0.5, -2);
            poseStack.rotateAround(Axis.ZN.rotationDegrees(45), 0.5F, 0.5F, 0.5F);

            for (BakedQuad quad : BACKDROP_QUADS.get()) {
                renderBuffer.putBulkData(poseStack.last(), quad, outlineR, outlineG, outlineB, 1, packedLight, OverlayTexture.NO_OVERLAY);
            }

            poseStack.popPose();
        }

        if (!travelData.name().trim().isEmpty()) {
            // Render Text
            poseStack.pushPose();

            {
                Quaternionf textRotation = Axis.YN.rotationDegrees(camera.getYRot()).mul(Axis.XP.rotationDegrees(camera.getXRot()));
                int lineHeight = minecraft.font.lineHeight;
                double scale = 0.1;
                double textOffsetY = scale * lineHeight + 1.25;
                if (hasIcon && active) {
                    textOffsetY += 0.15;
                }

                poseStack.translate(0.5, 0.5, 0.5);
                poseStack.mulPose(textRotation);
                poseStack.translate(0, textOffsetY, 0);
                float s = (float) scale;
                poseStack.scale(-s, -s, s);
            }

            Component textComponent = Component.literal(travelData.name().trim());

            float textOpacitySetting = minecraft.options.getBackgroundOpacity(0.5f);
            int textBg = (int) (textOpacitySetting * 255) << 24;
            float halfWidth = (float) (-minecraft.font.width(textComponent) / 2);

            var mode1 = Font.DisplayMode.SEE_THROUGH;
            var mode2 = Font.DisplayMode.NORMAL;
            int textBg1 = textBg;
            int textBg2 = 0;

            if (ModCompatHelper.hasIris()) {
                // required for text to render correctly, possibly an Iris bug
                // is there a better way to draw text?
                var _m = mode1;
                mode1 = mode2;
                mode2 = _m;

                int _t = textBg1;
                textBg1 = textBg2;
                textBg2 = _t;
            }
            Matrix4f matrix4f = poseStack.last().pose();

            minecraft.font.drawInBatch(textComponent, halfWidth, 0, textColor, false, matrix4f, buffer, mode1, textBg1, packedLight);
            minecraft.font.drawInBatch(textComponent, halfWidth, 0, textColor, false, matrix4f, buffer, mode2, textBg2, packedLight);

            poseStack.popPose();
        }

        poseStack.popPose();
        // Seems to work fine without this line, but leaving it here in case there are future buffer problems
        // minecraft.renderBuffers().bufferSource().endBatch();
    }

private static void addTravelParticle(Vec3 pos) {
        int time = tick/3%20;
        float x = Mth.sin((float)(time*Math.PI)/10f);
        float z = Mth.cos((float)(time*Math.PI)/10f);
        @Nullable Particle particle = Minecraft.getInstance().levelRenderer.addParticleInternal(
            ParticleTypes.TOTEM_OF_UNDYING, false, true, pos.x() + x, pos.y() + 0.4, pos.z() + z, 0, 0, 0);
        if (particle != null) {
            particle.setLifetime(30);
            var color = getTravelParticleColor();
            particle.gravity = 0;
            particle.setColor(color.getLeft(), color.getMiddle(), color.getRight());
        }
    }

@SubscribeEvent
    public static void renderLevel(RenderLevelStageEvent event) {
        ClientLevel level = Minecraft.getInstance().level;
        LocalPlayer player = Minecraft.getInstance().player;
        if (level == null || player == null || event.getStage() != RenderLevelStageEvent.Stage.AFTER_TRIPWIRE_BLOCKS) {
            return;
        }

        if (!TravelHandler.canTeleport(player) && !KeymapHandler.showTravelTargets()) {
            return;
        }

        boolean itemTeleport = TravelHandler.canItemTeleport(player) || KeymapHandler.showTravelTargets();

        @Nullable
        TravelTarget activeTarget = TravelHandler.getTeleportAnchorTarget(player).orElse(null);
        for (TravelTarget target : TravelTargetApi.INSTANCE.getAll(level)) {
            double range = itemTeleport ? target.item2BlockRange() : target.block2BlockRange();
            double distanceSquared = target.pos().distToCenterSqr(player.position());
            if (range * range < distanceSquared || distanceSquared < TravelHandler.MIN_TELEPORTATION_DISTANCE_SQUARED
                    || TravelHandler.isTeleportPositionClear(level, target.pos()).isEmpty()) {
                continue;
            }

            PoseStack poseStack = event.getPoseStack();
            poseStack.pushPose();
            Camera mainCamera = Minecraft.getInstance().gameRenderer.getMainCamera();
            Vec3 projectedView = mainCamera.getPosition();
            poseStack.translate(
                target.pos().getX() - projectedView.x,
                target.pos().getY() - projectedView.y,
                target.pos().getZ() - projectedView.z);

            boolean active = activeTarget == target;

            // needed for smooth rendering
            // the boolean value controls whether it's still smooth while the game world is
            // paused (e.g. /tick freeze)
            float partialTick = event.getPartialTick().getGameTimeDeltaPartialTick(true);

            render(target, event.getLevelRenderer(), poseStack, distanceSquared, active, partialTick);
            poseStack.popPose();
        }
    }

