                    renderState.getRenderDataOrDefault(ModEntityRenderStates.MIST_FLOW, Vec3.ZERO),
                    event.getPoseStack());
        }
    }

public static void renderFluidTank(Level level, BlockPos pos, @Nullable FluidStack fluidStack, int capacity, Vec3 translation, Vec3 scale, PoseStack poseStack, SubmitNodeCollector nodeCollector, int packedLight, int packedOverlay) {
        if (fluidStack == null || fluidStack.isEmpty()) return;

        float filled = Mth.clamp((float) fluidStack.getAmount() / capacity, 0f, 1f);

        poseStack.pushPose();

        poseStack.translate(0.5, 0.5, 0.5);
        poseStack.translate(translation);
        poseStack.scale((float) scale.x, (float) scale.y, (float) scale.z);
        poseStack.translate(-0.5, -0.5, -0.5);


        FluidState fluidState = fluidStack.getFluid().defaultFluidState();

        FluidModel fluidModel = Minecraft.getInstance().getModelManager().getFluidStateModelSet().get(fluidState);
        ChunkSectionLayer renderLayer = fluidModel.layer();
        int tintColor = fluidModel.fluidTintSource() != null ? fluidModel.fluidTintSource().color(fluidState) : -1;
        TextureAtlasSprite still = fluidModel.stillMaterial().sprite();

        RenderType type = switch (renderLayer) {
            case SOLID -> RenderTypes.solidMovingBlock();
            case TRANSLUCENT -> RenderTypes.translucentMovingBlock();
            case CUTOUT -> RenderTypes.cutoutMovingBlock();
        };


        float u1 = still.getU(0);
        float u2 = still.getU(1);
        float v1 = still.getV(0);
        float v2 = still.getV(1);

        float height = 1 * filled;


        // West side (x=0)
        nodeCollector.submitCustomGeometry(poseStack, type, (pose, vertexBuilder) -> {
            vertexBuilder.addVertex(pose, 0, 0, 0).setColor(tintColor).setUv(u1, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
            vertexBuilder.addVertex(pose, 0, 0, 1).setColor(tintColor).setUv(u1, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
            vertexBuilder.addVertex(pose, 0, height, 1).setColor(tintColor).setUv(u2, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
            vertexBuilder.addVertex(pose, 0, height, 0).setColor(tintColor).setUv(u2, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
        });

        // East side (x=1)
        nodeCollector.submitCustomGeometry(poseStack, RenderTypes.translucentMovingBlock(), (pose, vertexBuilder) -> {
            vertexBuilder.addVertex(pose, 1, 0, 1).setColor(tintColor).setUv(u1, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(1, 0, 0);
            vertexBuilder.addVertex(pose, 1, 0, 0).setColor(tintColor).setUv(u1, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(1, 0, 0);
            vertexBuilder.addVertex(pose, 1, height, 0).setColor(tintColor).setUv(u2, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(1, 0, 0);
            vertexBuilder.addVertex(pose, 1, height, 1).setColor(tintColor).setUv(u2, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(1, 0, 0);
        });

        // North side (z=0)
        nodeCollector.submitCustomGeometry(poseStack, RenderTypes.translucentMovingBlock(), (pose, vertexBuilder) -> {
            vertexBuilder.addVertex(pose, 1, 0, 0).setColor(tintColor).setUv(u1, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, -1);
            vertexBuilder.addVertex(pose, 0, 0, 0).setColor(tintColor).setUv(u1, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, -1);
            vertexBuilder.addVertex(pose, 0, height, 0).setColor(tintColor).setUv(u2, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, -1);
            vertexBuilder.addVertex(pose, 1, height, 0).setColor(tintColor).setUv(u2, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, -1);
        });

        // South side (z=1)
        nodeCollector.submitCustomGeometry(poseStack, RenderTypes.translucentMovingBlock(), (pose, vertexBuilder) -> {
            vertexBuilder.addVertex(pose, 0, 0, 1).setColor(tintColor).setUv(u1, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, 1);
            vertexBuilder.addVertex(pose, 1, 0, 1).setColor(tintColor).setUv(u1, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, 1);
            vertexBuilder.addVertex(pose, 1, height, 1).setColor(tintColor).setUv(u2, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, 1);
            vertexBuilder.addVertex(pose, 0, height, 1).setColor(tintColor).setUv(u2, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 0, 1);
        });

        // Bottom face (y=0)
        nodeCollector.submitCustomGeometry(poseStack, RenderTypes.translucentMovingBlock(), (pose, vertexBuilder) -> {
            vertexBuilder.addVertex(pose, 0, 0, 0).setColor(tintColor).setUv(u1, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, -1, 0);
            vertexBuilder.addVertex(pose, 1, 0, 0).setColor(tintColor).setUv(u1, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, -1, 0);
            vertexBuilder.addVertex(pose, 1, 0, 1).setColor(tintColor).setUv(u2, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, -1, 0);
            vertexBuilder.addVertex(pose, 0, 0, 1).setColor(tintColor).setUv(u2, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, -1, 0);
        });

        // Top face (y=1)
        nodeCollector.submitCustomGeometry(poseStack, RenderTypes.translucentMovingBlock(), (pose, vertexBuilder) -> {
            vertexBuilder.addVertex(pose, 0, height, 1).setColor(tintColor).setUv(u1, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
            vertexBuilder.addVertex(pose, 1, height, 1).setColor(tintColor).setUv(u1, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
            vertexBuilder.addVertex(pose, 1, height, 0).setColor(tintColor).setUv(u2, v2).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
            vertexBuilder.addVertex(pose, 0, height, 0).setColor(tintColor).setUv(u2, v1).setLight(packedLight).setOverlay(packedOverlay).setNormal(0, 1, 0);
        });

        poseStack.popPose();
    }

public static void draw(String label, RenderPipeline pipeline, Matrix4fc modelView, List<Matrix4f> instances) {
        if (instances.isEmpty()) return;

        // Under fabulous graphics the stage these are drawn in targets the separate weather target, as
        // WorldBorderRenderer does right after; anywhere else it is the main target.
        RenderTarget weather = Minecraft.getInstance().levelRenderer.getWeatherTarget();
        RenderTarget scene = weather != null ? weather : Minecraft.getInstance().getMainRenderTarget();
        GpuTextureView sceneColor = scene.getColorTextureView();
        GpuTextureView sceneDepth = scene.getDepthTextureView();
        if (sceneColor == null || sceneDepth == null) return;

        TextureTarget reduced = reducedTarget(scene);
        GpuTextureView colorTarget = reduced.getColorTextureView();
        if (colorTarget == null) return;

        GpuBuffer quad = unitQuad();
        RenderSystem.AutoStorageIndexBuffer indices = RenderSystem.getSequentialBuffer(VertexFormat.Mode.QUADS);
        GpuBuffer indexBuffer = indices.getBuffer(6);
        SamplerCache samplers = RenderSystem.getSamplerCache();
        // Resolved before the pass opens, not at the bind below: the first call builds and uploads the sheet,
        // and a texture write is one of the commands the encoder refuses to record mid-pass.
        GpuTextureView noise = VolumetricNoise.view();

        // Every instance's uniforms are written up front, before the pass is opened - the ring buffer they land
        // in must not be written to while a pass is recording. Riding in the texture matrix slot of the standard
        // per-draw uniform means this pass needs no GPU buffer of its own.
        DynamicUniforms.Transform[] transforms = instances.stream().map(params -> new DynamicUniforms.Transform(modelView, NO_COLOR_MODULATION, NO_MODEL_OFFSET, params.m33((float) HALF_RESOLUTION_SCALE))).toArray(DynamicUniforms.Transform[]::new);
        GpuBufferSlice[] uniforms = RenderSystem.getDynamicUniforms().writeTransforms(transforms);

        // Cleared to transparent black, which is the identity the premultiplied accumulation below builds on -
        // volumes overlapping inside the offscreen target blend against each other exactly as they would have
        // against the scene, so compositing the result once is equivalent to having drawn them straight.
        OptionalInt clear = OptionalInt.of(0);

        try (RenderPass pass = RenderSystem.getDevice().createCommandEncoder().createRenderPass(() -> label, colorTarget, clear)) {
            pass.setPipeline(pipeline);
            RenderSystem.bindDefaultUniforms(pass);
            pass.bindTexture("DepthSampler", sceneDepth, samplers.getClampToEdge(FilterMode.NEAREST));
            // Repeat and linear are both load-bearing: the sheet is sampled at unbounded coordinates as the
            // noise drifts, and the filtering is the interpolation that makes it noise at all.
            pass.bindTexture("NoiseSampler", noise, samplers.getRepeat(FilterMode.LINEAR));
            pass.setVertexBuffer(0, quad);
            pass.setIndexBuffer(indexBuffer, indices.type());

            for (GpuBufferSlice uniform : uniforms) {
                pass.setUniform("DynamicTransforms", uniform);
                pass.drawIndexed(0, 0, 6, 1);
            }
        }

        composite(label, reduced, sceneColor, samplers);
    }

private static GpuBuffer unitQuad() {
        if (quadBuffer == null) {
            VertexFormat format = DefaultVertexFormat.POSITION;
            try (ByteBufferBuilder allocator = ByteBufferBuilder.exactlySized(format.getVertexSize() * 4)) {
                BufferBuilder builder = new BufferBuilder(allocator, VertexFormat.Mode.QUADS, format);
                builder.addVertex(-1.0f, -1.0f, 0.0f);
                builder.addVertex(1.0f, -1.0f, 0.0f);
                builder.addVertex(1.0f, 1.0f, 0.0f);
                builder.addVertex(-1.0f, 1.0f, 0.0f);
                try (MeshData mesh = builder.buildOrThrow()) {
                    quadBuffer = RenderSystem.getDevice().createBuffer(() -> "Vampirism volumetric billboard quad", GpuBuffer.USAGE_VERTEX, mesh.vertexBuffer());
                }
            }
        }
        return quadBuffer;
    }

private static void renderBeam(PoseStack poseStack, SubmitNodeCollector nodeCollector, float textureOffset, float dx, float dy, float dz, int packedLight, boolean beacon) {
        float distFlat = Mth.sqrt(dx * dx + dz * dz);
        float dist = Mth.sqrt(dx * dx + dy * dy + dz * dz);

        Identifier texture = beacon ? BEACON_BEAM_LOCATION : INFUSION_BEAM_LOCATION;
        float uvScrollV = textureOffset * 0.05f;
        float uvScrollVFar = dist / 32.0F + textureOffset * 0.05f;

        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotation((float) -Math.atan2(dz, dx) - (float) (Math.PI / 2)));
        poseStack.mulPose(Axis.XP.rotation((float) -Math.atan2(distFlat, dy) - (float) (Math.PI / 2)));

        nodeCollector.submitCustomGeometry(poseStack, RenderTypes.endCrystalBeam(texture), (pose, vertexBuilder) -> {
            Matrix4f matrix = pose.pose();

            float prevSin = 0.0F;
            float prevCos = 0.2F;
            float prevU = 0.0F;

            for (int side = 1; side <= BEAM_SIDES; side++) {
                float angle = side * ((float) Math.PI * 2F) / BEAM_SIDES;
                float sin = Mth.sin(angle) * BEAM_NEAR_RADIUS;
                float cos = Mth.cos(angle) * BEAM_NEAR_RADIUS;
                float u = (float) side / BEAM_SIDES;

                vertexBuilder.addVertex(matrix, prevSin, prevCos, 0.0F).setColor( 75, 0, 0, 255).setUv(prevU, uvScrollV).setOverlay(OverlayTexture.NO_OVERLAY).setLight(packedLight).setNormal(pose, 0, -1, 0);
                vertexBuilder.addVertex(matrix, prevSin * 0.5f, prevCos * 0.5f, dist).setColor(255, 0, 0, 255).setUv(prevU, uvScrollVFar).setOverlay(OverlayTexture.NO_OVERLAY).setLight(packedLight).setNormal(pose, 0, -1, 0);
                vertexBuilder.addVertex(matrix, sin * 0.5f, cos * 0.5f, dist).setColor(255, 0, 0, 255).setUv(u, uvScrollVFar).setOverlay(OverlayTexture.NO_OVERLAY).setLight(packedLight).setNormal(pose, 0, -1, 0);
                vertexBuilder.addVertex(matrix, sin, cos, 0.0F).setColor( 75, 0, 0, 255).setUv(u, uvScrollV).setOverlay(OverlayTexture.NO_OVERLAY).setLight(packedLight).setNormal(pose, 0, -1, 0);

                prevSin = sin;
                prevCos = cos;
                prevU = u;
            }
        });

        poseStack.popPose();
    }

