        nodeCollector.submitBlockModel(poseStack, RenderTypes.cutoutMovingBlock(), List.of(this.bottom[renderState.color.getId()]), EMPTY_TINTS, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);

