                    .setColor(255, 255, 255, 255)
                    .setUv(u, 0)
                    .setLight(FULL_BRIGHT);
            builder.addVertex(posMat, width, height, 0)
                    .setColor(255, 255, 255, 255)
                    .setUv(u, v)
