public static void render3d(PoseStack poseStack, MultiBufferSource buffer, float minX, float minY, float maxX, float maxY, float zLevel, float progress, int color1, int color2) {
        Pair<float[], float[]> cols = calcColors(color1, color2, progress);
        float[] f1 = cols.getLeft();
        float[] f2 = cols.getRight();

        float x = Mth.lerp(progress / 100F, minX, maxX);

        // draw the bar
        RenderUtils.renderWithTypeAndFinish(poseStack, buffer, ModRenderTypes.UNTEXTURED_QUAD_NO_DEPTH, (posMat, builder) -> {
            builder.addVertex(posMat, minX, minY, zLevel).setColor(f1[0], f1[1], f1[2], f1[3]).setLight(FULL_BRIGHT);
            builder.addVertex(posMat, minX, minY + (maxY - minY), zLevel).setColor(f1[0], f1[1], f1[2], f1[3]).setLight(FULL_BRIGHT);
            builder.addVertex(posMat, x, minY + (maxY - minY), zLevel).setColor(f2[0], f2[1], f2[2], f2[3]).setLight(FULL_BRIGHT);
            builder.addVertex(posMat, x, minY, zLevel).setColor(f2[0], f2[1], f2[2], f2[3]).setLight(FULL_BRIGHT);
        });

        // draw the outline
        final Matrix3f normal = poseStack.last().normal();
        RenderUtils.renderWithTypeAndFinish(poseStack, buffer, ModRenderTypes.getLineLoops(1.5), (posMat, builder) -> {
            normalLine(builder, poseStack, minX, minY, zLevel, minX, maxY, zLevel, 255,0, 0, 0, true);
            normalLine(builder, poseStack, minX, maxY, zLevel, maxX, maxY, zLevel, 255,0, 0, 0, true);
            normalLine(builder, poseStack, maxX, maxY, zLevel, maxX, minY, zLevel, 255,0, 0, 0, true);
            normalLine(builder, poseStack, maxX, minY, zLevel, minX, minY, zLevel, 255,0, 0, 0, true);
        });
    }

public static void render2d(GuiGraphics graphics, float minX, float minY, float maxX, float maxY, float zLevel, float progress, int color1, int color2) {
        Pair<float[], float[]> cols = calcColors(color1, color2, progress);
        float[] f1 = cols.getLeft();
        float[] f2 = cols.getRight();

        float x = Mth.lerp(progress / 100F, minX, maxX);

        Matrix4f posMat = graphics.pose().last().pose();

        RenderSystem.setShader(GameRenderer::getPositionColorShader);

        BufferBuilder builder = Tesselator.getInstance().begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_COLOR);
        builder.addVertex(posMat, minX, minY, zLevel).setColor(f1[0], f1[1], f1[2], f1[3]);
        builder.addVertex(posMat, minX, minY + (maxY - minY), zLevel).setColor(f1[0], f1[1], f1[2], f1[3]);
        builder.addVertex(posMat, x, minY + (maxY - minY), zLevel).setColor(f2[0], f2[1], f2[2], f2[3]);
        builder.addVertex(posMat, x, minY, zLevel).setColor(f2[0], f2[1], f2[2], f2[3]);
        BufferUploader.drawWithShader(builder.buildOrThrow());

        RenderSystem.lineWidth(2.0f);
        builder = Tesselator.getInstance().begin(VertexFormat.Mode.DEBUG_LINE_STRIP, DefaultVertexFormat.POSITION_COLOR);
        builder.addVertex(posMat, minX, minY, zLevel).setColor(0, 0, 0, 1f);
        builder.addVertex(posMat, minX, maxY, zLevel).setColor(0, 0, 0, 1f);
        builder.addVertex(posMat, maxX, maxY, zLevel).setColor(0, 0, 0, 1f);
        builder.addVertex(posMat, maxX, minY, zLevel).setColor(0, 0, 0, 1f);
        BufferUploader.drawWithShader(builder.buildOrThrow());
    }

@SubscribeEvent
    public void renderLevelStageEvent(RenderLevelStageEvent event) {
        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES) return;

        Player player = ClientUtils.getClientPlayer();

        MultiBufferSource.BufferSource buffer = Minecraft.getInstance().renderBuffers().bufferSource();
        PoseStack matrixStack = event.getPoseStack();

        matrixStack.pushPose();

        Vec3 projectedView = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        matrixStack.translate(-projectedView.x, -projectedView.y, -projectedView.z);

        // block entity controlled renderers
        for (AreaRenderer handler : showHandlers.values()) {
            handler.render(matrixStack, buffer);
        }

        // some special rendering for certain items
        maybeRenderPositionProvider(matrixStack, buffer, player);
        maybeRenderCamo(matrixStack, buffer, player);
        maybeRenderDroneDebug(matrixStack, buffer, player);
        maybeRenderAreaTool(matrixStack, buffer, player);
        maybeRenderJackhammer(matrixStack, buffer, player);
        maybeRenderCoordinateTracker(matrixStack, buffer, player, event.getPartialTick());

        matrixStack.popPose();
    }

private void maybeRenderCoordinateTracker(PoseStack matrixStack, MultiBufferSource.BufferSource buffer, Player player, DeltaTracker partialTicks) {
        CoordTrackerHandler handler = CommonUpgradeHandlers.coordTrackerHandler;
        if (CommonArmorHandler.getHandlerForPlayer().upgradeUsable(handler, true)) {
            BlockPos pos = ClientArmorRegistry.getInstance().getClientHandler(handler, CoordTrackClientHandler.class).getTrackedPos();
            if (pos != null) {
                float progress = (player.level().getGameTime() % 20 + partialTicks.getGameTimeDeltaPartialTick(false)) / 20;
                float g = progress < 0.5F ? progress + 0.5F : 1.5F - progress;
                int col = 0xA00000FF | (int)(g * 255) << 8;
                Vec3 targetVec = Vec3.atCenterOf(pos);
                float size = ClientUtils.calculateViewScaling(targetVec);
                float textSize = size * 0.02f;
                matrixStack.pushPose();
                matrixStack.translate(targetVec.x(), targetVec.y(), targetVec.z());
                matrixStack.scale(textSize, textSize, textSize);
                RenderUtils.rotateToPlayerFacing(matrixStack);
                RenderUtils.renderString3d(Component.literal(PneumaticCraftUtils.posToString(pos)), 0, 0, 0xFFFFFFFF, matrixStack, buffer, true, true);
                matrixStack.popPose();
                AreaRenderer.builder().withColor(col).xray().withSize(size / 2f).build(pos).render(matrixStack, buffer);
            }
        }
    }

private void maybeRenderJackhammer(PoseStack matrixStack, MultiBufferSource.BufferSource buffer, Player player) {
        if (level == null
                || !(player.getMainHandItem().getItem() instanceof JackHammerItem)
                || !((Minecraft.getInstance().hitResult) instanceof BlockHitResult)) {
            return;
        }
        JackHammerItem.DigMode digMode = JackHammerItem.getDigMode(player.getMainHandItem());
        if (digMode == JackHammerItem.DigMode.MODE_1X1) return;

        BlockHitResult brtr = (BlockHitResult) Minecraft.getInstance().hitResult;
        if (!level.isLoaded(brtr.getBlockPos()) || level.getBlockState(brtr.getBlockPos()).isAir()) return;

        if (!lastJackhammerDetails.matches(brtr.getBlockPos(), brtr.getDirection(), digMode, player.isShiftKeyDown())) {
            BlockState state = level.getBlockState(brtr.getBlockPos());
            Set<BlockPos> posSet = level.getBlockEntity(brtr.getBlockPos()) == null && !(state.getBlock() instanceof LiquidBlock) ?
                    JackHammerItem.getBreakPositions(level, brtr.getBlockPos(), brtr.getDirection(), player, digMode) :
                    Collections.emptySet();
            if (!posSet.isEmpty()) posSet.add(brtr.getBlockPos());
            AreaRenderer.Builder b = AreaRenderer.builder().withColor(0x20FFFFFF).withSize(1.01f).disableWriteMask();
            if (state.getShape(level, brtr.getBlockPos()) != (Shapes.block())) b = b.drawShapes();
            jackhammerPositionShower = b.build(posSet);
            lastJackhammerDetails = new LastJackhammerDetails(brtr.getBlockPos(), brtr.getDirection(), digMode, player.isShiftKeyDown());
        }
        jackhammerPositionShower.render(matrixStack, buffer);
    }

public AreaRenderer showArea(Set<BlockPos> area, int color, BlockEntity areaShower, boolean depth) {
        if (areaShower == null) return null;
        removeHandlers(areaShower);
        AreaRenderer.Builder builder = AreaRenderer.builder().withColor(color);
        if (depth) builder.xray();
        AreaRenderer handler = builder.build(area);
        showHandlers.put(new BlockPos(areaShower.getBlockPos().getX(), areaShower.getBlockPos().getY(), areaShower.getBlockPos().getZ()), handler);
        return handler;
    }

