        matrixStackIn.translate(0.0D, 1.0D, -0.09375D);
        matrixStackIn.mulPose(Axis.XP.rotationDegrees(te.heightAngle));
        matrixStackIn.translate(0.0D, -1.0D, 0.09375D);
