private void renderBlades(VacuumPumpBlockEntity te, float partialTicks, PoseStack matrixStackIn, VertexConsumer builder, int combinedLightIn, int combinedOverlayIn) {
        float rotation = Mth.lerp(partialTicks, te.oldRotation, te.rotation) + 1;

        matrixStackIn.pushPose();
        matrixStackIn.translate(0, -0.68f, 1f);
        matrixStackIn.scale(0.8f, 0.8f, 0.8f);
        for (int i = 0; i < BLADE_COUNT; i++) {
            matrixStackIn.pushPose();
            matrixStackIn.mulPose(Axis.YP.rotationDegrees(rotation * 2 + (i + 0.5F) / BLADE_COUNT * 360));
            matrixStackIn.translate(0, 0, 1D / 16D);
            blade.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();
        }
        matrixStackIn.popPose();

        matrixStackIn.mulPose(Axis.YP.rotationDegrees(180));
    }

@Override
    public void render(VortexEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        if (!entity.hasRenderOffsetX()) {
            entity.setRenderOffsetX(calculateXoffset());
        }

        matrixStackIn.pushPose();

        VertexConsumer builder = bufferIn.getBuffer(ModRenderTypes.getTextureRenderColored(getTextureLocation(entity)));

        matrixStackIn.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot())));
        matrixStackIn.mulPose(Axis.XP.rotationDegrees(-Mth.lerp(partialTicks, entity.xRotO, entity.getXRot())));
        float incr = (float) (2 * Math.PI / CIRCLE_POINTS);
        for (float angleRads = 0f; angleRads < 2 * Math.PI; angleRads += incr) {
            matrixStackIn.pushPose();
            matrixStackIn.translate(RADIUS * Mth.sin(angleRads), RADIUS * Mth.cos(angleRads), 0);
            renderGust(matrixStackIn, builder, entity.getRenderOffsetX(), packedLightIn);
            matrixStackIn.popPose();
        }

        matrixStackIn.popPose();
    }

private void renderGust(PoseStack matrixStackIn, VertexConsumer wr, float xOffset, int packedLightIn) {
        float u1 = 0F;
        float u2 = 1F;
        float v1 = 0F;
        float v2 = 1F;

        matrixStackIn.scale(TEX_SCALE, TEX_SCALE, TEX_SCALE);
        matrixStackIn.translate(xOffset, 0, 0);
        matrixStackIn.mulPose(Axis.YP.rotationDegrees(90));

        Matrix4f posMat = matrixStackIn.last().pose();

        wr.addVertex(posMat, -7.0F, -2.0F, -2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u1, v1).setLight(packedLightIn);
        wr.addVertex(posMat, -7.0F, -2.0F, 2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u2, v1).setLight(packedLightIn);
        wr.addVertex(posMat, -7.0F, 2.0F, 2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u2, v2).setLight(packedLightIn);
        wr.addVertex(posMat, -7.0F, 2.0F, -2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u1, v2).setLight(packedLightIn);

        wr.addVertex(posMat, -7.0F, 2.0F, -2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u1, v1).setLight(packedLightIn);
        wr.addVertex(posMat, -7.0F, 2.0F, 2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u2, v1).setLight(packedLightIn);
        wr.addVertex(posMat, -7.0F, -2.0F, 2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u2, v2).setLight(packedLightIn);
        wr.addVertex(posMat, -7.0F, -2.0F, -2.0F).setColor(1f, 1f, 1f, 0.5f).setUv(u1, v2).setLight(packedLightIn);
    }

@Override
    public void render(MicromissileEntity entityIn, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        // mostly lifted from ArrowRenderer
        matrixStackIn.pushPose();

        matrixStackIn.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entityIn.yRotO, entityIn.getYRot()) - 90.0F));
        matrixStackIn.mulPose(Axis.ZP.rotationDegrees(Mth.lerp(partialTicks, entityIn.xRotO, entityIn.getXRot())));
        matrixStackIn.mulPose(Axis.XP.rotationDegrees(45.0F));

        matrixStackIn.scale(0.05625F, 0.05625F, 0.05625F);
        matrixStackIn.translate(-4.0D, 0.0D, 0.0D);

        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(this.getTextureLocation(entityIn)));
        PoseStack.Pose pose = matrixStackIn.last();
        vertex(pose, builder, -7, -2, -2, 0.0F, 0.15625F, -1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, -2, 2, 0.15625F, 0.15625F, -1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, 2, 2, 0.15625F, 0.3125F, -1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, 2, -2, 0.0F, 0.3125F, -1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, 2, -2, 0.0F, 0.15625F, 1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, 2, 2, 0.15625F, 0.15625F, 1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, -2, 2, 0.15625F, 0.3125F, 1, 0, 0, packedLightIn);
        vertex(pose, builder, -7, -2, -2, 0.0F, 0.3125F, 1, 0, 0, packedLightIn);

        for (int j = 0; j < 4; ++j) {
            matrixStackIn.mulPose(Axis.XP.rotationDegrees(90.0F));
            vertex(pose, builder, -8, -2, 0, 0.0F, 0.0F, 0, 1, 0, packedLightIn);
            vertex(pose, builder, 8, -2, 0, 0.5F, 0.0F, 0, 1, 0, packedLightIn);
            vertex(pose, builder, 8, 2, 0, 0.5F, 0.15625F, 0, 1, 0, packedLightIn);
            vertex(pose, builder, -8, 2, 0, 0.0F, 0.15625F, 0, 1, 0, packedLightIn);
        }

        matrixStackIn.popPose();
    }

@Override
    public void render(TumblingBlockEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        ItemStack stack = entity.getStack();
        if (stack.isEmpty() || !(stack.getItem() instanceof BlockItem)) {
            return;
        }
        Block block = ((BlockItem) stack.getItem()).getBlock();
        BlockState state = block.defaultBlockState();
        if (state.getRenderShape() == RenderShape.MODEL) {
            Level world = entity.getCommandSenderWorld();
            if (state != world.getBlockState(entity.blockPosition()) && state.getRenderShape() != RenderShape.INVISIBLE) {
                matrixStackIn.pushPose();
                if (entity.tumbleVec != null) {
                    // spin the block on the x & z axes
                    matrixStackIn.translate(0, 0.5, 0);
                    float angle = ((entity.tickCount + partialTicks) * 18);
                    matrixStackIn.mulPose(Axis.of(entity.tumbleVec).rotationDegrees(angle));
                    matrixStackIn.translate(-0.5, -0.5, -0.5);
                }

                BlockPos blockpos = BlockPos.containing(entity.getX(), entity.getBoundingBox().maxY, entity.getZ());
                BlockRenderDispatcher renderer = Minecraft.getInstance().getBlockRenderer();
                BakedModel blockModel = renderer.getBlockModel(state);
                for (RenderType type : blockModel.getRenderTypes(state, world.getRandom(), ModelData.EMPTY)) {
                    renderer.getModelRenderer().tesselateBlock(world, blockModel, state, blockpos, matrixStackIn, bufferIn.getBuffer(type), false, world.getRandom(), state.getSeed(entity.getOrigin()), OverlayTexture.NO_OVERLAY, ModelData.EMPTY, type);
                }
                matrixStackIn.popPose();
            }
        }
    }

@Override
    public void render(PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn, AbstractDroneEntity entityIn, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        BlockPos diggingPos = entityIn.getDugBlock();
        if (diggingPos != null) {
            matrixStackIn.pushPose();
            matrixStackIn.mulPose(Axis.XP.rotationDegrees(180));
            matrixStackIn.translate(0, -1, 0);
            BlockState state = entityIn.getCommandSenderWorld().getBlockState(diggingPos);
            VoxelShape shape = state.getShape(entityIn.getCommandSenderWorld(), diggingPos);
            if (shape.isEmpty()) {
                renderLaser(matrixStackIn, bufferIn, partialTicks, entityIn,
                        0, -entityIn.getLaserOffsetY(), 0,
                        diggingPos.getX() + 0.5 - entityIn.getX(), diggingPos.getY() + 0.45 - entityIn.getY(), diggingPos.getZ() + 0.5 - entityIn.getZ());
            } else {
                Vec3 vec = shape.bounds().getCenter().add(Vec3.atLowerCornerOf(diggingPos));
                renderLaser(matrixStackIn, bufferIn, partialTicks, entityIn,
                        0, -entityIn.getLaserOffsetY(), 0,
                        vec.x() - entityIn.getX(), vec.y() - entityIn.getY(), vec.z() - entityIn.getZ());
            }
            matrixStackIn.popPose();
        }
    }

@SuppressWarnings("SameParameterValue")
    private void renderLaser(PoseStack matrixStack, MultiBufferSource buffer, float partialTicks, AbstractDroneEntity drone, double x1, double y1, double z1, double x2, double y2, double z2) {
        float laserLength = (float) PneumaticCraftUtils.distBetween(x1, y1, z1, x2, y2, z2);

        matrixStack.pushPose();

        matrixStack.translate(x1, y1, z1);

        double dx = x2 - x1;
        double dy = y2 - y1;
        double dz = z2 - z1;
        float f3 = Mth.sqrt((float) (dx * dx + dz * dz));
        double rotYawRad = Math.atan2(dx, dz);
        double rotPitchRad = Math.PI / 2.0 - Math.atan2(dy, f3);

        matrixStack.mulPose(Axis.YP.rotation((float) rotYawRad));
        matrixStack.mulPose(Axis.XP.rotation((float) rotPitchRad));

        matrixStack.scale(LASER_SIZE, LASER_SIZE, LASER_SIZE);
        matrixStack.translate(0, 0.6, 0);
        matrixStack.mulPose(Axis.YP.rotationDegrees(drone.tickCount + partialTicks));

        matrixStack.pushPose();
        matrixStack.scale(1f, laserLength / LASER_SIZE * 2, 1f);

        int[] cols = RenderUtils.decomposeColor(drone.getLaserColor());

        // todo 1.15 consider stitching these 4 into one texture for less state switching
        VertexConsumer builder;

        Matrix4f posMat = matrixStack.last().pose();
        builder = buffer.getBuffer(ModRenderTypes.getTextureRenderColored(Textures.RENDER_LASER));
        renderQuad(posMat, builder, cols);  // glow
        builder = buffer.getBuffer(ModRenderTypes.getTextureRenderColored(Textures.RENDER_LASER_OVERLAY));
        renderQuad(posMat, builder, cols);  // core

        matrixStack.popPose();

        matrixStack.mulPose(Axis.XP.rotationDegrees(180));

        posMat = matrixStack.last().pose();
        builder = buffer.getBuffer(ModRenderTypes.getTextureRenderColored(Textures.RENDER_LASER_START));
        renderQuad(posMat, builder, cols);  // glow
        builder = buffer.getBuffer(ModRenderTypes.getTextureRenderColored(Textures.RENDER_LASER_START_OVERLAY));
        renderQuad(posMat, builder, cols);  // core

        matrixStack.popPose();
    }

private void renderHeldItem(@Nonnull ItemStack stack, PoseStack matrixStack, MultiBufferSource buffer, int packedLight, int packedOverlay, Level level) {
        matrixStack.pushPose();

        // note: transform is currently set up so items render upside down
        matrixStack.translate(0.0D, 1.5D, 0.0D);
        if (!(stack.getItem() instanceof DiggerItem || stack.getItem() instanceof SwordItem || stack.getItem() instanceof HoeItem)) {
            // since items are rendered suspended under the drone,
            // holding tools upside down looks more natural - especially if the drone is digging with them
            matrixStack.mulPose(Axis.XP.rotationDegrees(180));
        }
        float scaleFactor = stack.getItem() instanceof BlockItem ? 0.7F : 0.5F;
        matrixStack.scale(scaleFactor, scaleFactor, scaleFactor);
        Minecraft.getInstance().getItemRenderer().renderStatic(stack, ItemDisplayContext.FIXED, packedLight, packedOverlay, matrixStack, buffer, level, 0);

        matrixStack.popPose();
    }

