        model.renderToBuffer(matrixStackIn, builder, kludgeLightingLevel(entityIn, packedLightIn), OverlayTexture.pack(0F, false), 0xFF000000);
        matrixStackIn.popPose();
    }

@Override
    public void render(AbstractLogisticsFrameEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        float alpha = entity.getAlpha() / 255F;
        if (alpha == 0f) return;

        if (entity.isAir()) {
            return;
        }

        matrixStackIn.pushPose();

        if (entity.getTimeSinceHit() > 0) {
            wobble(entity, partialTicks, matrixStackIn);
        }

        Direction side = entity.getSide();
        matrixStackIn.translate(0, side.getAxis() == Direction.Axis.Y ? 0.5 : -0.5, 0);
        switch (side) {
            case UP:
                matrixStackIn.mulPose(Axis.ZP.rotationDegrees(90));
                matrixStackIn.translate(0, -1, 0);
                break;
            case DOWN:
                matrixStackIn.mulPose(Axis.ZP.rotationDegrees(-90));
                matrixStackIn.translate(0, -1, 0);
                break;
            case NORTH:
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(90));
                break;
            case SOUTH:
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(-90));
                break;
            case WEST:
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(180));
                break;
            case EAST:
                break;
        }

        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityTranslucent(getTextureLocation(entity)));
        int color = FastColor.ARGB32.color((int) (255 * alpha), 255, 255, 255);
        model.renderToBuffer(matrixStackIn, builder, kludgeLightingLevel(entity, packedLightIn), OverlayTexture.pack(0F, false), color);

        matrixStackIn.popPose();
    }

void wobble(T entityIn, float partialTicks, PoseStack matrixStack) {
        float f = (float) entityIn.getTimeSinceHit() - partialTicks;
        float f1 = entityIn.getDamageTaken() - partialTicks;
        if (f1 < 0.0F) {
            f1 = 0.0F;
        }

        if (f > 0.0F) {
            Vec3 look = Minecraft.getInstance().player.getViewVector(partialTicks);
            Vector3f wobble = new Vector3f((float)look.z(), 0.0F, -(float)look.x());
            matrixStack.mulPose(Axis.of(wobble).rotationDegrees(Mth.sin(f) * f * f1 / 10.0F * 1));
        }
    }

@Override
    public void render(SpawnerAgitatorEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        float g = 0.1f * Mth.sin((entity.level().getGameTime() + partialTicks) / 12f);

        matrixStackIn.pushPose();
        matrixStackIn.translate(0, 1.5, 0);
        matrixStackIn.mulPose(Axis.XP.rotationDegrees(180F));
        if (entity.getTimeSinceHit() > 0) {
            wobble(entity, partialTicks, matrixStackIn);
        }
        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(getTextureLocation(entity)));
        int color = FastColor.ARGB32.color(255, 51, (int) (255 * (0.8f + g)), 51);
        model.renderToBuffer(matrixStackIn, builder, packedLightIn, OverlayTexture.pack(0F, false), color);
        matrixStackIn.popPose();

    }

@Override
    public void render(TransferGadgetEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        if (entity.isAir()) {
            return;
        }

        matrixStackIn.pushPose();

        if (entity.getTimeSinceHit() > 0) {
            wobble(entity, partialTicks, matrixStackIn);
        }

        Direction side = entity.getSide();
        matrixStackIn.translate(0, side.getAxis() == Direction.Axis.Y ? 1.2 : -1.1, 0);
        switch (side) {
            case UP -> {
                matrixStackIn.mulPose(Axis.ZP.rotationDegrees(90));
                matrixStackIn.translate(-1.1, -1.1, 0);
            }
            case DOWN -> {
                matrixStackIn.mulPose(Axis.ZP.rotationDegrees(-90));
                matrixStackIn.translate(1.3, -1.1, 0);
            }
            case NORTH -> matrixStackIn.mulPose(Axis.YP.rotationDegrees(90));
            case SOUTH -> matrixStackIn.mulPose(Axis.YP.rotationDegrees(-90));
            case WEST -> matrixStackIn.mulPose(Axis.YP.rotationDegrees(180));
        }

        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(getTextureLocation(entity)));
        model.renderToBuffer(matrixStackIn, builder, kludgeLightingLevel(entity, packedLightIn), OverlayTexture.pack(0F, false), 0xFFFFFFFF);

        matrixStackIn.popPose();
    }

public static void renderFluid(VertexConsumer builder, TankRenderInfo tankRenderInfo, Matrix4f posMat, int combinedLight, int combinedOverlay) {
        IFluidTank tank = tankRenderInfo.getTank();
        if (tank.getFluidAmount() == 0) return;

        Fluid fluid = tank.getFluid().getFluid();
        IClientFluidTypeExtensions renderProps = IClientFluidTypeExtensions.of(fluid);
        ResourceLocation texture = renderProps.getStillTexture(tank.getFluid());
        TextureAtlasSprite still = Minecraft.getInstance().getTextureAtlas(InventoryMenu.BLOCK_ATLAS).apply(texture);
        int[] cols = RenderUtils.decomposeColor(renderProps.getTintColor(tank.getFluid()));

        AABB bounds = getRenderBounds(tank, tankRenderInfo.getBounds());
        float x1 = (float) bounds.minX;
        float x2 = (float) bounds.maxX;
        float y1 = (float) bounds.minY;
        float y2 = (float) bounds.maxY;
        float z1 = (float) bounds.minZ;
        float z2 = (float) bounds.maxZ;

        if (tankRenderInfo.shouldRender(Direction.DOWN)) {
            float u1 = still.getU(x1);
            float u2 = still.getU(x2);
            float v1 = still.getV(z1);
            float v2 = still.getV(z2);
            builder.addVertex(posMat, x1, y1, z2).setColor(cols[1], cols[2], cols[3], cols[0]).setUv(u1, v2).setOverlay(combinedOverlay).setLight(combinedLight).setNormal(0f, -1f, 0f);
            builder.addVertex(posMat, x1, y1, z1).setColor(cols[1], cols[2], cols[3], cols[0]).setUv(u1, v1).setOverlay(combinedOverlay).setLight(combinedLight).setNormal(0f, -1f, 0f);
            builder.addVertex(posMat, x2, y1, z1).setColor(cols[1], cols[2], cols[3], cols[0]).setUv(u2, v1).setOverlay(combinedOverlay).setLight(combinedLight).setNormal(0f, -1f, 0f);
            builder.addVertex(posMat, x2, y1, z2).setColor(cols[1], cols[2], cols[3], cols[0]).setUv(u2, v2).setOverlay(combinedOverlay).setLight(combinedLight).setNormal(0f, -1f, 0f);
