@Override
    public void render(GuiGraphics graphics, DeltaTracker deltaTracker) {
        Minecraft mc = Minecraft.getInstance();
        Player player = mc.player;

        if (player == null || mc.options.hideGui || mc.screen != null
                || !PneumaticArmorItem.isPlayerWearingAnyPneumaticArmor(player)) {
            return;
        }

        Window mw = Minecraft.getInstance().getWindow();
        graphics.pose().pushPose();
        CommonArmorHandler comHudHandler = CommonArmorHandler.getHandlerForPlayer(player);

        boolean anyArmorInInit = false;
        for (EquipmentSlot slot : ArmorUpgradeRegistry.ARMOR_SLOTS) {
            ItemStack armorStack = player.getItemBySlot(slot);
            if (armorStack.getItem() instanceof PneumaticArmorItem && comHudHandler.getArmorPressure(slot) >= 0.0001f
                    && !comHudHandler.isArmorReady(slot)) {
                anyArmorInInit = true;
                break;
            }
        }

        float partialTicks = deltaTracker.getGameTimeDeltaPartialTick(true);

        for (EquipmentSlot slot : ArmorUpgradeRegistry.ARMOR_SLOTS) {
            ItemStack armorStack = player.getItemBySlot(slot);
            if (armorStack.getItem() instanceof PneumaticArmorItem && comHudHandler.getArmorPressure(slot) >= 0.0001F) {
                if (anyArmorInInit) {
                    // draw initialization progress bar(s)
                    renderInitProgressBarForSlot(graphics, partialTicks, mw, comHudHandler, slot, armorStack);
                }
                if (comHudHandler.isArmorReady(slot)) {
                    renderHUDForSlot(graphics, partialTicks, player, comHudHandler, slot);
                }
            }
        }

        // render every pending message
        HUDHandler.getInstance().renderMessages(graphics, partialTicks);

        graphics.pose().popPose();

        // show armor initialisation percentages
        if (comHudHandler.isArmorEnabled() && anyArmorInInit) {
            for (EquipmentSlot slot : ArmorUpgradeRegistry.ARMOR_SLOTS) {
                if (isPneumaticArmorPiece(player, slot) && comHudHandler.getArmorPressure(slot) > 0F) {
                    String text = Math.min(100, comHudHandler.getTicksSinceEquipped(slot) * 100 / comHudHandler.getStartupTime(slot)) + "%";
                    graphics.drawString(mc.font, text, mw.getGuiScaledWidth() * 0.75f - 8, 14 + PROGRESS_BAR_HEIGHT * (3 - slot.getIndex()), 0xFFFF40, true);
                }
            }
        }
    }

private void renderInitProgressBarForSlot(GuiGraphics graphics, float partialTicks, Window mw, CommonArmorHandler comHudHandler, EquipmentSlot slot, ItemStack armorStack) {
        if (comHudHandler.isArmorEnabled()) {
            int xLeft = mw.getGuiScaledWidth() / 2;
            int yOffset = 10 + (3 - slot.getIndex()) * PROGRESS_BAR_HEIGHT;
            float progress = comHudHandler.getTicksSinceEquipped(slot) * 100f / comHudHandler.getStartupTime(slot);
            progress = Math.min(100, progress + partialTicks);
            RenderSystem.enableBlend();
            RenderSystem.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
            ProgressBarRenderer.render2d(graphics, mw.getGuiScaledWidth() / 2f, yOffset,
                    mw.getGuiScaledWidth() - 10, yOffset + PROGRESS_BAR_HEIGHT - 1, -90F,
                    progress, 0xAAFFC000, 0xAA00FF00);
            RenderSystem.disableBlend();
            graphics.renderItem(armorStack, xLeft + 2, yOffset);
        }
    }

public void render(PoseStack matrixStack, MultiBufferSource buffer, float partialTicks) {
        matrixStack.pushPose();

        double x = pos.getX() + 0.5D;
        double y = pos.getY() + 0.5D;
        double z = pos.getZ() + 0.5D;

        matrixStack.translate(x, y, z);

        if (!world.isEmptyBlock(pos)) {
            renderBlockHighlight(matrixStack, buffer, world, pos, partialTicks);
        }

        RenderUtils.rotateToPlayerFacing(matrixStack);

        float targetAcquireProgress = (ticksExisted + partialTicks) / 1.2f;

        if (ticksExisted > START_ACQUIRE_TIME && ticksExisted <= FINISH_ACQUIRE_TIME) {
            ProgressBarRenderer.render3d(matrixStack, buffer,0, 0.4F, 1.8F, 0.7F, 0, targetAcquireProgress, 0xD0FFFF00, 0xD000FF00);
        }

        matrixStack.scale(STAT_SCALE, STAT_SCALE, STAT_SCALE);

        if (!world.isEmptyBlock(pos)) {
            if (ticksExisted > FINISH_ACQUIRE_TIME) {
                if (isPlayerLookingAtTarget()) {
                    // a bit of growing or shrinking to keep the stat on screen and/or of legible size
                    float mul = ClientUtils.getStatSizeMultiplier(Mth.sqrt((float) ClientUtils.getClientPlayer().distanceToSqr(x, y, z)));
                    matrixStack.scale(mul, mul, mul);
                    stat.renderStat(matrixStack, buffer, partialTicks);
                }
            } else if (ticksExisted > START_ACQUIRE_TIME) {
                RenderUtils.renderString3d(Component.translatable("pneumaticcraft.entityTracker.info.acquiring"), 0, 0, 0xFFD0D0D0, matrixStack, buffer, false, true);
                RenderUtils.renderString3d(Component.literal((int)targetAcquireProgress + "%"), 37, 24, 0xFFD0D0D0, matrixStack, buffer, false, true);
            } else if (ticksExisted < LOST_TARGET_TIME) {
                matrixStack.scale(1.5F, 1.5F, 1.5F);
                stat.renderStat(matrixStack, buffer, partialTicks);
                RenderUtils.renderString3d(Component.translatable("pneumaticcraft.blockTracker.info.lostTarget"), 0, -ticksExisted / 2.5f, 0xFFFF0000, matrixStack, buffer, false, true);
            }
        }

        matrixStack.popPose();
    }

private void renderBlockHighlight(PoseStack matrixStack, MultiBufferSource buffer, Level world, BlockPos pos, float partialTicks) {
        BlockState state = world.getBlockState(pos);
        VoxelShape shape = state.getShape(world, pos);
        if (shape.isEmpty()) return;

        float progress = ((world.getGameTime() & 0x1f) + partialTicks) / 32f;
        float cycle = Mth.sin((float) (progress * Math.PI));

        float shrink = (shape == Shapes.block() ? 0.05f : 0f) + cycle / 60f;
        AABB aabb = shape.bounds().deflate(shrink);

        float alpha = blockTracker.getFocusedPos() != null ? (blockTracker.getFocusedPos().equals(pos) ? 0.75f : 0.15f) : 0.5f;

        matrixStack.pushPose();
        matrixStack.translate(-0.5, -0.5, -0.5);
        RenderType type = RenderUtils.renderFrame(matrixStack, buffer, aabb, 1/64f, 0.25f, 0.75f, 0.75f, alpha, FULL_BRIGHT);
        RenderUtils.finishBuffer(buffer, type);
        matrixStack.popPose();
    }

