public void render(PoseStack matrixStack, MultiBufferSource buffer, float partialTicks) {
        for (Pair<RenderCoordWireframe, Integer> wireframe : blackListWireframes) {
            wireframe.getKey().render(matrixStack, buffer, partialTicks);
        }

        if (PneumaticArmorItem.isPlayerDebuggingDrone(ClientUtils.getClientPlayer(), drone)) {
            IProgWidget activeWidget = getActiveWidget(drone);
            if (activeWidget != null) {
                double x, y, z;
                if (pos != null) {
                    x = getInterpolated(pos.getX(), oldPos.getX(), partialTicks);
                    y = getInterpolated(pos.getY(), oldPos.getY(), partialTicks);
                    z = getInterpolated(pos.getZ(), oldPos.getZ(), partialTicks);
                } else {
                    x = Mth.lerp(partialTicks, drone.xo, drone.getX());
                    y = Mth.lerp(partialTicks, drone.yo, drone.getY()) + 0.5;
                    z = Mth.lerp(partialTicks, drone.zo, drone.getZ());
                }
                matrixStack.pushPose();
                matrixStack.translate(x, y + 0.5, z);
                matrixStack.scale(0.01f, 0.01f, 0.01f);
                matrixStack.mulPose(Axis.XP.rotationDegrees(180));
                matrixStack.mulPose(Axis.YP.rotationDegrees(Minecraft.getInstance().gameRenderer.getMainCamera().getYRot()));
                ProgWidgetRenderer.renderProgWidget3d(matrixStack, buffer, activeWidget);
                matrixStack.popPose();
            }
        }
    }

public void render(PoseStack matrixStack, MultiBufferSource buffer, float partialTicks, boolean justRenderWhenHovering) {
        trackEntries.forEach(tracker -> tracker.render(matrixStack, buffer, entity, partialTicks));

        double x = Mth.lerp(partialTicks, entity.xo, entity.getX());
        double y = Mth.lerp(partialTicks, entity.yo, entity.getY()) + entity.getBbHeight() / 2D;
        double z = Mth.lerp(partialTicks, entity.zo, entity.getZ());

        matrixStack.pushPose();

        matrixStack.translate(x, y, z);
        RenderUtils.rotateToPlayerFacing(matrixStack);

        float size = entity.getBbHeight() * 0.5F;
        float alpha = 0.5F;
        if (ticksExisted < 60) {
            size += 5 - Math.abs(ticksExisted) * 0.083F;
            alpha = Math.abs(ticksExisted) * 0.005F;
        }
        float renderSize = Mth.lerp(partialTicks, oldSize, size);

        circle1.render(matrixStack, buffer, renderSize, partialTicks, alpha);
        circle2.render(matrixStack, buffer, renderSize + 0.2F, partialTicks, alpha);

        float targetAcquireProgress = ((ticksExisted + partialTicks - 50) / 0.7F);
        if (ticksExisted > 50 && ticksExisted <= 120) {
            ProgressBarRenderer.render3d(matrixStack, buffer, 0F, 0.4F, 1.8F, 0.7F, 0, targetAcquireProgress,  0xD0FFFF00, 0xD000FF00);
        }

        matrixStack.scale(STAT_SCALE, STAT_SCALE, STAT_SCALE);

        if (ticksExisted > 120) {
            if (justRenderWhenHovering && !isLookingAtTarget) {
                stat.closeStat();
            } else {
                stat.openStat();
            }
            textList = new ArrayList<>();
            for (IEntityTrackEntry tracker : trackEntries) {
                tracker.addInfo(entity, textList, isLookingAtTarget);
            }
            textList.add(xlate("pneumaticcraft.gui.misc.distanceMeters", String.format("%.1f", distToEntity)));
            stat.setText(textList);
            // a bit of growing or shrinking to keep the stat on screen and/or of legible size
            float mul = getStatSizeMultiplier(distToEntity);
            matrixStack.scale(mul, mul, mul);
            stat.renderStat(matrixStack, buffer, partialTicks);
        } else if (ticksExisted > 50) {
            RenderUtils.renderString3d(Component.translatable("pneumaticcraft.entityTracker.info.acquiring"), 0, 0, 0xFF7F7F7F, matrixStack, buffer, false, true);
            RenderUtils.renderString3d(Component.literal((int)targetAcquireProgress + "%"), 37, 24, 0xFF002F00, matrixStack, buffer, false, true);
        } else if (ticksExisted < -30) {
            stat.closeStat();
            stat.renderStat(matrixStack, buffer, partialTicks);
            RenderUtils.renderString3d(Component.translatable("pneumaticcraft.blockTracker.info.lostTarget"), 0, 0, 0xFF7F7F7F, matrixStack, buffer, false, true);
        }

        matrixStack.popPose();

        oldSize = size;
    }

public void render(PoseStack poseStack, MultiBufferSource buffer, float size, float partialTicks, float alpha) {
            double renderRotationAngle = Mth.lerp(partialTicks, oldRotationAngle, rotationAngle);

            poseStack.pushPose();

            poseStack.mulPose(Axis.ZP.rotationDegrees((float) renderRotationAngle));

            for (int pass = 0; pass < 2; pass++) {
                RenderUtils.renderWithTypeAndFinish(poseStack, buffer, ModRenderTypes.TARGET_CIRCLE, (posMat, builder) -> {
                    for (float i = 0; i < QUARTER_CIRCLE; i += STEP) {
                        RenderUtils.posF(builder, posMat,Mth.cos(i) * size, Mth.sin(i) * size, 0)
                                .setColor(cols[0], cols[1], cols[2], alpha)
                                .setLight(FULL_BRIGHT);
                        RenderUtils.posF(builder, posMat,Mth.cos(i) * (size + 0.1F), Mth.sin(i) * (size + 0.1F), 0)
                                .setColor(cols[0], cols[1], cols[2], alpha)
                                .setLight(FULL_BRIGHT);
                    }
                });

                if (renderAsTagged) {
                    RenderUtils.renderWithTypeAndFinish(poseStack, buffer, ModRenderTypes.getLineLoops(3.0), (posMat, builder) -> {
                        for (float i = 0; i < QUARTER_CIRCLE; i += STEP) {
                            Vec3 v1 = new Vec3(Mth.cos(i) * size, Mth.sin(i) * size, 0);
                            Vec3 v2 = new Vec3(Mth.cos(i + STEP) * size, Mth.sin(i + STEP) * size, 0);
                            RenderUtils.posF(builder, posMat, v1.x(), v1.y(), 0)
                                    .setColor(255, 0, 0, 255)
                                    .setNormal(poseStack.last(), (float) (v2.x() - v1.x()), (float) (v2.y() - v1.y()), 0f);
                        }
                        for (float i = QUARTER_CIRCLE - STEP; i >= 0f; i -= STEP) {
                            Vec3 v1 = new Vec3(Mth.cos(i) * size, Mth.sin(i) * size, 0);
                            Vec3 v2 = new Vec3(Mth.cos(i + STEP) * size, Mth.sin(i + STEP) * size, 0);
                            RenderUtils.posF(builder, posMat, v1.x(), v1.y(), 0)
                                    .setColor(255, 0, 0, 255)
                                    .setNormal(poseStack.last(), (float) (v2.x() - v1.x()), (float) (v2.y() - v1.y()), 0f);
                        }
                    });
                }

                poseStack.mulPose(Axis.ZP.rotationDegrees(180));
            }
            poseStack.popPose();
        }

public void render(PoseStack matrixStack, MultiBufferSource buffer, boolean wirePath, boolean xRayEnabled, float partialTicks) {
        if (path == null) return;

        boolean hasDestinationPath = tracedToDestination();

        matrixStack.pushPose();
        matrixStack.translate(0, 0.01D, 0);

        Matrix4f posMat = matrixStack.last().pose();
        if (wirePath) {
            // Draws just wires
            // TODO line stippling would be nice here
            VertexConsumer builder = buffer.getBuffer(ModRenderTypes.getLineLoops(5.0));
            for (int i = 1; i < path.getNodeCount(); i++) {
                float red = 1;
                if (path.getNodeCount() - i < 200) {
                    red = (path.getNodeCount() - i) * 0.005F;
                }
                Node lastPoint = path.getNode(i - 1);
                Node pathPoint = path.getNode(i);
                builder.addVertex(posMat, lastPoint.x + 0.5F, lastPoint.y, lastPoint.z + 0.5F)
                        .setColor(red, 1 - red, 0, 0.5f)
                        .setNormal(matrixStack.last(), pathPoint.x - lastPoint.x, pathPoint.y - lastPoint.y, pathPoint.z - lastPoint.z);
                builder.addVertex(posMat, (lastPoint.x + pathPoint.x) / 2F + 0.5F, Math.max(lastPoint.y, pathPoint.y), (lastPoint.z + pathPoint.z) / 2F + 0.5F)
                        .setColor(red, 1 - red, 0, 0.5f)
                        .setNormal(matrixStack.last(), pathPoint.x - lastPoint.x, pathPoint.y - lastPoint.y, pathPoint.z - lastPoint.z);
                builder.addVertex(posMat, pathPoint.x + 0.5F, pathPoint.y, pathPoint.z + 0.5F)
                        .setColor(red, 1 - red, 0, 0.5f)
                        .setNormal(matrixStack.last(), pathPoint.x - lastPoint.x, pathPoint.y - lastPoint.y, pathPoint.z - lastPoint.z);
            }
        } else {
            VertexConsumer builder = buffer.getBuffer(xRayEnabled ? ModRenderTypes.UNTEXTURED_QUAD_NO_DEPTH : ModRenderTypes.UNTEXTURED_QUAD);
            if (hasDestinationPath) {
                if (alphaValue > 0.2F) alphaValue -= 0.005F;
            } else {
                if (increaseAlpha) {
                    alphaValue += 0.005F;
                    if (alphaValue > 0.3F) increaseAlpha = false;
                } else {
                    alphaValue -= 0.005F;
                    if (alphaValue < 0.2F) increaseAlpha = true;
                }
            }
            for (int i = 0; i < path.getNodeCount(); i++) {
                float red = 1;
                if (path.getNodeCount() - i < 200) {
                    red = (path.getNodeCount() - i) * 0.005F;
                }
                Node pathPoint = path.getNode(i);
                builder.addVertex(posMat, pathPoint.x, pathPoint.y, pathPoint.z)
                        .setColor(red, 1 - red, 0, alphaValue)
                        .setLight(FULL_BRIGHT);
                builder.addVertex(posMat, pathPoint.x, pathPoint.y, pathPoint.z + 1)
                        .setColor(red, 1 - red, 0, alphaValue)
                        .setLight(FULL_BRIGHT);
                builder.addVertex(posMat, pathPoint.x + 1, pathPoint.y, pathPoint.z + 1)
                        .setColor(red, 1 - red, 0, alphaValue)
                        .setLight(FULL_BRIGHT);
                builder.addVertex(posMat, pathPoint.x + 1, pathPoint.y, pathPoint.z)
                        .setColor(red, 1 - red, 0, alphaValue)
                        .setLight(FULL_BRIGHT);
            }
        }

        matrixStack.popPose();
    }

public static void renderSearch(PoseStack matrixStack, VertexConsumer builder, double x, double y, double z, int itemCount, int totalCount, float partialTicks) {
        matrixStack.pushPose();

        matrixStack.translate(x, y, z);
        RenderUtils.rotateToPlayerFacing(matrixStack);
        float ratio = (float) itemCount / totalCount;
        float diff = (1 - ratio) / 1.5F;
        float size = 1 - diff;
        float f = ((ClientUtils.getClientLevel().getGameTime() & 0x1f) + partialTicks) / 5.092f;  // 0 .. 2*pi every 32 ticks
        float alpha = 0.65F + Mth.sin(f) * 0.15f;
        Matrix4f posMat = matrixStack.last().pose();
        builder.addVertex(posMat, -size, size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(0, 1)
                .setLight(LightTexture.FULL_BRIGHT);
        builder.addVertex(posMat, size, size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(1, 1)
                .setLight(LightTexture.FULL_BRIGHT);
        builder.addVertex(posMat, size, -size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(1, 0)
                .setLight(LightTexture.FULL_BRIGHT);
        builder.addVertex(posMat, -size, -size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(0, 0)
                .setLight(LightTexture.FULL_BRIGHT);

        matrixStack.popPose();
    }

