private static void drawGaugeBackground(Matrix4f posMat, VertexConsumer builder, float minPressure, float maxPressure, float dangerPressure, float minWorkingPressure, int xPos, int yPos) {
        float[] color = RED;

        int explodeBoundary = GAUGE_POINTS - (int) ((dangerPressure - minPressure) / (maxPressure - minPressure) * GAUGE_POINTS);
        int workingBoundary = GAUGE_POINTS - (int) ((minWorkingPressure - minPressure) / (maxPressure - minPressure) * GAUGE_POINTS);

        boolean changedColorGreen = false;
        boolean changedColorYellow = false;

        for (int i = 0; i < GAUGE_POINTS; i++) {
            if (i == explodeBoundary && !changedColorGreen) {
                color = minWorkingPressure < 0 && minWorkingPressure >= -1 ? YELLOW : GREEN;
                changedColorGreen = true;
            }
            if (i == workingBoundary && !changedColorYellow) {
                color = minWorkingPressure < 0 && minWorkingPressure >= -1 ? GREEN : YELLOW;
                changedColorYellow = true;
            }
            float angle = -i / (float) CIRCLE_POINTS * 2F * PI_F - STOP_ANGLE;
            float angle2 = -(i + 1) / (float) CIRCLE_POINTS * 2F * PI_F - STOP_ANGLE;

            builder.addVertex(posMat, xPos, yPos, 0f).setColor(0.5f, 0.5f, 0.1f, 1f);

            builder.addVertex(posMat, Mth.cos(angle) * RADIUS + xPos, Mth.sin(angle) * RADIUS + yPos, 0f)
                .setColor(color[0], color[1], color[2], color[3]);
            builder.addVertex(posMat, Mth.cos(angle2) * RADIUS + xPos, Mth.sin(angle2) * RADIUS + yPos, 0f)
            	.setColor(color[0], color[1], color[2], color[3]);
        }
    }

private static void drawNeedle(PoseStack poseStack, VertexConsumer builder, int xPos, int yPos, float angle, int fgColor) {
        float[] cols = RenderUtils.decomposeColorF(fgColor);

        float x1 = Mth.cos(angle + 0.89F * PI_F) * RADIUS * 0.3F + xPos;
        float y1 = Mth.sin(angle + 0.89F * PI_F) * RADIUS * 0.3F + yPos;

        float x2 = Mth.cos(angle + 1.11F * PI_F) * RADIUS * 0.3F + xPos;
        float y2 = Mth.sin(angle + 1.11F * PI_F) * RADIUS * 0.3F + yPos;

        float x3 = Mth.cos(angle) * RADIUS * 0.8F + xPos;
        float y3 = Mth.sin(angle) * RADIUS * 0.8F + yPos;

        // Edge 1: x1 -> x2
        RenderUtils.normalLine(builder, poseStack,
                x1, y1, 0f,
                x2, y2, 0f,
                cols[0], cols[1], cols[2], cols[3],
                false);

        // Edge 2: x2 -> x3
        RenderUtils.normalLine(builder, poseStack,
                x2, y2, 0f,
                x3, y3, 0f,
                cols[0], cols[1], cols[2], cols[3],
                false);

        // Edge 3: x3 -> x1
        RenderUtils.normalLine(builder, poseStack,
                x3, y3, 0f,
                x1, y1, 0f,
                cols[0], cols[1], cols[2], cols[3],
                false);
    }

public final void renderModule(T module, PoseStack matrixStack, MultiBufferSource buffer, float partialTicks, int combinedLight, int combinedOverlay) {
        matrixStack.pushPose();

        // transforms to get model orientation right
        matrixStack.translate(0.5, 1.5, 0.5);
        matrixStack.scale(1f, -1f, -1f);

        RenderUtils.rotateMatrixForDirection(matrixStack, module.getDirection());
        int alpha = module.isFake() ? 80 : 255;

        VertexConsumer builder = module.isFake() ?
                buffer.getBuffer(RenderType.entityTranslucent(getTexture(module.isUpgraded()))) :
                buffer.getBuffer(RenderType.entityCutout(getTexture(module.isUpgraded())));
        render(module, matrixStack, builder, partialTicks, combinedLight, combinedOverlay, alpha);

        matrixStack.popPose();

        renderExtras(module, matrixStack, buffer, partialTicks, combinedLight, combinedOverlay);
    }

@Override
    protected void render(LogisticsModule module, PoseStack matrixStack, VertexConsumer builder, float partialTicks, int combinedLight, int combinedOverlay, int alpha) {
        ModelPart base;
        if (module.getTicksSinceAction() >= 0) {
            base = action;
        } else if (module.getTicksSinceNotEnoughAir() >= 0) {
            base = notEnoughAir;
        } else {
            base = module.hasPower() ? powered : notPowered;
        }

        int baseColor = FastColor.ARGB32.color(alpha, 0xFFFFFF);
        base.render(matrixStack, builder, FULL_BRIGHT, combinedOverlay, baseColor);
        base2.render(matrixStack, builder, combinedLight, combinedOverlay, baseColor);

        // the coloured frame
        int frameColor = FastColor.ARGB32.color(alpha, DyeColor.byId(module.getColorChannel()).getTextureDiffuseColor());
        shape1.render(matrixStack, builder, combinedLight, combinedOverlay, frameColor);
        shape2.render(matrixStack, builder, combinedLight, combinedOverlay, frameColor);
        shape3.render(matrixStack, builder, combinedLight, combinedOverlay, frameColor);
        shape4.render(matrixStack, builder, combinedLight, combinedOverlay, frameColor);
    }

@Override
    public void renderExtras(PressureGaugeModule module, PoseStack matrixStack, MultiBufferSource buffer, float partialTicks, int combinedLight, int combinedOverlay) {
        if (module.isFake()) return;

        BlockPos pos = module.getTube().getBlockPos();
        if (ClientUtils.getClientPlayer().distanceToSqr(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5) > 256) return;

        matrixStack.pushPose();

        matrixStack.translate(0.5, 1.5, 0.5);
        matrixStack.scale(1f, -1f, -1f);
        RenderUtils.rotateMatrixForDirection(matrixStack, module.getDirection());
        PressureTubeBlockEntity te = module.getTube();
        matrixStack.translate(0, 1.01, 0.378);
        matrixStack.scale(GAUGE_SCALE, GAUGE_SCALE, GAUGE_SCALE);
        matrixStack.mulPose(Axis.YP.rotationDegrees(180));
        if (module.shouldShowGauge()) {
            PressureGaugeRenderer3D.drawPressureGauge(matrixStack, buffer, -1, te.getCriticalPressure(), te.getDangerPressure(),
                    0, te.getPressure(), 0, 0, 0xFF000000);
        } else {
            // plain text display of bar
            Component s = Component.literal(PneumaticCraftUtils.roundNumberTo(te.getPressure(), 1));
            RenderUtils.renderString3d(s, -font.width(s) / 2f, -10, 0x000000, matrixStack, buffer, false, false);
            RenderUtils.renderString3d(BAR, -font.width(BAR) / 2f, 0, 0x000000, matrixStack, buffer, false, false);
        }
        matrixStack.popPose();
    }

@Override
    protected void render(RedstoneModule module, PoseStack poseStack, VertexConsumer builder, float partialTicks, int combinedLight, int combinedOverlay, int alpha) {
        int baseColor = FastColor.ARGB32.color(alpha, 0xFFFFFF);
        tubeConnector1.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);
        tubeConnector2.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);
        tubeConnector3.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);
        tubeConnector4.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);
        tubeConnector5.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);
        tubeConnector6.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);
        faceplate.render(poseStack, builder, combinedLight, combinedOverlay, baseColor);

        if (module.isFake()) {
            redstoneConnector.render(poseStack, builder, combinedLight, combinedOverlay, 0xFFFFFFFF);
        } else {
            int rsLevel = module.getRedstoneDirection() == RedstoneModule.EnumRedstoneDirection.INPUT ? module.getInputLevel() : module.getRedstoneLevel();
            poseStack.pushPose();
            poseStack.translate(0, 0, 5.2 / 16);
            poseStack.scale(1, 1, 0.25f + 0.72f * Mth.lerp(partialTicks, module.lastExtension, module.extension));
            poseStack.translate(0, 0, -5.2 / 16);
            redstoneConnector.render(poseStack, builder, combinedLight, combinedOverlay, 0xFF300000 | (rsLevel * 13 << 16));
            poseStack.popPose();
        }

