			RenderSystem.setShader(GameRenderer::getPositionTexShader);
			Tesselator tessellator = Tesselator.getInstance();
			BufferBuilder buffer = tessellator.getBuilder();
			RenderSystem.setShaderColor(0.9F, 0.9F, 0.9F, 1.0F);

			for (float x = backgroundScale; x < width + backgroundScale; x += backgroundScale) {
				for (float y = backgroundScale; y < height + backgroundScale; y += backgroundScale) {
					RenderSystem.setShaderTexture(0, this.getBackgroundMaterials()[random.nextInt(this.getBackgroundMaterials().length)]);
					buffer.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX_COLOR);
					buffer.vertex(x - backgroundScale, y, 0)
						.uv(0, 1)
						.color(0.5f, 0.5f, 0.5f, 1f)
						.endVertex();
					buffer.vertex(x, y, 0)
						.uv(1, 1)
						.color(0.5f, 0.5f, 0.5f, 1f)
						.endVertex();
					buffer.vertex(x, y - backgroundScale, 0)
						.uv(1, 0)
						.color(0.5f, 0.5f, 0.5f, 1f)
						.endVertex();
					buffer.vertex(x - backgroundScale, y - backgroundScale, 0)
						.uv(0, 0)
						.color(0.5f, 0.5f, 0.5f, 1f)
						.endVertex();
					tessellator.end();
				}
			}
		}

public static void renderItemEntity(GuiGraphicsExtractor graphics, ItemStack stack, int x, int y, float bobOffset) {
		ItemEntity itemEntity = EntityCache.fetchItemEntity(stack);
		if (itemEntity == null)
			return;

		if (!(Minecraft.getInstance().getEntityRenderDispatcher().extractEntity(itemEntity, 0f) instanceof ItemEntityRenderState renderState))
			return;

		renderState.bobOffset = bobOffset;

		// TODO verify that the rotations and translations are correct, see below commented method
		Quaternionf rotation = Axis.ZP.rotationDegrees(180.0F);
		rotation.mul(Axis.XN.rotationDegrees(15.0F));
		float partialTicks = Minecraft.getInstance().getDeltaTracker().getGameTimeDeltaPartialTick(false);

		float spin = getSpin(partialTicks, bobOffset);
		rotation.mul(Axis.YP.rotation(spin - 145.0F));

		float yBob = Mth.sin((Objects.requireNonNull(Minecraft.getInstance().level).getGameTime() + partialTicks) / 10.0F + bobOffset) * 0.1F + 0.1F;
		ItemTransforms noTransforms = ItemTransforms.NO_TRANSFORMS; // ItemModel bakedmodel = Minecraft.getInstance().getModelManager().getItemModel(stack.get(DataComponents.ITEM_MODEL));
		float f2 = noTransforms.getTransform(ItemDisplayContext.GROUND).scale().y();

		Vector3f translation = new Vector3f(16, 32 + yBob + 0.25F * f2, 50);

		graphics.entity(renderState, 50, translation, rotation, null, x, y, x + 32, y + 32);
	}

private void extractPartRenderStates(ExtractLevelRenderStateEvent event) {
		ClientLevel level = event.getLevel();
		LevelRenderState renderState = event.getRenderState();
		DeltaTracker deltaTracker = event.getDeltaTracker();
		TickRateManager tickRateManager = level.tickRateManager();
		Frustum frustum = event.getFrustum();
		Vec3 cameraPos = event.getCamera().position();
		boolean showOutlines = event.getLevelRenderer().shouldShowEntityOutlines();
		List<PartRender> renders = new ArrayList<>();

		TFPart.forEachPart(level.entitiesForRendering(), part -> {
			EntityRenderer<Entity, EntityRenderState> renderer = BakedMultiPartRenderers.lookup(part.renderer());
			if (!renderer.shouldRender(part, frustum, cameraPos.x(), cameraPos.y(), cameraPos.z()))
				return;

			EntityRenderState state = renderer.createRenderState(part, deltaTracker.getGameTimeDeltaPartialTick(!tickRateManager.isEntityFrozen(part)));
			renders.add(new PartRender(renderer, state));
			if (showOutlines && state.appearsGlowing())
				renderState.haveGlowingEntities = true;
		});

		renderState.setRenderData(this.partRenders, renders);
	}

private void submitPartRenderStates(SubmitCustomGeometryEvent event) {
		LevelRenderState renderState = event.getLevelRenderState();
		@Nullable List<PartRender> renders = renderState.getRenderData(this.partRenders);
		if (renders == null || renders.isEmpty())
			return;

		CameraRenderState cameraRenderState = renderState.cameraRenderState;
		Vec3 cameraPos = cameraRenderState.pos;
		PoseStack stack = event.getPoseStack();

		for (PartRender render : renders) {
			EntityRenderState state = render.state();
			if (!renderState.haveGlowingEntities)
				state.outlineColor = 0;

			Vec3 offset = render.renderer().getRenderOffset(state);
			stack.pushPose();
			stack.translate(state.x - cameraPos.x() + offset.x(), state.y - cameraPos.y() + offset.y(), state.z - cameraPos.z() + offset.z());
			render.renderer().submit(state, stack, event.getSubmitNodeCollector(), cameraRenderState);
			stack.popPose();
		}
	}

private void renderAurora(RenderLevelStageEvent.AfterWeather event) {
		Minecraft mc = Minecraft.getInstance();
		if (mc.level == null)
			return;

		if (aurora > 0 || lastAurora > 0) {
			BufferBuilder buffer = Tesselator.getInstance().begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_COLOR);

			final float scale = 2048F * (mc.options.getEffectiveRenderDistance() * 16F / 32F);
			Vec3 pos = event.getLevelRenderState().cameraRenderState.pos;
			float y = (float) (256F - pos.y());
			buffer.addVertex(-scale, y, scale).setColor(1F, 1F, 1F, 1F);
			buffer.addVertex(-scale, y, -scale).setColor(1F, 1F, 1F, 1F);
			buffer.addVertex(scale, y, -scale).setColor(1F, 1F, 1F, 1F);
			buffer.addVertex(scale, y, scale).setColor(1F, 1F, 1F, 1F);

			float alpha = Mth.lerp(mc.getDeltaTracker().getGameTimeDeltaTicks(), lastAurora, aurora) / 60F * 0.5F;
			auroraRenderer.draw(
				buffer.buildOrThrow(),
				alpha,
				Mth.abs((int) mc.level.getBiomeManager().biomeZoomSeed),
				(float) pos.x(),
				(float) pos.y(),
				(float) pos.z()
			);
		}
	}

private void updateBowFOV(ComputeFovModifierEvent event) {
		Player player = event.getPlayer();
		if (player.isUsingItem()) {
			Item useItem = player.getUseItem().getItem();
			if (useItem instanceof TripleBowItem || useItem instanceof EnderBowItem || useItem instanceof IceBowItem || useItem instanceof SeekerBowItem) {
				float f = player.getTicksUsingItem() / 20.0F;
				f = f > 1.0F ? 1.0F : f * f;
				event.setNewFovModifier((float) Mth.lerp(Minecraft.getInstance().options.fovEffectScale().get(), 1.0F, (event.getFovModifier() * (1.0F - f * 0.15F))));
			}
		}
	}

private void renderGiantBlockOutlines(ExtractBlockOutlineRenderStateEvent event) {
		BlockPos pos = event.getBlockPos();
		BlockState state = event.getCamera().entity().level().getBlockState(pos);

		if (state.getBlock() instanceof MiniatureStructureBlock) {
			event.setCanceled(true);
			return;
		}

		event.addCustomRenderer((renderState, buffer, poseStack, translucentPass, levelRenderState) -> {
			LocalPlayer player = Minecraft.getInstance().player;
			if (player != null && (player.getMainHandItem().getItem() instanceof GiantPickItem || (player.getMainHandItem().getItem() instanceof BlockItem blockItem && blockItem.getBlock() instanceof GiantBlock))) {
				if (!state.isAir() && player.level().getWorldBorder().isWithinBounds(pos)) {
					BlockPos offsetPos = new BlockPos(pos.getX() & ~0b11, pos.getY() & ~0b11, pos.getZ() & ~0b11);
					VertexConsumer consumer = buffer.getBuffer(RenderTypes.lines());
					Vec3 xyz = Vec3.atLowerCornerOf(offsetPos).subtract(event.getCamera().position());
					int outlineColor = renderState.highContrast() ? 0xff_57_ff_e1 : 0x66_00_00_00;
					ShapeRenderer.renderShape(poseStack, consumer, GIANT_BLOCK, xyz.x(), xyz.y(), xyz.z(), outlineColor, Minecraft.getInstance().gameRenderer.getGameRenderState().windowRenderState.appropriateLineWidth);
				}
				return true;
			}
			return false;
		});
	}

private void attachRenderLayers(EntityRenderersEvent.AddLayers event) {
		BakedMultiPartRenderers.bakeMultiPartRenderers(event.getContext());
		for (EntityType<?> type : event.getEntityTypes()) {
			EntityRenderer<?, ?> renderer = event.getRenderer(type);
			if (renderer instanceof LivingEntityRenderer<?, ?, ?>) {
				@SuppressWarnings("unchecked") // Yuck
				var living = (LivingEntityRenderer<?, LivingEntityRenderState, EntityModel<LivingEntityRenderState>>) renderer;
				this.attachLivingRenderLayers(living);
			}
		}

		event.getSkins().forEach(renderer -> {
			AvatarRenderer<AbstractClientPlayer> skin = event.getPlayerRenderer(renderer);
			this.attachLivingRenderLayers(Objects.requireNonNull(skin));
		});
	}

protected static void renderPrecipitation(RenderLevelStageEvent.AfterWeather event) {
		if (TFConfig.getClientCloudBlockPrecipitationDistance() > 0 && !RENDER_HELPER.isEmpty()) {
			Minecraft minecraft = Minecraft.getInstance();
			if (minecraft.level == null) return;
			float partialTick = minecraft.getDeltaTracker().getGameTimeDeltaPartialTick(false);
			int ticks = minecraft.levelRenderer.getTicks();

			Vec3 vec3 = event.getLevelRenderState().cameraRenderState.pos;
			double camX = vec3.x();
			double camY = vec3.y();
			double camZ = vec3.z();

			int floorY = Mth.floor(camY);

			int renderDistance = minecraft.options.weatherRadius().get();

			float fullTick = (float) ticks + partialTick;
			BlockPos.MutableBlockPos mutableBlockPos = new BlockPos.MutableBlockPos();
			MultiBufferSource.BufferSource bufferSource = minecraft.renderBuffers().bufferSource();

			for (PrecipitationRenderHelper helper : RENDER_HELPER) {
				BlockPos pos = helper.cloudPos();
				int roofX = pos.getX();
				int roofZ = pos.getZ();

				int botY = Math.max(helper.rainOnY(), floorY - renderDistance);
				int topY = Math.min(pos.getY(), floorY + renderDistance);
				if (topY - botY <= 0) continue;

				double xDiff = (double) roofX + 0.5D - camX;
				double zDiff = (double) roofZ + 0.5D - camZ;
				double columnDistance = Math.sqrt(xDiff * xDiff + zDiff * zDiff);
				double rainX = columnDistance == 0.0D ? 0.0D : -zDiff / columnDistance * 0.5D;
				double rainZ = columnDistance == 0.0D ? 0.0D : xDiff / columnDistance * 0.5D;

				RandomSource random = RandomSource.create((long) roofX * roofX * 3121 + roofX * 45238971L ^ (long) roofZ * roofZ * 418711 + roofZ * 13761L);
				if (helper.precipitation() == Biome.Precipitation.RAIN) {
					RenderType renderType = RenderTypeUtil.weather(TFWeatherRenderer.RAIN_TEXTURES, Minecraft.useShaderTransparency());

					int offset = ticks + roofX * roofX * 3121 + roofX * 45238971 + roofZ * roofZ * 418711 + roofZ * 13761 & 31;
					float uvOffset = -((float) offset + partialTick) / 32.0F * (3.0F + random.nextFloat());
					float distance = (float) (columnDistance / (double) renderDistance);
					float alpha = ((1.0F - distance * distance) * 0.5F + 0.5F) * helper.precipitationLevel();
					mutableBlockPos.set(roofX, Math.max(helper.rainOnY(), floorY), roofZ);
					int lightCoords = LevelRenderer.getLightCoords(minecraft.level, mutableBlockPos);

					VertexConsumer vC = bufferSource.getBuffer(renderType);

					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX - rainX + 0.5D), (float) (topY - camY), (float) (roofZ - camZ - rainZ + 0.5D)).setUv(0.0F, (float) botY * 0.25F + uvOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setLight(lightCoords);
					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX + rainX + 0.5D), (float) (topY - camY), (float) (roofZ - camZ + rainZ + 0.5D)).setUv(1.0F, (float) botY * 0.25F + uvOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setLight(lightCoords);
					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX + rainX + 0.5D), (float) (botY - camY), (float) (roofZ - camZ + rainZ + 0.5D)).setUv(1.0F, (float) topY * 0.25F + uvOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setLight(lightCoords);
					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX - rainX + 0.5D), (float) (botY - camY), (float) (roofZ - camZ - rainZ + 0.5D)).setUv(0.0F, (float) topY * 0.25F + uvOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setLight(lightCoords);
				} else if (helper.precipitation() == Biome.Precipitation.SNOW) {
					RenderType renderType = RenderTypeUtil.weather(TFWeatherRenderer.SNOW_TEXTURES, Minecraft.useShaderTransparency());

					float offset = -((float) (ticks & 511) + partialTick) / 512.0F;
					float uOffset = (float) (random.nextDouble() + (double) fullTick * 0.01D * (double) ((float) random.nextGaussian()));
					float vOffset = (float) (random.nextDouble() + (double) (fullTick * (float) random.nextGaussian()) * 0.001D);
					float distance = (float) (columnDistance / (double) renderDistance);
					float alpha = ((1.0F - distance * distance) * 0.3F + 0.5F) * helper.precipitationLevel();
					mutableBlockPos.set(roofX, Math.max(helper.rainOnY(), floorY), roofZ);

					int lightCoords = LevelRenderer.getLightCoords(minecraft.level, mutableBlockPos);
					int u = lightCoords & '\uffff';
					int v = lightCoords >> 16 & '\uffff';
					u = (u * 3 + 240) / 4;
					v = (v * 3 + 240) / 4;

					VertexConsumer vC = bufferSource.getBuffer(renderType);

					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX - rainX + 0.5D), (float) (topY - camY), (float) (roofZ - camZ - rainZ + 0.5D)).setUv(0.0F + uOffset, (float) botY * 0.25F + offset + vOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setUv2(u, v);
					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX + rainX + 0.5D), (float) (topY - camY), (float) (roofZ - camZ + rainZ + 0.5D)).setUv(1.0F + uOffset, (float) botY * 0.25F + offset + vOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setUv2(u, v);
					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX + rainX + 0.5D), (float) (botY - camY), (float) (roofZ - camZ + rainZ + 0.5D)).setUv(1.0F + uOffset, (float) topY * 0.25F + offset + vOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setUv2(u, v);
					vC.addVertex(event.getPoseStack().last(), (float) (roofX - camX - rainX + 0.5D), (float) (botY - camY), (float) (roofZ - camZ - rainZ + 0.5D)).setUv(0.0F + uOffset, (float) topY * 0.25F + offset + vOffset).setColor(1.0F, 1.0F, 1.0F, alpha).setUv2(u, v);
				}
			}

			bufferSource.endBatch();
		}
	}

