private static void renderIndicator(Minecraft minecraft, GuiGraphicsExtractor graphics, Gui gui, Player player, int screenWidth, int screenHeight) {
		if (minecraft.options.getCameraType().isFirstPerson() && (minecraft.gameMode.getPlayerMode() != GameType.SPECTATOR || gui.canRenderCrosshairForSpectator(minecraft.hitResult)) && minecraft.crosshairPickEntity instanceof QuestRam ram) {
			ItemStack stack = player.getInventory().getItem(player.getInventory().getSelectedSlot());
			if (!stack.isEmpty()) {
				for (var questEntry : questingRamCurrentContext.getContext().questItems().entrySet()) {
					if (questEntry.getValue().test(stack)) {
						int j = ((screenHeight - 1) / 2) - 11;
						int k = ((screenWidth - 1) / 2) - 3;
						if (!ram.isColorPresent(questEntry.getKey())) {
							graphics.blitSprite(RenderPipelines.CROSSHAIR, QUESTING_RAM_X_SPRITE, k, j, 7, 7);
						} else {
							graphics.blitSprite(RenderPipelines.CROSSHAIR, QUESTING_RAM_CHECK_SPRITE, k, j, 7, 7);
						}
						break;
					}
				}
			}
		}
	}

private static void renderHolders(GuiGraphicsExtractor graphics, Minecraft minecraft, Gui gui, Player player, List<DisplayHolder> typesToRender, int widest) {
		graphics.pose().pushMatrix();
		graphics.pose().translate(TFConfig.itemDisplayXOffs, TFConfig.itemDisplayYOffs);
		graphics.pose().scale((float) TFConfig.itemDisplayScale, (float) TFConfig.itemDisplayScale);
		typesToRender.sort(Comparator.comparing(holder -> holder.display().displayPosition()));
		for (DisplayHolder holder : typesToRender) {
			graphics.pose().pushMatrix();
			holder.display().render(holder.stack(), graphics, minecraft, gui, player, widest);
			//debug fill to see widget sizes
			//graphics.fill(holder.bounds().startX(), holder.bounds().startY(), holder.bounds().startX() + holder.bounds().width(), holder.bounds().startY() + holder.bounds().height(), 0x80FF0000);
			graphics.pose().popMatrix();
			graphics.pose().translate(0.0F, holder.bounds().height());
		}
		graphics.pose().popMatrix();
	}

@Override
	public void extract(QuadParticleRenderState buffer, Camera entity, float partialTicks) {
		this.alpha = Math.min(Mth.clamp(this.age, 0, 20) / 20.0F, Mth.clamp(this.lifetime - this.age, 0, 20) / 20.0F);
		Quaternionf quaternion = new Quaternionf();
		if (this.roll != 0.0F) {
			quaternion.rotateZ(Mth.lerp(partialTicks, this.oRoll, this.roll));
		}
		quaternion.rotateY(Mth.cos((float) Math.toRadians(this.rot % 360.0F)));
		this.extractRotatedQuad(buffer, entity, quaternion, partialTicks);
		quaternion.rotateY(-Mth.PI).rotateZ(Mth.HALF_PI);
		this.extractRotatedQuad(buffer, entity, quaternion, partialTicks);
	}

public void draw(MeshData mesh, float alpha, int seed, float x, float y, float z) {
		GpuDevice device = RenderSystem.getDevice();
		GpuTextureView colorTexture = Minecraft.getInstance().getMainRenderTarget().getColorTextureView();
		GpuTextureView depthTexture = Minecraft.getInstance().getMainRenderTarget().getDepthTextureView();

		try (mesh) {
			if (colorTexture == null)
				return;

			MeshData.DrawState drawState = mesh.drawState();
			RenderSystem.AutoStorageIndexBuffer sequential = RenderSystem.getSequentialBuffer(drawState.mode());
			GpuBuffer indexBuffer = sequential.getBuffer(drawState.indexCount());
			GpuBufferSlice transforms = RenderSystem.getDynamicUniforms()
				.writeTransform(RenderSystem.getModelViewMatrix(), new Vector4f(1.0F, 1.0F, 1.0F, alpha), new Vector3f(), new Matrix4f());
			GpuBufferSlice aurora = this.uniformStorage.get().writeUniform(new AuroraUniform(seed, x, y, z));

			try (
				GpuBuffer vertexBuffer = device.createBuffer(
					() -> "Twilight Forest aurora vertices",
					GpuBuffer.USAGE_VERTEX,
					mesh.vertexBuffer()
				);
				RenderPass pass = device.createCommandEncoder().createRenderPass(
					() -> "Aurora",
					colorTexture,
					OptionalInt.empty(),
					depthTexture,
					OptionalDouble.empty()
				)
			) {
				pass.setPipeline(TFRenderPipelines.AURORA);
				RenderSystem.bindDefaultUniforms(pass);
				pass.setUniform("DynamicTransforms", transforms);
				pass.setUniform(TFRenderPipelines.AURORA_UNIFORM, aurora);
				pass.setVertexBuffer(0, vertexBuffer);
				pass.setIndexBuffer(indexBuffer, sequential.type());
				pass.drawIndexed(0, 0, drawState.indexCount(), 1);
			}
		}
	}

