private void renderStars(PoseStack stack) {
		Matrix4fStack matrix = RenderSystem.getModelViewStack();
		matrix.pushMatrix();
		matrix.mul(stack.last().pose());
		RenderPipeline renderPipeline = RenderPipelines.STARS;
		GpuTextureView colorTexture = Minecraft.getInstance().getMainRenderTarget().getColorTextureView();
		GpuTextureView depthTexture = Minecraft.getInstance().getMainRenderTarget().getDepthTextureView();
		GpuBuffer indices = this.starIndices.getBuffer(this.starIndexCount);
		GpuBufferSlice dynamicTransforms = RenderSystem.getDynamicUniforms()
			.writeTransform(matrix, new Vector4f(1.0F, 1.0F, 1.0F, 1.0F), new Vector3f(), new Matrix4f());
		try (RenderPass renderPass = RenderSystem.getDevice()
				.createCommandEncoder()
				.createRenderPass(() -> "Stars", colorTexture, OptionalInt.empty(), depthTexture, OptionalDouble.empty())) {
			renderPass.setPipeline(renderPipeline);
			RenderSystem.bindDefaultUniforms(renderPass);
			renderPass.setUniform("DynamicTransforms", dynamicTransforms);
			renderPass.setVertexBuffer(0, this.starBuffer);
			renderPass.setIndexBuffer(indices, this.starIndices.type());
			renderPass.drawIndexed(0, 0, this.starIndexCount, 1);
		}

		matrix.popMatrix();
	}

private GpuBuffer buildStars() {
		RandomSource random = RandomSource.create(10842L);
		GpuBuffer gpuBuffer;

		try (ByteBufferBuilder byteBufferBuilder = ByteBufferBuilder.exactlySized(DefaultVertexFormat.POSITION.getVertexSize() * 3000 * 4)) {
			BufferBuilder bufferBuilder = new BufferBuilder(byteBufferBuilder, VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION);

			// TF - 1500 -> 3000
			for (int i = 0; i < 3000; ++i) {
				float f1 = random.nextFloat() * 2.0F - 1.0F;
				float f2 = random.nextFloat() * 2.0F - 1.0F;
				float f3 = random.nextFloat() * 2.0F - 1.0F;
				float f4 = 0.15F + random.nextFloat() * 0.1F;
				float f5 = Mth.lengthSquared(f1, f2, f3);
				if (!(f5 <= 0.010000001F) && !(f5 >= 1.0F)) {
					Vector3f vector3f = new Vector3f(f1, f2, f3).normalize(100.0F);
					float f6 = (float)(random.nextDouble() * (float) Math.PI * 2.0);
					Matrix3f matrix3f = new Matrix3f().rotateTowards(new Vector3f(vector3f).negate(), new Vector3f(0.0F, 1.0F, 0.0F)).rotateZ(-f6);
					bufferBuilder.addVertex(new Vector3f(f4, -f4, 0.0F).mul(matrix3f).add(vector3f));
					bufferBuilder.addVertex(new Vector3f(f4, f4, 0.0F).mul(matrix3f).add(vector3f));
					bufferBuilder.addVertex(new Vector3f(-f4, f4, 0.0F).mul(matrix3f).add(vector3f));
					bufferBuilder.addVertex(new Vector3f(-f4, -f4, 0.0F).mul(matrix3f).add(vector3f));
				}
			}

			try (MeshData mesh = bufferBuilder.buildOrThrow()) {
				this.starIndexCount = mesh.drawState().indexCount();
				gpuBuffer = RenderSystem.getDevice().createBuffer(() -> "TF Stars buffer", 40, mesh.vertexBuffer());
			}
		}

		return gpuBuffer;
	}

private static void renderLockedBiome(int ticks, float partialTicks, ClientLevel level, LocalPlayer player, Vec3 camera, MultiBufferSource buffer) {
		// check nearby for locked biome
		if (isNearLockedBiome(level, player)) {
			int px = Mth.floor(camera.x());
			int py = Mth.floor(camera.y());
			int pz = Mth.floor(camera.z());

			int range = Minecraft.getInstance().options.weatherRadius().get();

			WeatherRenderType currentType = null;
			float combinedTicks = ticks + partialTicks;
			BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();

			for (int dz = pz - range; dz <= pz + range; ++dz) {
				for (int dx = px - range; dx <= px + range; ++dx) {
					int rainIndex = (dz - pz + 16) * 32 + dx - px + 16;
					double rainX = rainxs[rainIndex] * 0.5D;
					double rainZ = rainzs[rainIndex] * 0.5D;

					pos.set(dx, 0, dz);
					Biome biome = level.getBiome(pos).value();

					Optional<Restriction> restriction = Restriction.getRestrictionForBiome(biome, player);
					if (restriction.isPresent()) {
						int groundY = level.getMinY();
						int minY = py - range;
						int maxY = py + range;

						if (minY < groundY) {
							minY = groundY;
						}

						if (maxY < groundY) {
							maxY = groundY;
						}


						if (minY != maxY) {

							random.setSeed((long) dx * dx * 3121 + dx * 45238971L ^ (long) dz * dz * 418711 + dz * 13761L);

							WeatherRenderType nextType = getRenderType(restriction.get());
							if (nextType == null)
								continue;
							currentType = nextType;

							double xRange = (double) ((float) dx + 0.5F) - camera.x();
							double zRange = (double) ((float) dz + 0.5F) - camera.z();
							float distanceToPlayer = Mth.sqrt((float) (xRange * xRange + zRange * zRange)) / (float) range;
							float alpha = ((1.0F - distanceToPlayer * distanceToPlayer) * 0.3F + 0.5F);
							int fullbright = 15 << 20 | 15 << 4;

							switch (currentType) {
								case BLIZZARD -> {
									float countFactor = ((float) (ticks & 511) + partialTicks) / 512.0F;
									float uFactor = random.nextFloat() + combinedTicks * 0.05F * (float) random.nextGaussian();
									float vFactor = random.nextFloat() + combinedTicks * 0.0025F * (float) random.nextGaussian();
									renderEffect(currentType.getTextureLocation(), rainX, rainZ, minY, maxY, camera, dx, dz, countFactor, uFactor, vFactor, new float[]{1.0F, 1.0F, 1.0F, alpha}, fullbright, buffer);
								}
								case MOSQUITO -> {
									float countFactor = 0;
									float uFactor = random.nextFloat() + combinedTicks * 0.03F * (float) random.nextGaussian();
									float vFactor = random.nextFloat() + combinedTicks * 0.003F * (float) random.nextGaussian();
									float red = random.nextFloat() * 0.3F;
									float green = random.nextFloat() * 0.3F;
									float blue = random.nextFloat() * 0.3F;
									renderEffect(currentType.getTextureLocation(), rainX, rainZ, minY, maxY, camera, dx, dz, countFactor, uFactor, vFactor, new float[]{red, green, blue, 1.0F}, fullbright, buffer);
								}
								case ASHES -> {
									float countFactor = -((float) (ticks & 1023) + partialTicks) / 1024.0F;
									float uFactor = random.nextFloat() + combinedTicks * 0.0025F * (float) random.nextGaussian();
									float vFactor = random.nextFloat() + combinedTicks * 0.005F * (float) random.nextGaussian();
									float color = random.nextFloat() * 0.2F + 0.8F;
									renderEffect(currentType.getTextureLocation(), rainX, rainZ, minY, maxY, camera, dx, dz, countFactor, uFactor, vFactor, new float[]{color, color, color, alpha}, fullbright, buffer);
								}
								case DARK_STREAM -> {
									float countFactor = -((ticks & 511) + partialTicks) / 512.0F;
									float uFactor = 0; //no moving horizontally
									float vFactor = random.nextFloat() + combinedTicks * 0.005F * (float) random.nextGaussian();
									renderEffect(currentType.getTextureLocation(), rainX, rainZ, minY, maxY, camera, dx, dz, countFactor, uFactor, vFactor, new float[]{1.0F, 1.0F, 1.0F, alpha}, fullbright, buffer);
								}
								case BIG_RAIN -> {
									float countFactor = ((float) (ticks + dx * dx * 3121 + dx * 45238971 + dz * dz * 418711 + dz * 13761 & 31) + partialTicks) / 32.0F * (3.0F + random.nextFloat());
									float uFactor = random.nextFloat();
									float vFactor = random.nextFloat();
									int terrainHeight = level.getHeight(Heightmap.Types.MOTION_BLOCKING, dx, dz);
									int worldBrightness = LevelRenderer.getLightCoords(level, pos.set(dx, Math.max(py, terrainHeight), dz));
									renderEffect(currentType.getTextureLocation(), rainX, rainZ, minY, maxY, camera, dx, dz, countFactor, uFactor, vFactor, new float[]{1.0F, 1.0F, 1.0F, alpha}, worldBrightness, buffer);
								}
							}
						}
					}
				}
			}
		}
	}

private static void renderEffect(Identifier type, double rainX, double rainZ, int minY, int maxY, Vec3 camera, int dx, int dz, float countFactor, float uFactor, float vFactor, float[] color, int light, MultiBufferSource bufferSource) {
		VertexConsumer consumer = bufferSource.getBuffer(RenderTypeUtil.weather(type, Minecraft.useShaderTransparency()));
		consumer
			.addVertex((float) (dx - camera.x() - rainX + 0.5F), (float) (minY - camera.y()), (float) (dz - camera.z() - rainZ + 0.5F))
			.setUv(0.0F + uFactor, minY * 0.25F + countFactor + vFactor)
			.setColor(color[0], color[1], color[2], color[3])
			.setLight(light);
		consumer
			.addVertex((float) (dx - camera.x() + rainX + 0.5F), (float) (minY - camera.y()), (float) (dz - camera.z() + rainZ + 0.5F))
			.setUv(1.0F + uFactor, minY * 0.25F + countFactor + vFactor)
			.setColor(color[0], color[1], color[2], color[3])
			.setLight(light);
		consumer
			.addVertex((float) (dx - camera.x() + rainX + 0.5F), (float) (maxY - camera.y()), (float) (dz - camera.z() + rainZ + 0.5F))
			.setUv(1.0F + uFactor, maxY * 0.25F + countFactor + vFactor)
			.setColor(color[0], color[1], color[2], color[3])
			.setLight(light);
		consumer
			.addVertex((float) (dx - camera.x() - rainX + 0.5F), (float) (maxY - camera.y()), (float) (dz - camera.z() - rainZ + 0.5F))
			.setUv(0.0F + uFactor, maxY * 0.25F + countFactor + vFactor)
			.setColor(color[0], color[1], color[2], color[3])
			.setLight(light);
	}

public static void extractUrGhastRain(ExtractLevelRenderStateEvent event) {
		if (!(event.getRenderState().customWeatherEffectRenderer instanceof TwilightForestRenderInfo))
			return;

		WeatherRenderState renderState = event.getRenderState().weatherRenderState;
		if (urGhastRain <= renderState.intensity)
			return;

		ClientLevel level = event.getLevel();
		int ticks = event.getRenderTick();
		float partialTicks = event.getDeltaTracker().getGameTimeDeltaPartialTick(false);
		Vec3 cameraPos = event.getCamera().position();

		renderState.intensity = urGhastRain;
		renderState.radius = Minecraft.getInstance().options.weatherRadius().get();
		int cameraBlockX = Mth.floor(cameraPos.x);
		int cameraBlockY = Mth.floor(cameraPos.y);
		int cameraBlockZ = Mth.floor(cameraPos.z);
		BlockPos.MutableBlockPos mutablePos = new BlockPos.MutableBlockPos();
		RandomSource columnRandom = RandomSource.createThreadLocalInstance();

		for (int z = cameraBlockZ - renderState.radius; z <= cameraBlockZ + renderState.radius; z++) {
			for (int x = cameraBlockX - renderState.radius; x <= cameraBlockX + renderState.radius; x++) {
				int terrainHeight = level.getHeight(Heightmap.Types.MOTION_BLOCKING, x, z);
				int y0 = Math.max(cameraBlockY - renderState.radius, terrainHeight);
				int y1 = Math.max(cameraBlockY + renderState.radius, terrainHeight);
				if (y1 - y0 != 0 && getPrecipitationAt(level, mutablePos.set(x, cameraBlockY, z)) == Biome.Precipitation.RAIN) {
					columnRandom.setSeed(x * x * 3121L + x * 45238971L ^ z * z * 418711L + z * 13761L);
					int lightCoords = LevelRenderer.getLightCoords(level, mutablePos.set(x, Math.max(cameraBlockY, terrainHeight), z));
					int wrappedTicks = ticks & 131071;
					int tickOffset = x * x * 3121 + x * 45238971 + z * z * 418711 + z * 13761 & 0xFF;
					float blockPosRainSpeed = 3.0F + columnRandom.nextFloat();
					float textureOffset = -(wrappedTicks + tickOffset + partialTicks) / 32.0F * blockPosRainSpeed;
					renderState.rainColumns.add(new WeatherEffectRenderer.ColumnInstance(x, z, y0, y1, 0.0F, textureOffset % 32.0F, lightCoords));
				}
			}
		}
	}

