		World world = Minecraft.getMinecraft().world;

		ItemStack stack = player.getHeldItemMainhand();

		if (stack.getItem() != ModItems.FAIRY_BELL) return;

		if (Minecraft.getMinecraft().objectMouseOver.typeOfHit == RayTraceResult.Type.ENTITY) {
			Entity entityHit = Minecraft.getMinecraft().objectMouseOver.entityHit;
			if (entityHit instanceof EntityFairy) {
				EntityFairy fairy = (EntityFairy) entityHit;
				FairyData data = fairy.getDataFairy();

				if (data != null && data.isDepressed) {
					double interpPosX = player.lastTickPosX + (player.posX - player.lastTickPosX) * event.getPartialTicks();
					double interpPosY = player.lastTickPosY + (player.posY - player.lastTickPosY) * event.getPartialTicks();
					double interpPosZ = player.lastTickPosZ + (player.posZ - player.lastTickPosZ) * event.getPartialTicks();

					IMiscCapability cap = MiscCapabilityProvider.getCap(Minecraft.getMinecraft().player);
					if (cap == null) return;

					UUID uuid = cap.getSelectedFairyUUID();
					if (uuid != null && uuid.equals(fairy.getUniqueID())) {
						GlStateManager.pushMatrix();
						GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

						RenderUtils.drawCircle(fairy.getPositionVector().add(0, fairy.height, 0), 0.3, true, false, Color.RED);
						GlStateManager.popMatrix();
					} else {
						GlStateManager.pushMatrix();
						GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

						RenderUtils.drawCircle(fairy.getPositionVector().add(0, fairy.height, 0), (Math.sin(ClientTickHandler.getTicks() / 5.0f) + 2.5) / 10.0, true, false);
						GlStateManager.popMatrix();
					}
				}
			}
		}

		for (EntityFairy entityFairy : world.getEntities(EntityFairy.class, input -> {
			if (input == null) return false;
			FairyData dataFairy = input.getDataFairy();
			if (dataFairy == null) return false;
			return dataFairy.isDepressed;
		})) {

			FairyData dataFairy = entityFairy.getDataFairy();
			if (dataFairy == null) return;

			IMiscCapability cap = MiscCapabilityProvider.getCap(Minecraft.getMinecraft().player);
			if (cap == null) return;

			double interpPosX = player.lastTickPosX + (player.posX - player.lastTickPosX) * event.getPartialTicks();
			double interpPosY = player.lastTickPosY + (player.posY - player.lastTickPosY) * event.getPartialTicks();
			double interpPosZ = player.lastTickPosZ + (player.posZ - player.lastTickPosZ) * event.getPartialTicks();

			Tessellator tess = Tessellator.getInstance();
			BufferBuilder bb = tess.getBuffer();

			GlStateManager.glLineWidth(2f);

			GlStateManager.pushMatrix();
			GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

			RenderUtils.drawCircle(entityFairy.getPositionVector().add(0, entityFairy.height, 0), 0.25, true, false, Color.YELLOW);
			GlStateManager.popMatrix();

			Vec3d lookTarget = entityFairy.getLookTarget();
			Vec3d fairyPos = entityFairy.getPositionVector().add(0, entityFairy.height, 0);

			if (lookTarget != null) {
				Vec3d to = fairyPos.add(lookTarget);

				GlStateManager.pushMatrix();
				GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

				RenderUtils.drawCircle(to, 0.1, true, false, Color.ORANGE);

				GlStateManager.popMatrix();


				GlStateManager.pushMatrix();
				GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

				GlStateManager.disableLighting();
				GlStateManager.disableCull();
				GlStateManager.enableAlpha();
				GlStateManager.enableBlend();
				GlStateManager.shadeModel(GL11.GL_SMOOTH);
				GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);
				GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
				GlStateManager.color(1, 1, 1, 1);
				GlStateManager.disableTexture2D();
				GlStateManager.enableColorMaterial();
				GlStateManager.enableDepth();

				bb.begin(GL11.GL_LINES, DefaultVertexFormats.POSITION_COLOR);

				Color c = Color.ORANGE;

				bb.pos(to.x, to.y, to.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();
				bb.pos(fairyPos.x, fairyPos.y, fairyPos.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();

				tess.draw();

				GlStateManager.enableTexture2D();
				GlStateManager.popMatrix();
			}

			UUID uuid = cap.getSelectedFairyUUID();
			if (uuid != null && uuid.equals(entityFairy.getUniqueID())) {

				boolean movingMode = NBTHelper.getBoolean(stack, "moving_mode", true);

				if (!movingMode) {

					Vec3d hitVec = Minecraft.getMinecraft().objectMouseOver.hitVec;
					Vec3d subtract = hitVec.subtract(fairyPos);
					double length = subtract.length();
					hitVec = entityFairy.getPositionVector().add(0, entityFairy.height, 0).add(subtract.normalize().scale(MathHelper.clamp(length, -3, 3)));

					GlStateManager.pushMatrix();
					GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

					RenderUtils.drawCircle(hitVec, 0.2, true, false, Color.CYAN);
					GlStateManager.popMatrix();

					GlStateManager.pushMatrix();
					GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

					GlStateManager.disableLighting();
					GlStateManager.disableCull();
					GlStateManager.enableAlpha();
					GlStateManager.enableBlend();
					GlStateManager.shadeModel(GL11.GL_SMOOTH);
					GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);
					GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
					GlStateManager.color(1, 1, 1, 1);
					GlStateManager.disableTexture2D();
					GlStateManager.enableColorMaterial();
					GlStateManager.enableDepth();

					bb.begin(GL11.GL_LINES, DefaultVertexFormats.POSITION_COLOR);

					Color c = Color.GREEN;

					bb.pos(hitVec.x, hitVec.y, hitVec.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();
					bb.pos(fairyPos.x, fairyPos.y, fairyPos.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();

					tess.draw();

					GlStateManager.enableTexture2D();
					GlStateManager.popMatrix();

				} else {
					if (Minecraft.getMinecraft().objectMouseOver.typeOfHit == RayTraceResult.Type.BLOCK) {

						BlockPos target = Minecraft.getMinecraft().objectMouseOver.getBlockPos();

						GlStateManager.pushMatrix();
						GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

						RenderUtils.drawCubeOutline(entityFairy.world, target, entityFairy.world.getBlockState(target), Color.CYAN);
						GlStateManager.popMatrix();


						Vec3d tar = new Vec3d(target).add(0.5, 0.5, 0.5).add(new Vec3d(Minecraft.getMinecraft().objectMouseOver.sideHit.getDirectionVec()));
						PathNavigate navigateFlying = entityFairy.getNavigator();
						Path path = navigateFlying.getPathToXYZ(tar.x, tar.y, tar.z);


						GlStateManager.pushMatrix();
						GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

						RenderUtils.drawCircle(tar, 0.25, true, false, Color.CYAN);
						GlStateManager.popMatrix();

						if (path != null) {
							GlStateManager.pushMatrix();
							GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);

							GlStateManager.disableLighting();
							GlStateManager.disableCull();
							GlStateManager.enableAlpha();
							GlStateManager.enableBlend();
							GlStateManager.shadeModel(GL11.GL_SMOOTH);
							GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);
							GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
							GlStateManager.color(1, 1, 1, 1);
							GlStateManager.disableTexture2D();
							GlStateManager.enableColorMaterial();
							GlStateManager.disableDepth();

							bb.begin(GL11.GL_LINE_STRIP, DefaultVertexFormats.POSITION_COLOR);

							Color c = Color.GREEN;

							Vec3d lastPoint = null;
							Vec3d center = new Vec3d(entityFairy.posX, entityFairy.posY + entityFairy.height / 2.0, entityFairy.posZ);
							bb.pos(center.x, center.y, center.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();

							for (int i = 0; i < path.getCurrentPathLength(); i++) {

								Vec3d vec = path.getVectorFromIndex(entityFairy, i);

								if (lastPoint != null) {
									if (i >= path.getCurrentPathLength() - 1) {
										continue;
									}

									Vec3d from = path.getVectorFromIndex(entityFairy, i - 1);
									from = from.subtract(from.subtract(vec).scale(0.5));

									Vec3d to = path.getVectorFromIndex(entityFairy, i + 1);
									to = to.subtract(to.subtract(vec).scale(0.5));

									Vec3d fromControl = vec.subtract(from).normalize().scale(0.4);
									Vec3d toControl = vec.subtract(to).normalize().scale(0.4);

									InterpBezier3D bezier = new InterpBezier3D(from, to, fromControl, toControl);

									for (Vec3d dot : bezier.list(20)) {
										bb.pos(dot.x, dot.y, dot.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();
										lastPoint = dot;
									}
								} else {
									bb.pos(vec.x, vec.y, vec.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();
									lastPoint = vec;
								}
							}

							bb.pos(tar.x, tar.y, tar.z).color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha()).endVertex();

							tess.draw();

							GlStateManager.enableTexture2D();
							GlStateManager.popMatrix();
						}
					}
				}
			}
		}

	}

@SubscribeEvent
	public static void renderHud(Post event) {
		ScaledResolution resolution = event.getResolution();
		int width = resolution.getScaledWidth();
		int height = resolution.getScaledHeight();
		EntityPlayer player = Minecraft.getMinecraft().player;

		ItemStack stack = BaublesSupport.getItem(player, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO);
		if (stack.isEmpty()) return;

		if (event.getType() == ElementType.EXPERIENCE) {

			int barSide = Minecraft.getMinecraft().gameSettings.mainHand == EnumHandSide.RIGHT ? 1 : -1;
			barSide *= Minecraft.getMinecraft().gameSettings.attackIndicator == 2 ? -1 : 1;

			int right = ((width / 2) - (100 / 2)) + 155 * barSide;
			int top = height - 17;

			HUD_TEXTURE.bind();

			GlStateManager.pushMatrix();
			GlStateManager.color(1.0F, 1.0F, 1.0F);
			emptyManaBar.draw(ClientTickHandler.getTicks(), right, top);
			emptyBurnoutBar.draw(ClientTickHandler.getTicks(), right, top + 6);
			GlStateManager.popMatrix();

			try (ManaManager.CapManagerBuilder mgr = ManaManager.forObject(player)) {
				double mana = mgr.getMana();
				double burnout = mgr.getBurnout();
				double maxMana = mgr.getMaxMana();
				double maxBurnout = mgr.getMaxBurnout();

				GlStateManager.pushMatrix();
				GlStateManager.color(1.0F, 1.0F, 1.0F);
				int visualManaLength = 0;
				if (mana > 0)
					visualManaLength = (int) (((mana * 100) / maxMana) % 101);
				fullManaBar.draw(ClientTickHandler.getTicks(), right, top, visualManaLength, 5);

				GlStateManager.color(1.0F, 1.0F, 1.0F);

				int visualBurnoutLength = 0;
				if (burnout > 0)
					visualBurnoutLength = (int) (((burnout * 100) / maxBurnout) % 101);
				fullBurnoutBar.draw(ClientTickHandler.getTicks(), right, top + 6, visualBurnoutLength, 5);

				GlStateManager.popMatrix();
			}
		}
	}

@SubscribeEvent
	public static void tickDisplay(CustomWorldRenderEvent event) {
		if (Minecraft.getMinecraft() == null) return;
		if (Minecraft.getMinecraft().player == null) return;
		if (Minecraft.getMinecraft().world == null) return;
		if (Minecraft.getMinecraft().getRenderManager() == null) return;
		if (Minecraft.getMinecraft().getRenderManager().options == null) return;

		EntityPlayer player = Minecraft.getMinecraft().player;
		World world = Minecraft.getMinecraft().world;

		if (player.isInvisible() || VanishTracker.isVanished(player)) return;

		ItemStack hand = player.getHeldItemMainhand();
		if (!(hand.getItem() instanceof ISpellCaster)) return;
		if (hand.getItem() instanceof ICooldownSpellCaster && ((ICooldownSpellCaster) hand.getItem()).isCoolingDown(world, hand))
			return;

		if (player.isSneaking()) {
			for (SpellRing spellRing : SpellUtils.getAllSpellRings(hand)) {
				if ((spellRing.getModule() != null ? spellRing.getModule().getModuleClass() : null) instanceof IBlockSelectable) {
					RayTraceResult result = Minecraft.getMinecraft().objectMouseOver;


					if (result.typeOfHit == RayTraceResult.Type.BLOCK) {
						BlockPos posHit = result.getBlockPos();
						if (player.world.isAirBlock(posHit)) return;

						RenderUtils.drawCubeOutline(event.getWorld(), posHit, event.getWorld().getBlockState(posHit));
						return;
					}
				}
			}
		}

		List<SpellRing> chains = SpellUtils.getSpellChains(hand);

		for (SpellRing chain : chains) {

			SpellData data = new SpellData();
			data.processEntity(player, true);

			SpellRing ring = chain;
			while (ring != null && ring.getModule() != null) {

				ring.getModule().renderVisualization(world, data, ring, event.getPartialTicks());

				ring = ring.getChildRing();
			}
		}
	}

@SubscribeEvent
	@SideOnly(Side.CLIENT)
	public static void render(RenderWorldLastEvent event) {
		if (Minecraft.getMinecraft().player == null) return;
		if (Minecraft.getMinecraft().getRenderManager().options == null) return;

		for (ParticleError error : errors) {

			EntityPlayer player = Minecraft.getMinecraft().player;

			double interpPosX = player.lastTickPosX + (player.posX - player.lastTickPosX) * event.getPartialTicks();
			double interpPosY = player.lastTickPosY + (player.posY - player.lastTickPosY) * event.getPartialTicks();
			double interpPosZ = player.lastTickPosZ + (player.posZ - player.lastTickPosZ) * event.getPartialTicks();


			GlStateManager.pushMatrix();
			GlStateManager.translate(-interpPosX, -interpPosY, -interpPosZ);
			GlStateManager.translate(error.pos.getX() + 0.5, error.pos.getY() + 0.5, error.pos.getZ() + 0.5);

			GlStateManager.rotate(-Minecraft.getMinecraft().getRenderManager().playerViewY, 0.0F, 1.0F, 0.0F);
			GlStateManager.rotate((float) (Minecraft.getMinecraft().getRenderManager().options.thirdPersonView == 2 ? -1 : 1) * Minecraft.getMinecraft().getRenderManager().playerViewX, 1.0F, 0.0F, 0.0F);
			GlStateManager.rotate(180.0F, 0.0F, 1.0F, 0.0F);
			GlStateManager.translate(-0.25, -0.25, -0.25);

			GlStateManager.disableDepth();

			GlStateManager.disableCull();
			GlStateManager.enableBlend();
			GlStateManager.enableTexture2D();
			GlStateManager.enableColorMaterial();

			int alphaFunc = GL11.glGetInteger(GL11.GL_ALPHA_TEST_FUNC);
			float alphaRef = GL11.glGetFloat(GL11.GL_ALPHA_TEST_REF);
			int blendSrc = GL11.glGetInteger(GL_BLEND_SRC);
			int blendDst = GL11.glGetInteger(GL_BLEND_DST);

			//	GlStateManager.shadeModel(GL11.GL_SMOOTH);
			GlStateManager.alphaFunc(GL11.GL_ALWAYS, 1);
			GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);

			GlStateManager.color(1f, 0, 0, MathHelper.sin((float) ((1f - ((float) error.tick / (float) error.maxTick)) * Math.PI * 2.0f)));
			particle.getTex().bind();
			particle.draw((int) event.getPartialTicks(), 0, 0, 0.5f, 0.5f);

			GlStateManager.blendFunc(blendSrc, blendDst);
			GlStateManager.alphaFunc(alphaFunc, alphaRef);
			GlStateManager.enableDepth();
			GlStateManager.color(1f, 1f, 1f, 1f);

			GlStateManager.popMatrix();
		}
	}

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void tick(TickEvent.ClientTickEvent event) {
		if (event.phase != TickEvent.Phase.END) return;
		World world = Minecraft.getMinecraft().world;
		if (world == null) return;

		List<EntityUnicorn> unicorns = world.getEntities(EntityUnicorn.class, input -> true);

		for (EntityUnicorn unicorn : unicorns) {
			if (unicorn == null) continue;
			if (unicorn.isDead) {
				positions.remove(unicorn);
				break;
			}

			positions.putIfAbsent(unicorn, new ArrayList<>());

			List<Point> poses = positions.get(unicorn);

			if ((poses.size() >= 1000 || world.getTotalWorldTime() % 20 == 0) && !poses.isEmpty()) {
				poses.remove(0);
			}

			double mot = 0.05;
			if (poses.size() < 1000) {
				if (unicorn.motionX >= mot || unicorn.motionX <= -mot
						|| unicorn.motionY >= mot || unicorn.motionY <= -mot
						|| unicorn.motionZ >= mot || unicorn.motionZ <= -mot) {

					Vec3d backCenter = unicorn.getPositionVector();
					Vec3d look = new Vec3d(unicorn.motionX, unicorn.motionY, unicorn.motionZ).normalize();
					backCenter = backCenter.add(look.scale(-1));

					Vec3d cross = look.crossProduct(new Vec3d(0, 1, 0)).normalize().scale(0.35f);
					poses.add(new Point(backCenter, cross, world.getTotalWorldTime()));
				} else if (!poses.isEmpty()) {
					poses.remove(0);
				}
			}
		}
	}

@SubscribeEvent
	@SideOnly(Side.CLIENT)
	public static void render(RenderWorldLastEvent event) {
		World world = Minecraft.getMinecraft().world;
		EntityPlayer player = Minecraft.getMinecraft().player;
		if (player == null || world == null) return;

		GlStateManager.pushMatrix();

		double interpPosX = player.lastTickPosX + (player.posX - player.lastTickPosX) * event.getPartialTicks();
		double interpPosY = player.lastTickPosY + (player.posY - player.lastTickPosY) * event.getPartialTicks();
		double interpPosZ = player.lastTickPosZ + (player.posZ - player.lastTickPosZ) * event.getPartialTicks();

		GlStateManager.translate(-interpPosX, -interpPosY + 0.1, -interpPosZ);

		GlStateManager.disableCull();
		GlStateManager.depthMask(false);
		GlStateManager.enableBlend();
		GlStateManager.disableTexture2D();
		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);
		GlStateManager.enableColorMaterial();
		GlStateManager.disableLighting();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vb = tessellator.getBuffer();

		Set<EntityUnicorn> corns = new HashSet<>(positions.keySet());
		for (EntityUnicorn corn : corns) {
			if (corn.world.provider.getDimension() != world.provider.getDimension()) continue;

			List<Point> points = new ArrayList<>(positions.getOrDefault(corn, new ArrayList<>()));
			boolean q = false;

			vb.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
			for (Point pos : points) {
				if (pos == null) continue;

				float sub = (world.getTotalWorldTime() - pos.time);
				Color color = Color.getHSBColor(sub % 360.0f / 360.0f, 1f, 1f);

				int alpha;
				if (sub < 500) {
					alpha = (int) (MathHelper.clamp(Math.log(sub + 1) / 2.0, 0, 1) * 80.0);
				} else {
					alpha = (int) (MathHelper.clamp(1 - (Math.log(sub) / 2.0), 0, 1) * 80.0);
				}

				pos(vb, pos.origin.subtract(pos.normal.scale(1.5))).color(color.getRed(), color.getGreen(), color.getBlue(), alpha).endVertex();
				pos(vb, pos.origin.add(pos.normal.scale(1.5))).color(color.getRed(), color.getGreen(), color.getBlue(), alpha).endVertex();
				q = !q;
			}

			tessellator.draw();
		}

		GlStateManager.enableCull();
		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.enableTexture2D();
		GlStateManager.shadeModel(GL11.GL_FLAT);
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);

		GlStateManager.popMatrix();
	}

private void render(EntityPlayer player, double x, double y, double z, float delta) {
			Tessellator tes = Tessellator.getInstance();
			BufferBuilder buf = tes.getBuffer();
			buf.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_NORMAL);
			buf.setTranslation(x, y, z);
			for (Quad quad : quads) {
				Quad.Vertex v00 = quad.getV00();
				Quad.Vertex v01 = quad.getV01();
				Quad.Vertex v11 = quad.getV11();
				Quad.Vertex v10 = quad.getV10();
				float v00x = v00.getX(delta);
				float v00y = v00.getY(delta);
				float v00z = v00.getZ(delta);
				float v01x = v01.getX(delta);
				float v01y = v01.getY(delta);
				float v01z = v01.getZ(delta);
				float v11x = v11.getX(delta);
				float v11y = v11.getY(delta);
				float v11z = v11.getZ(delta);
				float v10x = v10.getX(delta);
				float v10y = v10.getY(delta);
				float v10z = v10.getZ(delta);
				float nx = (v11y - v00y) * (v10z - v01z) - (v11z - v00z) * (v10y - v01y);
				float ny = (v10x - v01x) * (v11z - v00z) - (v10z - v01z) * (v11x - v00x);
				float nz = (v11x - v00x) * (v10y - v01y) - (v11y - v00y) * (v10x - v01x);
				float len = MathHelper.sqrt(nx * nx + ny * ny + nz * nz);
				nx /= len;
				ny /= len;
				nz /= len;
				buf.pos(v00x, v00y, v00z)
						.tex(v00.getU(), v00.getV())
						.normal(nx, ny, nz)
						.endVertex();
				buf.pos(v01x, v01y, v01z)
						.tex(v01.getU(), v01.getV())
						.normal(nx, ny, nz)
						.endVertex();
				buf.pos(v11x, v11y, v11z)
						.tex(v11.getU(), v11.getV())
						.normal(nx, ny, nz)
						.endVertex();
				buf.pos(v10x, v10y, v10z)
						.tex(v10.getU(), v10.getV())
						.normal(nx, ny, nz)
						.endVertex();
			}
			buf.setTranslation(0, 0, 0);
			GlStateManager.color(1, 1, 1);
			GlStateManager.disableCull();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);

			ItemStack stack = BaublesSupport.getItem(player, ModItems.CAPE);

			ResourceLocation fallBackCape;
			UUID uuid = NBTHelper.getUniqueId(stack, "uuid");
			if (uuid != null) {
				RandUtilSeed seed = new RandUtilSeed(uuid.hashCode());
				fallBackCape = new ResourceLocation(Wizardry.MODID, "textures/capes/cape_normal_" + seed.nextInt(1, 4) + ".png");
			} else {
				fallBackCape = new ResourceLocation(Wizardry.MODID, "textures/capes/cape_normal_3.png");
			}

			String capeName = "cape_" + player.getUniqueID().toString().replace("-", "");
			ResourceLocation loc = new ResourceLocation(Wizardry.MODID, "capes/" + capeName);

			ResourceLocation finalFallBackCape = fallBackCape;
			Minecraft.getMinecraft().addScheduledTask(() -> {
				ITextureObject itextureobject = Minecraft.getMinecraft().getTextureManager().getTexture(loc);

				if (itextureobject == null) {
					ThreadDownloadImageData threaddownloadimagedata = new ThreadDownloadImageData(null, "https://raw.githubusercontent.com/TeamWizardry/Wizardry/master/capes/" + capeName + ".png", finalFallBackCape, null);
					Minecraft.getMinecraft().getTextureManager().loadTexture(loc, threaddownloadimagedata);
				}
			});

			Minecraft.getMinecraft().getTextureManager().bindTexture(loc);

			tes.draw();
			GlStateManager.enableCull();
		}

public static void EXPLODE(World world, Vec3d pos, Color color1, Color color2, double strengthUpwards, double strengthSideways, int amount, int lifeTime, int lifeTimeRange, boolean bounce) {
		ParticleBuilder glitter = new ParticleBuilder(10);
		glitter.setRender(new ResourceLocation(Wizardry.MODID, MISC.SPARKLE_BLURRED));
		glitter.setCollision(true);
		glitter.enableMotionCalculation();
		glitter.setColorFunction(new InterpColorHSV(ColorUtils.changeColorAlpha(color1, RandUtil.nextInt(50, 150)), ColorUtils.changeColorAlpha(color2, RandUtil.nextInt(50, 150))));
		glitter.setAcceleration(new Vec3d(0, RandUtil.nextDouble(-0.03, -0.04), 0));
		glitter.setCanBounce(true);
		ParticleSpawner.spawn(glitter, world, new StaticInterp<>(pos), amount, 0, (i, build) -> {
			double radius = RandUtil.nextDouble(1, 2);
			double theta = 2.0f * (float) Math.PI * RandUtil.nextFloat();
			double r = radius * RandUtil.nextFloat();
			double x = r * MathHelper.cos((float) theta);
			double z = r * MathHelper.sin((float) theta);
			Vec3d normalize = new Vec3d(x, 0, z).normalize();
			glitter.setMotion(new Vec3d(
					normalize.x * RandUtil.nextDouble(-strengthSideways, strengthSideways),
					RandUtil.nextDouble(-strengthUpwards, strengthUpwards),
					normalize.z * RandUtil.nextDouble(-strengthSideways, strengthSideways)
			));
			glitter.setAlphaFunction(new InterpFloatInOut(0.0f, RandUtil.nextFloat()));
			glitter.setLifetime(RandUtil.nextInt(lifeTime - lifeTimeRange, lifeTime + lifeTimeRange));
			glitter.setScale(RandUtil.nextFloat());
		});
	}

public void spawn(int lifeTime, int lifeTimeRange, int amount, Vec3d pos, Color colorFrom, Color colorTo, double strengthUpwards, double strengthSideways) {
			reload();
			for (int i = 0; i < amount; i++) {
				double radius = RandUtil.nextDouble(1, 2);
				double theta = 2.0f * (float) Math.PI * RandUtil.nextFloat();
				double r = radius * RandUtil.nextFloat();
				double x = r * MathHelper.cos((float) theta) * RandUtil.nextDouble(-strengthSideways, strengthSideways);
				double z = r * MathHelper.sin((float) theta) * RandUtil.nextDouble(-strengthSideways, strengthSideways);

				addParticle(
						lifeTime + RandUtil.nextDouble(-lifeTimeRange, lifeTimeRange),
						RandUtil.nextDouble(0.2, 1f),
						pos.x, pos.y, pos.z,
						pos.x, pos.y, pos.z,
						x, RandUtil.nextDouble(-strengthUpwards, strengthUpwards), z,
						colorFrom.getRed() / 255.0, colorFrom.getGreen() / 255.0, colorFrom.getBlue() / 255.0, colorFrom.getAlpha() / 255.0,
						colorTo.getRed() / 255.0, colorTo.getGreen() / 255.0, colorTo.getBlue() / 255.0, colorTo.getAlpha() / 255.0
				);
			}
		}

