@Override
	public void doRenderLayer(@Nonnull AbstractClientPlayer entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		if (Minecraft.getMinecraft().player == null || Minecraft.getMinecraft().world == null) return;

		IManaCapability cap = ManaCapabilityProvider.getCap(entity);
		if (cap != null) {
			EnumBloodType type = cap.getBloodType();
			if (type != null && type != EnumBloodType.NONE) {
				render.bindTexture(EnumBloodType.getResourceLocation(type));
				ClientUtilMethods.glColor(type.color);
				setModelVisibilities(entity);
				GlStateManager.enableBlendProfile(Profile.PLAYER_SKIN);

				GlStateManager.disableLighting();
				ShaderHelper.INSTANCE.useShader(Shaders.rawColor);

				render.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

				GlStateManager.enableLighting();
				ShaderHelper.INSTANCE.releaseShader();

				GlStateManager.disableBlendProfile(Profile.PLAYER_SKIN);
				GlStateManager.color(1.0F, 1.0F, 1.0F);
			}
		}
	}

@Override
	public void render(float partialTicks, int destroyStage, float alpha) {
		ArrayList<BlockPos> errors = new ArrayList<>(((IStructure) tile.getBlockType()).testStructure(tile.getWorld(), tile.getPos()));
		errors.sort(Vec3i::compareTo);

		ItemStack input = tile.getInput();
		if (input.isEmpty()) {
			input = tile.getOutput();
			if (input.isEmpty()) {
				input = ItemStack.EMPTY;
			}
		}

		ICraftingPlateRecipe recipeForItem = CraftingPlateRecipeManager.getRecipe(tile.getWorld(), tile.getPos(), input);
		if (recipeForItem != null) recipeForItem.renderInput(tile.getWorld(), tile.getPos(), input, partialTicks);

		if (!errors.isEmpty() && tile.revealStructure && tile.getBlockType() instanceof IStructure) {
			ModStructures.structureManager.draw(ModStructures.CRAFTING_PLATE, (float) (Math.sin(ClientTickHandler.getTicks() / 10.0) + 1) / 10.0f + 0.3f);
		}

		if (!errors.isEmpty()) {
			for (BlockPos error : errors) {
				StructureErrorRenderer.addError(error);
			}
			return;
		} else if (tile.getWorld().isAirBlock(tile.getPos().offset(EnumFacing.UP)) && !CraftingPlateRecipeManager.doesRecipeExist(tile.getWorld(), tile.getPos(), input) && RandUtil.nextInt(4) == 0) {
			LibParticles.CRAFTING_ALTAR_IDLE(tile.getWorld(), new Vec3d(tile.getPos()).add(0.5, 0.7, 0.5));
		}

		// render each item at its current position
		final int mapSize = hoveringStacks.size();
		for (HoveringStack hoveringStack : hoveringStacks.values()) {

			if (!hoveringStack.stack.isEmpty()) {

				{
					GlStateManager.pushMatrix();
					GlStateManager.translate(0.5 + hoveringStack.location.x, 1 + hoveringStack.location.y, 0.5 + hoveringStack.location.z);
					GlStateManager.scale(0.3, 0.3, 0.3);
					GlStateManager.rotate((hoveringStack.randX + ClientTickHandler.getTicks()), 0, 1, 0);
					GlStateManager.rotate((hoveringStack.randY + ClientTickHandler.getTicks()), 1, 0, 0);
					GlStateManager.rotate((hoveringStack.randZ + ClientTickHandler.getTicks()), 0, 0, 1);

					GlStateManager.enableLighting();
					RenderHelper.disableStandardItemLighting();
					Minecraft.getMinecraft().getRenderItem().renderItem(hoveringStack.stack, TransformType.NONE);
					RenderHelper.enableStandardItemLighting();
					GlStateManager.popMatrix();
				}

				if (tile.suckingCooldown <= 0) {
					if (RandUtil.nextInt(mapSize / 2) == 0) {
						LibParticles.CLUSTER_DRAPE(
								tile.getWorld(),
								hoveringStack.location.add(new Vec3d(tile.getPos())).add(0.5, 0.5, 0.5));
					}
				} else {
					if (RandUtil.nextInt(mapSize) == 0) {
						LibParticles.CRAFTING_ALTAR_CLUSTER_SUCTION(
								tile.getWorld(),
								new Vec3d(tile.getPos()).add(0.5, 0.75, 0.5),
								new InterpBezier3D(hoveringStack.location, new Vec3d(0, 0, 0)));
					}
				}
			}
		}
	}

@Override
	public void render(float partialTicks, int destroyStage, float alpha) {
		if (RandUtil.nextInt(4) == 0) {
			Color primaryColor;
			Color secondaryColor;
			if (te.getModule() != null) {
				primaryColor = te.getModule().getPrimaryColor();
				secondaryColor = te.getModule().getSecondaryColor();
			} else {
				// NOTE: Usually should never happen, if tile entity is initialized correctly in ModuleEffectLight.
				primaryColor = new Color(0xAA00AA);    // Purple color.
				secondaryColor = new Color(0x000000);
			}

			ParticleBuilder glitter = new ParticleBuilder(30);
			glitter.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
			glitter.setAlphaFunction(new InterpFloatInOut(0.3f, 0.3f));
			glitter.setColorFunction(new InterpColorHSV(Color.CYAN, Color.BLUE));
			glitter.setScaleFunction(new InterpScale((float) RandUtil.nextDouble(1, 3), 0));
			ParticleSpawner.spawn(glitter, te.getWorld(), new StaticInterp<>(new Vec3d(te.getPos()).add(0.5, 0.5, 0.5)), 1, 0, (i, build) -> {
				build.setMotion(new Vec3d(
						RandUtil.nextDouble(-0.01, 0.01),
						RandUtil.nextDouble(0, 0.03),
						RandUtil.nextDouble(-0.01, 0.01)));

				if (RandUtil.nextBoolean()) {
					build.setColorFunction(new InterpColorHSV(primaryColor, secondaryColor));
				} else {
					build.setColorFunction(new InterpColorHSV(secondaryColor, primaryColor));
				}
			});
		}
	}

@Override
	public void render(float partialTicks, int destroyStage, float alpha) {
		if (!getBakedModels()) return;

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		TextureManager texturemanager = Minecraft.getMinecraft().renderEngine;

		if (texturemanager != null) {
			texturemanager.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		}

		if (Minecraft.isAmbientOcclusionEnabled())
			GlStateManager.shadeModel(GL11.GL_SMOOTH);
		else GlStateManager.shadeModel(GL11.GL_FLAT);

		float fill = (float) (ManaManager.getMana(tile.getWizardryCap()) / ManaManager.getMaxMana(tile.getWizardryCap())) / 40.0f;


		GlStateManager.translate(0, 0.5, 0);
		GlStateManager.disableRescaleNormal();

		{
			double x = RandUtil.nextDouble(-fill, fill), y = RandUtil.nextDouble(-fill, fill), z = RandUtil.nextDouble(-fill, fill);
			GlStateManager.translate(0, Math.sin((ClientTickHandler.getTicks() + ClientTickHandler.getPartialTicks()) / 40) / 8, 0);

			GlStateManager.translate(x, y, z);
			Minecraft.getMinecraft().getBlockRendererDispatcher().getBlockModelRenderer().renderModelBrightnessColor(modelCrystal, 1.0F, 1, 1, 1);
			GlStateManager.translate(-x, -y, -z);
		}

		GlStateManager.translate(0.5, 0, 0.5);
		GlStateManager.rotate(ClientTickHandler.getTicks() + ClientTickHandler.getPartialTicks(), 0, 1, 0);
		GlStateManager.translate(-0.5, 0, -0.5);

		Minecraft.getMinecraft().getBlockRendererDispatcher().getBlockModelRenderer().renderModelBrightnessColor(modelRing, 1.0F, 1, 1, 1);

		GlStateManager.translate(0.5, 0, 0.5);
		GlStateManager.rotate(ClientTickHandler.getTicks() + ClientTickHandler.getPartialTicks(), 0, -1, 0);
		GlStateManager.rotate(ClientTickHandler.getTicks() + ClientTickHandler.getPartialTicks(), 0, -1, 0);
		GlStateManager.translate(-0.5, 0, -0.5);

		Minecraft.getMinecraft().getBlockRendererDispatcher().getBlockModelRenderer().renderModelBrightnessColor(modelRingOuter, 1.0F, 1, 1, 1);

		GlStateManager.disableBlend();
		GlStateManager.popMatrix();

		ArrayList<BlockPos> errors = new ArrayList<>(((IStructure) tile.getBlockType()).testStructure(tile.getWorld(), tile.getPos()));
		errors.sort(Vec3i::compareTo);

		if (!errors.isEmpty()) {
			for (BlockPos error : errors) {
				StructureErrorRenderer.addError(error);
			}
		}

		if (!errors.isEmpty() && tile.revealStructure && tile.getBlockType() instanceof IStructure) {
			ModStructures.structureManager.draw(ModStructures.MANA_BATTERY, (float) (Math.sin(ClientTickHandler.getTicks() / 10.0) + 1) / 10.0f + 0.3f);
			return;
		}

		if (tile.getBlockType() == ModBlocks.CREATIVE_MANA_BATTERY) {
			double angle = ClientTickHandler.getTicks() / 10.0;
			double x1 = Math.cos((float) angle);
			double y1 = Math.sin((float) angle);

			ParticleBuilder builder = new ParticleBuilder(10);
			builder.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
			builder.setCollision(true);
			builder.disableRandom();
			builder.disableMotionCalculation();

			ParticleSpawner.spawn(builder, tile.getWorld(), new InterpCircle(new Vec3d(tile.getPos()).add(0.5, 0.5, 0.5), new Vec3d(x1, x1, y1), 1.5f), 20, 0, (aFloat, particleBuilder) -> {
				particleBuilder.setScale(0.5f);
				particleBuilder.setColor(new Color(0xd600d2));
				particleBuilder.setAlphaFunction(new InterpFloatInOut(1, 1));
				particleBuilder.setLifetime(RandUtil.nextInt(5, 10));
			});
		} else if (ClientTickHandler.getTicks() % 10 == 0 && ManaManager.forObject(tile.getWizardryCap()).isManaFull()) {
			double radius = 1;
			double theta = 2.0f * (float) Math.PI * RandUtil.nextFloat();
			double r = radius * RandUtil.nextFloat();
			double x = r * MathHelper.cos((float) theta);
			double z = r * MathHelper.sin((float) theta);

			ParticleBuilder helix = new ParticleBuilder(20);
			helix.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
			helix.setAlphaFunction(new InterpFloatInOut(0.1f, 0.4f));
			ParticleSpawner.spawn(helix, tile.getWorld(), new StaticInterp<>(new Vec3d(tile.getPos()).add(0.5, 0.5, 0.5)), 1, 0, (someFloat, particleBuilder) -> {
				particleBuilder.setColor(ColorUtils.changeColorAlpha(new Color(0x0097FF), RandUtil.nextInt(50, 200)));
				particleBuilder.setScale(RandUtil.nextFloat(0.5f, 1.2f));
				particleBuilder.setMotion(new Vec3d(x, RandUtil.nextDouble(-1, 1), z).scale(0.05));
				particleBuilder.setLifetime(RandUtil.nextInt(20, 40));
			});
		}
	}

