@Override
    protected void scale(Swet swet, PoseStack poseStack, float partialTicks) {
        float scale = 1.5F;
        if (!swet.getPassengers().isEmpty()) {
            scale += (swet.getPassengers().getFirst().getBbWidth() + swet.getPassengers().getFirst().getBbHeight()) * 0.75F;
        }

        float height = Mth.lerp(partialTicks, swet.getSwetHeightO(), swet.getSwetHeight());
        float width = Mth.lerp(partialTicks, swet.getSwetWidthO(), swet.getSwetWidth());

        poseStack.scale(width * scale, height * scale, width * scale);
        poseStack.scale(swet.getScale(), swet.getScale(), swet.getScale());
        this.shadowRadius = 0.3F * width;
    }

@Override
    public void render(TntPresent present, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        poseStack.pushPose();
        poseStack.translate(0.0, 0.5, 0.0);
        if ((float) present.getFuse() - partialTicks + 1.0F < 10.0F) {
            float f = 1.0F - ((float) present.getFuse() - partialTicks + 1.0F) / 10.0F;
            f = Mth.clamp(f, 0.0F, 1.0F);
            f = Mth.square(f);
            f = Mth.square(f);
            float f1 = 1.0F + f * 0.3F;
            poseStack.scale(f1, f1, f1);
        }
        poseStack.translate(-0.5, -0.5, -0.5);
        TntMinecartRenderer.renderWhiteSolidBlock(this.blockRenderer, AetherBlocks.PRESENT.get().defaultBlockState(), poseStack, buffer, packedLight, present.getFuse() / 5 % 2 == 0);
        poseStack.popPose();
        super.render(present, entityYaw, partialTicks, poseStack, buffer, packedLight);
    }

@Override
    protected void scale(Zephyr zephyr, PoseStack poseStack, float partialTicks) {
        float f = Math.min(Mth.lerp(partialTicks, zephyr.getCloudScale(), zephyr.getCloudScale() + zephyr.getCloudScaleAdd()), 38.0F);
        float f1 = f / 38.0F;
        if (f1 < 0.0F) {
            f1 = 0.0F;
        }
        f1 = 1.0F / ((float) Math.pow(f1, 5) * 2.0F + 1.0F);
        float f2 = (8.0F + f1) / 2.0F;
        float f3 = (8.0F + 1.0F / f1) / 2.0F;

        poseStack.scale(f3, f2, f3);
        poseStack.translate(0.0, 0.5, 0.0);

        if (this.getModel() instanceof ClassicZephyrModel) {
            poseStack.scale(0.8F, 0.8F, 0.8F);
            poseStack.translate(0.0, -0.1, 0.0);
        }
    }

