public void setupWingRotation(T entity, float sinage) {
        if (!entity.onGround() && !entity.isInFluidType() && (entity.getVehicle() != null && !entity.getVehicle().onGround())) {
            sinage *= 1.5F;
        } else {
            sinage *= 0.3F;
        }

        this.wings.rightWing.yRot = 0.4F;
        this.wings.rightWing.zRot = 0.125F;
        this.wings.leftWing.yRot = -0.4F;
        this.wings.leftWing.zRot = -0.125F;

        if (entity.isCrouching()) {
            this.wings.rightWing.xRot = 0.45F;
            this.wings.rightWing.y = 3.33F;
            this.wings.rightWing.z = 3.388F;
            this.wings.leftWing.xRot = 0.45F;
            this.wings.leftWing.y = 3.33F;
            this.wings.leftWing.z = 3.388F;
        } else {
            this.wings.rightWing.xRot = 0.0F;
            this.wings.leftWing.xRot = 0.0F;
        }

        this.wings.rightWing.yRot -= Mth.sin(sinage) / 6.0F;
        this.wings.rightWing.zRot -= Mth.cos(sinage) / (entity.onGround() || entity.isInFluidType() ? 8.0F : 3.0F);
        this.wings.leftWing.yRot += Mth.sin(sinage) / 6.0F;
        this.wings.leftWing.zRot += Mth.cos(sinage) / (entity.onGround() || entity.isInFluidType() ? 8.0F : 3.0F);
    }

@Override
	public void renderOverlay(Minecraft mc, PoseStack stack) {
		RenderSystem.setShader(GameRenderer::getPositionTexShader);
		RenderSystem.setShaderTexture(0, getRenderOverlayTexture(mc));

		BufferBuilder buffer = Tesselator.getInstance().begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
		float uOffset = mc.player.getYRot() / 512f + (mc.player.tickCount / 1800f);
		float vOffset = mc.player.getXRot() / 1024f + (mc.player.tickCount / 3600f);
		Matrix4f matrixStack = stack.last().pose();

		RenderSystem.enableBlend();
		RenderSystem.defaultBlendFunc();
		RenderSystem.setShaderColor(0.5f, 0.5f, 0.5f, 0.5f);
		buffer.addVertex(matrixStack, -1.0F, -1.0F, -0.5F).setUv(uOffset, 1 + vOffset).setNormal(0.0F, 1.0F, 0.0F);
		buffer.addVertex(matrixStack, 1.0F, -1.0F, -0.5F).setUv(1 + uOffset, 1 + vOffset).setNormal(0.0F, 1.0F, 0.0F);
		buffer.addVertex(matrixStack, 1.0F, 1.0F, -0.5F).setUv(1 + uOffset, vOffset).setNormal(0.0F, 1.0F, 0.0F);
		buffer.addVertex(matrixStack, -1.0F, 1.0F, -0.5F).setUv(uOffset, vOffset).setNormal(0.0F, 1.0F, 0.0F);
		BufferUploader.drawWithShader(buffer.buildOrThrow());
		RenderSystem.disableBlend();
	}

@Override
    public boolean applyForgeHandTransform(PoseStack poseStack, LocalPlayer player, HumanoidArm arm, ItemStack stack, float partialTick, float equipProcess, float swingProcess) {
        if (player.isUsingItem() && player.getUseItemRemainingTicks() > 0) {
            poseStack.translate(0.725f, -0.3f, -0.15f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-5));
            poseStack.mulPose(Axis.ZN.rotationDegrees(25));
            poseStack.mulPose(Axis.YP.rotationDegrees(90));
