    }

private static void onEntityTick(EntityTickEvent.Post ev) {
		if (AoAConfigs.CLIENT.partyDeaths.get() && ev.getEntity() instanceof LivingEntity entity && entity.deathTime >= 10) {
			AABB boundingBox = entity.getBoundingBox();
			double width = boundingBox.maxX - boundingBox.minX;
			double depth = boundingBox.maxZ - boundingBox.minZ;
			double height = boundingBox.maxY - boundingBox.minY;

			for (int i = 0; i < 3 + (10 * width * depth * height); i++) {
				ParticleBuilder.forRandomPosInBounds(AoAParticleTypes.GENERIC_DUST.get(), entity.getBoundingBox())
						.scaleMod(0.1f)
						.power(new Vec3(RandomUtil.scaledGaussianValue(0.05d), 0, RandomUtil.scaledGaussianValue(0.05d)))
						.colourTint(RandomUtil.colour(0.75f, 0.75f, 1f))
						.spawnClientParticles(entity.level());
			}
		}
	}

@Override
	public void tick() {
		if (this.entity == null || !this.entity.isAlive()) {
			remove();

			return;
		}

		this.xo = this.x;
		this.yo = this.y;
		this.zo = this.z;

		double slope = 20 * Mth.DEG_TO_RAD;
		double angleX = Math.cos(slope);
		double angleZ = Math.sin(slope);
		double angleY = Math.cos(angleX + angleZ);
		Vec3 rotDelta = new Vec3(
				angleX * (this.x - this.startX) - angleZ * (this.z - this.startZ),
				angleY * (this.y - this.startY) * Math.tan(angleX + angleZ),
				angleZ * (this.x - this.startX) + angleX * (this.z - this.startZ)
		).normalize().scale(2f).add(this.startX, this.startY, this.startZ);

		this.xd = rotDelta.x - this.x;
		this.yd = rotDelta.y - this.y;
		this.zd = rotDelta.z - this.z;

		move(this.xd, this.yd, this.zd);

		if (this.age++ >= this.lifetime)
			remove();
	}

private static void renderResources(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
		Minecraft mc = Minecraft.getInstance();

		if (mc.player == null || mc.player.isSpectator() || mc.options.hideGui)
			return;

		float partialTick = deltaTracker.getGameTimeDeltaPartialTick(false);
		Window window = mc.getWindow();
		int horizontalAdjuster = AoAConfigs.CLIENT.hudResourcesHorizontal.get() ? 1 : 0;
		int verticalAdjuster = horizontalAdjuster == 1 ? 0 : 1;
		int potionRenderOffset = 0;
		int x = 0;
		int y = 0;
		PoseStack poseStack = guiGraphics.pose();

		if (AoAConfigs.CLIENT.hudResourcesPosition.get() == AoAResourceRenderer.HudResourcesPosition.Top_Right) {
			horizontalAdjuster *= -1;
			x = window.getGuiScaledWidth();
			potionRenderOffset = RenderUtil.getPotionGuiRenderOffset();
			y = potionRenderOffset;

			if (horizontalAdjuster == 0)
				x -= 25;
		}

		poseStack.pushPose();
		poseStack.translate(x, y, 0);

		x = 0;
		y = 0;

		if (AoAKeybinds.statusResourceGui) {
			int lastHeight = 0;

			for (AoAResource.Instance resource : ClientPlayerDataManager.get().getResources()) {
				AoAResourceRenderer renderer = AoAGuiElementRenderers.getResourceRenderer(resource.type());
				x += (renderer.hudRenderWidth(resource) * horizontalAdjuster);
				y += (renderer.hudRenderHeight(resource) * verticalAdjuster);
				lastHeight = y + renderer.hudRenderHeight(resource);

				poseStack.pushPose();
				poseStack.translate(x, y, 0);
				renderer.renderInHud(poseStack, resource, partialTick, null);
				poseStack.popPose();
			}

			y = lastHeight;
		}
		else if (AoAKeybinds.statusResourceGuiMessage & AoAKeybinds.RESOURCE_GUI.getKey().getValue() != -1) {
			poseStack.scale(0.5f, 0.5f, 0);
			MutableComponent locale = LocaleUtil.getLocaleMessage("gui.aoa3.resources.showtip", AoAKeybinds.RESOURCE_GUI.getTranslatedKeyMessage());

			RenderUtil.renderCenteredScaledText(poseStack, locale, -(int)(mc.font.width(locale) * 0.75f), (int)((y + 4) / 2f), 1.5f, ColourUtil.WHITE, RenderUtil.TextRenderType.OUTLINED);

			y = y + 4 + mc.font.lineHeight / 2;
		}

		poseStack.popPose();

		resourcesRenderHeightOffset = (AoAConfigs.CLIENT.hudResourcesPosition.get() == AoAResourceRenderer.HudResourcesPosition.Top_Right ? y : 0) + potionRenderOffset;
	}

private static void renderSkills(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
		Minecraft mc = Minecraft.getInstance();

		if (mc.player == null || mc.player.isSpectator() || mc.options.hideGui)
			return;

		float partialTick = deltaTracker.getGameTimeDeltaPartialTick(false);
		Window window = mc.getWindow();
		int x = 0;
		int y = 0;
		PoseStack poseStack = guiGraphics.pose();

		poseStack.pushPose();
		poseStack.translate(window.getGuiScaledWidth(), resourcesRenderHeightOffset, 0);
		RenderSystem.disableDepthTest();

		if (AoAKeybinds.statusSkillGui) {
			int maxHeight = 0;
			int cumulativeXOffset = 0;

			for (AoASkill.Instance skill : ClientPlayerDataManager.get().getSkills()) {
				AoASkillRenderer renderer = AoAGuiElementRenderers.getSkillRenderer(skill.type());
				int xOffset = renderer.hudRenderWidth(skill);
				cumulativeXOffset += xOffset;
				x -= xOffset;
				maxHeight = Math.max(maxHeight, renderer.hudRenderHeight(skill));

				if (cumulativeXOffset >= xOffset * 6) {
					y += maxHeight;
					x += cumulativeXOffset - xOffset;
					maxHeight = 0;
					cumulativeXOffset = 0;
				}

				poseStack.pushPose();
				poseStack.translate(x, y, 0);
				renderer.renderInHud(RenderContext.of(guiGraphics), skill, partialTick, AoAConfigs.CLIENT.hudSkillProgressRenderType.get(), true);
				poseStack.popPose();
			}
		}
		else if (AoAKeybinds.statusSkillGuiMessage & AoAKeybinds.SKILL_GUI.getKey().getValue() != -1) {
			poseStack.scale(0.5f, 0.5f, 1);
			MutableComponent locale = LocaleUtil.getLocaleMessage("gui.aoa3.skills.showtip", AoAKeybinds.SKILL_GUI.getTranslatedKeyMessage());

			RenderUtil.renderCenteredScaledText(poseStack, locale, -(int)(mc.font.width(locale) * 0.75f), (int)(y / 2f) + 1, 1.5f, ColourUtil.WHITE, RenderUtil.TextRenderType.OUTLINED);
		}

		RenderSystem.enableDepthTest();
		poseStack.popPose();
	}

@Override
	public void render(BossAltarBlockEntity blockEntity, float partialTick, PoseStack matrix, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
		Entity entity = blockEntity.getCachedEntity();

		if (entity != null) {
			matrix.pushPose();
			matrix.translate(0.5f, 0, 0.5f);

			float scale = 0.53125F;
			float maxScale = Math.max(entity.getBbWidth(), entity.getBbHeight());

			if (maxScale > 1.0D)
				scale /= maxScale;

			matrix.translate(0, -0.1, 0);
			matrix.scale(scale, scale, scale);
			matrix.translate(0, (1 / scale), 0);
			matrix.mulPose(Axis.YP.rotationDegrees((entity.level().getGameTime() + partialTick) % 360 - 90));

			Minecraft.getInstance().getEntityRenderDispatcher().render(entity, 0, 0, 0, 0, 0, matrix, buffer, combinedLight);
			matrix.popPose();

			if (partialTick > 0.5f && !Minecraft.getInstance().isPaused()) {
				BlockPos pos = blockEntity.getBlockPos();
				RandomSource rand = blockEntity.getLevel().getRandom();

				blockEntity.getLevel().addParticle(ParticleTypes.GLOW, pos.getX() - 3 + rand.nextFloat() * 7, pos.getY() + 0.2, pos.getZ() - 3 + rand.nextFloat() * 7, 0, 0, 0);
			}
		}
	}

@Override
	public void render(ImbuingChamberBlockEntity imbuingChamber, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight, int packedOverlay) {
		final List<ItemStack> contents = imbuingChamber.getItems();
		final Direction direction = imbuingChamber.getBlockState().getValue(HorizontalDirectionalBlock.FACING).getCounterClockWise();

		poseStack.pushPose();
		poseStack.translate(0.5f, 0.5625f, 0.5f);
		poseStack.mulPose(Axis.YN.rotationDegrees(direction.toYRot()));

		renderContents(poseStack, contents, partialTick, packedLight, packedOverlay, buffer);

		int colour = renderBeam(poseStack, contents, partialTick, packedLight, packedOverlay, buffer);

		if (colour != 0) {
			Vec3 pos = new Vec3(imbuingChamber.getBlockPos().getX() + 0.5f, imbuingChamber.getBlockPos().getY() + 0.7f, imbuingChamber.getBlockPos().getZ() + 0.5f)
					.add(direction.getStepX() * 0.375f, 0, direction.getStepZ() * 0.375f);

			if (!Minecraft.getInstance().isPaused()) {
				ParticleBuilder.forPositions(ParticleTypes.WARPED_SPORE, pos)
						.colourTint(ColourUtil.getRed(colour), ColourUtil.getGreen(colour), ColourUtil.getBlue(colour), 255)
						.cutoffDistance(16)
						.scaleMod(0.25f)
						.isAmbient()
						.lifespan(3)
						.spawnClientParticles(Minecraft.getInstance().level);
			}
		}

		poseStack.popPose();
	}

private static int renderBeam(PoseStack poseStack, List<ItemStack> contents, float partialTick, int packedLight, int packedOverlay, MultiBufferSource buffer) {
		if (contents.get(0).getItem() instanceof PowerStone powerStone) {
			int colour = powerStone.getColour();
			int currentIndex = 1;
			int lastIndex = 0;
			ItemStack slotStack;

			poseStack.mulPose(Axis.XP.rotationDegrees(90));
			poseStack.translate(-0.5f, -0.375f, -0.5f);

			do {
				if (!(slotStack = contents.get(currentIndex)).isEmpty() || currentIndex == 6) {
					int delta = (currentIndex - lastIndex);

					poseStack.pushPose();
					poseStack.translate(0, (lastIndex) * 0.137f, 0);
					poseStack.scale(1, 0.137f * delta, 1);
					BeaconRenderer.renderBeaconBeam(poseStack, buffer, BeaconRenderer.BEAM_LOCATION, partialTick, 0.125f, Minecraft.getInstance().level.getGameTime() * 12, 0, 1, colour, 0.1f, 0.12f);
					poseStack.popPose();

					if (slotStack.getItem() instanceof AspectFocusItem focus)
						colour = ColourUtil.lerpColour(colour, focus.getFocus().colour(), 0.75f);

					lastIndex = currentIndex;
				}

				currentIndex++;
			} while (currentIndex < contents.size());

			return colour;
		}

		return 0;
	}

private static void renderContents(PoseStack poseStack, List<ItemStack> contents, float partialTick, int packedLight, int packedOverlay, MultiBufferSource buffer) {
		final ItemRenderer renderer = Minecraft.getInstance().getItemRenderer();

		for (int i = 0; i < contents.size(); i++) {
			ItemStack focus = contents.get(i);

			if (focus == ItemStack.EMPTY)
				continue;

			poseStack.pushPose();
			poseStack.translate(0, 0, -0.34375f + 0.125 * i);

			if (i == 0 || i == 6) {
				poseStack.scale(0.5f, 0.5f, 0.5f);

				if (i == 0) {
					poseStack.translate(0, 0, 0.0313f);
				}
				else {
					poseStack.translate(0, 0, -0.03125f);
				}
			}

			renderer.renderStatic(focus, ItemDisplayContext.FIXED, packedLight, packedOverlay, poseStack, buffer, Minecraft.getInstance().level, 0);
			poseStack.popPose();
		}
	}

@Override
	public void render(InfusedPressBlockEntity blockEntity, float partialTicks, PoseStack matrix, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
		GenericItemStackHandler itemHandler = blockEntity.getItemHandler();
		ItemRenderer renderer = Minecraft.getInstance().getItemRenderer();
		Level world = blockEntity.getLevel();
		BlockPos abovePos = blockEntity.getBlockPos().above();

		if (world != null) {
			if (world.getBlockState(abovePos).isSolidRender(world, abovePos))
				return;

			combinedLight = LevelRenderer.getLightColor(world, abovePos);
		}
		else {
			combinedLight = LightTexture.FULL_BRIGHT;
		}

		matrix.pushPose();

		matrix.scale(0.25f, 0.25f, 0.25f);
		matrix.translate(1.25f, 4f, 1.25f);
		matrix.mulPose(Axis.YP.rotationDegrees(180f));

		ItemStack output = itemHandler.getStackInSlot(9);

		if (!output.isEmpty()) {
			matrix.pushPose();
			matrix.translate(-0.75f, 0, -0.75f);
			matrix.mulPose(Axis.XP.rotationDegrees(90f));
			matrix.scale(4, 4, 0.25f);

			if (!(output.getItem() instanceof BlockItem))
				matrix.scale(1, 1, 0.5f);

			renderer.renderStatic(output, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, matrix, buffer, blockEntity.getLevel(), 0);

			matrix.popPose();
		}

		for (int i = 0; i < 9; i++) {
			ItemStack stack = itemHandler.getStackInSlot(i);

			if (stack.isEmpty())
				continue;

			matrix.pushPose();
			matrix.translate(-0.75f * (i % 3), 0.01f, -0.75f * (i / 3));
			matrix.mulPose(Axis.XP.rotationDegrees(90f));

			renderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, matrix, buffer, blockEntity.getLevel(), 0);
			matrix.popPose();
		}

		matrix.popPose();
	}

@Override
	public void render(InfusionTableBlockEntity blockEntity, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
		final NonNullList<ItemStack> contents = blockEntity.getItems();
		final ItemRenderer renderer = Minecraft.getInstance().getItemRenderer();
		final Level level = blockEntity.getLevel();
		final BlockPos pos = blockEntity.getBlockPos();
		final BlockPos abovePos = pos.above();

		if (level != null) {
			if (level.getBlockState(abovePos).isSolidRender(level, abovePos))
				return;

			combinedLight = LevelRenderer.getLightColor(level, abovePos);
		}
		else {
			combinedLight = LightTexture.FULL_BRIGHT;
		}

		poseStack.pushPose();

		poseStack.scale(0.25f, 0.25f, 0.25f);
		poseStack.translate(1.25f, 4.25f, 1.25f);
		poseStack.mulPose(Axis.YP.rotationDegrees(180f));

		ItemStack input = contents.get(0);
		ItemStack output = contents.get(10);

		if (!input.isEmpty()) {
			poseStack.pushPose();
			poseStack.translate(-0.75f, 1.25f, -0.75f);
			poseStack.mulPose(Axis.YP.rotationDegrees(level.getGameTime() + partialTick));
			poseStack.scale(1.25f, 1.25f, 1.25f);

			if (!(input.getItem() instanceof BlockItem))
				poseStack.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(input, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, poseStack, buffer, blockEntity.getLevel(), 0);
			poseStack.popPose();

			if (!output.isEmpty() && RandomUtil.oneInNChance(10)) {
				Vec3 slotItemPos = Vec3.atCenterOf(blockEntity.getBlockPos())
						.add(level.random.nextGaussian() * 0.02f, 0.9, level.random.nextGaussian() * 0.02f);
				Vec3 velocity = slotItemPos.vectorTo(slotItemPos.add(0, 0.25f, 0)).scale(0.02);

				ParticleBuilder.forPositions(new ItemParticleOption(ParticleTypes.ITEM, input), slotItemPos)
						.scaleMod(0.125f)
						.gravityOverride(0)
						.velocity(velocity.x, velocity.y,	velocity.z)
						.addTransition(ToVelocityParticleTransition.create(velocity))
						.lifespan(30)
						.cutoffDistance(20)
						.spawnClientParticles(level);
			}
		}

		if (!output.isEmpty()) {
			poseStack.pushPose();
			poseStack.translate(-0.75f, 2, -0.75f);
			poseStack.mulPose(Axis.YN.rotationDegrees(level.getGameTime() + partialTick));
			poseStack.scale(1.75f, 1.75f, 1.75f);

			if (!(output.getItem() instanceof BlockItem))
				poseStack.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(output, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, poseStack, buffer, blockEntity.getLevel(), 0);
			poseStack.popPose();
		}

		for (int i = 1; i < 10; i++) {
			ItemStack stack = contents.get(i);

			if (stack.isEmpty())
				continue;

			final int row = (i - 1) % 3;
			final int column = (i - 1) / 3;

			poseStack.pushPose();
			poseStack.translate(-0.75f * row, 0, -0.75f * column);

			if (!(stack.getItem() instanceof BlockItem))
				poseStack.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, poseStack, buffer, blockEntity.getLevel(), 0);
			poseStack.popPose();

			if (RandomUtil.oneInNChance(input.isEmpty() ? 50 : 10)) {
				Vec3 slotItemPos = Vec3.atLowerCornerOf(blockEntity.getBlockPos())
						.add(0.3125f, 1, 0.3125f)
						.add(row * 0.1875f, 0.0625f, column * 0.1875f)
						.add(level.random.nextGaussian() * 0.02f, level.random.nextGaussian() * 0.02f, level.random.nextGaussian() * 0.02f);
				Vec3 velocity;

				if (input.isEmpty()) {
					velocity = new Vec3(level.random.nextGaussian() * 0.001f, 0.01f, level.random.nextGaussian() * 0.001f);
				}
				else {
					Vec3 targetPos = Vec3.atCenterOf(blockEntity.getBlockPos())
							.add(0, 0.95, 0);
					velocity = slotItemPos.vectorTo(targetPos).normalize().scale(0.0125f);
				}

				ParticleBuilder.forPositions(new ItemParticleOption(ParticleTypes.ITEM, stack), slotItemPos)
						.scaleMod(0.125f)
						.gravityOverride(0)
						.lifespan(30)
						.velocity(velocity.x, velocity.y,	velocity.z)
						.addTransition(ToVelocityParticleTransition.create(velocity))
						.cutoffDistance(20)
						.spawnClientParticles(level);
			}
		}

		poseStack.popPose();
	}

