@Override
	public void render(TrophyBlockEntity blockEntity, float partialTick, PoseStack matrix, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
		Entity entity = blockEntity.getCachedEntity();

		if (entity != null) {
			matrix.pushPose();
			matrix.translate(0.5f, 0, 0.5f);

			float scale = 0.53125F;
			float maxScale = Math.max(entity.getBbWidth(), entity.getBbHeight());
			double hover = (Mth.sin((float)blockEntity.hoverStep + partialTick) / 30d);
			blockEntity.hoverStep += hover * 0.01f;
			RandomSource random = entity.level().getRandom();

			if (maxScale > 1.0D)
				scale /= maxScale;

			matrix.translate(0, -0.1, 0);
			matrix.scale(scale, scale, scale);
			matrix.translate(0, (1 / scale), 0);

			if (blockEntity.getTrophyData().isOriginalTrophy() && !Minecraft.getInstance().isPaused() && random.nextInt(5) == 0) {
				float colourMod = random.nextFloat() * 0.7f + 0.3f;
				Vec3 pos = Vec3.atBottomCenterOf(blockEntity.getBlockPos()).add(random.nextGaussian() * (entity.getBbWidth() / 2f) * scale * 0.75f, 0.9f + random.nextFloat() * entity.getBbHeight() * scale, random.nextGaussian() * (entity.getBbWidth() / 2f) * scale * 0.75f);

				ParticleBuilder.forPositions(ParticleTypes.GLOW, pos)
						.scaleMod(0.05f)
						.lifespan(Mth.ceil(10 * (random.nextFloat() * 0.8f + 0.2f)))
						.colourTint(colourMod, colourMod * 200 / 255f, 0, 1f)
						.power(Vec3.ZERO)
						.spawnClientParticles(entity.level());
			}

			if (AoAConfigs.CLIENT.rotatingTrophies.get())
				matrix.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTick, blockEntity.getPrevMobRotation(), blockEntity.getMobRotation()) * 30.0F));

			Minecraft.getInstance().getEntityRenderDispatcher().render(entity, 0, 0, 0, 0, 0, matrix, buffer, combinedLight);
			matrix.popPose();
		}
	}

default void renderInHud(PoseStack matrix, AoAResource.Instance resource, float partialTicks, @Nullable String valueOverride) {
		ResourceLocation resourceId = AoARegistries.AOA_RESOURCES.getKey(resource.type());

		matrix.pushPose();
		matrix.scale(0.5f, 0.5f, 0);
		RenderSystem.setShaderColor(1, 1, 1, 1);
		RenderSystem.setShader(GameRenderer::getPositionTexShader);
		RenderSystem.setShaderTexture(0, ResourceLocation.fromNamespaceAndPath(resourceId.getNamespace(), "textures/gui/aoaresource/" + resourceId.getPath() + ".png"));

		int renderWidth = hudRenderWidth(resource) * 2;
		int renderHeight = hudRenderHeight(resource) * 2;
		float currentValue = resource.getCurrentValue();
		String value = String.valueOf((int)currentValue);

		if (valueOverride != null) {
			if (valueOverride.equals("-1")) {
				currentValue = resource.getMaxValue();
				value = "";
			}
			else if (NumberUtils.isParsable(valueOverride)) {
				currentValue = Float.parseFloat(valueOverride);
				value = String.valueOf((int)currentValue);
			}
			else {
				currentValue = resource.getMaxValue();
				value = valueOverride;
			}
		}

		float percentOfMax = (float)Math.floor((Math.min(currentValue, resource.getMaxValue()) / resource.getMaxValue()) * (float)renderWidth);

		RenderUtil.renderScaledCustomSizedTexture(matrix, 0, 0, 0, 0, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth, renderHeight * 3);
		RenderUtil.renderScaledCustomSizedTexture(matrix, 0, 0, 0, percentOfMax == renderWidth ? renderHeight * 2 : renderHeight, percentOfMax, renderHeight, percentOfMax, renderHeight, renderWidth, renderHeight * 3);
		RenderUtil.renderCenteredScaledText(matrix, Component.literal(value), 26, 29, 1.5f, ColourUtil.WHITE, RenderUtil.TextRenderType.OUTLINED);
		matrix.popPose();
	}

@Override
		public void renderInHud(RenderContext renderContext, AoASkill.Instance skill, float partialTicks, ProgressRenderType progressRenderType, boolean renderLevel) {
			PoseStack poseStack = renderContext.getGuiGraphics().pose();

			poseStack.pushPose();
			poseStack.scale(0.5f, 0.5f, 0);
			RenderSystem.setShaderColor(1, 1, 1, 1);
			RenderSystem.setShader(GameRenderer::getPositionTexShader);

			Font fontRenderer = Minecraft.getInstance().font;
			int renderWidth = hudRenderWidth(skill) * 2;
			int renderHeight = hudRenderHeight(skill) * 2;
			int level = skill.getLevel(true);

			RenderSystem.setShaderTexture(0, SKILL_ICON_BASE);
			RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, 0, 0, 0, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth * 4, renderHeight * 2);
			RenderSystem.setShaderTexture(0, ResourceLocation.fromNamespaceAndPath(RegistryUtil.getId(skill.type()).getNamespace(), "textures/gui/aoaskill/" + RegistryUtil.getId(skill.type()).getPath() + ".png"));
			RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, 0, 0, 0, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth, renderHeight);
			RenderSystem.setShaderTexture(0, SKILL_ICON_BASE);

			if (level == 1000) {
				RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, 0, renderWidth * 3, 0, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth * 4, renderHeight * 2);
			}
			else {
				float percentComplete = PlayerUtil.getLevelProgressPercentage(skill.getLevel(true), skill.getXp()) / 100f;

				RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, 0, renderWidth, 0, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth * 4, renderHeight * 2);

				switch (progressRenderType) {
					case Ring -> RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, renderHeight - percentComplete * renderHeight, renderWidth * 2, renderHeight - percentComplete * renderHeight, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth * 4, renderHeight * 2);
					case Percent -> {
						String percentMessage = NumberUtil.roundToNthDecimalPlace(percentComplete * 100, 0) + "%";
						RenderUtil.renderScaledText(poseStack, Component.literal(percentMessage), (int)(renderWidth - fontRenderer.width(percentMessage) * 1.5f), (int)(renderHeight - fontRenderer.lineHeight * 1.5f), 1.5f, ColourUtil.WHITE, RenderUtil.TextRenderType.OUTLINED);
					}
					case Bar -> {
						RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, renderHeight - 10, 0, 50, 100, 20, renderWidth, 10, renderWidth * 4, renderHeight * 2);
						RenderUtil.renderScaledCustomSizedTexture(poseStack, 0, renderHeight - 10, 0, 70, percentComplete * 100, 20, percentComplete * renderWidth, 10, renderWidth * 4, renderHeight * 2);
					}
					default -> {
					}
				}
			}

			if (renderLevel) {
				RenderUtil.renderScaledText(poseStack, Component.literal(String.valueOf(level)), (int)(renderWidth - fontRenderer.width(String.valueOf(level)) * 1.5f), 1, 1.5f, ColourUtil.WHITE, RenderUtil.TextRenderType.OUTLINED);

				if (skill.getCycles() > 0)
					RenderUtil.renderScaledText(poseStack, Component.literal(String.valueOf(skill.getCycles())), 0, 1, 1.5f, ColourUtil.RGB(252, 170, 0), RenderUtil.TextRenderType.OUTLINED);
			}

			poseStack.popPose();
		}

@Override
	public void renderInHud(PoseStack matrix, AoAResource.Instance resource, float partialTicks, @Nullable String valueOverride) {
		ResourceLocation resourceId = AoARegistries.AOA_RESOURCES.getKey(resource.type());

		matrix.pushPose();
		matrix.scale(0.5f, 0.5f, 0);
		RenderSystem.setShaderColor(1, 1, 1, 1);
		RenderSystem.setShader(GameRenderer::getPositionTexShader);
		RenderSystem.setShaderTexture(0, ResourceLocation.fromNamespaceAndPath(resourceId.getNamespace(), "textures/gui/aoaresource/" + resourceId.getPath() + ".png"));

		int renderWidth = hudRenderWidth(resource) * 2;
		int renderHeight = hudRenderHeight(resource) * 2;
		float currentValue = resource.getCurrentValue();
		String value = String.valueOf((int)currentValue);

		if (valueOverride != null) {
			if (valueOverride.equals("-1")) {
				currentValue = resource.getMaxValue();
				value = "";
			}
			else if (NumberUtils.isParsable(valueOverride)) {
				currentValue = Float.parseFloat(valueOverride);
				value = String.valueOf((int)currentValue);
			}
			else {
				currentValue = resource.getMaxValue();
				value = valueOverride;
			}
		}

		float percentOfMax = (float)Math.floor((Math.min(currentValue, resource.getMaxValue()) / resource.getMaxValue()) * (float)renderWidth);

		RenderUtil.renderScaledCustomSizedTexture(matrix, 0, 0, 0, 0, renderWidth, renderHeight, renderWidth, renderHeight, renderWidth, renderHeight * 3);
		RenderUtil.renderScaledCustomSizedTexture(matrix, 0, 0, 0, percentOfMax == renderWidth ? renderHeight * 2 : renderHeight, percentOfMax, renderHeight, percentOfMax, renderHeight, renderWidth, renderHeight * 3);

		if (((EnergyResource)resource).getCurrentDelay() > 0) {
			RenderUtil.renderCenteredScaledText(matrix, Component.literal(String.valueOf(Mth.ceil(((EnergyResource)resource).getCurrentDelay() / 20f))), 26, 29, 1.5f, ColourUtil.RED, RenderUtil.TextRenderType.OUTLINED);
		}
		else {
			RenderUtil.renderCenteredScaledText(matrix, Component.literal(value), 26, 29, 1.5f, ColourUtil.WHITE, RenderUtil.TextRenderType.OUTLINED);
		}

		matrix.popPose();
	}

@Override
    public boolean spawnAmbientParticle(ClientLevel level, BlockPos pos, Biome biome, EasyRandom random) {
        if (pos.getY() > 125)
            return true;

        if (pos.getY() >= 85) {
            final long gameTick = level.getGameTime();

            if (this.sandstorm != null) {
                if (level.getBrightness(LightLayer.SKY, pos) == 15) {
                    float intensity = this.sandstorm.getIntensity(gameTick);
                    float rotProgress = ((gameTick / 60f) % 360) * Mth.DEG_TO_RAD;
                    Vec3 angle = new Vec3(Math.cos(rotProgress), 0, Math.sin(rotProgress)).scale(Mth.sin(((gameTick / (gameTick % 1000 > 250 ? 20f : 1f)) % 360) * Mth.DEG_TO_RAD) * 0.4f * intensity + 0.9f);

                    ParticleBuilder.forPositions(EntityTrackingParticleOptions.ambient(AoAParticleTypes.SANDSTORM), Vec3.atLowerCornerOf(pos).add(random.nextDouble(), random.nextDouble(), random.nextDouble()))
                            .scaleMod(0.6f * intensity)
                            .lifespan(Mth.ceil(5 / random.valueBetween(0.2f, 1f)))
                            .colourTint(0xC4C0A1)
                            .velocity(angle)
                            .spawnClientParticles(level);
                }
            }
            else if (0.01f * 0.98572f > random.nextFloat()) {
                float rotProgress = ((gameTick / 60f) % 360) * Mth.DEG_TO_RAD;
                Vec3 angle = new Vec3(Math.cos(rotProgress), 0, Math.sin(rotProgress)).scale(Mth.sin(((gameTick / (gameTick % 1000 > 250 ? 20f : 1f)) % 360) * Mth.DEG_TO_RAD) * 0.3f);

                ParticleBuilder.forPositions(EntityTrackingParticleOptions.ambient(AoAParticleTypes.SANDSTORM), Vec3.atLowerCornerOf(pos).add(random.nextDouble(), random.nextDouble(), random.nextDouble()))
                        .scaleMod(0.3f)
                        .lifespan(Mth.ceil(10 / random.valueBetween(0.2f, 1f)))
                        .colourTint(0xC4C0A1)
                        .velocity(angle)
                        .spawnClientParticles(level);
            }
        }
        else if (0.1f * 0.98572f >= random.nextFloat()) {
            ParticleBuilder.forPositions(ParticleTypes.SMOKE, Vec3.atLowerCornerOf(pos).add(random.nextDouble(), random.nextDouble(), random.nextDouble()))
                    .lifespan(Mth.ceil(5 / random.valueBetween(0.2f, 1f)))
                    .velocity(0, 0.05f, 0)
                    .spawnClientParticles(level);
        }

        return true;
    }

@Override
    public boolean renderSky(ClientLevel level, int ticks, float partialTick, Matrix4f frustumMatrix, Camera camera, Matrix4f projectionMatrix, boolean isFoggy, Runnable setupFog) {
        Minecraft mc = Minecraft.getInstance();
        LevelRenderer levelRenderer = mc.levelRenderer;

        setupFog.run();

        FogType screenFogType = camera.getFluidInCamera();

        if (screenFogType != FogType.POWDER_SNOW && screenFogType != FogType.LAVA && !levelRenderer.doesMobEffectBlockSky(camera)) {
            PoseStack poseStack = new PoseStack();

            poseStack.mulPose(frustumMatrix);

            if (mc.level.effects().skyType() == SkyType.END) {
                levelRenderer.renderEndSky(poseStack);
            }
            else if (mc.level.effects().skyType() == SkyType.NORMAL) {
                Vec3 skyColour = level.getSkyColor(mc.gameRenderer.getMainCamera().getPosition(), partialTick);
                Tesselator tesselator = Tesselator.getInstance();
                ShaderInstance shaderInstance = RenderSystem.getShader();
                float rainStrength = 1 - level.getRainLevel(partialTick);
                float[] sunriseColour = level.effects().getSunriseColor(level.getTimeOfDay(partialTick), partialTick);

                FogRenderer.levelFogColor();
                RenderSystem.depthMask(false);
                RenderSystem.setShaderColor((float)skyColour.x, (float)skyColour.y, (float)skyColour.z, 1);

                levelRenderer.skyBuffer.bind();
                levelRenderer.skyBuffer.drawWithShader(poseStack.last().pose(), projectionMatrix, shaderInstance);
                VertexBuffer.unbind();
                RenderSystem.enableBlend();

                if (sunriseColour != null) {
                    RenderSystem.setShader(GameRenderer::getPositionColorShader);
                    RenderSystem.setShaderColor(1, 1, 1, 1);
                    poseStack.pushPose();
                    poseStack.mulPose(Axis.XP.rotationDegrees(90));
                    poseStack.mulPose(Axis.ZP.rotationDegrees(Mth.sin(level.getSunAngle(partialTick)) < 0 ? 180 : 0));
                    poseStack.mulPose(Axis.ZP.rotationDegrees(90));

                    Matrix4f pose = poseStack.last().pose();
                    BufferBuilder buffer = tesselator.begin(VertexFormat.Mode.TRIANGLE_FAN, DefaultVertexFormat.POSITION_COLOR);

                    buffer.addVertex(pose, 0, 100, 0).setColor(sunriseColour[0], sunriseColour[1], sunriseColour[2], sunriseColour[3]);

                    for (int i = 0; i <= 16; i++) {
                        float angle = i * Mth.TWO_PI / 16;
                        float cosine = Mth.cos(angle);

                        buffer.addVertex(pose, Mth.sin(angle) * 120, cosine * 120, -cosine * 40 * sunriseColour[3])
                                .setColor(sunriseColour[0], sunriseColour[1], sunriseColour[2], 0);
                    }

                    BufferUploader.drawWithShader(buffer.buildOrThrow());
                    poseStack.popPose();
                }

                RenderSystem.blendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
                poseStack.pushPose();
                RenderSystem.setShaderColor(1, 1, 1, rainStrength);
                poseStack.mulPose(Axis.YP.rotationDegrees(-90));
                poseStack.mulPose(Axis.XP.rotationDegrees(level.getTimeOfDay(partialTick) * 360));

                Matrix4f pose = poseStack.last().pose();
                float celestialRadius = 65;

                RenderSystem.setShader(GameRenderer::getPositionTexShader);
                RenderSystem.setShaderTexture(0, LevelRenderer.SUN_LOCATION);

                BufferBuilder buffer = tesselator.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);

                buffer.addVertex(pose, -celestialRadius, 100, -celestialRadius).setUv(0, 0);
                buffer.addVertex(pose, celestialRadius, 100, -celestialRadius).setUv(1, 0);
                buffer.addVertex(pose, celestialRadius, 100, celestialRadius).setUv(1, 1);
                buffer.addVertex(pose, -celestialRadius, 100, celestialRadius).setUv(0, 1);
                buffer.addVertex(pose, -celestialRadius + 40, 100 + 55, -celestialRadius + 40).setUv(0, 0);
                buffer.addVertex(pose, celestialRadius + 40, 100 + 55, -celestialRadius + 40).setUv(1, 0);
                buffer.addVertex(pose, celestialRadius + 40, 100 + 55, celestialRadius + 40).setUv(1, 1);
                buffer.addVertex(pose, -celestialRadius + 40, 100 + 55, celestialRadius + 40).setUv(0, 1);
                BufferUploader.drawWithShader(buffer.buildOrThrow());

                if (level.dimensionType().fixedTime().orElse(0) != 2000) {
                    float starBrightness = level.getStarBrightness(partialTick) * rainStrength;
                    int moonPhase = level.getMoonPhase();
                    int uColumn = moonPhase % 4;
                    int vRow = moonPhase / 4 % 2;
                    float uMin = (float)(uColumn) / 4f;
                    float vMin = (float)(vRow) / 2f;
                    float uMax = (float)(uColumn + 1) / 4f;
                    float vMax = (float)(vRow + 1) / 2f;
                    celestialRadius = 20f;
                    buffer = tesselator.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);

                    RenderSystem.setShaderTexture(0, LevelRenderer.MOON_LOCATION);
                    buffer.addVertex(pose, -celestialRadius, -100, celestialRadius).setUv(uMax, vMax);
                    buffer.addVertex(pose, celestialRadius, -100, celestialRadius).setUv(uMin, vMax);
                    buffer.addVertex(pose, celestialRadius, -100, -celestialRadius).setUv(uMin, vMin);
                    buffer.addVertex(pose, -celestialRadius, -100, -celestialRadius).setUv(uMax, vMin);
                    BufferUploader.drawWithShader(buffer.buildOrThrow());

                    if (starBrightness > 0) {
                        RenderSystem.setShaderColor(starBrightness, starBrightness, starBrightness, starBrightness);
                        FogRenderer.setupNoFog();
                        levelRenderer.starBuffer.bind();
                        levelRenderer.starBuffer.drawWithShader(poseStack.last().pose(), projectionMatrix, GameRenderer.getPositionShader());
                        VertexBuffer.unbind();
                        setupFog.run();
                    }

                }

                RenderSystem.setShaderColor(1, 1, 1, 1);
                RenderSystem.disableBlend();
                RenderSystem.defaultBlendFunc();
                poseStack.popPose();
                RenderSystem.setShaderColor(0, 0, 0, 1);

                if (mc.player.getEyePosition(partialTick).y - level.getLevelData().getHorizonHeight(level) < 0) {
                    poseStack.pushPose();
                    poseStack.translate(0, 12, 0);
                    levelRenderer.darkBuffer.bind();
                    levelRenderer.darkBuffer.drawWithShader(poseStack.last().pose(), projectionMatrix, shaderInstance);
                    VertexBuffer.unbind();
                    poseStack.popPose();
                }

                RenderSystem.setShaderColor(1, 1, 1, 1);
                RenderSystem.depthMask(true);
            }
        }

        return true;
    }

@Override
    public boolean renderSky(ClientLevel level, int ticks, float partialTick, Matrix4f frustumMatrix, Camera camera, Matrix4f projectionMatrix, boolean isFoggy, Runnable setupFog) {
        setupFog.run();

        if (!isFoggy) {
            final Minecraft mc = Minecraft.getInstance();
            final LevelRenderer levelRenderer = mc.levelRenderer;
            FogType fogtype = camera.getFluidInCamera();

            if (fogtype != FogType.POWDER_SNOW && fogtype != FogType.LAVA && !levelRenderer.doesMobEffectBlockSky(camera)) {
                PoseStack poseStack = new PoseStack();
                Vec3 skyColour = level.getSkyColor(mc.gameRenderer.getMainCamera().getPosition(), partialTick);
                float skyColourRed = (float)skyColour.x;
                float skyColourGreen = (float)skyColour.y;
                float skyColourBlue = (float)skyColour.z;
                Tesselator tesselator = Tesselator.getInstance();
                BufferBuilder bufferBuilder;
                ShaderInstance shader = RenderSystem.getShader();

                poseStack.mulPose(projectionMatrix);
                FogRenderer.levelFogColor();
                RenderSystem.depthMask(false);
                RenderSystem.setShaderColor(skyColourRed, skyColourGreen, skyColourBlue, 1);

                levelRenderer.skyBuffer.bind();
                levelRenderer.skyBuffer.drawWithShader(frustumMatrix, projectionMatrix, shader);
                VertexBuffer.unbind();
                RenderSystem.enableBlend();

                float[] sunriseColour = level.effects().getSunriseColor(level.getTimeOfDay(partialTick), partialTick);

                if (sunriseColour != null) {
                    RenderSystem.setShader(GameRenderer::getPositionColorShader);
                    RenderUtil.resetShaderColour();
                    poseStack.pushPose();
                    poseStack.mulPose(Axis.XP.rotationDegrees(90));
                    float sunAngle = Mth.sin(level.getSunAngle(partialTick)) < 0 ? 180 : 0;
                    poseStack.mulPose(Axis.ZP.rotationDegrees(sunAngle));
                    poseStack.mulPose(Axis.ZP.rotationDegrees(90));
                    float sunriseRed = sunriseColour[0];
                    float sunriseGreen = sunriseColour[1];
                    float sunriseBlue = sunriseColour[2];
                    Matrix4f pose = poseStack.last().pose();
                    bufferBuilder = tesselator.begin(VertexFormat.Mode.TRIANGLE_FAN, DefaultVertexFormat.POSITION_COLOR);
                    bufferBuilder.addVertex(pose, 0, 100, 0).setColor(sunriseRed, sunriseGreen, sunriseBlue, sunriseColour[3]);

                    for (int section = 0; section <= 16; ++section) {
                        float sectionAngle = (float)section * (float) (Math.PI * 2) / 16.0F;
                        float angleX = Mth.sin(sectionAngle);
                        float angleZ = Mth.cos(sectionAngle);
                        bufferBuilder.addVertex(pose, angleX * 120, angleZ * 120, -angleZ * 40 * sunriseColour[3])
                                .setColor(sunriseColour[0], sunriseColour[1], sunriseColour[2], 0);
                    }

                    BufferUploader.drawWithShader(bufferBuilder.buildOrThrow());
                    poseStack.popPose();
                }

                RenderSystem.blendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
                poseStack.pushPose();

                float rainAmount = 1 - level.getRainLevel(partialTick);
                float dayAngle = level.getTimeOfDay(partialTick) * 360;
                float celestialQuadRadius = 30;

                RenderSystem.setShaderColor(1, 1, 1, rainAmount);
                poseStack.mulPose(Axis.YP.rotationDegrees(-90));
                poseStack.mulPose(Axis.XP.rotationDegrees(dayAngle));
                Matrix4f pose = poseStack.last().pose();
                RenderSystem.setShader(GameRenderer::getPositionTexShader);

                if (dayAngle > 286 || dayAngle < 82) {
                    RenderSystem.setShaderTexture(0, SUN_TEXTURE);
                    bufferBuilder = tesselator.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
                    bufferBuilder.addVertex(pose, -celestialQuadRadius, 100, -celestialQuadRadius).setUv(0, 0);
                    bufferBuilder.addVertex(pose, celestialQuadRadius, 100, -celestialQuadRadius).setUv(1, 0);
                    bufferBuilder.addVertex(pose, celestialQuadRadius, 100, celestialQuadRadius).setUv(1, 1);
                    bufferBuilder.addVertex(pose, -celestialQuadRadius, 100, celestialQuadRadius).setUv(0, 1);
                    BufferUploader.drawWithShader(bufferBuilder.buildOrThrow());
                }

                if (dayAngle > 101 && dayAngle < 258) {
                    celestialQuadRadius = 20;
                    int moonPhaseIndex = level.getMoonPhase();
                    int phaseRow = moonPhaseIndex % 4;
                    int phaseColumn = moonPhaseIndex / 4 % 2;
                    float uMin = phaseRow / 4f;
                    float vMin = phaseColumn / 2f;
                    float uMax = (phaseRow + 1) / 4f;
                    float vMax = (phaseColumn + 1) / 2f;

                    RenderSystem.setShaderTexture(0, MOON_TEXTURE);
                    bufferBuilder = tesselator.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
                    bufferBuilder.addVertex(pose, -celestialQuadRadius, -100, celestialQuadRadius).setUv(uMax, vMax);
                    bufferBuilder.addVertex(pose, celestialQuadRadius, -100, celestialQuadRadius).setUv(uMin, vMax);
                    bufferBuilder.addVertex(pose, celestialQuadRadius, -100, -celestialQuadRadius).setUv(uMin, vMin);
                    bufferBuilder.addVertex(pose, -celestialQuadRadius, -100, -celestialQuadRadius).setUv(uMax, vMin);
                    BufferUploader.drawWithShader(bufferBuilder.buildOrThrow());
                }

                float starBrightness = level.getStarBrightness(partialTick) * rainAmount;

                if (starBrightness > 0) {
                    RenderSystem.setShaderColor(starBrightness, starBrightness, starBrightness, starBrightness);
                    FogRenderer.setupNoFog();
                    levelRenderer.starBuffer.bind();
                    levelRenderer.starBuffer.drawWithShader(poseStack.last().pose(), projectionMatrix, GameRenderer.getPositionShader());
                    VertexBuffer.unbind();
                    setupFog.run();
                }

                RenderUtil.resetShaderColour();
                RenderSystem.disableBlend();
                RenderSystem.defaultBlendFunc();
                poseStack.popPose();
                RenderSystem.setShaderColor(0, 0, 0, 1);
                double darknessDepth = mc.player.getEyePosition(partialTick).y - level.getLevelData().getHorizonHeight(level);

                if (darknessDepth < 0.0) {
                    poseStack.pushPose();
                    poseStack.translate(0, 12, 0);
                    levelRenderer.darkBuffer.bind();
                    levelRenderer.darkBuffer.drawWithShader(poseStack.last().pose(), projectionMatrix, shader);
                    VertexBuffer.unbind();
                    poseStack.popPose();
                }

                RenderUtil.resetShaderColour();
                RenderSystem.depthMask(true);
            }
        }

        return true;
    }

@Override
    public boolean renderSky(ClientLevel level, int ticks, float partialTick, Matrix4f frustumMatrix, Camera camera, Matrix4f projectionMatrix, boolean isFoggy, Runnable setupFog) {
        PoseStack poseStack = new PoseStack();
        Tesselator tesellator = Tesselator.getInstance();

        poseStack.mulPose(frustumMatrix);
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();
        RenderSystem.depthMask(false);
        RenderUtil.prepRenderTexture(TEXTURE);

        for (int i = 0; i < 6; ++i) {
            poseStack.pushPose();

            switch (i) {
                case 1 -> poseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
                case 2 -> poseStack.mulPose(Axis.XP.rotationDegrees(-90.0F));
                case 3 -> poseStack.mulPose(Axis.XP.rotationDegrees(180.0F));
                case 4 -> poseStack.mulPose(Axis.ZP.rotationDegrees(90.0F));
                case 5 -> poseStack.mulPose(Axis.ZP.rotationDegrees(-90.0F));
                default -> {}
            }

            Matrix4f pose = poseStack.last().pose();
            BufferBuilder buffer = tesellator.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX_COLOR);

            buffer.addVertex(pose, -100, -100, -100).setUv(0.0F, 0.0F).setColor(150, 150, 150, 255);
            buffer.addVertex(pose, -100, -100, 100).setUv(0.0F, 1).setColor(150, 150, 150, 255);
            buffer.addVertex(pose, 100, -100, 100).setUv(1, 1).setColor(150, 150, 150, 255);
            buffer.addVertex(pose, 100, -100, -100).setUv(1, 0.0F).setColor(150, 150, 150, 255);
            BufferUploader.drawWithShader(buffer.buildOrThrow());
            poseStack.popPose();
        }

        RenderSystem.depthMask(true);
        RenderSystem.disableBlend();

        return true;
    }

@Override
	public void emitBlockQuads(BlockAndTintGetter blockView, BlockState state, BlockPos pos, Supplier<RandomSource> randomSupplier, RenderContext context) {
		if (!(state.getBlock() instanceof PlatformBlock)) {
			Minecraft.getInstance().getBlockRenderer().getBlockModelShaper().getModelManager().getMissingModel()
					.emitBlockQuads(blockView, state, pos, randomSupplier, context);
			return;
		}

		Object data = blockView.getBlockEntityRenderData(pos);
		if (data instanceof PlatformBlockEntity.PlatformData) {
			BlockPos heldPos = ((PlatformBlockEntity.PlatformData) data).pos();
			BlockState heldState = ((PlatformBlockEntity.PlatformData) data).state();

			if (heldState == null || heldState.is(BotaniaTags.Blocks.UNSUPPORTED_PLATFORM_DISGUISE)) {
				// No camo
				super.emitBlockQuads(blockView, state, pos, randomSupplier, context);
			} else {
				BakedModel model = Minecraft.getInstance().getBlockRenderer()
						.getBlockModelShaper().getBlockModel(heldState);
				// Steal camo's model
				model.emitBlockQuads(blockView, heldState, heldPos, randomSupplier, context);
			}
		}
	}

@NotNull
	@Override
	public ChunkRenderTypeSet getRenderTypes(@NotNull BlockState state, @NotNull RandomSource rand, @NotNull ModelData extraData) {
		var data = extraData.get(PROPERTY);
		if (!(state.getBlock() instanceof PlatformBlock) || data == null) {
			return Minecraft.getInstance().getBlockRenderer().getBlockModelShaper()
					.getModelManager().getMissingModel().getRenderTypes(state, rand, extraData);
		}

		BlockState heldState = data.state();
		if (heldState == null) {
			return super.getRenderTypes(state, rand, extraData);
		} else {
			BakedModel model = Minecraft.getInstance().getBlockRenderer().getBlockModelShaper().getBlockModel(heldState);
			return model.getRenderTypes(heldState, rand, ModelData.EMPTY);
		}
	}

private static void drawHealthBar(GuiGraphics gui, GaiaGuardianEntity currentBoss, int x, int y, int u, int v, int w, int h, boolean bg) {
		var shader = CoreShaders.dopplegangerBar();
		if (shader != null) {
			float time = currentBoss.getInvulTime();
			float grainIntensity = time > 20 ? 1F : Math.max(currentBoss.isHardMode() ? 0.5F : 0F, time / 20F);
			shader.safeGetUniform("BotaniaGrainIntensity").set(grainIntensity);
			shader.safeGetUniform("BotaniaHpFract").set(currentBoss.getHealth() / currentBoss.getMaxHealth());
		}

		float minU = u / 256.0F;
		float maxU = (u + w) / 256.0F;
		float minV = v / 256.0F;
		float maxV = (v + h) / 256.0F;

		var matrix = gui.pose().last().pose();
		RenderSystem.setShader(CoreShaders::dopplegangerBar);
		BufferBuilder builder = Tesselator.getInstance().getBuilder();
		builder.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
		builder.vertex(matrix, x, y + h, 0).uv(minU, maxV).endVertex();
		builder.vertex(matrix, x + w, y + h, 0).uv(maxU, maxV).endVertex();
		builder.vertex(matrix, x + w, y, 0).uv(maxU, minV).endVertex();
		builder.vertex(matrix, x, y, 0).uv(minU, minV).endVertex();
		Tesselator.getInstance().end();
	}

