private static void renderBlockAt(PoseStack ms, VertexConsumer buffer, BlockState state, BlockPos pos) {
		double renderPosX = Minecraft.getInstance().getEntityRenderDispatcher().camera.getPosition().x();
		double renderPosY = Minecraft.getInstance().getEntityRenderDispatcher().camera.getPosition().y();
		double renderPosZ = Minecraft.getInstance().getEntityRenderDispatcher().camera.getPosition().z();

		ms.pushPose();
		ms.translate(-renderPosX, -renderPosY, -renderPosZ);

		BlockRenderDispatcher brd = Minecraft.getInstance().getBlockRenderer();
		ms.translate(pos.getX(), pos.getY(), pos.getZ());
		BakedModel model = brd.getBlockModel(state);
		int color = Minecraft.getInstance().getBlockColors().getColor(state, null, null, 0);
		float r = (float) (color >> 16 & 255) / 255.0F;
		float g = (float) (color >> 8 & 255) / 255.0F;
		float b = (float) (color & 255) / 255.0F;
		// always use entity translucent layer so blending is turned on
		brd.getModelRenderer().renderModel(ms.last(), buffer, state, model, r, g, b, 0xF000F0, OverlayTexture.NO_OVERLAY);

		ms.popPose();
	}

public static void onWorldRenderLast(Camera camera, PoseStack ms, Level level) {
		Player player = Minecraft.getInstance().player;
		if (!BotaniaConfig.client().boundBlockWireframe()
				|| player == null
				|| player.level() != level) {
			return;
		}

		ms.pushPose();

		int color = 0xFF000000 | Mth.hsvToRgb(ClientTickHandler.ticksInGame % 200 / 200F, 0.6F, 1F);

		if (!player.getMainHandItem().isEmpty()) {
			var coordBoundItem = XplatAbstractions.INSTANCE.findCoordBoundItem(player.getMainHandItem());
			if (coordBoundItem != null) {
				BlockPos coords = coordBoundItem.getBinding(player.level());
				if (coords != null) {
					renderBlockOutlineAt(camera, ms, LINE_BUFFERS, player.level(), coords, color);
				}
			}
		}

		if (!player.getOffhandItem().isEmpty()) {
			var coordBoundItem = XplatAbstractions.INSTANCE.findCoordBoundItem(player.getOffhandItem());
			if (coordBoundItem != null) {
				BlockPos coords = coordBoundItem.getBinding(player.level());
				if (coords != null) {
					renderBlockOutlineAt(camera, ms, LINE_BUFFERS, player.level(), coords, color);
				}
			}
		}

		renderWireframeProviders(camera, player.getInventory(), player, ms, color);
		renderWireframeProviders(camera, BotaniaAPI.instance().getAccessoriesInventory(player), player, ms, color);

		ms.popPose();
		RenderSystem.disableDepthTest();
		LINE_BUFFERS.endBatch();
	}

public static void renderExtra(PoseStack ms, ClientLevel world, float partialTicks, float insideVoid) {
		// Botania - Begin extra stuff
		Tesselator tessellator = Tesselator.getInstance();
		float rain = 1.0F - world.getRainLevel(partialTicks);
		float celAng = world.getTimeOfDay(partialTicks);
		float effCelAng = celAng;
		if (celAng > 0.5) {
			effCelAng = 0.5F - (celAng - 0.5F);
		}

		// === Planets
		float scale = 20F;
		float lowA = Math.max(0F, effCelAng - 0.3F) * rain;
		float a = Math.max(0.1F, lowA);

		RenderSystem.blendFuncSeparate(770, 771, 1, 0);
		ms.pushPose();
		RenderSystem.setShaderColor(1F, 1F, 1F, a * 4 * (1F - insideVoid));
		ms.mulPose(new Quaternionf().rotateAxis(VecHelper.toRadians(90), 0.5F, 0.5F, 0F));
		for (int p = 0; p < planetTextures.length; p++) {
			RenderSystem.setShader(GameRenderer::getPositionTexShader);
			RenderSystem.setShaderTexture(0, planetTextures[p]);
			Matrix4f mat = ms.last().pose();
			tessellator.getBuilder().begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
			tessellator.getBuilder().vertex(mat, -scale, 100, -scale).uv(0.0F, 0.0F).endVertex();
			tessellator.getBuilder().vertex(mat, scale, 100, -scale).uv(1.0F, 0.0F).endVertex();
			tessellator.getBuilder().vertex(mat, scale, 100, scale).uv(1.0F, 1.0F).endVertex();
			tessellator.getBuilder().vertex(mat, -scale, 100, scale).uv(0.0F, 1.0F).endVertex();
			tessellator.end();

			switch (p) {
				case 0 -> {
					ms.mulPose(VecHelper.rotateX(70));
					scale = 12F;
				}
				case 1 -> {
					ms.mulPose(VecHelper.rotateZ(120));
					scale = 15F;
				}
				case 2 -> {
					ms.mulPose(new Quaternionf().rotateAxis(VecHelper.toRadians(80), 1, 0, 1));
					scale = 25F;
				}
				case 3 -> {
					ms.mulPose(VecHelper.rotateZ(100));
					scale = 10F;
				}
				case 4 -> {
					ms.mulPose(new Quaternionf().rotateAxis(VecHelper.toRadians(-60), 1, 0, 0.5F));
					scale = 40F;
				}
			}
		}
		RenderSystem.setShaderColor(1F, 1F, 1F, 1F);
		ms.popPose();

		// === Rays
		RenderSystem.setShaderTexture(0, textureSkybox);

		scale = 20F;
		a = lowA;
		ms.pushPose();
		RenderSystem.blendFuncSeparate(770, 1, 1, 0);
		ms.translate(0, -1, 0);
		ms.mulPose(VecHelper.rotateX(220));
		RenderSystem.setShaderColor(1F, 1F, 1F, a);
		int angles = 90;
		float y = 2F;
		float y0 = 0F;
		float uPer = 1F / 360F;
		float anglePer = 360F / angles;
		double fuzzPer = Math.PI * 10 / angles;
		float rotSpeed = 1F;
		float rotSpeedMod = 0.4F;

		for (int p = 0; p < 3; p++) {
			float baseAngle = rotSpeed * rotSpeedMod * (ClientTickHandler.ticksInGame + ClientTickHandler.partialTicks);
			ms.mulPose(VecHelper.rotateY((ClientTickHandler.ticksInGame + ClientTickHandler.partialTicks) * 0.25F * rotSpeed * rotSpeedMod));

			Matrix4f mat = ms.last().pose();
			tessellator.getBuilder().begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
			for (int i = 0; i < angles; i++) {
				int j = i;
				if (i % 2 == 0) {
					j--;
				}

				float ang = j * anglePer + baseAngle;
				float xp = (float) Math.cos(ang * Math.PI / 180F) * scale;
				float zp = (float) Math.sin(ang * Math.PI / 180F) * scale;
				float yo = (float) Math.sin(fuzzPer * j) * 1;

				float ut = ang * uPer;
				if (i % 2 == 0) {
					tessellator.getBuilder().vertex(mat, xp, yo + y0 + y, zp).uv(ut, 1F).endVertex();
					tessellator.getBuilder().vertex(mat, xp, yo + y0, zp).uv(ut, 0).endVertex();
				} else {
					tessellator.getBuilder().vertex(mat, xp, yo + y0, zp).uv(ut, 0).endVertex();
					tessellator.getBuilder().vertex(mat, xp, yo + y0 + y, zp).uv(ut, 1F).endVertex();
				}

			}
			tessellator.end();

			switch (p) {
				case 0 -> {
					ms.mulPose(VecHelper.rotateX(20));
					RenderSystem.setShaderColor(1F, 0.4F, 0.4F, a);
					fuzzPer = Math.PI * 14 / angles;
					rotSpeed = 0.2F;
				}
				case 1 -> {
					ms.mulPose(VecHelper.rotateX(50));
					RenderSystem.setShaderColor(0.4F, 1F, 0.7F, a);
					fuzzPer = Math.PI * 6 / angles;
					rotSpeed = 2F;
				}
			}
		}
		ms.popPose();

		// === Rainbow
		ms.pushPose();
		GlStateManager._blendFuncSeparate(770, 771, 1, 0);
		RenderSystem.setShaderTexture(0, textureRainbow);
		scale = 10F;
		float effCelAng1 = celAng;
		if (effCelAng1 > 0.25F) {
			effCelAng1 = 1F - effCelAng1;
		}
		effCelAng1 = 0.25F - Math.min(0.25F, effCelAng1);

		long time = world.getDayTime() + 1000;
		int day = (int) (time / 24000L);
		Random rand = new Random(day * 0xFF);
		float angle1 = rand.nextFloat() * 360F;
		float angle2 = rand.nextFloat() * 360F;
		RenderSystem.setShaderColor(1F, 1F, 1F, effCelAng1 * (1F - insideVoid));
		ms.mulPose(VecHelper.rotateY(angle1));
		ms.mulPose(VecHelper.rotateZ(angle2));

		Matrix4f mat = ms.last().pose();
		tessellator.getBuilder().begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
		for (int i = 0; i < angles; i++) {
			int j = i;
			if (i % 2 == 0) {
				j--;
			}

			float ang = j * anglePer;
			float xp = (float) Math.cos(ang * Math.PI / 180F) * scale;
			float zp = (float) Math.sin(ang * Math.PI / 180F) * scale;
			float yo = 0;

			float ut = ang * uPer;
			if (i % 2 == 0) {
				tessellator.getBuilder().vertex(mat, xp, yo + y0 + y, zp).uv(ut, 1F).endVertex();
				tessellator.getBuilder().vertex(mat, xp, yo + y0, zp).uv(ut, 0).endVertex();
			} else {
				tessellator.getBuilder().vertex(mat, xp, yo + y0, zp).uv(ut, 0).endVertex();
				tessellator.getBuilder().vertex(mat, xp, yo + y0 + y, zp).uv(ut, 1F).endVertex();
			}

		}
		tessellator.end();
		ms.popPose();
		RenderSystem.setShaderColor(1F, 1F, 1F, 1F - insideVoid);
		GlStateManager._blendFuncSeparate(770, 1, 1, 0);
	}

public static void renderStars(VertexBuffer starVBO, PoseStack ms, Matrix4f projMat, float partialTicks, Runnable resetFog) {
		FogRenderer.setupNoFog();
		Minecraft mc = Minecraft.getInstance();
		ShaderInstance shader = GameRenderer.getPositionShader();
		float rain = 1.0F - mc.level.getRainLevel(partialTicks);
		float celAng = mc.level.getTimeOfDay(partialTicks);
		float effCelAng = celAng;
		if (celAng > 0.5) {
			effCelAng = 0.5F - (celAng - 0.5F);
		}
		float alpha = rain * Math.max(0.1F, effCelAng * 2);

		float t = (ClientTickHandler.ticksInGame + partialTicks + 2000) * 0.005F;
		ms.pushPose();
		starVBO.bind();

		ms.pushPose();
		ms.mulPose(VecHelper.rotateY(t * 3));
		RenderSystem.setShaderColor(1F, 1F, 1F, alpha);
		starVBO.drawWithShader(ms.last().pose(), projMat, shader);
		ms.popPose();

		ms.pushPose();
		ms.mulPose(VecHelper.rotateY(t));
		RenderSystem.setShaderColor(0.5F, 1F, 1F, alpha);
		starVBO.drawWithShader(ms.last().pose(), projMat, shader);
		ms.popPose();

		ms.pushPose();
		ms.mulPose(VecHelper.rotateY(t * 2));
		RenderSystem.setShaderColor(1F, 0.75F, 0.75F, alpha);
		starVBO.drawWithShader(ms.last().pose(), projMat, shader);
		ms.popPose();

		ms.pushPose();
		ms.mulPose(VecHelper.rotateZ(t * 3));
		RenderSystem.setShaderColor(1F, 1F, 1F, 0.25F * alpha);
		starVBO.drawWithShader(ms.last().pose(), projMat, shader);
		ms.popPose();

		ms.pushPose();
		ms.mulPose(VecHelper.rotateZ(t));
		RenderSystem.setShaderColor(0.5F, 1F, 1F, 0.25F * alpha);
		starVBO.drawWithShader(ms.last().pose(), projMat, shader);
		ms.popPose();

		ms.pushPose();
		ms.mulPose(VecHelper.rotateZ(t * 2));
		RenderSystem.setShaderColor(1F, 0.75F, 0.75F, 0.25F * alpha);
		starVBO.drawWithShader(ms.last().pose(), projMat, shader);
		ms.popPose();

		ms.popPose();
		VertexBuffer.unbind();
		resetFog.run();
	}

@Override
	public void render(MagnetizedBlockBlockEntity tileEntityIn, float partialTicks, @NotNull PoseStack matrixStackIn, @NotNull MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
		Level world = tileEntityIn.getLevel();
		if(world != null) {
			BlockPos truepos = tileEntityIn.getBlockPos();
			BlockPos blockpos = truepos.relative(tileEntityIn.getFacing().getOpposite());
			BlockState blockstate = tileEntityIn.getMagnetState();
			if(!blockstate.isAir() && (tileEntityIn.getProgress(partialTicks) <= 1.0F)) {
				BlockEntity subTile = tileEntityIn.getSubTile(tileEntityIn.getBlockPos());
				Vec3 offset = new Vec3(tileEntityIn.getOffsetX(partialTicks), tileEntityIn.getOffsetY(partialTicks), tileEntityIn.getOffsetZ(partialTicks));
				if(QuarkPistonBlockEntityRenderer.renderTESafely(world, truepos, blockstate, subTile, tileEntityIn, partialTicks, offset, matrixStackIn, bufferIn, combinedLightIn, combinedOverlayIn))
					return;

				ModelBlockRenderer.enableCaching();
				matrixStackIn.pushPose();
				matrixStackIn.translate(offset.x, offset.y, offset.z);
				if(blockstate.getBlock() == Blocks.PISTON_HEAD && tileEntityIn.getProgress(partialTicks) <= 4.0F) {
					blockstate = blockstate.setValue(PistonHeadBlock.SHORT, Boolean.TRUE);
					renderStateModel(blockpos, blockstate, matrixStackIn, bufferIn, world, false, combinedOverlayIn);
				} else {
					renderStateModel(blockpos, blockstate, matrixStackIn, bufferIn, world, false, combinedOverlayIn);
				}

				matrixStackIn.popPose();
				ModelBlockRenderer.clearCache();
			}
		}
	}

private void renderItem(ItemStack item, float time, float bookOpen, float rot, PoseStack matrix, MultiBufferSource buffer, int light, int overlay, Level level, MatrixEnchantingTableBlockEntity tileEntityIn) {
		matrix.pushPose();
		matrix.translate(0.5F, 0.8F, 0.5F);
		matrix.scale(0.6F, 0.6F, 0.6F);

		rot *= -180F / (float) Math.PI;
		rot -= 90F;
		rot *= bookOpen;

		matrix.mulPose(Axis.YP.rotationDegrees(Mth.wrapDegrees(rot)));
		matrix.translate(0, bookOpen * 1.4F, Math.sin(bookOpen * Math.PI));
		matrix.mulPose(Axis.XP.rotationDegrees(-90F * (bookOpen - 1F)));

		float trans = (float) Math.sin(time * 0.06) * bookOpen * 0.2F;
		matrix.translate(0F, trans, 0F);

		ItemRenderer render = Minecraft.getInstance().getItemRenderer();
		render.renderStatic(item, ItemDisplayContext.FIXED, light, overlay, matrix, buffer, level, 0);
		matrix.popPose();
	}

private void renderBook(MatrixEnchantingTableBlockEntity be, float time, float bookRot, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay) {
        poseStack.pushPose();
		poseStack.translate(0.5D, 0.75D, 0.5D);
		float f = time + partialTicks;
		poseStack.translate(0.0D, 0.1F + Mth.sin(f * 0.1F) * 0.01F, 0.0D);

		float rotationDiff = be.bookRotation - be.bookRotationPrev;

        rotationDiff = RotationHelper.wrapRadians(rotationDiff);

		float f2 = be.bookRotationPrev + rotationDiff * partialTicks;
		poseStack.mulPose(Axis.YP.rotation(-f2));
		poseStack.mulPose(Axis.ZP.rotationDegrees(80.0F));
		float f3 = Mth.lerp(partialTicks, be.pageFlipPrev, be.pageFlip);
		float f4 = Mth.frac(f3 + 0.25F) * 1.6F - 0.3F;
		float f5 = Mth.frac(f3 + 0.75F) * 1.6F - 0.3F;
		float f6 = Mth.lerp(partialTicks, be.bookSpreadPrev, be.bookSpread);

		this.modelBook.setupAnim(f, Mth.clamp(f4, 0.0F, 1.0F), Mth.clamp(f5, 0.0F, 1.0F), f6);
		VertexConsumer ivertexbuilder = TEXTURE_BOOK.buffer(bufferSource, RenderType::entitySolid);
		this.modelBook.render(poseStack, ivertexbuilder, packedLight, packedOverlay, -1);
		poseStack.popPose();
	}

@Override
	public void render(PipeBlockEntity te, float partialTicks, PoseStack matrix, @NotNull MultiBufferSource buffer, int light, int overlay) {
		matrix.pushPose();
		matrix.translate(0.5, 0.5, 0.5);
		ItemRenderer render = Minecraft.getInstance().getItemRenderer();
		Iterator<PipeItem> items = te.getItemIterator();

		if(PipesModule.renderPipeItems)
			while(items.hasNext())
				renderItem(items.next(), render, matrix, buffer, partialTicks, light, overlay, te.getLevel());

		BlockRenderDispatcher blockrendererdispatcher = Minecraft.getInstance().getBlockRenderer();
		ModelManager modelmanager = blockrendererdispatcher.getBlockModelShaper().getModelManager();
		BakedModel model = modelmanager.getModel(LOCATION_MODEL);
		for(Direction d : Direction.values())
			renderFlare(te, blockrendererdispatcher, model, matrix, buffer, partialTicks, light, overlay, d);

		matrix.popPose();
	}

private void renderFlare(PipeBlockEntity te, BlockRenderDispatcher disp, BakedModel model, PoseStack matrix, MultiBufferSource buffer, float partial, int light, int overlay, Direction dir) {
		ConnectionType type = te.getConnectionTo(dir);
		if(type.isFlared) {
			matrix.pushPose();
			switch(dir.getAxis()) {
			case X -> matrix.mulPose(Axis.YP.rotationDegrees(-dir.toYRot()));
			case Z -> matrix.mulPose(Axis.YP.rotationDegrees(dir.toYRot()));
			case Y -> {
				matrix.mulPose(Axis.XP.rotationDegrees(90F));
				if(dir == Direction.UP)
					matrix.mulPose(Axis.YP.rotationDegrees(180F));
			}
			}

			matrix.translate(-0.5, -0.5, type.getFlareShift(te));
			disp.getModelRenderer().renderModel(matrix.last(), buffer.getBuffer(Sheets.cutoutBlockSheet()), null, model, 1.0F, 1.0F, 1.0F, light, OverlayTexture.NO_OVERLAY);
			matrix.popPose();
		}
	}

private void renderItem(PipeItem item, ItemRenderer render, PoseStack matrix, MultiBufferSource buffer, float partial, int light, int overlay, Level level) {
		matrix.pushPose();

		boolean taterFlag = item.stack.getItem().equals(TinyPotatoModule.tiny_potato.asItem());

		float scale = 0.4F;
		float fract = item.getTimeFract(partial);
		float shiftFract = fract - 0.5F;
		Direction face = item.outgoingFace;
		if(fract < 0.5)
			face = item.incomingFace.getOpposite();

		float offX = (face.getStepX() * 1F);
		float offY = (face.getStepY() * 1F);
		float offZ = (face.getStepZ() * 1F);
		matrix.translate(offX * shiftFract, offY * shiftFract, offZ * shiftFract);

		if (taterFlag) {
			matrix.translate(0, 0.225, 0);
			scale = 0.5f;
		}
		matrix.scale(scale, scale, scale);

		float speed = 4F;
		matrix.mulPose(Axis.YP.rotationDegrees((item.timeInWorld + partial) * speed));

		int seed = item.stack.isEmpty() ? 187 : Item.getId(item.stack.getItem());
		random.setSeed(seed);

		int count = getModelCount(item.stack);
		for(int i = 0; i < count; i++) {
			matrix.pushPose();
			if(i > 0) {
				float spread = 0.15F;
				float x = (this.random.nextFloat() * 2.0F - 1.0F) * spread;
				float y = (this.random.nextFloat() * 2.0F - 1.0F) * spread;
				float z = (this.random.nextFloat() * 2.0F - 1.0F) * spread;
				matrix.translate(x, y, z);
			}

			render.renderStatic(item.stack, ItemDisplayContext.FIXED, light, overlay, matrix, buffer, level, 0);
			matrix.popPose();
		}
		matrix.popPose();
	}

@Override
	public void render(@NotNull TinyPotatoBlockEntity potato, float partialTicks, @NotNull PoseStack poseStack, @NotNull MultiBufferSource buffers, int light, int overlay) {
		poseStack.pushPose();

		TinyPotatoInfo info = TinyPotatoInfo.fromComponent(potato.name);
		RenderType layer = Sheets.translucentCullBlockSheet();
		BakedModel model = getModel(info.name(), potato.angry);

		poseStack.translate(0.5F, 0F, 0.5F);
		Direction potatoFacing = potato.getBlockState().getValue(BlockStateProperties.HORIZONTAL_FACING);
		float rotY = 0;
		switch (potatoFacing) {
			default:
			case SOUTH:
				rotY = 180F;
				break;
			case NORTH:
				break;
			case EAST:
				rotY = 90F;
				break;
			case WEST:
				rotY = 270F;
				break;
		}
		poseStack.mulPose(com.mojang.math.Axis.YN.rotationDegrees(rotY));
        if (potato.isActuallyAnItem) poseStack.mulPose(com.mojang.math.Axis.YN.rotationDegrees(180));

		float jump = potato.jumpTicks;
		if(jump > 0) {
			jump -= partialTicks;
		}

		float up = (float) Math.abs(Math.sin(jump / 10 * Math.PI)) * 0.2F;
		float rotZ = (float) Math.sin(jump / 10 * Math.PI) * 2;
		float wiggle = (float) Math.sin(jump / 10 * Math.PI) * 0.05F;

		poseStack.translate(wiggle, up, 0F);
		poseStack.mulPose(com.mojang.math.Axis.ZP.rotationDegrees(rotZ));

		boolean render = !(info.name().equals("mami") || info.name().equals("soaryn") || info.name().equals("eloraam") && jump != 0);
		if(render) {
			poseStack.pushPose();
			poseStack.translate(-0.5F, 0, -0.5F);
			RuneColor runeColor = info.runeColor();
			if(runeColor != null)
				ColorRunesModule.setTargetColor(runeColor);

			VertexConsumer buffer = ItemRenderer.getFoilBuffer(buffers, layer, true, info.enchanted());

			renderModel(poseStack, buffer, light, overlay, model);
			poseStack.popPose();
		}

		poseStack.translate(0F, 1.5F, 0F);
		poseStack.pushPose();
		poseStack.mulPose(com.mojang.math.Axis.ZP.rotationDegrees(180F));
		renderItems(potato, potatoFacing, poseStack, buffers, light, overlay);
		poseStack.popPose();

		poseStack.mulPose(com.mojang.math.Axis.ZP.rotationDegrees(-rotZ));
		poseStack.mulPose(com.mojang.math.Axis.YN.rotationDegrees(-rotY));

		renderName(potato, info.name(), poseStack, buffers, light);
		poseStack.popPose();
	}

private void renderItems(TinyPotatoBlockEntity potato, Direction facing, PoseStack ms, MultiBufferSource buffers, int light, int overlay) {
		ms.pushPose();
		ms.mulPose(com.mojang.math.Axis.ZP.rotationDegrees(180F));
		ms.translate(0F, -1F, 0F);
		float s = 1F / 3.5F;
		ms.scale(s, s, s);

		for(int i = 0; i < potato.getContainerSize(); i++) {
			ItemStack stack = potato.getItem(i);
			if(stack.isEmpty()) {
				continue;
			}

			ms.pushPose();
			Direction side = Direction.values()[i];
			if(side.getAxis() != Axis.Y) {
				float sideAngle = side.toYRot() - facing.toYRot();
				side = Direction.fromYRot(sideAngle);
			}

			boolean block = stack.getItem() instanceof BlockItem;
			boolean mySon = stack.getItem() == TinyPotatoModule.tiny_potato.asItem();

			switch(side) {
			case UP -> {
				if(mySon) {
					ms.translate(0F, -0.375F, 0.5F);
				} else if(block) {
					ms.translate(0F, 0.3F, 0.5F);
				}
				ms.translate(0F, -0.5F, -0.4F);
			}
			case DOWN -> {
				ms.translate(0, -2.3F, -0.88F);
				if(mySon) {
					ms.translate(0, 1.25F, 0.5F);
				} else if(block) {
					ms.translate(0, 1, 0.6F);
				}
			}
			case NORTH -> {
				ms.translate(0, -1.9F, 0.02F);
				if(mySon) {
					ms.translate(0, -0.29F, 0.6F);
				} else if(block) {
					ms.translate(0, 1, 0.6F);
				}
			}
			case SOUTH -> {
				ms.translate(0, -1.6F, -0.89F);
				if(mySon) {
					ms.translate(0, -0.59F, 0.26F);
				} else if(block) {
					ms.translate(0, 1.0F, 0.5F);
				}
			}
			case EAST -> {
				if(mySon) {
					ms.translate(-0.35F, -0.29F, -0.06F);
				} else if(block) {
					ms.translate(-0.4F, 0.8F, 0F);
				} else {
					ms.mulPose(com.mojang.math.Axis.YP.rotationDegrees(-90F));
				}
				ms.translate(-0.3F, -1.9F, 0.04F);
			}
			case WEST -> {
				if(mySon) {
					ms.translate(0.95F, -0.29F, 0.9F);
					if(stack.getComponents().has(DataComponents.CUSTOM_NAME)) {
						TinyPotatoInfo info = TinyPotatoInfo.fromComponent(stack.getHoverName());
						if(info.name().equals("kingdaddydmac")) {
							ms.translate(0.55F, 0, 0);
						}
					}
				} else if(block) {
					ms.translate(1F, 0.8F, 1F);
				} else {
					ms.mulPose(com.mojang.math.Axis.YP.rotationDegrees(-90F));
				}
				ms.translate(-0.3F, -1.9F, -0.92F);
			}
			}

			if(mySon) {
				ms.scale(1.1F, 1.1F, 1.1F);
			} else if(block) {
				ms.scale(0.5F, 0.5F, 0.5F);
			}
			if(block && side == Direction.NORTH) {
				ms.mulPose(com.mojang.math.Axis.YP.rotationDegrees(180F));
			}
			renderItem(ms, buffers, light, overlay, stack);
			ms.popPose();
		}
		ms.popPose();
	}

@Override
	public void render(Boat boat, float yaw, float partialTicks, PoseStack matrix, @NotNull MultiBufferSource buffer, int light) {
		matrix.pushPose();
		matrix.translate(0.0D, 0.375D, 0.0D);
		matrix.mulPose(Axis.YP.rotationDegrees(180.0F - yaw));
		float wiggleAngle = (float) boat.getHurtTime() - partialTicks;
		float wiggleMagnitude = boat.getDamage() - partialTicks;
		if(wiggleMagnitude < 0.0F) {
			wiggleMagnitude = 0.0F;
		}

		if(wiggleAngle > 0.0F) {
			matrix.mulPose(Axis.XP.rotationDegrees(Mth.sin(wiggleAngle) * wiggleAngle * wiggleMagnitude / 10.0F * (float) boat.getHurtDir()));
		}

		float f2 = boat.getBubbleAngle(partialTicks);
		if(!Mth.equal(f2, 0.0F)) {
			matrix.mulPose((new Quaternionf()).setAngleAxis(boat.getBubbleAngle(partialTicks) * 0.017453292F, 1.0F,
					0.0F, 1.0F));
		}

		BoatModelTuple tuple = getModelWithLocation(boat);
		ResourceLocation loc = tuple.resloc();
		BoatModel model = tuple.model();

		matrix.scale(-1.0F, -1.0F, 1.0F);
		matrix.mulPose(Axis.YP.rotationDegrees(90.0F));
		model.setupAnim(boat, partialTicks, 0.0F, -0.1F, 0.0F, 0.0F);
		VertexConsumer vertexconsumer = buffer.getBuffer(model.renderType(loc));
		model.renderToBuffer(matrix, vertexconsumer, light, OverlayTexture.NO_OVERLAY);
		if(!boat.isUnderWater()) {
			VertexConsumer waterMask = buffer.getBuffer(RenderType.waterMask());
			model.waterPatch().render(matrix, waterMask, light, OverlayTexture.NO_OVERLAY);
		}

		matrix.popPose();
		super.render(boat, yaw, partialTicks, matrix, buffer, light);
	}

public static boolean renderTESafely(Level world, BlockPos truePos, BlockState state, BlockEntity tile, BlockEntity sourceTE, float partialTicks, Vec3 offset, PoseStack matrix, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
		Block block = state.getBlock();
		String id = Objects.toString(BuiltInRegistries.BLOCK.getKey(block));

		PoseStack.Pose currEntry = matrix.last();
		render: try {
			if(tile == null || (block == Blocks.PISTON_HEAD) || PistonsMoveTileEntitiesModule.renderBlacklist.contains(id))
				break render;

			matrix.pushPose();
			Minecraft mc = Minecraft.getInstance();
			BlockEntityRenderer<BlockEntity> tileentityrenderer = mc.getBlockEntityRenderDispatcher().getRenderer(tile);
			if(tileentityrenderer != null) {
				tile.setLevel(sourceTE.getLevel());
				tile.clearRemoved();

				matrix.translate(offset.x, offset.y, offset.z);

				tile.setBlockState(state);
				tileentityrenderer.render(tile, partialTicks, matrix, bufferIn, combinedLightIn, combinedOverlayIn);
			}
		} catch (Exception e) {
			Quark.LOG.warn("{} can't be rendered for piston TE moving", id, e);
			PistonsMoveTileEntitiesModule.renderBlacklist.add(id);
			return false;
		} finally {
			while(matrix.last() != currEntry)
				matrix.popPose();
		}

		return state.getRenderShape() != RenderShape.MODEL;
	}

@Override
			public int getColor(@NotNull ItemStack stack, int layer) {
		 		if(isEnabled() && featureEnabled.getAsBoolean() && (layer == 1 || layer == 2) && stack.has(DataComponents.BUCKET_ENTITY_DATA)) {
					CompoundTag tag = stack.get(DataComponents.BUCKET_ENTITY_DATA).copyTag();

					if(tag != null && tag.contains(TropicalFish.BUCKET_VARIANT_TAG, Tag.TAG_INT)) {
						int variant = tag.getInt(TropicalFish.BUCKET_VARIANT_TAG);

						DyeColor dyeColor = layer == 1 ? TropicalFish.getBaseColor(variant) : TropicalFish.getPatternColor(variant);
						int colorComponents = dyeColor.getTextureDiffuseColor();

						return ((colorComponents * 255) << 16) |
								((colorComponents * 255) << 8) |
                                (colorComponents * 255);
					}
				}

				return parent != null ? parent.getColor(stack, layer) : -1;
			}

private static void renderCameraHUD(Minecraft mc, GuiGraphics guiGraphics) {
			PoseStack matrix = guiGraphics.pose();

			Window mw = mc.getWindow();
			int twidth = mw.getGuiScaledWidth();
			int theight = mw.getGuiScaledHeight();
			int width = twidth;
			int height = theight;

			int paddingHoriz = 0;
			int paddingVert = 0;
			int paddingColor = 0xFF000000;

			double targetAspect = -1;

			switch(currBorders) {
			case 1 -> // Square
				targetAspect = 1;
			case 2 -> // 4:3
				targetAspect = 4.0 / 3.0;
			case 3 -> // 16:9
				targetAspect = 16.0 / 9.0;
			case 4 -> // 21:9
				targetAspect = 21.0 / 9.0;
			case 5 -> { // Polaroid
				int border = (int) (20.0 * ((double) (twidth * theight) / 518400));
				paddingHoriz = border;
				paddingVert = border;
				paddingColor = 0xFFFFFFFF;
			}
			}

			if(targetAspect > 0) {
				double currAspect = (double) width / (double) height;

				if(currAspect > targetAspect) {
					int desiredWidth = (int) ((double) height * targetAspect);
					paddingHoriz = (width - desiredWidth) / 2;
				} else if(currAspect < targetAspect) {
					int desiredHeight = (int) ((double) width / targetAspect);
					paddingVert = (height - desiredHeight) / 2;
				}
			}

			width -= (paddingHoriz * 2);
			height -= (paddingVert * 2);

			// =============================================== DRAW BORDERS ===============================================
			if(paddingHoriz > 0) {
				guiGraphics.fill(0, 0, paddingHoriz, theight, paddingColor);
				guiGraphics.fill(twidth - paddingHoriz, 0, twidth, theight, paddingColor);
			}

			if(paddingVert > 0) {
				guiGraphics.fill(0, 0, twidth, paddingVert, paddingColor);
				guiGraphics.fill(0, theight - paddingVert, twidth, theight, paddingColor);
			}

			// =============================================== DRAW OVERLAYS ===============================================
			String overlayText = "";
			boolean overlayShadow = true;
			double overlayScale = 2.0;
			int overlayColor = 0xFFFFFFFF;
			int overlayX = -1;
			int overlayY = -1;

			switch(currOverlay) {
			case 1 -> { // Date
				overlayText = new SimpleDateFormat(dateFormat).format(new Date(System.currentTimeMillis()));
				overlayColor = 0xf77700;
			}
			case 2 -> { // Postcard
				String worldName = "N/A";
				if(mc.getSingleplayerServer() != null)
					worldName = mc.getSingleplayerServer().getWorldData().getLevelName();
				else if(mc.getCurrentServer() != null)
					worldName = mc.getCurrentServer().name;
				overlayText = I18n.get("quark.camera.greetings", worldName);
				overlayX = paddingHoriz + 20;
				overlayY = paddingVert + 20;
				overlayScale = 3;
				overlayColor = 0xef5425;
			}
			case 3 -> { // Watermark
				overlayText = mc.player.getGameProfile().getName();
				overlayScale = 6;
				overlayShadow = false;
				overlayColor = 0x44000000;
			}
			case 4 -> { // Held Item
				overlayText = mc.player.getMainHandItem().getHoverName().getString();
				overlayX = twidth / 2 - mc.font.width(overlayText);
				overlayY = paddingVert + 40;
			}
			}

			if(overlayX == -1)
				overlayX = twidth - paddingHoriz - mc.font.width(overlayText) * (int) overlayScale - 40;
			if(overlayY == -1)
				overlayY = theight - paddingVert - 10 - (10 * (int) overlayScale);

			if(!overlayText.isEmpty()) {
				matrix.pushPose();
				matrix.translate(overlayX, overlayY, 0);
				matrix.scale((float) overlayScale, (float) overlayScale, 1.0F);
				guiGraphics.drawString(mc.font, overlayText, 0, 0, overlayColor, overlayShadow);
				matrix.popPose();
			}

			if(!screenshotting) {
				// =============================================== DRAW RULERS ===============================================
				matrix.pushPose();
				matrix.translate(paddingHoriz, paddingVert, 0);
				switch(currRulers) {
				case 1 -> { // Rule of Thirds
					vruler(guiGraphics, width / 3, height);
					vruler(guiGraphics, width / 3 * 2, height);
					hruler(guiGraphics, height / 3, width);
					hruler(guiGraphics, height / 3 * 2, width);
				}
				case 2 -> { // Golden Ratio
					double phi1 = 1 / 2.61;
					double phi2 = 1.61 / 2.61;
					vruler(guiGraphics, (int) (width * phi1), height);
					vruler(guiGraphics, (int) (width * phi2), height);
					hruler(guiGraphics, (int) (height * phi1), width);
					hruler(guiGraphics, (int) (height * phi2), width);
				}
				case 3 -> { // Center
					vruler(guiGraphics, width / 2, height);
					hruler(guiGraphics, height / 2, width);
				}
				}
				matrix.popPose();

				int left = 30;
				int top = theight - 65;

				// =============================================== DRAW SETTINGS ===============================================
				ResourceLocation shader = SHADERS[currShader];
				String text = "none";
                if(shader != null)
                    text = shader.getPath().replaceAll(".+/(.+)\\.json", "$1");
				text = ChatFormatting.BOLD + "[1] " + ChatFormatting.RESET + I18n.get("quark.camera.filter") + ChatFormatting.GOLD + I18n.get("quark.camera.filter." + text);
				guiGraphics.drawString(mc.font, text, left, top, 0xFFFFFF, true);

				text = ChatFormatting.BOLD + "[2] " + ChatFormatting.RESET + I18n.get("quark.camera.rulers") + ChatFormatting.GOLD + I18n.get("quark.camera.rulers" + currRulers);
				guiGraphics.drawString(mc.font, text, left, top + 12, 0xFFFFFF, true);

				text = ChatFormatting.BOLD + "[3] " + ChatFormatting.RESET + I18n.get("quark.camera.borders") + ChatFormatting.GOLD + I18n.get("quark.camera.borders" + currBorders);
				guiGraphics.drawString(mc.font, text, left, top + 24, 0xFFFFFF, true);

				text = ChatFormatting.BOLD + "[4] " + ChatFormatting.RESET + I18n.get("quark.camera.overlay") + ChatFormatting.GOLD + I18n.get("quark.camera.overlay" + currOverlay);
				guiGraphics.drawString(mc.font, text, left, top + 36, 0xFFFFFF, true);

				text = ChatFormatting.BOLD + "[5] " + ChatFormatting.RESET + I18n.get("quark.camera.reset");
				guiGraphics.drawString(mc.font, text, left, top + 48, 0xFFFFFF, true);

				text = ChatFormatting.AQUA + I18n.get("quark.camera.header");
				guiGraphics.drawString(mc.font, text, (float) (twidth / 2 - mc.font.width(text) / 2), 6, 0xFFFFFF, true);

				text = I18n.get("quark.camera.info", Component.keybind("quark.keybind.camera_mode").getString());
				guiGraphics.drawString(mc.font, text, (float) (twidth / 2 - mc.font.width(text) / 2), 16, 0xFFFFFF, true);

				ResourceLocation CAMERA_TEXTURE = Quark.asResource("textures/misc/camera.png");
				RenderSystem.setShader(GameRenderer::getPositionTexShader);
				RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
				guiGraphics.blit(CAMERA_TEXTURE, left - 22, top + 18, 0, 0, 0, 16, 16, 16, 16);
			}
		}

@PlayEvent
		public void renderForeground(ZRenderContainerScreen.Foreground event) {
			if(searchBar != null && searchEnabled) {
				GuiGraphics guiGraphics = event.getGuiGraphics();
				PoseStack matrix = guiGraphics.pose();
				AbstractContainerScreen<?> gui = event.getContainerScreen();

				matrix.pushPose();

				drawBackground(guiGraphics, gui, searchBar.getX() - 11, searchBar.getY() - 3);

				if(!text.isEmpty()) {
					AbstractContainerMenu container = gui.getMenu();
					matched = 0;
					for(Slot s : container.slots) {
						if(s.isActive()) {
							ItemStack stack = s.getItem();
							if(!namesMatch(stack, text)) {
								int x = s.x;
								int y = s.y;

								guiGraphics.fill(x, y, x + 16, y + 16, overlayColor.getColor());
							} else
								matched++;
						}
					}
				}

				if(matched == 0 && !text.isEmpty())
					searchBar.setTextColor(0xFF5555);
				else
					searchBar.setTextColor(0xFFFFFF);

				searchBar.render(guiGraphics, 0, 0, 0);
				matrix.popPose();
			}
		}

