public static void renderBeamSegment(
            PoseStack poseStack,
            MultiBufferSource bufferIn,
            ResourceLocation textureLocation,
            ExtendedBeamSegment segment,
            float partialTicks,
            float textureScale,
            long totalWorldTime,
            float beamRadius,
            float glowRadius
    ) {
		int height = segment.getHeight();
		int colors = segment.getColor();
		int alpha = segment.alpha;

		poseStack.pushPose();
		poseStack.translate(0.5D, 0.5, 0.5D); // Y translation changed to 0.5
		poseStack.translate(segment.offset.getX(), segment.offset.getY(), segment.offset.getZ()); // offset by the correct distance
		poseStack.mulPose(segment.dir.getRotation());

		float angle = Math.floorMod(totalWorldTime, 40L) + partialTicks;

		poseStack.pushPose();
		poseStack.mulPose(Axis.YP.rotationDegrees(angle * 2.25F - 45.0F));

		float renderTime = -(totalWorldTime + partialTicks);
		float partAngle = Mth.frac(renderTime * 0.2F - (float) Mth.floor(angle * 0.1F));
		float v2 = -1.0F + partAngle;
		float v1 = (float) height * textureScale * (0.5F / beamRadius) + v2;

		renderPart(poseStack, bufferIn.getBuffer(RenderType.beaconBeam(textureLocation, false)), FastColor.ARGB32.color(alpha, colors), height, 0.0F, beamRadius, beamRadius, 0.0F, -beamRadius, 0.0F, 0.0F, -beamRadius, 0.0F, 1.0F, v1, v2);
		poseStack.popPose();
		v1 = (float) height * textureScale + v2;
		renderPart(poseStack, bufferIn.getBuffer(RenderType.beaconBeam(textureLocation, true)), FastColor.ARGB32.color((int)(32f*(alpha/255f)), colors), height, -glowRadius, -glowRadius, glowRadius, -glowRadius, -glowRadius, glowRadius, glowRadius, glowRadius, 0.0F, 1.0F, v1, v2);
		poseStack.popPose();
	}

