public static void drawPsiBar(GuiGraphics graphics, DeltaTracker deltatracker) {
		Minecraft mc = Minecraft.getInstance();
		ItemStack cadStack = PsiAPI.getPlayerCAD(mc.player);

		if(cadStack.isEmpty()) {
			return;
		}

		ICAD cad = (ICAD) cadStack.getItem();
		PlayerData data = PlayerDataHandler.get(mc.player);

		int totalPsi = data.getTotalPsi();
		int currPsi = data.getAvailablePsi();

		if(PsiConfig.client().contextSensitiveBar() && currPsi == totalPsi &&
				!showsBar(data, mc.player.getMainHandItem()) &&
				!showsBar(data, mc.player.getOffhandItem())) {
			return;
		}

		graphics.pose().pushPose();

		boolean right = PsiConfig.client().psiBarOnRight();

		int pad = 3;
		int width = 32;
		int height = 140;

		int x = -pad;
		if(right) {
			x = graphics.guiWidth() + pad - width;
		}
		int y = graphics.guiHeight() / 2 - height / 2;

		if(!registeredMask) {
			RenderSystem.setShaderTexture(0, psiBarMask);
			RenderSystem.setShaderTexture(1, psiBarShatter);
			registeredMask = true;
		}

		RenderSystem.enableBlend();
		graphics.blit(psiBar, x, y, 0, 0, width, height, 64, 256);

		x += 8;
		y += 26;

		width = 16;
		height = 106;

		float r = 0.6F;
		float g = 0.65F;
		float b = 1F;

		if(data.isOverflowed()) {
			r = 1F;
			g = 0.6F;
			b = 0.6F;
		}

		int origHeight = height;
		int origY = y;
		int v = 0;

		RenderSystem.enableBlend();
		RenderSystem.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		for(Deduction d : data.deductions) {
			float a = d.getPercentile(deltatracker.getGameTimeDeltaPartialTick(false));
			RenderSystem.setShaderColor(r, g, b, a);
			height = (int) Math.ceil(origHeight * (double) d.deduct / totalPsi);
			int effHeight = (int) (origHeight * (double) d.current / totalPsi);
			v = origHeight - effHeight;
			y = origY + v;

			usePsiBarShader(a, d.shatter, data.overflowed);
			graphics.blit(psiBar, x, y, 32, v, width, height, 64, 256);
		}

		float textY = origY;
		if(totalPsi > 0) {
			height = (int) ((double) origHeight * (double) data.availablePsi / totalPsi);
			v = origHeight - height;
			y = origY + v;

			if(data.availablePsi != data.lastAvailablePsi) {
				float textHeight = (float) (origHeight
						* (data.availablePsi * deltatracker.getGameTimeDeltaPartialTick(false) + data.lastAvailablePsi * (1.0 - deltatracker.getGameTimeDeltaPartialTick(false))) / totalPsi);
				textY = origY + (origHeight - textHeight);
			} else {
				textY = y;
			}
		} else {
			height = 0;
		}

		RenderSystem.setShaderColor(r, g, b, 1F);
		usePsiBarShader(1F, false, data.overflowed);
		graphics.blit(psiBar, x, y, 32, v, width, height, 64, 256);

		RenderSystem.setShaderColor(1F, 1F, 1F, 1F);

		graphics.pose().pushPose();
		graphics.pose().translate(0F, textY, 0F);
		width = 44;
		height = 3;

		int storedPsi = cad.getStoredPsi(cadStack);

		String s1 = storedPsi == -1 ? "∞" : "" + data.availablePsi;
		String s2 = "" + storedPsi;

		int offBar = 22;
		int offStr1 = 7 + mc.font.width(s1);
		int offStr2 = 7 + mc.font.width(s2);

		if(!right) {
			offBar = 6;
			offStr1 = -23;
			offStr2 = -23;
		}

		int color = cad.getSpellColor(cadStack);
		RenderSystem.setShaderColor(PsiRenderHelper.r(color) / 255F,
				PsiRenderHelper.g(color) / 255F,
				PsiRenderHelper.b(color) / 255F, 1F);

		graphics.blit(psiBar, x - offBar, -2, 0, 140, width, height, 64, 256);
		graphics.drawString(mc.font, s1, x - offStr1, -11, 0xFFFFFF, true);
		graphics.pose().popPose();

		if(storedPsi != -1) {
			graphics.pose().pushPose();
			graphics.pose().translate(0F, Math.max(textY + 3, origY + 100), 0F);
			graphics.drawString(mc.font, s2, x - offStr2, 0, 0xFFFFFF, true);
			graphics.pose().popPose();
		}
		RenderSystem.setShaderColor(1F, 1F, 1F, 1F);
		RenderSystem.disableBlend();
		graphics.pose().popPose();
	}

private static void renderSocketableEquippedName(GuiGraphics graphics, DeltaTracker deltatracker) {
		Minecraft mc = Minecraft.getInstance();
		int toolHighlightTimer = ((AccessorGui) mc.gui).psi$getToolHighlightTimer();
		if(mc.player == null || toolHighlightTimer - 10 <= 0) {
			return;
		}

		ItemStack stack = mc.player.getItemInHand(InteractionHand.MAIN_HAND);
		if(!ISocketable.isSocketable(stack)) {
			return;
		}

		String name = ISocketable.getSocketedItemName(stack, "").getString();
		if(stack.isEmpty() || name.trim().isEmpty()) {
			return;
		}

		ISocketable socketable = ISocketable.socketable(stack);
		ItemStack bullet = socketable.getSelectedBullet();

		int ticks = toolHighlightTimer - 10;
		int alpha = Math.min(255, (int) ((ticks - deltatracker.getGameTimeDeltaPartialTick(false)) * 256.0F / 10.0F));
		int color = ICADColorizer.DEFAULT_SPELL_COLOR + (alpha << 24);
		int x = graphics.guiWidth() / 2 - mc.font.width(name) / 2;
		int y = graphics.guiHeight() - 71;
		int w = mc.font.width(name);
		if(mc.player.isCreative()) {
			y += 14;
		}

		graphics.drawString(mc.font, name, x, y, color, true);
		graphics.pose().pushPose();
		graphics.pose().translate(x + w, y - 6, 0);
		graphics.pose().scale(alpha / 255F, 1F, 1);
		graphics.renderFakeItem(bullet, 0, 0);
		graphics.pose().popPose();
	}

private static void renderRemainingItems(GuiGraphics graphics, DeltaTracker deltatracker) {
		if(remainingTime <= 0 || remainingDisplayStack.isEmpty()) {
			return;
		}

		int pos = maxRemainingTicks - remainingTime;
		Minecraft mc = Minecraft.getInstance();
		int remainingLeaveTicks = 20;
		int x = graphics.guiWidth() / 2 + 10 + Math.max(0, pos - remainingLeaveTicks);
		int y = graphics.guiHeight() / 2;

		int start = maxRemainingTicks - remainingLeaveTicks;
		float alpha = remainingTime + deltatracker.getGameTimeDeltaPartialTick(false) > start ? 1F : (remainingTime + deltatracker.getGameTimeDeltaPartialTick(false)) / start;

		RenderSystem.setShaderColor(1F, 1F, 1F, alpha);
		int xp = x + (int) (16F * (1F - alpha));
		graphics.pose().pushPose();
		graphics.pose().translate(xp, y, 0F);
		graphics.pose().scale(alpha, 1F, 1F);
		graphics.renderFakeItem(remainingDisplayStack, 0, 0);
		graphics.pose().scale(1F / alpha, 1F, 1F);
		graphics.pose().translate(-xp, -y, 0F);
		RenderSystem.setShaderColor(1F, 1F, 1F, 1F);

		String text = remainingDisplayStack.getHoverName().plainCopy().withStyle(ChatFormatting.GREEN).getString();
		if(remainingCount >= 0) {
			int max = remainingDisplayStack.getMaxStackSize();
			int stacks = remainingCount / max;
			int rem = remainingCount % max;

			if(stacks == 0) {
				text = "" + remainingCount;
			} else {
				text = remainingCount + " (" + ChatFormatting.AQUA + stacks + ChatFormatting.RESET + "*"
						+ ChatFormatting.GRAY + max + ChatFormatting.RESET + "+" + ChatFormatting.YELLOW + rem
						+ ChatFormatting.RESET + ")";
			}
		} else if(remainingCount == -1) {
			text = "∞";
		}

		int color = 0x00FFFFFF | (int) (alpha * 0xFF) << 24;

		graphics.drawString(mc.font, text, x + 20, y + 6, color, true);
		graphics.pose().popPose();
	}

public static void render(PlayerData data, Player player, float partialTicks, PoseStack poseStack) {
		EntityRenderDispatcher renderManager = Minecraft.getInstance().getEntityRenderDispatcher();
		double x = player.xOld + (player.getX() - player.xOld) * partialTicks - renderManager.camera.getPosition().x;
		double y = player.yOld + (player.getY() - player.yOld) * partialTicks - renderManager.camera.getPosition().y;
		double z = player.zOld + (player.getZ() - player.zOld) * partialTicks - renderManager.camera.getPosition().z;
		float scale = 0.75F;
		if(data.loopcasting) {
			scale *= Math.min(5F, data.loopcastTime + partialTicks) / 5F;
		} else if(data.loopcastFadeTime > 0) {
			scale *= Math.min(5F, data.loopcastFadeTime - partialTicks) / 5F;
		} else {
			return;
		}

		int color = ICADColorizer.DEFAULT_SPELL_COLOR;
		ItemStack cad = PsiAPI.getPlayerCAD(data.playerWR.get());
		if(!cad.isEmpty() && cad.getItem() instanceof ICAD icad) {
			color = icad.getSpellColor(cad);
		}

		poseStack.pushPose();
		poseStack.translate(x, y + 0.15, z);
		MultiBufferSource.BufferSource buffers = Minecraft.getInstance().renderBuffers().bufferSource();
		RenderSpellCircle.renderSpellCircle(ClientTickHandler.ticksInGame + partialTicks,
				scale, 1, 0, -1, 0, color, poseStack, buffers);
		buffers.endBatch();
		poseStack.popPose();
	}

public static void renderSpellCircle(float alive, float scale, float horizontalScale, float xDir, float yDir, float zDir, int color, PoseStack ms, MultiBufferSource buffers) {
		ms.pushPose();
		double ratio = 0.0625 * horizontalScale;

		Vec3 direction = new Vec3(xDir, yDir, zDir);
		Vec3 normal = new Vec3(0f, 0f, 1f);
		Vec3 axis = normal.cross(direction);
		double dot = normal.dot(direction);

		// Very small threshold to see if it's parallel or not.
		if(axis.length() < 1e-6) {
			// If it's parallel but the dot product is negative we flip it.
			if(dot < 0) {
				ms.mulPose(Axis.XP.rotationDegrees(180f));
			}
		} else {
			float angle = (float) Math.acos(dot);
			ms.mulPose(new Quaternionf().fromAxisAngleRad((float) axis.x, (float) axis.y, (float) axis.z, angle));
		}

		ms.translate(0, 0, 0.1);
		ms.scale((float) ratio * scale, (float) ratio * scale, (float) ratio);

		int r = PsiRenderHelper.r(color);
		int g = PsiRenderHelper.g(color);
		int b = PsiRenderHelper.b(color);

		for(int i = 0; i < LAYERS.length; i++) {
			int rValue = r;
			int gValue = g;
			int bValue = b;

			if(i == 1) {
				rValue = gValue = bValue = 0xFF;
			} else if(i == 2) {
				int minBrightness = (int) (1 / (1 - BRIGHTNESS_FACTOR));
				if(rValue == 0 && gValue == 0 && bValue == 0) {
					rValue = gValue = bValue = minBrightness;
				}
				if(rValue > 0 && rValue < minBrightness) {
					rValue = minBrightness;
				}
				if(gValue > 0 && gValue < minBrightness) {
					gValue = minBrightness;
				}
				if(bValue > 0 && bValue < minBrightness) {
					bValue = minBrightness;
				}

				rValue = (int) Math.min(rValue / BRIGHTNESS_FACTOR, 0xFF);
				gValue = (int) Math.min(gValue / BRIGHTNESS_FACTOR, 0xFF);
				bValue = (int) Math.min(bValue / BRIGHTNESS_FACTOR, 0xFF);
			}

			ms.pushPose();
			ms.mulPose(Axis.ZP.rotationDegrees(i == 0 ? -alive : alive));

			VertexConsumer buffer = buffers.getBuffer(LAYERS[i]);
			Matrix4f mat = ms.last().pose();
			int fullbright = 0xF000F0;
			addVertex(buffer, mat, -32, 32, rValue, gValue, bValue, 0, 1, fullbright);
			addVertex(buffer, mat, 32, 32, rValue, gValue, bValue, 1, 1, fullbright);
			addVertex(buffer, mat, 32, -32, rValue, gValue, bValue, 1, 0, fullbright);
			addVertex(buffer, mat, -32, -32, rValue, gValue, bValue, 0, 0, fullbright);
			ms.popPose();

			ms.translate(0, 0, -0.5);
		}

		ms.popPose();
	}

@Override
	public void render(TileProgrammer te, float partialticks, @NotNull PoseStack ms, @NotNull MultiBufferSource buffers, int worldLight, int overlay) {
		if(te.isEnabled()) {
			ms.pushPose();
			boolean magical = PsiEnvironment.isMagical();
			int light = magical ? worldLight : 0xF000F0;

			ms.translate(0, 1.62F, 0);
			ms.mulPose(Axis.ZP.rotationDegrees(180F));
			ms.mulPose(Axis.YP.rotationDegrees(-90F));

			float rot = 90F;
			BlockState state = te.getBlockState();

			Direction facing = state.getValue(FaceAttachedHorizontalDirectionalBlock.FACING);
			switch(facing) {
			case SOUTH:
				rot = -90F;
				break;
			case EAST:
				rot = 180F;
				break;
			case WEST:
				rot = 0F;
				break;
			default:
				break;
			}

			ms.translate(0.5F, 0F, 0.5F);
			ms.mulPose(Axis.YP.rotationDegrees(rot));
			ms.translate(-0.5F, 0F, -0.5F);

			float f = 1F / 300F;
			ms.scale(f, f, -f);

			if(magical) {
				ms.mulPose(Axis.XP.rotationDegrees(90F));
				ms.translate(70F, -220F, -100F + Math.sin(ClientTickHandler.total / 50) * 10);
				ms.mulPose(Axis.XP.rotationDegrees(-16F + (float) Math.cos(ClientTickHandler.total / 100) * 10F));
			} else {
				ms.translate(70F, 0F, -200F);
			}

			SpellPieceRenderer.draw(te.spell, ms, buffers, light);

			ms.pushPose();
			ms.translate(0F, 0F, -0.01F);
			VertexConsumer buffer = buffers.getBuffer(GuiProgrammer.LAYER);
			float x = -7, y = -7;
			float width = 174;
			float height = 184;
			float u = 0, v = 0;
			float rescale = 1 / 256F;
			float a = magical ? 1F : 0.5F;
			Matrix4f mat = ms.last().pose();
			buffer.addVertex(mat, x, y + height, 0).setColor(1, 1, 1, a).setUv(u * rescale, (v + height) * rescale).setLight(light);
			buffer.addVertex(mat, x + width, y + height, 0).setColor(1, 1, 1, a).setUv((u + width) * rescale, (v + height) * rescale).setLight(light);
			buffer.addVertex(mat, x + width, y, 0).setColor(1, 1, 1, a).setUv((u + width) * rescale, v * rescale).setLight(light);
			buffer.addVertex(mat, x, y, 0).setColor(1, 1, 1, a).setUv(u * rescale, v * rescale).setLight(light);
			ms.popPose();

			int color = magical ? 0 : 0xFFFFFF;
			Minecraft mc = Minecraft.getInstance();
			mc.font.drawInBatch(I18n.get("psimisc.name"), 0, 164, color, false, ms.last().pose(), buffers, Font.DisplayMode.NORMAL, 0, 0xF000F0);
			mc.font.drawInBatch(te.spell.name, 38, 164, color, false, ms.last().pose(), buffers, Font.DisplayMode.NORMAL, 0, 0xF000F0);

			ms.popPose();
		}
	}

