			PoseStack poseStack = guiGraphics.pose();
			if (animation > 0.0F)
			{
				poseStack.pushPose();
				float f1 = 1.0F + animation / 5.0F;
				poseStack.translate((float) (x + 8), (float) (y + 12), 0.0F);
				poseStack.scale(1.0F / f1, (f1 + 1.0F) / 2.0F, 1.0F);
