@Override
    public <T extends LivingEntity, M extends EntityModel<T>> void render(ItemStack stack,
                                                                          SlotContext slotContext,
                                                                          MatrixStack matrixStack,
                                                                          FeatureRendererContext<T, M> renderLayerParent,
                                                                          VertexConsumerProvider renderTypeBuffer,
                                                                          int light, float limbSwing,
                                                                          float limbSwingAmount,
                                                                          float partialTicks,
                                                                          float ageInTicks, float netHeadYaw,
                                                                          float headPitch) {
        var client = MinecraftClient.getInstance();
        var model = client.getBakedModelManager().getModel(this.modelIdentifier);
        if (slotContext.entity() instanceof AbstractClientPlayerEntity player
                && renderLayerParent.getModel() instanceof PlayerEntityModel playerModel) {
            // Inlined equivalent of Trinkets' `TrinketRenderer.translateToChest`, so the
            // placement below can reuse the offsets tuned for the Fabric renderer.
            if (player.isInSneakingPose() && !playerModel.riding && !player.isSwimming()) {
                matrixStack.translate(0.0F, 0.2F, 0.0F);
                matrixStack.multiply(RotationAxis.POSITIVE_X.rotation(playerModel.body.pitch));
            }
            matrixStack.multiply(RotationAxis.POSITIVE_Y.rotation(playerModel.body.yaw));
            matrixStack.translate(0.0F, 0.4F, -0.16F);

            matrixStack.translate(-0.825F, 0.25F, 0.7F); //Position
            Quaternionf rotation = new Quaternionf().rotationAxis((float) Math.toRadians(-140), //Degrees of rotation
                    new Vector3f(1, 0, 0)); //Rotate around the X axis
            matrixStack.multiply(rotation);
        }
        var buffer = renderTypeBuffer.getBuffer(RenderLayers.getItemLayer(stack, true));
        ((ItemRendererAccessor) client.getItemRenderer()).SpellEngine_renderBakedItemModel(model, ItemStack.EMPTY, light, OverlayTexture.DEFAULT_UV, matrixStack, buffer);
    }

private static RenderPhase.Texturing itemGlowTexturing(Color color) {
        return new RenderPhase.Texturing("spell_engine_item_glow_texturing",
                () -> {
                    // `getShaderColor` hands out the live array, not a copy of it
                    System.arraycopy(RenderSystem.getShaderColor(), 0, shaderColorToRestore, 0, 4);
                    glintAlphaToRestore = RenderSystem.getShaderGlintAlpha();

                    RenderSystem.setTextureMatrix(itemGlowTextureMatrix());

                    // Opacity is folded into the color instead of the alpha, because the additive blend
                    // scales by color, and the glint shader discards fragments below `alpha < 0.1`,
                    // which would cut faint glows off entirely instead of fading them out.
                    var intensity = color.alpha() * itemGlowGain;
                    RenderSystem.setShaderColor(
                            color.red() * intensity,
                            color.green() * intensity,
                            color.blue() * intensity,
                            1F);

                    // The glint shader fades by this, and it follows the `Glint Strength` video setting.
                    // This glow carries gameplay meaning, so it must not be dimmed away by a cosmetic option.
                    RenderSystem.setShaderGlintAlpha(1F);
                },
                () -> {
                    RenderSystem.resetTextureMatrix();
                    RenderSystem.setShaderColor(
                            shaderColorToRestore[0], shaderColorToRestore[1],
                            shaderColorToRestore[2], shaderColorToRestore[3]);
                    RenderSystem.setShaderGlintAlpha(glintAlphaToRestore);
                });
    }

@Override
    public void renderEffect(long appliedAtWorldTime, int amplifier, LivingEntity livingEntity, float delta, MatrixStack matrixStack,
                 VertexConsumerProvider vertexConsumers, int light) {
        var itemRenderer = MinecraftClient.getInstance().getItemRenderer();
        // World time, not Entity.age: the server stamps `appliedAtWorldTime` in its clock, and the
        // client's World.getTime() tracks it (shared origin, re-synced each second). Entity.age counts
        // from whenever each side first saw the entity, so `age - appliedAtAge` could start deeply
        // negative and skip the whole animation for seconds. See Synchronized.Effect.
        float rawTime = (livingEntity.getWorld().getTime() - appliedAtWorldTime) + delta;

        if (followYaw) {
            float yaw = livingEntity.getYaw(delta);
            matrixStack.multiply(RotationAxis.NEGATIVE_Y.rotationDegrees(yaw));
        }

        if (entityScaling != null) {
            float s = entityScaling.scaleFor(livingEntity);
            matrixStack.scale(s, s, s);
        }

        for (var effect : effects) {
            if (effect.model_id == null || effect.model_id.isEmpty()) continue;

            float age;
            if (playback == Playback.LOOP && effect.duration > 0) {
                age = rawTime % effect.duration;
            } else {
                age = rawTime;
            }

            ModelEffectOperations.renderEffect(effect, age, matrixStack, itemRenderer, vertexConsumers, light, livingEntity.getId());
        }
    }

@Override
    public void renderEffect(long appliedAtWorldTime, int amplifier, LivingEntity livingEntity, float delta, MatrixStack matrixStack, VertexConsumerProvider vertexConsumers, int light) {
        matrixStack.push();
        var time = livingEntity.age + delta;

        var initialAngle = time * orbitingSpeed - 45.0F;
        var entityScale = livingEntity.getScale();
        var horizontalOffset = this.horizontalOffset * livingEntity.getScaleFactor();
        var verticalOffset = livingEntity.getHeight() / (2F * entityScale);
        var itemRenderer = MinecraftClient.getInstance().getItemRenderer();

        var stacks = amplifier + 1;
        var turnAngle = 360F / stacks;
        for (int i = 0; i < stacks; i++) {
            var angle = initialAngle + turnAngle * i;
            renderModel(matrixStack, scale, verticalOffset, horizontalOffset, angle, itemRenderer, vertexConsumers, light, livingEntity);
        }

        matrixStack.pop();
    }

private void renderModel(MatrixStack matrixStack, float scale, float verticalOffset, float horizontalOffset, float rotation,
                               ItemRenderer itemRenderer, VertexConsumerProvider vertexConsumers, int light, LivingEntity livingEntity) {
        matrixStack.push();

        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(rotation));
        matrixStack.translate(0, verticalOffset, -horizontalOffset);
        matrixStack.scale(scale, scale, scale);

        for(var model: models) {
            matrixStack.push();
            CustomModels.render(model.layer, itemRenderer, model.modelId,
                    matrixStack, vertexConsumers, light, livingEntity.getId());
            matrixStack.pop();
        }

        matrixStack.pop();
    }

public static ModelEffectBuilder spike(ModelEffectBuilder builder, int riseTime, int upTime,
                                                boolean withScale, float buryDepth) {
            int sinkStart = riseTime + upTime;
            int end = sinkStart + riseTime;
            builder.duration(end)
                    .initialTranslate(0, -buryDepth, 0)
                    .translate(0, buryDepth, 0, 0, riseTime, Easing.EASE_OUT_ELASTIC)
                    .translate(0, -buryDepth, 0, sinkStart, end, Easing.EASE_IN_ELASTIC);
            if (withScale) {
                builder.scaleIn(0, riseTime, Easing.EASE_OUT_ELASTIC)
                        .scaleOut(sinkStart, end, Easing.EASE_IN_ELASTIC);
            }
            return builder;
        }

protected SpellParticle(ClientWorld world, double x, double y, double z,
                            double velocityX, double velocityY, double velocityZ,
                            SpriteProvider spriteProvider,
                            SpellEngineParticles.Entry entry,
                            ParticleGroup.Appearance config,
                            @Nullable Entity sourceEntity) {
        super(world, x, y, z);
        this.spriteProvider = spriteProvider;
        this.frameCount = entry.texture().frames();
        this.pivot = entry.pivot();

        this.facing = config.facing != null ? config.facing : ParticleGroup.Facing.CAMERA;
        this.render = config.render != null ? config.render : ParticleGroup.Render.TRANSLUCENT;
        this.glow = config.glow != null ? config.glow : true;
        var motion = config.motion != null ? config.motion : ParticleGroup.Motion.STATIC;
        this.motion = motion;

        // MARK: Motion preset (constants ported from V1 SpellUniversalParticle)

        this.collidesWithWorld = config.collides;
        switch (motion) {
            case STATIC -> {
                this.velocityX = velocityX;
                this.velocityY = velocityY;
                this.velocityZ = velocityZ;
                this.velocityMultiplier = 1F;
                this.gravityStrength = 0F;
            }
            case FLOAT, DECELERATE -> {
                this.velocityMultiplier = motion == ParticleGroup.Motion.DECELERATE ? 0.768F : 0.96F;
                this.gravityStrength = 0F;
                this.velocityX = velocityX + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
                this.velocityY = velocityY + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
                this.velocityZ = velocityZ + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
                this.x += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
                this.y += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
                this.z += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
                this.setPos(this.x, this.y, this.z);
            }
            case ASCEND -> {
                this.velocityMultiplier = 0.96F;
                this.gravityStrength = -0.1F;
                this.ascending = true;
                this.velocityX = velocityX * (velocityX == 0 && velocityZ == 0 ? 0.1F : 1F)
                        + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
                this.velocityY = velocityY * 0.2F + 0.02F;
                this.velocityZ = velocityZ * (velocityX == 0 && velocityZ == 0 ? 0.1F : 1F)
                        + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            }
            case BURST -> {
                this.velocityMultiplier = 0.7F;
                this.gravityStrength = 0.5F;
                this.velocityX = velocityX * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
                this.velocityY = velocityY * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
                this.velocityZ = velocityZ * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
            }
            case DRIFT -> {
                // Vanilla SnowflakeParticle's motion: a wide random scatter, gravity,
                // and per-axis damping that bleeds vertical speed faster than lateral,
                // so particles fan out as they settle rather than dropping in a line.
                this.velocityMultiplier = 1F;
                this.gravityStrength = 0.225F;
                this.velocityX = velocityX + (Math.random() * 2.0 - 1.0) * 0.05F;
                this.velocityY = velocityY + (Math.random() * 2.0 - 1.0) * 0.05F;
                this.velocityZ = velocityZ + (Math.random() * 2.0 - 1.0) * 0.05F;
            }
        }
        if (config.gravity != null) {
            this.gravityStrength = config.gravity;
        }
        if (config.drag != null) {
            this.velocityMultiplier = config.drag;
        }

        // MARK: Lifetime & playback

        float playbackSpeed = config.playback_speed == 0F ? 1F : config.playback_speed;
        this.reversedPlayback = playbackSpeed < 0F;
        float lifetimeRoll = 1F + (this.random.nextFloat() * 2F - 1F) * MathHelper.clamp(config.lifetime_variance, 0F, 1F);
        this.maxAge = Math.max(1, Math.round(
                entry.lifetime() * motion.lifetime_factor * lifetimeRoll / Math.abs(playbackSpeed)));

        // MARK: Appearance

        float darken = 1F - this.random.nextFloat() * MathHelper.clamp(config.color_variance, 0F, 1F);
        float colorAlpha = 1F;
        if (config.color >= 0) {
            var color = Color.fromRGBA(config.color);
            this.setColor(color.red() * darken, color.green() * darken, color.blue() * darken);
            colorAlpha = color.alpha();
        } else {
            this.setColor(darken, darken, darken);
        }
        this.baseOpacity = config.opacity * colorAlpha;
        this.opacityCurve = config.opacity_curve;
        this.alpha = baseOpacity * (opacityCurve != null ? opacityCurve.sample(0F) : 1F);

        float scaleVariance = MathHelper.clamp(config.scale_variance, 0F, 1F);
        this.spawnScale = config.scale * (1F + (this.random.nextFloat() * 2F - 1F) * scaleVariance);
        this.scale = spawnScale;
        this.scaleEasing = config.scale_easing;
        this.scaleMultiplier = config.scale_multiplier;

        // MARK: Attachment

        this.attachment = config.attachment;
        this.followEntity = attachment != ParticleGroup.Attachment.NONE ? sourceEntity : null;
        if (followEntity != null) {
            this.followDiff = new Vec3d(this.x - followEntity.getX(), this.y - followEntity.getY(), this.z - followEntity.getZ());
        }
        // Seed the ground cache with the spawn height (a GROUND-anchored batch already
        // resolves to the floor), so the first frame is correct before any re-probe.
        this.groundY = this.y;

        updateSprite();
        updateSkipRender();
    }

@Override
    public void tick() {
        super.tick();
        if (this.dead) {
            return;
        }
        if (motion == ParticleGroup.Motion.DRIFT) {
            // Per-axis, so it cannot be expressed through the scalar `drag` field
            this.velocityX *= 0.95F;
            this.velocityY *= 0.9F;
            this.velocityZ *= 0.95F;
        }
        float progress = (float) this.age / (float) this.maxAge;
        updateSprite();
        this.alpha = baseOpacity * (opacityCurve != null ? opacityCurve.sample(progress) : 1F) * elevationFade();
        float eased = scaleEasing != null
                ? MathHelper.lerp(Easing.apply(scaleEasing, progress), 1F, scaleMultiplier)
                : 1F;
        float entityScale = attachment == ParticleGroup.Attachment.POSITION_SCALED
                && followEntity instanceof LivingEntity livingEntity
                ? livingEntity.getScale() : 1F;
        this.scale = spawnScale * eased * entityScale;
        updateSkipRender();
    }

public static void renderAllInWorld(MatrixStack matrices, VertexConsumerProvider.Immediate vertexConsumers, Camera camera, int light, float delta) {
        var focusedEntity = camera.getFocusedEntity();
        if (focusedEntity == null) {
            return;
        }

        var world = MinecraftClient.getInstance().world;
        if (world == null) {
            return;
        }
        var renderDistance = MinecraftClient.getInstance().options.getViewDistance().getValue() * 24; // 24 = 16 * 1.5F
        var squaredRenderDistance = renderDistance * renderDistance;
        // Any entity exposing a cast process can beam (players and summons alike)
        var casters = new ArrayList<LivingEntity>();
        for (var entity : world.getEntities()) {
            if (entity instanceof LivingEntity livingEntity
                    && entity instanceof SpellCaster.Entity holder
                    && holder.getBeam() != null
                    && entity.squaredDistanceTo(focusedEntity) < squaredRenderDistance) {
                casters.add(livingEntity);
            }
        }
        if (casters.isEmpty()) {
            return;
        }

        matrices.push();
        Vec3d camPos = camera.getPos();
        matrices.translate(-camPos.x, -camPos.y, -camPos.z);
        for (var livingEntity : casters) {
            var launchHeight = LaunchGeometry.launchHeight(livingEntity);
            var offset = new Vec3d(0.0, launchHeight, LaunchGeometry.launchPointOffsetDefault);
            SpellCaster.Entity caster = (SpellCaster.Entity) livingEntity;
            matrices.push();
            var pos = new Vec3d(livingEntity.prevX, livingEntity.prevY, livingEntity.prevZ)
                    .lerp(livingEntity.getPos(), delta);
            matrices.translate(pos.x, pos.y, pos.z);

            Vec3d from = livingEntity.getPos().add(0, launchHeight, 0);
            var lookVector = Vec3d.ZERO;
            if (livingEntity == MinecraftClient.getInstance().player) {
                // No lerp for local player
                lookVector = Vec3d.fromPolar(livingEntity.getPitch(), livingEntity.getYaw());
            } else {
                lookVector = Vec3d.fromPolar(livingEntity.prevPitch, livingEntity.prevYaw);
                lookVector = lookVector.lerp(Vec3d.fromPolar(livingEntity.getPitch(), livingEntity.getYaw()), delta);
            }
            lookVector = lookVector.normalize();
            var beamPosition = TargetHelper.castBeam(livingEntity, lookVector, 32);
            lookVector = lookVector.multiply(beamPosition.length());
            Vec3d to = from.add(lookVector);

            var beamAppearance = caster.getBeam();
            renderBeamFromPlayer(matrices, vertexConsumers, beamAppearance,
                    from, to, offset, livingEntity.getWorld().getTime(), delta);
            ((BeamEmitterEntity)livingEntity).setLastRenderedBeam(new Beam.Rendered(beamPosition, beamAppearance));
            matrices.pop();
        }
        vertexConsumers.draw();
        matrices.pop();
    }

private static void renderBeamFromPlayer(MatrixStack matrixStack, VertexConsumerProvider vertexConsumerProvider,
                                             Spell.Target.Beam beam,
                                             Vec3d from, Vec3d to, Vec3d offset, long time, float tickDelta) {
        var absoluteTime = (float)Math.floorMod(time, 40) + tickDelta;

        matrixStack.push();
        matrixStack.translate(0, offset.y, 0);

        Vec3d beamVector = to.subtract(from);
        float length = (float)beamVector.length();

        // Perform some rotation
        beamVector = beamVector.normalize();
        float n = (float)Math.acos(beamVector.y);
        float o = (float)Math.atan2(beamVector.z, beamVector.x);
        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees((1.5707964F - o) * 57.295776F));
        matrixStack.multiply(RotationAxis.POSITIVE_X.rotationDegrees(n * 57.295776F));
        matrixStack.translate(0, offset.z, 0); // At this point everything is so rotated, we need to translate along y to move along z

        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(absoluteTime * 2.25F - 45.0F));

        var texture = Identifier.of(beam.texture_id);
        var outerColor = Color.IntFormat.fromLongRGBA(beam.color_rgba);
        var innerColor = Color.IntFormat.fromLongRGBA(beam.inner_color_rgba);

        LayerSet renderLayers;
        if (ShaderCompatibility.isVanillaRenderSystem()) {
            renderLayers = vanilla(texture);
        } else {
            var luminance = ShaderCompatibility.isShaderPackInUse()
                    ? (SpellEngineClient.config.renderBeamsHighLuminance ? beam.luminance : Spell.Target.Beam.Luminance.MEDIUM)
                    : Spell.Target.Beam.Luminance.LOW;
            renderLayers = layerSetFor(texture, luminance);
        }
        BeamRenderer.renderBeam(matrixStack, vertexConsumerProvider,
                time, tickDelta, beam.flow, true,
                innerColor, outerColor, renderLayers,
                0, length, beam.width);

        matrixStack.pop();
    }

public void render(SpellBindingBlockEntity blockEntity, float f, MatrixStack matrixStack, VertexConsumerProvider vertexConsumerProvider, int i, int j) {
        matrixStack.push();
        matrixStack.translate(0.5, 0.75, 0.5);
        float g = (float)blockEntity.ticks + f;
        matrixStack.translate(0.0F, 0.1F + MathHelper.sin(g * 0.1F) * 0.01F, 0.0F);

        float h;
        for(h = blockEntity.bookRotation - blockEntity.lastBookRotation; h >= 3.1415927F; h -= 6.2831855F) {
        }

        while(h < -3.1415927F) {
            h += 6.2831855F;
        }

        float k = blockEntity.lastBookRotation + h * f;
        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotation(-k));
        matrixStack.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(80.0F));
        float l = MathHelper.lerp(f, blockEntity.pageAngle, blockEntity.nextPageAngle);
        float m = MathHelper.fractionalPart(l + 0.25F) * 1.6F - 0.3F;
        float n = MathHelper.fractionalPart(l + 0.75F) * 1.6F - 0.3F;
        float o = MathHelper.lerp(f, blockEntity.pageTurningSpeed, blockEntity.nextPageTurningSpeed);
        this.book.setPageAngles(g, MathHelper.clamp(m, 0.0F, 1.0F), MathHelper.clamp(n, 0.0F, 1.0F), o);
        VertexConsumer vertexConsumer = BOOK_TEXTURE.getVertexConsumer(vertexConsumerProvider, RenderLayer::getEntitySolid);
        this.book.renderBook(matrixStack, vertexConsumer, i, j, -1);
        matrixStack.pop();
    }

private void renderModelFx(T entity, Spell.Delivery.Cloud.ClientData clientData, float tickDelta,
                               MatrixStack matrixStack, VertexConsumerProvider vertexConsumers, int light) {
        matrixStack.push();
        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-1F * entity.getYaw() + 180F));
        // Grow the model with the cloud's radius. Applied about the ground origin (before the 0.5 lift)
        // so the model scales up from where it sits. `getRenderScale` interpolates within the tick, so a
        // discrete growth step doesn't pop; it's 1.0 for a non-growing cloud, leaving existing clouds
        // untouched.
        float renderScale = entity.getRenderScale(tickDelta);
        if (renderScale != 1F) {
            matrixStack.scale(renderScale, renderScale, renderScale);
        }
        matrixStack.translate(0, 0.5, 0); // Compensate for translate within CustomModels.render

        float age = entity.age + tickDelta;
        for (var effect : clientData.model_fx) {
            if (effect == null || effect.model_id == null || effect.model_id.isEmpty()) {
                continue;
            }
            matrixStack.push();
            if (effect.positioning != null && effect.positioning.vertical != 0) {
                matrixStack.translate(0, effect.positioning.vertical * entity.getHeight(), 0);
            }
            ModelEffectOperations.renderEffect(effect, age, matrixStack, itemRenderer, vertexConsumers, light, entity.getId());
            matrixStack.pop();
        }

        matrixStack.pop();
    }

public void render(T entity, float yaw, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        if (!(entity instanceof SpellProjectile projectile)) {
            return;
        }
        var effectiveScale = this.scale * projectile.getScaleMultiplier();
        boolean rendered = false;
        var composite = projectile.renderModels();
        if (composite != null && !composite.models.isEmpty()) {
            rendered = renderComposite(effectiveScale, this.dispatcher, this.itemRenderer, composite, projectile.heldItemModelId(),
                    projectile.previousVelocity, entity, tickDelta, true, matrices, vertexConsumers, light);
        }
        if (rendered) {
            super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
        }
    }

public static boolean renderComposite(float scale, EntityRenderDispatcher dispatcher, ItemRenderer itemRenderer,
                                          Spell.ProjectileModelComposite composite, @Nullable String heldItemModelId,
                                          @Nullable Vec3d previousVelocity, Entity entity, float tickDelta, boolean allowSpin,
                                          MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        // Skip while very fresh and very close to the camera, so a just-spawned projectile doesn't
        // fill the caster's view.
        if (entity.age < 2 && dispatcher.camera.getFocusedEntity().squaredDistanceTo(entity) < 12.25) {
            return false;
        }

        float age = entity.age + tickDelta;
        for (var model : composite.models) {
            var fx = model.fx;
            matrices.push();

            // Placement within the entity bounding box (entity space, before the entity scale).
            if (fx.positioning != null && fx.positioning.vertical != 0) {
                matrices.translate(0, fx.positioning.vertical * entity.getHeight(), 0);
            }
            // Overall projectile scale.
            matrices.scale(scale, scale, scale);
            // Facing relative to travel.
            applyCompositeOrientation(model.orientation, dispatcher, entity, previousVelocity, tickDelta, matrices);
            // Continuous spin (disabled e.g. while an arrow is stuck in the ground).
            if (allowSpin && (model.rotate_degrees_per_tick != 0 || model.rotate_degrees_offset != 0)) {
                matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(
                        model.rotate_degrees_offset + age * model.rotate_degrees_per_tick));
            }
            // modelFX animation (initial + animated transforms + fx.scale).
            ModelEffectOperations.applyTransforms(matrices, fx, age);

            var layer = SpellModelHelper.LAYERS.get(fx.light_emission);
            if (model.use_held_item) {
                // Held items MUST resolve through the item model path (itemRenderer.getModel(stack, ...)).
                // Resolving them as a raw model Identifier via CustomModels.render breaks on NeoForge: getModel returns the missing-model placeholder
                // (never null) for a bare item id — an item's model isn't registered under the `#standalone`
                // variant the NeoForge branch looks up — so the item-stack fallback never fires and an
                // empty/placeholder model is drawn. heldItemModelId is null for non-held projectiles (e.g.
                // arrows via ProjectileEntityRendererMixin), which then correctly skip these models.
                if (heldItemModelId != null && !heldItemModelId.isEmpty()) {
                    var stack = Registries.ITEM.get(Identifier.of(heldItemModelId)).getDefaultStack();
                    if (!stack.isEmpty()) {
                        var itemModel = itemRenderer.getModel(stack, entity.getWorld(), null, entity.getId());
                        // Item models are authored in item-display space; FIXED (item-frame) gives them the
                        // base orientation the projectile orientation math (e.g. ALONG_MOTION) expects.
                        itemModel.getTransformation().getTransformation(ModelTransformationMode.FIXED).apply(false, matrices);
                        CustomModels.renderModel(layer, (ItemRendererAccessor) itemRenderer, matrices, vertexConsumers, light, itemModel);
                    }
                }
            } else if (fx.model_id != null && !fx.model_id.isEmpty()) {
                // Custom (non-item) fx models render raw, with no display transform.
                CustomModels.render(layer, itemRenderer, Identifier.of(fx.model_id), null, matrices, vertexConsumers, light, entity.getId());
            }

            matrices.pop();
        }
        return true;
    }

private static void applyCompositeOrientation(Spell.ProjectileModelComposite.Orientation orientation, EntityRenderDispatcher dispatcher,
                                                  Entity entity, @Nullable Vec3d previousVelocity, float tickDelta, MatrixStack matrices) {
        switch (orientation) {
            case TOWARDS_CAMERA -> {
                matrices.multiply(dispatcher.getRotation());
                matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F));
            }
            case TOWARDS_MOTION, ALONG_MOTION -> {
                var velocity = entity.getVelocity();
                if (previousVelocity != null) {
                    velocity = previousVelocity.lerp(velocity, tickDelta);
                }
                velocity = velocity.normalize();
                var directionBasedYaw = Math.toDegrees(Math.atan2(velocity.x, velocity.z)) + 180F;
                var directionBasedPitch = Math.toDegrees(Math.asin(velocity.y));
                matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees((float) directionBasedYaw));
                matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees((float) directionBasedPitch));
                if (orientation == Spell.ProjectileModelComposite.Orientation.ALONG_MOTION) {
                    // ALONG_MOTION models lie along their local X axis, so folding the +90 into the
                    // yaw would leave the pitch (applied around X) rotating the model about its own
                    // length — no elevation, model stuck facing the horizon. Instead convert the X
                    // length into the +Z "forward" that the yaw/pitch above already orient, applied
                    // innermost (last) so it doesn't cancel the vertical component of the motion.
                    matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(90F));
                }
            }
        }
    }

private static Vec3d direction(ParticleGroup.Batch batch, long time, float yaw, float pitch) {
        var direction = Vec3d.ZERO;

        float rotateAroundX = 0;
        float rotateAroundY = 0;
        switch (batch.shape) {
            case NONE -> {
                // Placed, not thrown: no velocity, and nothing for roll/pre_travel to act on
                return Vec3d.ZERO;
            }
            case LINE -> {
                direction = new Vec3d(0, 0, randomInRange(batch.min_speed, batch.max_speed));
                pitch = -pitch; // Inverting pitch, do not remove, it makes things work :D
            }
            case CONE -> {
                direction = new Vec3d(0, randomInRange(batch.min_speed, batch.max_speed), 0);
                rotateAroundX += rng.nextFloat() * batch.angle - (batch.angle * 0.5F);
                rotateAroundY += rng.nextFloat() * batch.angle - (batch.angle * 0.5F);
            }
            case CIRCLE -> {
                direction = new Vec3d(0, 0, randomInRange(batch.min_speed, batch.max_speed))
                        .rotateY((float) Math.toRadians(rng.nextFloat() * 360F));
            }
            case LINE_VERTICAL, PILLAR, PIPE -> {
                direction = new Vec3d(0, randomInRange(batch.min_speed, batch.max_speed), 0);
            }
            case SPHERE -> {
                direction = new Vec3d(randomInRange(batch.min_speed, batch.max_speed), 0, 0)
                        .rotateZ((float) Math.toRadians(rng.nextFloat() * 360F))
                        .rotateY((float) Math.toRadians(rng.nextFloat() * 360F));
            }
        }
        if (batch.alignment == ParticleGroup.Alignment.LOOK) {
            // Find actual rotation
            float pRot = -pitch;
            float yRot = yaw * (-1F);

            direction = direction
                    .rotateX((float) Math.toRadians(pRot - 90 + rotateAroundX))
                    .rotateY((float) Math.toRadians(yRot + rotateAroundY));

            if (batch.roll_per_tick != 0) {
                var axis = VectorHelper.axisFromRotation(yRot, pRot).negate();
                var diff = ((time * batch.roll_per_tick) % 360) + batch.roll_offset;
                direction = VectorHelper.rotateAround(direction, axis, diff);
            }
        } else {
            direction = direction
                    .rotateX((float) Math.toRadians(rotateAroundX))
                    .rotateY((float) Math.toRadians(rotateAroundY));

            if (batch.roll_per_tick != 0) {
                var diff = ((time * batch.roll_per_tick) % 360) + batch.roll_offset;
                direction = direction.rotateY((float) Math.toRadians(diff));
            }
        }

        return direction;
    }

public static <T extends LivingEntity & IDecoratable> void renderCosmetic(GeoBone bone, PoseStack matrix, MultiBufferSource buffer, T entity, int packedLightIn) {
        ItemStack stack = entity.getCosmeticItem();
        if (!(stack.getItem() instanceof ICosmeticItem cosmetic)) return;
        //checks should have already been made, but pattern variables ftw
        matrix.pushPose();

        RenderUtil.translateToPivotPoint(matrix, bone);
        RenderUtil.rotateMatrixAroundBone(matrix, bone);
        RenderUtil.translateMatrixToBone(matrix, bone);
        Vec3 translations = cosmetic.getTranslations(entity);
        Vec3 scaling = cosmetic.getScaling(entity);
        matrix.translate(translations.x, translations.y, translations.z);
        matrix.scale((float) scaling.x, (float) scaling.y, (float) scaling.z);
        Minecraft.getInstance().getItemRenderer().renderStatic(stack, cosmetic.getTransformType(), packedLightIn, OverlayTexture.NO_OVERLAY, matrix, buffer, entity.level, (int) entity.getOnPos().asLong());

        matrix.popPose();
    }

public Vector3f toEmitterSpace(float x, float y, float z, float localX, float localY, float localZ) {
        float xRotRadians = (float) Math.toRadians(this.emitter.getAdjustedRotation().x);
        float yRotRadians = (float) Math.toRadians(this.emitter.getAdjustedRotation().y);
        Matrix4f transform = new Matrix4f();
        transform.identity()
                .translate(new Vector3f(x, y, z))
                .rotateY(yRotRadians)
                .rotateX(-xRotRadians);

        Vector3f localPos = new Vector3f(localX, localY, localZ);
        transform.transformPosition(localPos);
        return localPos;
    }

