public static void renderBubble(Entity entityIn, EntityRenderDispatcher entityRenderDispatcher, PoseStack matrixStack, MultiBufferSource buffer) {
        double y = entityIn.getPassengers().isEmpty() ? 0.25f : entityIn.getBbHeight();
        matrixStack.pushPose();
        matrixStack.translate(0, y, 0);
        matrixStack.mulPose(entityRenderDispatcher.cameraOrientation());

        matrixStack.scale(0.025F, -0.025F, 0.025F);
        float base = 2.0f;
        var passenger = entityIn.getFirstPassenger();
        if (passenger != null) {
            base += 1f;
            // Compare the size difference between the bubble hitbox and the passenger
            base *= passenger.getBbWidth() / entityIn.getBbWidth();
        }
        matrixStack.scale(base, base, base);
        final Matrix4f pose = matrixStack.last().pose();
        ResourceLocation texture = TEXTURE;

        if (entityIn instanceof BubbleEntity bubbleEntity && bubbleEntity.poppingTicks > 0) {
            int popTicks = bubbleEntity.poppingTicks;
            if (popTicks < 2) {
                texture = POP_1;
            } else if (popTicks < 3) {
                texture = POP_2;
            } else if (popTicks < 4) {
                texture = POP_3;
            } else if (popTicks < 5) {
                texture = POP_4;
            } else {
                texture = POP_5;
            }
        }
        VertexConsumer r = buffer.getBuffer(ShaderRegistry.worldEntityIcon(texture));
        r.addVertex(pose, -8, -8, 0).setUv(0, 0);
        r.addVertex(pose, -8, 8, 0).setUv(0, 1);
        r.addVertex(pose, 8, 8, 0).setUv(1, 1);
        r.addVertex(pose, 8, -8, 0).setUv(1, 0);

        matrixStack.popPose();
    }

@Override
    public void render(EntityChimeraProjectile entityIn, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        matrixStackIn.pushPose();
        matrixStackIn.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entityIn.yRotO, entityIn.yRot) - 90.0F));
        matrixStackIn.mulPose(Axis.ZP.rotationDegrees(Mth.lerp(partialTicks, entityIn.xRotO, entityIn.getXRot())));

        float f9 = (float) entityIn.shakeTime - partialTicks;
        if (f9 > 0.0F) {
            float f10 = -Mth.sin(f9 * 3.0F) * f9;
            matrixStackIn.mulPose(Axis.ZP.rotationDegrees(f10));
        }
        matrixStackIn.popPose();
        super.render(entityIn, entityYaw, partialTicks, matrixStackIn, bufferIn, packedLightIn);

    }

public void render(
            PoseStack poseStack,
            MultiBufferSource buffer,
            int packedLight,
            EntityDummy livingEntity,
            float limbSwing,
            float limbSwingAmount,
            float partialTicks,
            float ageInTicks,
            float netHeadYaw,
            float headPitch
    ) {
        Player player = livingEntity.level.getPlayerByUUID(livingEntity.getOwnerUUID());
        if (player == null) {
            return;
        }
        if (!livingEntity.isInvisible()) {
            PlayerSkin playerskin = livingEntity.getPlayerInfo().getSkin();
            if (playerskin.capeTexture() != null) {
                ItemStack itemstack = livingEntity.getItemBySlot(EquipmentSlot.CHEST);
                if (!itemstack.is(Items.ELYTRA)) {
                    poseStack.pushPose();
                    poseStack.translate(0.0F, 0.0F, 0.125F);
                    double d0 = Mth.lerp((double) partialTicks, livingEntity.xCloakO, livingEntity.xCloak) - Mth.lerp((double) partialTicks, livingEntity.xo, livingEntity.getX());
                    double d1 = Mth.lerp((double) partialTicks, livingEntity.yCloakO, livingEntity.yCloak) - Mth.lerp((double) partialTicks, livingEntity.yo, livingEntity.getY());
                    double d2 = Mth.lerp((double) partialTicks, livingEntity.zCloakO, livingEntity.zCloak) - Mth.lerp((double) partialTicks, livingEntity.zo, livingEntity.getZ());
                    float f = Mth.rotLerp(partialTicks, livingEntity.yBodyRotO, livingEntity.yBodyRot);
                    double d3 = (double) Mth.sin(f * (float) (Math.PI / 180.0));
                    double d4 = (double) (-Mth.cos(f * (float) (Math.PI / 180.0)));
                    float f1 = (float) d1 * 10.0F;
                    f1 = Mth.clamp(f1, -6.0F, 32.0F);
                    float f2 = (float) (d0 * d3 + d2 * d4) * 100.0F;
                    f2 = Mth.clamp(f2, 0.0F, 150.0F);
                    float f3 = (float) (d0 * d4 - d2 * d3) * 100.0F;
                    f3 = Mth.clamp(f3, -20.0F, 20.0F);
                    if (f2 < 0.0F) {
                        f2 = 0.0F;
                    }

                    float f4 = Mth.lerp(partialTicks, livingEntity.oBob, livingEntity.bob);
                    f1 += Mth.sin(Mth.lerp(partialTicks, livingEntity.walkDistO, livingEntity.walkDist) * 6.0F) * 32.0F * f4;
                    if (livingEntity.isCrouching()) {
                        f1 += 25.0F;
                    }

                    poseStack.mulPose(Axis.XP.rotationDegrees(6.0F + f2 / 2.0F + f1));
                    poseStack.mulPose(Axis.ZP.rotationDegrees(f3 / 2.0F));
                    poseStack.mulPose(Axis.YP.rotationDegrees(180.0F - f3 / 2.0F));
                    VertexConsumer vertexconsumer = buffer.getBuffer(RenderType.entitySolid(playerskin.capeTexture()));
                    this.getParentModel().renderCloak(poseStack, vertexconsumer, packedLight, OverlayTexture.NO_OVERLAY);
                    poseStack.popPose();
                }
            }
        }
    }

@Override
    protected void setupRotations(EntityDummy p_225621_1_, PoseStack p_225621_2_, float p_225621_3_, float p_225621_4_, float p_225621_5_, float pScale) {
        float f = p_225621_1_.getSwimAmount(p_225621_5_);
        if (p_225621_1_.isFallFlying()) {
            super.setupRotations(p_225621_1_, p_225621_2_, p_225621_3_, p_225621_4_, p_225621_5_, pScale);
            float f1 = (float) p_225621_1_.getFallFlyingTicks() + p_225621_5_;
            float f2 = Mth.clamp(f1 * f1 / 100.0F, 0.0F, 1.0F);
            if (!p_225621_1_.isAutoSpinAttack()) {
                p_225621_2_.mulPose(Axis.XP.rotationDegrees(f2 * (-90.0F - p_225621_1_.getXRot())));
            }

            Vec3 vector3d = p_225621_1_.getViewVector(p_225621_5_);
            Vec3 vector3d1 = p_225621_1_.getDeltaMovement();
            double d0 = vector3d1.horizontalDistanceSqr();
            double d1 = vector3d.horizontalDistanceSqr();
            if (d0 > 0.0D && d1 > 0.0D) {
                double d2 = (vector3d1.x * vector3d.x + vector3d1.z * vector3d.z) / Math.sqrt(d0 * d1);
                double d3 = vector3d1.x * vector3d.z - vector3d1.z * vector3d.x;
                p_225621_2_.mulPose(Axis.YP.rotation((float) (Math.signum(d3) * Math.acos(d2))));
            }
        } else if (f > 0.0F) {
            super.setupRotations(p_225621_1_, p_225621_2_, p_225621_3_, p_225621_4_, p_225621_5_, pScale);
            float f3 = p_225621_1_.isInWater() ? -90.0F - p_225621_1_.getXRot() : -90.0F;
            float f4 = Mth.lerp(f, 0.0F, f3);
            p_225621_2_.mulPose(Axis.XP.rotationDegrees(f4));
            if (p_225621_1_.isVisuallySwimming()) {
                p_225621_2_.translate(0.0D, -1.0D, 0.3F);
            }
        } else {
            super.setupRotations(p_225621_1_, p_225621_2_, p_225621_3_, p_225621_4_, p_225621_5_, pScale);
        }

    }

