public SwirlingParticle(ClientLevel level, double xCoord, double yCoord, double zCoord, double xd, double yd, double zd, SwirlingParticleOptions options) {
        super(level, xCoord, yCoord, zCoord, 0, 0, 0);


        this.options = options;
        this.v = options.up().cross(options.normal());
        this.u = options.normal().cross(v);

        this.x = xCoord;
        this.y = yCoord;
        this.z = zCoord;
        this.xd = xd;
        this.yd = yd;
        this.zd = zd;

        this.scale(this.random.nextFloat() * 1.75f + 1f);
        this.lifetime = 40 + (int) (Math.random() * 45);
        this.cycle = this.random.nextInt(360);

        this.height = options.heightWidthSpeed().x;
        this.width = options.heightWidthSpeed().y;
        this.speed = options.heightWidthSpeed().z;
        this.dHeight = options.deltaHeightWidthSpeed().x;
        this.dWidth = options.deltaHeightWidthSpeed().y;
        this.dSpeed = options.deltaHeightWidthSpeed().z;
        ParticleOptions particleOptions = options.particleOptions();

        this.particle = Minecraft.getInstance().particleEngine.createParticle(particleOptions, xCoord, yCoord, zCoord, 0, 0, 0);
        if (particle != null) {
            Vec3 pos = calculatePos();
            particle.setPos(pos.x, pos.y, pos.z);
            // help with potential jitter
            ((ParticleAccessor) particle).irons_spellbooks$gravity(0);
            // trick basic particles into ceasing their movement
            ((ParticleAccessor) particle).irons_spellbooks$stoppedByCollision(true);
            this.tick();
        }

    }

@Override
    public void tick() {
        if (particle == null) {
            this.remove();
            return;
        }
        Vec3 oldpos = particle.getPos();
        if (!particle.isAlive()) {
            this.remove();
            return;
        }
        cycle = cycle + (float) speed;
        while (cycle >= 360) {
            cycle -= 360;
        }
        Vec3 pos = calculatePos();
        particle.setPos(pos.x, pos.y, pos.z);
        ((ParticleAccessor) particle).irons_spellbooks$xo(oldpos.x);
        ((ParticleAccessor) particle).irons_spellbooks$yo(oldpos.y);
        ((ParticleAccessor) particle).irons_spellbooks$zo(oldpos.z);
        height += dHeight;
        width += dWidth;
        speed += dSpeed;
        move(xd, yd, zd);
    }

@Override
    public void render(VertexConsumer buffer, Camera camera, float partialTick) {
        Vec3 vec3 = camera.getPosition();
        float f = (float) (Mth.lerp(partialTick, this.xo, this.x) - vec3.x());
        float f1 = (float) (Mth.lerp(partialTick, this.yo, this.y) - vec3.y());
        float f2 = (float) (Mth.lerp(partialTick, this.zo, this.z) - vec3.z());

        Vec3 ray = this.getPos().subtract(vec3).normalize();
        Vec3 forward = this.forward;
        Vec3 up = forward.cross(ray);


        Vector3f[] vertices = new Vector3f[]{new Vector3f(-1.0F, -1.0F, 0.0F), new Vector3f(-1.0F, 1.0F, 0.0F), new Vector3f(1.0F, 1.0F, 0.0F), new Vector3f(1.0F, -1.0F, 0.0F)};
        for (int i = 0; i < 4; i++) {
            float x = (float) (forward.x * vertices[i].x + up.x * vertices[i].y);
            float y = (float) (forward.y * vertices[i].x + up.y * vertices[i].y);
            float z = (float) (forward.z * vertices[i].x + up.z * vertices[i].y);
            vertices[i] = new Vector3f(x, y, z);
            vertices[i].mul(this.getQuadSize(partialTick));
            vertices[i].add(f, f1, f2);
        }
        int j = this.getLightColor(partialTick);
        this.makeCornerVertex(buffer, vertices[0], this.getU1(), this.getV1(), j);
        this.makeCornerVertex(buffer, vertices[1], this.getU1(), this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[2], this.getU0(), this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[3], this.getU0(), this.getV1(), j);
        //backface
        this.makeCornerVertex(buffer, vertices[3], this.getU0(), this.getV1(), j);
        this.makeCornerVertex(buffer, vertices[2], this.getU0(), this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[1], this.getU1(), this.getV0(), j);
        this.makeCornerVertex(buffer, vertices[0], this.getU1(), this.getV1(), j);

    }

@Override
    public void render(VertexConsumer consumer, Camera camera, float partialTick) {
        Vec3 vec3 = camera.getPosition();
        float f = (float) (Mth.lerp((double) partialTick, this.xo, this.x) - vec3.x());
        float f1 = (float) (Mth.lerp((double) partialTick, this.yo, this.y) - vec3.y());
        float f2 = (float) (Mth.lerp((double) partialTick, this.zo, this.z) - vec3.z());
        PoseStack poseStack = new PoseStack();
        poseStack.translate(f, f1, f2);
        float quadScale = this.getQuadSize(partialTick);
        poseStack.scale(quadScale, quadScale, quadScale);

        float chanceToBranch = 0.2f;
        setRGBA(1, 1, 1, 1);
        renderLightningPass(consumer, poseStack, partialTick, 0.06f, chanceToBranch);

        setRGBA(.25f, .7f, 1, .3f);
        renderLightningPass(consumer, poseStack, partialTick, 0.11f, chanceToBranch);

        setRGBA(.25f, .7f, 1, .15f);
        renderLightningPass(consumer, poseStack, partialTick, 0.25f, chanceToBranch);
    }

private void renderLightningPass(VertexConsumer consumer, PoseStack poseStack, float partialTick, float tubeWidth, float chanceToBranch) {
        RandomSource randomSource = RandomSource.create((age + lifetime) * 3456798L);
        Vec3 start = Vec3.ZERO;
        Vec3 end = destination.subtract(this.getPos()); // local space
        double distance = end.length();
        int segments = (int) (distance / 4 + randomSource.nextIntBetweenInclusive(1, 3));
        double distancePerSegment = distance / segments;
        Vec3 direction = end.normalize();
        for (int i = 0; i < segments; i++) {
            Vec3 wiggle = randomOffset(randomSource, .2f);
            Vec3 segmentEnd = start.add(direction.scale(distancePerSegment)).add(wiggle);

            drawLightningBeam(consumer, poseStack, partialTick, start, segmentEnd, tubeWidth, chanceToBranch, randomSource);

            start = segmentEnd;
//            end = end.subtract(wiggle).add(end);
        }
    }

private void drawTube(VertexConsumer consumer, PoseStack poseStack, float partialTick, Vec3 start, Vec3 end, float width) {
        Vec3 delta = end.subtract(start);
        float length = (float) delta.length();
        if (length <= 1e-6f) {
            return;
        }

        poseStack.pushPose();
        poseStack.translate(start.x, start.y, start.z);
        Vec2 rotation = Utils.rotationFromDirection(delta.normalize());
        poseStack.mulPose(Axis.YP.rotation(rotation.y));
        poseStack.mulPose(Axis.XP.rotation(-rotation.x));
        drawHull(Vec3.ZERO, new Vec3(0, 0, length), width, width, poseStack, consumer, partialTick);
        poseStack.popPose();
    }

private void drawQuad(Vec3 from, Vec3 to, float width, float height, PoseStack.Pose pose, VertexConsumer consumer, float partialTick) {
        Matrix4f poseMatrix = pose.pose();
        float halfWidth = width * .5f;
        float halfHeight = height * .5f;
        int light = getLightColor(partialTick);
        consumer.addVertex(poseMatrix, (float) from.x - halfWidth, (float) from.y - halfHeight, (float) from.z).setColor(this.rCol, this.gCol, this.bCol, this.alpha).setUv(getU1(), getV1()).setLight(light);
        consumer.addVertex(poseMatrix, (float) from.x + halfWidth, (float) from.y + halfHeight, (float) from.z).setColor(this.rCol, this.gCol, this.bCol, this.alpha).setUv(getU1(), getV0()).setLight(light);
        consumer.addVertex(poseMatrix, (float) to.x + halfWidth, (float) to.y + halfHeight, (float) to.z).setColor(this.rCol, this.gCol, this.bCol, this.alpha).setUv(getU0(), getV0()).setLight(light);
        consumer.addVertex(poseMatrix, (float) to.x - halfWidth, (float) to.y - halfHeight, (float) to.z).setColor(this.rCol, this.gCol, this.bCol, this.alpha).setUv(getU0(), getV1()).setLight(light);
    }

