        float bodyYaw = entity.yBodyRotO + (entity.yBodyRot - entity.yBodyRotO) * partialTicks;
        if (entity.isVehicle()) {
            Vec3 offset = new Vec3(0, 0.0F, 0F);
            Vec3 ridePos = getRiderPosition(offset);
            for (Entity passenger : entity.getPassengers()) {
