@Override
    public void extractRenderState(EntityBalloon balloon, BalloonRenderState state, float partialTick) {
        super.extractRenderState(balloon, state, partialTick);
        state.tint[0] = balloon.getColor().getPackedColor();
        BaseModelCache.BlockStateModelPartHelper model;
        LivingEntity latchedEntity = balloon.latchedEntity();
        if (latchedEntity != null) {
            //Shift the rendering of the balloon to be over the entity
            Vec3 latchedLerp = Mth.lerp(partialTick, latchedEntity.oldPosition(), latchedEntity.position());
            Vec3 balloonLerp = Mth.lerp(partialTick, balloon.oldPosition(), balloon.position());
            state.latchedAdjustment = latchedLerp.subtract(balloonLerp)
                  .add(0, balloon.getAddedHeight(latchedEntity), 0);
            model = AdditionsModelCache.INSTANCE.BALLOON;
        } else if (balloon.isLatchedToPos()) {
            model = AdditionsModelCache.INSTANCE.BALLOON;
        } else {
            model = AdditionsModelCache.INSTANCE.BALLOON_FREE;
        }
        state.model = model.getBakedModel();
    }

@Override
    public void extractRenderState(TileEntityBioGenerator generator, BioGeneratorRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(generator, state, partialTick, cameraPosition, breakProgress);
        FluidResource fluid = generator.bioFuelTank.resource();
        float fluidScale = generator.bioFuelTank.amountAsLong() / (float) generator.bioFuelTank.capacityAsLong(fluid);
        state.maxY = MODEL_MIN_Y_PAD + MODEL_Y_STAGE_FRACTION * getFluidStagePercent(fluidScale, MekanismUtils.lighterThanAirGas(fluid));
        switch (generator.getDirection()) {
            case NORTH -> {
                state.minX = MODEL_X_MIN_NORTH_SOUTH;
                state.maxX = MODEL_X_MAX_NORTH_SOUTH;
                state.minZ = MODEL_Z_MIN_NORTH;
                state.maxZ = MODEL_Z_MAX_NORTH;
            }
            case SOUTH -> {
                state.minX = MODEL_X_MIN_NORTH_SOUTH;
                state.maxX = MODEL_X_MAX_NORTH_SOUTH;
                state.minZ = MODEL_Z_MIN_SOUTH;
                state.maxZ = MODEL_Z_MIN_NORTH;
            }
            case WEST -> {
                state.minX = MODEL_Z_MIN_NORTH;
                state.maxX = MODEL_Z_MAX_NORTH;
                state.minZ = MODEL_Z_MIN_WEST;
                state.maxZ = MODEL_X_MAX_NORTH_SOUTH;
            }
            case EAST -> {
                state.minX = MODEL_Z_MIN_SOUTH;
                state.maxX = MODEL_Z_MIN_NORTH;
                state.minZ = MODEL_Z_MIN_EAST;
                state.maxZ = MODEL_X_MAX_NORTH_SOUTH;
            }
        }
        state.fluidTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(fluid, FluidTextureType.STILL));
        state.tint = MekanismRenderer.getColorARGB(fluid, fluidScale);
        state.lightCoords = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, fluid.getFluidType().getLightLevel());
        //noinspection MagicConstant
        state.renderCheck = (byte) (SideRender.FACE_UP | SideRender.of(generator.getDirection().getOpposite()));
    }

@Override
    public void extractRenderState(TileEntityFissionReactorCasing reactor, FissionReactorMultiblockData multiblock, FissionRenderState state, float partialTick,
          Vec3 cameraPosition, ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        state.calculateLightCoords(reactor.getLevel(), multiblock);
        float heatedCoolantScale = multiblock.prevHeatedCoolantScale;
        float coolantScale = multiblock.prevCoolantScale;
        if (multiblock.coolantTank.getCurrentType() == CurrentType.FLUID) {
            FluidResource coolant = multiblock.coolantTank.getFluidTank().resource();
            state.coolantTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(coolant, MekanismRenderer.FluidTextureType.STILL));
            boolean isGaseous = MekanismUtils.lighterThanAirGas(coolant);
            state.coolantGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, coolant.getFluidType().getLightLevel());
            state.coolantColor = MekanismRenderer.getColorARGB(coolant, coolantScale);
            state.coolantMaxY = ModelRenderer.getMaxY(state.height, coolantScale, isGaseous);
            state.valveTexture = MekanismRenderer.getValveTexture(coolant);
            for (Map.Entry<BlockPos, IValveHandler.ValveData> entry : multiblock.valves.entrySet()) {
                state.valves.add(ValveRenderData.get(entry.getValue(), entry.getKey(), state.coolantMaxY - 0.01F, state.renderLocation, state.height));
            }
        } else if (multiblock.coolantTank.getCurrentType() == CurrentType.CHEMICAL) {
            ChemicalResource coolant = multiblock.coolantTank.getChemicalTank().resource();
            state.coolantTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getChemicalTexture(coolant));
            boolean isGaseous = coolant.is(MekanismAPITags.Chemicals.GASEOUS);
            state.coolantGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, coolant.value().lightLevel());
            state.coolantColor = MekanismRenderer.getColorARGB(coolant, coolantScale);
            state.coolantMaxY = ModelRenderer.getMaxY(state.height, coolantScale, isGaseous);
        }
        if (!multiblock.heatedCoolantTank.isEmpty()) {
            ChemicalResource heatedCoolant = multiblock.heatedCoolantTank.resource();
            state.heatedCoolantTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getChemicalTexture(heatedCoolant));
            state.heatedCoolantMaxY = ModelRenderer.getMaxY(state.height, heatedCoolantScale, heatedCoolant.is(MekanismAPITags.Chemicals.GASEOUS));
            state.heatedCoolantColor = MekanismRenderer.getColorARGB(heatedCoolant, heatedCoolantScale);
            state.heatedCoolantGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, heatedCoolant.value().lightLevel());
        }

        if (multiblock.isBurning()) {
            //TODO - 26.3: Do we need to copy this like this?
            state.assemblies.addAll(multiblock.assemblies);
        }
    }

@Override
    public void submit(FissionRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        BlockPos pos = state.blockPos;
        if (!state.assemblies.isEmpty()) {
            for (FormedAssembly assembly : state.assemblies) {
                BlockPos assemblyPos = assembly.pos();
                poseStack.pushPose();
                poseStack.translate(assemblyPos.getX() - pos.getX(), assemblyPos.getY() - pos.getY(), assemblyPos.getZ() - pos.getZ());
                //Add a bit of extra distance so that it includes the lower part of the control rod
                poseStack.scale(1, assembly.height() + 0.625F, 1);
                RenderResizableCuboid.renderCube(RenderResizableCuboid.SideRender.HORIZONTAL, 0.05F, 0.01F, 0.05F, 0.95F, 0.99F, 0.95F,
                      poseStack, Sheets.translucentBlockItemSheet(), nodeCollector, GLOW_ARGB, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY,
                      RenderResizableCuboid.FaceDisplay.FRONT, camera.pos, Vec3.atLowerCornerOf(assemblyPos), MekanismRenderer.WHITE_ICON_GETTER);
                poseStack.popPose();
            }
        }
        if (state.coolantTexture != null) {
            RenderType renderType = Sheets.translucentBlockItemSheet();
            RenderResizableCuboid.renderObject(camera.pos, poseStack, renderType, nodeCollector, RenderResizableCuboid.SideRender.ALL_FACES,
                  0.01F, 0.01F, 0.01F, state.length - 0.02F, state.coolantMaxY, state.width - 0.02F, state.coolantTexture,
                  OverlayTexture.NO_OVERLAY, state.coolantGlow, state.coolantColor, state.blockPos, state.renderLocation, state.length, state.width);
            if (state.valveTexture != null) {
                RenderResizableCuboid.renderValves(camera.pos, poseStack, renderType, nodeCollector, state.valves, OverlayTexture.NO_OVERLAY, state.valveTexture,
                      state.blockPos, state.renderLocation, state.length, state.width, state.height, state.coolantColor, state.coolantGlow, state.coolantMaxY - 0.01F);
            }
        }
        if (state.heatedCoolantTexture != null) {
            //uses a slightly shrunken version of the model to prevent z-fighting
            RenderResizableCuboid.renderObject(camera.pos, poseStack, Sheets.translucentBlockItemSheet(), nodeCollector, RenderResizableCuboid.SideRender.ALL_FACES,
                  0.02F, 0.02F, 0.02F, state.length - 0.03F, state.heatedCoolantMaxY, state.width - 0.03F, state.heatedCoolantTexture,
                  OverlayTexture.NO_OVERLAY, state.heatedCoolantGlow, state.heatedCoolantColor, state.blockPos, state.renderLocation, state.length, state.width);
        }
    }

@Override
    public void submit(FusionRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        poseStack.pushPose();
        poseStack.translate(0.5, -1.5, 0.5);
        float scale = 1 + 0.7F * sinDegrees(3.14F * state.scaledTemp + 135);
        renderPart(state, poseStack, nodeCollector, EnumColor.RED, scale, -6, -7, 0, 36);

        scale = 1 + 0.8F * sinDegrees(3 * state.scaledTemp);
        renderPart(state, poseStack, nodeCollector, EnumColor.PINK, scale, 4, 4, 0, 36);

        scale = 1 - 0.9F * sinDegrees(4 * state.scaledTemp + 90);
        renderPart(state, poseStack, nodeCollector, EnumColor.ORANGE, scale, 5, -3, -35, 106);

        poseStack.popPose();
    }

private void renderPart(FusionRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, EnumColor color, float scale, int mult1, int mult2,
          int shift1, int shift2) {
        poseStack.pushPose();
        poseStack.scale(scale, scale, scale);
        poseStack.rotateDegrees(Axis.YP, state.animationTime * mult1 + shift1);
        poseStack.rotateDegrees(RenderEnergyCube.coreVec, state.animationTime * mult2 + shift2);
        nodeCollector.submitBlockModel(poseStack, Sheets.translucentBlockItemSheet(), MekanismModelCache.INSTANCE.ENERGY_CORE.getBakedModel(),
              new int[]{color.getPackedColor()}, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
        poseStack.popPose();
    }

@Override
    public void extractRenderState(TileEntityTurbineCasing turbine, TurbineMultiblockData multiblock, TurbineRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        state.height = multiblock.lowerVolume / ((state.length + 2) * (state.width + 2));
        Level level = turbine.getLevel();
        //Update the light coords based on the multiblock so that we can pass the proper value to the rotor
        state.calculateLightCoords(level, multiblock);
        if (RenderTurbineRotor.INSTANCE != null && multiblock.complex != null) {
            boolean tickingNormally = isTickingNormally(turbine);
            BlockPos.MutableBlockPos complexPos = multiblock.complex.mutable();
            while (true) {
                complexPos.move(Direction.DOWN);
                TileEntityTurbineRotor rotor = WorldUtils.getTileEntity(TileEntityTurbineRotor.class, level, complexPos);
                if (rotor == null) {
                    break;
                }
                if (rotor.getHousedBlades() > 0) {
                    if (tickingNormally) {
                        int baseIndex = rotor.getPosition() * 2;
                        float rotateSpeed = multiblock.clientRotation * RenderTurbineRotor.BASE_SPEED;
                        rotor.rotationLower += rotateSpeed / (baseIndex + 1);
                        rotor.rotationUpper += rotateSpeed / (baseIndex + 2);
                        rotor.rotationLower %= 360;
                        rotor.rotationUpper %= 360;
                    }

                    TurbineRotorRenderState rotorState = RenderTurbineRotor.INSTANCE.createRenderState();
                    RenderTurbineRotor.INSTANCE.extractRenderState(rotor, rotorState, partialTick, cameraPosition, null);
                    //Use the multiblock's light level
                    rotorState.lightCoords = state.lightCoords;
                    state.rotors.add(rotorState);
                }
            }
        }
        if (state.height > 0 && !multiblock.chemicalTank.isEmpty()) {
            ChemicalResource steam = multiblock.chemicalTank.resource();
            state.steamTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getChemicalTexture(steam));
            state.steamMaxY = ModelRenderer.getMaxY(state.height, multiblock.prevSteamScale, steam.is(MekanismAPITags.Chemicals.GASEOUS));
            state.steamColor = MekanismRenderer.getColorARGB(steam, multiblock.prevSteamScale);
            //We already calculated the multiblock's light coords, so update it the steam light coords here
            state.steamLightCoords = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, steam.value().lightLevel());
        }
    }

@Override
    public void submit(TurbineRotorRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        if (state.housedBlades == 0) {//No blades, nothing to render
            return;
        }

        //Bottom blade
        poseStack.pushPose();
        poseStack.translate(0.5, -1, 0.5);
        poseStack.rotateDegrees(Axis.YP, state.lowerBlade.rotation);
        submitCrumblingModel(nodeCollector, this.model, state.lowerBlade, poseStack, this.model.getRenderType(), state);
        poseStack.popPose();

        //Top blade
        if (state.housedBlades == 2) {
            poseStack.pushPose();
            poseStack.translate(0.5, -0.5, 0.5);
            poseStack.rotateDegrees(Axis.YP, state.upperBlade.rotation);
            submitCrumblingModel(nodeCollector, this.model, state.upperBlade, poseStack, this.model.getRenderType(), state);
            poseStack.popPose();
        }
    }

