@SubscribeEvent
    public static void registerRenderStateModifiers(RegisterRenderStateModifiersEvent event) {
        event.registerEntityModifier(new TypeToken<LivingEntityRenderer<? extends LivingEntity, LivingEntityRenderState, ?>>() {
        }, (entity, renderState) -> {
            if (renderState instanceof HumanoidRenderState state) {
                renderState.setRenderData(MekaSuitArmor.UUID_CONTEXT, entity.getUUID());
                if (state.headEquipment.getItem() instanceof ItemMekaSuitArmor) {
                    //Note: Hiding head also implicitly hides the hat model part as it is a child of head
                    state.overrideModelPartVisibility(PartNames.HEAD, false);
                    if (state instanceof AvatarRenderState avatarState) {
                        avatarState.showHat = false;
                        avatarState.showExtraEars = false;
                    }
                }
                Item chest = state.chestEquipment.getItem();
                if (chest instanceof ItemMekaSuitArmor) {
                    state.overrideModelPartVisibility(PartNames.BODY, false);
                    if (state instanceof ArmorStandRenderState armorStandState) {
                        armorStandState.showArms = false;
                        state.overrideModelPartVisibility(ArmorStandModel.RIGHT_BODY_STICK, false);
                        state.overrideModelPartVisibility(ArmorStandModel.LEFT_BODY_STICK, false);
                        state.overrideModelPartVisibility(ArmorStandModel.SHOULDER_STICK, false);
                    } else {
                        //Don't adjust arms for armor stands as we already use vanilla's way to define the arms shouldn't be shown
                        state.overrideModelPartVisibility(PartNames.LEFT_ARM, false);
                        state.overrideModelPartVisibility(PartNames.RIGHT_ARM, false);
                        if (state instanceof AvatarRenderState avatarState) {
                            avatarState.showCape = false;
                            avatarState.showJacket = false;
                            avatarState.showLeftSleeve = false;
                            avatarState.showRightSleeve = false;
                        }
                    }
                    if (IModuleHelper.INSTANCE.isEnabled(state.chestEquipment, MekanismModules.ELYTRA_UNIT)) {
                        float scale = 0;
                        //Note: In theory the entity is always "fall flying" for wing rendering given our conditions
                        // for it rendering, but we validate it just in case.
                        //If the entity is not dive-bombing the ground (at which point the wings will be folded)
                        if (state.isFallFlying && state.xRot < 45) {
                            // then we check if the entity is not pointing steeply into the sky
                            double deltaY = entity.getDeltaMovement().y;
                            // if it isn't or if the entity has a lot of movement
                            if (state.xRot > -45 || deltaY > 1) {
                                // then we fully expand the wings
                                scale = 1;
                            } else if (deltaY > 0) {
                                // otherwise, if the entity is pointing steeply into the sky, and we have a small amount
                                // of movement (y movement between zero and one) then we partially expand the wings
                                scale = (float) deltaY;
                            }
                            // if we don't have any upwards momentum, and we are pointing steeply into the sky then we just fold the wings
                        }
                        if (entity instanceof Player) {
                            //If the entity is a player, then transition the wings gradually to their target position
                            float yRot = scale * MekaSuitArmor.ModelPos.EXPANDED_WING_Y_ROT;
                            float targetYRot = Mth.lerp(0.01F, entity.getData(MekanismAttachmentTypes.MEKASUIT_WING_YROT), yRot);
                            entity.setData(MekanismAttachmentTypes.MEKASUIT_WING_YROT, targetYRot);
                            scale = targetYRot / MekaSuitArmor.ModelPos.EXPANDED_WING_Y_ROT;
                        }
                        state.setRenderData(MekaSuitArmor.WING_SCALE, scale);
                    }
                } else if (chest instanceof ItemJetpack || chest instanceof ItemScubaTank) {
                    ItemStackRenderState bodyItem = new ItemStackRenderState();
                    Minecraft.getInstance().getEntityRenderDispatcher().itemModelResolver.updateForLiving(bodyItem, state.chestEquipment, ItemDisplayContext.NONE, entity);
                    state.setRenderData(ChestArmor.CHEST_CONTEXT, bodyItem);
                    if (state instanceof AvatarRenderState avatarState) {
                        //Hide the player's cape if they have a thick armor piece on that would clip with it
                        //TODO - 26.3: Look into the translations that CapeLayer does if the chest equipment has the humanoid layer type
                        // I think we can probably just add a wing layer type to the equipment assets, but then have the list of layers for it be empty?
                        avatarState.showCape = false;
                    }
                }
                if (state.legsEquipment.getItem() instanceof ItemMekaSuitArmor) {
                    state.overrideModelPartVisibility(PartNames.LEFT_LEG, false);
                    state.overrideModelPartVisibility(PartNames.RIGHT_LEG, false);
                    if (state instanceof AvatarRenderState avatarState) {
                        avatarState.showLeftPants = false;
                        avatarState.showRightPants = false;
                    }
                }
            }
        });
    }

@SubscribeEvent
    public void onTick(ClientTickEvent.Pre event) {
        if (minecraft.level == null || minecraft.player == null) {
            return;
        }
        RegistryAccess registryAccess = minecraft.level.registryAccess();
        boolean tickingNormally = MekanismRenderer.isRunningNormally();
        HolidayManager.notify(minecraft.player);

        //Reboot player sounds if needed
        SoundHandler.restartSounds();

        if (tickingNormally) {
            ClientRadiation.tickClient(minecraft.player);
        }

        UUID playerUUID = minecraft.player.getUUID();
        // Update player's state for various items; this also automatically notifies server if something changed and
        // kicks off sounds as necessary
        ItemAccess jetpack = IJetpackItem.getActiveJetpack(minecraft.player);
        boolean jetpackInUse = isJetpackInUse(minecraft.player, jetpack);
        Mekanism.playerState.setJetpackState(playerUUID, jetpackInUse, true);
        Mekanism.playerState.setScubaMaskState(playerUUID, isScubaMaskOn(minecraft.player), true);
        Mekanism.playerState.setGravitationalModulationState(playerUUID, isGravitationalModulationOn(minecraft.player), true);

        if (tickingNormally) {
            //Note: If we aren't ticking normally we can skip adding the particles or checking if the time matches as we know the time hasn't changed
            for (Iterator<Entry<Player, TeleportData>> iter = portableTeleports.entrySet().iterator(); iter.hasNext(); ) {
                Entry<Player, TeleportData> entry = iter.next();
                Player player = entry.getKey();
                for (int i = 0; i < 100; i++) {
                    double x = player.getX() + rand.nextDouble() - 0.5D;
                    double y = player.getY() + rand.nextDouble() * 2 - 2D;
                    double z = player.getZ() + rand.nextDouble() - 0.5D;
                    minecraft.level.addParticle(ParticleTypes.PORTAL, x, y, z, 0, 1, 0);
                }
                TeleportData data = entry.getValue();
                if (minecraft.level.getGameTime() == data.teleportTime) {
                    PacketUtils.sendToServer(new PacketPortableTeleporterTeleport(data.hand, data.identity));
                    iter.remove();
                }
            }
        }

        if (jetpack != null) {
            ItemResource primaryJetpack = IJetpackItem.getPrimaryJetpack(minecraft.player);
            if (!primaryJetpack.isEmpty()) {
                JetpackMode primaryMode = ((IJetpackItem) primaryJetpack.getItem()).getJetpackMode(primaryJetpack);
                JetpackMode mode = IJetpackItem.getPlayerJetpackMode(minecraft.player, primaryMode, p -> p.input.keyPresses.jump());
                MekanismClient.updateKey(minecraft.player.input.keyPresses.jump(), KeySync.ASCEND);
                try (Transaction simulation = Transaction.openRoot()) {
                    double jetpackThrust = ((IJetpackItem) jetpack.getResource().getItem()).useJetpackFuel(registryAccess, jetpack, primaryJetpack, simulation);
                    if (jetpackThrust > 0 && jetpackInUse && IJetpackItem.handleJetpackMotion(minecraft.player, mode, jetpackThrust, p -> p.input.keyPresses.jump())) {
                        minecraft.player.resetFallDistance();
                    }
                }
            }
        }

        if (isScubaMaskOn(minecraft.player) && minecraft.player.getAirSupply() == minecraft.player.getMaxAirSupply()) {
            for (MobEffectInstance effect : minecraft.player.getActiveEffects()) {
                if (MekanismUtils.shouldSpeedUpEffect(effect)) {
                    for (int i = 0; i < 9; i++) {
                        MekanismUtils.speedUpEffectSafely(minecraft.player, effect);
                    }
                }
            }
        }

        if (isVisionEnhancementOn(minecraft.player)) {
            visionEnhancement = true;
            // adds if it doesn't exist, otherwise tops off duration to 220. equal or less than 200 will make vision flickers
            minecraft.player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, 11 * SharedConstants.TICKS_PER_SECOND, 0, false, false, false));
        } else if (visionEnhancement) {
            visionEnhancement = false;
            MobEffectInstance effect = minecraft.player.getEffect(MobEffects.NIGHT_VISION);
            if (effect != null && effect.getDuration() <= 11 * SharedConstants.TICKS_PER_SECOND) {
                //Only remove it if it is our effect and not one that has a longer remaining duration
                minecraft.player.removeEffect(MobEffects.NIGHT_VISION);
            }
        }

        if (RadialConflictContext.INSTANCE.isActive()) {
            if (!MekKeyHandler.isRadialPressed() || (!updateSelectorRenderer(EquipmentSlot.MAINHAND) && !updateSelectorRenderer(EquipmentSlot.OFFHAND))) {
                if (minecraft.gui.screen() != null) {
                    //If we currently have a radial selector gui open but shouldn't close it
                    minecraft.gui.setScreen(null);
                }
            }
        }

        if (tickingNormally && MekanismConfig.client.enablePlayerSounds.get()) {
            RadiationScale scale = ClientRadiation.getClientScale();
            if (scale != RadiationScale.NONE && !SoundHandler.radiationSoundMap.containsKey(scale)) {
                GeigerSound sound = GeigerSound.create(minecraft.player, scale);
                SoundHandler.radiationSoundMap.put(scale, sound);
                SoundHandler.playSound(sound);
            }
        }
    }

@Override
    public ParticleGroupRenderState extractRenderState(Frustum frustum, Camera camera, float partialTickTime) {
        return new LaserParticleGroup.State(this.particles.stream()
              //Ensure the laser is in the view, otherwise we don't need to bother rendering it
              .filter(particle -> frustum.isVisible(particle.getBoundingBox()))
              .<LaserFeatureRenderer.Submit>mapMulti((particle, consumer) -> {
                  PoseStack poseStack = new PoseStack();
                  Vec3 shift = particle.getPos().subtract(camera.position());
                  poseStack.translate(shift.x, shift.y, shift.z);
                  poseStack.rotate(particle.direction().getRotation());

                  poseStack.rotate(Axis.YP, RADIAN_45);
                  consumer.accept(new LaserFeatureRenderer.Submit(poseStack, particle));

                  poseStack.pushPose();
                  poseStack.rotate(Axis.YP, Mth.HALF_PI);
                  consumer.accept(new LaserFeatureRenderer.Submit(poseStack, particle));
              }).toList()
        );
    }

@Override
    protected void renderToTexture(CompassPiP.State state, PoseStack poseStack, SubmitNodeCollector nodeCollector) {
        Font font = Minecraft.getInstance().font;
        int color = HUDColor.REGULAR.getColorARGB();
        poseStack.translate(50, 50, 0);

        poseStack.pushPose();
        poseStack.scale(0.7F, 0.7F, 0.7F);
        nodeCollector.submitText(poseStack, -font.width(state.coords()) / 2F, -4, state.coords(), false, Font.DisplayMode.NORMAL, LightCoordsUtil.FULL_BRIGHT,
              color, 0, EntityRenderState.NO_OUTLINE);
        poseStack.popPose();

        poseStack.rotate(Axis.XN, ONE_THIRD_PI);
        poseStack.rotate(Axis.ZP, state.angle());

        rotateStr(poseStack, nodeCollector, MekanismLang.NORTH_SHORT, state.angle(), 0, color);
        rotateStr(poseStack, nodeCollector, MekanismLang.EAST_SHORT, state.angle(), Mth.HALF_PI, color);
        rotateStr(poseStack, nodeCollector, MekanismLang.SOUTH_SHORT, state.angle(), Mth.PI, color);
        rotateStr(poseStack, nodeCollector, MekanismLang.WEST_SHORT, state.angle(), -Mth.HALF_PI, color);

        poseStack.translate(-50, -50, 0);
        nodeCollector.submitCustomGeometry(poseStack, MekanismRenderType.GUI_SPRITES, (pose, buffer) -> {
            TextureAtlasSprite sprite = Minecraft.getInstance().getAtlasManager().getAtlasOrThrow(AtlasIds.GUI).getSprite(COMPASS);
            int argb = HUDColor.REGULAR.getColorARGB();
            Matrix4f matrix = pose.pose();
            buffer.addVertex(matrix, 0, 0, 0).setUv(sprite.getU0(), sprite.getV0()).setColor(argb);
            buffer.addVertex(matrix, 0, 100, 0).setUv(sprite.getU0(), sprite.getV1()).setColor(argb);
            buffer.addVertex(matrix, 100, 100, 0).setUv(sprite.getU1(), sprite.getV1()).setColor(argb);
            buffer.addVertex(matrix, 100, 0, 0).setUv(sprite.getU1(), sprite.getV0()).setColor(argb);
        });
    }

@Nullable
    public static <RESULT, SLOT extends RVRecipeSlot, ITEM_UUID> RESULT transferRecipe(RVRecipeInfo<RESULT, SLOT, ITEM_UUID> recipeHelper, boolean execute) {
        if (recipeHelper.transferAmount() < 1) {
            //Short circuit if for some reason our caller is trying to transfer an invalid amount of items
            return recipeHelper.createInternalError();
        }
        QIOItemViewerContainer container = recipeHelper.container();
        byte selectedCraftingGrid = container.getSelectedCraftingGrid();
        if (selectedCraftingGrid == -1) {
            //Note: While the java docs recommend logging a message to the console when returning an internal error,
            // this isn't actually an error state here, and is just one where we want to make sure the plus button is hidden
            // as there are no crafting grids being shown
            return recipeHelper.createInternalError();
        }
        QIOCraftingWindow craftingWindow = container.getCraftingWindow(selectedCraftingGrid);
        //Note: This variable is only used for when doTransfer is false
        byte nonEmptyCraftingSlots = 0;
        if (!execute) {
            List<ItemStack> dummy = new ArrayList<>(QIOCraftingWindow.SLOTS_PER_WINDOW);
            for (int slot = 0; slot < QIOCraftingWindow.SLOTS_PER_WINDOW; slot++) {
                ItemResource inputStack = craftingWindow.getInputSlot(slot).resource();
                //Copy it in case any recipe does weird things and tries to mutate the stack
                dummy.add(inputStack.toStack());
                if (!inputStack.isEmpty()) {
                    //Count how many crafting slots are not empty
                    nonEmptyCraftingSlots++;
                }
            }
            if (recipeHelper.recipe().matches(CraftingInput.of(3, 3, dummy), recipeHelper.player().level())) {
                //If we are not transferring things, and the crafting window's contents already matches the given recipe,
                // then we can just early exit knowing that we have something that will work. If we are transferring items
                // then we need to actually do all the checks as we may be transferring more items if maxTransfer is true,
                // or we may be transferring different items if different ones are shown in JEI
                return null;
            }
        }
        //TODO: It may be nice to eventually implement some sort of caching for this, it isn't drastically needed because JEI is smart
        // and only calls it once per recipe to decide if it should display the button rather than say calling it every render tick in
        // case something changed and the render state should be different. We probably could add some sort of listeners to
        // inventory, QIO, and crafting window that if one changes it invalidates the cache of what ingredients are stored, though then
        // we wouldn't be able to directly modify the map as we find inputs, and also we still would have to do a lot of this comparison
        // logic, unless we can also somehow cache the recipe layout and how it interacts with the other information
        List<SLOT> slotViews = recipeHelper.inputs();
        int maxInputCount = slotViews.size();
        if (maxInputCount > QIOCraftingWindow.SLOTS_PER_WINDOW) {
            //I don't believe this ever will happen with a normal crafting recipe but just in case it does, error
            // if we have more than nine inputs, as there should never be
            // a case where this actually happens except potentially with some really obscure modded recipe
            Mekanism.logger.warn("Error evaluating recipe transfer handler for recipe: {}, had more than {} inputs: {}", recipeHelper.id(), QIOCraftingWindow.SLOTS_PER_WINDOW, maxInputCount);
            return recipeHelper.createInternalError();
        }
        int inputCount = 0;
        record TrackedIngredients<SLOT extends RVRecipeSlot>(SLOT view, Set<ItemResource> representations) {
        }
        //We will have at most the same number of ingredients as we have input slot views
        Byte2ObjectMap<TrackedIngredients<SLOT>> hashedIngredients = new Byte2ObjectArrayMap<>(maxInputCount);
        for (int index = 0; index < maxInputCount; index++) {
            SLOT slotView = slotViews.get(index);
            List<ItemStack> validIngredients = slotView.itemStacks();
            if (!validIngredients.isEmpty()) {
                //If there are valid ingredients, increment the count
                inputCount++;
                // and convert them to ItemResources
                // Note: we use a linked hash set to preserve the order of the ingredients as done in JEI
                LinkedHashSet<ItemResource> representations = new LinkedHashSet<>(validIngredients.size());
                //Note: We shouldn't need to convert the item that is part of the recipe to a "reduced" stack form based
                // on what the server would send, as the item should already be like that from when the server sent the
                // client the recipe. If this turns out to be incorrect due to how some mod does recipes, then we may need
                // to change this
                // Unchecked cast as we only requested views for item types
                ItemStack displayed = slotView.displayedIngredient();
                //Note: We use raw hashed items as none of this stuff should or will be modified while doing these checks,
                // so we may as well remove some unneeded copies
                if (!displayed.isEmpty()) {
                    //Start by adding the displayed ingredient if there is one to prioritize it
                    representations.add(ItemResource.of(displayed));
                }
                //Then add all valid ingredients in the order they appear in JEI. Because we are using a set
                // we will just end up merging with the displayed ingredient when we get to it as a valid ingredient
                for (ItemStack validIngredient : validIngredients) {
                    if (!validIngredient.isEmpty()) {//Shouldn't be empty but validate it just in case
                        representations.add(ItemResource.of(validIngredient));
                    }
                }
                hashedIngredients.put((byte) index, new TrackedIngredients<>(slotView, representations));
            }
        }
        //Get all our available items in the QIO frequency, we flatten the cache to stack together items that
        // as far as the client is concerned are the same instead of keeping them UUID separated, and add all
        // the items in the currently selected crafting window and the player's inventory to our available items
        QIOCraftingTransferHelper qioTransferHelper = container.getTransferHelper(recipeHelper.player(), craftingWindow);
        if (qioTransferHelper.isInvalid()) {
            Mekanism.logger.warn("Error initializing QIO transfer handler for crafting window: {}", selectedCraftingGrid);
            return recipeHelper.createInternalError();
        }
        //Note: We do this in a reversed manner (ItemResource -> slots, vs slot -> ItemResource) so that we can more easily
        // calculate the split for how we handle maxTransfer by quickly being able to see how many of each type we have
        Map<ItemResource, ByteList> matchedItems = new HashMap<>(inputCount);
        ByteSet missingSlots = new ByteArraySet(inputCount);
        for (ObjectIterator<Byte2ObjectMap.Entry<TrackedIngredients<SLOT>>> iterator = Byte2ObjectMaps.fastIterator(hashedIngredients); iterator.hasNext(); ) {
            Byte2ObjectMap.Entry<TrackedIngredients<SLOT>> entry = iterator.next();
            //TODO: Eventually we probably will want to add in some handling for if an item is valid for more than one slot and one combination
            // has it being valid and one combination it is not valid. For example if we have a single piece of stone and it is valid in either
            // slot 1 or 2 but slot 2 only allows for stone, and slot 1 can accept granite instead and we have granite available. When coming
            // up with a solution to this, we also will need to handle the slower comparison method, and make sure that if maxTransfer is true
            // then we pick the one that has the most elements we can assign to all slots evenly so that we can craft as many things as possible.
            // We currently don't bother with any handling related to this as JEI's own transfer handler it registers for things like the crafting
            // table don't currently handle this, though it is something that would be nice to handle and is something I believe vanilla's recipe
            // book transfer handler is able to do (RecipeItemHelper/ServerRecipePlayer)
            boolean matchFound = false;
            for (ItemResource validInput : entry.getValue().representations()) {
                ItemTypeSource source = qioTransferHelper.getSource(validInput);
                if (source != null && source.hasMoreRemaining()) {
                    //We found a match for this slot, reduce how much of the item we have as an input
                    source.matchFound();
                    // mark that we found a match
                    matchFound = true;
                    // and which ItemResource the slot's index corresponds to
                    matchedItems.computeIfAbsent(validInput, item -> new ByteArrayList()).add(entry.getByteKey());
                    // and stop checking the other possible inputs
                    break;
                }
            }
            if (!matchFound) {
                //If we didn't find a match for the slot, add it as a slot we may be missing
                missingSlots.add(entry.getByteKey());
            }
        }
        if (!missingSlots.isEmpty()) {
            //After doing the quicker exact match lookup checks, go through any potentially missing slots
            // and do the slower more "accurate" check of if the stacks match. This allows us to use JEI's
            // system for letting mods declare what things match when it comes down to NBT
            Map<ItemResource, ITEM_UUID> cachedIngredientUUIDs = new HashMap<>();
            for (Map.Entry<ItemResource, ItemTypeSource> entry : qioTransferHelper.reverseLookup.entrySet()) {
                ItemTypeSource source = entry.getValue();
                if (source.hasMoreRemaining()) {
                    //Only look at the source if we still have more items available in it
                    ItemResource storedITemType = entry.getKey();
                    Item storedItemType = storedITemType.getItem();
                    ITEM_UUID storedItemUUID = null;
                    for (ByteIterator missingIterator = missingSlots.iterator(); missingIterator.hasNext(); ) {
                        byte index = missingIterator.nextByte();
                        for (ItemResource validIngredient : hashedIngredients.get(index).representations()) {
                            //Compare the raw item types
                            if (storedItemType == validIngredient.getItem()) {
                                //If they match, compute the identifiers for both stacks as needed
                                if (storedItemUUID == null) {
                                    //If we haven't retrieved a UUID for the stored stack yet because none of our previous ingredients
                                    // matched the basic item type, retrieve it
                                    storedItemUUID = recipeHelper.itemUUID(storedITemType);
                                }
                                //Next compute the UUID for the ingredient we are missing if we haven't already calculated it
                                // either in a previous iteration or for a different slot
                                ITEM_UUID ingredientUUID = cachedIngredientUUIDs.computeIfAbsent(validIngredient, recipeHelper::itemUUID);
                                if (storedItemUUID.equals(ingredientUUID)) {
                                    //If the items are equivalent, reduce how much of the item we have as an input
                                    source.matchFound();
                                    // unmark that the slot is missing a match
                                    missingIterator.remove();
                                    // and mark which ItemResource the slot's index corresponds to
                                    matchedItems.computeIfAbsent(storedITemType, item -> new ByteArrayList()).add(index);
                                    // and stop checking the other possible inputs
                                    break;
                                }
                            }
                        }
                        if (!source.hasMoreRemaining()) {
                            //If we have "used up" all the input we have available then continue onto the next stored stack
                            break;
                        }
                    }
                    if (missingSlots.isEmpty()) {
                        //If we have accounted for all the slots, stop checking for matches
                        break;
                    }
                }
            }
            if (!missingSlots.isEmpty()) {
                //If we have any missing slots, report that they are missing to the user and don't allow transferring
                List<SLOT> missing = new ArrayList<>(missingSlots.size());
                for (byte slot : missingSlots) {
                    missing.add(hashedIngredients.get(slot).view());
                }
                return recipeHelper.createMissingSlotsError(missing);
            }
        }
        if (execute || (nonEmptyCraftingSlots > 0 && nonEmptyCraftingSlots >= qioTransferHelper.getEmptyInventorySlots())) {
            //Note: If all our crafting inventory slots are not empty, and we don't "obviously" have enough room due to empty slots,
            // then we need to calculate how much we can actually transfer and where it is coming from so that we are able to calculate
            // if we actually have enough room to shuffle the items around, even though otherwise we would only need to do these
            // calculations for when we are transferring items
            int toTransfer = recipeHelper.transferAmount();
            if (toTransfer > 1) {
                //Calculate how much we can actually transfer if we want to transfer as many full sets as possible
                for (Map.Entry<ItemResource, ByteList> entry : matchedItems.entrySet()) {
                    ItemResource itemType = entry.getKey();
                    ItemTypeSource source = qioTransferHelper.getSource(itemType);
                    if (source == null) {
                        //If something went wrong, and we don't actually have the item we think we do, error
                        return invalidSource(recipeHelper, itemType);
                    }
                    int maxStack = itemType.getMaxStackSize();
                    //If we have something that only stacks to one, such as a bucket. Don't limit the max stack size
                    // of other items to one
                    int max = maxStack == 1 ? toTransfer : Math.min(toTransfer, maxStack);
                    //Note: This will always be at least one as the int list should not be able to become
                    // larger than the number of items we have available
                    toTransfer = Math.min(max, Ints.saturatedCast(source.getAvailable() / entry.getValue().size()));
                    if (toTransfer == 1) {
                        //Short circuit checking the other ones if we get down to a single stack
                        break;
                    }
                }
            }
            QIOFrequency frequency = container.getFrequency();
            Byte2ObjectMap<List<SingularItemTypeSource>> sources = new Byte2ObjectArrayMap<>(inputCount);
            Map<ItemTypeSource, List<List<SingularItemTypeSource>>> shuffleLookup = frequency == null ? Collections.emptyMap() : new HashMap<>(inputCount);
            for (Map.Entry<ItemResource, ByteList> entry : matchedItems.entrySet()) {
                ItemResource itemType = entry.getKey();
                ItemTypeSource source = qioTransferHelper.getSource(itemType);
                if (source == null) {
                    //If something went wrong, and we don't actually have the item we think we do, error
                    return invalidSource(recipeHelper, itemType);
                }
                //Cap the amount to transfer at the max tack size. This way we allow for transferring buckets
                // and other stuff with it. This only actually matters if the max stack size is one, due to
                // the logic done above when calculating how much to transfer, but we do this regardless here
                // as there is no reason not to and then if we decide to widen it up we only have to change one spot
                int transferAmount = Math.min(toTransfer, itemType.getMaxStackSize());
                for (byte slot : entry.getValue()) {
                    //Try to use the item and figure out where it is coming from
                    List<SingularItemTypeSource> actualSources = source.use(transferAmount);
                    if (actualSources.isEmpty()) {
                        //If something went wrong, and we don't actually have enough of the item for some reason, error
                        return invalidSource(recipeHelper, itemType);
                    }
                    sources.put(slot, actualSources);
                    if (frequency != null) {
                        //The shuffle lookup only comes into play if we have a frequency so might end up having to check if there is room in it
                        int elements = entry.getValue().size();
                        if (elements == 1) {
                            shuffleLookup.put(source, Collections.singletonList(actualSources));
                        } else {
                            List<List<SingularItemTypeSource>> list = shuffleLookup.get(source);
                            //noinspection Java8MapApi - Capturing lambda
                            if (list == null) {
                                list = new ArrayList<>(elements);
                                shuffleLookup.put(source, list);
                            }
                            list.add(actualSources);
                        }
                    }
                }
            }
            if (!hasRoomToShuffle(qioTransferHelper, frequency, craftingWindow, container.getPlayerSlots(), container.getNumPlayerSlots(), shuffleLookup)) {
                return recipeHelper.createNoRoomError();
            }
            if (execute) {
                //Note: We skip doing a validation check on if the recipe matches or not, as there is a chance that for some recipes
                // things may not fully be accurate on the client side with the stacks that JEI lets us know match the recipe, as
                // they may require extra NBT that is server side only.
                //TODO: If the sources are all from the crafting window and are already in the correct spots, there is no need to send this packet
                PacketUtils.sendToServer(new PacketQIOFillCraftingWindow(recipeHelper.id(), toTransfer > 1, MekanismConfig.client.qioRejectsToInventory.get(), sources));
            }
        }
        return null;
    }

@Override
    public boolean render(BlockOutlineRenderState state, SubmitNodeCollector nodeCollector, PoseStack poseStack, LevelRenderState levelRenderState) {
        poseStack.pushPose();
        Vec3 viewPosition = levelRenderState.cameraRenderState.pos;
        poseStack.translate(pos.getX() - viewPosition.x, pos.getY() - viewPosition.y, pos.getZ() - viewPosition.z);

        //if top/bottom face, try to rotate so the bottom is as close to screen bottom as we can get
        if (face == Direction.UP || face == Direction.DOWN) {
            Direction cameraFacing = Direction.fromYRot(levelRenderState.cameraRenderState.yRot);
            if (cameraFacing != Direction.NORTH) {
                poseStack.rotateAround(V_ROT[cameraFacing.ordinal() - V_ROT_OFFSET], 0.5F, 1, 0.5F);
            }
        }

        if (isDiversion) {
            poseStack.scale(0.5F, 0.5F, 0.5F);
            poseStack.translate(0.5, 0.5, 0.5);
        }
        RenderPhaseKey<SubmitNode> phase = state.isTranslucent() ? RenderPhaseKeys.AFTER_TERRAIN : RenderPhaseKeys.SHAPE_OUTLINES;
        nodeCollector.submitSpecial(phase, new CustomFeatureRenderer.Submit(poseStack.last().copy(), RenderTypes.eyes(sprite.atlasLocation()), this));
        poseStack.popPose();
        return !isDiversion;
    }

@Override
    public void render(Pose pose, VertexConsumer buffer) {
        Vector3f normal = pose.transformNormal(face.getUnitVec3f(), new Vector3f());
        Matrix4f matrix = pose.pose();
        //face draw code donated by XFactHD
        FaceInfo faceInfo = FaceInfo.fromFacing(face);
        for (int vertex = 0; vertex < 4; vertex++) {
            FaceInfo.VertexInfo vertInfo = faceInfo.getVertexInfo(vertex);
            float x = vertInfo.xFace().select(0, 0, 0, 1, 1, 1) + face.getStepX() * 0.01F;
            float y = vertInfo.yFace().select(0, 0, 0, 1, 1, 1) + face.getStepY() * 0.01F;
            float z = vertInfo.zFace().select(0, 0, 0, 1, 1, 1) + face.getStepZ() * 0.01F;
            float u = vertex < 2 ? 0 : 1;
            float v = vertex == 0 || vertex == 3 ? 0 : 1;
            buffer.addVertex(matrix, x, y, z)
                  .setColor(transmissionColor)
                  .setUv(sprite.getU(u), sprite.getV(v))
                  .setOverlay(OverlayTexture.NO_OVERLAY)
                  .setLight(LightCoordsUtil.FULL_BRIGHT)
                  .setNormal(normal.x, normal.y, normal.z);
        }
    }

public void renderHUD(Minecraft minecraft, Player player, GuiGraphicsExtractor guiGraphics, Font font, DeltaTracker delta, int screenWidth, int screenHeight,
          int maxTextHeight, boolean reverseHud) {
        update(minecraft.level, player);
        if (MekanismConfig.client.hudOpacity.get() < 0.05F) {
            return;
        }
        Matrix3x2fStack matrix = guiGraphics.pose();
        matrix.pushMatrix();
        float yawJitter = -absSqrt(player.yHeadRot - prevRotationYaw);
        float pitchJitter = -absSqrt(player.getXRot() - prevRotationPitch);
        matrix.translate(yawJitter, pitchJitter);
        int audibleSubtitlesWidth = MekanismConfig.client.hudAvoidSoundSubtitleOverlay.get() ? getAudibleSubtitlesWidth(minecraft, font) : 0;
        if (MekanismConfig.client.hudCompassEnabled.get()) {
            matrix.pushMatrix();
            //Reversed hud causes the compass to render on the right side of the screen
            int posX = reverseHud ? screenWidth - 125 - audibleSubtitlesWidth : 25;
            //Pin the compass above the bottom of the screen and also above the text hud that may render below it
            int posY = Math.min(screenHeight - 20, maxTextHeight) - 80;
            matrix.translate(posX - 125, posY - 125);
            guiGraphics.submitPictureInPictureRenderState(new CompassPiP.State(new Matrix3x2f(matrix), guiGraphics.peekScissorStack(),
                  MekanismLang.GENERIC_BLOCK_POS.translate(player.getBlockX(), player.getBlockY(), player.getBlockZ()),
                  Mth.PI - Mth.DEG_TO_RAD * player.getViewYRot(delta.getGameTimeDeltaPartialTick(true))
            ));
            matrix.popMatrix();
        }

        renderMekaSuitEnergyIcons(player, font, guiGraphics);
        renderMekaSuitModuleIcons(player, font, guiGraphics, screenWidth, screenHeight, reverseHud, audibleSubtitlesWidth);

        matrix.popMatrix();
    }

@SubscribeEvent
    public static void onStitch(TextureAtlasStitchedEvent event) {
        TextureAtlas atlas = event.getAtlas();
        if (atlas.location().equals(TextureAtlas.LOCATION_ITEMS)) {
            GUNPOWDER_SPRITE = atlas.getSprite(Identifier.withDefaultNamespace("item/gunpowder"));
        } else if (atlas.location().equals(TextureAtlas.LOCATION_BLOCKS)) {
            for (TransmissionType type : TransmissionType.VALUES) {
                overlays.put(type, atlas.getSprite(Mekanism.rl("block/overlay/" + type.getTransmission() + "_overlay")));
            }

            WHITE_ICON_GETTER = new SingleTexturePicker(atlas.getSprite(Mekanism.rl("block/overlay/overlay_white")));
            energyIcon = atlas.getSprite(ENERGY_ICON_LOCATION);
            REDSTONE_TORCH_OFF_SPRITE = atlas.getSprite(Identifier.withDefaultNamespace("block/redstone_torch_off"));
            REDSTONE_TORCH_SPRITE = atlas.getSprite(Identifier.withDefaultNamespace("block/redstone_torch"));
            teleporterPortal = new SingleTexturePicker(atlas.getSprite(Mekanism.rl("block/teleporter_portal")));

            //Note: These are called in post rather than pre to make sure the icons have properly been stitched/attached
            SINGLE_TEXTURE_PICKERS.clear();
            VALVE_FLUID_TEX_CACHE.clear();

            parseColorAtlas(Mekanism.rl("textures/colormap/primary.png"), EnumColor.VALUES);
            parseColorAtlas(Mekanism.rl("textures/colormap/tiers.png"), BaseTier.VALUES);
        } else if (atlas.location().equals(Sheets.GUI_SHEET)) {
            SpecialColors.GUI_OBJECTS.parse(Mekanism.rl("textures/colormap/gui_objects.png"));
            SpecialColors.GUI_TEXT.parse(Mekanism.rl("textures/colormap/gui_text.png"));
            GuiElementHolder.updateBackgroundColor(atlas);
        }
    }

public void calculateLightCoords(@Nullable Level level, MultiblockData multiblock, int emission) {
        if (emission == Level.MAX_BRIGHTNESS) {
            //If it is already fully emissive like lava, skip looking up the light coords of the level
            lightCoords = LightCoordsUtil.FULL_BRIGHT;
        } else if (level != null) {//Shouldn't really be null, but given the base impl for BlockEntityState supports checking if it is, just let it handle it
            BlockPos minPos = multiblock.getMinPos();
            BlockPos maxPos = multiblock.getMaxPos();
            //Note: We offset the min position and max position by one so that we are not counting the frame. That way we only take into account light that is affected
            // by things like structural glass. We know this is valid positioning wise, due to the sanity checks in MultiblockTileEntityRenderer#extractRenderState.
            // This also has the added benefit of allowing us to check fewer positions
            int lightLevel = LightLevelUtils.getMaxLightCoordsBounds(level, minPos.offset(1, 1, 1), maxPos.offset(-1, -1, -1));
            int blockLight = LightCoordsUtil.block(lightLevel);
            if (blockLight > 0 && blockLight < Level.MAX_BRIGHTNESS) {
                //Note: If there is a block light level, and it is not at max brightness, that means that we have block light making it into the multiblock
                // presumably through a block like structural glass. So we need to increase the block light by one so that we have the light level at the structural glass
                // instead of one inside it
                lightLevel = LightCoordsUtil.withBlock(lightLevel, blockLight + 1);
            }
            lightCoords = LightCoordsUtil.lightCoordsWithEmission(lightLevel, emission);
        }
    }

public static void renderCube(@SideRender.SideRenderFlags byte sidesToRender, float cubeMinX, float cubeMinY, float cubeMinZ, float cubeMaxX, float cubeMaxY, float cubeMaxZ,
          PoseStack matrix, RenderType renderType, OrderedSubmitNodeCollector nodeCollector, int light, int overlay, FaceDisplay faceDisplay, @Nullable Vec3 camPos,
          @Nullable Vec3 renderPos, int westColor, int eastColor, int downColor, int upColor, int northColor, int southColor, TexturePicker spriteFromDirection,
          boolean invertedBackNormals) {
        TextureAtlasSprite[] sprites = new TextureAtlasSprite[6];
        int axisToRender = 0;
        //TODO: Eventually try not rendering faces that are covered by things? At the very least for things like multiblocks
        // when one face is entirely casing and not glass
        if (renderPos != null && camPos != null && faceDisplay != FaceDisplay.BOTH) {
            //If we know the position this model is based around in the world, and we aren't displaying both faces
            // then calculate to see if we can skip rendering any faces due to the camera not facing them
            Vec3 minPos = renderPos.add(cubeMinX, cubeMinY, cubeMinZ);
            Vec3 maxPos = renderPos.add(cubeMaxX, cubeMaxY, cubeMaxZ);
            for (Direction direction : EnumUtils.DIRECTIONS) {
                if (!shouldRenderSide(sidesToRender, direction)) {
                    continue;
                }
                TextureAtlasSprite sprite = spriteFromDirection.apply(direction);
                if (sprite != null) {
                    Axis axis = direction.getAxis();
                    AxisDirection axisDirection = direction.getAxisDirection();
                    double planeLocation = switch (axisDirection) {
                        case POSITIVE -> axis.choose(maxPos.x, maxPos.y, maxPos.z);
                        case NEGATIVE -> axis.choose(minPos.x, minPos.y, minPos.z);
                    };
                    double cameraPosition = axis.choose(camPos.x, camPos.y, camPos.z);
                    //Check whether the camera's position is past the side that it can render on for the face
                    // that we want to be rendering
                    if (faceDisplay.front == (axisDirection == AxisDirection.POSITIVE)) {
                        if (cameraPosition >= planeLocation) {
                            sprites[direction.ordinal()] = sprite;
                            axisToRender |= 1 << axis.ordinal();
                        }
                    } else if (cameraPosition <= planeLocation) {
                        sprites[direction.ordinal()] = sprite;
                        axisToRender |= 1 << axis.ordinal();
                    }
                }
            }
        } else {
            for (Direction direction : EnumUtils.DIRECTIONS) {
                if (!shouldRenderSide(sidesToRender, direction)) {
                    continue;
                }
                TextureAtlasSprite sprite = spriteFromDirection.apply(direction);
                if (sprite != null) {
                    sprites[direction.ordinal()] = sprite;
                    axisToRender |= 1 << direction.getAxis().ordinal();
                }
            }
        }
        if (axisToRender == 0) {
            //Skip rendering if no sides are meant to be rendered
            return;
        }
        //TODO: Further attempt to fix z-fighting at larger distances if we make it not render the sides when it is in a solid block
        // that may improve performance some, but definitely would reduce/remove the majority of remaining z-fighting that is going on
        int xDelta = calculateDelta(cubeMinX, cubeMaxX);
        int yDelta = calculateDelta(cubeMinY, cubeMaxY);
        int zDelta = calculateDelta(cubeMinZ, cubeMaxZ);
        float[] xBounds = getBlockBounds(xDelta, cubeMinX, cubeMaxX);
        float[] yBounds = getBlockBounds(yDelta, cubeMinY, cubeMaxY);
        float[] zBounds = getBlockBounds(zDelta, cubeMinZ, cubeMaxZ);

        int finalAxisToRender = axisToRender;
        nodeCollector.submitCustomGeometry(matrix, renderType, (pose, buffer) -> {
            NormalData normalData;
            if (invertedBackNormals) {
                Vector3f normal = pose.transformNormal(Direction.UP.getUnitVec3f(), new Vector3f());
                normalData = new NormalData(faceDisplay.front ? normal : UNUSED, faceDisplay.back ? normal : UNUSED);
            } else {
                //TODO: Figure out why we have to use these instead of the ones per corresponding direction
                normalData = new NormalData(
                      faceDisplay.front ? pose.transformNormal(Direction.UP.getUnitVec3f(), new Vector3f()) : UNUSED,
                      faceDisplay.back ? pose.transformNormal(Direction.DOWN.getUnitVec3f(), new Vector3f()) : UNUSED
                );
            }
            if ((finalAxisToRender & X_AXIS_MASK) != 0) {
                renderSideXAxis(buffer, light, overlay, faceDisplay, xDelta, yDelta, zDelta, sprites, yBounds, zBounds, xBounds, pose.pose(), normalData, westColor, eastColor);
            }
            if ((finalAxisToRender & Y_AXIS_MASK) != 0) {
                renderSideYAxis(buffer, light, overlay, faceDisplay, xDelta, yDelta, zDelta, sprites, yBounds, zBounds, xBounds, pose.pose(), normalData, downColor, upColor);
            }
            if ((finalAxisToRender & Z_AXIS_MASK) != 0) {
                renderSideZAxis(buffer, light, overlay, faceDisplay, xDelta, yDelta, zDelta, sprites, yBounds, zBounds, xBounds, pose.pose(), normalData, northColor, southColor);
            }
        });
    }

@SubscribeEvent
    public void tickEnd(ClientTickEvent.Post event) {
        //Note: We check that the game mode is not null as if it is that means the world is unloading, and we don't actually want to be rendering
        // as our data may be out of date or invalid. For example configs could unload while it is still unloading
        Level world;
        //noinspection ConstantValue
        if (minecraft.player != null && (world = minecraft.player.level()) != null && minecraft.gameMode != null && MekanismRenderer.isRunningNormally()) {
            float partialTicks = MekanismRenderer.getPartialTick();
            for (Player p : world.players()) {
                //Traverse active jetpacks and do animations
                if (Mekanism.playerState.isJetpackOn(p)) {
                    doJetpackRender(p, world, partialTicks);
                }

                if (world.getGameTime() % 4 == 0) {
                    //Traverse active scuba masks and do animations
                    if (Mekanism.playerState.isScubaMaskOn(p)) {
                        if (p.isInWater()) {
                            doScubaRender(p, world);
                        }
                    }

                    //Traverse players and do animations for idle flamethrowers
                    if (!p.isSwinging()) {
                        if (p.isUsingItem()) {
                            InteractionHand usedHand = p.getUsedItemHand();
                            if (!(p.getItemInHand(usedHand).getItem() instanceof ItemFlamethrower)) {
                                //If we the used item isn't a flamethrower, grab the other hand's item for checks
                                // if it was an active flamethrower we just skip adding the idle particles
                                tryAddIdleFlamethrowerParticles(minecraft, p, usedHand == InteractionHand.MAIN_HAND ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND, partialTicks);
                            }
                        } else if (!tryAddIdleFlamethrowerParticles(minecraft, p, InteractionHand.MAIN_HAND, partialTicks)) {
                            //If the player isn't using an item, try to first add particles for a flamethrower in the main hand
                            // and then add particles for a flamethrower in the offhand if we failed
                            tryAddIdleFlamethrowerParticles(minecraft, p, InteractionHand.OFF_HAND, partialTicks);
                        }
                    }
                }
            }
        }
    }

private void doJetpackRender(Player p, Level world, float partialTicks) {
        Vec3 playerPos = p.getEyePosition();
        //TODO - 1.21: Figure out why this is incorrect for other clients when they are hovering
        Vec3 playerMotion = p.getDeltaMovement();
        float random = (world.getRandom().nextFloat() - 0.5F) * 0.1F;
        //This positioning code is somewhat cursed, but it seems to be mostly working and entity pose code seems cursed in general
        float xAngle;
        float yBodyRot = Mth.rotLerp(partialTicks, p.yBodyRotO, p.yBodyRot);
        float bodyYRot = -yBodyRot * Mth.DEG_TO_RAD;
        double sideZ = -0.54;
        double centerZ = -0.3;
        if (p.isCrouching()) {
            xAngle = 20 * Mth.DEG_TO_RAD;
            playerPos = playerPos.add(0, 0.5, 0);
            centerZ = -0.9;
            sideZ = -0.8;
        } else {
            float swimAmount = p.getSwimAmount(partialTicks);
            if (p.isFallFlying()) {
                float fallFlyingTimeInTicks = p.getFallFlyingTicks() + partialTicks;
                //AvatarRenderSate#fallFlyingScale
                float fallFlyingScale = Math.clamp(fallFlyingTimeInTicks * fallFlyingTimeInTicks / 100.0F, 0.0F, 1.0F);
                if (!p.isAutoSpinAttack()) {
                    xAngle = fallFlyingScale * (-90.0F - p.getXRot()) * Mth.DEG_TO_RAD;
                } else {
                    xAngle = 0;
                }
            } else {
                float targetXRot = p.isInWater() ? -90.0F - p.getXRot() : -90.0F;
                xAngle = Mth.lerp(swimAmount, 0.0F, targetXRot) * Mth.DEG_TO_RAD;
            }
            Vec3 eyeAdjustments;
            if (p.isFallFlying() && (p != minecraft.player || !minecraft.options.getCameraType().isFirstPerson())) {
                eyeAdjustments = new Vec3(0, p.getEyeHeight(Pose.STANDING), 0).xRot(xAngle).yRot(bodyYRot).add(0, 0.5, 0);
            } else {
                eyeAdjustments = new Vec3(0, p.getEyeHeight(), 0).xRot(xAngle).yRot(bodyYRot);
                if (p.isVisuallySwimming()) {
                    eyeAdjustments = eyeAdjustments.add(0, 0.5, 0);
                }
                centerZ = -0.2;
            }
            playerPos = p.position().add(eyeAdjustments);
        }
        Vec3 vLeft = new Vec3(-0.43, -0.55, sideZ).xRot(xAngle).yRot(bodyYRot);
        renderJetpackSmoke(world, playerPos.add(vLeft).add(playerMotion), vLeft.scale(0.2).add(playerMotion).add(vLeft.scale(random)));
        Vec3 vRight = new Vec3(0.43, -0.55, sideZ).xRot(xAngle).yRot(bodyYRot);
        renderJetpackSmoke(world, playerPos.add(vRight).add(playerMotion), vRight.scale(0.2).add(playerMotion).add(vRight.scale(random)));
        Vec3 vCenter = new Vec3((world.getRandom().nextFloat() - 0.5) * 0.4, -0.86, centerZ).xRot(xAngle).yRot(bodyYRot);
        renderJetpackSmoke(world, playerPos.add(vCenter).add(playerMotion), vCenter.scale(0.2).add(playerMotion));
    }

