                        case LOW -> MekanismRenderer.REDSTONE_TORCH_OFF_SPRITE;
                    };
                    if (sprite != null) {
                        event.addCustomRenderer(new ConfiguratorOverlayHandler(pos, sprite, face));
                    }
                }
