                                int transmissionColor = MekanismRenderer.getColorARGB(configInfo.getDataType(side).getColor(), 0.6F);
                                event.addCustomRenderer(new ConfiguratorOverlayHandler(pos, type, face, transmissionColor));
                                showingConfiguratorOverlay = true;
                            }
                        }
                    }
                }
            }
            profiler.pop();
        }
        if (!showingConfiguratorOverlay) {
            //Only do normal outline rendering if we aren't displaying the configurator overlay
            Outlines.onBlockHover(event, profiler);
        }
    }

@Override
    public <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector collector, int lightCoords, STATE state,
          boolean isBaby, ItemStack stack) {
        ItemStackRenderState bodyItem = state.getRenderData(CHEST_CONTEXT);
        if (bodyItem != null) {
            poseStack.pushPose();
            baseModel.body.translateAndRotate(poseStack);
            if (isBaby) {
                poseStack.scale(state.ageScale, state.ageScale, state.ageScale);
                if (jetpack) {
                    poseStack.translate(0, -0.05, 0);
                }
            } else if (jetpack) {
                poseStack.translate(0, 0.3, 0);
            } else {
                poseStack.translate(0, 0.41, 0);
            }
            if (jetpack) {
                poseStack.translate(0, 0, 0.145);
                poseStack.scale(1.02F, -1.02F, -1.02F);
            } else {
                poseStack.translate(0, 0, 0.28);
                poseStack.scale(1, -1, -1);
            }
            bodyItem.submit(poseStack, collector, lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor);
            poseStack.popPose();
        }
    }

private void applyTransforms(PoseStack poseStack, ModelPart leg, boolean isBaby, HumanoidRenderState state, double xo) {
        leg.translateAndRotate(poseStack);
        if (isBaby) {
            poseStack.scale(state.ageScale, state.ageScale, state.ageScale);
            poseStack.translate(0, -0.2, 0);
        }
        poseStack.translate(xo, 1, 0.525);
        poseStack.scale(1.02F, -1.02F, -1.02F);
    }

public void renderArm(AvatarRenderState avatarRenderState, ModelPart armPart, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, boolean rightHand) {
        ModelPos armPos = rightHand ? ModelPos.RIGHT_ARM : ModelPos.LEFT_ARM;
        Map<ModelPos, PartData> armorQuads = cache.getUnchecked(key(avatarRenderState));
        PartData armData = armorQuads.get(armPos);
        if (armData != null) {
            poseStack.pushPose();
            armPart.translateAndRotate(poseStack);
            armPos.translateModel(poseStack);
            armData.render(poseStack, nodeCollector, lightCoords, avatarRenderState.outlineColor, getColor(avatarRenderState.chestEquipment), avatarRenderState.chestEquipment.hasFoil());
            poseStack.popPose();
        }
    }

@Override
    public <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords,
          STATE state, boolean isBaby, ItemStack stack) {
        Map<ModelPos, PartData> armorQuads = cache.getUnchecked(key(state));
        boolean renderFoil = stack.hasFoil();

        if (!armorQuads.isEmpty()) {
            int tintColor = getColor(stack);
            for (Map.Entry<ModelPos, PartData> entry : armorQuads.entrySet()) {
                ModelPos modelPos = entry.getKey();
                poseStack.pushPose();
                modelPos.translate(baseModel, poseStack, state);
                if (isBaby) {
                    modelPos.scaleBaby(poseStack, state);
                }
                modelPos.translateModel(poseStack);
                entry.getValue().render(poseStack, nodeCollector, lightCoords, state.outlineColor, tintColor, renderFoil);
                poseStack.popPose();
            }
        }


        if (type == EquipmentSlot.CHEST) {
            UUID entityUUID = state.getRenderData(UUID_CONTEXT);
            if (entityUUID != null) {
                long gameTime = Minecraft.getInstance().level == null ? 0L : Minecraft.getInstance().level.getGameTime();
                BoltRenderer boltRenderer = boltRenderMap.computeIfAbsent(entityUUID, _ -> new BoltRenderer());
                if (IModuleHelper.INSTANCE.isEnabled(state.chestEquipment, MekanismModules.GRAVITATIONAL_MODULATING_UNIT)) {
                    boltRenderer.update(0, LEFT_GRAV_BOLT, gameTime, state.partialTick);
                    boltRenderer.update(1, RIGHT_GRAV_BOLT, gameTime, state.partialTick);
                }
                List<BoltRenderState> boltRenderStates = boltRenderer.collectBoltStates(gameTime, state.partialTick);
                if (!boltRenderStates.isEmpty()) {
                    //Adjust the poseStack so that we render the lightning in the correct spot if the player is crouching
                    poseStack.pushPose();
                    ModelPos.BODY.translate(baseModel, poseStack, state);
                    PoseStack.Pose pose = poseStack.last().copy();
                    for (BoltRenderState boltState : boltRenderStates) {
                        nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, boltState));
                    }
                    poseStack.popPose();
                }
            }
        }
    }

private <STATE extends HumanoidRenderState> void translateWings(HumanoidModel<STATE> baseModel, PoseStack poseStack, STATE state) {
            baseModel.body.translateAndRotate(poseStack);
            float scale = state.getRenderDataOrDefault(WING_SCALE, 0F);
            // if we don't have any upwards momentum, and we are pointing steeply into the sky then we just fold the wings
            float x = EXPANDED_WING_X * scale;
            float y = EXPANDED_WING_Y * scale;
            float z = EXPANDED_WING_Z * scale;
            float yRot = EXPANDED_WING_Y_ROT * scale;
            float zRot = EXPANDED_WING_Z_ROT * scale;
            if (this == RIGHT_WING) {
                //Invert things that need to be inverted for the right wing to mirror it properly
                x = -x;
                yRot = -yRot;
                zRot = -zRot;
            }
            poseStack.translate(x / 16, y / 16, z / 16);
            if (yRot != 0.0F) {
                poseStack.rotateDegrees(Axis.YP, yRot);
            }
            if (zRot != 0.0F) {
                poseStack.rotateDegrees(Axis.ZP, zRot);
            }
        }

@Override
    public void submit(FlameRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        poseStack.pushPose();
        poseStack.rotateDegrees(Axis.YP, state.yRot - 90.0F);
        poseStack.rotateDegrees(Axis.ZP, state.xRot);

        poseStack.scale(state.scale, state.scale, state.scale);

        nodeCollector.submitModel(
              this.model,
              state,
              poseStack,
              model.renderType(TEXTURE),
              state.lightCoords,
              OverlayTexture.NO_OVERLAY,
              state.tintColor,
              null,
              state.outlineColor
        );
        poseStack.popPose();
        super.submit(state, poseStack, nodeCollector, camera);
    }

@Override
    public void submit(RobitRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        boolean isBodyVisible = this.isBodyVisible(state);
        boolean forceTransparent = !isBodyVisible && !state.isInvisibleToPlayer;
        //nb: this segment copied from super, bed & layer checks removed, invisibility check moved, and model submit replaced with submitRobitSkin()
        if (!forceTransparent) {
            poseStack.pushPose();
            {
                float scale = state.scale;
                poseStack.scale(scale, scale, scale);
                this.setupRotations(state, poseStack, state.bodyRot, scale);
                poseStack.scale(-1.0F, -1.0F, 1.0F);
                this.scale(state, poseStack);
                poseStack.translate(0.0F, -1.501F, 0.0F);
                //isBodyVisible & forceTransparent moved above
                submitRobitSkin(state, poseStack, nodeCollector);
            }
            poseStack.popPose();
        }
        //allow any layers/nametag/leash states to submit
        super.submit(state, poseStack, nodeCollector, camera);
    }

@Override
    public void render(GuiGraphicsExtractor graphics, DeltaTracker delta) {
        Minecraft minecraft = Minecraft.getInstance();
        Player player = minecraft.player;
        if (player != null && !player.isSpectator() && !minecraft.gui.hud.isHidden() && MekanismConfig.client.enableHUD.get()) {
            int count = 0;
            List<List<Component>> renderStrings = new ArrayList<>();
            for (EquipmentSlot slotType : EQUIPMENT_ORDER) {
                ItemStack stack = player.getItemBySlot(slotType);
                IItemHUDProvider hudProvider = getHudProvider(stack);
                if (hudProvider != null) {
                    //noinspection RedundantTypeArguments - Causes nullability warnings
                    count += this.<EquipmentSlot>makeComponent(hudProvider, player, stack, slotType, renderStrings, IItemHUDProvider::addHUDStrings);
                }
            }
            ResourceHandler<ItemResource> curiosInventory = Mekanism.hooks.getCuriosInventory(player);
            if (curiosInventory != null) {
                for (int i = 0, slots = curiosInventory.size(); i < slots; i++) {
                    ItemResource stack = curiosInventory.getResource(i);
                    IItemHUDProvider hudProvider = getHudProvider(stack);
                    if (hudProvider != null) {
                        count += makeComponent(hudProvider, player, stack.toStack(), null, renderStrings,
                              (provider, l, plyr, s, _) -> provider.addCurioHUDStrings(l, plyr, s));
                    }
                }
            }
            Font font = minecraft.font;

            boolean reverseHud = MekanismConfig.client.reverseHUD.get();
            int maxTextHeight = graphics.guiHeight();
            if (count > 0) {
                float hudScale = MekanismConfig.client.hudScale.get();
                int xScale = (int) (graphics.guiWidth() / hudScale);
                int yScale = (int) (graphics.guiHeight() / hudScale);
                int start = (renderStrings.size() * 2) + (count * 9);
                int y = yScale - start;
                maxTextHeight = (int) (y * hudScale);
                Matrix3x2fStack pose = graphics.pose();
                pose.pushMatrix();
                pose.scale(hudScale, hudScale);

                int backgroundColor = minecraft.options.getBackgroundColor(0.0F);
                if (backgroundColor != 0) {
                    //If we need to render the background behind it based on accessibility options
                    // calculate how big an area we need and draw it
                    int maxTextWidth = 0;
                    for (List<Component> group : renderStrings) {
                        for (Component text : group) {
                            int textWidth = font.width(text);
                            if (textWidth > maxTextWidth) {
                                maxTextWidth = textWidth;
                            }
                        }
                    }
                    int x = reverseHud ? xScale - maxTextWidth - 2 : 2;
                    GuiUtils.drawBackdrop(graphics, Minecraft.getInstance(), x, y, maxTextWidth, maxTextHeight, 1);
                }

                for (List<Component> group : renderStrings) {
                    for (Component text : group) {
                        int textWidth = font.width(text);
                        //Align text to right if hud is reversed, otherwise align to the left
                        //Note: that we always offset by 2 pixels from the edge of the screen regardless of how it is aligned
                        int x = reverseHud ? xScale - textWidth - 2 : 2;
                        graphics.text(font, text, x, y, 0xFFC8C8C8);
                        y += 9;
                    }
                    y += 2;
                }
                pose.popMatrix();
            }

            if (player.getItemBySlot(EquipmentSlot.HEAD).is(MekanismAPITags.Items.MEKASUIT_HUD_RENDERER)) {
                hudRenderer.renderHUD(minecraft, player, graphics, font, delta, graphics.guiWidth(), graphics.guiHeight(), maxTextHeight, reverseHud);
            }
        }
    }

@Override
    public void submit(@Nullable CubeState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, int overlayCoords, boolean hasFoil, int outlineColor) {
        if (state == null) {
            return;
        }
        if (hasFoil) {
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor, true);
        } else {
            //Use vanilla's normal rendering submit chain so that if something breaks when updating, we only have things break when using glint
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor);
        }
        if (state.coreTint != null) {
            float scaledTicks = 4 * state.ticks();
            poseStack.pushPose();
            poseStack.translate(0.5, 0.5, 0.5);
            poseStack.scale(0.4F, 0.4F, 0.4F);
            poseStack.translate(0, Math.sin(Math.toRadians(3 * state.ticks())) / 7, 0);
            poseStack.rotateDegrees(Axis.YP, scaledTicks);
            poseStack.rotateDegrees(RenderEnergyCube.coreVec, 36F + scaledTicks);
            nodeCollector.submitBlockModel(poseStack, Sheets.translucentBlockItemSheet(), MekanismModelCache.INSTANCE.ENERGY_CORE.getBakedModel(),
              new int[]{state.coreTint}, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
            poseStack.popPose();
        }
    }

