private void render(PoseStack.Pose pose, VertexConsumer buffer, BillboardingRenderState state) {
        int tick = state.renderTick % (state.gridSize * state.gridSize);
        int xIndex = tick % state.gridSize;
        int yIndex = tick / state.gridSize;
        float spriteSize = 1F / state.gridSize;

        float u0 = xIndex * spriteSize;
        float u1 = u0 + spriteSize;
        float v0 = yIndex * spriteSize;
        float v1 = v0 + spriteSize;

        buffer.addVertex(pose, 1.0F, -1.0F, 0.0F).setUv(u0, v1).setColor(state.color);
        buffer.addVertex(pose, 1.0F, 1.0F, 0.0F).setUv(u1, v1).setColor(state.color);
        buffer.addVertex(pose, -1.0F, 1.0F, 0.0F).setUv(u1, v0).setColor(state.color);
        buffer.addVertex(pose, -1.0F, -1.0F, 0.0F).setUv(u0, v0).setColor(state.color);
    }

@Override
    protected void buildGroup(FeatureFrameContext context, List<BoltFeatureRenderer.Submit> submits) {
        VertexConsumer builder = getVertexBuilder(RenderTypes.lightning());
        for (BoltFeatureRenderer.Submit submit : submits) {
            for (Vector3fc vertex : submit.state.vertices) {
                builder.addVertex(submit.pose, vertex).setColor(submit.state.color);
            }
        }
    }

@Override
    public void prepareGroup(FeatureFrameContext context, List<LaserFeatureRenderer.Submit> submits, boolean strictlyOrdered) {
        if (!submits.isEmpty()) {
            StagedVertexBuffer stagedVertexBuffer = context.stagedVertexBuffer();
            StagedVertexBuffer.Draw layerDraw = stagedVertexBuffer.appendDraw(DefaultVertexFormat.PARTICLE, PrimitiveTopology.QUADS, null);
            for (LaserFeatureRenderer.Submit submit : submits) {
                VertexConsumer vertexBuilder = stagedVertexBuffer.getVertexBuilder(layerDraw);

                float uMin = submit.sprite.getU0();
                float uMax = submit.sprite.getU1();
                float vMin = submit.sprite.getV0();
                float vMax = submit.sprite.getV1();
                float energyScale = submit.energyScale;
                float halfLength = submit.halfLength;

                addVertex(vertexBuilder, submit.pose, energyScale, -halfLength, uMax, vMax);
                addVertex(vertexBuilder, submit.pose, energyScale, halfLength, uMax, vMin);
                addVertex(vertexBuilder, submit.pose, -energyScale, halfLength, uMin, vMin);
                addVertex(vertexBuilder, submit.pose, -energyScale, -halfLength, uMin, vMax);

                //TODO - 26.3: Why do we need to draw back faces? (Can we just change the rotation based on the camera? Ideally yes)
                //Draw back faces
                addVertex(vertexBuilder, submit.pose, energyScale, halfLength, uMax, vMin);
                addVertex(vertexBuilder, submit.pose, energyScale, -halfLength, uMax, vMax);
                addVertex(vertexBuilder, submit.pose, -energyScale, -halfLength, uMin, vMax);
                addVertex(vertexBuilder, submit.pose, -energyScale, halfLength, uMin, vMin);

                stagedVertexBuffer.requestIndexCount(layerDraw);
            }
            this.groups.add(new LaserFeatureRenderer.PreparedGroup(layerDraw, context.textureManager().getTexture(SingleQuadParticle.Layer.TRANSLUCENT.textureAtlasLocation())));
        }
    }

@Override
    protected void buildGroup(FeatureFrameContext context, List<MekanismOutlineFeatureRender.Submit> submits) {
        Vector3f normal = new Vector3f();
        for (MekanismOutlineFeatureRender.Submit submit : submits) {
            VertexConsumer outline = getVertexBuilder(submit.renderType());
            Pose pose = submit.pose();
            int lineColor = submit.color();
            float lineWidth = submit.lineWidth();
            for (Line line : submit.toDraw()) {
                normal.set(line.nX(), line.nY(), line.nZ());
                outline.addVertex(pose, line.x1(), line.y1(), line.z1()).setColor(lineColor).setNormal(pose, normal).setLineWidth(lineWidth);
                outline.addVertex(pose, line.x2(), line.y2(), line.z2()).setColor(lineColor).setNormal(pose, normal).setLineWidth(lineWidth);
            }
        }
    }

public static void onBlockHover(ExtractBlockOutlineRenderStateEvent event, ProfilerFiller profiler) {
        profiler.push(ProfilerConstants.MEKANISM_OUTLINE);
        ClientLevel level = event.getLevel();
        BlockPos pos = event.getBlockPos();
        BlockState blockState = event.getBlockState();
        if (!blockState.isAir() && level.getWorldBorder().isWithinBounds(pos)) {
            BlockPos actualPos = pos;
            BlockState actualState = blockState;
            if (blockState.is(MekanismBlocks.BOUNDING_BLOCK)) {
                BlockPos mainPos = BlockBounding.getMainBlockPos(level, pos);
                if (mainPos != null) {
                    actualPos = mainPos;
                    actualState = level.getBlockState(actualPos);
                }
            }
            AttributeCustomSelectionBox customSelectionBox = Attribute.get(actualState, AttributeCustomSelectionBox.class);
            if (customSelectionBox != null) {
                if (customSelectionBox.isJavaModel()) {
                    //If we use a TER to render the wire frame, grab the tile
                    BlockEntity tile = WorldUtils.getTileEntity(level, actualPos);
                    if (tile != null) {
                        BlockEntityRenderer<BlockEntity, ?> tileRenderer = Minecraft.getInstance().getBlockEntityRenderDispatcher().getRenderer(tile);
                        if (tileRenderer instanceof IWireFrameRenderer wireFrameRenderer && wireFrameRenderer.hasSelectionBox(actualState)) {
                            List<Line> outlinesFromModel = wireFrameRenderer.isCombined() ? getOutlinesFromModel(level, actualPos, actualState) : Collections.emptyList();
                            event.addCustomRenderer(new IWireframeRendererHandler(actualPos, outlinesFromModel, wireFrameRenderer, tile));
                        }
                    }
                } else {
                    //Otherwise, skip getting the tile and just grab the model
                    List<Line> outlinesFromModel = getOutlinesFromModel(level, actualPos, actualState);
                    event.addCustomRenderer(new MekanismOutlineRenderer(actualPos, outlinesFromModel));
                }
            }
        }
        profiler.pop();
    }

@Override
    public void extractRenderState(TileEntityBin bin, BinRenderState state, float partialTick, Vec3 cameraPosition, ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(bin, state, partialTick, cameraPosition, breakProgress);
        Level level = bin.getLevel();
        BinInventorySlot binSlot = bin.getBinSlot();
        if (level != null && (!binSlot.isEmpty() || binSlot.isLocked())) {
            state.facing = bin.getDirection();
            //position of the block covering the front side
            BlockPos coverPos = state.blockPos.relative(state.facing);
            //if the bin has an item stack and the face isn't covered by a solid side
            Optional<BlockState> blockState = WorldUtils.getBlockState(level, coverPos);
            if (blockState.isEmpty() || !blockState.get().canOcclude() || !blockState.get().isFaceSturdy(level, coverPos, state.facing.getOpposite())) {
                //Calculate lighting based on the light at the block the bin is facing, but using our own block state
                // similar to how BrushableBlockRenderer calculates the light coords
                state.lightCoords = LightCoordsUtil.getLightCoords(LightCoordsUtil.BrightnessGetter.DEFAULT, level, bin.getBlockState(), coverPos);
                //Copy from how the campfire renderer calculates the seed
                int seed = (int) state.blockPos.asLong();
                this.itemModelResolver.updateForTopItem(state.item, binSlot.getBinItemType().toStack(), ItemDisplayContext.GUI, level, null, seed);
                state.displayCount = bin.getTier().isCreative() ? MekanismLang.INFINITE.translate() : TextComponentUtil.build(binSlot.amountAsInt());
                if (binSlot.isLocked()) {
                    state.displayColor = EnumColor.AQUA.getPackedColor();
                }
            } else {
                //TODO - 26.3: Re-evaluate how we want to do this. This just makes it so that we don't actually submit any rendering,
                // but we should see if we can just put some of this stuff in the should render?
                state.facing = null;
            }
        }
    }

@Override
    public void submit(BinRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        if (state.facing != null) {
            poseStack.pushPose();
            switch (state.facing) {
                case NORTH -> {
                    poseStack.translate(0.71, 0.8, -0.0001);
                    poseStack.rotate(Axis.YP, Mth.PI);
                }
                case SOUTH -> poseStack.translate(0.29, 0.8, 1.0001);
                case WEST -> {
                    poseStack.translate(-0.0001, 0.8, 0.29);
                    poseStack.rotate(Axis.YN, Mth.HALF_PI);
                }
                case EAST -> {
                    poseStack.translate(1.0001, 0.8, 0.71);
                    poseStack.rotate(Axis.YP, Mth.HALF_PI);
                }
            }

            poseStack.scale(0.025F, 0.025F, 0.0001F);
            poseStack.translate(8, -8, 8);
            poseStack.scale(16, 16, 16);
            state.item.submit(poseStack, nodeCollector, state.lightCoords, OverlayTexture.NO_OVERLAY, 0);
            poseStack.popPose();
            if (state.displayCount != null) {
                poseStack.pushPose();
                poseStack.translate(0, -0.25, 0);
                switch (state.facing) {
                    case SOUTH -> {
                        poseStack.translate(0, 1, 0);
                        poseStack.rotate(Axis.XP, Mth.HALF_PI);
                    }
                    case NORTH -> {
                        poseStack.translate(1, 1, 1);
                        poseStack.rotate(Axis.YP, Mth.PI);
                        poseStack.rotate(Axis.XP, Mth.HALF_PI);
                    }
                    case EAST -> {
                        poseStack.translate(0, 1, 1);
                        poseStack.rotate(Axis.YP, Mth.HALF_PI);
                        poseStack.rotate(Axis.XP, Mth.HALF_PI);
                    }
                    case WEST -> {
                        poseStack.translate(1, 1, 0);
                        poseStack.rotate(Axis.YN, Mth.HALF_PI);
                        poseStack.rotate(Axis.XP, Mth.HALF_PI);
                    }
                }

                float displayWidth = 1;
                float displayHeight = 1;
                poseStack.translate(displayWidth / 2, 1, displayHeight / 2);
                poseStack.rotate(Axis.XN, Mth.HALF_PI);

                int requiredWidth = Math.max(font.width(state.displayCount), 1);
                int requiredHeight = font.lineHeight + 2;
                float textScale = 0.4F * (displayWidth / requiredWidth);
                //clamp how much we are willing to scale to ensure it remains readable
                textScale = Math.min(textScale, 0.02F);

                poseStack.scale(textScale, -textScale, textScale);
                int realHeight = Mth.floor(displayHeight / textScale);
                int realWidth = Mth.floor(displayWidth / textScale);
                int offsetX = (realWidth - requiredWidth) / 2;
                int offsetY = (realHeight - requiredHeight) / 2;
                nodeCollector.submitText(
                      poseStack,
                      offsetX - realWidth / 2,
                      1 + offsetY - realHeight / 2,
                      state.displayCount.getVisualOrderText(),
                      false,
                      DisplayMode.POLYGON_OFFSET,
                      state.lightCoords,
                      state.displayColor,
                      0,
                      EntityRenderState.NO_OUTLINE
                );
                poseStack.popPose();
            }
        }
    }

@Override
    public void submit(DigitalMinerRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        poseStack.pushPose();
        //Adjust translation and scale ever so slightly so that no z-fighting happens at the edges if there are blocks there
        poseStack.translate(-state.radius + 0.01, state.minY - state.blockPos.getY() + 0.01, -state.radius + 0.01);
        float diameter = state.diameter - 0.02F;
        poseStack.scale(diameter, state.maxY - state.minY - 0.02F, diameter);
        Vec3 camPos = camera.pos;
        //If we are inside the visualization we don't have to render the "front" face, otherwise we need to render both given how the visualization works
        // we want to be able to see all faces easily
        FaceDisplay faceDisplay = RenderResizableCuboid.isInsideBounds(camPos,
              state.blockPos.getX() - state.radius, state.minY, state.blockPos.getZ() - state.radius,
              state.blockPos.getX() + state.radius + 1, state.maxY, state.blockPos.getZ() + state.radius + 1
        ) ? FaceDisplay.BACK : FaceDisplay.BOTH;
        RenderResizableCuboid.renderCube(RenderResizableCuboid.SideRender.ALL_FACES, 0, 0, 0, 1, 1, 1, poseStack,
              Sheets.translucentBlockItemSheet(), nodeCollector, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, faceDisplay, camPos, null,
              EAST_WEST_COLOR, EAST_WEST_COLOR, UP_DOWN_COLOR, UP_DOWN_COLOR, NORTH_SOUTH_COLOR, NORTH_SOUTH_COLOR, MekanismRenderer.WHITE_ICON_GETTER, true);
        poseStack.popPose();
    }

@Override
    public void submit(StabilizerRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        BlockPos pos = state.blockPos;
        for (RenderPiece piece : state.renderPieces) {
            int xChunkOffset = piece.x - TileEntityDimensionalStabilizer.MAX_LOAD_RADIUS;
            int zChunkOffset = piece.z - TileEntityDimensionalStabilizer.MAX_LOAD_RADIUS;
            ChunkPos startChunk = new ChunkPos(state.chunkX + xChunkOffset, state.chunkZ + zChunkOffset);
            ChunkPos endChunk = new ChunkPos(startChunk.x() + piece.xLength - 1, startChunk.z() + piece.zLength - 1);
            //Adjust translation and scale ever so slightly so that no z-fighting happens at the edges if there are blocks there
            double xShift = 0.01, zShift = 0.01;
            float xScaleShift = 0.02F, zScaleShift = 0.02F;
            if (piece.renderEast && piece.renderWest && !piece.renderNorth) {
                //North and maybe South walls missing
                zShift = -0.01;
                zScaleShift = piece.renderSouth ? 0 : -0.02F;
            } else if (piece.renderNorth && !piece.renderSouth) {
                //South and maybe East and/or West walls missing
                zScaleShift = 0;
            } else if (piece.renderNorth && piece.renderWest && !piece.renderEast) {
                //East wall missing
                xScaleShift = 0;
            } else if (piece.renderNorth && !piece.renderWest) {
                //West and maybe East walls missing
                xShift = -0.01;
                xScaleShift = piece.renderEast ? 0 : -0.02F;
            } else if (piece.renderSouth && piece.renderEast != piece.renderWest) {
                //North and either East or West walls missing
                zShift = -0.01;
                zScaleShift = 0;
            }
            //If we are inside the visualization we don't have to render the "front" face, otherwise we need to render both given how the visualization works
            // we want to be able to see all faces easily
            FaceDisplay faceDisplay = RenderResizableCuboid.isInsideBounds(camera.pos, startChunk.getMinBlockX(), Double.NEGATIVE_INFINITY, startChunk.getMinBlockZ(),
                  endChunk.getMaxBlockX() + 1, Double.POSITIVE_INFINITY, endChunk.getMaxBlockZ() + 1) ? FaceDisplay.BACK : FaceDisplay.BOTH;
            poseStack.pushPose();
            poseStack.translate(startChunk.getMinBlockX() - pos.getX() + xShift, state.minY - pos.getY(), startChunk.getMinBlockZ() - pos.getZ() + zShift);
            poseStack.scale(16 * piece.xLength - xScaleShift, state.height, 16 * piece.zLength - zScaleShift);

            RenderResizableCuboid.renderCube(piece.sidesToRender(), 0, 0, 0, 1, 1, 1, poseStack,
                  Sheets.translucentBlockItemSheet(), nodeCollector, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, faceDisplay, camera.pos, null,
                  EAST_WEST_COLOR, EAST_WEST_COLOR, 0, 0, NORTH_SOUTH_COLOR, NORTH_SOUTH_COLOR, MekanismRenderer.WHITE_ICON_GETTER, true);
            poseStack.popPose();
        }
    }

@Override
    public AABB getRenderBoundingBox(TileEntityDimensionalStabilizer tile) {
        Level level = tile.getLevel();
        if (tile.isClientRendering() && tile.canDisplayVisuals() && level != null) {
            int chunkX = SectionPos.blockToSectionCoord(tile.getBlockPos().getX());
            int chunkZ = SectionPos.blockToSectionCoord(tile.getBlockPos().getZ());
            ChunkPos minChunk = new ChunkPos(
                  chunkX - TileEntityDimensionalStabilizer.MAX_LOAD_RADIUS,
                  chunkZ - TileEntityDimensionalStabilizer.MAX_LOAD_RADIUS
            );
            ChunkPos maxChunk = new ChunkPos(
                  chunkX + TileEntityDimensionalStabilizer.MAX_LOAD_RADIUS,
                  chunkZ + TileEntityDimensionalStabilizer.MAX_LOAD_RADIUS
            );
            return new AABB(
                  minChunk.getMinBlockX(),
                  level.getMinY(),
                  minChunk.getMinBlockZ(),
                  maxChunk.getMaxBlockX() + 1,
                  level.getMaxY() + 1,
                  maxChunk.getMaxBlockZ() + 1
            );
        }
        return super.getRenderBoundingBox(tile);
    }

@Override
    public void extractRenderState(TileEntityDynamicTank tank, TankMultiblockData multiblock, DynamicTankRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        float scale = multiblock.prevScale;
        switch (multiblock.mergedTank.getCurrentType()) {
            case FLUID -> {
                FluidResource fluid = multiblock.getFluidTank().resource();
                state.calculateLightCoords(tank.getLevel(), multiblock, fluid.getFluidType().getLightLevel());
                state.tankTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(fluid, MekanismRenderer.FluidTextureType.STILL));
                state.tankColor = MekanismRenderer.getColorARGB(fluid, scale);
                state.tankMaxY = ModelRenderer.getMaxY(state.height, scale, MekanismUtils.lighterThanAirGas(fluid));
                state.valveTexture = MekanismRenderer.getValveTexture(fluid);
                for (Map.Entry<BlockPos, IValveHandler.ValveData> entry : multiblock.valves.entrySet()) {
                    state.valves.add(ValveRenderData.get(entry.getValue(), entry.getKey(), state.tankMaxY - 0.01F, state.renderLocation, state.height));
                }
            }
            case CHEMICAL -> {
                ChemicalResource chemical = multiblock.getChemicalTank().resource();
                state.calculateLightCoords(tank.getLevel(), multiblock, chemical.value().lightLevel());
                state.tankTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getChemicalTexture(chemical));
                state.tankColor = MekanismRenderer.getColorARGB(chemical, scale);
                state.tankMaxY = ModelRenderer.getMaxY(state.height, scale, chemical.is(MekanismAPITags.Chemicals.GASEOUS));
            }
        }
    }

