@Override
    public void extractRenderState(TileEntityNutritionalLiquifier liquifier, LiquifierRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(liquifier, state, partialTick, cameraPosition, breakProgress);
        if (!liquifier.fluidTank.isEmpty()) {
            FluidResource paste = liquifier.fluidTank.resource();
            float fluidScale = liquifier.fluidTank.amountAsLong() / (float) liquifier.fluidTank.capacityAsLong(paste);
            state.pasteTint = MekanismRenderer.getColorARGB(paste, fluidScale);
            state.stage = ModelRenderer.getStage(paste, stages, fluidScale);
            state.pasteTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(paste, FluidTextureType.STILL));
            state.pasteGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, paste.getFluidType().getLightLevel());
        } else {
            state.stage = 0;
        }
        state.active = liquifier.getActive();
        if (state.active) {
            float animationTime = getAnimationTime(liquifier, partialTick);
            state.bladeRotation = (animationTime * BLADE_SPEED) % 360;
            state.itemRotation = (animationTime * ROTATE_SPEED) % 360;
        }
        ItemStack stack = liquifier.getRenderStack();
        if (!stack.isEmpty()) {
            Level level = liquifier.getLevel();
            //Copy from how the campfire renderer calculates the seed
            int seed = (int) state.blockPos.asLong();
            this.itemModelResolver.updateForTopItem(state.item, stack, ItemDisplayContext.GROUND, level, null, seed);

            if (state.active && Minecraft.getInstance().options.particles().get() != ParticleStatus.MINIMAL) {
                //Render eating particles
                PseudoParticleData pseudoParticles = particles.computeIfAbsent(liquifier, _ -> new PseudoParticleData());
                if (isTickingNormally(liquifier)) {
                    //Don't add particles if the game is paused
                    long gameTime = liquifier.getGameTime();
                    if (pseudoParticles.lastTick != gameTime) {
                        pseudoParticles.lastTick = gameTime;
                        for (Iterator<BreakingItemParticle> iterator = pseudoParticles.particles.iterator(); iterator.hasNext(); ) {
                            BreakingItemParticle particle = iterator.next();
                            particle.tick();
                            if (!particle.isAlive()) {
                                iterator.remove();
                            }
                        }
                    }
                    int rate = Minecraft.getInstance().options.particles().get() == ParticleStatus.DECREASED ? 10 : 3;
                    if (gameTime % rate == 0) {
                        RandomSource random = level.getRandom();
                        Material.Baked itemSprite = state.item.pickParticleMaterial(random);
                        pseudoParticles.particles.add(new EatingParticle((ClientLevel) level, state.blockPos, itemSprite, state.lightCoords));
                    }
                }
                Camera camera = Minecraft.getInstance().gameRenderer.mainCamera();
                for (BreakingItemParticle particle : pseudoParticles.particles) {
                    particle.extract(state.particles, camera, partialTick);
                }
                state.partialTick = partialTick;
            } else {
                particles.remove(liquifier);
            }
        }
    }

@Override
    public void submit(LiquifierRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        if (state.stage > 0 && state.pasteTexture != null) {
            RenderResizableCuboid.renderCube(RenderResizableCuboid.SideRender.NOT_DOWN, 0.001F, 0.313F, 0.001F, 0.999F,
                  0.313F + 0.624F * (state.stage / (float) stages), 0.999F, poseStack, Sheets.translucentBlockItemSheet(), nodeCollector,
                  state.pasteTint, state.pasteGlow, OverlayTexture.NO_OVERLAY, RenderResizableCuboid.FaceDisplay.FRONT, camera.pos, Vec3.atLowerCornerOf(state.blockPos), state.pasteTexture);
        }
        if (state.active) {
            //Render the blade at the correct rotation if we are active
            poseStack.pushPose();
            poseStack.translate(0.5, 0.5, 0.5);
            poseStack.rotateDegrees(Axis.YP, state.bladeRotation);
            poseStack.translate(-0.5, -0.5, -0.5);
            submitBreakableBlockModel(nodeCollector, poseStack, Sheets.cutoutBlockItemSheet(), MekanismModelCache.INSTANCE.LIQUIFIER_BLADE.getBakedModel(), state);
            poseStack.popPose();
        }
        //Render the item and particle
        if (!state.item.isEmpty()) {
            poseStack.pushPose();
            poseStack.translate(0.5, 0.6, 0.5);
            if (state.active) {
                //Make the item rotate if the liquifier is active
                poseStack.rotateDegrees(Axis.YP, state.itemRotation);
            }
            state.item.submit(poseStack, nodeCollector, state.lightCoords, OverlayTexture.NO_OVERLAY, 0);
            poseStack.popPose();
            if (!state.particles.isEmpty()) {
                state.particles.submit(nodeCollector, camera);
            }
        }
    }

@Override
    public void extractRenderState(TileEntitySPSCasing sps, SPSMultiblockData multiblock, SPSRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        state.setProcessed(multiblock.lastProcessed);

        state.center = Vec3.atLowerCornerOf(multiblock.getMinPos())
              .add(Vec3.atLowerCornerOf(multiblock.getMaxPos()))
              .add(1, 1, 1)
              .scale(0.5);

        BlockPos pos = state.blockPos;
        BoltRenderer bolts = boltRendererMap.computeIfAbsent(multiblock.inventoryID, _ -> new BoltRenderer());

        int targetEffectCount = 0;
        long gameTime = sps.getGameTime();
        boolean tickingNormally = isTickingNormally(sps);
        if (tickingNormally) {
            Vector3fc renderCenter = new Vector3f((float) (state.center.x() - pos.getX()), (float) (state.center.y() - pos.getY()), (float) (state.center.z() - pos.getZ()));
            for (CoilData data : multiblock.coilData.coilMap.values()) {
                if (data.prevLevel > 0) {
                    bolts.update(data.coilPos.hashCode(), getBoltFromData(data, pos, renderCenter), gameTime, partialTick);
                }
            }
            if (multiblock.lastReceivedEnergy > 0) {
                if (random.nextDouble() < state.lerpEnergy(0.01F, 0.4F)) {
                    CuboidSide side = Util.getRandom(CuboidSide.VALUES, random);
                    Plane plane = Plane.getInnerCuboidPlane(multiblock.getBounds(), side);
                    Vector3fc endPos = plane.getRandomPoint(random).sub(pos.getX(), pos.getY(), pos.getZ());
                    BoltEffect bolt = new BoltEffect(BoltRenderInfo.ELECTRICITY, renderCenter, endPos, 15)
                          .size(0.01F * state.lerpEnergy(0.5F, 5))
                          .lifespan(8)
                          .spawn(SpawnFunction.NO_DELAY);
                    bolts.update(31 * side.hashCode() + endPos.hashCode(), bolt, gameTime, partialTick);
                }
                targetEffectCount = (int) state.lerpEnergy(10, 120);
            }
        }

        if (state.processed > 0) {
            state.coreState = new BillboardingRenderState();
            state.coreState.color = 0xF0FFFFFF;
            state.coreState.gridSize = 4;
            state.coreState.scale = state.lerpEnergy(0.1F, 4F);
            //TODO - 26.3: Re-evaluate this, ConduitBlockEntity#tickCount?
            state.coreState.renderTick =  (int) gameTime;
        }

        if (sps.orbitEffects.size() > targetEffectCount) {
            sps.orbitEffects.poll();
        } else if (sps.orbitEffects.size() < targetEffectCount && random.nextDouble() < 0.5) {
            sps.orbitEffects.add(new SPSOrbitEffect(multiblock, random));
        }
        for (SPSOrbitEffect effect : sps.orbitEffects) {
            BillboardingRenderState orbitState = new BillboardingRenderState();
            orbitState.color = SPSOrbitEffect.COLOR;
            orbitState.scale = effect.getScale();
            orbitState.renderTick = effect.getTick();
            effect.transformPos(orbitState.pos, partialTick);
            state.orbitEffects.add(orbitState);
        }
        state.boltRenderStates = bolts.collectBoltStates(gameTime, partialTick);
    }

@Override
    public void extractRenderState(TileEntityTeleporter teleporter, TeleporterRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(teleporter, state, partialTick, cameraPosition, breakProgress);
        state.tint = MekanismRenderer.getColorARGB(teleporter.getColor(), 0.75F);

        Direction direction = Objects.requireNonNullElse(teleporter.frameDirection(), Direction.UP);
        boolean rotated = teleporter.frameRotated();

        if (direction.getAxis().isHorizontal()) {
            state.renderAxis = RenderResizableCuboid.SideRender.Y_AXIS;
        } else if (rotated) {
            state.renderAxis = RenderResizableCuboid.SideRender.X_AXIS;
        } else {
            state.renderAxis = RenderResizableCuboid.SideRender.Z_AXIS;
        }

        int min = direction.getAxisDirection() == AxisDirection.POSITIVE ? 1 : -2;
        int max = direction.getAxisDirection() == AxisDirection.POSITIVE ? 3 : 0;

        setBounds(state, direction, rotated, min, max);
    }

@Override
    public void extractRenderState(TileEntityThermalEvaporationController controller, EvaporationMultiblockData multiblock, TEPRenderState state, float partialTick,
          Vec3 cameraPosition, ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        float scale = Math.min(1, multiblock.prevScale);
        FluidResource fluid = multiblock.inputTank.resource();
        state.calculateLightCoords(controller.getLevel(), multiblock, fluid.getFluidType().getLightLevel());
        state.fluidTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(fluid, MekanismRenderer.FluidTextureType.STILL));
        state.valveTexture = MekanismRenderer.getValveTexture(fluid);
        state.tankColor = MekanismRenderer.getColorARGB(fluid, scale);
        state.tankMaxY = ModelRenderer.getMaxY(state.height, scale, MekanismUtils.lighterThanAirGas(fluid));
        for (Map.Entry<BlockPos, IValveHandler.ValveData> entry : multiblock.valves.entrySet()) {
            state.valves.add(ValveRenderData.get(entry.getValue(), entry.getKey(), state.tankMaxY - 0.01F, state.renderLocation, state.height));
        }
    }

@Override
    public void extractRenderState(TileEntityBoilerCasing boiler, BoilerMultiblockData multiblock, BoilerRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        FluidResource water = multiblock.waterTank.resource();
        ChemicalResource steam = multiblock.steamTank.resource();
        if (water.isEmpty() && steam.isEmpty() || multiblock.upperRenderLocation == null) {
            //Should not be empty due to the checks for shouldRender
            return;
        }
        state.calculateLightCoords(boiler.getLevel(), multiblock);

        state.steamHeight = state.renderLocation.getY() + state.height - multiblock.upperRenderLocation.getY();
        state.height = multiblock.upperRenderLocation.getY() - 1 - state.renderLocation.getY();
        if (state.height > 0 && !water.isEmpty()) {
            state.waterTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(water, MekanismRenderer.FluidTextureType.STILL));
            state.valveTexture = MekanismRenderer.getValveTexture(water);
            state.waterGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, water.getFluidType().getLightLevel());
            state.waterColor = MekanismRenderer.getColorARGB(water, multiblock.prevWaterScale);
            state.waterMaxY = ModelRenderer.getMaxY(state.height, multiblock.prevWaterScale, MekanismUtils.lighterThanAirGas(water));
            state.valves.clear();
            if (multiblock.prevWaterScale > 0) {
                for (Map.Entry<BlockPos, IValveHandler.ValveData> entry : multiblock.valves.entrySet()) {
                    state.valves.add(ValveRenderData.get(entry.getValue(), entry.getKey(), state.waterMaxY - 0.01F, state.renderLocation, state.height));
                }
            }
        }
        if (state.steamHeight > 0 && !steam.isEmpty()) {
            state.upperRenderLocation = multiblock.upperRenderLocation.offset(1, 0, 1);
            state.steamTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getChemicalTexture(steam));
            state.steamGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, steam.value().lightLevel());
            state.steamColor = MekanismRenderer.getColorARGB(steam, multiblock.prevSteamScale);
            state.steamMaxY = ModelRenderer.getMaxY(state.steamHeight, multiblock.prevSteamScale, steam.is(MekanismAPITags.Chemicals.GASEOUS));
        }
    }

@Override
    public void submit(TransporterRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        //Note: We expect this to not actually render anything, but call it just in case for consistency
        super.submit(state, poseStack, nodeCollector, camera);
        if (!state.stacks.isEmpty()) {
            for (TransporterStackRenderState stackRenderState : state.stacks) {
                poseStack.pushPose();
                poseStack.translate(stackRenderState.stackPos().x(), stackRenderState.stackPos().y(), stackRenderState.stackPos().z());
                if (stackRenderState.color() != null) {
                    poseStack.pushPose();
                    poseStack.translate(-0.5F, -0.25F, -0.5F);
                    nodeCollector.submitBlockModel(poseStack, Sheets.cutoutBlockItemSheet(), MekanismModelCache.INSTANCE.TRANSPORTER_BOX.getBakedModel(),
                          new int[]{stackRenderState.color().getPackedColor()}, state.lightCoords, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
                    poseStack.popPose();
                }
                AABB bb = stackRenderState.item().getModelBoundingBox();
                double maxDimension = Math.max(bb.getXsize(), Math.max(bb.getYsize(), bb.getZsize()));
                //TODO: Do we want to scale up tiny models?
                if (maxDimension > 1) {
                    //Scale any overly large models down to a single unit
                    float scale = (float) (1 / maxDimension);
                    poseStack.scale(scale, scale, scale);
                    poseStack.translate(0, 0.25F, 0);
                }
                poseStack.translate(0, 0.25F, 0);
                poseStack.scale(0.25F, 0.25F, 0.25F);
                stackRenderState.item().submit(poseStack, nodeCollector, state.lightCoords, OverlayTexture.NO_OVERLAY, 0);
                poseStack.popPose();
            }
        }
    }

@Override
    public void extractRenderState(TileEntityMechanicalPipe pipe, PipeRenderState state, float partialTick, Vec3 cameraPosition, ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(pipe, state, partialTick, cameraPosition, breakProgress);
        MechanicalPipe transmitter = pipe.getTransmitter();
        //Note: We validated in shouldRender(Transmitter) that the pipe has a network, which is two lines above the call to this method
        FluidNetwork network = transmitter.getTransmitterNetworkNN();
        FluidResource fluidType = network.getLastType();
        if (fluidType.isEmpty()) {
            return;//Shouldn't be the case but validate it
        }
        TextureAtlasSprite texture = MekanismRenderer.getFluidTexture(fluidType, FluidTextureType.STILL);
        state.fluidTexture = MekanismRenderer.getSinglePicker(texture);
        state.fluidTint = MekanismRenderer.getColorARGB(fluidType, network.currentScale);
        state.modelTint = new int[]{state.fluidTint};

        int stage = Math.max(3, ModelRenderer.getStage(fluidType, STAGES, network.currentScale));
        state.stage = stage;
        state.lightCoords = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, fluidType.getFluidType().getLightLevel());

        ConnectionType[] connectionContents = new ConnectionType[EnumUtils.DIRECTIONS.length];
        boolean[] renderSides = new boolean[6];
        boolean hasHorizontalSide = false;
        int verticalSides = 0;
        for (Direction side : EnumUtils.DIRECTIONS) {
            ConnectionType connectionType = transmitter.getConnectionType(side);
            //If it is normal we need to render it manually so to have it be the correct dimensions instead of too narrow
            if (connectionType == ConnectionType.PUSH || connectionType == ConnectionType.PULL) {
                connectionContents[side.ordinal()] = connectionType;
            }
            renderSides[side.ordinal()] = connectionType != ConnectionType.NORMAL;
            if (connectionType != ConnectionType.NONE) {
                if (side.getAxis().isHorizontal()) {
                    hasHorizontalSide = true;
                } else {
                    verticalSides++;
                }
            }
        }
        state.contentsModel = TransmitterContentsManager.get().getBaked(connectionContents, texture.contents().name());
        //Render the base part if there is a horizontal connection, or we only have one vertical connection
        boolean renderBase = hasHorizontalSide || verticalSides < 2;
        state.renderBase = renderBase;
        @SideRender.SideRenderFlags byte coreSideRender = 0;
        for (Direction side : EnumUtils.DIRECTIONS) {
            //Render the side if there is no connection on that side, or it is a vertical connection, we have at least one side, and we are not full
            // We also render for push and pull as they use slightly smaller fill models which then means we would have
            // small gaps if we didn't render
            if (renderSides[side.ordinal()] || (renderBase && stage != STAGES - 1 && side.getAxis().isVertical())) {
                coreSideRender |= SideRender.of(side);
            }
        }
        state.coreSideRender = coreSideRender;
        Arrays.fill(state.renderSideModel, false);
        for (Direction side : EnumUtils.DIRECTIONS) {
            ConnectionType connectionType = transmitter.getConnectionType(side);
            if (connectionType == ConnectionType.NORMAL) {
                //If it is normal we need to render it manually so to have it be the correct dimensions instead of too narrow
                state.renderSideModel[side.ordinal()] = true;
            }
        }
    }

@Override
    public void extractRenderState(TileEntityPressurizedTube tube, TransmitterRenderState state, float partialTick, Vec3 cameraPosition, ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(tube, state, partialTick, cameraPosition, breakProgress);
        //Note: We validated in shouldRender(Transmitter) that the tube has a network, which is two lines above the call to this method
        ChemicalNetwork network = tube.getTransmitter().getTransmitterNetworkNN();
        ChemicalResource chemical = network.getLastType();
        float currentScale = Math.max(0.2F, network.currentScale);
        //TODO - 26.3: Figure out the tint better
        setContentsModel(tube, state, chemical.value().icon(), ARGB.color(currentScale, chemical.value().tint()));
        state.lightCoords = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, chemical.value().lightLevel());
    }
